class _MB:
    """測試時把 messagebox 換成印出來，避免原生對話框卡住 mainloop。"""

    def __getattr__(self, name):
        def f(*a, **k):
            print(f"[messagebox.{name}] {a[:2]}")
            return True if name.startswith("ask") else None
        return f


sv.messagebox = _MB()
