menus = []
menu_objs = []          # 和 menus 一一對應的 Menu 元件：測試可以用 invoke_menu() 真的按下某一項


def _fake_popup(self, x, y, entry=None):
    labels = []
    try:
        for i in range(self.index("end") + 1):
            if self.type(i) in ("command", "cascade", "checkbutton"):
                labels.append(self.entrycget(i, "label"))
    except Exception:
        pass
    menus.append(labels)
    menu_objs.append(self)


def invoke_menu(m, label: str) -> bool:
    """按下選單 m 裡標籤＝label 的那一項（走真的 command）；沒有這一項回 False。"""
    try:
        for i in range(m.index("end") + 1):
            if m.type(i) in ("command", "checkbutton") and m.entrycget(i, "label") == label:
                m.invoke(i)
                return True
    except Exception:
        pass
    return False


