# --- 測試資料 ---------------------------------------------------------------
fs = 64e6                      # 64 Msps、1 Msym/s → 64 samples / symbol
n = 6000
rng = np.random.default_rng(1)
bits = rng.integers(0, 2, n // 64 + 1) * 2 - 1
sym = np.repeat(bits, 64)[:n].astype(float)
g = np.exp(-np.linspace(-2, 2, 33) ** 2)
sym = np.convolve(sym, g / g.sum(), mode="same")
freq = 1.77778e6 + 250e3 * sym
phase = 2 * np.pi * np.cumsum(freq) / fs
adc_i = np.rint(512 + 300 * np.cos(phase) + rng.normal(0, 1.5, n))
adc_q = np.rint(512 + 300 * np.sin(phase) + rng.normal(0, 1.5, n))
spike_pos = [100, 777, 1500]
adc_i[spike_pos] = 0
with open(os.path.join(ROOT, "iq.csv"), "w", encoding="utf-8") as f:
    f.write("Time, adc i, adc q\n")
    for k in range(n):
        f.write(f"{k * 15.625:g} ns, {int(adc_i[k])}, {int(adc_q[k])}\n")
clk = np.tile([0, 0, 1, 1], 200)
data = clk.copy()
data[40:48] = 1 - data[40:48]
data[300:302] = 1 - data[300:302]
with open(os.path.join(ROOT, "digital", "clk.txt"), "w") as f:
    f.write("# clock\n" + "\n".join(map(str, clk)) + "\n")
with open(os.path.join(ROOT, "digital", "data.txt"), "w") as f:
    f.write("\n".join(map(str, data)) + "\n")
with open(os.path.join(ROOT, "hex", "samples.txt"), "w") as f:
    f.write("\n".join(f"{v:04X}" for v in (np.rint(2048 + 1000 * np.sin(np.arange(500) / 20))).astype(int)) + "\n")
with open(os.path.join(ROOT, "sub dir [1]", "weird name #2.txt"), "w") as f:
    f.write("\n".join(str(v) for v in range(0, 400, 3)) + "\n")
