@step
def s2_csv_dialog():
    path = os.path.join(ROOT, "iq.csv")
    table = sv.get_csv_table(path)
    dlg = sv.CsvImportDialog(app, path, table, None)
    app.update()
    check(set(dlg.rows) == {"adc i", "adc q"}, f"CSV 對話框欄位：{list(dlg.rows)}")
    r = dlg.rows["adc i"]
    check(r["ss"] and r["ds"] and r["suggest"] == -512, f"類比欄位預設勾選、建議平移 {r['suggest']}")
    dlg._use_estimate()
    check(dlg.v_fs.get().startswith("64M"), f"用估計值 fs={dlg.v_fs.get()}")
    dlg._use_suggest()
    check(dlg.v_shift.get() == "-512", f"用建議值 shift={dlg.v_shift.get()}")
    check("SPS = fs / symbol rate = 64" in dlg.v_sps_info.get(), f"SPS 提示：{dlg.v_sps_info.get()}")
    dlg.v_merge.set(True)
    dlg._on_add()
    app.update()
    check(dlg.result == ["adc i", "adc q"] and len(app.signals) == 2, f"加入 2 條訊號：{[s.key for s in app.signals]}")
    s = app.signals[0]
    check(s.sps == 64 and s.vshift == -512 and s.despike and s.panel == app.signals[1].panel,
          f"參數：sps={s.sps} shift={s.vshift} despike={s.despike} panel={s.panel}")
    # 同 key 再加入 → 更新不重複
    dlg2 = sv.CsvImportDialog(app, path, table, ["adc q"])
    dlg2.v_shift.set("-500")
    dlg2._on_add()
    check(len(app.signals) == 2 and app.find_signal("iq.csv;;adc q").vshift == -500, "同 key 再加入 → 更新、不重複")
    app.find_signal("iq.csv;;adc q").vshift = -512
    app.find_signal("iq.csv;;adc q").invalidate()
    app.refresh_list()
    app.plot()


