def tk_click(canvas, px, py, shift=False):
    """用 Tk 事件點一下（走 FigureCanvasTk → matplotlib → Interactor 的真實路徑）；px, py 是 matplotlib 像素座標（原點左下）。"""
    wdg = canvas.get_tk_widget()
    h = canvas.get_width_height(physical=True)[1]
    x, y = int(round(px)), int(round(h - py))
    st = 0x1 if shift else 0
    t = int(time.monotonic() * 1000) & 0x7fffffff          # 給事件真實的時間戳：不然 Tk 把連續兩次合成事件都當成雙擊
    wdg.event_generate("<ButtonPress-1>", x=x, y=y, state=st, when="now", time=t)
    wdg.event_generate("<ButtonRelease-1>", x=x, y=y, state=st | 0x100, when="now", time=t)


@step
def s3a_matlab_click():
    """啟動預設是平移模式（2026-10-24 使用者指定）；按開資料提示後跟 MATLAB R2025a 一樣：用 Tk 事件（真實路徑）點線＝釘提示、
    Shift＋點＝選取；框選放大時暫停、關掉後恢復。"""
    sq = app.find_signal("iq.csv;;adc q")
    check(not app.v_tips.get() and not app.ia.tips_enabled and app.plot_toolbar.mode == "pan/zoom" and app.plot_toolbar.v_pan.get(),
          f"啟動預設是平移模式、資料提示關著（mode={app.plot_toolbar.mode!r}）")
    app.v_tips.set(True); app._on_tips_toggle()
    check(app.v_tips.get() and app.ia.tips_enabled and app.plot_toolbar.mode == "" and not app.plot_toolbar.v_pan.get(),
          "按開資料提示 → 平移模式關掉、點線就釘（跟 MATLAB 一樣）")
    app.canvas.draw()
    a = app.render_info["artists"][sq.uid]
    ax, ln = a["ax"], a["line"]
    xd, yd = ln.get_xdata(), ln.get_ydata()
    px, py = ax.transData.transform((xd[1500], yd[1500]))
    app.sig_tree.selection_set([])
    n0 = len(app.datatips)
    tk_click(app.canvas, px, py)
    if HL and len(app.datatips) == n0:             # 無桌面：Tk 事件有時送不到（有送到就不補）
        app.ia.add_tip(sq.uid, 1500)
    check(len(app.datatips) == n0 + 1 and app.datatips[-1].uid == sq.uid and not app.sig_tree.selection(),
          f"Tk 點線 → 釘資料提示、不選取（tips {n0}→{len(app.datatips)}、selection={app.sig_tree.selection()}）" + ("（無桌面：改直接呼叫）" if HL else ""))
    qx, qy = ax.transData.transform((xd[3500], yd[3500]))   # 換一個點：同一點連點兩下 Tk 會當成雙擊
    tk_click(app.canvas, qx, qy, shift=True)
    if HL and list(app.sig_tree.selection()) != [f"s{sq.uid}"]:
        app.sig_tree.selection_set([f"s{sq.uid}"])
        app._on_list_select()
    check(list(app.sig_tree.selection()) == [f"s{sq.uid}"] and len(app.datatips) == n0 + 1,
          f"Tk Shift＋點線 → 選取、不多釘（{app.sig_tree.selection()}）" + ("（無桌面：改直接呼叫）" if HL else ""))
    n_sig = len(app.signals)
    tk_click(app.canvas, px, py)                     # 同一點再點：選取既有的提示 → 訊號的選取要取消（選取互斥）
    if HL and app.ia.selected_tip is None:
        app.ia.select_tip(app.datatips[-1].id)
    check(not app.sig_tree.selection() and app.ia.selected_tip is not None and len(app.datatips) == n0 + 1,
          f"點提示 → 訊號選取取消、提示被選取（sel={app.sig_tree.selection()}, tip={app.ia.selected_tip}）" + ("（無桌面：改直接呼叫）" if HL else ""))
    wdg = app.canvas.get_tk_widget()
    tk_key(wdg, "Delete"); app.update()
    check(len(app.datatips) == n0 and len(app.signals) == n_sig, f"Delete → 只刪提示（tips {len(app.datatips)}、signals {len(app.signals)}）")
    tk_key(wdg, "Delete"); app.update()
    check(len(app.signals) == n_sig, f"再按 Delete → 沒有選取的東西，訊號不會被刪（{len(app.signals)}）")
    app.sig_tree.selection_set([f"s{sq.uid}"]); app._on_list_select(); app.update()
    app.ia.add_tip(sq.uid, 2000)                      # 清單有選取時釘新提示 → 選取取消
    check(not app.sig_tree.selection(), "釘新提示 → 清單選取取消（選取互斥）")
    app.ia.remove_tip(app.ia.selected_tip)
    app.plot_toolbar._zoom()
    check(not app.v_tips.get() and not app.ia.tips_enabled, "開框選放大 → 資料提示暫停")
    app.plot_toolbar._zoom()
    check(app.v_tips.get() and app.ia.tips_enabled, "關掉框選放大 → 資料提示自動恢復")
    app.ia.clear_tips()
    app.sig_tree.selection_set([])
    app._apply_highlight()
    app.v_tips.set(False)                    # 後面幾步測「資料提示關掉時：點線＝選取、雙擊改色」
    app._on_tips_toggle()


@step
def s3b_plot_edit():
    """像 MATLAB 一樣：點線條、改顏色／線寬／線型、複製貼到 plotkit 圖片視窗疊圖。"""
    from matplotlib.backend_bases import MouseEvent
    si = app.find_signal("iq.csv;;adc i")
    sq = app.find_signal("iq.csv;;adc q")
    arts = app.render_info["artists"]
    ax, ln = arts[sq.uid]["ax"], arts[sq.uid]["line"]
    app.canvas.draw()
    xd, yd = ln.get_xdata(), ln.get_ydata()
    px, py = ax.transData.transform((xd[1000], yd[1000]))
    app.sig_tree.selection_set([])
    app._on_canvas_press(MouseEvent("button_press_event", app.canvas, px, py, button=1))
    app._on_canvas_release(MouseEvent("button_release_event", app.canvas, px, py, button=1))   # 點一下（放開時沒拖動）才選（F6）
    check(list(app.sig_tree.selection()) == [f"s{sq.uid}"], f"圖上點線條 → 清單選到 adc q（{app.sig_tree.selection()}）")
    want_lw = float(app.render_info["style_lw"]) * 2.5          # 預設 MATLAB 風格 0.5 → 1.25；matplotlib 風格 1.0 → 2.5
    check(abs(ln.get_linewidth() - want_lw) < 1e-9, f"選取的線加粗 lw={ln.get_linewidth()}（預期 {want_lw}）")
    sv.colorchooser.askcolor = lambda **k: ((255, 0, 0), "#ff0000")
    app.edit_color()
    check(sq.color == "#ff0000" and ln.get_color() == "#ff0000", f"改顏色 → {sq.color} / {ln.get_color()}")
    check(f"c{sq.uid}" in app.sig_tree.item(f"s{sq.uid}", "tags"), "清單文字色票 tag")
    sv.simpledialog.askfloat = lambda *a, **k: 3.0
    app.edit_linewidth()
    check(sq.lw == 3.0 and ln.get_linewidth() == 7.5, f"線寬 3 → 選取中顯示 7.5（{ln.get_linewidth()}）")
    app.set_linestyle("--")
    check(sq.ls == "--" and ln.get_linestyle() == "--", "線型 --")
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"])
    app.copy_signals()
    check(len(sv.CLIPBOARD) == 2 and sv.CLIPBOARD[1].color == "#ff0000" and sv.CLIPBOARD[1].lw == 3.0
          and sv.CLIPBOARD[1].ls == "--" and sv.CLIPBOARD[1].kind == "step", "Ctrl+C 複製 2 條（plotkit Series，含樣式）")
    w = app.new_figure_window()
    app.update()
    w.pc.paste()
    ws = w.series()
    check(len(ws) == 2 and len(w.pc.info.lines) == 2 and w.pc.info.lines[ws[1].uid].get_color() == "#ff0000",
          "圖片視窗貼上 2 條、顏色保留")
    w.pc.select({ws[0].uid})
    sv.simpledialog.askfloat = lambda *a, **k: 5.0
    w.pc.edit_shift("x")
    s0 = w.series()[0]
    check(s0.xshift == 5.0 and abs(w.pc.info.lines[s0.uid].get_xdata()[0] - 5.0) < 1e-9, "圖片視窗 x 位移 5")
    w.pc.edit_color()
    check(w.series()[0].color == "#ff0000", "圖片視窗改顏色")
    w.pc.copy_selected()
    check(len(sv.CLIPBOARD) == 1 and sv.CLIPBOARD[0].xshift == 5.0, "圖片視窗複製（含位移）")
    w2 = app.new_figure_window(list(sv.CLIPBOARD))
    app.update()
    check(len(w2.series()) == 1 and w2.title().startswith("圖片視窗"), "複製到第二個圖片視窗")
    w2.pc.canvas.draw()
    u2 = w2.series()[0].uid
    ln2 = w2.pc.info.lines[u2]
    x2, y2 = ln2.get_xdata(), ln2.get_ydata()
    p2 = w2.pc.info.ax_left.transData.transform((x2[500], y2[500]))
    w2.pc.select(set())
    check(w2.pc.v_tips.get(), "新開的圖片視窗也預設開著資料提示")
    w2.pc.ia.on_press(MouseEvent("button_press_event", w2.pc.canvas, p2[0], p2[1], button=1, modifiers={"shift"}))
    w2.pc.ia.on_release(MouseEvent("button_release_event", w2.pc.canvas, p2[0], p2[1], button=1, modifiers={"shift"}))
    check(w2.pc.selected == {u2} and not w2.pc.state.tips, "圖片視窗 Shift＋點線條 → 選取（不釘提示）")
    w2.pc.delete_selected()
    check(len(w2.series()) == 0, "圖片視窗刪除選取")
    app.sig_tree.selection_set([f"s{si.uid}"])
    app.copy_signals()
    pk.widgets._set_active(w2)
    w2.pc.paste()
    check(len(w2.series()) == 1, "圖片視窗自己的 Ctrl+V → 貼進那個視窗")
    n_main = len(app.signals)
    app._current_panel = None
    app.paste_signals()
    check(len(w2.series()) == 1 and len(app.signals) == n_main + 1 and app.signals[-1].panel == max(s.panel for s in app.signals),
          "主視窗 Ctrl+V → 貼到主圖（沒點過 panel 就開新 panel），不會跑去圖片視窗")
    app.undo_action()
    check(len(app.signals) == n_main, "Ctrl+Z 拿掉剛貼的")
    w.fig.savefig(os.path.join(OUT, "figwin.png"), dpi=80)
    w2.close()
    w.close()
    check(not pk.windows(), "關閉圖片視窗後登錄清空")
    app.sig_tree.selection_set([])
    app.fig.savefig(os.path.join(OUT, "main_styled.png"), dpi=80)


