@step
def s3e_interactor():
    from matplotlib.backend_bases import KeyEvent, MouseEvent
    app.show_all_x()
    ax = app.render_info["axes"][0]
    full = ax.get_xlim()
    ex, ey = ax.transData.transform((40.0, ax.get_ylim()[1] - 2))      # 全圖視野下線條到不了的上緣
    hit = app.ia.hit_test(MouseEvent("button_press_event", app.canvas, ex, ey, button=1))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, ex, ey, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, ex + 60, ey))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, ex + 60, ey, button=1))
    check(hit.kind == "empty" and ax.get_xlim()[0] < full[0], f"空白處拖曳平移（hit={hit.kind}）")
    app.show_all_x()
    ax = app.render_info["axes"][0]
    cx, cy = ax.transData.transform((40.0, 0.0))
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    xl1, yl1 = ax.get_xlim(), ax.get_ylim()
    check(xl1[1] - xl1[0] < full[1] - full[0] and yl1[1] - yl1[0] < 650, "滾輪：兩軸一起放大")
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1, modifiers={"shift"}))
    xl2, yl2 = ax.get_xlim(), ax.get_ylim()
    check(xl2[1] - xl2[0] < xl1[1] - xl1[0] and yl2 == yl1, "Shift+滾輪只縮 x")
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1, modifiers={"ctrl", "shift"}))
    xl3, yl3 = ax.get_xlim(), ax.get_ylim()
    check(xl3 == xl2 and yl3[1] - yl3[0] < yl2[1] - yl2[0], "Ctrl+Shift+滾輪只縮 y")
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "home", cx, cy))
    ax = app.render_info["axes"][0]
    check(abs(ax.get_xlim()[0] - full[0]) < 1e-6 and abs(ax.get_xlim()[1] - full[1]) < 1e-6, "Home 鍵還原視圖")
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1, modifiers={"shift"}))   # 只縮 x，y 仍是全幅
    ex, ey = ax.transData.transform((40.0, ax.get_ylim()[1] - 2))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, ex, ey, button=1, dblclick=True))
    ax = app.render_info["axes"][0]
    check(abs(ax.get_xlim()[1] - full[1]) < 1e-6, "雙擊空白還原視圖")
    app.toolbar.mode = "zoom rect"
    before = ax.get_xlim()
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    check(ax.get_xlim() != before and abs((before[1] - before[0]) / (ax.get_xlim()[1] - ax.get_xlim()[0]) - 1.1) < 1e-6,
          "工具列放大模式開著時滾輪照樣縮放、一格 1.1 倍（MATLAB）")
    app.toolbar.mode = ""
    before = ax.get_xlim()
    app.v["wheel_zoom"].set(False)
    app._on_wheel_zoom_toggle()
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    check(ax.get_xlim() == before, "關掉滾輪縮放後滾輪不動作")
    app.v["wheel_zoom"].set(True)
    app._on_wheel_zoom_toggle()
    app.show_all_x()
    ax = app.render_info["axes"][0]
    full = ax.get_xlim()
    yfull = ax.get_ylim()
    cx, cy = ax.transData.transform((40.0, 0.0))
    for _k in range(8):
        app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=-1))
    check(abs(ax.get_xlim()[0] - full[0]) < 1e-6 and abs(ax.get_xlim()[1] - full[1]) < 1e-6 and ax.get_ylim() == yfull,
          f"滾輪縮小到「全部顯示」的範圍為止（和 MATLAB 一樣；{ax.get_xlim()} vs {full}）")
    if HL:
        check(True, "（無桌面：放大模式單擊／Shift＋單擊的 Tk 事件測試略過）")
        return
    app.plot_toolbar._zoom()
    tk_click(app.canvas, cx, cy)
    xs = ax.get_xlim()
    px1 = (full[1] - full[0]) / ax.bbox.width                 # Tk 事件的座標是整數像素：以點為中心的誤差 < 1 px
    check(abs((full[1] - full[0]) / (xs[1] - xs[0]) - 1.5) < 1e-6 and abs(ax.transData.inverted().transform((cx, cy))[0] - 40.0) < px1,
          f"放大模式單擊 → 以該點為中心放大 1.5 倍（{xs}）")
    time.sleep(0.6); app.update()                             # 同一點再點一下要隔 500 ms 以上，不然 Tk 當雙擊（＝還原視圖）
    tk_click(app.canvas, cx, cy, shift=True)
    check(abs(ax.get_xlim()[0] - full[0]) < 1e-6 and abs(ax.get_xlim()[1] - full[1]) < 1e-6, "放大模式 Shift＋單擊 → 縮小 1.5 倍（回到全幅）")
    app.plot_toolbar._zoom()


_replots = []


@step
def s3e2_msg_no_replot_a():
    """滑鼠在圖上移動會改工具列座標訊息；Tk 因此對同樣大小的 plot_scroll 送 <Configure>，不可以因此整張重畫"""
    orig = app._do_resize_replot
    app._do_resize_replot = lambda: (_replots.append(1), orig())
    app.plot_toolbar.msg_var.set("(x, y) = (123.456, 0.0031)")
    app.update()
    app.plot_toolbar.msg_var.set("(x, y) = (1, 2)")
    app.update()


@step
def s3e2_msg_no_replot_b():
    check(not _replots, f"座標訊息改字（plot_scroll 大小沒變）不會觸發整張重畫（{len(_replots)} 次）")


@step
def s3e3_pan_view():
    """MATLAB 的平移／還原視圖：拖曳門檻 10 px、方向鍵 5 px、尺規只沿該軸平移、「原始視圖」、工具列 Home、平移模式的雙擊／右鍵。"""
    from matplotlib.backend_bases import KeyEvent, MouseEvent
    app.toolbar.mode = ""
    app.show_all_x()
    ax = app.render_info["axes"][0]
    full, yfull = ax.get_xlim(), ax.get_ylim()
    dpr = float(getattr(app.canvas, "device_pixel_ratio", 1) or 1)
    ex, ey = ax.transData.transform((40.0, ax.get_ylim()[1] - 2))      # 線條到不了的上緣
    ix, iy = int(ex), int(ey)                          # MouseEvent 的 x／y 會取整數
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, ix, iy, button=1))
    # 門檻是 10 個邏輯像素＝10×dpr 個事件像素；事件只能落在整數像素：Windows 175% 是 17.5 → 15 px 不動、18 px 才平移
    # （以前 int(10×dpr)＝17 還不到門檻；Mac 的 dpr 是 1，ceil 和 int 一樣是 10）
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, ix + int(9 * dpr), iy))
    still = ax.get_xlim() == full and not app.ia.dragging
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, ix + math.ceil(10 * dpr), iy))
    moved = ax.get_xlim() != full and app.ia.dragging
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, ix + math.ceil(10 * dpr), iy, button=1))
    check(still and moved and pk.interact.DRAG_THRESHOLD_PX == 10.0,
          f"拖曳門檻 10 px（MATLAB 的拖曳門檻）：9 px 不動、10 px 才平移（{still} {moved}）")
    app.show_all_x()
    ax = app.render_info["axes"][0]
    cx, cy = ax.transData.transform((40.0, 0.0))
    x0 = ax.get_xlim()
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "left", cx, cy))
    d_expect = 5.0 * dpr * (x0[1] - x0[0]) / ax.bbox.width
    check(abs((ax.get_xlim()[0] - x0[0]) - d_expect) < 1e-6 * abs(d_expect) + 1e-12 and ax.get_ylim() == yfull,
          f"方向鍵 ← ＝往左拖 5 像素（MATLAB 的 pan 方向鍵；移 {ax.get_xlim()[0] - x0[0]:.4g}，應 {d_expect:.4g}）")
    x1 = ax.get_xlim()
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "up", cx, cy))
    check(ax.get_xlim() == x1 and ax.get_ylim()[0] < yfull[0], "方向鍵 ↑：只動 y")
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "home", cx, cy))
    ax = app.render_info["axes"][0]
    check(abs(ax.get_xlim()[0] - full[0]) < 1e-6 and ax.get_ylim() == yfull, "方向鍵之後 Home 回到第一次互動前的視圖")
    # 「原始視圖」：x 範圍欄位設的 a..b → 縮放 → Home／工具列 Home 回 a..b（不是全幅）
    factor = sv.x_display_factor(app.current_opts())
    app.xfrom_var.set(f"{20.0 * factor:g}")
    app.xto_var.set(f"{60.0 * factor:g}")
    app.apply_xrange()
    ax = app.render_info["axes"][0]
    ab = ax.get_xlim()
    cx, cy = ax.transData.transform((40.0, 0.0))
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    zoomed = ax.get_xlim() != ab
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "home", cx, cy))
    ax = app.render_info["axes"][0]
    check(zoomed and abs(ax.get_xlim()[0] - ab[0]) < 1e-6 and abs(ax.get_xlim()[1] - ab[1]) < 1e-6,
          f"x 範圍 a..b → 滾輪 → Home 回 a..b（MATLAB Restore View＝原始視圖；{ax.get_xlim()} vs {ab}）")
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    app.plot_toolbar._home()
    ax = app.render_info["axes"][0]
    check(abs(ax.get_xlim()[0] - ab[0]) < 1e-6 and abs(ax.get_xlim()[1] - ab[1]) < 1e-6,
          "圖工具列的 Home 也回原始視圖（跟 Home 鍵、雙擊一致）")
    app.show_all_x()
    check(not app.ia.has_home(), "全部顯示＝明確換視圖，原始視圖重記")
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "home", cx, cy))
    ax = app.render_info["axes"][0]
    check(abs(ax.get_xlim()[1] - full[1]) < 1e-6, "還沒互動過按 Home＝全部顯示")
    # 尺規：x 刻度數字拖曳只沿 x 平移；右鍵、雙擊在尺規上不動作
    app.canvas.draw()
    r = app.canvas.get_renderer()
    labs = [t for t in ax.xaxis.get_majorticklabels() if t.get_visible() and t.get_text()]
    tb = labs[len(labs) // 2].get_window_extent(r)
    rx, ry = (ax.bbox.x0 + ax.bbox.x1) / 2, (tb.y0 + tb.y1) / 2
    hr = app.ia.hit_test(MouseEvent("button_press_event", app.canvas, rx, ry, button=1))
    yb = ax.get_ylim()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, rx, ry, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, rx - 60, ry + 30))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, rx - 60, ry + 30, button=1))
    ax = app.render_info["axes"][0]
    check(hr.kind == "ruler" and hr.id == "x" and ax.get_xlim()[0] > full[0] and ax.get_ylim() == yb,
          f"拖曳 x 尺規：只沿 x 平移（MATLAB rulerPanInteraction；hit {hr.kind} {hr.id}）")
    n_menu = len(menus)
    xl = ax.get_xlim()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, rx, ry, button=3))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, rx, ry, button=1, dblclick=True))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, rx, ry, button=1))
    check(len(menus) == n_menu and app.render_info["axes"][0].get_xlim() == xl, "尺規上右鍵不出選單、雙擊不動作（MATLAB 的 pan）")
    lab_y = [t for t in ax.yaxis.get_majorticklabels() if t.get_visible() and t.get_text()]
    tby = lab_y[len(lab_y) // 2].get_window_extent(r)
    hy = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, (tby.x0 + tby.x1) / 2, (ax.bbox.y0 + ax.bbox.y1) / 2))
    check(hy.kind != "ruler" and app._margin_panel(MouseEvent("motion_notify_event", app.canvas, (tby.x0 + tby.x1) / 2, (ax.bbox.y0 + ax.bbox.y1) / 2)) is not None,
          f"主視窗的 y 刻度數字＝panel 握把，不是尺規（{hy.kind}；x 尺規照舊）")
    # 工具列平移模式：雙擊＝還原視圖、右鍵＝選單、方向鍵照樣平移
    app.show_all_x()
    ax = app.render_info["axes"][0]
    cx, cy = ax.transData.transform((40.0, 0.0))
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1))
    app.toolbar.mode = "pan/zoom"
    try:
        xz = ax.get_xlim()
        app.ia.on_key(KeyEvent("key_press_event", app.canvas, "right", cx, cy))
        key_ok = ax.get_xlim()[0] < xz[0]                  # → ＝往右拖 5 像素：內容往右、範圍往左
        n_menu = len(menus)
        app.ia.on_press(MouseEvent("button_press_event", app.canvas, ex, ey, button=3))
        menu_ok = len(menus) == n_menu + 1
        app.ia.on_press(MouseEvent("button_press_event", app.canvas, ex, ey, button=1, dblclick=True))
    finally:
        app.toolbar.mode = ""
    ax = app.render_info["axes"][0]
    check(key_ok and menu_ok and abs(ax.get_xlim()[0] - full[0]) < 1e-6 and abs(ax.get_xlim()[1] - full[1]) < 1e-6,
          f"工具列平移模式：方向鍵平移、右鍵＝選單、雙擊＝還原視圖（MATLAB pan 模式；{key_ok} {menu_ok}）")
    if HL:
        check(True, "（無桌面：拖曳門檻／尺規游標／平移模式右鍵拖曳的 Tk 事件測試略過）")
        return
    # 真實 Tk 事件：9 px 放開＝點一下（不平移）、10 px＝平移；尺規懸停換游標；平移模式右鍵拖曳不縮放
    app.show_all_x()
    app.update()
    ax = app.render_info["axes"][0]
    full = ax.get_xlim()
    w = app.canvas.get_tk_widget()
    H = app.canvas.get_width_height(physical=True)[1]
    ex, ey = ax.transData.transform((40.0, ax.get_ylim()[1] - 2))
    t0 = int(time.monotonic() * 1000) & 0x7fffffff

    def tk_drag(px, py, dx, btn=1, t=0):
        x, y = int(round(px)), int(round(H - py))
        mask = {1: 0x100, 2: 0x200, 3: 0x400}[btn]
        w.event_generate(f"<ButtonPress-{btn}>", x=x, y=y, when="now", time=t)
        for k in (1, 2):
            w.event_generate("<Motion>", x=x + dx * k // 2, y=y, state=mask, when="now", time=t + 10 * k)
        w.event_generate(f"<ButtonRelease-{btn}>", x=x + dx, y=y, state=mask, when="now", time=t + 30)
        app.update()

    tk_drag(ex, ey, int(9 * dpr), t=t0)
    nine = ax.get_xlim() == full
    tk_drag(ex - 40, ey, math.ceil(10 * dpr), t=t0 + 2000)              # 10 個邏輯像素：Windows 175% 是 18 個事件像素（W10）
    ten = app.render_info["axes"][0].get_xlim() != full
    check(nine and ten, f"Tk 事件：移 9 px 放開＝點一下、10 px＝平移（{nine} {ten}）")
    app.canvas.draw()
    app.update()
    ax = app.render_info["axes"][0]
    r = app.canvas.get_renderer()
    lab_y = [t for t in ax.yaxis.get_majorticklabels() if t.get_visible() and t.get_text()]
    tby = lab_y[len(lab_y) // 2].get_window_extent(r)
    hx, hy_ = int(round((tby.x0 + tby.x1) / 2)), int(round(H - (ax.bbox.y0 + ax.bbox.y1) / 2))
    w.event_generate("<Motion>", x=hx, y=hy_, when="now", time=t0 + 4000)
    app.update()
    cur_on = str(w.cget("cursor"))
    cx_, cy_ = ax.transData.transform((40.0, 0.0))
    w.event_generate("<Motion>", x=int(cx_), y=int(H - cy_), when="now", time=t0 + 4100)
    app.update()
    cur_off = str(w.cget("cursor"))
    want = "openhand" if w.tk.call("tk", "windowingsystem") == "aqua" else "hand2"     # 主視窗：y 刻度區＝panel 握把（手形），不是 y 尺規
    check(cur_on == want and cur_off != want, f"游標移到 y 刻度區變 {want}（panel 握把）、移進座標區還原（{cur_on!r} → {cur_off!r}）")
    app.show_all_x()
    app.update()
    ax = app.render_info["axes"][0]
    full = ax.get_xlim()
    app.plot_toolbar._pan()
    try:
        rb = 2 if sys.platform == "darwin" else 3
        n_menu = len(menus)
        tk_drag(ex, ey - 40, 80, btn=rb, t=t0 + 6000)
        check(app.render_info["axes"][0].get_xlim() == full and len(menus) == n_menu + 1,
              f"平移模式右鍵拖曳不縮放、出選單（MATLAB pan 模式 'alt'＝選單；選單 {len(menus) - n_menu}）")
    finally:
        app.plot_toolbar._pan()


@step
def s3f_datatips():
    from matplotlib.backend_bases import KeyEvent, MouseEvent
    si = app.find_signal("iq.csv;;adc i")
    app.v_tips.set(True)
    app._on_tips_toggle()
    app.canvas.draw()
    a = app.render_info["artists"][si.uid]
    ax, ln = a["ax"], a["line"]
    xd, yd = ln.get_xdata(), ln.get_ydata()
    px, py = ax.transData.transform((xd[1000], yd[1000]))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, px, py, button=1))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, px, py, button=1))
    spp = len(xd) / max(1.0, float(ax.bbox.width))            # 每個像素幾個樣本：事件座標是整數像素，釘到的點最多差這麼多
    tol = max(3, int(round(spp)) + 1)
    check(len(app.datatips) == 1 and app.datatips[0].uid == si.uid and abs(app.datatips[0].index - 1000) <= tol
          and len(app.ia.tip_artists) == 1,
          f"資料提示模式：點線釘住（uid、樣本索引 ±{tol}；得到 {[ (t.uid, t.index) for t in app.datatips ]}）")
    ann, mk = app.ia.tip_artists[app.datatips[0].id]
    check("adc i" in ann.get_text() and "\nX " in ann.get_text() and "\nY " in ann.get_text(),
          f"資料提示文字：名稱＋X／Y 兩列（{ann.get_text().splitlines()}）")
    app.plot()
    check(len(app.ia.tip_artists) == 1 and len(app.datatips) == 1, "重畫後資料提示重建")
    app.v_tips.set(False)
    app._on_tips_toggle()
    app.canvas.draw()
    ann, mk = app.ia.tip_artists[app.datatips[0].id]
    bb = ann.get_bbox_patch().get_window_extent(app.canvas.get_renderer())
    tx, ty = (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2
    off_placed = app.datatips[0].offset
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, tx, ty, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, tx + 30, ty + 10))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, tx + 30, ty + 10, button=1))
    check(app.datatips[0].offset != off_placed, f"拖曳資料提示（offset={app.datatips[0].offset}）")
    cfg = app.dump_settings()
    check(len(cfg["datatips"]) == 1 and cfg["datatips"][0]["uid"] == si.uid, "設定檔含資料提示")
    app.ia.select_tip(app.datatips[0].id)
    i0, xl_k = app.datatips[0].index, ax.get_xlim()
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "right", tx, ty))
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "up", tx, ty))
    i2 = app.datatips[0].index
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "down", tx, ty))
    i1 = app.datatips[0].index
    check(i2 == i0 + 2 and i1 == i0 + 1 and ax.get_xlim() == xl_k,
          f"選取的資料提示：→／↑ 下一個樣本、↓ 上一個，不平移（{i0}→{i2}→{i1}）")
    app.undo_action()
    check(app.datatips and app.datatips[0].index == i0,
          f"方向鍵移動資料提示可復原（連續按鍵 2 秒內合併成一筆；{app.datatips[0].index if app.datatips else None}）")
    app.ia.select_tip(app.datatips[0].id)
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "delete", tx, ty))
    check(len(app.datatips) == 0 and not app.ia.tip_artists, "Delete 刪除資料提示")
    app.apply_settings(cfg, quiet=True)
    check(len(app.datatips) == 1 and len(app.ia.tip_artists) == 1, "apply_settings 還原資料提示")
    app.datatips[0].index = 10 ** 9
    app.plot()
    check(len(app.datatips) == 0, "索引超出範圍的資料提示在重畫時丟棄")
    # hover 暫時提示（MATLAB dataTipInteraction）：線上 ±2 px → 頂點標記＋crosshair、停 200 ms 出框、不進模型／undo、移開收掉、點一下才釘
    app.v_tips.set(True)
    app._on_tips_toggle()
    app.canvas.draw()
    a = app.render_info["artists"][si.uid]
    ax, ln = a["ax"], a["line"]
    xd, yd = ln.get_xdata(), ln.get_ydata()
    hx, hy = ax.transData.transform((xd[1000], yd[1000]))
    n_undo = len(app.undo)
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, hx, hy))
    h = app.ia.hover_tip
    check(h is not None and h["uid"] == si.uid and h["mk"].get_visible() and not h["ann"].get_visible()
          and not app.datatips and len(app.undo) == n_undo, "hover：線上 → 頂點標記、框等 200 ms、不進模型／undo")
    app.ia._hover_linger()
    check(h["ann"].get_visible() and "adc i" in h["ann"].get_text() and "\nX " in h["ann"].get_text(),
          f"hover：linger 後出現暫時提示框（{h['ann'].get_text().splitlines()}）")
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, hx, ax.bbox.y1 - 3))
    check(app.ia.hover_tip is None, "hover：離開線 → 收掉")
    # 視圖改變：資料點在 XLim 外整個提示不畫、回來再畫；自動擺放的提示靠右時翻到左邊
    tip = app.ia.add_tip(si.uid, 1000)
    t_ann, t_mk = app.ia.tip_artists[tip.id]
    xl0 = ax.get_xlim()
    ax.set_xlim(xd[1500], xd[2500])
    hid = not t_ann.get_visible() and not t_mk.get_visible()
    ax.set_xlim(xd[900], xd[1003])
    flip, off_r = t_ann.get_visible() and tip.offset[0] < 0, tip.offset
    ax.set_xlim(*xl0)
    check(hid and flip, f"視圖改變：點在 XLim 外不畫（{hid}）、點靠右緣 → 框翻到左邊（{flip}，offset={off_r}）")
    app.ia.remove_tip(tip.id)
    app.canvas.draw()
    if HL:
        check(True, "（無桌面：hover 的真實 Tk <Motion>／200 ms／游標檢查略過）")
        return
    w = app.canvas.get_tk_widget()
    H = app.canvas.get_width_height(physical=True)[1]
    app.update()
    w.event_generate("<Motion>", x=int(round(hx)), y=int(round(H - hy)), when="now")
    app.update()
    cur0 = str(w.cget("cursor"))
    h = app.ia.hover_tip
    t_end = time.monotonic() + 1.5
    while h is not None and not h["ann"].get_visible() and time.monotonic() < t_end:
        time.sleep(0.02)
        app.update()
    shown = h is not None and h["ann"].get_visible()
    check(h is not None and cur0 == "crosshair" and shown and not app.datatips,
          f"Tk <Motion> 到線上 → crosshair、200 ms 後出現暫時提示框（cursor={cur0!r}、shown={shown}）")
    w.event_generate("<Motion>", x=int(round(hx)), y=int(round(H - (ax.bbox.y1 - 3))), when="now")
    app.update()
    check(app.ia.hover_tip is None and str(w.cget("cursor")) != "crosshair",
          f"Tk <Motion> 離開線 → 收掉、游標還原（{str(w.cget('cursor'))!r}）")


@step
def s3g_annotations():
    from matplotlib.backend_bases import MouseEvent
    n0 = len(app.undo)
    app.add_annotation("xline", 1, x=20.0)
    app.add_annotation("yline", 1, y=100.0)
    sv.simpledialog.askstring = lambda *a, **k: "note"
    app.add_annotation("text", 1, x=30.0, y=50.0)
    check(len(app.annotations) == 3 and len(app.ia.ann_artists) == 3 and len(app.undo) == n0 + 3,
          "xline / yline / text 標註（各推一筆 undo）")
    ax = app.render_info["axes"][0]
    menus.clear()
    ex, ey = ax.transData.transform((60.0, ax.get_ylim()[1] - 2))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, ex, ey, button=3))
    check(menus and any(s.startswith("插入垂直參考線") for s in menus[-1]) and "複製圖到剪貼簿" in menus[-1]
          and any(s.startswith("復原") for s in menus[-1]), f"空白右鍵選單（{len(menus[-1]) if menus else 0} 項）")
    check(menus and "複製向量圖（PDF）到剪貼簿" in menus[-1], "空白右鍵選單有「複製向量圖（PDF）到剪貼簿」（MATLAB Copy as vector graphic）")
    app.canvas.draw()
    tid = app.annotations[2].id
    art = app.ia.ann_artists[tid]
    bb = art.get_window_extent(app.canvas.get_renderer())
    tx, ty = (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, tx, ty, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, tx + 40, ty))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, tx + 40, ty, button=1))
    check(app.annotations[2].x > 30.0, f"拖曳文字標註（x={app.annotations[2].x:.2f}）")
    cfg = app.dump_settings()
    check(len(cfg["annotations"]) == 3 and cfg["annotations"][0]["kind"] == "xline" and cfg["annotations"][0]["value"] == 20.0,
          "設定檔含標註（symbol 單位）")
    app.ia.remove_annotation(app.annotations[0].id)
    check(len(app.annotations) == 2 and len(app.ia.ann_artists) == 2, "刪除標註")
    app.undo_action()
    check(len(app.annotations) == 3 and len(app.ia.ann_artists) == 3, "undo 還原標註")
    app.plot()
    check(len(app.ia.ann_artists) == 3, "重畫後標註重建")
    # 點選標註＝選取、Esc 取消、Delete 刪它（只刪標註、可 undo）、右鍵先選取、與訊號清單選取互斥（MATLAB plot edit）
    from matplotlib.backend_bases import KeyEvent
    app.ia.select_annotation(None)
    app.canvas.draw()
    tid = app.annotations[2].id
    bb = app.ia.ann_artists[tid].get_window_extent(app.canvas.get_renderer())
    tx, ty = (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, tx, ty, button=1))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, tx, ty, button=1))
    check(app.ia.selected_ann == tid and "已選取標註" in app.status_var.get(), f"點文字標註＝選取（{app.status_var.get()}）")
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "escape", tx, ty))
    check(app.ia.selected_ann is None, "Esc 取消標註選取")
    n_sig, n_ann, n_undo = len(app.signals), len(app.annotations), len(app.undo)
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, tx, ty, button=3))
    check(app.ia.selected_ann == tid, "右鍵標註：先選取再出選單")
    app.ia.on_key(KeyEvent("key_press_event", app.canvas, "delete", tx, ty))
    check(len(app.annotations) == n_ann - 1 and len(app.signals) == n_sig and len(app.undo) == n_undo + 1
          and app.ia.selected_ann is None, "Delete 刪掉選取的標註（訊號不動、推一筆 undo）")
    app.undo_action()
    check(len(app.annotations) == n_ann and any(a.id == tid for a in app.annotations), "undo 復活刪掉的標註")
    app.canvas.draw()
    s0 = app.signals[0]
    tree = app.sig_tree
    if tree.exists(f"s{s0.uid}"):
        app.ia.select_annotation(tid)
        tree.selection_set([f"s{s0.uid}"])
        app._on_list_select()
        check(app.ia.selected_ann is None, "清單選訊號 → 取消標註的選取（Delete 只刪目前選的那一種）")
        app.ia.select_annotation(tid)
        check(not tree.selection() and app.ia.selected_ann == tid, "選標註 → 清單選取清空")
    app.ia.select_annotation(None)


@step
def s3h_undo_redo():
    si = app.find_signal("iq.csv;;adc i")
    sq = app.find_signal("iq.csv;;adc q")
    d0 = si.data
    app.sig_tree.selection_set([f"s{si.uid}"])
    sv.colorchooser.askcolor = lambda **k: ((0, 255, 0), "#00ff00")
    app.edit_color()
    check(si.color == "#00ff00", "改色")
    app.undo_action()
    check(si.color is None and si.data is d0, f"undo 樣式 → 顏色還原、data 快取保留（color={si.color!r} same={si.data is d0} undo={len(app.undo)}）")
    app.redo_action()
    check(si.color == "#00ff00", "redo 樣式")
    app.undo_action()
    app.p_shift.set("1")
    app.p_scale.set("1")
    app.apply_shift_scale()
    d1 = si.data
    check(d1 is not d0 and float(d1[0]) == float(si.raw[0]) + 1.0, "shift 套用 → data 重算")
    app.undo_action()
    check(si.vshift == -512.0 and si.data is not d1 and float(si.data[0]) == float(d0[0]), "undo shift → 資料重算回原值")
    n = len(app.undo)
    app.sig_tree.selection_set([f"s{sq.uid}"])
    for v in (3, 4, 5):
        app.offset_slider_var.set(v)
        app._apply_offset_slider()
    check(len(app.undo) == n + 1 and sq.offset == 5.0, "滑桿連續三次只推一筆 undo")
    app.undo_action()
    check(sq.offset == 0.0, "undo 滑桿")
    app.sig_tree.selection_set([f"s{sq.uid}"])
    app.remove_selected()
    check(app.find_signal("iq.csv;;adc q") is None, "移除 adc q")
    app.undo_action()
    sq2 = app.find_signal("iq.csv;;adc q")
    check(sq2 is sq and sq2.raw is not None, "undo 移除 → 同一個物件復活、快取還在")
    app.undo.clear()
    app._update_undo_buttons()
    check(app.btn_undo.instate(["disabled"]) and app.btn_redo.instate(["disabled"]), "堆疊空時按鈕停用")
    app.sig_tree.selection_set([])


