@step
def s3j_clipboard():
    from matplotlib.backend_bases import MouseEvent
    captured = {}
    orig = pk.clipboard.copy_png_to_clipboard
    pk.clipboard.copy_png_to_clipboard = lambda path: captured.setdefault("size", os.path.getsize(path)) and (True, "fake ok")
    ax = app.render_info["axes"][0]
    px, py = ax.transData.transform((20.0, sum(ax.get_ylim()) / 2))
    app.canvas.draw()
    app._on_motion(MouseEvent("motion_notify_event", app.canvas, px, py))      # 先讓十字游標顯示出來
    check(bool(app._cursor_items) and app._cursor_items[0][1].get_visible(), "複製前十字游標是顯示的")
    ok, msg = app.copy_figure_clipboard()
    check(ok and captured.get("size", 0) > 1000 and "fake ok" in app.status_var.get(), "複製圖到剪貼簿：產生 PNG 並呼叫剪貼簿函式")
    check(all(not vl.get_visible() and not tx.get_visible() for _a, vl, tx in app._cursor_items), "複製圖前把十字游標藏起來（不會印進 PNG）")
    pk.clipboard.copy_png_to_clipboard = lambda path: (False, f"failed; PNG 已存到 {path}")
    ok, msg = app.copy_figure_clipboard()
    check(not ok and "PNG 已存到" in msg, "失敗時回報 PNG 路徑")
    left_png = msg.split("PNG 已存到 ", 1)[-1].strip() if "PNG 已存到 " in msg else ""
    check(bool(left_png) and os.path.isfile(left_png), f"失敗時 PNG 真的留在那裡給使用者用（{left_png}）")
    if left_png and os.path.isfile(left_png):          # 0.9.14 W13：測試自己留下的暫存檔自己刪（以前每跑一次在 %TEMP% 留一個）
        os.remove(left_png)
    pk.clipboard.copy_png_to_clipboard = orig
    capv = {}
    origv = pk.clipboard.copy_pdf_to_clipboard

    def fake_pdf(path):
        with open(path, "rb") as fh:
            capv["head"] = fh.read(5)
        return True, "fake pdf ok"
    pk.clipboard.copy_pdf_to_clipboard = fake_pdf
    vsup = pk.clipboard.clipboard_vector_supported()
    bvec = app.plot_toolbar.buttons["clipvec"]
    check(bool(bvec.instate(["disabled"])) == (not vsup),
          f"工具列「複製向量圖」跟著平台啟用／停用（{sys.platform}：disabled={bool(bvec.instate(['disabled']))}）")
    try:
        if vsup:
            bvec.invoke()
            check(capv.get("head") == b"%PDF-" and "fake pdf ok" in app.status_var.get(),
                  "工具列「複製向量圖（PDF）」：產生 PDF 並放剪貼簿（MATLAB Copy as vector graphic）")
            capv.clear()
            ok, msg = app.copy_figure_clipboard(vector=True)
            check(ok and capv.get("head") == b"%PDF-", "copy_figure_clipboard(vector=True) → PDF")
        else:
            check("放不了向量圖" in str(getattr(bvec, "_pk_tip", "")), "剪貼簿放不了向量圖（Windows）：工具列按鈕停用、tooltip 說明")
    finally:
        pk.clipboard.copy_pdf_to_clipboard = origv


@step
def s3k_legend_rename():
    from matplotlib.backend_bases import MouseEvent
    sq = app.find_signal("iq.csv;;adc q")
    app.canvas.draw()
    ax = app.render_info["axes"][0]
    leg = (app.render_info["axes_right"].get(1) or ax).get_legend()
    t = leg.get_texts()[1]
    bb = t.get_window_extent(app.canvas.get_renderer())
    cx, cy = (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2
    hit = app.ia.hit_test(MouseEvent("button_press_event", app.canvas, cx, cy, button=1))
    check(hit.kind == "legend" and hit.id == sq.uid, f"hit_test：圖例文字 → uid（{hit.kind} {hit.id}）")
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, cx, cy, button=1, dblclick=True))
    ed = getattr(app, "_inline_editor", None)
    check(ed is not None and ed.entry.winfo_exists(), "雙擊圖例 → 就地編輯 Entry")
    ed.entry.delete(0, "end")
    ed.entry.insert(0, "Q2")
    ed._commit()
    check(sq.label == "Q2" and app.sig_tree.item(f"s{sq.uid}", "values")[2] == "Q2", "圖例改名 → label 與清單更新")
    app.undo_action()
    check(sq.label == "iq:adc q", "undo 改名")


@step
def s3m_line_menu_matlab_values():
    """主畫面線條／清單右鍵共用的樣式選單：線寬、標記大小是 MATLAB 線條選單的固定值，線型多了 none，標記 14 種。"""
    sq = app.find_signal("iq.csv;;adc q")
    app.sig_tree.selection_set([f"s{sq.uid}"]); app._on_list_select(); app.update()
    m = sv.tk.Menu(app, tearoff=0)
    app._add_style_menu_items(m)
    def sub_of(label):
        for i in range(m.index("end") + 1):
            if m.type(i) == "cascade" and m.entrycget(i, "label") == label:
                sub = m.nametowidget(m.entrycget(i, "menu"))
                return sub, ["---" if sub.type(j) == "separator" else sub.entrycget(j, "label") for j in range(sub.index("end") + 1)]
        return None, []
    sub_w, lw_labels = sub_of("線寬")
    check(lw_labels == ["0.5"] + [f"{v}.0" for v in range(1, 13)] + ["---", "自訂…"], f"線寬 ▸ 0.5、1.0 … 12.0、自訂…（{lw_labels}）")
    sub_s, ms_labels = sub_of("標記大小")
    check(ms_labels == ["2", "4", "5", "6", "7", "8", "10", "12", "18", "24", "48", "---", "自訂…"], f"標記大小 ▸ MATLAB 的 11 個值（{ms_labels}）")
    _s, ls_labels = sub_of("線型")
    check(ls_labels == ["自動", "solid  -", "dash  --", "dot  :", "dash-dot  -.", "none"], f"線型 ▸ 自動＋MATLAB 的 5 種（{ls_labels}）")
    _s, mk_labels = sub_of("標記")
    check(len(mk_labels) == 14, f"標記 ▸ MATLAB 的 14 種（{len(mk_labels)}）")
    lw0, ms0 = sq.lw, sq.ms
    sub_w.invoke(lw_labels.index("3.0"))
    sub_s.invoke(ms_labels.index("12"))
    check(sq.lw == 3.0 and sq.ms == 12.0, f"線寬 ▸ 3.0、標記大小 ▸ 12 → 套用（lw {sq.lw}、ms {sq.ms}）")
    app.undo_action(); app.undo_action()
    check(sq.lw == lw0 and sq.ms == ms0, "undo ×2 → 線寬／標記大小還原")
    m.destroy()
    app.sig_tree.selection_set([]); app._on_list_select(); app.update()


@step
def s3l_legend_drag_menu_spectrum():
    """跟 MATLAB 一樣：拖曳圖例＝移動圖例（重畫後留在原處）；圖例右鍵「刪除圖例」「圖例位置」；頻譜視窗的圖例也能雙擊改名、拖曳。"""
    from matplotlib.backend_bases import MouseEvent
    app.canvas.draw()
    ax = app.render_info["axes"][0]
    top = app.render_info["axes_right"].get(1) or ax
    leg = top.get_legend()
    r = app.canvas.get_renderer()
    lb = leg.get_window_extent(r)
    tb = leg.get_texts()[0].get_window_extent(r)
    hx, hy = (lb.x0 + tb.x0) / 2, (tb.y0 + tb.y1) / 2
    xl0 = ax.get_xlim()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, hx, hy, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, hx - 90, hy - 60))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, hx - 90, hy - 60, button=1))
    app.canvas.draw()
    lb1 = (app.render_info["axes_right"].get(1) or app.render_info["axes"][0]).get_legend().get_window_extent(app.canvas.get_renderer())
    check(ax.get_xlim() == xl0 and isinstance(app.legend_loc.get(1), tuple) and abs((lb1.x0 - lb.x0) + 90) < 3 and abs((lb1.y0 - lb.y0) + 60) < 3,
          f"拖曳圖例 → 圖例移動 (-90,-60)、不平移（Δ=({lb1.x0 - lb.x0:.0f},{lb1.y0 - lb.y0:.0f})）")
    app.plot(keep=True)
    app.canvas.draw()
    lb2 = (app.render_info["axes_right"].get(1) or app.render_info["axes"][0]).get_legend().get_window_extent(app.canvas.get_renderer())
    check(abs(lb2.x0 - lb1.x0) < 2 and abs(lb2.y0 - lb1.y0) < 2, "重畫（PLOT）後圖例留在拖到的位置")
    tb = (app.render_info["axes_right"].get(1) or app.render_info["axes"][0]).get_legend().get_texts()[0].get_window_extent(app.canvas.get_renderer())
    menus.clear()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, (tb.x0 + tb.x1) / 2, (tb.y0 + tb.y1) / 2, button=3))
    check(menus and "刪除圖例" in menus[-1] and "圖例位置" in menus[-1] and "顏色…" not in menus[-1],
          f"右鍵圖例：刪除圖例／圖例位置（MATLAB 的 Delete／Location）（{menus[-1] if menus else []}）")
    app.ia.host.on_legend_loc(app.render_info["axes_right"].get(1) or app.render_info["axes"][0], "lower left")
    check(app.legend_loc.get(1) == "lower left", "圖例位置 → 左下")
    app.ia.host.on_legend_delete(app.render_info["axes"][0])
    check(not app.v["legend"].get() and (app.render_info["axes_right"].get(1) or app.render_info["axes"][0]).get_legend() is None, "刪除圖例 → 圖例關掉")
    app.v["legend"].set(True)
    app.legend_loc.clear()
    app.plot(keep=True)
    # 頻譜視窗：圖例雙擊改名（MATLAB 預設 ItemHitFcn）、拖曳圖例
    sigs = [app.find_signal("iq.csv;;adc i"), app.find_signal("iq.csv;;adc q")]
    app.spec_defaults["iq"] = False
    sw = sv.SpectrumWindow(app, sigs)
    app.update()
    check(sw.fig.axes[0].get_legend() is None, "頻譜視窗：圖例預設關（MATLAB spectrumAnalyzer ShowLegend＝false）")
    sw.v_legend.set(True); sw.compute()                      # 示波器 → 設定 → 圖例
    app.update()
    sw.canvas.draw()
    sax = sw.fig.axes[0]
    sleg = sax.get_legend()
    stb = sleg.get_texts()[0].get_window_extent(sw.canvas.get_renderer())
    scx, scy = (stb.x0 + stb.x1) / 2, (stb.y0 + stb.y1) / 2
    sw.ia.on_press(MouseEvent("button_press_event", sw.canvas, scx, scy, button=1, dblclick=True))
    ed = getattr(sw, "_inline_editor", None)
    check(ed is not None and ed.entry.winfo_exists(), "頻譜視窗：雙擊圖例 → 就地編輯 Entry")
    ed.entry.delete(0, "end")
    ed.entry.insert(0, "spec I")
    ed._commit()
    check(sax.get_legend().get_texts()[0].get_text() == "spec I", "頻譜視窗：圖例改名套用")
    slb = sax.get_legend().get_window_extent(sw.canvas.get_renderer())
    sxl0 = sax.get_xlim()
    sw.ia.on_press(MouseEvent("button_press_event", sw.canvas, (slb.x0 + stb.x0) / 2, scy, button=1))
    sw.ia.on_motion(MouseEvent("motion_notify_event", sw.canvas, (slb.x0 + stb.x0) / 2 - 80, scy - 50))
    sw.ia.on_release(MouseEvent("button_release_event", sw.canvas, (slb.x0 + stb.x0) / 2 - 80, scy - 50, button=1))
    sw.canvas.draw()
    slb1 = sax.get_legend().get_window_extent(sw.canvas.get_renderer())
    check(HL or (sax.get_xlim() == sxl0 and isinstance(sw.legend_loc, tuple) and abs((slb1.x0 - slb.x0) + 80) < 3),
          f"頻譜視窗：拖曳圖例 → 移動、不平移（Δx={slb1.x0 - slb.x0:.0f}）" + ("（無桌面：視窗沒有實際尺寸，像素檢查略過）" if HL else ""))
    sw.destroy()


@step
def s4_text_files():
    iids = [i for i, nd in app.tree_map.items() if nd["kind"] == "text"]
    app._add_tree_items(iids)
    check(len(app.signals) == 6, f"加入 4 個文字檔後共 {len(app.signals)} 條")
    hx = app.find_signal("hex/samples.txt")
    check(hx is not None and hx.detected == "HEX" and hx.get_data()[0] == 2048, f"hex 檔 AUTO→{hx.detected if hx else None}")
    wd = app.find_signal("sub dir [1]/weird name #2.txt")
    check(wd is not None and wd.n == 134, "怪檔名文字檔讀入")
    clk_s = app.find_signal("digital/clk.txt")
    dat_s = app.find_signal("digital/data.txt")
    app.sig_tree.selection_set([f"s{clk_s.uid}", f"s{dat_s.uid}"])
    app.merge_panels()
    info = app.render_info
    p = clk_s.panel
    check(dat_s.panel == p and len(info["diff_segments"].get(p, [])) == 2, f"數位訊號合併後差異 {len(info['diff_segments'].get(p, []))} 段（預期 2）")
    ax = info["axes"][info["panels"].index(p)]
    check(list(ax.get_yticks()) == [0, 1] and ax.get_ylim() == (-0.2, 1.2), f"數位 panel ticks {ax.get_yticks()} ylim {ax.get_ylim()}")
    app.fig.savefig(os.path.join(OUT, "main_all.png"), dpi=80)


@step
def s5_edit_and_params():
    clk_s = app.find_signal("digital/clk.txt")
    app._commit_edit(clk_s, "sps", "4")
    check(clk_s.sps == 4.0, "就地編輯 SPS=4")
    app._commit_edit(clk_s, "label", "CLK")
    check(clk_s.name == "CLK", "編輯名稱")
    app.sig_tree.selection_set([f"s{clk_s.uid}"])
    app._on_list_select()
    check(app.p_sps.get() == "4" and app.p_fs.get() == "4M", f"選取後帶入參數 sps={app.p_sps.get()} fs={app.p_fs.get()}")
    app.scale_sps(2.0)
    check(clk_s.sps == 8.0, "×2 → SPS 8")
    app.p_fs.set("16M")
    app.apply_fs()
    check(clk_s.sps == 16.0, "Sample rate 16M → SPS 16")
    app.nudge_offset(10)
    check(clk_s.offset == 10.0, "offset +10")
    app.v["offset_unit"].set("sample")
    check(sv.SETTINGS["offset_unit"] == "sample" and abs(clk_s.x0 - 10 / 16) < 1e-12, f"offset 單位 sample → x0={clk_s.x0}")
    app.v["offset_unit"].set("symbol")
    app.offset_slider_var.set(25)
    app._apply_offset_slider()
    check(clk_s.offset == 25.0, "offset 滑桿 → 25")
    app.p_shift.set("1")
    app.p_scale.set("2")
    app.apply_shift_scale()
    check(clk_s.get_data()[2] == 4.0, "shift/scale：(1+1)×2 = 4")
    app.p_shift.set("0")
    app.p_scale.set("1")
    app.apply_shift_scale()
    app.set_fmt("HEX")
    check(clk_s.fmt == "HEX" and clk_s.detected == "HEX", "讀取格式 HEX 重新讀檔")
    app.set_fmt("AUTO")
    app.v["dk"].set("3")
    app.v["dthr"].set(12.0)
    app.v["dmin"].set("30")
    app.sig_tree.selection_set([f"s{app.find_signal('iq.csv;;adc i').uid}"])
    app.apply_despike_params()
    si = app.find_signal("iq.csv;;adc i")
    check((si.dk, si.dthr, si.dmin) == (3, 12.0, 30.0) and si.spikes_fixed == 3, f"despike 參數套用 {si.dk},{si.dthr},{si.dmin} 修正 {si.spikes_fixed}")
    app.set_despike(False)
    check(not si.despike and si.spikes_fixed == 0, "despike 關閉")
    app.set_despike(True)
    app.sig_tree.selection_set([])


@step
def s6_view():
    app.v["xunit"].set("us")
    app.v["symbol_rate"].set("1M")
    app.xfrom_var.set("10")
    app.xto_var.set("50")
    app.apply_xrange()
    xl = app.current_xlim()
    check(abs(xl[0] - 10) < 1e-6 and abs(xl[1] - 50) < 1e-6, f"x 範圍 10..50 us → xlim {xl}")
    ax = app._current_axes()                     # 2026-10-25 第 8 項起 x 單位是每個 panel 各自的：工具列的欄位改的是目前 panel
    labels = [ax.xaxis.get_major_formatter()(v) for v in (10, 50)]
    check(labels == ["10", "50"] and ax.get_xlabel() == "x [us]", f"x 軸格式（目前 panel）{labels} {ax.get_xlabel()}")
    app.v["xunit"].set("ns")
    app.plot()
    ax = app._current_axes()
    check(ax.xaxis.get_major_formatter()(10) == "10000", "ns 單位（目前 panel）：10 symbol → 10000")
    app.v["xunit"].set("symbol")
    app.show_all_x()
    xl2 = app.current_xlim()
    check(xl2[1] - xl2[0] > 300, f"全部顯示 xlim {xl2}")
    app.v["dashed"].set(True)
    app.v["ystack"].set("50")
    app.v["markers"].set(True)
    app.v["tol"].set("5")
    app.plot()
    check(app.render_info["panels"] and app.status_var.get(), "虛線/疊圖位移/markers 重畫不出錯")
    app.v["dashed"].set(False)
    app.v["ystack"].set("0")
    app.v["markers"].set(False)
    app.v["tol"].set("0")
    app.v["panel_height"].set("2.5")
    app.plot()
    h = app.fig.get_size_inches()[1]
    npan = len(app.render_info["panels"])
    check(h >= npan * 2.5, f"每張圖高度 2.5 in × {npan} panel → 畫布 {h:.1f} in，可捲動")
    app.v["panel_height"].set("1.5")
    app.plot(keep=True, xlim=(0, 5))          # 先把畫面放到最左邊
    app.goto_diff(1)
    xl3 = app.current_xlim()
    check(xl3[0] < 5 < xl3[1] and "差異 1/" in app.status_var.get(), f"下一個差異 → xlim {xl3} {app.status_var.get()[-12:]}")
    app.goto_diff(1)
    m2 = re.search(r"差異 (\d+)/", app.status_var.get())
    check(m2 and int(m2.group(1)) > 1, f"再下一個差異 → {app.status_var.get()[-12:]}")
    app.goto_diff(-1)
    m3 = re.search(r"差異 (\d+)/", app.status_var.get())
    check(m3 and m2 and int(m3.group(1)) < int(m2.group(1)), f"上一個差異 → {app.status_var.get()[-12:]}")
    app.show_all_x()


@step
def s6b_analyze_buttons():
    """分析分頁有訊號之後：6 顆啟用；突波抑制 開／關 在狀態列說結果、已是該狀態時只說明不塞 undo；
    GFSK 沒有 I/Q 配對不開空視窗；頻譜／GFSK 視窗的選項都有 tooltip、算完在自己的狀態列說範圍；
    差異導覽：全部顯示時「下一個」＝第 1 段、連按逐段、到底提示、「上一個」＝最後一段；關掉標示差異區間 → 兩顆變灰。"""
    ab = app._analyze_btns
    check(all(not b.instate(["disabled"]) for b in ab.values()), "有訊號且有差異：分析分頁 10 顆按鈕（含訊號分頁的錯誤率比對…）都啟用")
    si = app.find_signal("iq.csv;;adc i")
    sq = app.find_signal("iq.csv;;adc q")
    app.sig_tree.selection_set([f"s{si.uid}"])
    app.update()
    n_undo = len(app.undo)
    app.set_despike(True)                       # s5 已開且參數相同 → no-op
    check(app.status_var.get().startswith("突波抑制已經是開的：選取的 1 條") and len(app.undo) == n_undo and si.despike,
          f"已開著再按「開啟突波抑制」→ 狀態列說明、不重算、不塞 undo：{app.status_var.get()[:40]}")
    app.set_despike(False)
    check(app.status_var.get().startswith("突波抑制 關：選取的 1 條") and not si.despike, f"「停用突波抑制」→ 狀態列：{app.status_var.get()[:40]}")
    app.set_despike(False)
    check(app.status_var.get().startswith("突波抑制本來就沒開：選取的 1 條"), f"已關著再按「停用」→ 狀態列說明：{app.status_var.get()[:40]}")
    app.set_despike(True)
    check(app.status_var.get().startswith("突波抑制 開：選取的 1 條，共修正 3 點") and si.despike and si.spikes_fixed == 3,
          f"「開啟突波抑制」→ 狀態列說修了幾點：{app.status_var.get()[:60]}")
    # GFSK（2026-10-25 第 9 項起）：只選 1 條＝不是明確的一對 → 分析「目前 panel」的 I/Q，標題與狀態列寫是哪個 panel、哪兩條
    n_gw = len([w for w in app.winfo_children() if isinstance(w, sv.GfskWindow)])
    app._set_current_panel(si.panel)
    app.open_gfsk()
    app.update()
    gws = [w for w in app.winfo_children() if isinstance(w, sv.GfskWindow)]
    check(len(gws) == n_gw + 1 and app.status_var.get().startswith(f"已開啟 GFSK 視窗：P{si.panel}，I＝iq:adc i、Q＝iq:adc q")
          and f"P{si.panel}" in gws[-1].title(), f"選 1 條按 GFSK… → 分析目前 panel 的 I/Q、標題與狀態列寫出來：{app.status_var.get()[:50]}")
    gws[-1].destroy(); app.update()
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"])
    app.update()
    app.open_gfsk()
    app.update()
    gws = [w for w in app.winfo_children() if isinstance(w, sv.GfskWindow)]
    check(len(gws) == n_gw + 1 and app.status_var.get().startswith(f"已開啟 GFSK 視窗：清單選取（P{si.panel}），I＝iq:adc i、Q＝iq:adc q"),
          f"選 I、Q 兩條按 GFSK… → 用那兩條、狀態列寫「清單選取」：{app.status_var.get()[:50]}")
    gw = gws[-1]
    check(gw.v_status.get().startswith("已計算 1 組 I/Q") and len(gw.lines) == 1, f"GFSK 視窗狀態列說算了什麼、範圍從哪來：{gw.v_status.get()[:60]}")
    top = [c for c in gw.winfo_children() if isinstance(c, sv.ttk.Frame) and any(isinstance(x, sv.ttk.Entry) for x in c.winfo_children())][0]
    opts = [w for w in top.winfo_children() if not isinstance(w, sv.ttk.Label)]
    missing = _no_tooltip(opts)
    check(len(opts) == 5 and not missing, f"GFSK 視窗 IF／頻寬／I/Q 順序／taps／重新計算 都有 tooltip（缺：{missing}）")
    app.plot(keep=True, xlim=(5000.0, 5010.0))   # 主圖縮放到沒有訊號的地方 → 樣本不足：要說範圍怎麼來、怎麼重算
    gw.compute()
    check(len(gw.lines) == 0 and gw.v_status.get().startswith("已計算 0 組 I/Q")
          and "分析範圍＝主圖目前的 x 範圍（x 5000..5010 symbol）" in gw.v_msg.get() and "重新計算" in gw.v_msg.get(),
          f"主圖範圍外 → GFSK 視窗說明分析範圍與怎麼重算：{gw.v_msg.get()[-60:]}")
    app.show_all_x()
    gw.compute()
    check(len(gw.lines) == 1 and gw.v_status.get().startswith("已計算 1 組 I/Q"), "主圖全部顯示後「重新計算」→ 鑑頻輸出回來")
    gw.destroy()
    app.open_spectrum()
    app.update()
    sw = [w for w in app.winfo_children() if isinstance(w, sv.SpectrumWindow)][-1]
    check(app.status_var.get().startswith("已開啟頻譜視窗：選取的 2 條訊號"), f"按「頻譜…」→ 狀態列：{app.status_var.get()[:40]}")
    check(sw.v_status.get().startswith("已計算 2 條頻譜；分析範圍 x "), f"頻譜視窗狀態列說算了幾條、範圍：{sw.v_status.get()[:60]}")
    opts = strip_controls(sw.strip)
    missing = _no_tooltip(opts)
    check(len(opts) >= 40 and not missing, f"頻譜視窗工具列 {len(opts)} 個按鈕／勾選／下拉／輸入格都有 tooltip（缺：{missing}）")
    app.plot(keep=True, xlim=(5000.0, 5010.0))   # 主圖縮放到沒有訊號的地方 → 全部略過：要說範圍怎麼來、怎麼重算
    sw.compute()
    check(len(sw.fig.axes) == 0 and "分析範圍＝主圖目前的 x 範圍（x 5000..5010 symbol）" in sw.v_msg.get() and "重新計算" in sw.v_msg.get(),
          f"主圖範圍外 → 頻譜視窗說明分析範圍與怎麼重算：{sw.v_msg.get()[-60:]}")
    app.show_all_x()
    sw.compute()
    check(len(sw.fig.axes) == 1 and len(sw.lines) == 2, "主圖全部顯示後「重新計算」→ 2 條頻譜回來")
    sw.destroy()
    app.sig_tree.selection_set([])
    app.update()
    # 差異導覽
    app.show_all_x()
    app.goto_diff(1)
    m = re.match(r"差異 1/(\d+)：P(\d+)，x [-\d.]+\.\.[-\d.]+ symbol（寬 [\d.]+） ｜ ", app.status_var.get())
    check(m, f"全部顯示按「下一個差異」→ 第 1 段，狀態列開頭就是「差異 1/n：P? x=…」：{app.status_var.get()[:60]}")
    n = int(m.group(1)) if m else 0
    xl1 = app.current_xlim()
    app.goto_diff(1)
    check(app.status_var.get().startswith("差異 2/") and app.current_xlim() != xl1, "連按「下一個差異」→ 2/n、畫面移動")
    app.goto_diff(-1)
    check(app.status_var.get().startswith("差異 1/") and app.current_xlim() == xl1, "「上一個差異」→ 回到 1/n（同一個畫面）")
    app.goto_diff(-1)
    check(app.status_var.get().startswith("沒有更多差異（往前）：已經是第 1 段"), f"第 1 段再按上一個 → 到底提示：{app.status_var.get()[:40]}")
    app.show_all_x()
    app.goto_diff(-1)
    check(app.status_var.get().startswith(f"差異 {n}/{n}："), f"全部顯示按「上一個差異」→ 最後一段 {n}/{n}：{app.status_var.get()[:30]}")
    app.goto_diff(1)
    check(app.status_var.get().startswith("沒有更多差異（往後）：已經是最後一段"), f"最後一段再按下一個 → 到底提示：{app.status_var.get()[:40]}")
    app.v["diff"].set(False)
    app.plot()
    check(ab["diff_prev"].instate(["disabled"]) and ab["diff_next"].instate(["disabled"]) and not ab["spectrum"].instate(["disabled"]),
          "關掉「標示差異區間」→ 上一個／下一個差異 disabled，其他照常")
    app.goto_diff(1)
    check(app.status_var.get().startswith("沒有差異區間"), "關著時呼叫 goto_diff → 狀態列說要先勾「標示差異區間」")
    app.v["diff"].set(True)
    app.plot()
    check(not ab["diff_prev"].instate(["disabled"]) and not ab["diff_next"].instate(["disabled"]), "打開「標示差異區間」→ 兩顆恢復啟用")
    app.show_all_x()


@step
def s7_cursor():
    from matplotlib.backend_bases import MouseEvent
    ax = app.render_info["axes"][0]
    xdata = 20.0
    px, py = ax.transData.transform((xdata, (ax.get_ylim()[0] + ax.get_ylim()[1]) / 2))
    ev = MouseEvent("motion_notify_event", app.canvas, px, py)
    app.canvas.draw()
    app._on_motion(ev)
    txt = app._cursor_items[0][2].get_text()
    check(txt.startswith("≠ x = 20") or txt.startswith("x = 20"), f"十字游標文字：{txt.splitlines()[0]!r}")
    check("adc i" in txt and "adc q" in txt, "游標顯示每條訊號的值")
    check(txt.startswith("≠"), "I/Q 值不同 → 前面加 ≠")


def toolbar_order(pt):
    """工具列實際的左→右順序（pack_slaves；winfo_children 是建立順序，不能用）：按鈕回 key、分隔線回 "|"。"""
    keys = {str(b): k for k, b in pt.buttons.items()}
    return [keys.get(str(c), "|" if c.winfo_class() == "TSeparator" else "?") for c in pt.left.pack_slaves()]


@step
def s8_windows():
    sigs = [app.find_signal("iq.csv;;adc i"), app.find_signal("iq.csv;;adc q")]
    app.spec_defaults["iq"] = True
    order = toolbar_order(app.plot_toolbar)
    check(order == ["save", "clip", "clipvec", "tips", "pan", "zoom", "zoomout", "|", "home", "|", "back", "forward", "|", "cursor"],
          f"主畫面工具列順序照 MATLAB axtoolbar（存檔／複製影像／複製向量圖 → 資料提示 → 平移 → 放大 → 還原視圖；{order}）")
    w = sv.SpectrumWindow(app, sigs)
    app.update()
    order = toolbar_order(w.plot_toolbar)
    check(order == ["save", "tips", "pan", "zoom", "zoomout", "|", "home", "|", "back", "forward"], f"頻譜視窗工具列順序（{order}）")
    ax = w.fig.axes[0]
    ln = ax.get_lines()[0]
    fx, fy = ln.get_xdata(), ln.get_ydata()
    peak = fx[int(np.argmax(fy))]
    check(abs(peak - 1.77778e6) < 400e3, f"頻譜 I/Q 複數峰值 {peak / 1e6:.3f} MHz（預期 1.78 ± 0.25，GFSK 兩個 lobe）")
    w.v_iq.set(False)
    w.v_sep.set(True)
    w.v_logf.set(True)
    w.compute()
    check(len(w.fig.axes) == 2, "頻譜分開畫 → 2 張")
    w.ia.host.status("STATUS-TEST")
    check(w.v_status.get() == "STATUS-TEST" and w.plot_toolbar.msg_var.get() != "STATUS-TEST", "頻譜視窗的狀態訊息寫到自己的狀態列、不佔座標欄")
    check(w.v_tips.get() and w.ia.tips_enabled and w.ia.wheel_enabled == bool(app.v["wheel_zoom"].get()), "頻譜視窗：資料提示預設開、滾輪縮放跟主畫面的開關")
    w.ia.add_tip(1, 50)
    check(len(w.ia.model.tips) == 1 and len(w.ia.tip_artists) == 1, "頻譜視窗釘資料提示")
    app.v["theme"].set("light")
    app.update()
    app.update()
    check(len(w.ia.model.tips) == 1 and len(w.ia.tip_artists) == 1 and w.ia.model.tips[0].index == 50,
          f"切主題後頻譜視窗的資料提示留在同一點（tips={len(w.ia.model.tips)}, artists={len(w.ia.tip_artists)}）")
    w.compute()
    app.update()
    check(len(w.ia.model.tips) == 0, "重新計算 → 提示清掉（資料變了）")
    app.v["theme"].set("dark")
    app.update()
    tk_key(w, "w", mods="Control")
    app.update()
    check(not w.winfo_exists(), "Ctrl＋W 關閉頻譜視窗（MATLAB File > Close）")
    gw = sv.GfskWindow(app, sigs)
    app.update()
    order = toolbar_order(gw.plot_toolbar)
    check(order == ["save", "tips", "pan", "zoom", "zoomout", "|", "home", "|", "back", "forward"], f"GFSK 視窗工具列順序（{order}）")
    check(len(gw.pairs) == 1 and gw.pairs[0][0].column == "adc i", "GFSK 自動配對 adc i / adc q")
    ln = gw.fig.axes[0].get_lines()[0]
    f = ln.get_ydata()
    mid = f[200:-200]
    p90 = float(np.percentile(np.abs(mid), 90))
    check(150e3 < p90 < 350e3 and mid.min() < -150e3 and mid.max() > 150e3,
          f"GFSK 鑑頻輸出 ±250 kHz（|f| 90 百分位 {p90 / 1e3:.0f} kHz，範圍 {mid.min() / 1e3:.0f}..{mid.max() / 1e3:.0f} kHz）")
    gw.v_taps.set("40")
    gw.compute()
    check(gw.v_taps.get() == "41" and app.gfsk_defaults["taps"] == 41, "taps 強制奇數並存到 gfsk_defaults")
    gw.fig.savefig(os.path.join(OUT, "gfsk.png"), dpi=80)
    tk_key(gw, "w", mods="Command" if sys.platform == "darwin" else "Control")
    app.update()
    check(not gw.winfo_exists(), "⌘W（macOS）／Ctrl＋W 關閉 GFSK 視窗")
    hw = sv.HelpWindow(app)
    app.update()
    check(hw.toc.size() > 3 and len(hw.text.get("1.0", "end")) > 500, f"說明視窗：目錄 {hw.toc.size()} 項")
    hw.toc.selection_set(2)
    hw._on_toc()
    hw.destroy()
    dw = sv.DiagWindow(app)
    app.update()
    txt = dw.text.get("1.0", "end")
    check("numpy" in txt and "動作記錄" in txt and "iq.csv;;adc i" in txt, "診斷視窗內容")
    dw.copy()
    check(app.clipboard_get().startswith(sv.APP_NAME), "複製到剪貼板")
    dw.destroy()


@step
def s10_theme():
    """MATLAB 主題：切 light／dark、圖風格跟著換、toolstrip／面板存在、設定往返。"""
    T = sv.T
    check(T.current() is not None and T.current().name == "dark" and app.v["theme"].get() == "dark", "預設 dark 主題（使用者的 MATLAB 桌面主題）")
    check(set(app.strip.tabs) == {"home", "signal", "preprocess", "style", "analyze", "measure", "view", "export"} and app.strip.current == "home",
          "toolstrip 的分頁（第三批加「前處理」）")
    check(all(hasattr(app, n) for n in ("folder_panel", "plot_panel", "sig_panel", "prop_panel")), "資料夾／圖／已繪訊號／訊號屬性 四個面板")
    check(app.toolbar is app.plot_toolbar.nav and hasattr(app.toolbar, "mode"), "圖工具列包著 matplotlib 的 NavigationToolbar2Tk")
    app.v["style"].set("matlab-dark")
    app.plot()
    fc = tuple(round(c, 3) for c in app.fig.get_facecolor()[:3])
    check(fc == (0.129, 0.129, 0.129), f"dark 主題的圖底 #212121（{fc}）")
    app.v["theme"].set("light")
    app.update()
    fc = tuple(round(c, 3) for c in app.fig.get_facecolor()[:3])
    check(T.current().name == "light" and app.v["style"].get() == "matlab" and fc == (0.961, 0.961, 0.961)
          and app.v_theme_label.get() == "淺色", f"切到 light：ttk 主題、圖風格 matlab、圖底 #f5f5f5（{fc}）")
    check(str(app.plot_scroll.cget("bg")) == "#f5f5f5", "畫布底色跟主題")
    tags_bg = app.sig_tree.tag_configure("p0", "background")
    check(str(tags_bg) == "#ffffff", f"清單交錯底色跟主題（{tags_bg}）")
    d = app.dump_settings()
    check(d["view"]["theme"] == "light" and d["view"]["style"] == "matlab", "設定檔記錄 theme／style")
    app.v_style_label.set("matplotlib")
    app._on_style_combo()
    check(app.v["style"].get() == "default" and app.fig.get_facecolor()[0] == 1.0, "風格下拉：matplotlib → default 白底")
    app.v["theme"].set("dark")
    app.update()
    check(T.current().name == "dark" and app.v["style"].get() == "default", "切回 dark：自訂的 default 風格不被改掉")
    app.v["style"].set("matlab-dark")
    app.plot()
    d["view"]["theme"] = "light"
    app.apply_settings(d, quiet=True)
    check(T.current().name == "light" and app.v["theme"].get() == "light", "apply_settings 帶 theme=light → 套用")
    app.v["theme"].set("dark")
    app.update()
    check(T.current().name == "dark", "再切回 dark 給後面的步驟")
    app.v["theme"].set("light"); app.update(); app.v["theme"].set("dark"); app.update()
    light_theme = T._THEMES[(T._interp(app), "light")]
    names = set(app.tk.call("image", "names"))
    check(len(light_theme.images) > 20 and all(str(im) in names for im in light_theme.images),
          f"來回切換後 light 主題的 {len(light_theme.images)} 張元素圖片都還在（Theme 物件被快取、不會被回收）")
    sb = app.sig_tree.master.winfo_children()
    sbs = [w for w in sb if w.winfo_class() == "TScrollbar"]
    check(sbs and sbs[0].winfo_reqwidth() >= 8, f"捲軸有寬度（{[w.winfo_reqwidth() for w in sbs]}）")
    app.folder_panel.collapse(True)
    check(app.folder_panel.collapsed and not app.folder_panel.body.winfo_manager(), "面板收合")
    app.folder_panel.collapse(False)
    app.sig_panel.select(True)
    check(app.sig_panel._selected and not app.folder_panel._selected and str(app.sig_panel.header.cget("style")) == "PanelTitleSel.TFrame",
          "點面板標題 → 只有它變成被選面板（藍底）")
    tb = app.plot_toolbar
    tb._pan()
    check(str(app.toolbar.mode) == "pan/zoom" and tb.v_pan.get() and not tb.v_zoom.get(), "工具列平移：mode 同步")
    tb._zoom()
    check(str(app.toolbar.mode) == "zoom rect" and tb.v_zoom.get() and not tb.v_pan.get(), "工具列框選放大：mode 同步")
    tb._zoom()
    check(str(app.toolbar.mode) == "" and not tb.v_zoom.get(), "再按一次關掉")


@step
def s10b_matlab_feedback():
    """主畫面也照 MATLAB：重畫不閃等待游標；放大模式 crosshair、扁的框畫 #268cdd 的 15 px 帶子且只縮 x；平移模式張開的手；關掉回箭頭。"""
    app.sig_tree.selection_set([])
    app.show_all_x()
    app.update()
    cv = app.canvas
    wd = cv.get_tk_widget()
    calls = []
    orig = cv.set_cursor
    cv.set_cursor = lambda c: (calls.append(c), orig(c))
    time.sleep(1.1)
    app.plot()
    cv.draw()
    app.update()
    cv.set_cursor = orig
    check(not calls, f"主畫面隔 1 秒後重畫不會閃等待游標（{calls}）")
    if HL:
        check(True, "（無桌面：主畫面游標與框選帶子的 Tk 事件測試略過）")
        return
    aqua = str(app.tk.call("tk", "windowingsystem")) == "aqua"
    ax = app.fig.axes[0]
    bb = ax.bbox
    h = cv.get_width_height(physical=True)[1]
    cx, cy = int((bb.x0 + bb.x1) / 2), int(h - (bb.y0 + bb.y1) / 2)

    def ev(seq, x, y, **kw):
        wd.event_generate(seq, x=x, y=y, rootx=wd.winfo_rootx() + x, rooty=wd.winfo_rooty() + y, when="now", **kw)

    items = []
    tb = app.plot_toolbar
    tb._zoom()
    app.update()
    ev("<Motion>", cx, cy)
    app.update()
    check(wd.cget("cursor") == "crosshair", f"主畫面放大模式的游標＝crosshair（{wd.cget('cursor')}）")
    xl0, yl0 = ax.get_xlim(), ax.get_ylim()
    ev("<ButtonPress-1>", cx - 150, cy)
    app.update()
    for i in (1, 2, 3):
        ev("<Motion>", cx - 150 + 100 * i, cy + 2 * i, state=0x100)
        app.update()
        if i == 2:
            items[:] = [(wd.type(k), wd.itemcget(k, "outline" if wd.type(k) == "rectangle" else "fill")) for k in wd.find_all() if wd.type(k) != "image" and "dsv_panel_ui" not in wd.gettags(k)]
    ev("<ButtonRelease-1>", cx + 150, cy + 6, state=0x100)
    app.update()
    check([t for t, _ in items] == ["line", "line", "line"] and all(c == "#268cdd" for _, c in items), f"主畫面：扁的框 → #268cdd 的 15 px 帶子（{items}）")
    check(ax.get_ylim() == yl0 and ax.get_xlim()[1] - ax.get_xlim()[0] < 0.5 * (xl0[1] - xl0[0]), "主畫面：扁的框只縮 x")
    tb._zoom()
    app.update()
    tb._pan()
    app.update()
    ev("<Motion>", cx + 1, cy)
    app.update()
    check(wd.cget("cursor") == ("openhand" if aqua else "hand2"), f"主畫面平移模式的游標＝張開的手（{wd.cget('cursor')}）")
    tb._pan()
    app.update()
    ev("<Motion>", cx + 2, cy)
    app.update()
    check(wd.cget("cursor") == "arrow", f"主畫面模式關掉 → 箭頭（{wd.cget('cursor')}）")
    app.show_all_x()
    app.update()


@step
def s11_scroll_fit_cursor():
    """多 panel：座標區外滾輪＝捲動畫布、座標區內＝縮放；「全部放進視窗」把全部 panel 塞進可見高度；十字游標開關不整張重畫。"""
    app.v["fit_panels"].set(False)
    app.v["panel_height"].set("3")                 # 每張 3 in：4 張就 1290 px，一定比可見範圍高
    app.plot()
    app.update()
    npan = len({s.panel for s in app.signals if s.visible})
    w = app.canvas.get_tk_widget()
    H = app.canvas.get_width_height(physical=True)[1]
    vis = app.plot_scroll.winfo_height()
    check(npan >= 4 and H > vis + 50, f"{npan} 個 panel × 3 in 時畫布 {H}px 比可見 {vis}px 高（可捲動）")
    y0 = app.plot_scroll.yview()
    ax0 = app.fig.axes[0]
    bb = ax0.bbox
    tx, ty = int((bb.x0 + bb.x1) / 2), max(2, int(H - bb.y1) // 2)        # 第一張圖上緣以上的留白（座標區外）
    rx, ry = w.winfo_rootx() + tx, w.winfo_rooty() + ty
    if _w14_wheel_hit(True):                       # W-A：Windows 安靜模式的命中測試換成 Tk 幾何（Mac 不換）
        _w14_geo_checks()
    try:
        over = app.winfo_containing(rx, ry)
        app.plot_scroll.event_generate("<Enter>", when="now")            # 滑鼠進到右側畫布才掛上滾輪捲動（照真實 Enter/Leave 路徑）
        app.update()
        w.event_generate("<MouseWheel>", delta=_w14_wheel_delta(-1), x=tx, y=ty, rootx=rx, rooty=ry, when="now")
        app.update()
        y1 = app.plot_scroll.yview()
        check(HL or (over is w and y1[0] > y0[0]), f"座標區外滾輪 → 捲動畫布（yview {y0[0]:.3f} → {y1[0]:.3f}；over={over is w} scrollable={app._plot_scrollable()} "
                                          f"bound={bool(app.plot_scroll.bind_all('<MouseWheel>'))} over_axes={app._pointer_over_axes(type('E', (), {'x_root': rx, 'y_root': ry})())}）")
        app.plot_scroll.yview_moveto(0)
        app.update()
        ax0 = app.fig.axes[0]
        bb = ax0.bbox
        xl0 = ax0.get_xlim()
        cx, cy = int((bb.x0 + bb.x1) / 2), int(H - (bb.y0 + bb.y1) / 2)
        rx, ry = w.winfo_rootx() + cx, w.winfo_rooty() + cy
        w.event_generate("<MouseWheel>", delta=_w14_wheel_delta(-1), x=cx, y=cy, rootx=rx, rooty=ry, when="now")
        app.update()
        check(HL or (app.plot_scroll.yview()[0] > 0 and ax0.get_xlim() == xl0), f"放不下時座標區內的滾輪也是捲動、不縮放（yview {app.plot_scroll.yview()[0]:.3f}）")
        app.plot_scroll.yview_moveto(0)
        app.update()
        ax0 = app.fig.axes[0]
        xl0 = ax0.get_xlim()
        w.event_generate("<MouseWheel>", delta=_w14_wheel_delta(1), x=cx, y=cy, rootx=rx, rooty=ry, state=0x8 if sv.IS_MAC else 0x4, when="now")
        app.update()
        check(HL or (app.plot_scroll.yview()[0] == 0 and ax0.get_xlim() != xl0), "放不下時 ⌘／Ctrl＋滾輪 → 縮放、不捲動")
        app.plot_scroll.event_generate("<Leave>", when="now")
        app.show_all_x()
        app.v["fit_panels"].set(True)
        app.plot()
        app.update()
        H2 = app.canvas.get_width_height(physical=True)[1]
        check(abs(H2 - app.plot_scroll.winfo_height()) <= 2 and app.plot_scroll.yview() == (0.0, 1.0),
              f"全部放進視窗：畫布高 {H2}px ＝ 可見 {app.plot_scroll.winfo_height()}px、不用捲動")
        app.plot_scroll.event_generate("<Enter>", when="now")
        ax0 = app.fig.axes[0]
        bb = ax0.bbox
        H = app.canvas.get_width_height(physical=True)[1]
        cx, cy = int((bb.x0 + bb.x1) / 2), int(H - (bb.y0 + bb.y1) / 2)
        xl0 = ax0.get_xlim()
        w.event_generate("<MouseWheel>", delta=_w14_wheel_delta(1), x=cx, y=cy, rootx=w.winfo_rootx() + cx, rooty=w.winfo_rooty() + cy, when="now")
        app.update()
        check(HL or ax0.get_xlim() != xl0, "放得下時座標區內的滾輪 → 縮放（MATLAB）")
        app.plot_scroll.event_generate("<Leave>", when="now")
    finally:
        _w14_wheel_hit(False)
    app.show_all_x()
    app.v["fit_panels"].set(False)
    app.v["panel_height"].set("1.5")
    app.plot()
    app.update()
    calls = []
    orig = app.plot
    app.plot = lambda *a, **k: (calls.append(1), orig(*a, **k))
    was = app.v["cursor"].get()
    app.v["cursor"].set(not was)
    app._toggle_cursor()
    app.update()
    n_items = len(app._cursor_items)
    app.v["cursor"].set(was)
    app._toggle_cursor()
    app.update()
    app.plot = orig
    check(not calls and (n_items == 0) == was and len(app._cursor_items) == (len(app.fig.axes) if was else 0),
          f"十字游標開關不整張重畫（plot 呼叫 {len(calls)} 次；游標 artist {n_items} → {len(app._cursor_items)}）")


def _legacy_layout(d):
    """測試用：排成舊的三欄版面（左 資料夾｜中 圖｜右 已繪訊號、訊號屬性，量測／游標量測隱藏在右欄）。"""
    d.reset()
    d.hide("props", False)
    d.move("sigs", "right"); d.move("props", "right")
    for k in ("meas", "cursors"):
        d.move(k, "right")
    d.order["right"] = ["sigs", "props", "meas", "cursors"]
    d._rebuild()
    app.update()


@step
def s12_layout():
    """可調版面：面板搬欄、排序、隱藏、最大化、欄寬，版面寫進設定檔並可還原、恢復預設。"""
    d = app.dock
    check(d.order["left"] == ["folder", "sigs", "props"] and d.order["center"] == ["plot", "meas"] and d.order["right"] == ["cursors"]
          and d.hidden == {"props", "meas", "cursors"} and not app.v_panel["meas"].get() and not app.v_panel["cursors"].get(),
          "預設版面：左欄 資料夾、已繪訊號（訊號屬性隱藏）｜右邊整個是圖（量測在圖的下方、游標量測在右欄，預設都隱藏）")
    _legacy_layout(d)                                   # 下面的搬欄／排序檢查以舊的三欄配置（右欄 已繪訊號、訊號屬性）為起點
    d.move("sigs", "left")
    app.update()
    check(d.column_of("sigs") == "left" and (HL or app.sig_panel.winfo_ismapped()) and d.order["left"] == ["folder", "sigs"], "已繪訊號移到左欄")
    d.shift("sigs", -1)
    app.update()
    check(d.order["left"] == ["sigs", "folder"], "上移")
    d.move("props", "center", 0)
    app.update()
    check(d.order["center"] == ["plot", "props"] and (HL or app.prop_panel.winfo_ismapped()), "訊號屬性移到圖下方（圖固定在中欄最上面）")
    d.hide("folder")
    app.update()
    check("folder" in d.hidden and (HL or not (HL or app.folder_panel.winfo_ismapped())) and not app.v_panel["folder"].get(), "隱藏資料夾（檢視分頁的勾選同步）")
    lay = app.dump_settings()["layout"]
    check(lay["columns"]["left"] == ["sigs", "folder"] and lay["columns"]["center"] == ["plot", "props"] and "folder" in lay["hidden"],
          "設定檔記錄版面（隱藏的面板也記著它原本的欄位）")
    d.maximize("plot")
    app.update()
    check(d.max_key == "plot" and app.v_plot_max.get() and (HL or not (HL or app.sig_panel.winfo_ismapped())) and (HL or app.plot_panel.winfo_ismapped()), "圖最大化（只剩圖）")
    d.toggle_max("plot")
    app.update()
    check(d.max_key is None and (HL or app.sig_panel.winfo_ismapped()) and "folder" in d.hidden and not app.v_plot_max.get(), "還原回最大化前的版面（資料夾仍隱藏）")
    d.reset()
    app.update()
    check(d.column_of("sigs") == "left" and d.column_of("folder") == "left" and d.hidden == {"props", "meas", "cursors"} and app.v_panel["folder"].get()
          and (HL or app.folder_panel.winfo_ismapped()), "恢復預設版面（已繪訊號回左欄；訊號屬性、量測面板仍是預設的隱藏）")
    _legacy_layout(d)
    old_lay = dict(lay, columns={c: [k for k in v if k not in ("meas", "cursors")] for c, v in lay["columns"].items()},
                   hidden=[k for k in lay["hidden"] if k not in ("meas", "cursors")])
    d.apply(old_lay)
    app.update()
    check("meas" in d.hidden and d.column_of("meas") == "center" and "cursors" in d.hidden and d.column_of("cursors") == "right"
          and "folder" in d.hidden, "舊版存的版面（沒有量測／游標量測面板）→ 照預設隱藏、放回預設的欄（量測：圖的下方；游標量測：右欄）")
    d.apply(lay)
    app.update()
    check(d.column_of("sigs") == "left" and d.order["center"] == ["plot", "props"] and "folder" in d.hidden, "apply(layout) 還原存下的版面")
    _legacy_layout(d)                                   # 三欄都看得到才有兩條 sash
    d.h.sashpos(0, 222)
    app.update()
    lay2 = d.layout()
    check(lay2["sash"]["h_cols"] == ["left", "center", "right"] and abs(lay2["sash"]["h"][0] - 222) <= 2, f"欄寬（sash）記進版面（{lay2['sash']['h']}）")
    d.h.sashpos(0, 300)
    app.update()
    d.apply(lay2)
    for _ in range(12):                              # 分隔線位置要等 ttk 排版後才吃得下（最多重試 10 次、每次 100 ms）
        app.update()
        if d._pending_sash is None:
            break
        time.sleep(0.1)
    check(abs(d.h.sashpos(0) - 222) <= 2, f"apply(layout) 還原欄寬（{d.h.sashpos(0)}）")
    app.v_panel["sigs"].set(False)
    app._toggle_panel("sigs")
    app.update()
    check("sigs" in d.hidden and (HL or not (HL or app.sig_panel.winfo_ismapped())), "檢視分頁取消勾選 → 隱藏面板")
    app.v_panel["sigs"].set(True)
    app._toggle_panel("sigs")
    app.update()
    check("sigs" not in d.hidden and (HL or app.sig_panel.winfo_ismapped()), "再勾選 → 顯示面板")
    _legacy_layout(d)                                   # 拖曳檢查以舊三欄版面為起點（已繪訊號、訊號屬性在右欄）

    def drag(panel, tx, ty, release=True):
        lab = panel.label
        sx, sy = lab.winfo_rootx() + 5, lab.winfo_rooty() + 5
        lab.event_generate("<ButtonPress-1>", x=5, y=5, rootx=sx, rooty=sy, when="now")
        lab.event_generate("<B1-Motion>", x=tx - lab.winfo_rootx(), y=ty - lab.winfo_rooty(), rootx=tx, rooty=ty, when="now")
        app.update()
        if release:
            lab.event_generate("<ButtonRelease-1>", x=tx - lab.winfo_rootx(), y=ty - lab.winfo_rooty(), rootx=tx, rooty=ty, when="now")
            app.update()

    if HL:
        check(True, "（無桌面：面板拖曳的 Tk 事件測試略過）")
        return
    fp = app.folder_panel
    drag(app.sig_panel, fp.winfo_rootx() + fp.winfo_width() // 2, fp.winfo_rooty() + fp.winfo_height() - 8, release=False)
    check(d._drag is not None and d._drag["on"] and d._drag["target"] == ("left", None) and d._ind is not None and d._ind.winfo_ismapped(),
          f"拖曳標題列到左欄底部：拖曳中、指示線顯示（target={d._drag and d._drag['target']}）")
    lab = app.sig_panel.label
    tx, ty = fp.winfo_rootx() + fp.winfo_width() // 2, fp.winfo_rooty() + fp.winfo_height() - 8
    lab.event_generate("<ButtonRelease-1>", x=tx - lab.winfo_rootx(), y=ty - lab.winfo_rooty(), rootx=tx, rooty=ty, when="now")
    app.update()
    check(d.order["left"] == ["folder", "sigs"] and (HL or app.sig_panel.winfo_ismapped()) and not d._ind.winfo_ismapped(), "放開 → 已繪訊號搬到左欄資料夾下面、指示線消失")
    pp = app.prop_panel
    drag(app.sig_panel, pp.winfo_rootx() + 20, pp.winfo_rooty() + 6)
    check([k for k in d.order["right"] if k not in ("meas", "cursors")] == ["sigs", "props"] and d.order["left"] == ["folder"], "拖到訊號屬性上緣 → 插在它前面（回右欄）")
    pl = app.plot_panel
    drag(app.sig_panel, pl.winfo_rootx() + pl.winfo_width() // 2, pl.winfo_rooty() + pl.winfo_height() - 8)
    check(d.order["center"] == ["plot", "sigs"], "拖到圖下方 → 中欄、圖仍固定在最上面")
    drag(app.folder_panel, pp.winfo_rootx() + 20, pp.winfo_rooty() + pp.winfo_height() - 8)
    check([k for k in d.order["right"] if k not in ("meas", "cursors")] == ["props", "folder"] and "left" not in d.visible_columns(), "資料夾拖到右欄底部 → 左欄變空、消失")
    drag(app.folder_panel, app.dock.winfo_rootx() + 10, app.dock.winfo_rooty() + app.dock.winfo_height() // 2)
    check(d.order["left"] == ["folder"] and "left" in d.visible_columns(), "拖到 Dock 左邊緣 → 空的左欄重新出現")
    before = d.layout()["columns"]
    drag(app.sig_panel, fp.winfo_rootx() + fp.winfo_width() // 2, fp.winfo_rooty() + fp.winfo_height() - 8, release=False)
    tk_key(app, "Escape")
    app.update()
    lab = app.sig_panel.label
    lab.event_generate("<ButtonRelease-1>", x=5, y=5, rootx=lab.winfo_rootx() + 5, rooty=lab.winfo_rooty() + 5, when="now")
    app.update()
    check(d.layout()["columns"] == before and d._drag is None and not d._ind.winfo_ismapped(), "拖曳中按 Esc → 取消、版面不變")
    d.reset()
    app.update()


@step
def s13_mat():
    """MATLAB .mat：資料夾樹列出變數、直接加入、匯入對話框，SPS 由 t 向量算出。"""
    if not HAVE_MAT:
        check(True, "沒有 samples/mat/demo_v6.mat，略過 .mat 測試")
        return
    path = os.path.join(ROOT, "mat", "demo_v6.mat")
    node = next((n for n in app.tree_map.values() if n.get("name") == "demo_v6.mat"), None)
    cols = [n["column"] for n in app.tree_map.values() if n["kind"] == "column" and n.get("path") == path]
    check(node is not None and node["kind"] == "csv" and sorted(cols) == ["adc", "clk", "imag(iq)", "real(iq)"],
          f"資料夾樹：demo_v6.mat 展開成 4 個變數（時間向量 t 不列）（{cols}）")
    n0 = len(app.signals)
    app.add_csv_columns_direct(path, ["real(iq)", "imag(iq)"])
    app.refresh_list()
    app.plot()
    sigs = [s for s in app.signals if s.path == path]
    check(len(sigs) == 2 and all(len(s.get_data()) == 4000 for s in sigs) and all(abs(s.sps - 32.0) < 1e-6 for s in sigs)
          and sigs[0].detected == "DEC", f"直接加入 .mat 變數：4000 點、SPS = 32 MHz ÷ 1 Msym/s = 32（{[s.sps for s in sigs]}）")
    table = sv.get_csv_table(path)
    dlg = sv.CsvImportDialog(app, path, table, ["clk"])
    app.update()
    fs_pre = sv.parse_si(dlg.v_fs.get()) or 0
    check(dlg.rows["clk"]["add"] and not dlg.rows["adc"]["add"] and abs(fs_pre - 32e6) < 1,
          f"匯入對話框認得 .mat：預選 clk、Sample rate 由 t 向量預填 {dlg.v_fs.get()}")
    dlg._on_add()
    app.update()
    check(any(s.column == "clk" and s.path == path for s in app.signals), "對話框加入 clk")
    app.signals = [s for s in app.signals if s.path != path]
    app.refresh_list()
    app.plot()
    check(len(app.signals) == n0, "清掉 .mat 訊號、回到原本狀態")


def _s14_prereq():
    """只跑 s14（DSV_TEST_ONLY=s14）時清單是空的：自己建前提——iq.csv 的兩欄（一個 panel）＋ digital/clk.txt（另一個 panel），
    和完整流程跑到這裡時一樣至少有兩個 panel；完整流程（前面的步驟已經加了好幾個 panel）不動（0.9.13 D10）。"""
    if len({s.panel for s in app.signals}) >= 2:
        return
    app.add_csv_columns_direct(os.path.join(ROOT, "iq.csv"), None)
    app.add_text_signal(os.path.join(ROOT, "digital", "clk.txt"))
    app.refresh_list(); app.plot(); app.update()
    check(len({s.panel for s in app.signals}) >= 2, f"s14 單獨跑：自己建前提（{[(s.key, s.panel) for s in app.signals]}）")


@step
def s14_copy_paste_panel():
    """像 MATLAB：選訊號 ⌘C → 點目標 panel → ⌘V 貼到那個 panel；⌘X 剪下＝搬；再貼一次＝再一份（照 MATLAB 不檢查重複，第 13 項）；右鍵貼上；Undo。
    用 DSV_TEST_ONLY=s14 單獨跑也要能過（_s14_prereq 自己建前提，0.9.13 D10）。"""
    _s14_prereq()
    app.dock.reset()
    app.v["panel_height"].set("1.5")
    app.plot()
    app.update()
    sigs = sorted(app.signals, key=lambda s: s.panel)
    src = sigs[-1]                                   # 最後一個 panel 的訊號
    target_p = sigs[0].panel
    n0 = len(app.signals)
    app.sig_tree.selection_set([f"s{src.uid}"])
    app._on_list_select()
    app.copy_signals()
    check(len(app._sig_clip) == 1 and app._sig_clip[0]["key"] == src.key and "Ctrl+V" in app.status_var.get(), "⌘C：訊號參數進剪貼簿、狀態列說明怎麼貼")
    info = app.render_info
    ax_t = info["axes"][info["panels"].index(target_p)]
    app.canvas.draw()
    bb = ax_t.bbox
    tk_click(app.canvas, (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2)   # 點目標 panel 的空白處（tk_click 吃 matplotlib 像素座標）
    if HL:
        app._set_current_panel(target_p)
    check(app._current_panel == target_p and f"P{target_p}" in app.status_var.get(), f"點 P{target_p} 的座標區 → 目前 panel（狀態列提示可貼上）")
    app.paste_signals()
    app.update()
    new = [s for s in app.signals if s.panel == target_p and s.path == src.path and s.column == src.column]
    check(len(app.signals) == n0 + 1 and len(new) == 1 and new[0].key != src.key and new[0].label == src.label
          and new[0].uid != src.uid and len(new[0].get_data()) == len(src.get_data()),
          f"⌘V → 複製一份到 P{target_p}（新 key {new[0].key if new else None}、同名、同資料）")
    app.paste_signals()
    app.update()
    new2 = [s for s in app.signals if s.panel == target_p and s.path == src.path and s.column == src.column]
    k2 = [s.key for s in new2]
    check(len(app.signals) == n0 + 2 and len(new2) == 2 and k2 == [src.key + "#2", src.key + "#3"]
          and app.status_var.get() == f"已貼上 1 條訊號到 P{target_p}",
          f"再貼一次：照 MATLAB 再貼一份、不檢查重複，編號往下加（{k2}；第 13 項，以前略過、只寫「已經有這些訊號，沒有貼上」）")
    app.undo_action()
    app.update()
    check(len(app.signals) == n0 + 1 and [s.key for s in app.signals if s.panel == target_p and s.column == src.column and s.path == src.path] == [src.key + "#2"],
          "Ctrl+Z → 第二份拿掉、第一份還在")
    app.undo_action()
    app.update()
    check(len(app.signals) == n0 and not any(s.key == new[0].key for s in app.signals), "Ctrl+Z → 貼上的那份拿掉")
    # 剪下 → 貼到 P1 等於搬過去
    app.sig_tree.selection_set([f"s{src.uid}"])
    app._on_list_select()
    app.cut_signals()
    app.update()
    check(len(app.signals) == n0 - 1 and app.find_signal(src.key) is None and len(app._sig_clip) == 1, "⌘X → 從清單拿掉、進剪貼簿")
    moved = app.paste_to_panel(target_p)
    app.update()
    mv = [s for s in app.signals if s.panel == target_p and s.path == src.path and s.column == src.column]
    check(moved == 1 and len(app.signals) == n0 and len(mv) == 1 and mv[0].key == src.key, "右鍵「貼上訊號到 P1」→ 搬過去（原本的 key 沒被佔用就沿用）")
    app.event_generate("<<Undo>>", when="now")
    app.update()
    app.event_generate("<<Undo>>", when="now")
    app.update()
    check(len(app.signals) == n0 and app.find_signal(src.key) is not None and app.find_signal(src.key).panel == src.panel,
          "<<Undo>> 兩次（macOS 的 ⌘Z 走 Edit 選單的虛擬事件）→ 回到剪下前")
    app.sig_tree.selection_set([f"s{src.uid}"])
    app._on_list_select()
    app._sig_clip = []
    app.event_generate("<<Copy>>", when="now")
    app.update()
    check(len(app._sig_clip) == 1 and app._sig_clip[0]["key"] == src.key, "<<Copy>>（⌘C）→ 進剪貼簿")
    app._current_panel = target_p
    app.event_generate("<<Paste>>", when="now")
    app.update()
    check(len(app.signals) == n0 + 1 and any(s.panel == target_p and s.column == src.column and s.path == src.path for s in app.signals), "<<Paste>>（⌘V）→ 貼到目前 panel")
    app.event_generate("<<Undo>>", when="now")
    app.update()
    check(len(app.signals) == n0, "<<Undo>> 拿掉")
    app._sig_clip = []
    app.plot()
def s8z_signal_tab_buttons():
    """「訊號」分頁的按鈕（2026-10 review；第四批加「錯誤率比對…」）：每顆有 tooltip；要選取／要訊號／要剪貼簿的按鈕不適用時變灰（MATLAB 慣例）；
    每個動作完成狀態列留結果；沒變化（已在最上面、已同一張、已各自一張、清單空）不推 undo、狀態列說明。"""
    pk.close_all()
    app.update()
    tab = app.strip.tabs["signal"]
    btns = {}
    stack = [tab, app.strip.tabs["style"], app.strip.tabs["export"]]   # 樣式、圖片視窗的按鈕現在在「樣式」「匯出」分頁
    while stack:
        w = stack.pop()
        if isinstance(w, (sv.ttk.Button, sv.ttk.Checkbutton)):
            btns[w.cget("text")] = w
        stack.extend(w.winfo_children())
    names = ["上移", "下移", "依名稱排序", "移除", "清空", "全選", "復原", "重做", "合併成一張圖", "拆成各自一張",
             "顏色…", "線寬…", "標記大小…", "重設樣式", "繪圖類型 ▾", "複製訊號", "複製到新圖片視窗", "開新圖片視窗", "貼到圖片視窗",
             "開啟突波抑制", "停用突波抑制", "圖上標示修正的點", "參數…", "標示差異區間", "虛線區分", "容許誤差…", "上一個差異", "下一個差異",
             "錯誤率比對…", "上一個轉態", "下一個轉態"]
    check(len(btns) == 31 and all(n in btns for n in names), f"訊號分頁 31 顆按鈕都在（缺 {sorted(set(names) - set(btns))}）")
    no_tip = [n for n in names if n in btns and not getattr(btns[n], "_pk_tip", None)]
    check(not no_tip, f"每顆按鈕都有 tooltip（缺：{no_tip}）")
    need_sel = ["上移", "下移", "移除", "顏色…", "線寬…", "標記大小…", "重設樣式", "繪圖類型 ▾", "複製訊號", "複製到新圖片視窗"]
    need_sig = ["依名稱排序", "清空", "全選", "合併成一張圖", "拆成各自一張"]
    dis = lambda n: btns[n].instate(["disabled"])
    snap0 = app._snapshot()
    sv.CLIPBOARD[:] = []
    app.sig_tree.selection_set([])
    app._update_action_buttons()
    app.update()
    check(all(dis(n) for n in need_sel) and dis("貼到圖片視窗") and not any(dis(n) for n in need_sig) and not dis("開新圖片視窗"),
          "沒選取：上移／下移／移除／樣式／複製變灰，貼上（剪貼簿空）變灰；排序／清空／全選／合併／拆開／開新視窗可用")
    n_undo = len(app.undo)
    app.move_selected(-1)
    check("要先在「已繪訊號」清單選取" in app.status_var.get() and len(app.undo) == n_undo,
          f"沒選取直接叫上移（快速鍵路徑）→ 狀態列說明、不推 undo（{app.status_var.get()[:44]}）")
    ids = list(app.sig_tree.get_children())
    app.sig_tree.selection_set([ids[0]])
    app.update()
    check(not any(dis(n) for n in need_sel), "選了 1 條 → 需要選取的按鈕全部可用")
    btns["上移"].invoke(); app.update()
    check("已經在最上面" in app.status_var.get() and len(app.undo) == n_undo, "第一條按上移 → 「已經在最上面」、不推 undo")
    btns["下移"].invoke(); app.update()
    check(app.sig_tree.get_children()[1] == ids[0] and "已把 1 條訊號下移" in app.status_var.get() and len(app.undo) == n_undo + 1,
          f"下移 → 變第二列、狀態列有結果、推 1 筆 undo（{app.status_var.get()}）")
    app.undo_action()
    app.sig_tree.selection_set([ids[0]]); app.update()
    btns["合併成一張圖"].invoke(); app.update()
    check("合併要選 2 條以上" in app.status_var.get() and len(app.undo) == n_undo, "只選 1 條按合併 → 狀態列說明、不推 undo")
    a = app.signals[0]
    b = next(s for s in app.signals if s.panel != a.panel)
    pair = [f"s{a.uid}", f"s{b.uid}"]
    app.sig_tree.selection_set(pair); app.update()
    btns["合併成一張圖"].invoke(); app.update()
    check(a.panel == b.panel and "已把 2 條訊號合併到 panel" in app.status_var.get(), f"合併 2 條 → 同一 panel、狀態列（{app.status_var.get()}）")
    btns["合併成一張圖"].invoke(); app.update()
    check("已經在同一張圖" in app.status_var.get(), "再按合併 → 「已經在同一張圖」")
    btns["拆成各自一張"].invoke(); app.update()
    check(a.panel != b.panel and "拆成各自一張圖" in app.status_var.get(), f"拆開 → 各自一張、狀態列（{app.status_var.get()}）")
    btns["拆成各自一張"].invoke(); app.update()
    check("已經各自一張圖了" in app.status_var.get(), "再按拆開 → 「已經各自一張圖了」")
    btns["全選"].invoke(); app.update()
    check(len(app.sig_tree.selection()) == len(ids) and "已選取全部 6 條訊號" in app.status_var.get(), f"全選 → 全部選取、狀態列（{app.status_var.get()}）")
    check(bool(app.sig_tree.bind("<Control-a>")), "清單有 Ctrl+A 全選綁定")
    app.sig_tree.selection_set([ids[0]]); app.update()
    sv.colorchooser.askcolor = lambda **k: ((0, 0, 255), "#0000ff")
    btns["顏色…"].invoke(); app.update()
    check(app.selected_signals()[0].color == "#0000ff" and "已把 1 條訊號的線色改成 #0000ff" in app.status_var.get(), "顏色… → 改了、狀態列有結果")
    sv.simpledialog.askfloat = lambda *a, **k: 2.0
    btns["線寬…"].invoke(); app.update()
    check(app.selected_signals()[0].lw == 2.0 and "線寬改成 2 點" in app.status_var.get(), "線寬… → 狀態列有結果")
    btns["標記大小…"].invoke(); app.update()
    check(app.selected_signals()[0].ms == 2.0 and "標記大小改成 2 點" in app.status_var.get(), "標記大小… → 狀態列有結果")
    btns["重設樣式"].invoke(); app.update()
    check(app.selected_signals()[0].color is None and app.selected_signals()[0].lw is None and "樣式恢復成自動" in app.status_var.get(),
          "重設樣式 → 還原、狀態列有結果")
    btns["貼到圖片視窗"].invoke(); app.update()
    check(not pk.windows() and dis("貼到圖片視窗"), "剪貼簿空：貼到圖片視窗是灰的、按了不開視窗")
    app.paste_signals()
    check("剪貼簿是空的" in app.status_var.get() and not pk.windows(), "Ctrl+V 剪貼簿空 → 狀態列說明（不跳對話框、不開視窗）")
    btns["複製訊號"].invoke(); app.update()
    check(len(sv.CLIPBOARD) == 1 and not dis("貼到圖片視窗"), "複製訊號 → 「貼到圖片視窗」變成可用")
    btns["貼到圖片視窗"].invoke(); app.update()
    w = pk.active_window()
    check(w is not None and len(w.series()) == 1 and "已把 1 條訊號貼到「" in app.status_var.get(),
          f"貼到圖片視窗 → 開新視窗貼 1 條、狀態列（{app.status_var.get()}）")
    btns["複製到新圖片視窗"].invoke(); app.update()
    check(len(pk.windows()) == 2 and "已把 1 條訊號複製到新的「" in app.status_var.get(), f"複製到新圖片視窗 → 狀態列（{app.status_var.get()}）")
    btns["開新圖片視窗"].invoke(); app.update()
    check(len(pk.windows()) == 3 and "已開啟空的「" in app.status_var.get(), "開新圖片視窗 → 狀態列說接著怎麼貼")
    pk.close_all()
    app.update()
    app.sig_tree.selection_set([ids[0]]); app.update()
    btns["移除"].invoke(); app.update()
    check(len(app.signals) == 5 and "已移除 1 條訊號（Ctrl+Z 可復原）" in app.status_var.get(), "移除 → 狀態列有結果")
    app.undo_action()
    check(len(app.signals) == 6, "復原移除")
    app.sig_tree.selection_set([]); app.update()
    btns["清空"].invoke(); app.update()
    check(len(app.signals) == 0 and "已清空 6 條訊號" in app.status_var.get() and all(dis(n) for n in need_sig),
          "清空 → 狀態列有結果；清單空時排序／清空／全選／合併／拆開變灰")
    n2 = len(app.undo)
    btns["依名稱排序"].invoke(); app.update()          # 已停用：什麼都不做
    app.sort_by_name()                                   # 直接叫（快速鍵／右鍵路徑）
    check(len(app.undo) == n2 and "沒有訊號可以排序" in app.status_var.get(), "清單空按排序 → 狀態列說明、不推 undo")
    app._restore_snapshot(snap0)
    app.sig_tree.selection_set([])
    app.update()
    check(len(app.signals) == 6 and not dis("依名稱排序") and dis("移除"), "還原測試前的 6 條訊號；按鈕狀態跟著更新")
def s13_view_strip_buttons():
    """檢視分頁與右上快速存取列（按鈕 review 2026-10-23）：每顆都有 tooltip；開關按了狀態列說開／關、圖真的變；
    預設版面／只看圖／面板開關有回應且勾選與版面一致；主題／風格下拉有狀態列；存成圖檔不印十字游標、報路徑；
    大小改變引起的重畫不蓋掉狀態列。"""
    from matplotlib.backend_bases import MouseEvent
    T = sv.T
    ttk = sv.ttk

    def walk(w):
        yield w
        for c in w.winfo_children():
            yield from walk(c)

    def find(text):
        for w in walk(app.strip.tabs["view"]):
            if isinstance(w, (ttk.Button, ttk.Checkbutton)) and str(w.cget("text")) == text:
                return w
        raise KeyError(text)

    def tip_of(w):
        return getattr(getattr(w, "_tooltip", None), "text", "")

    items = [w for w in walk(app.strip.tabs["view"]) if isinstance(w, (ttk.Button, ttk.Checkbutton, ttk.Combobox))]
    qab = [w for w in app.strip.qab.winfo_children() if isinstance(w, ttk.Button)]
    no_tip = [str(w.cget("text")) or w.winfo_class() for w in items + qab if not tip_of(w)]
    check(len(items) == 15 and len(qab) == 4 and not no_tip, f"檢視分頁 15 項＋快速存取列 4 顆（沒有 PLOT）都有 tooltip（缺：{no_tip}）")
    check("復原" in tip_of(app.btn_undo) and "重做" in tip_of(app.btn_redo) and "匯出設定" in tip_of(qab[0]) and "README" in tip_of(qab[-1]),
          f"快速存取列 tooltip：{[tip_of(w)[:14] for w in qab]}")
    app.strip.select("view")
    app.update()
    # --- 顯示開關 ---
    find("格線").invoke(); app.update()
    ax = app.render_info["axes"][0]
    check(not app.v["grid"].get() and not any(gl.get_visible() for gl in ax.get_xgridlines()) and app.status_var.get() == "格線：關",
          f"格線 → 重畫沒有格線、狀態列「格線：關」（{app.status_var.get()!r}）")
    find("格線").invoke(); app.update()
    check(app.v["grid"].get() and any(gl.get_visible() for gl in app.render_info["axes"][0].get_xgridlines()) and app.status_var.get() == "格線：開",
          "再按 → 格線回來、「格線：開」")
    find("圖例").invoke(); app.update()
    check(app.render_info["axes"][0].get_legend() is None and app.status_var.get() == "圖例：關", "圖例 → 圖例消失、狀態列")
    find("圖例").invoke(); app.update()
    check(app.render_info["axes"][0].get_legend() is not None, "圖例回來")
    n0 = sum(len(a.get_lines()) for a in app.render_info["axes"])
    find("Sample markers").invoke(); app.update()
    n1 = sum(len(a.get_lines()) for a in app.render_info["axes"])
    check(app.v["markers"].get() and n1 > n0 and app.status_var.get().startswith("Sample markers：開"),
          f"Sample markers → 多了 marker 線（{n0} → {n1}）、狀態列")
    find("Sample markers").invoke(); app.update()
    check(sum(len(a.get_lines()) for a in app.render_info["axes"]) == n0, "再按 → marker 線拿掉")
    find("十字游標").invoke(); app.update()
    check(not app.v["cursor"].get() and not app._cursor_items and app.status_var.get() == "十字游標：關", "十字游標關 → 游標 artist 拿掉、狀態列")
    find("十字游標").invoke(); app.update()
    check(app._cursor_items and app.status_var.get().startswith("十字游標：開"), "十字游標開 → 狀態列")
    find("滾輪縮放").invoke(); app.update()
    check(not app.ia.wheel_enabled and app.status_var.get().startswith("滾輪縮放：關"), "滾輪縮放關 → 狀態列說怎麼縮放")
    find("滾輪縮放").invoke(); app.update()
    check(app.ia.wheel_enabled and app.status_var.get().startswith("滾輪縮放：開"), "滾輪縮放開")
    app.show_all_x(); app.update()
    full = app.current_xlim()
    z = (full[0] + (full[1] - full[0]) * 0.3, full[0] + (full[1] - full[0]) * 0.4)
    app.plot(keep=True, xlim=z); app.update()
    app.plot(); app.update()
    check(abs(app.current_xlim()[0] - z[0]) < 1e-6 and abs(app.current_xlim()[1] - z[1]) < 1e-6, "保留 x 範圍開著：PLOT 不動縮放")
    find("重畫時保留 x 範圍").invoke(); app.update()
    check(not app.v["keep_xlim"].get() and app.status_var.get().startswith("重畫時保留 x 範圍：關"), "保留 x 範圍關 → 狀態列說明")
    app.plot(); app.update()
    check(abs(app.current_xlim()[1] - full[1]) < 1e-6, "關掉後 PLOT 回到全部顯示")
    find("重畫時保留 x 範圍").invoke(); app.update()
    check(app.v["keep_xlim"].get() and app.status_var.get().startswith("重畫時保留 x 範圍：開"), "再按 → 開")
    # --- 版面 ---
    d = app.dock
    d.hide("folder"); d.move("props", "left"); app.update()
    find("預設版面").invoke(); app.update()
    check(d.order["left"][:2] == ["folder", "sigs"] and "props" in d.hidden and d.order["center"] == ["plot"]
          and app.status_var.get().startswith("已恢復預設版面"), f"預設版面 → 左欄 資料夾、已繪訊號｜右 圖、狀態列（{app.status_var.get()[:12]!r}）")
    find("預設版面").invoke(); app.update()
    check(app.status_var.get().startswith("版面已經是預設版面"), "版面沒變也有回應")
    find("只看圖").invoke(); app.update()
    check(d.max_key == "plot" and app.v_plot_max.get() and not app.folder_panel.winfo_ismapped() and app.status_var.get().startswith("只看圖："),
          "只看圖 → 最大化、狀態列")
    find("資料夾").invoke(); app.update()
    check(d.max_key is None and not app.v_plot_max.get() and not d.hidden and app.v_panel["folder"].get() and app.folder_panel.winfo_ismapped()
          and app.status_var.get() == "已顯示「資料夾」面板", f"只看圖開著時勾資料夾 → 先離開最大化、勾選與版面一致（{app.status_var.get()!r}）")
    find("已繪訊號").invoke(); app.update()
    check("sigs" in d.hidden and not app.sig_panel.winfo_ismapped() and app.status_var.get().startswith("已隱藏「已繪訊號」面板"), "取消勾選 → 隱藏、狀態列")
    time.sleep(0.25); app.update()                   # 等 120 ms 的 resize 重畫跑過
    check(app.status_var.get().startswith("已隱藏「已繪訊號」面板"), "大小改變引起的重畫不蓋掉狀態列訊息")
    find("已繪訊號").invoke(); app.update()
    check("sigs" not in d.hidden and app.sig_panel.winfo_ismapped(), "再勾 → 顯示")
    find("只看圖").invoke(); app.update()
    find("只看圖").invoke(); app.update()
    check(d.max_key is None and not d.hidden and app.status_var.get() == "已還原版面", "只看圖 開→關 → 還原、狀態列")
    # --- 外觀 ---
    theme_cb, style_cb = [w for w in walk(app.strip.tabs["view"]) if isinstance(w, ttk.Combobox)][-2:]   # 外觀的主題／風格（座標區另有 x 軸單位）
    theme_cb.set("淺色"); theme_cb.event_generate("<<ComboboxSelected>>"); app.update()
    check(T.current().name == "light" and app.v["theme"].get() == "light" and app.status_var.get().startswith("已切換為淺色主題"),
          f"主題下拉 → light、狀態列（{app.status_var.get()!r}）")
    theme_cb.set("深色"); theme_cb.event_generate("<<ComboboxSelected>>"); app.update()
    check(T.current().name == "dark" and app.status_var.get().startswith("已切換為深色主題"), "切回 dark")
    style_cb.set("matplotlib"); style_cb.event_generate("<<ComboboxSelected>>"); app.update()
    check(app.v["style"].get() == "default" and app.status_var.get() == "圖風格：matplotlib 預設", "風格下拉 → default、狀態列")
    style_cb.set("MATLAB"); style_cb.event_generate("<<ComboboxSelected>>"); app.update()
    check(app.v["style"].get() == "matlab-dark" and app.status_var.get() == "圖風格：MATLAB（跟著主題）", "風格下拉 → MATLAB（dark 主題 → matlab-dark）")
    # --- 匯出：存成圖檔… ---
    seen = {}
    orig_savefig = app.fig.savefig

    def rec_savefig(*a, **k):
        seen["cursor_visible"] = any(vl.get_visible() or tx.get_visible() for _a, vl, tx in app._cursor_items)
        return orig_savefig(*a, **k)
    app.fig.savefig = rec_savefig
    png = os.path.join(OUT, "view_strip.png")
    orig_ask = sv.filedialog.asksaveasfilename
    titles = []
    sv.filedialog.asksaveasfilename = lambda **k: (titles.append(k.get("title")), png)[1]
    ax = app.render_info["axes"][0]
    px, py = ax.transData.transform((sum(ax.get_xlim()) / 2, sum(ax.get_ylim()) / 2))
    app.canvas.draw()
    app._on_motion(MouseEvent("motion_notify_event", app.canvas, px, py))
    check(app._cursor_items and app._cursor_items[0][1].get_visible() and app._cursor_items[0][2].get_text(), "存圖前十字游標顯示中（有數值框）")
    find("存成圖檔…").invoke(); app.update()
    check(os.path.exists(png) and os.path.getsize(png) > 1000 and seen.get("cursor_visible") is False and titles == ["存成圖檔"]
          and app.status_var.get() == f"圖已存成 {png}",
          f"存成圖檔 → 中文對話框、PNG 寫出、十字游標先藏起來、狀態列報路徑（{app.status_var.get()[:30]!r}）")
    sv.filedialog.asksaveasfilename = lambda **k: ""
    st = app.status_var.get()
    find("存成圖檔…").invoke(); app.update()
    check(app.status_var.get() == st and len(titles) == 1, "取消對話框 → 不存、狀態列不變")
    sv.filedialog.asksaveasfilename = orig_ask
    app.fig.savefig = orig_savefig
    # --- 快速存取列：復原／重做 disabled 跟堆疊一致 ---
    check(app.btn_undo.instate(["disabled"]) == (not app.undo.can_undo) and app.btn_redo.instate(["disabled"]) == (not app.undo.can_redo),
          "復原／重做按鈕的 disabled 與 undo 堆疊一致")
    app.show_all_x(); app.update()


@step
def s15_panel_strips():
    """panel 左邊的標題區（P1 那一帶）：拖曳換順序、雙擊收合／展開、右鍵選單；收合時資料提示保留；設定檔記錄收合。"""
    app.dock.reset()
    app.v["fit_panels"].set(False)
    app.v["panel_height"].set("1.5")
    app.panel_collapsed = set()
    app.plot()
    app.update()
    order0 = app.panel_order()
    info = app.render_info
    w = app.canvas.get_tk_widget()
    H = app.canvas.get_width_height(physical=True)[1]

    def margin_xy(p):                                  # 該 panel 的標題（「P1」ylabel）中心（matplotlib 像素座標）；y 刻度數字是尺規，不算標題區
        ax = info["axes"][info["panels"].index(p)]
        lb = ax.yaxis.label.get_window_extent(app.canvas.get_renderer())
        return (lb.x0 + lb.x1) / 2, (ax.bbox.y0 + ax.bbox.y1) / 2

    from matplotlib.backend_bases import MouseEvent
    mx, my = margin_xy(order0[0])
    dpr_ = float(getattr(app.canvas, "device_pixel_ratio", 1) or 1)     # 60 個邏輯像素：Windows 175% 是 105 個事件像素（W10；Mac 是 1）
    check(app._margin_panel(MouseEvent("motion_notify_event", app.canvas, mx, my)) == order0[0]
          and app._margin_panel(MouseEvent("motion_notify_event", app.canvas, mx + 60 * dpr_, my)) is None,
          "座標區左邊的留白認得是哪個 panel；座標區裡不算")
    ax0 = info["axes"][info["panels"].index(order0[0])]
    rx = ax0.bbox.x0 - 6                               # 軸線左邊、y 刻度數字那一帶＝尺規（MATLAB rulerPanInteraction）
    ev = MouseEvent("motion_notify_event", app.canvas, rx, my)
    hr = app.ia.hit_test(ev)
    check(app._margin_panel(ev) == order0[0] and hr.kind != "ruler",
          f"y 刻度數字那一帶也是 panel 握把（可拖曳換順序；hit {hr.kind}）")
    last = order0[-1]
    app.move_panel(last, -1)
    app.update()
    check(app.panel_order()[-2] == last, f"選單「上移」→ P{last} 往上一格（{app.panel_order()}）")
    app.undo_action()
    app.update()
    check(app.panel_order() == order0, "Ctrl+Z → 順序還原")
    # 用 Tk 事件拖最後一個 panel 的標題區到最上面
    info = app.render_info
    lx, ly = margin_xy(last)
    tx, ty = margin_xy(order0[0])
    ty = info["axes"][0].bbox.y1 + 5                   # 第一個 panel 上緣再上面一點
    wx, wy = int(lx), int(H - ly)
    w.event_generate("<ButtonPress-1>", x=wx, y=wy, rootx=w.winfo_rootx() + wx, rooty=w.winfo_rooty() + wy, when="now")
    app.update()
    check(HL or (app._strip_drag is not None and app._strip_drag["p"] == last and not app._strip_drag["on"]), "按住標題區 → 準備拖曳")
    wx2, wy2 = int(tx), int(H - ty)
    w.event_generate("<Motion>", x=wx2, y=wy2, rootx=w.winfo_rootx() + wx2, rooty=w.winfo_rooty() + wy2, state=0x100, when="now")
    app.update()
    check(HL or (app._strip_drag["on"] and app._strip_drag["target"] == 0 and app._strip_ind is not None and app._strip_ind.winfo_ismapped()),
          f"拖到最上面：指示線顯示（target={app._strip_drag['target'] if app._strip_drag else None}）")
    w.event_generate("<ButtonRelease-1>", x=wx2, y=wy2, rootx=w.winfo_rootx() + wx2, rooty=w.winfo_rooty() + wy2, when="now")
    app.update()
    if HL:
        app.reorder_panels([last] + [p for p in order0 if p != last])
    check(app.panel_order()[0] == last and app.panel_order()[1:] == order0[:-1] and not (app._strip_ind is not None and app._strip_ind.winfo_ismapped()),
          f"放開 → P{last} 變成最上面、指示線消失（{app.panel_order()}）" + ("（無桌面：改直接呼叫）" if HL else ""))
    app.undo_action()
    app.update()
    check(app.panel_order() == order0, "Ctrl+Z → 拖曳的順序還原")
    # 雙擊標題區收合；資料提示保留；設定檔記錄；再雙擊展開
    p0 = order0[0]
    s0 = next(s for s in app.signals if s.panel == p0)
    app.ia.add_tip(s0.uid, 10)
    n_tips = len(app.datatips)
    info = app.render_info
    h_before = info["axes"][0].bbox.height
    mx, my = margin_xy(p0)
    MouseEvent("button_press_event", app.canvas, mx, my, button=1, dblclick=True)._process()   # Tk 不能 event_generate 雙擊，走 matplotlib 的事件
    app.update()
    ax0 = app.render_info["axes"][0]
    drawn = any(a["panel"] == p0 for a in app.render_info["artists"].values())
    check(p0 in app.panel_collapsed and ax0.bbox.height < h_before * 0.5 and not drawn and p0 in app.render_info["collapsed"],
          f"雙擊標題區 → 收合 P{p0}：矮列、訊號不畫（高 {h_before:.0f} → {ax0.bbox.height:.0f}）")
    check(len(app.datatips) == n_tips and s0.uid in app.render_info["collapsed_uids"], "收合時資料提示留在模型裡")
    check(app.dump_settings()["collapsed_panels"] == [p0], "設定檔記錄收合")
    mx, my = ax0.bbox.x0 + 30, (ax0.bbox.y0 + ax0.bbox.y1) / 2
    MouseEvent("button_press_event", app.canvas, mx, my, button=1, dblclick=True)._process()
    app.update()
    check(p0 not in app.panel_collapsed and any(a["panel"] == p0 for a in app.render_info["artists"].values()) and len(app.ia.tip_artists) >= 1,
          "在矮列上雙擊 → 展開，線和資料提示回來")
    app.ia.clear_tips()
    cfg = app.dump_settings()
    cfg["collapsed_panels"] = [order0[1]]
    app.apply_settings(cfg, quiet=True)
    app.update()
    check(app.panel_collapsed == {order0[1]} and order0[1] in app.render_info["collapsed"], "apply_settings 還原收合狀態")
    app.panel_collapsed = set()
    app.plot()
    app.update()


@step
def s16_measure_transition_normalize():
    """批次 A（工具缺口 8／9／12／13）：量測面板（統計＋脈波，範圍＝目前 x 視圖或掛進來的來源）、上一個／下一個轉態、Normalize Y。"""
    T = sv.T
    ttk = sv.ttk
    d = app.dock
    d.reset()
    app.show_all_x(); app.update()
    clk_s = app.find_signal("digital/clk.txt")
    check(clk_s is not None, "有 digital/clk.txt 可以量")
    tab = app.strip.tabs["signal"]                   # 轉態鈕在訊號分頁（2026-10-23 搬過去）
    by_text = {str(w.cget("text")): w for tb in (tab, app.strip.tabs["measure"]) for w in _walk(tb) if isinstance(w, (ttk.Button, ttk.Checkbutton))}
    # --- 沒選取：轉態鈕變灰、直接叫 → 狀態列說明 ---
    app.sig_tree.selection_set([]); app.update(); app._on_list_select()
    check(by_text["上一個轉態"].instate(["disabled"]) and by_text["下一個轉態"].instate(["disabled"]), "沒有選取：上一個／下一個轉態 disabled")
    app.goto_transition(1)
    check("上一個／下一個轉態" in app.status_var.get() and "先在「已繪訊號」清單選取" in app.status_var.get(), f"沒選取叫轉態 → 狀態列說明：{app.status_var.get()[:40]}")
    # --- 量測面板：分析 → 量測 開關＝檢視 → 版面 的勾選 ---
    check("meas" in d.hidden and not app.meas_visible(), "量測面板預設隱藏")
    app.request_measure_update(0)
    check(app._meas_job is None, "面板隱藏時不排重算")
    by_text["量測"].invoke(); app.update()
    check("meas" not in d.hidden and app.v_panel["meas"].get() and (HL or app.meas_panel.winfo_ismapped())
          and app.status_var.get().startswith("已顯示「量測」面板"), "分析 → 量測：打開面板、版面勾選同步、狀態列")
    head0, _rows0 = app.update_measurements()
    check(app.meas_tree.get_children() and head0[1:] == [x.name for x in app.target_signals()][:sv.MEAS_MAX_SIGNALS]
          and "量測全部" in app.meas_info.get(),
          f"沒選取：量測全部的訊號（2026-10-25 使用者決定 U6：和匯出 TXT、頻譜同一個「全部」；{app.meas_info.get()[-24:]}）")
    app.sig_tree.selection_set([f"s{clk_s.uid}"]); app.update(); app._on_list_select()
    check(app._meas_job is not None, "改選取 → 排一次（防抖）重算")
    app.plot(keep=True, xlim=(10.0, 90.0)); app.update()
    head, rows = app.update_measurements()
    lo, hi, src = app.meas_range()
    exp = sv.measure_signal(clk_s, lo, hi)
    opts = app.current_opts()
    fac, unit, sr = sv.x_display_factor(opts), opts["xunit"], app.symbol_rate()
    got = {r[0]: r[1] for r in rows}
    check(src == "view" and abs(lo - 10.0) < 1e-9 and abs(hi - 90.0) < 1e-9 and head == ["量測", clk_s.name],
          f"範圍＝目前 x 視圖 10..90、表頭＝量測＋訊號名（{head}）")
    exp_rows = sv.MEAS_STAT_ROWS + sv.MEAS_PULSE_ROWS            # 預設兩組（Time Scope：峰值、轉態、過衝／下衝預設關著）
    check(len(rows) == len(exp_rows) == 18 and all(got[lbl] == sv.format_meas(k, exp, fac, unit, sr) for k, lbl in exp_rows),
          f"預設 18 列（統計 10＋脈波 8）都等於 measure_signal＋format_meas（{list(got.items())[:3]}）")
    check(app.meas_tree.get_children() == ("g_stats", "g_pulse") and app.meas_tree.item("m_max", "text") == "最大值"
          and app.meas_tree.heading("v0", "text") == clk_s.name, "表格分「訊號統計」「脈波（Cycles）」兩組、欄標題＝訊號名")
    check(exp["npos"] > 0 and got["週期"] != "—" and got["+工作週期"].endswith("%"), f"時脈量得到脈波：週期 {got['週期']}、duty {got['+工作週期']}")
    # 縮放／平移 → xlim_changed → 防抖重算；結果跟著新範圍
    app.ia.set_xlim(app.render_info["axes"][-1], 20.0, 40.0)
    check(app._meas_job is not None, "改 x 範圍（任何方式）→ 排重算，不是當場算")
    app.update_measurements()
    check(app._meas_table[1][0][1] == sv.format_meas("samples", sv.measure_signal(clk_s, 20.0, 40.0)), "重算後用新的 x 範圍 20..40")
    # 勾選項目
    app.set_meas_rows(["max", "freq"]); app.update()
    head2, rows2 = app.update_measurements()
    check([r[0] for r in rows2] == ["最大值", "頻率"] and app.v["meas_rows"].get() == "max,freq"
          and app.v_meas_row["max"].get() and not app.v_meas_row["mean"].get(), "項目只勾 Max／Frequency → 表格兩列、設定與勾選同步")
    app.v_meas_row["max"].set(False); app._on_meas_row_toggle("max")
    app.v_meas_row["freq"].set(False); app._on_meas_row_toggle("freq")
    check(app.v["meas_rows"].get() == "freq" and app.v_meas_row["freq"].get() and "至少" in app.status_var.get(), "全部取消 → 留住最後一項、狀態列說明")
    menus.clear()
    app._meas_rows_menu(None)
    check(menus and "最大值" in menus[-1] and "+工作週期" in menus[-1] and "峰值搜尋" in menus[-1] and "全部項目" in menus[-1],
          f"項目… 選單：上面是五組開關、下面是各列的勾選（{len(menus[-1]) if menus else 0} 項）")
    app.set_meas_rows(sv.MEAS_ROW_KEYS); app.update()
    # 複製（TSV）
    txt = app.copy_measurements()
    clip = app.clipboard_get()
    check(txt and clip == txt and clip.splitlines()[0] == "量測\t" + clk_s.name and "\t" in clip.splitlines()[1]
          and clip.splitlines()[-1].startswith("範圍\tx 20 .. 40") and app.status_var.get().startswith("已複製 18 項量測"),
          f"複製 → 剪貼簿 TSV（標題列、18 列、範圍）：{clip.splitlines()[:2]}")
    # 範圍來源的掛勾（批次 B 的「兩游標之間」會用）
    rng = {"r": (30.0, 26.0)}
    app.register_meas_range("test", "目前 x 視圖", lambda: rng["r"])
    app.v["meas_range"].set("test")
    app.update_measurements()
    check(app.meas_range() == (26.0, 30.0, "test") and app._meas_table[1][0][1] == sv.format_meas("samples", sv.measure_signal(clk_s, 26.0, 30.0)),
          "register_meas_range：新來源的範圍（順序不拘）拿來量")
    rng["r"] = None
    app.update_measurements()
    check(app.meas_range()[2] == "view" and "目前不能用" in app.meas_info.get(), "來源回 None → 退回目前 x 視圖並註明")
    del app.meas_range_sources["test"]
    app.v["meas_range"].set("view"); app._refresh_meas_range_values()
    # 設定檔：meas_rows／meas_range／normalize
    app.set_meas_rows(["mean", "duty"])
    cfg = app.dump_settings()
    check(cfg["view"]["meas_rows"] == "mean,duty" and cfg["view"]["meas_range"] == "view" and "normalize" in cfg["view"],
          "設定檔記錄 meas_rows／meas_range／normalize")
    app.set_meas_rows(sv.MEAS_ROW_KEYS)
    app.v["meas_rows"].set(cfg["view"]["meas_rows"])
    check(app.v_meas_row["mean"].get() and not app.v_meas_row["max"].get(), "還原 meas_rows → 勾選同步")
    app.set_meas_rows(sv.MEAS_ROW_KEYS)
    # --- 上一個／下一個轉態 ---
    app.sig_tree.selection_set([f"s{clk_s.uid}"]); app.update(); app._on_list_select()
    check(by_text["下一個轉態"].instate(["!disabled"]), "有選取：轉態鈕可用")
    edges = sv.transition_x(clk_s)
    check(edges.size > 6, f"CLK 有轉態（{edges.size} 個）")
    c0 = (edges[2] + edges[3]) / 2.0
    w0 = 4.0 * float(edges[3] - edges[2])
    app.plot(keep=True, xlim=(c0 - w0 / 2, c0 + w0 / 2)); app.update()
    nav0 = len(app.toolbar._nav_stack._elements) if hasattr(app.toolbar, "_nav_stack") else 0
    x1 = app.goto_transition(1)
    exp1 = float(edges[3])
    xl = app.current_xlim()
    check(x1 == exp1 and abs((xl[0] + xl[1]) / 2 - exp1) < 1e-9 and abs((xl[1] - xl[0]) - w0) < 1e-9,
          f"下一個轉態：中心右邊最近的 {exp1}、置中、寬度不變（xlim {xl}）")
    check(app.status_var.get().startswith("轉態 ") and clk_s.name in app.status_var.get(), f"狀態列：{app.status_var.get()[:40]}")
    nav1 = len(app.toolbar._nav_stack._elements) if hasattr(app.toolbar, "_nav_stack") else 0
    check(nav1 > nav0 and app.ia.has_home(), f"轉態跳躍進 上一個／下一個視圖 的 nav stack（{nav0}→{nav1}）")
    if app.v["cursor"].get() and app._cursor_items:
        check(list(app._cursor_items[0][1].get_xdata()) == [x1, x1], "十字游標畫在轉態上")
    x2 = app.goto_transition(1)
    check(x2 == float(edges[edges > exp1 + 1e-9][0]), f"連按 → 下一個（{x2}）")
    x3 = app.goto_transition(-1)
    check(x3 == exp1, f"上一個 → 回到 {exp1}")
    wdg = app.canvas.get_tk_widget()
    tk_key(wdg, "bracketright"); app.update()
    check(abs(sum(app.current_xlim()) / 2 - x2) < 1e-9, "快速鍵 ] ＝下一個轉態")
    tk_key(wdg, "bracketleft"); app.update()
    check(abs(sum(app.current_xlim()) / 2 - exp1) < 1e-9, "快速鍵 [ ＝上一個轉態")
    ent = next(w for w in _walk(app.prop_panel) if w.winfo_class() == "TEntry")
    tk_key(ent, "bracketright"); app.update()
    check(abs(sum(app.current_xlim()) / 2 - exp1) < 1e-9, "輸入框裡按 ] 不跳（照常打字）")
    app.plot(keep=True, xlim=(float(edges[-1]) + 1, float(edges[-1]) + 21)); app.update()
    check(app.goto_transition(1) is None and app.status_var.get().startswith("沒有更多轉態（往後）"), "最後一個之後 → 狀態列說沒有更多")
    # --- Normalize Y ---
    vt = app.strip.tabs["view"]
    nb = next(w for w in _walk(vt) if isinstance(w, ttk.Checkbutton) and str(w.cget("text")) == "Normalize Y")
    nb.invoke(); app.update()
    arts = app.render_info["artists"]
    big = next(s for s in app.signals if s.uid in arts and np.nanmax(np.abs(s.get_data())) > 10)
    yd = np.asarray(arts[big.uid]["line"].get_ydata(), float)
    check(app.v["normalize"].get() and app.render_info["normalize"] and app.status_var.get().startswith("Normalize Y：開")
          and np.nanmax(np.abs(yd - arts[big.uid]["j"] * app.render_info["ystack"])) <= 1.0 + 1e-12,
          f"檢視 → Normalize Y：線畫成 ±1 以內、狀態列（{app.status_var.get()[:20]}）")
    check(np.nanmax(np.abs(big.get_data())) > 10, "Normalize Y 不動資料")
    xs, ys, _n, _ax = app.ia.host.series_data(big.uid)
    i = int(np.nanargmax(np.abs(big.get_data())))
    o = app.current_opts()
    check(abs(abs(ys[i] - arts[big.uid]["j"] * app.render_info["ystack"]) - 1.0) < 1e-12
          and app.ia.host.tip_text(big.uid, i, xs[i], ys[i]) == pk.format_tip_text(big.name, xs[i] * sv.x_display_factor(o), float(big.get_data()[i]), o["xunit"]),
          "資料提示釘在正規化後的線上（series_data），提示文字仍是樣本真值")
    check(app.dump_settings()["view"]["normalize"] is True, "設定檔記錄 normalize=True")
    nb.invoke(); app.update()
    check(not app.render_info["normalize"] and app.status_var.get().startswith("Normalize Y：關"), "再按 → 關")
    by_text["量測"].invoke(); app.update()
    check("meas" in d.hidden, "再按 分析 → 量測 → 面板隱藏")
    app.sig_tree.selection_set([]); app.update()
    app.show_all_x(); app.update()


@step
def s17_dcursors_datatips():
    """批次 B（工具缺口 7、5）：量測游標（Data Cursors：無／一條／兩條、拖曳、Snap、鎖定間距、游標量測面板、量測「兩游標之間」、
    設定檔）與資料提示（匯出／複製 TSV、提示間 Δ、提示內容）。"""
    from matplotlib.backend_bases import MouseEvent
    ttk = sv.ttk
    d = app.dock
    d.reset(); app.update()
    app.set_dcursor_mode("none"); app.v["dcursor_snap"].set(False); app.v["dcursor_lock"].set(False)
    app.show_all_x(); app.update()
    check("cursors" in d.hidden and not app.dcur.active, "游標量測面板預設隱藏、游標預設關")
    tab = app.strip.tabs["measure"]                  # 資料游標在「量測」分頁
    by_text = {str(w.cget("text")): w for w in _walk(tab) if isinstance(w, (ttk.Button, ttk.Checkbutton))}
    menus.clear()
    by_text["資料游標 ▾"].invoke(); app.update()
    mm = app._dcursor_menu()
    radios = [mm.entrycget(i, "label") for i in range(mm.index("end") + 1) if mm.type(i) == "radiobutton"]
    check(menus and "Snap to data" in menus[-1] and "鎖定游標間距" in menus[-1] and "游標移到目前視圖" in menus[-1]
          and radios == ["無", "一條", "兩條"], f"分析 → 資料游標 ▾：無／一條／兩條＋Snap／鎖定間距（{radios} {menus[-1] if menus else None}）")
    mm.destroy()
    xl = app.current_xlim()
    app.set_dcursor_mode("two"); app.update()
    exp = pk.cursors.default_positions(xl[0], xl[1], "two")
    check(app.dcur.active and app.dcur.positions() == exp and "cursors" not in d.hidden and app.v_panel["cursors"].get()
          and app.v["dcursor_mode"].get() == "two" and app.dcursor_mode_label.get() == "兩條",
          f"打開兩條：放在視圖中央 ±1/4、自動顯示「游標量測」面板（{app.dcur.positions()}）")
    axes = app.render_info["axes"]
    check(len(app.dcur.lines[0]) == len(axes) and [t.get_text() for t in app.dcur.labels] == ["1", "2"], "游標貫穿每個 panel、標 1／2")
    head, rows = app.update_cursor_readout()
    vis = [s for s in app.signals if s.visible]
    vis.sort(key=lambda s: -(s.x_span[1] - s.x_span[0]))      # 最長的訊號（游標一定在它的範圍內）放前面
    check(head == ["項目", "游標 1", "游標 2", "Δ"] and rows[0][0].startswith("x (") and rows[1][0] == "1/Δx"
          and rows[1][3].endswith("Hz") and len(rows) == 2 + len(vis), f"讀數表：x、1/Δx（Hz）、每條顯示的訊號一列（{len(rows)} 列）")
    s0 = vis[0]
    v1, v2 = s0.value_at(exp[0]), s0.value_at(exp[1])
    r0 = next(r for r in rows if r[0] == s0.name)
    check(v1 is not None and v2 is not None and r0[1] == sv.fmt_num(v1) and r0[2] == sv.fmt_num(v2) and r0[3] == sv.fmt_num(v2 - v1),
          f"{s0.name}：游標處的值與 Δy（{r0}）")
    # --- 拖曳：游標線旁幾個像素內優先（點線不釘提示、不平移），blit ---
    app.v_tips.set(True); app._on_tips_toggle()
    app.canvas.draw()
    a = app.render_info["artists"][s0.uid]
    ax = a["ax"]
    px = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    hit = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, px + 3, py))
    hit_m = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, 5, py))
    check(hit.kind == "cursor" and hit.id == 0 and hit_m.kind != "cursor", f"游標線 ±3 px → cursor（{hit.kind}）；座標區外（標題區）不是（{hit_m.kind}）")
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, px + 3, py))
    check(app.ia._cursor_kind == "cursor_x" and app.ia.hover_tip is None, "游標上懸停：左右箭頭游標、不出暫時提示")
    xl0, n_tips, n_undo = app.current_xlim(), len(app.datatips), len(app.undo)
    target = (xl[0] + xl[1]) / 2
    tx = float(ax.transData.transform((target, 0))[0])
    n_draw = []
    cid_d = app.canvas.mpl_connect("draw_event", lambda e: n_draw.append(1))
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, px + 3, py, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, px + 6, py))
    check(app.ia.dragging and app.dcur.dragging, "按住游標一動就拖（不等 10 px）")
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, tx + 3, py))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, tx + 3, py, button=1))
    app.canvas.mpl_disconnect(cid_d)
    check(not n_draw, f"拖曳全程只 blit、不整張重畫（{len(n_draw)} 次；大檔也順）")
    x_new = app.dcur.xs[0]
    tol = 2.0 * (xl[1] - xl[0]) / max(1.0, float(ax.bbox.width))
    check(abs(x_new - target) <= tol and app.current_xlim() == xl0 and len(app.datatips) == n_tips and len(app.undo) == n_undo,
          f"拖曳游標 1 到中央：視圖不動、沒釘提示、不進 undo（{x_new:.3f}≈{target:.3f}）")
    check(pk.cursors.parse_positions(app.v["dcursor_x"].get()) == app.dcur.positions() and app.status_var.get().startswith("游標 1：x = "),
          f"放開：位置寫進設定值、狀態列報 x1／x2／Δx（{app.status_var.get()[:50]}）")
    # --- 量測面板「兩游標之間」---
    app.v["meas_range"].set("cursors")
    lo, hi, src = app.meas_range()
    check(src == "cursors" and (lo, hi) == tuple(sorted(app.dcur.positions())), f"量測範圍「兩游標之間」＝兩條游標（{lo:.3f}..{hi:.3f}）")
    check("兩游標之間" in app.meas_range_cb.cget("values"), "量測面板的範圍下拉有「兩游標之間」")
    app.set_dcursor_mode("one"); app.update()
    check(app.meas_range()[2] == "view" and len(app.dcur.positions()) == 1 and app.update_cursor_readout()[0] == ["項目", "游標 1"],
          "一條游標：量測退回目前 x 視圖、讀數表只有游標 1")
    app.v["meas_range"].set("view")
    app.set_dcursor_mode("two"); app.update()
    # --- Snap to data／鎖定間距 ---
    app.sig_tree.selection_set([f"s{s0.uid}"]); app.update(); app._on_list_select()
    app.dcur.set_positions([exp[0] + 0.3 / s0.sps, exp[1] + 0.4 / s0.sps])
    app.v["dcursor_snap"].set(True); app._on_dcursor_snap()
    grid_ok = all(abs((x - s0.x0) * s0.sps - round((x - s0.x0) * s0.sps)) < 1e-6 for x in app.dcur.positions())
    check(grid_ok and app.dcur.snap_enabled, f"Snap to data 打開：游標吸到選取訊號的樣本（{app.dcur.positions()}）")
    app.v["dcursor_lock"].set(True); app._on_dcursor_lock()
    p0 = app.dcur.positions()
    ax = app.dcur.axes[-1]                                     # 選取改變後重畫過：用現在的座標區
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    px2 = float(ax.transData.transform((p0[1], 0))[0])
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, px2, py, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, px2 - 40, py))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, px2 - 40, py, button=1))
    p1 = app.dcur.positions()
    check(abs((p1[1] - p1[0]) - (p0[1] - p0[0])) < 1e-9 and p1[1] < p0[1], f"鎖定間距：拖游標 2，兩條一起動、Δx 不變（{p0} → {p1}）")
    app.v["dcursor_lock"].set(False); app._on_dcursor_lock()
    app.v["dcursor_snap"].set(False); app._on_dcursor_snap()
    # --- 重畫、設定檔 ---
    keep = app.dcur.positions()
    app.plot(); app.update()
    check(app.dcur.active and app.dcur.positions() == keep and app.dcur.lines[0][0].axes is app.render_info["axes"][0],
          "重畫（fig.clear）後游標還在原位")
    cfg = app.dump_settings()
    check(cfg["view"]["dcursor_mode"] == "two" and pk.cursors.parse_positions(cfg["view"]["dcursor_x"]) == keep
          and cfg["view"]["dcursor_snap"] is False and cfg["view"]["dcursor_lock"] is False, "設定檔記錄游標模式、位置、Snap、鎖定間距")
    app.set_dcursor_mode("none"); app.update()
    check(not app.dcur.active and not app.dcur.lines, "關掉游標")
    app.apply_settings(cfg, quiet=True); app.update()
    check(app.dcur.mode == "two" and app.dcur.positions() == keep and app.dcur.active, "apply_settings 還原游標模式與位置")
    old = dict(cfg, view={k: v for k, v in cfg["view"].items() if not k.startswith("dcursor") and k != "tip_fields"})
    app.set_dcursor_mode("none")
    app.apply_settings(old, quiet=True); app.update()
    check(app.dcur.mode == "none" and pk.parse_tip_fields(app.v["tip_fields"].get()) == pk.DEFAULT_TIP_FIELDS, "舊設定檔（沒有游標／提示內容的鍵）照讀、用預設")
    # 右鍵選單有資料游標子選單
    menus.clear()
    app.set_dcursor_mode("two"); app.update()
    ax = app.render_info["axes"][0]
    px = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, px, py, button=3))
    check(menus and "資料游標" in menus[-1], f"游標上右鍵：選單有「資料游標」子選單（{menus[-1][-4:] if menus else None}）")
    xl_d = app.current_xlim()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, px, py, button=1, dblclick=True))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, px, py, button=1))
    check(app.current_xlim() == xl_d, "游標上雙擊不還原視圖")
    if not HL:
        w = app.canvas.get_tk_widget()
        H = app.canvas.get_width_height(physical=True)[1]
        w.event_generate("<Motion>", x=int(round(px)), y=int(round(H - py)), when="now"); app.update()
        check(str(w.cget("cursor")) in ("resizeleftright", "sb_h_double_arrow"), f"Tk <Motion> 到游標線 → 左右箭頭（{w.cget('cursor')!r}）")
        w.event_generate("<Motion>", x=int(round(px + 40)), y=int(round(H - py)), when="now"); app.update()
    app.set_dcursor_mode("none"); app.update()
    # --- 資料提示：Δ、匯出、提示內容 ---
    app.ia.clear_tips()
    sa, sb = vis[0], vis[1]
    t1 = app.ia.add_tip(sa.uid, 20)
    check(app.status_var.get().startswith("資料提示 #"), "一個提示：狀態列照舊（拖曳可移動…）")
    t2 = app.ia.add_tip(sb.uid, 50)
    dlt = app.ia.tip_delta()
    fac = sv.x_display_factor(app.current_opts())
    exp_dx = (sb.x0 + 50 / sb.sps - (sa.x0 + 20 / sa.sps)) * fac
    check(dlt is not None and abs(dlt["dx"] - exp_dx) < 1e-9 and abs(dlt["dy"] - (float(sb.get_data()[50]) - float(sa.get_data()[20]))) < 1e-9
          and app.status_var.get().startswith(f"資料提示 #{t2.id} − #{t1.id}：Δx = "),
          f"兩個提示：狀態列顯示 Δx／Δy（{app.status_var.get()[:60]}）")
    hb = app.home_btns
    check("tip_export" in hb and "tip_fields" in hb and hb["tip_export"].bind("<Enter>"), "首頁 → 資料提示：匯出提示…、提示內容… 鈕（有 tooltip）")
    ann = app.ia.tip_artists[t1.id][0]
    items = [lbl for lbl, _cb in [it for it in app.ia.menu_items(pk.Hit("tip", ann.axes, ann, t1.id)) if it]]
    check("匯出資料提示…" in items and "複製資料提示（TSV）" in items and "提示內容…" in items, f"提示框右鍵：匯出／複製／提示內容（{items}）")
    head, rows = app.ia.tips_table()
    check(head[:4] == ["#", "訊號名稱", "Panel", "樣本索引"] and head[4].startswith("x") and len(rows) == 2
          and rows[0][1] == sa.name and rows[0][2] == f"P{sa.panel}" and rows[0][3] == "21", f"tips_table（{rows[0]}）")
    txt = app.ia.copy_tips()
    check(txt is not None and app.clipboard_get() == txt and txt.splitlines()[0].split("\t")[0] == "#" and len(txt.splitlines()) == 3,
          "複製資料提示：TSV（標題列＋2 列）放進剪貼簿")
    pth = os.path.join(OUT, "tips.csv")
    orig_ask = pk.dialogs.ask_save_path
    pk.dialogs.ask_save_path = lambda *a, **k: pth
    try:
        got = app.export_datatips()
    finally:
        pk.dialogs.ask_save_path = orig_ask
    lines_csv = open(pth, encoding="utf-8").read().splitlines()
    check(got == pth and len(lines_csv) == 3 and lines_csv[1].split(",")[1] == sa.name and "已匯出 2 個資料提示" in app.status_var.get(),
          "首頁「匯出提示…」→ 存 CSV（逗號分隔）")
    dlg = app.tip_fields_dialog()
    check(dlg.selected() == ("name", "x", "y"), f"提示內容…：對話框勾選＝目前的列（{dlg.selected()}）")
    dlg.vars["index"].set(True); dlg.vars["panel"].set(True); dlg.vars["name"].set(False)
    dlg.ok(); app.update()
    t_txt = app.ia.tip_artists[t1.id][0].get_text()
    check(app.v["tip_fields"].get() == "x,y,index,panel" and t_txt.startswith("X ") and "\nIndex 21" in t_txt and f"\nPanel P{sa.panel}" in t_txt
          and sa.name not in t_txt, f"勾 Index／Panel、取消名稱 → 現有提示跟著換、存進設定（{t_txt.splitlines()}）")
    t3 = app.ia.add_tip(sa.uid, 30)
    check("Index 31" in app.ia.tip_artists[t3.id][0].get_text(), "新釘的提示也照勾選的列")
    app.plot(); app.update()
    check("Index 21" in app.ia.tip_artists[t1.id][0].get_text(), "重畫後提示內容不變")
    check(app.dump_settings()["view"]["tip_fields"] == "x,y,index,panel", "設定檔記錄 tip_fields")
    app.ia.set_tip_fields(pk.DEFAULT_TIP_FIELDS)
    check(app.ia.tip_artists[t1.id][0].get_text().startswith(sa.name + "\nX ") and app.v["tip_fields"].get() == "name,x,y", "改回預設")
    app.ia.clear_tips()
    app.v_tips.set(True); app._on_tips_toggle()
    d.reset(); app.update()


@step
def s17b_dcursors_modes_horizontal_keys():
    """游標加強：(1) 工具列放大／平移模式開著時游標線照樣可拖、可點選（線旁 4 px 優先，不放大／不平移）；
    (2) 水平游標（Screen Cursors → Horizontal）：每個 panel 兩條、讀數 y1／y2／Δy、Normalize Y／右軸讀數、設定檔；
    (3) 鍵盤微調：選取的垂直游標 ←→（Snap 開＝一個樣本、關＝1 像素，Shift ×10）、水平游標 ↑↓，和平移／資料提示不衝突；
    (4) 游標移動不進 undo（MATLAB 一樣）。"""
    from matplotlib.backend_bases import KeyEvent, MouseButton, MouseEvent
    cv = app.canvas
    wd = cv.get_tk_widget()
    tb = app.plot_toolbar
    nav = app.toolbar
    L = {MouseButton.LEFT}

    def send(kind, x, y, **kw):
        name = {"press": "button_press_event", "move": "motion_notify_event", "release": "button_release_event"}[kind]
        if kind == "press":
            kw.setdefault("button", 1)
        elif kind == "release":
            kw.setdefault("button", 1)
            kw.setdefault("buttons", set())
        else:
            kw.setdefault("buttons", L)
        ev = MouseEvent(name, cv, x, y, **kw)
        cv.callbacks.process(name, ev)          # 工具列（MatlabNav）和 Interactor 都收到，跟真的滑鼠一樣
        return ev

    def key(k, x=None, y=None):
        app.ia.on_key(KeyEvent("key_press_event", cv, k, x, y))

    app.set_dcursor_mode("none"); app.set_dcursor_h(False)
    app.v["dcursor_snap"].set(False); app._on_dcursor_snap()
    app.v["dcursor_lock"].set(False); app._on_dcursor_lock()
    app.v["normalize"].set(False); app.v["ystack"].set("0")
    app.v_tips.set(True); app._on_tips_toggle()
    app.ia.clear_tips()
    app.show_all_x(); app.plot(); app.update()
    app.set_dcursor_mode("two"); app.update(); cv.draw()
    n_undo = len(app.undo)
    # --- (1) 平移模式：游標線旁照樣拖，不平移 ---
    tb._pan(); app.update()
    check(str(nav.mode) == "pan/zoom", "工具列平移模式開著")
    ax = app.render_info["axes"][0]
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    xl0 = app.current_xlim()
    px = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
    app.ia.on_motion(MouseEvent("motion_notify_event", cv, px + 3, py))
    check(app.ia._cursor_kind == "cursor_x", f"平移模式：游標線上懸停 → ↔（{app.ia._cursor_kind}）")
    target = xl0[0] + 0.4 * (xl0[1] - xl0[0])
    tx = float(ax.transData.transform((target, 0))[0])
    send("press", px + 3, py)
    send("move", px + 8, py)
    send("move", tx + 3, py)
    check(app.ia.dragging and app.dcur.dragging and nav._pan_info is None, "平移模式：按在游標線旁 → 拖游標（工具列沒開始平移）")
    send("release", tx + 3, py)
    tol = 2.0 * (xl0[1] - xl0[0]) / max(1.0, float(ax.bbox.width))
    check(abs(app.dcur.xs[0] - target) <= tol and app.current_xlim() == xl0 and app.dcur.selected == 0
          and pk.cursors.parse_positions(app.v["dcursor_x"].get()) == app.dcur.positions(),
          f"平移模式：拖完游標 1 到 {target:.3f}（{app.dcur.xs[0]:.3f}）、視圖不動、拖過的游標＝選取、位置寫進設定")
    far = float(ax.transData.transform((xl0[0] + 0.85 * (xl0[1] - xl0[0]), 0))[0])
    send("press", far, py)
    send("move", far - 30, py)
    send("release", far - 30, py)
    check(app.current_xlim() != xl0 and not app.dcur.dragging, "平移模式：離游標遠一點照樣平移（模式沒被搶走）")
    app.ia.restore_view(); app.update(); cv.draw()
    tb._pan(); app.update()
    # --- (1) 放大模式：拖游標不拉框、點一下選取不放大、雙擊不還原、Esc 取消 ---
    tb._zoom(); app.update()
    check(str(nav.mode) == "zoom rect", "工具列放大模式開著")
    ax = app.render_info["axes"][0]                  # 還原視圖可能重畫、換掉座標區：重新取
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    xl0 = app.current_xlim()
    p1 = float(ax.transData.transform((app.dcur.xs[1], 0))[0])
    target2 = xl0[0] + 0.7 * (xl0[1] - xl0[0])
    tx2 = float(ax.transData.transform((target2, 0))[0])
    send("press", p1 - 2, py)
    send("move", p1 + 20, py)
    send("move", tx2 - 2, py)
    check(nav._zoom_info is None and app.dcur.dragging, "放大模式：按在游標線旁 → 拖游標，沒有開始拉框")
    send("release", tx2 - 2, py)
    check(abs(app.dcur.xs[1] - target2) <= tol and app.current_xlim() == xl0 and app.dcur.selected == 1,
          f"放大模式：游標 2 拖到 {target2:.3f}（{app.dcur.xs[1]:.3f}）、沒放大、選取游標 2")
    p0 = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
    time.sleep(0.6)
    send("press", p0 + 1, py)
    send("release", p0 + 1, py)
    check(app.current_xlim() == xl0 and app.dcur.selected == 0, "放大模式：在游標上點一下＝選取游標 1，不是放大 1.5 倍")
    send("press", p0 + 1, py, dblclick=True)
    send("release", p0 + 1, py)
    check(app.current_xlim() == xl0, "放大模式：游標上雙擊不還原視圖")
    keep = list(app.dcur.xs)
    send("press", p0 + 1, py)
    send("move", p0 + 60, py)
    key("escape", p0 + 60, py)
    send("release", p0 + 60, py)
    check(app.dcur.xs == keep and not app.dcur.dragging and app.current_xlim() == xl0, "放大模式：拖游標時 Esc 取消、回原位")
    if not HL:                                   # 真的 Tk 滑鼠事件（走 TkAgg → matplotlib → MatlabNav → Interactor）
        H = cv.get_width_height(physical=True)[1]
        px0 = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
        tgt = xl0[0] + 0.3 * (xl0[1] - xl0[0])
        tpx = float(ax.transData.transform((tgt, 0))[0])

        def tev(seq, x, state=0):
            wd.event_generate(seq, x=int(round(x)), y=int(round(H - py)), rootx=wd.winfo_rootx() + int(round(x)),
                              rooty=wd.winfo_rooty() + int(round(H - py)), when="now", state=state)
            app.update()
        time.sleep(0.6)
        tev("<Motion>", px0 + 2)
        check(str(wd.cget("cursor")) in ("resizeleftright", "sb_h_double_arrow"), f"放大模式 Tk <Motion> 到游標線 → ↔（{wd.cget('cursor')!r}）")
        tev("<ButtonPress-1>", px0 + 2)
        tev("<Motion>", px0 + 20, 0x100)
        tev("<Motion>", tpx + 2, 0x100)
        tev("<ButtonRelease-1>", tpx + 2, 0x100)
        check(abs(app.dcur.xs[0] - tgt) <= tol and app.current_xlim() == xl0 and not [i for i in wd.find_all() if wd.type(i) != "image" and "dsv_panel_ui" not in wd.gettags(i)],
              f"放大模式 Tk 拖曳游標線：游標到 {tgt:.3f}（{app.dcur.xs[0]:.3f}）、沒放大、沒留框")
        tev("<Motion>", tpx + 80)
    tb._zoom(); app.update()
    check(not nav.mode and len(app.undo) == n_undo, "放大／平移模式裡拖游標也不進 undo")
    # --- (2) 水平游標 ---
    menus.clear()
    mm = app._dcursor_menu()
    labels = [mm.entrycget(i, "label") for i in range(mm.index("end") + 1) if mm.type(i) == "checkbutton"]
    mm.destroy()
    check("水平游標" in labels, f"資料游標選單有「水平游標」勾選（{labels}）")
    app.set_dcursor_h(True); app.update(); cv.draw()
    info = app.render_info
    panels = [p for p in info["panels"] if p not in (info.get("collapsed") or [])]
    hp = app.dcur.hpositions()
    ok_def = all(hp.get(p) == pk.cursors.default_hpositions(*info["axes"][info["panels"].index(p)].get_ylim()) for p in panels)
    check(app.dcur.h_on and app.dcur.h_active and set(hp) == set(panels) and ok_def and app.v["dcursor_h"].get(),
          f"水平游標打開：每個 panel 兩條、放在 y 視圖中央 ±1/4（{hp}）")
    check(app.dcur.active and app.dcur.mode == "two", "和垂直游標同時開")
    head, rows = app.update_cursor_readout()
    p_a = panels[0]
    ya = hp[p_a]
    r_a = next((r for r in rows if r[0] == f"P{p_a} y"), None)
    check(head == ["項目", "游標 1", "游標 2", "Δ"] and r_a == [f"P{p_a} y", sv.fmt_num(ya[0]), sv.fmt_num(ya[1]), sv.fmt_num(ya[1] - ya[0])],
          f"讀數：P{p_a} y 的 y1、y2、Δy（{r_a}）")
    ax_a = info["axes"][info["panels"].index(p_a)]
    hy = float(ax_a.transData.transform((0, ya[1]))[1])
    app.ia.clear_tips()                                   # 前面步驟釘的提示可能剛好擋在游標線上
    cands = [ax_a.bbox.x0 + 60, ax_a.bbox.x0 + 140, (ax_a.bbox.x0 + ax_a.bbox.x1) / 2 - 80, (ax_a.bbox.x0 + ax_a.bbox.x1) / 2 + 37, ax_a.bbox.x1 - 60]
    hx = next((x for x in cands if app.ia.hit_test(MouseEvent("motion_notify_event", cv, x, hy - 3)).kind == "cursor"), cands[0])
    hit = app.ia.hit_test(MouseEvent("motion_notify_event", cv, hx, hy - 3))
    check(hit.kind == "cursor" and hit.id == ("h", p_a, 1), f"水平游標線 ±3 px → cursor（{hit.kind} {hit.id}）")
    app.ia.on_motion(MouseEvent("motion_notify_event", cv, hx, hy - 3))
    check(app.ia._cursor_kind == "cursor_y", "水平游標上懸停 → ↕")
    yl = ax_a.get_ylim()
    ytgt = yl[0] + 0.9 * (yl[1] - yl[0])
    ty = float(ax_a.transData.transform((0, ytgt))[1])
    xl0 = app.current_xlim()
    send("press", hx, hy - 3)
    send("move", hx, hy + 5)
    send("move", hx, ty - 3)
    send("release", hx, ty - 3)
    ytol = 2.0 * (yl[1] - yl[0]) / max(1.0, float(ax_a.bbox.height))
    hp2 = app.dcur.hpositions()
    check(abs(hp2[p_a][1] - ytgt) <= ytol and hp2[p_a][0] == ya[0] and ax_a.get_ylim() == yl and app.current_xlim() == xl0
          and pk.cursors.parse_hpositions(app.v["dcursor_y"].get()) == hp2 and app.status_var.get().startswith(f"P{p_a} 水平游標：y1 = "),
          f"拖水平游標 2 到 y≈{ytgt:.3f}（{hp2[p_a][1]:.3f}）：視圖不動、設定值、狀態列 y1／y2／Δy（{app.status_var.get()[:40]}）")
    app.set_dcursor_mode("one"); app.update()
    head, rows = app.update_cursor_readout()
    check(len(head) == 4 and rows[0][0].startswith("x (") and rows[0][2:] == ["", ""] and any(r[0] == f"P{p_a} y" for r in rows),
          "一條垂直游標＋水平游標：表格三欄（x 那列補空格）")
    app.set_dcursor_mode("none"); app.update()
    head, rows = app.update_cursor_readout()
    check(rows and all(r[0].startswith("P") or r[0].endswith("(y)") for r in rows) and "資料游標關著" not in app.dcursor_info.get(),
          f"只開水平游標：只有 y 讀數（{[r[0] for r in rows]}）")
    # Normalize Y：軸上是 [norm]，另列各訊號原始單位
    app.v["normalize"].set(True); app.plot(); app.update()
    info = app.render_info
    hp3 = app.dcur.hpositions()
    check(hp3 == hp2 and app.dcur.h_active, "重畫（Normalize Y）後水平游標留在原位")
    head, rows = app.update_cursor_readout()
    sg = next(s for s in app.signals if s.visible and s.panel == p_a and info["artists"].get(s.uid, {}).get("ptype") != "bus"
              and info["artists"][s.uid]["yaxis"] == "left")
    g = info["artists"][sg.uid]["gain"]
    r_s = next((r for r in rows if r[0] == f"{sg.name} (y)"), None)
    exp_s = [hp3[p_a][0] / g, hp3[p_a][1] / g]
    check(any(r[0] == f"P{p_a} y [norm]" for r in rows) and r_s == [r_s[0] if r_s else "", sv.fmt_num(exp_s[0]), sv.fmt_num(exp_s[1]), sv.fmt_num(exp_s[1] - exp_s[0])]
          and abs(g - 1.0) > 1e-9, f"Normalize Y：P{p_a} y [norm] 一列＋{sg.name} (y)＝y／倍率（原始單位；{r_s}）")
    app.v["normalize"].set(False)
    # 右軸：同一個螢幕高度換成右軸的值
    sg.yaxis = "right"; app.plot(); app.update()
    info = app.render_info
    ax_l = info["axes"][info["panels"].index(p_a)]
    ax_r = info["axes_right"][p_a]
    head, rows = app.update_cursor_readout()
    (l0, l1), (r0, r1) = ax_l.get_ylim(), ax_r.get_ylim()
    yy = app.dcur.hpositions()[p_a]
    exp_r = [r0 + (v - l0) * (r1 - r0) / (l1 - l0) for v in yy]
    r_r = next((r for r in rows if r[0] == f"P{p_a} y 右軸"), None)
    ok_r = r_r is not None and all(abs(float(r_r[k + 1]) - exp_r[k]) <= 1e-4 * max(1.0, abs(exp_r[k])) for k in (0, 1))
    check(ax_r is not None and ok_r, f"右軸：P{p_a} y 右軸＝同一高度的右軸值（{r_r} ≈ {[round(v, 6) for v in exp_r]}）")
    sg.yaxis = "left"; app.plot(); app.update()
    # 設定檔
    cfg = app.dump_settings()
    keep_h = app.dcur.hpositions()
    check(cfg["view"]["dcursor_h"] is True and pk.cursors.parse_hpositions(cfg["view"]["dcursor_y"]) == keep_h,
          "設定檔記錄水平游標開關與各 panel 的 y1、y2（view.dcursor_h／dcursor_y）")
    app.set_dcursor_h(False); app.update()
    check(not app.dcur.h_on and not app.dcur.hlines, "水平游標關掉")
    app.apply_settings(cfg, quiet=True); app.update()
    check(app.dcur.h_on and app.dcur.hpositions() == keep_h, "apply_settings 還原水平游標與位置")
    check(len(app.undo) == n_undo, f"水平游標的開關、拖曳不進 undo（{len(app.undo)} vs {n_undo}）")
    # --- (3) 鍵盤微調 ---
    app.set_dcursor_mode("two"); app.show_all_x(); app.update()
    tgt_sig = app._dcursor_target()
    n_t = len(tgt_sig.get_data())
    app.dcur.set_positions([tgt_sig.x0 + (n_t // 3) / tgt_sig.sps, tgt_sig.x0 + (n_t // 2) / tgt_sig.sps])    # 在目標訊號裡面、看得到
    app.update(); cv.draw()
    ax = app.render_info["axes"][0]
    py = (ax.bbox.y0 + ax.bbox.y1) / 2
    xl0 = app.current_xlim()
    p0 = float(ax.transData.transform((app.dcur.xs[0], 0))[0])
    send("press", p0 + 1, py)
    send("release", p0 + 1, py)
    check(app.dcur.selected == 0 and app.dcur.lines[0][0].get_linewidth() > 1.0 and app.status_var.get().startswith("已選取游標 1"),
          "點一下游標 1＝選取（線變粗、狀態列提示方向鍵）")
    x_b = app.dcur.xs[0]
    n_v = len(app.undo)
    tk_key(wd, "Right"); app.update()
    dpx = float(ax.transData.transform((app.dcur.xs[0], 0))[0]) - float(ax.transData.transform((x_b, 0))[0])
    dpr = float(getattr(cv, "device_pixel_ratio", 1) or 1)
    check(abs(dpx - dpr) < 1e-6 and app.current_xlim() == xl0, f"Snap 關：→ 移 1 像素、視圖不平移（{dpx:.3f} px）")
    key("shift+left")
    dpx2 = float(ax.transData.transform((app.dcur.xs[0], 0))[0]) - float(ax.transData.transform((x_b, 0))[0])
    check(abs(dpx2 + 9 * dpr) < 1e-6 and pk.cursors.parse_positions(app.v["dcursor_x"].get()) == app.dcur.positions(),
          f"Shift＋← 移 10 像素（{dpx2:.3f}）、位置寫進設定")
    check(len(app.undo) == n_v, f"垂直游標的鍵盤微調不進 undo（{len(app.undo)} vs {n_v}）")
    app.v["dcursor_snap"].set(True); app._on_dcursor_snap()
    x_sn = app.dcur.xs[0]
    tk_key(wd, "Right"); app.update()
    d1 = (app.dcur.xs[0] - x_sn) * tgt_sig.sps
    key("shift+right")
    d10 = (app.dcur.xs[0] - x_sn) * tgt_sig.sps
    check(abs(d1 - 1) < 1e-6 and abs(d10 - 11) < 1e-6 and app.current_xlim() == xl0,
          f"Snap 開：→ 一個樣本、Shift＋→ 十個樣本（{tgt_sig.name}；{d1:.3f}、{d10:.3f} 個樣本）")
    app.v["dcursor_snap"].set(False); app._on_dcursor_snap()
    x_k = list(app.dcur.xs)
    yls = [a.get_ylim() for a in app.render_info["axes"]]
    key("up")
    check(app.dcur.xs == x_k and [a.get_ylim() for a in app.render_info["axes"]] != yls,
          "垂直游標選取中：↑ 不是它的方向 → 照舊平移 5 px、游標不動")
    app.ia.restore_view(); app.update(); cv.draw()
    xl0 = app.current_xlim()
    key("escape")
    check(app.dcur.selected is None and app.dcur.lines[0][0].get_linewidth() == 1.0, "Esc 取消游標選取")
    x_k = list(app.dcur.xs)
    tk_key(wd, "Right"); app.update()
    check(app.current_xlim() != xl0 and app.dcur.xs == x_k, "沒選取游標：→ 照舊平移 5 px、游標不動")
    app.ia.restore_view(); app.update(); cv.draw()
    sv0 = next(s for s in app.signals if s.visible)
    t1 = app.ia.add_tip(sv0.uid, 20)
    app.ia.select_cursor(0)
    check(app.dcur.selected == 0 and app.ia.selected_tip is None, "選游標＝取消資料提示的選取（互斥）")
    app.ia.select_tip(t1.id)
    x_k = list(app.dcur.xs)
    tk_key(wd, "Right"); app.update()
    check(app.dcur.selected is None and t1.index == 21 and app.dcur.xs == x_k, "選提示＝取消游標選取；→ 移提示（不動游標）")
    app.ia.clear_tips()
    n_undo_c = len(app.undo) - n_undo                            # 釘提示／移提示／清除提示本來就可復原：不算在游標的帳上
    non_view = lambda: sum(1 for e in app.undo._undo if e["tag"] != "view_key")    # 鍵盤縮放／平移本來就進 undo（MATLAB）：另計
    nv_c = non_view()
    # 水平游標：↑↓；← 不是它的方向 → 照舊平移；放大模式裡 ↑ 也是移游標（選取中的游標優先）
    info = app.render_info
    ax_a = info["axes"][info["panels"].index(p_a)]
    ya = app.dcur.hpositions()[p_a]
    hy = float(ax_a.transData.transform((0, ya[0]))[1])
    send("press", hx, hy + 2)
    send("release", hx, hy + 2)
    check(app.dcur.selected == ("h", p_a, 0) and app.status_var.get().startswith("已選取水平游標 1"), "點一下水平游標 1＝選取")
    yl = ax_a.get_ylim()
    n_h = len(app.undo)
    tk_key(wd, "Up"); app.update()
    dpy = float(ax_a.transData.transform((0, app.dcur.hpositions()[p_a][0]))[1]) - hy
    key("shift+down")
    dpy2 = float(ax_a.transData.transform((0, app.dcur.hpositions()[p_a][0]))[1]) - hy
    check(abs(dpy - dpr) < 1e-6 and abs(dpy2 + 9 * dpr) < 1e-6 and ax_a.get_ylim() == yl, f"水平游標：↑ 1 像素、Shift＋↓ 10 像素、y 視圖不動（{dpy:.3f}、{dpy2:.3f}）")
    check(len(app.undo) == n_h, f"水平游標的鍵盤微調不進 undo（{len(app.undo)} vs {n_h}）")
    xl0 = app.current_xlim()
    tk_key(wd, "Left"); app.update()
    check(app.current_xlim() != xl0 and app.dcur.selected == ("h", p_a, 0) and app.undo.last_tag == "view_key",
          "水平游標選取中：← 照舊平移（不是它的方向；平移進 undo「縮放／平移」）")
    app.ia.restore_view(); app.update(); cv.draw()
    tb._zoom(); app.update()
    yl = ax_a.get_ylim()
    y_b = app.dcur.hpositions()[p_a][0]
    tk_key(wd, "Up"); app.update()
    check(ax_a.get_ylim() == yl and app.dcur.hpositions()[p_a][0] > y_b, "放大模式＋水平游標選取中：↑ 移游標（不是放大）")
    key("escape")
    tk_key(wd, "Up"); app.update()
    check(ax_a.get_ylim() != yl and app.dcur.selected is None, "取消選取後放大模式 ↑ 照舊放大")
    tb._zoom(); app.update()
    app.ia.restore_view(); app.update()
    # --- (4) undo ---
    check(len(app.undo) - n_undo_c >= n_undo and non_view() == nv_c,
          f"游標的拖曳、選取、鍵盤微調都不進 undo（MATLAB 一樣；只有鍵盤縮放／平移進；非視圖筆數 {non_view()} vs {nv_c}）")
    app.set_dcursor_h(False); app.set_dcursor_mode("none")
    app.dock.reset(); app.update()


@step
def s18_plot_type_iq_constellation_spectrum_units():
    """批次 C（工具缺口 6、14、10）：每條訊號的繪圖類型 line／stairs／stem（選單、屬性、undo、設定檔、提示吸附、hover、
    marker／右軸／Normalize／ystack／隱藏）、I/Q 幅度／相位衍生訊號、星座圖視窗、頻譜類型與單位（dBFS／dBm／RMS、NENBW／RBW）。"""
    from matplotlib.backend_bases import MouseEvent
    ttk = sv.ttk
    app.set_dcursor_mode("none")
    app.v["normalize"].set(False); app.v["ystack"].set("0")
    app.show_all_x(); app.update()
    si = app.find_signal("iq.csv;;adc i")
    sq = app.find_signal("iq.csv;;adc q")
    N = si.n
    # --- 6a 繪圖類型 ---
    by = {str(w.cget("text")): w for w in _walk(app.strip.tabs["style"]) if isinstance(w, ttk.Button)}
    app.sig_tree.selection_set([]); app._on_list_select(); app.update()
    b_pt = by.get("繪圖類型 ▾")
    check(b_pt is not None and b_pt.instate(["disabled"]) and getattr(b_pt, "_pk_tip", None), "訊號 → 樣式 → 繪圖類型 ▾：沒有選取時 disabled、有 tooltip")
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select(); app.update()
    check(not b_pt.instate(["disabled"]) and si.ptype == "stairs" and app.p_ptype.get() == "階梯（stairs）",
          f"選取後啟用；預設 stairs，訊號參數的繪圖類型跟著選取（{app.p_ptype.get()}）")
    m = app._ptype_menu()
    radios = [m.entrycget(i, "label") for i in range(m.index("end") + 1) if m.type(i) == "radiobutton"]
    check(radios == ["線條（line）", "階梯（stairs）", "針狀（stem）"] and app.v_ptype_menu.get() == "stairs", f"繪圖類型選單 {radios}")
    m.destroy()
    n_undo = len(app.undo)
    app.set_plot_type("stem"); app.update()
    a = app.render_info["artists"][si.uid]
    ln = a["line"]
    check(si.ptype == "stem" and a["ptype"] == "stem" and len(ln.get_xdata()) == 3 * N and ln.get_marker() == "o"
          and ln.get_markevery() == slice(1, None, 3) and len(app.undo) == n_undo + 1 and app.p_ptype.get() == "針狀（stem）"
          and app.status_var.get().startswith("已把 1 條訊號的繪圖類型改成 針狀（stem）"),
          f"stem：一條 Line2D（3N 點、空心圓針頭）、進 undo、狀態列（{app.status_var.get()[:40]}）")
    app.v_tips.set(True); app._on_tips_toggle()
    xs, ys, _, _ = app.ia.host.series_data(si.uid)
    tip = app.ia.add_tip(si.uid, 100); app.update()
    ann = app.ia.tip_artists[tip.id][0]
    check(np.allclose(ann.xy, (xs[100], ys[100])) and np.isclose(ys[100], ln.get_ydata()[3 * 100 + 1]),
          f"stem 的資料提示吸附在針頭（樣本頂點 {ann.xy}）")
    ln.axes.set_xlim(xs[290], xs[310])           # 放大到樣本 300 附近：全幅時一個像素涵蓋上百個樣本，hover 解析不到單一樣本
    app.canvas.draw()
    px, py = ln.axes.transData.transform((xs[300], ys[300]))
    hit = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, px, py))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, px, py))
    h = app.ia.hover_tip
    check(hit.kind == "line" and hit.id == si.uid and h is not None and h["uid"] == si.uid and h["index"] == 300,
          f"stem 針頭上 hover（樣本 300）／點選命中這條線（{hit.kind} {hit.id} {h and h['index']}）")
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, px, ln.axes.bbox.y1 - 2))
    app.ia.clear_tips()
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()      # 釘提示會取消訊號的選取（選取互斥）
    app.set_marker("s")
    a = app.render_info["artists"][si.uid]
    check(a["line"].get_marker() == "s" and a["line"].get_markevery() == slice(1, None, 3) and a["line"].get_markerfacecolor() == "none",
          "stem＋標記：針頭換成訊號的 marker（仍只標針頭）")
    app.set_linestyle("--")
    check(a["line"].get_linestyle() == "--" and a["line"].get_marker() == "s", "stem＋線型：針用虛線、針頭不變")
    app.reset_style()
    app.set_yaxis("right"); app.update()
    a = app.render_info["artists"][si.uid]
    check(a["yaxis"] == "right" and a["ptype"] == "stem" and a["ax"] is app.render_info["axes_right"][si.panel], "stem 畫在右軸")
    app.set_yaxis("left")
    app.v["normalize"].set(True); app.v["ystack"].set("2"); app.plot(keep=True)
    a = app.render_info["artists"][si.uid]
    yy = np.asarray(a["line"].get_ydata())
    base = a["j"] * 2.0
    check(np.allclose(yy[0::3], base) and abs(float(np.max(np.abs(yy[1::3] - base))) - 1.0) < 1e-9,
          f"stem＋Normalize＋疊圖 y 位移：基線在 j·ystack={base:g}、峰值 1")
    app.v["normalize"].set(False); app.v["ystack"].set("0"); app.plot(keep=True)
    app.toggle_visible([si]); app.update()
    check(si.uid not in app.render_info["artists"], "隱藏的 stem 不畫")
    app.toggle_visible([si]); app.update()
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()
    app.set_plot_type("line"); app.update()
    a = app.render_info["artists"][si.uid]
    check(a["ptype"] == "line" and len(a["line"].get_xdata()) == N and a["line"].get_drawstyle() == "default", "line：N 個樣本點連直線")
    app.undo_action()
    check(si.ptype == "stem" and app.render_info["artists"][si.uid]["ptype"] == "stem", "復原 → stem")
    app.redo_action()
    check(si.ptype == "line", "重做 → line")
    d = next(x for x in app.dump_settings()["signals"] if x["uid"] == si.uid)
    check(d["ptype"] == "line" and d["derive"] == "", "設定檔記 ptype")
    menus.clear()
    app._on_list_context(SimpleNamespace(x=2, y=2, x_root=10, y_root=10))
    lab = menus[-1] if menus else []
    check("繪圖類型" in lab and sum(1 for x in lab if x.startswith("星座圖")) == 1
          and sum(1 for x in lab if x.startswith("AM/PM/FM 分析")) == 1 and not any(x.startswith(("AM/PM 分析", "FM 分析")) for x in lab)
          and "I/Q 幅度／相位" not in lab,
          f"清單右鍵：繪圖類型、星座圖…、一個「AM/PM/FM 分析（對象）…」（{lab[-12:]}）")
    app.p_ptype.set("針狀（stem）"); app._on_ptype_combo()
    check(si.ptype == "stem", "訊號參數 → 繪圖類型 下拉：選了就套用")
    app.set_plot_type("stairs"); app.update()
    check(si.ptype == "stairs" and app.render_info["artists"][si.uid]["line"].get_drawstyle() == "steps-post", "改回 stairs")
    # --- 6b I/Q 幅度／相位 ---
    ab = app._analyze_btns
    check(not ab["ampm"].instate(["disabled"]) and "fm" not in ab and not ab["constellation"].instate(["disabled"]),
          "分析：星座圖、AM/PM/FM 分析… 有訊號時啟用")
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    n0, n_undo = len(app.signals), len(app.undo)
    panels0 = {s.panel for s in app.signals}
    app.add_iq_magphase(); app.update()                 # 衍生訊號的核心（視窗的「複製訊號」→ 貼上走同一套）
    new = [s for s in app.signals if s.derive]
    mag = next((s for s in new if s.derive == "iq_mag"), None)
    ph = next((s for s in new if s.derive == "iq_phase"), None)
    check(len(app.signals) == n0 + 2 and mag is not None and ph is not None and mag.panel not in panels0 and ph.panel not in panels0
          and mag.panel != ph.panel and len(app.undo) == n_undo + 1 and app.status_var.get().startswith("已新增 2 條衍生訊號"),
          f"I/Q 幅度／相位：新增 2 條衍生訊號、各自新 panel、一次 undo（{app.status_var.get()[:30]}）")
    di, dq = si.get_data(), sq.get_data()
    check(np.allclose(mag.get_data(), np.hypot(di, dq)) and np.allclose(ph.get_data(), np.degrees(np.arctan2(dq, di)))
          and mag.uid in app.render_info["artists"] and app.sig_tree.set(f"s{mag.uid}", "fmt") == "|I+jQ|",
          "衍生訊號：|I+jQ| 與相位（度）、有畫出來、清單 Fmt 欄 |I+jQ|")
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    app.add_iq_magphase()
    check(len(app.signals) == n0 + 2 and app.status_var.get().startswith("這些 I/Q 配對已經有幅度／相位訊號了"), "同一組再按不重複加")
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()
    sh0, sc0 = si.vshift, si.vscale
    app.p_shift.set(sv.fmt_num(sh0 - 100)); app.p_scale.set(sv.fmt_num(sc0)); app.apply_shift_scale(); app.update()
    check(np.allclose(mag.get_data(), np.hypot(si.get_data(), sq.get_data())), "來源改 shift → 衍生訊號自動重算")
    app.undo_action()
    app.sig_tree.selection_set([f"s{ph.uid}"]); app._on_list_select()
    app.v["iq_unwrap"].set(True); app._on_iq_unwrap(); app.update()
    phd = ph.get_data()
    check(ph.derive == "iq_phase_unwrap" and float(np.max(np.abs(np.diff(phd)))) < 180.0, "相位展開：unwrap 後沒有 ±360° 跳躍")
    app.v["iq_unwrap"].set(False); app._on_iq_unwrap()
    check(ph.derive == "iq_phase", "相位不展開：回到 −180..180")
    sw = sv.SpectrumWindow(app, [mag]); app.update()
    check(len(sw.lines) == 1, "衍生訊號可以做頻譜")
    sw.destroy()
    cfg = app.dump_settings()
    app.apply_settings(cfg, quiet=True); app.update()
    si = app.find_signal("iq.csv;;adc i"); sq = app.find_signal("iq.csv;;adc q")
    der = [s for s in app.signals if s.derive]
    mag = next((s for s in der if s.derive == "iq_mag"), None)
    check(len(der) == 2 and mag is not None and np.allclose(mag.get_data(), np.hypot(si.get_data(), sq.get_data()))
          and set(mag.src_uids) == {si.uid, sq.uid}, "設定檔往返：衍生訊號與來源 uid 還原、資料重算")
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()
    der0 = [(s.uid, s.derive, s.src, np.asarray(s.get_data(), float).copy()) for s in app.signals if s.derive]
    app.remove_selected(); app.update()
    now = [app.find_signal_by_uid(u) for u, *_r in der0]
    check(app.find_signal("iq.csv;;adc i") is None and len(der0) == 2
          and all(x is not None and not x.derive and np.allclose(x.get_data(), d_, equal_nan=True) for x, (_u, _k, _s, d_) in zip(now, der0)),
          "移除來源 → 沒一起選到的衍生訊號留著、改成獨立訊號（資料不變；2026-10-25 使用者決定 U8，以前一起移除）")
    app.undo_action(); app.update()
    back = [app.find_signal_by_uid(u) for u, *_r in der0]
    check(len([s for s in app.signals if s.derive]) == 2 and app.find_signal("iq.csv;;adc i") is not None
          and all(x is not None and x.derive == k_ and x.src == s_ for x, (_u, k_, s_, _d) in zip(back, der0)),
          "復原 → 來源回來、衍生訊號的來源連結也回來")
    app.sig_tree.selection_set([f"s{s.uid}" for s in app.signals if s.derive]); app._on_list_select()
    app.remove_selected(); app.update()
    check(not any(s.derive for s in app.signals) and len(app.signals) == n0, "清掉衍生訊號")
    si = app.find_signal("iq.csv;;adc i"); sq = app.find_signal("iq.csv;;adc q")
    # --- 14 星座圖 ---
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()
    n_cw = len([w for w in app.winfo_children() if isinstance(w, sv.ConstellationWindow)])
    app._set_current_panel(si.panel)
    w1 = app.open_constellation(); app.update()          # 第 9 項起：選 1 條 → 分析目前 panel 的 I/Q
    check(isinstance(w1, sv.ConstellationWindow) and w1.pairs[0][0].uid == si.uid
          and app.status_var.get().startswith(f"已開啟星座圖視窗：P{si.panel}，I＝iq:adc i、Q＝iq:adc q"),
          f"選 1 條按 星座圖… → 分析目前 panel 的 I/Q（{app.status_var.get()[:30]}）")
    if w1 is not None:
        w1.destroy(); app.update()
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    app.show_all_x(); app.update()
    w = app.open_constellation(); app.update()
    check(isinstance(w, sv.ConstellationWindow) and app.status_var.get().startswith(f"已開啟星座圖視窗：清單選取（P{si.panel}），I＝iq:adc i、Q＝iq:adc q"),
          f"選 I、Q 按 星座圖… → 用那兩條（{app.status_var.get()[:40]}）")
    di, dq = si.get_data(), sq.get_data()
    n = min(len(di), len(dq))
    lnc = w.lines[1]
    check(w.v_sps.get() == "64" and w.result["points"] == len(range(0, n, 64)) and np.allclose(lnc.get_xdata(), di[:n:64])
          and np.allclose(lnc.get_ydata(), dq[:n:64]) and lnc.get_linestyle() == "None",
          f"預設 SPS＝I 的 SPS（64）、offset 0：每 64 點取一點（{w.result['points']} 點）")
    check(w.fig.axes[0].get_aspect() == 1.0 and w.v_status.get().startswith(f"已畫 {w.result['points']} 個符號點"), "等比例軸、狀態列說畫了幾點")
    w.v_offset.set("10"); w.compute()
    check(np.isclose(w.lines[1].get_xdata()[0], di[10]) and app.const_defaults["offset"] == 10.0, "Offset 10：第一點＝樣本 10、存進設定")
    w.v_symbols_label.set("最後 N 個"); w.v_nsym.set("16"); w.compute()
    idx = sv.constellation_indices(n, 64, 10)
    check(w.result["points"] == 16 and np.isclose(w.lines[1].get_xdata()[-1], di[idx[-1]]), "最後 N 個：只畫最後 16 個符號")
    w.v_ref_label.set("QPSK"); w.compute()
    check("evm" in w.result and "RMS EVM" in w.v_status.get() and len(w.fig.axes[0].get_lines()) == 4, f"參考星座 QPSK＋RMS EVM（{w.v_status.get()[-30:]}）")
    tipc = w.ia.add_tip(1, 3); app.update()
    annc = w.ia.tip_artists[tipc.id][0]
    check(np.allclose(annc.xy, (w.lines[1].get_xdata()[3], w.lines[1].get_ydata()[3])), "星座圖：資料提示釘在點上")
    w.canvas.draw()
    axc = w.fig.axes[0]
    kc = 5
    if os.name == "nt":                         # Windows（W-E）：字大、視窗相對小，第 5 點常在剛釘的提示框底下——往後找第一個不在提示框底下的點
        rr_ = w.canvas.get_renderer()
        tb_ = annc.get_window_extent(rr_)
        for k_ in range(5, len(w.lines[1].get_xdata())):
            px_, py_ = axc.transData.transform((w.lines[1].get_xdata()[k_], w.lines[1].get_ydata()[k_]))
            if not tb_.expanded(1.05, 1.2).contains(px_, py_) and axc.bbox.contains(px_, py_):
                kc = k_
                break
    pxc, pyc = axc.transData.transform((w.lines[1].get_xdata()[kc], w.lines[1].get_ydata()[kc]))
    hc = w.ia.hit_test(MouseEvent("motion_notify_event", w.canvas, pxc, pyc))
    check(HL or (hc.kind == "line" and hc.id == 1),
          f"星座圖：點上點選命中（{hc.kind}）" + ("（無桌面：視窗沒有實際尺寸，提示框蓋住點，略過）" if HL else ""))
    w.v_symbols_label.set("全部"); w.v_offset.set("0"); w.v_ref_label.set("無"); w.compute()
    app.plot(keep=True, xlim=(10.0, 20.0))
    w.compute()
    i0, i1 = si.index_range(10.0, 20.0)
    check(w.result["points"] == len(sv.constellation_indices(n, 64, 0, i0, i1)) and "x 10..20 symbol" in w.v_status.get(),
          f"只用目前 x 範圍：{w.result['points']} 點（{w.v_status.get()[-30:]}）")
    w.v_xrange.set(False); w.compute()
    check(w.result["points"] == len(range(0, n, 64)) and "全部範圍" in w.v_status.get(), "不勾「只用目前 x 範圍」→ 整段")
    w.v_xrange.set(True); w.compute()
    frs = [fr for fr in w.winfo_children() if isinstance(fr, ttk.Frame) and any(isinstance(x, (ttk.Entry, ttk.Checkbutton)) for x in fr.winfo_children())]
    opts_w = [x for fr in frs for x in fr.winfo_children() if not isinstance(x, ttk.Label)]
    missing = _no_tooltip(opts_w)
    check(len(opts_w) >= 10 and not missing, f"星座圖視窗的選項都有 tooltip（{len(opts_w)} 個，缺：{missing}）")
    check(app.dump_settings()["constellation"]["xrange"] is True, "星座圖設定存進設定檔（constellation）")
    w.destroy()
    app.show_all_x(); app.update()
    # --- 10 頻譜類型與單位 ---
    saved_spec = dict(app.spec_defaults)
    app.spec_defaults.clear(); app.spec_defaults.update(sv.DEFAULT_SPEC)      # 新使用者的預設（前面步驟改過 log f 等）
    sw = sv.SpectrumWindow(app, [si]); app.update()
    ax = sw.fig.axes[0]
    check(sw.v_stype.get() == "mag" and ax.get_ylabel() == "dB" and "Window = Hann" in sw.v_info.get()
          and "NENBW = 1.5 bins" in sw.v_info.get() and "RBW = " in sw.v_info.get() and "Hz" in sw.v_info.get(),
          f"頻譜預設＝振幅 dB；資訊列 Window／NENBW／RBW（{sw.v_info.get()[:70]}）")
    y_mag = np.asarray(sw.lines[1].get_ydata())
    yv, dx = si.slice_range(*app.current_xlim())
    fs_ = app.symbol_rate() / dx
    DS = sv.dsv_spectrum
    L_ = min(len(yv), DS.window_length_for_rbw(fs_, DS.auto_rbw(fs_, True), "hann"))
    r_ = DS.welch(yv, fs_, DS.design_window("hann", L_), 0, None, "centered", detrend=True)
    check(np.allclose(y_mag, sv.to_db(sv.spectrum_type_values("mag", r_))),
          f"預設的值＝MATLAB spectrumAnalyzer 的預設（RBW Auto → Hann {L_} 點、不重疊、雙邊置中；{r_['nseg']} 段平均）")
    sw.v_unit.set("dBFS"); sw.set_spectrum_type("power")
    fsv, how = sw._fullscale_for([si])
    check(sw.fig.axes[0].get_ylabel() == "dBFS" and f"Full scale = {fsv:g}" in sw.v_info.get() and fsv == 512.0 * abs(si.vscale),
          f"功率＋dBFS：Full scale 由原始值猜 10-bit → 512（{sw.v_info.get()[-40:]}）")
    sw.set_spectrum_type("psd")
    check(sw.fig.axes[0].get_ylabel() == "dBFS/Hz", "功率密度＋dBFS → dBFS/Hz")
    sw.v_unit.set("dBm"); sw.v_rload.set("50"); sw.compute()
    check(sw.fig.axes[0].get_ylabel() == "dBm/Hz" and "Reference load = 50 Ω" in sw.v_info.get(), "dBm＋Reference load 50 Ω")
    sw.v_fullscale.set("1000"); sw.v_unit.set("dBFS"); sw.compute()
    check("Full scale = 1000（手動）" in sw.v_info.get(), "Full scale 可手動輸入")
    sw.v_db.set(False); sw.set_spectrum_type("rms")
    check(sw.fig.axes[0].get_ylabel() == "Vrms" and "單位 線性" in sw.v_info.get(), "RMS 線性 → Vrms")
    sw.v_hz.set(False); sw.compute()
    check("cycles/symbol" in sw.v_info.get(), "頻率不用 Hz → RBW 用 cycles/symbol")
    check(app.spec_defaults["stype"] == "rms" and app.spec_defaults["unit"] == "dBFS" and app.spec_defaults["rload"] == "50"
          and app.dump_settings()["spectrum"]["fullscale"] == "1000", "頻譜類型／單位／Full scale／Reference load 存進設定")
    sc = [c for c in strip_controls(sw.strip) if c.winfo_class() == "TCombobox" and str(c.cget("textvariable")) in
          (str(sw.v_unit_label), str(sw.v_fullscale), str(sw.v_rload), str(sw.v_fscale_label))]
    missing = _no_tooltip(sc)
    check(len(sc) == 8 and not missing, f"頻譜／頻譜圖分頁的「刻度」（頻率刻度、參考負載、頻譜單位、滿刻度）各一份、都有 tooltip（缺：{missing}）")
    sw.destroy()
    app.spec_defaults.clear(); app.spec_defaults.update(saved_spec)
    app.sig_tree.selection_set([]); app._on_list_select()
    app.v_tips.set(True); app._on_tips_toggle()
    app.show_all_x()


@step
def s19_bus_display():
    """批次 D（工具缺口 11）：數位匯流排顯示＝MATLAB Logic Analyzer 的顯示格式（自動／類比／數位）、進位制、位元寬度：
    六角框＋數值、縮放重排、點選／資料提示／十字游標／量測／游標讀數用進位制、右鍵選單、屬性區、復原、設定檔。"""
    from matplotlib.backend_bases import MouseEvent
    db = sv.dsv_bus
    path = os.path.join(OUT, "bus_capture.txt")
    vals = np.repeat([0x0012, 0x00AB, 0x0003, 0xBEEF, 0x0012, 0x7F00], 40)
    with open(path, "w") as f:
        f.write("\n".join(f"{v:04X}" for v in vals) + "\n")
    n_before = len(app.signals)
    cursor_was = app.v["cursor"].get()
    s = app.add_text_signal(path)
    app.refresh_list()
    app.plot(keep=False); app.update()
    a = app.render_info["artists"].get(s.uid, {})
    check(s.detected == "HEX" and s.disp == "analog" and not db.is_bus(s) and "bus" not in a and db.auto_bits(s) == 16,
          f"HEX 擷取預設＝類比（不自動判斷、畫線）、位元寬度 16（4 個 hex 字）（{s.detected} {s.disp} {db.auto_bits(s)}）")
    app.sig_tree.selection_set([f"s{s.uid}"]); app._on_list_select()
    app.set_bus_format("digital"); app.update()
    a = app.render_info["artists"].get(s.uid, {})
    check(s.disp == "digital" and db.is_bus(s) and "bus" in a, "手動選「數位」→ 畫成匯流排")
    ax = a["ax"]
    x0, x1 = s.x_span
    ax.set_xlim(x0, x1); app.canvas.draw()
    labs = [t for _x, t in a["bus"].labels()]
    check(HL or labs == ["0012", "00AB", "0003", "BEEF", "0012", "7F00"],
          f"每段值不變的區段一個六角框、框內寫 hex（自動進位制）（{labs}）" + ("（無桌面：圖不跟視窗長大、框太矮寫不下字，略過）" if HL else ""))
    w_run = 40 / s.sps
    ax.set_xlim(x0 + 0.1 * w_run, x0 + 0.9 * w_run); app.canvas.draw()
    check([t for _x, t in a["bus"].labels()] == ["0012"], "放大到一段：只寫看得到的那段（縮放即時重排）")
    ax.set_xlim(x0, x1); app.canvas.draw()
    # 點選／懸停：框裡任何地方都命中這條訊號、索引是最近的樣本
    xm = x0 + 1.5 * w_run
    px, py = ax.transData.transform((xm, a["bus_center"]))
    _px2, py_top = ax.transData.transform((xm, a["bus_center"] + 0.9 * a["bus_half"]))
    hit = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, px, py))
    hit2 = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, px, py_top))
    i_exp = int(round((xm - s.x0) * s.sps))
    check(hit.kind == "line" and hit.id == s.uid and hit2.kind == "line" and hit2.id == s.uid and abs((hit.index or 0) - i_exp) <= 1,
          f"點框中心或靠上緣都命中匯流排、索引＝最近樣本（{hit.kind} {hit.index} vs {i_exp}；{hit2.kind}）")
    tips_was = app.ia.tips_enabled
    app.v_tips.set(True); app._on_tips_toggle()
    t1 = app.ia.add_tip(s.uid, i_exp)
    txt0 = app.ia.tip_artists[t1.id][0].get_text()
    check(txt0.endswith("Y 171"), f"資料提示：自動進位制＝十進位真值（{txt0!r}）")
    # 進位制：選單、套用、復原
    app.sig_tree.selection_set([f"s{s.uid}"]); app._on_list_select()
    m = sv.tk.Menu(app, tearoff=0)
    app._add_bus_menu_items(m)
    top = [m.entrycget(i, "label") for i in range(m.index("end") + 1)]
    subr = app.nametowidget(m.entrycget(1, "menu"))
    radix_labels = [subr.entrycget(i, "label") for i in range(subr.index("end") + 1)]
    check(top == ["顯示格式", "進位制", "位元寬度…"] and len(radix_labels) == 6 and radix_labels[1] == "十六進位（Hex）",
          f"右鍵：顯示格式／進位制（自動＋5 種）／位元寬度…（{top} {radix_labels}）")
    m.destroy()
    menus.clear()
    app._on_list_context(SimpleNamespace(x=5, y=5, x_root=0, y_root=0))
    check(menus and {"顯示格式", "進位制", "位元寬度…"} <= set(menus[-1]), "清單右鍵選單有顯示格式／進位制／位元寬度…")
    n_undo = len(app.undo)
    subr2 = sv.tk.Menu(app, tearoff=0)
    app._add_bus_menu_items(subr2)
    app.nametowidget(subr2.entrycget(1, "menu")).invoke(1)        # 進位制 → 十六進位
    subr2.destroy()
    app.update()
    tip_txt = app.ia.tip_artists[t1.id][0].get_text() if t1.id in app.ia.tip_artists else ""
    check(s.radix == "hex" and len(app.undo) == n_undo + 1 and tip_txt.endswith("Y 0x00AB") and app.p_bus_radix.get() == "十六進位（Hex）",
          f"選單選 Hex：進 Undo、資料提示 Y＝0x00AB、屬性區同步（{tip_txt!r}）")
    app.v["cursor"].set(True); app.plot(keep=True); app.update(); app.canvas.draw()
    pi = app.render_info["panels"].index(s.panel)
    app._draw_cursor(x0 + 3.5 * w_run)
    ctext = app._cursor_items[pi][2].get_text()
    check(f"{s.name} = 0xBEEF" in ctext, f"十字游標：用進位制（{ctext!r}）")
    app._hide_cursor()
    app.update_measurements()
    mx = app.meas_tree.item("m_max", "values") if app.meas_tree.exists("m_max") else ()
    check(bool(mx) and str(mx[0]).startswith("0xBEEF @"), f"量測面板 Max 用進位制（{mx}）")
    app.set_dcursor_mode("two", show_panel=False)
    app.dcur.set_positions([x0 + 0.5 * w_run, x0 + 3.5 * w_run])
    _h, rows = app.update_cursor_readout()
    r = next((r for r in rows if r[0] == s.name), None)
    check(r is not None and all(c.startswith("0x") or c == "—" for c in r[1:3]), f"游標量測 y1／y2 用進位制（{r}）")
    app.set_dcursor_mode("none", show_panel=False)
    app.undo_action(); app.update()
    check(s.radix == "", "復原 → 進位制回到自動")
    app.redo_action(); app.update()
    check(s.radix == "hex", "重做 → Hex")
    # 位元寬度
    app.sig_tree.selection_set([f"s{s.uid}"]); app._on_list_select()
    app.p_bus_bits.set("8"); app.apply_bus_bits(); app.update()
    a = app.render_info["artists"][s.uid]
    a["ax"].set_xlim(x0, x1); app.canvas.draw()
    labs8 = [t for _x, t in a["bus"].labels()]
    check(s.bits == 8 and labs8 == ["12", "AB", "03", "EF", "12", "00"], f"位元寬度 8：補零 2 位、超出取低 8 位（{labs8}）")
    app.p_bus_bits.set("99"); app.apply_bus_bits()
    check(s.bits == 8 and "0～64" in app.status_var.get(), "位元寬度超出範圍：不改、狀態列說明")
    # 顯示格式：屬性區的下拉（類比 → 線；數位 → 匯流排）
    if not HL:
        app.p_bus_disp.set("類比")
        app.bus_disp_cb.event_generate("<<ComboboxSelected>>"); app.update()
    else:
        app.set_bus_format("analog")
    check(s.disp == "analog" and "bus" not in app.render_info["artists"][s.uid], "屬性區格式選「類比」→ 畫回階梯線")
    app.set_bus_format("digital"); app.update()
    check(s.disp == "digital" and "bus" in app.render_info["artists"][s.uid] and app.p_bus_disp.get() == "數位",
          "格式「數位」→ 匯流排；屬性區同步")
    # 設定檔：三個欄位存檔；舊設定檔沒有＝預設
    d = next(x for x in app.dump_settings()["signals"] if x["uid"] == s.uid)
    d_old = {k: v for k, v in d.items() if k not in ("disp", "radix", "bits")}
    s_new, s_old = sv.Signal.from_dict(d), sv.Signal.from_dict(d_old)
    check(d["disp"] == "digital" and d["radix"] == "hex" and d["bits"] == 8 and (s_new.disp, s_new.radix, s_new.bits) == ("digital", "hex", 8)
          and (s_old.disp, s_old.radix, s_old.bits) == ("analog", "", 0), "設定檔存 disp／radix／bits；舊檔沒有＝類比")
    # 收尾
    app.ia.clear_tips()
    app.v_tips.set(tips_was); app._on_tips_toggle()
    app.v["cursor"].set(cursor_was)
    app.sig_tree.selection_set([f"s{s.uid}"])
    app.remove_selected(); app.update()
    app.sig_tree.selection_set([])
    app.show_all_x(); app.update()
    check(len(app.signals) == n_before, "移除測試用的匯流排訊號")


@step
def s20_tools_e_prefs_export_zoom_undo():
    """批次 E（工具缺口 1–4）：偏好設定的字型／匯出／確認頁與「說明」鈕、匯出對話框（格式、DPI、背景、尺寸、只匯出一個 panel）、
    縮小鈕與縮放平移方向限制、復原／重做寫動作名稱；頻譜圖例右鍵只有圖例項目。"""
    from matplotlib.backend_bases import MouseEvent
    import tkinter.font as tkfont
    T = sv.T
    if not app.signals:
        app.expand_tree(True); app.add_all_visible()
    app.plot(); app.show_all_x(); app.update()
    # --- 1 偏好設定 ---
    d = sv.PreferencesDialog(app); d.grab_release(); app.update()
    cats = [d.cat_list.get(i) for i in range(d.cat_list.size())]
    check(cats == ["一般", "外觀", "字型", "繪圖", "匯出", "資料夾", "確認對話框", "鍵盤"] and {"fonts", "export", "confirm", "keyboard"} <= set(d.pages),
          f"偏好設定：類別多了 字型／匯出／確認對話框（{cats}）")
    hw = d.show_help(); app.update()
    sel = hw.toc.curselection()
    check(isinstance(hw, sv.HelpWindow) and sel and hw.toc.get(sel[0]).strip().startswith("偏好設定、匯出圖檔")
          and hw.text.yview()[0] > 0, f"「說明」鈕 → 說明視窗跳到「偏好設定、匯出圖檔」那一節（{hw.toc.get(sel[0]) if sel else None}）")
    hw.destroy()
    vs = d.vars
    vs["ui_font_px"].set("14"); vs["plot_font_pt"].set("12"); vs["export_dpi"].set("300")
    vs["export_bg"].set("白色"); vs["nav_dims"].set("只水平（x）"); vs["confirm_clear"].set(False)
    d._apply(); app.update()
    f_def = tkfont.nametofont("TkDefaultFont")
    check(T.ui_font_px() == 14 and abs(int(f_def.cget("size"))) == T.current().px(14) and pk.styles.plot_fontsize() == 12
          and pk.export.DEFAULTS["dpi"] == 300 and pk.export.DEFAULTS["background"] == "white" and app.ia.nav_dims() == "x"
          and app.toolbar.zoom_constraint == "x" and app.v["confirm_clear"].get() is False,
          f"套用：介面字級 14 px（命名字型跟著變）、圖字級 12 pt、匯出預設 300 DPI／白、方向只水平、清空不確認（{f_def.cget('size')}）")
    ax = app.render_info["axes"][0]
    labs = ax.yaxis.get_majorticklabels()
    check(labs and labs[0].get_fontsize() == 12, "圖字級 12 pt 套到主圖刻度（重畫）")
    view = app.dump_settings()["view"]
    check(view["ui_font_px"] == "14" and view["plot_font_pt"] == "12" and view["export_dpi"] == "300" and view["export_bg"] == "white"
          and view["nav_dims"] == "x" and view["confirm_clear"] is False, "設定檔記錄批次 E 的鍵")
    asked = []
    sv.messagebox.askyesno = lambda *a, **k: (asked.append(a), True)[1]
    try:
        n_sig = len(app.signals)
        app.clear_all(); app.update()
        cleared = not app.signals and not asked
        app.undo_action(); app.update()
    finally:
        del sv.messagebox.askyesno
    check(cleared and len(app.signals) == n_sig, "確認對話框關掉：清空不問、直接清（Ctrl+Z 可復原）")
    cfg = app.dump_settings()
    for k in sv.SignalViewer.VIEW_KEYS_E:
        cfg["view"].pop(k, None)
    vs["ui_font_px"].set("12"); vs["plot_font_pt"].set("10"); vs["export_dpi"].set("150")
    vs["export_bg"].set("主題色"); vs["nav_dims"].set("不限制"); vs["confirm_clear"].set(True)
    d._apply(); d.destroy(); app.update()
    check(T.ui_font_px() == 12 and pk.styles.plot_fontsize() == 10 and app.ia.nav_dims() == "both" and pk.export.DEFAULTS["dpi"] == 150,
          "還原預設字級／方向／匯出預設")
    app.v["ui_font_px"].set("15")
    app.apply_settings(cfg, quiet=True); app.update()
    check(T.ui_font_px() == 15 and app.v["nav_dims"].get() == "both", "舊設定檔沒有批次 E 的鍵：讀得進來、不動目前的值")
    app.v["ui_font_px"].set("12"); app.update()
    # --- 2 匯出對話框 ---
    app.show_all_x(); app.update()
    ax = app.render_info["axes"][0]
    px_, py_ = ax.transData.transform((sum(ax.get_xlim()) / 2, sum(ax.get_ylim()) / 2))
    app.canvas.draw()
    app._on_motion(MouseEvent("motion_notify_event", app.canvas, px_, py_))
    cursor_on = bool(app._cursor_items) and app._cursor_items[0][1].get_visible()
    dlg = app.save_figure_dialog(); app.update()
    exts = [e for e, _d in dlg.formats]
    check(isinstance(dlg, pk.export.ExportDialog) and dlg.title() == "存成圖檔" and exts[:6] == ["png", "jpg", "tif", "pdf", "eps", "svg"]
          and dlg.v_dpi.get() == "150" and dlg.background() == "theme" and "PNG（Portable Network Graphics）" in dlg._fmt_labels,
          f"存成圖檔… → 匯出對話框：格式清單、DPI 150、背景主題色（{exts[:6]}）")
    dlg.v_format.set(dlg._fmt_labels[exts.index("pdf")]); dlg._refresh()
    check("向量" in dlg.v_content.get() and "英吋（向量）" in dlg.v_pixels.get(), f"選 PDF → 內容類型＝向量（{dlg.v_content.get()}）")
    wi, hi = (float(v) for v in app.fig.get_size_inches())
    dlg.v_unit.set("cm"); dlg._on_unit()
    check(abs(float(dlg.v_w.get()) - wi * 2.54) < 0.05 * wi * 2.54 and dlg.size_in() is not None,
          f"單位換成 cm：寬高跟著換算（{dlg.v_w.get()} cm）")
    dlg.v_unit.set("in"); dlg._on_unit(); dlg.reset_size()
    dlg.v_format.set(dlg._fmt_labels[exts.index("png")]); dlg.v_dpi.set("50"); dlg.v_bg.set("透明"); dlg._refresh()
    # 寬高＝對話框欄位顯示的英吋（圖的大小四捨五入到欄位的位數）：Mac 的圖寬高是 Tk 像素÷100、本來就是兩位小數，兩者一樣；
    # Windows 高 DPI 是 Tk 像素÷fig.dpi（175），小數比較多（W10），像素數照欄位上的值算
    sz_ = dlg.size_in() or (0.0, 0.0)
    exp_px = (int(round(sz_[0] * 50)), int(round(sz_[1] * 50)))
    check(dlg.v_pixels.get() == f"輸出 {exp_px[0]} × {exp_px[1]} 像素" and abs(sz_[0] - wi) < 0.006 and abs(sz_[1] - hi) < 0.006,
          f"像素數＝寬高 × DPI（{dlg.v_pixels.get()}；欄位 {sz_} ≈ 圖 {wi:.4f}×{hi:.4f} in）")
    seen = {}
    orig_savefig = app.fig.savefig

    def rec_savefig(*a, **k):
        seen["cursor_visible"] = any(vl.get_visible() or tx.get_visible() for _a, vl, tx in app._cursor_items)
        seen["kw"] = k
        return orig_savefig(*a, **k)
    app.fig.savefig = rec_savefig
    png = os.path.join(OUT, "export_e.png")
    asks = []
    orig_ask = pk.export.ask_export_path
    pk.export.ask_export_path = lambda *a, **k: (asks.append(a), png)[1]
    try:
        dlg.btn_export.invoke(); app.update()
    finally:
        app.fig.savefig = orig_savefig
    from PIL import Image
    im = Image.open(png)
    check(os.path.exists(png) and im.size == exp_px and im.convert("RGBA").getpixel((0, 0))[3] == 0 and not dlg.winfo_exists()
          and asks and asks[0][2] == "signal_viewer.png" and app.status_var.get() == f"圖已存成 {png}",
          f"匯出：檔名對話框預設 signal_viewer.png、PNG {im.size}（預期 {exp_px}）、透明背景、存好關掉對話框並寫狀態列")
    check(cursor_on and seen.get("cursor_visible") is False and seen["kw"].get("dpi") == 50.0,
          "匯出前把十字游標藏起來（不印進檔案）、DPI 照對話框")
    check(pk.export.DEFAULTS["dpi"] == 50 and pk.export.DEFAULTS["background"] == "transparent",
          "對話框記住上次的 DPI／背景（同一個程式裡）")
    pk.export.DEFAULTS.update({"dpi": 150, "background": "theme", "format": "png"})
    # panel 右鍵「只匯出這個 panel…」（重新取座標區：前面的匯出／排程中的重畫可能已經重建了圖，舊的 ax 不在圖上）
    app.update()
    ax = app.render_info["axes"][0]
    px_, py_ = ax.transData.transform((sum(ax.get_xlim()) / 2, sum(ax.get_ylim()) / 2))
    ev = MouseEvent("button_press_event", app.canvas, px_, py_, button=3)
    labels = [it[0] for it in app.ia.menu_items(pk.Hit("empty", ax), ev) if it]
    check("只匯出這個 panel…" in labels, f"圖上右鍵有「只匯出這個 panel…」（{labels[-3:]}）")
    menus.clear()
    app._context_for_hit(pk.Hit("empty", ax), ev)
    check(menus and "只匯出這個 panel…" in menus[-1], "主畫面右鍵選單裡看得到")
    dlg2 = app.ia.export_axes_dialog(ax); app.update()
    p_one = os.path.join(OUT, "panel_e.png")
    dlg2.v_dpi.set("50")
    title2 = dlg2.title()
    got = dlg2.export(p_one); app.update()
    im2 = Image.open(p_one)
    n_vis = sum(1 for a in app.fig.axes if a.get_visible())
    check(got == p_one and dlg2.axes == [ax] and dlg2.initialfile.startswith("signal_viewer_P") and title2 == "只匯出這個 panel"
          and im2.size[1] < exp_px[1] * (0.9 if len(app.render_info["axes"]) > 1 else 1.01) and n_vis == len(app.fig.axes),
          f"只匯出這個 panel：tight bbox（{im2.size} vs 全圖 {exp_px}）、其他 panel 存完恢復顯示"
          f"［got={got == p_one} axes={dlg2.axes == [ax]} file={dlg2.initialfile} title={title2} vis={n_vis}/{len(app.fig.axes)} panels={len(app.render_info['axes'])}］")
    app.plot_toolbar.buttons["save"].invoke(); app.update()
    check(isinstance(getattr(app, "_export_dialog", None), pk.export.ExportDialog) and app._export_dialog.winfo_exists(),
          "工具列存檔鈕＝同一個匯出對話框")
    app._export_dialog.destroy()
    # --- 3 縮小鈕、方向限制 ---
    app.show_all_x(); app.update()
    ax = app.render_info["axes"][0]
    xh, yh = ax.get_xlim(), ax.get_ylim()
    app.ia.zoom_step([ax], *pk.interact.axes_center_px(ax), 3.0)
    xz, yz = ax.get_xlim(), ax.get_ylim()
    app.plot_toolbar.buttons["zoomout"].invoke(); app.update()
    xo, yo = ax.get_xlim(), ax.get_ylim()
    check(abs((xo[1] - xo[0]) / (xz[1] - xz[0]) - 1.5) < 1e-6 and abs((yo[1] - yo[0]) / (yz[1] - yz[0]) - 1.5) < 1e-6,
          f"工具列「縮小」：以座標區中心縮小 1.5 倍（x {xz} → {xo}）")
    for _k in range(6):
        app.plot_toolbar.buttons["zoomout"].invoke()
    app.update()
    check(abs(ax.get_xlim()[0] - xh[0]) < 1e-6 * (xh[1] - xh[0]) + 1e-9 and abs(ax.get_xlim()[1] - xh[1]) < 1e-6 * (xh[1] - xh[0]) + 1e-9,
          "一直按「縮小」停在全部顯示（和 MATLAB 一樣）")
    tip = getattr(app.plot_toolbar.buttons["zoomout"], "_pk_tip", "")
    check(tip.startswith("縮小"), f"縮小鈕有提示文字（{tip[:20]}）")
    cap = []
    orig_popup = sv.tk.Menu.tk_popup

    def rec_popup(self, x, y, entry=None):
        cap.append([("---" if self.type(i) == "separator" else self.entrycget(i, "label")) for i in range(self.index("end") + 1)])
    sv.tk.Menu.tk_popup = rec_popup
    _s35_mode_off()                                              # 只跑 s20（DSV_TEST_ONLY）時 App 還在啟動預設的平移模式：Interactor 的拖曳會被工具列接走
    app.ia.zoom_step([ax], *pk.interact.axes_center_px(ax), 30.0)   # 先放大：方波的邊才會稀疏，中間附近找得到空白處（只跑 s20 時整張都在線上）
    cx, cy = _mid_empty_px(ax)                                   # 中間附近的空白處：只跑 s20（DSV_TEST_ONLY）時座標區中心剛好在線上，開的會是線的選單
    try:
        app.ia.zoom_mode_context(MouseEvent("button_press_event", app.canvas, cx, cy, button=3))
        app.toolbar.mode = "pan/zoom"
        try:
            app.ia.on_press(MouseEvent("button_press_event", app.canvas, cx, cy, button=3))
        finally:
            app.toolbar.mode = ""
    finally:
        sv.tk.Menu.tk_popup = orig_popup
    p_ax = app.render_info["panel_of_ax"].get(id(ax))
    tail = ["---", f"座標（P{p_ax}）", "整張圖的大標題…"]          # 2026-10-27 使用者第二次選單：MATLAB 的模式選單照留，最下面加這兩項
    check(len(cap) == 2 and cap[0][:3] == ["縮小        Shift＋點", "還原視圖", "---"] and len(cap[0]) == 9 and cap[0][6:] == tail,
          f"放大模式右鍵：「還原視圖」之後有分隔線（MATLAB 模式選單），最下面隔一條線加「座標（P{p_ax}）」與「整張圖的大標題…」（{cap[0] if cap else None}）")
    check(len(cap) == 2 and cap[1] == ["還原視圖", "---", "不限方向平移", "只平移 x（水平）", "只平移 y（垂直）"] + tail,
          f"平移模式右鍵：MATLAB 模式選單 Restore View｜Unconstrained／Horizontal／Vertical Pan，最下面加「座標（P{p_ax}）」與大標題"
          f"（{cap[1] if len(cap) > 1 else None}）")
    app.ia.set_nav_dims("y")
    check(app.v["nav_dims"].get() == "y" and "只垂直" in app.status_var.get(), "選「只垂直」→ 設定與狀態列跟著變")
    app.ia.set_nav_dims("x")
    app.show_all_x(); app.update()
    ax = app.render_info["axes"][0]
    ax.set_xlim(*xz); app.canvas.draw()
    y0 = ax.get_ylim()
    app.ia.zoom_step([ax], *pk.interact.axes_center_px(ax), 30.0, "x")   # 先把 x 放大：方波的邊才會稀疏，中間附近找得到空白處
    xz = ax.get_xlim()
    cx, cy = _mid_empty_px(ax)                                   # 中間附近的空白處：拖曳才是平移（中心剛好在線上時按下會變成點線；上緣拖出去不平移）
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, cx, cy, step=1, modifiers={"ctrl"}))    # Ctrl＝明確要求兩軸縮放（畫布可捲動時也縮放）
    check(ax.get_ylim() == y0 and ax.get_xlim() != xz, f"只水平：Ctrl＋滾輪（兩軸）也只縮 x（{xz} → {ax.get_xlim()}）")
    x1 = ax.get_xlim()
    cx, cy = _mid_empty_px(ax)                                   # 滾輪縮放之後畫面變了：再找一次空白處（按在線上會變成點線，不是平移）
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, cx, cy, button=1))
    app.ia.on_motion(MouseEvent("motion_notify_event", app.canvas, cx + 40, cy + 40, button=1, buttons=[1]))
    app.ia.on_release(MouseEvent("button_release_event", app.canvas, cx + 40, cy + 40, button=1))
    check(ax.get_ylim() == y0 and ax.get_xlim() != x1, "只水平：拖曳平移只動 x")
    x2 = ax.get_xlim()
    nav = app.toolbar
    app.plot_toolbar._pan(); app.update()
    try:
        nav.press_pan(MouseEvent("button_press_event", app.canvas, cx, cy, button=1))
        nav.drag_pan(MouseEvent("motion_notify_event", app.canvas, cx + 30, cy + 30, button=1, buttons=[1]))
        nav.release_pan(MouseEvent("button_release_event", app.canvas, cx + 30, cy + 30, button=1))
    finally:
        app.plot_toolbar._pan(); app.update()
    check(ax.get_ylim() == y0 and ax.get_xlim() != x2 and str(nav.mode) == "", "只水平：平移模式拖曳也只動 x（MatlabNav.drag_pan）")
    app.ia.set_nav_dims("both")
    app.show_all_x(); app.update()
    # --- 4 復原／重做寫動作名稱 ---
    app.undo.clear(); app._update_undo_buttons()
    acc_u, acc_r = app.shortcut_label("edit.undo"), app.shortcut_label("edit.redo")       # 快速鍵系統：⌘Z／⌘Y, ⇧⌘Z
    check(app.btn_undo.instate(["disabled"]) and app.btn_undo._pk_tip == f"復原 ({acc_u})" and app.btn_redo._pk_tip == f"重做 ({acc_r})",
          f"沒有可復原的：按鈕停用、提示只寫「復原」（{app.btn_undo._pk_tip}）")
    s0 = app.signals[0]
    app.sig_tree.selection_set([f"s{s0.uid}"]); app._on_list_select(); app.update()
    app.set_marker("o"); app.update()
    desc = app.undo.peek_desc()
    tips_u = [getattr(b, "_pk_tip", "") for b in app._undo_btns]
    check(desc.startswith("標記") and all(t.startswith(f"復原：{desc}") for t in tips_u) and not app.btn_undo.instate(["disabled"]),
          f"改標記後：復原鈕（快速存取列、首頁）提示「復原：{desc}」（{tips_u}）")
    menus.clear()
    ax = app.render_info["axes"][0]
    app._context_for_hit(pk.Hit("empty", ax), MouseEvent("button_press_event", app.canvas, cx, cy, button=3))
    check(menus and menus[-1][0] == f"復原：{desc}" and menus[-1][1] == "重做", f"圖上右鍵：「復原：{desc}」「重做」（{menus[-1][:2] if menus else None}）")
    app.undo_action(); app.update()
    check(app.status_var.get() == f"已復原：{desc}" and app.btn_redo._pk_tip == f"重做：{desc} ({acc_r})",
          f"復原後：狀態列「已復原：…」、重做鈕提示「重做：{desc}」")
    app.redo_action(); app.update()
    check(app.status_var.get() == f"已重做：{desc}" and app.btn_undo._pk_tip.startswith(f"復原：{desc}"), "重做後：狀態列「已重做：…」")
    app.undo_action(); app.update()
    # --- 頻譜視窗：圖例右鍵只有圖例的項目 ---
    sigs = app.signals[:2]
    w = sv.SpectrumWindow(app, sigs); app.update()
    axs = w.fig.axes[0]
    menus.clear()
    w.context_menu(pk.Hit("legend_box", axs), SimpleNamespace(guiEvent=None))
    leg_menu = menus[-1] if menus else None
    w.context_menu(pk.Hit("empty", axs), SimpleNamespace(guiEvent=None))
    check(leg_menu == ["刪除圖例", "圖例位置"] and "只匯出這個 panel…" in menus[-1] and "資料提示模式" in menus[-1],
          f"頻譜圖例右鍵只有「刪除圖例／圖例位置」；空白處仍是完整選單（{leg_menu}）")
    dlg3 = w.plot_toolbar._save(); app.update()
    check(isinstance(dlg3, pk.export.ExportDialog) and dlg3.fig is w.fig, "頻譜視窗的存檔鈕也是匯出對話框")
    dlg3.destroy(); w.destroy(); app.update()


@step
def s_lim_fixes():
    """限制修正：I/Q 衍生訊號的 SPS／offset 跟著來源 I（Q 不一致提示、undo、設定檔）、數位匯流排複製到圖片視窗也畫成匯流排、
    星座圖 EVM 的時序／相位修正（預設關）。"""
    from matplotlib.backend_bases import MouseEvent
    app.show_all_x(); app.update()
    si = app.find_signal("iq.csv;;adc i")
    sq = app.find_signal("iq.csv;;adc q")
    n0 = len(app.signals)
    sps0, off0 = si.sps, si.offset
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    new = app.add_iq_magphase(); app.update()
    mag = next((s for s in new if s.derive == "iq_mag"), None)
    ph = next((s for s in new if s.derive.startswith("iq_phase")), None)
    check(mag is not None and ph is not None and mag.sps == si.sps and ph.offset == si.offset, "衍生訊號建立時用 I 的時間軸")
    app.set_sps(sps0 / 2, [si]); app.update()
    st = app.status_var.get()
    check(mag.sps == sps0 / 2 and ph.sps == sps0 / 2 and mag.x_span == si.x_span and mag.ptype == ph.ptype,
          f"改 I 的 SPS → 幅度／相位跟著（{mag.sps}），x 範圍和 I 一致")
    check("I/Q 時間軸不一致" in st and sq.name in st, f"Q 的 SPS 和 I 不同 → 狀態列提示（{st[-60:]}）")
    app.undo_action(); app.update()
    check(si.sps == sps0 and mag.sps == sps0 and ph.sps == sps0 and "I/Q 時間軸不一致" not in app.status_var.get(),
          "復原 → I 與衍生訊號一起回到原 SPS、提示消失")
    app.redo_action(); app.update()
    check(si.sps == sps0 / 2 and mag.sps == sps0 / 2, "重做 → 衍生訊號又跟著")
    app.undo_action(); app.update()
    app.sig_tree.selection_set([f"s{si.uid}"]); app._on_list_select()
    app.nudge_offset(5); app.update()
    check(si.offset == off0 + 5 and mag.offset == off0 + 5 and ph.offset == off0 + 5 and mag.x_span[0] == si.x_span[0],
          "微調 I 的 offset → 衍生訊號跟著")
    cfg = app.dump_settings()
    dm = next(d for d in cfg["signals"] if d["uid"] == mag.uid)
    check(dm["offset"] == off0 + 5 and dm["sps"] == si.sps, "設定檔存的衍生訊號時間軸＝I 的")
    pt_mag = mag.ptype
    app.set_plot_type("stem", [si]); app.update()
    check(si.ptype == "stem" and mag.ptype == pt_mag and mag.offset == si.offset, "改 I 的繪圖類型：衍生訊號不跟（只跟時間軸）")
    app.undo_action(); app.undo_action(); app.update()
    check(si.offset == off0 and mag.offset == off0, "復原 offset")
    app.sig_tree.selection_set([f"s{s.uid}" for s in app.signals if s.derive]); app._on_list_select()
    app.remove_selected(); app.update()
    check(len(app.signals) == n0 and not any(s.derive for s in app.signals), "清掉衍生訊號")
    # --- 數位匯流排 → 圖片視窗 ---
    path = os.path.join(OUT, "lim_bus.txt")
    vals = np.repeat([0x12, 0xAB, 0x03, 0x7F], 30)
    with open(path, "w") as f:
        f.write("\n".join(f"{v:02X}" for v in vals) + "\n")
    s = app.add_text_signal(path)
    app.refresh_list(); app.plot(keep=False); app.update()
    app.sig_tree.selection_set([f"s{s.uid}"]); app._on_list_select()
    app.set_bus_format("digital"); app.set_bus_radix("hex"); app.update()
    app.copy_to_new_window(); app.update()
    wins = [w for w in app.winfo_children() if isinstance(w, pk.FigureWindow)]
    fw = wins[-1]
    try:
        pc = fw.pc
        ser = pc.state.series[0] if pc.state.series else None
        b = pc.info.bus.get(ser.uid) if ser is not None else None
        pc.canvas.draw()
        labs = [t for _x, t in b["art"].labels()] if b else []
        check(ser is not None and ser.disp == "digital" and ser.radix == "hex" and b is not None and labs == ["12", "AB", "03", "7F"],
              f"複製到新圖片視窗：數位訊號畫成匯流排框、hex 數值（{labs}）")
        lines = dict(pc.lines_in(pc.info.ax_left))
        sd = pc.series_data(ser.uid)
        tt = pc.tip_text(ser.uid, 35, float(sd[0][35]), float(sd[1][35]))
        check(lines.get(ser.uid) is b["hit"] and np.all(sd[1] == b["center"]) and tt.endswith("Y 0xAB"),
              f"圖片視窗：點選用框內 hit 線、提示釘在框中心、提示 Y 用進位制（{tt.splitlines()[-1]}）")
        p = os.path.join(OUT, "lim_bus_fig.json")
        pk.save_json(pc.state, p)
        st2 = pk.load_json(p)
        check(st2.series[0].disp == "digital" and st2.series[0].radix == "hex" and st2.series[0].bits == ser.bits,
              "圖片視窗存檔／開檔保留匯流排設定")
    finally:
        fw.destroy(); app.update()
        app.sig_tree.selection_set([f"s{s.uid}"])
        app.remove_selected(); app.update()
        app.sig_tree.selection_set([])
    check(len(app.signals) == n0, "移除測試用的匯流排訊號")
    # --- 星座圖 EVM：時序／相位修正 ---
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    w = app.open_constellation(); app.update()
    check(w is not None and w.v_sync.get() is False and "sync" in app.const_defaults, "星座圖：時序／相位修正 預設關")
    w.v_xrange.set(False); w.v_dc.set(True); w.v_ref_label.set("QPSK"); w.compute()
    e_raw, st_raw = w.result.get("evm"), w.v_status.get()
    check(e_raw is not None and "已做時序／相位修正" not in st_raw and not w.result["synced"], "關著：EVM 照舊、不標示修正")
    w.v_sync.set(True); w.compute()
    e_fix, st_fix = w.result.get("evm"), w.v_status.get()
    check(w.result["synced"] and "已做時序／相位修正" in st_fix and e_fix is not None and e_fix <= e_raw + 1e-9
          and app.const_defaults["sync"] is True,
          f"開了：狀態列標示「已做時序／相位修正」、EVM 不會變大（{e_raw:.2f}% → {e_fix:.2f}%）、存進設定")
    w.v_ref_label.set("無"); w.compute()
    check(not w.result["synced"] and "時序／相位修正要先選參考星座" in w.v_msg.get(), "沒選參考星座：不修正、提示要先選")
    w.v_sync.set(False); w.v_ref_label.set("無"); w.v_dc.set(False); w.v_xrange.set(True); w.compute()
    w.destroy(); app.update()
    app.sig_tree.selection_set([])


@step
def s17_panel_review():
    """面板組 review：Dock 收合縮到標題列、最大化中隱藏／搬欄先還原、上下移跳過隱藏面板、資料夾工具圖示、
    清單空白右鍵沒選取時變灰、panel 標題區在平移模式的游標與右鍵、Esc 取消拖曳、量測／游標的複製鈕狀態。"""
    from matplotlib.backend_bases import MouseEvent
    d = app.dock
    _legacy_layout(d)                                   # 這組檢查以舊的三欄版面為起點
    caught = []
    orig_popup = sv.tk.Menu.tk_popup

    def grab(self, x, y, entry=None):
        caught.append(self)
    sv.tk.Menu.tk_popup = grab

    def states(m):
        return {m.entrycget(i, "label"): m.entrycget(i, "state") for i in range(m.index("end") + 1)
                if m.type(i) in ("command", "cascade", "checkbutton")}
    try:
        # --- Dock 收合：pane 縮到標題列，同欄的面板長高 ---
        col = d.cols["right"]
        app.update()
        h_sig, h_prop = app.sig_panel.winfo_height(), app.prop_panel.winfo_height()
        app.sig_panel._collapse_btn.invoke(); app.update()
        check(HL or (app.sig_panel.winfo_height() <= app.sig_panel.winfo_reqheight() + 4 and app.prop_panel.winfo_height() > h_prop),
              f"收合「已繪訊號」→ 只剩標題列、訊號屬性長高（{h_sig}→{app.sig_panel.winfo_height()}，{h_prop}→{app.prop_panel.winfo_height()}）")
        app.sig_panel._collapse_btn.invoke(); app.update()
        short = app.winfo_height() < app.theme.px(930)      # 螢幕可用區放不下設計的 940 px 高（macOS 1080p 邏輯解析度＋Dock）：右欄太矮，像素門檻不適用
        check(HL or short or app.sig_panel.winfo_height() > app.sig_panel.winfo_reqheight() // 2,
              f"展開 → 高度回來（{app.sig_panel.winfo_height()}）" + (f"（視窗只有 {app.winfo_height()} px 高：略過像素門檻）" if short else ""))
        # --- 最大化中隱藏它自己：先還原，Dock 不會變空 ---
        d.maximize("folder"); app.update()
        d.post_menu("folder")
        caught[-1].invoke(caught[-1].index(sv.tr("隱藏面板"))); app.update()
        check(d.max_key is None and "plot" not in d.hidden and "folder" in d.hidden and "center" in d.visible_columns(),
              f"最大化中按「隱藏面板」→ 先還原再隱藏，圖還在（hidden={sorted(d.hidden)}）")
        _legacy_layout(d)
        d.maximize("sigs"); d.move("sigs", "left"); app.update()
        check(d.max_key is None and d.order["left"] == ["folder", "sigs"] and "plot" not in d.hidden, "最大化中「移到左欄」→ 先還原、搬過去")
        _legacy_layout(d)
        # --- 上移／下移跳過隱藏面板 ---
        d.post_menu("props")
        st = states(caught[-1])
        check(st[sv.tr("下移")] == "disabled" and st[sv.tr("上移")] == "normal", f"訊號屬性是右欄最後一個看得到的 → 下移灰（{st[sv.tr('下移')]}）")
        d.hide("meas", False); d.order["right"] = ["sigs", "cursors", "props", "meas"]; d._rebuild(); app.update()
        d.shift("props", -1); app.update()
        check([k for k in d.order["right"] if k not in d.hidden][:2] == ["props", "sigs"] or
              [k for k in d.order["right"] if k not in d.hidden] == ["props", "sigs", "meas"],
              f"上移跨過隱藏的游標量測 → 畫面上真的往上一格（{d.order['right']}）")
        d.reset(); app.update()
        # --- 資料夾標題列的展開／收合全部用雙箭頭，不和面板收合鈕同圖示 ---
        icons = [ic for _b, ic in app.folder_panel._tools]
        check("expand_all" in icons and "collapse_all" in icons and "expand" not in icons, f"資料夾工具圖示 {icons}")
        nb = [w for w in _walk(app.folder_panel.body) if isinstance(w, sv.ttk.Button)]
        check(all(getattr(b, "_pk_tip", None) for b in nb), "資料夾面板的按鈕都有 tooltip")
        # --- 清單空白處右鍵、沒有選取：只對選取有意義的項目變灰 ---
        app.sig_tree.selection_set([]); app.update()
        app._on_list_context(SimpleNamespace(x=5, y=max(1, app.sig_tree.winfo_height() - 2), x_root=0, y_root=0))
        st = states(caught[-1])
        check(st[sv.tr("編輯名稱…")] == "disabled" and st[sv.tr("顏色")] == "disabled" and st[sv.tr("移除")] == "disabled"
              and st[sv.tr("頻譜…")] == "normal", "沒選取的清單右鍵：編輯／樣式／移除灰、頻譜照常（沒選取＝全部）")
        app.status_var.set(""); app.edit_field_dialog("label")
        check("先在「已繪訊號」清單選取" in app.status_var.get(), "沒選取叫「編輯名稱…」→ 狀態列說明")
        # --- panel 標題區：平移模式不顯示手形、右鍵選單照樣有；拖曳中 Esc 取消 ---
        app.panel_collapsed = set(); app.plot(); app.update()
        info = app.render_info
        order0 = app.panel_order()
        ax = info["axes"][0]
        lb = ax.yaxis.label.get_window_extent(app.canvas.get_renderer())
        mx, my = (lb.x0 + lb.x1) / 2, (ax.bbox.y0 + ax.bbox.y1) / 2
        app.toolbar.pan()
        MouseEvent("motion_notify_event", app.canvas, mx, my)._process()
        check(app._margin_cursor in ("openhand", "hand2"), "平移模式：標題區也顯示手形（2026-10-25 使用者決定 U3：四種模式都能拖握把）")
        n = len(caught)
        MouseEvent("button_press_event", app.canvas, mx, my, button=3)._process()
        check(len(caught) == n + 1 and sv.tr("隱藏這張圖的訊號") in states(caught[-1]), "平移模式：標題區右鍵選單照樣出現")
        app.toolbar.pan()
        lx = (lb.x0 + lb.x1) / 2
        last_ax = info["axes"][-1]
        MouseEvent("button_press_event", app.canvas, lx, (last_ax.bbox.y0 + last_ax.bbox.y1) / 2, button=1)._process()
        MouseEvent("motion_notify_event", app.canvas, lx, ax.bbox.y1 + 5, button=1)._process()
        dragging = bool(app._strip_drag and app._strip_drag["on"])
        tk_key(app, "Escape"); app.update()
        MouseEvent("button_release_event", app.canvas, lx, ax.bbox.y1 + 5, button=1)._process(); app.update()
        check(dragging and app._strip_drag is None and app.panel_order() == order0, f"拖曳標題區中按 Esc → 取消、順序不變（{app.panel_order()}）")
        # --- 收合 panel 的狀態列說明不再提不存在的 ▸ ---
        app.toggle_panel_collapsed(order0[0]); app.update()
        check("▸" not in app.status_var.get() and "雙擊" in app.status_var.get(), f"收合狀態列：{app.status_var.get()}")
        app.toggle_panel_collapsed(order0[0]); app.update()
        # --- 量測／游標量測的複製鈕：沒有東西可複製時灰 ---
        app.v_panel["meas"].set(True); app._toggle_panel("meas"); app.update()
        app.sig_tree.selection_set([]); app.update(); app.update_measurements()
        check(all(not b.instate(["disabled"]) for b in app._meas_copy_btns), "量測：沒選取＝量全部 → 複製鈕（面板內＋標題列）可按（U6）")
        app.sig_tree.selection_set([app.sig_tree.get_children()[0]]); app.update(); app.update_measurements()
        check(all(not b.instate(["disabled"]) for b in app._meas_copy_btns), "量測：選了訊號 → 複製鈕可按")
        app.set_dcursor_mode("none"); app.update()
        check(all(b.instate(["disabled"]) for b in app._dcur_copy_btns), "游標關著 → 游標量測的複製鈕灰")
        app.set_dcursor_mode("two"); app.update()
        check(all(not b.instate(["disabled"]) for b in app._dcur_copy_btns), "兩條游標 → 複製鈕可按")
        app.set_dcursor_mode("none")
        app.meas_panel.collapse(True)
        check(not app.meas_visible(), "量測面板收合時不計算")
        app.meas_panel.collapse(False)
    finally:
        sv.tk.Menu.tk_popup = orig_popup
        app.sig_tree.selection_set([])
        d.reset(); app.update()


@step
def s21_keyboard_view_undo():
    """MATLAB 圖形視窗：鍵盤縮放／平移進 undo，
    Ctrl+Z 先復原視圖、不動訊號；頻譜視窗也一樣；macOS 的 F2／F3／F4 不是剪下／複製／貼上；畫布 Ctrl+A 全選。"""
    app.plot(); app.update(); app.canvas.draw(); app.update()
    wdg = app.canvas.get_tk_widget()
    app.ia.restore_view(); app.update()
    ax = app.fig.axes[0]
    xl0 = tuple(ax.get_xlim())
    n_sig = len(app.signals)
    for _ in range(3):
        tk_key(wdg, "plus", char="+"); app.update()
    xl1 = tuple(app.fig.axes[0].get_xlim())
    check(xl1 != xl0 and app.undo.peek_desc() == sv.tr("縮放／平移"), f"＋ 連按三下 → 放大、undo 記一筆「縮放／平移」（{app.undo.peek_desc()}）")
    tk_key(wdg, "z", mods="Control"); app.update()
    check(len(app.signals) == n_sig and tuple(app.fig.axes[0].get_xlim()) == xl0,
          f"Ctrl+Z → 復原視圖、訊號不動（{len(app.signals)} 條，x {app.fig.axes[0].get_xlim()}）")
    tk_key(wdg, "y", mods="Control"); app.update()
    check(tuple(app.fig.axes[0].get_xlim()) == xl1 and len(app.signals) == n_sig, "Ctrl+Y → 重做放大")
    tk_key(wdg, "z", mods="Control"); app.update()
    check(sv.tr("縮放／平移") in app.status_var.get(), f"redo 之後再復原，狀態列寫動作名稱（{app.status_var.get()}）")
    tk_key(wdg, "Left"); app.update()
    check(tuple(app.fig.axes[0].get_xlim()) != xl0, "← 平移")
    tk_key(wdg, "z", mods="Control"); app.update()
    check(tuple(app.fig.axes[0].get_xlim()) == xl0 and len(app.signals) == n_sig, "Ctrl+Z → 復原方向鍵平移")
    if sys.platform == "darwin":
        info = " ".join(" ".join(app.tk.call("event", "info", v)) for v in ("<<Cut>>", "<<Copy>>", "<<Paste>>"))
        check("F2" not in info and "F3" not in info and "F4" not in info, f"macOS：F2／F3／F4 不再對應剪下／複製／貼上（{info}）")
    app.sig_tree.selection_set([]); app.update()
    tk_key(wdg, "a", mods="Control"); app.update()
    check(len(app.sig_tree.selection()) == len(app.signals), "畫布上 Ctrl+A → 全選訊號（MATLAB Edit > Select All）")
    app.sig_tree.selection_set([]); app.update()
    sigs = [s for s in app.signals if s.visible][:1]
    sw = sv.SpectrumWindow(app, sigs); app.update(); sw.canvas.draw(); sw.update()
    swdg = sw.canvas.get_tk_widget()
    sw.ia.restore_view(); sw.update()
    s0 = tuple(sw.fig.axes[0].get_xlim())
    tk_key(swdg, "plus", char="+"); sw.update()
    s1 = tuple(sw.fig.axes[0].get_xlim())
    tk_key(swdg, "z", mods="Control"); sw.update()
    s2 = tuple(sw.fig.axes[0].get_xlim())
    tk_key(swdg, "y", mods="Control"); sw.update()
    s3 = tuple(sw.fig.axes[0].get_xlim())
    check(s1 != s0 and s2 == s0 and s3 == s1,
          f"頻譜視窗：＋ 放大 → Ctrl+Z 復原視圖 → Ctrl+Y 重做（MATLAB 圖形視窗 Edit > Undo／Redo；{s0}→{s1}→{s2}→{s3}）")
    sw.destroy(); app.update()


@step
def s21_paste_window_text_column():
    """「貼到圖片視窗」按鈕真的貼到圖片視窗（啟用條件＝CLIPBOARD）；CSV 整欄都是文字＝NaN（MATLAB readmatrix），不畫線、不參與差異比對。"""
    # --- 貼到圖片視窗 ---
    btn = next((b for b in app._clip_btns if str(b.cget("text")) == "貼到圖片視窗"), None)
    check(btn is not None, "訊號 → 剪貼簿 有「貼到圖片視窗」按鈕")
    pk.close_all(); app.update()
    sig = app.signals[0]
    app.sig_tree.selection_set([f"s{sig.uid}"]); app._on_list_select()
    app.copy_signals([sig]); app._update_action_buttons()
    check(not btn.instate(["disabled"]), "複製訊號後「貼到圖片視窗」啟用（看 CLIPBOARD）")
    btn.invoke(); app.update()
    w1 = pk.active_window()
    check(isinstance(w1, pk.FigureWindow) and len(w1.pc.state.series) == 1, f"沒有圖片視窗 → 開新的並貼上（{len(w1.pc.state.series)} 條）")
    w2 = app.paste_to_figure_window(); app.update()
    check(w2 is w1 and len(w1.pc.state.series) == 2 and "已把 1 條訊號貼到" in app.status_var.get(),
          f"已有圖片視窗 → 疊到同一個（{len(w1.pc.state.series)} 條；{app.status_var.get()[:30]}）")
    pk.close_all(); app.update()
    saved = list(sv.CLIPBOARD); sv.CLIPBOARD[:] = []; app._update_action_buttons()
    check(btn.instate(["disabled"]) and app.paste_to_figure_window() is None, "剪貼簿空的：按鈕變灰、直接呼叫只寫狀態列")
    sv.CLIPBOARD[:] = saved
    # --- 整欄文字 → NaN ---
    path = os.path.join(ROOT, "text_col.csv")
    with open(path, "w", encoding="utf-8") as f:
        f.write("Time, val, note\n")
        for k in range(200):
            f.write(f"{k} us, {k % 7}, ERR\n")
    n0 = len(app.signals)
    dlg = sv.CsvImportDialog(app, path, sv.get_csv_table(path), None); app.update()
    for name in dlg.rows:
        dlg.rows[name]["add"] = True
    dlg.v_merge.set(True)
    dlg._on_add(); app.update()
    sn = next((s for s in app.signals if s.path == path and s.column == "note"), None)
    sval = next((s for s in app.signals if s.path == path and s.column == "val"), None)
    check(sn is not None and sval is not None and len(app.signals) == n0 + 2, "文字欄與數值欄都加進清單")
    d = sn.get_data()
    check(len(d) == 200 and not np.isfinite(d).any(), "整欄文字＝全部 NaN（不再是 0）")
    app.plot(keep=False); app.update()
    app.after(450, lambda: None); app.update(); time.sleep(0.5); app.update()
    check("整欄沒有數值" in app.status_var.get(), f"狀態列說明整欄沒有數值（{app.status_var.get()[:40]}）")
    segs, frac, _ = sv.diff_segments([sval, sn], 0.0)
    check(not segs and frac == 0.0, f"差異比對不把 NaN 欄算成差異（{len(segs)} 段、{frac}）")
    app.sig_tree.selection_set([f"s{sn.uid}"]); app._on_list_select()
    try:
        app.update_measurements(); ok_m = True
    except Exception as e:
        ok_m = False
    check(ok_m, "量測面板遇全 NaN 訊號不出錯")
    app.sig_tree.selection_set([f"s{sn.uid}", f"s{sval.uid}"]); app._on_list_select()
    app.remove_selected(); app.update()
    check(len(app.signals) == n0, "移除測試用的文字欄 CSV")


@step
def s22_home_regroup_panel_handle():
    """首頁重新分類（檔案／資料夾／檢視／資料提示／工作階段／環境／說明）、PLOT/REFRESH 拿掉（重新掃描兼重新讀檔）、
    小按鈕改圖示、panel 握把（左邊整塊含 y 刻度都能拖，MATLAB y 尺規平移讓出）、刪除單一 panel。"""
    from matplotlib.backend_bases import MouseEvent
    ttk = sv.ttk
    home = app.strip.tabs["home"]
    names = [str(sec.title) if hasattr(sec, "title") else str(sec.cget("text")) for sec in home.sections]
    check(names == ["檔案", "資料夾", "工作階段", "環境", "說明"], f"首頁分區順序（{names}）")
    hb = app.home_btns
    check("plot" not in hb and not app.bind("<F5>") and not hasattr(app, "refresh_plot"), "PLOT / REFRESH 按鈕、F5、refresh_plot 都拿掉")
    texts = [str(b.cget("text")) for b in app.strip.qab.winfo_children() if isinstance(b, ttk.Button)]
    check("PLOT" not in texts, f"快速存取列沒有 PLOT（{texts}）")
    bar = app.root_entry.master
    small = [w for w in bar.winfo_children() if isinstance(w, ttk.Button)]
    check(len(small) == 5 and all(str(w.cget("image")) and not str(w.cget("text")) for w in small) and not _no_tooltip(small),
          f"根資料夾列：返回／前進／上一層／瀏覽／重新掃描都是圖示鈕、有 tooltip（{len(small)}）")
    for b in (app._meas_rows_btn, app._meas_copy_btns[0], app._dcur_copy_btns[0]):
        check(bool(str(b.cget("image"))) and not str(b.cget("text")), f"面板小按鈕改圖示（{b.winfo_class()}）")
    # 重新掃描兼重新讀檔：改寫一個已載入的檔案後 rescan → 資料更新
    path = os.path.join(ROOT, "digital", "clk.txt")
    s_clk = next((s for s in app.signals if s.path == path), None) or app.add_text_signal(path)
    app.refresh_list(); app.plot(keep=False); app.update()
    old = s_clk.get_data().copy()
    time.sleep(1.1)                                   # mtime 解析度
    with open(path, "w") as f:
        f.write("\n".join(["1", "1", "0", "0"] * 200) + "\n")
    app.rescan(); app.update()
    new = s_clk.get_data()
    check(len(new) == 800 and not np.array_equal(old[:4], new[:4]) and "重新讀取 1 個改過的檔案" in app.status_var.get(),
          f"重新掃描：重新載入被改寫的檔案並重畫（{app.status_var.get()[-30:]}）")
    # panel 握把：P 標籤與 y 刻度區都能拖，換順序
    sa = app.find_signal("iq.csv;;adc i"); sq = app.find_signal("iq.csv;;adc q")
    if sa.panel == sq.panel:
        sq.panel = app.next_panel(); app.refresh_list(); app.plot(keep=False)
    app.update(); app.canvas.draw()
    order0 = app.panel_order()
    panels, axes = app.render_info["panels"], app.render_info["axes"]
    ax_first, ax_last = axes[0], axes[-1]
    ren = app.canvas.get_renderer()
    ticks = [t.get_window_extent(ren) for t in ax_first.get_yticklabels() if t.get_text()]
    tx = (min(b.x0 for b in ticks) + max(b.x1 for b in ticks)) / 2 if ticks else ax_first.bbox.x0 - 3
    ty0 = (ax_first.bbox.y0 + ax_first.bbox.y1) / 2
    ty1 = ax_last.bbox.y0 + 5
    check(ax_first.get_ylabel().startswith("≡ P"), f"panel 標籤有握把記號（{ax_first.get_ylabel()!r}）")
    check(app._margin_panel(MouseEvent("motion_notify_event", app.canvas, tx, ty0)) == panels[0]
          and app.ia.ruler_hit(MouseEvent("motion_notify_event", app.canvas, tx, ty0)) is None,
          "y 刻度數字區也是 panel 握把（主視窗不做 y 尺規平移）")
    def proc(name, **kw):
        ev = MouseEvent(name, app.canvas, kw.pop("x"), kw.pop("y"), **kw); app.canvas.callbacks.process(name, ev)
    yl0 = ax_first.get_ylim()
    proc("button_press_event", x=tx, y=ty0, button=1)
    for k in range(1, 8):
        proc("motion_notify_event", x=tx, y=ty0 + (ty1 - ty0) * k / 7)
    proc("button_release_event", x=tx, y=ty1, button=1)
    app.update()
    order1 = app.panel_order()
    check(order1 != order0 and order1[-1] == order0[0] and app.render_info["axes"][-1].get_ylim() == yl0,
          f"在 y 刻度區按住拖到最下面 → panel 順序改變、不是平移 y（{order0} → {order1}）")
    app.undo_action(); app.update()
    check(app.panel_order() == order0, "Ctrl+Z 復原 panel 順序")
    # 右鍵選單：上移／下移／刪除這個 panel
    ax0 = app.render_info["axes"][0]
    ev = MouseEvent("button_press_event", app.canvas, (ax0.bbox.x0 + ax0.bbox.x1) / 2, (ax0.bbox.y0 + ax0.bbox.y1) / 2, button=3)
    menus.clear()
    app._context_for_hit(pk.Hit("empty", ax0), ev)
    lab = menus[-1] if menus else []
    check({"上移 panel", "下移 panel", "刪除這個 panel"} <= set(lab), f"圖上右鍵有 上移／下移／刪除這個 panel（{lab[-6:]}）")
    # 刪除單一 panel → 一次 undo 復原
    p_del = app.panel_order()[0]
    n_in = sum(1 for s in app.signals if s.panel == p_del)
    n0, n_undo = len(app.signals), len(app.undo)
    was = app.v["confirm_clear"].get(); app.v["confirm_clear"].set(False)
    k = app.delete_panel(p_del); app.update()
    check(k == n_in and len(app.signals) == n0 - n_in and p_del not in app.panel_order() and len(app.undo) == n_undo + 1
          and f"已刪除 P{p_del}" in app.status_var.get(), f"刪除 P{p_del}：{k} 條訊號移除、進 undo（{app.status_var.get()[:30]}）")
    app.undo_action(); app.update()
    check(len(app.signals) == n0 and app.panel_order() == order0, "復原 → 訊號與 panel 順序都回來")
    app.v["confirm_clear"].set(was)
    check(app.delete_panel(999) == 0 and "沒有訊號" in app.status_var.get(), "刪除不存在的 panel：狀態列說明、不出錯")
    # 使用者的流程：點 P2 的訊號（資料提示模式：釘提示，不是選取）→ ⌘C → 點 P1 → ⌘V → 貼到 P1
    app.sig_tree.selection_set([]); app._on_list_select(); app.ia.clear_tips(); app.update()
    panels, axes = app.render_info["panels"], app.render_info["axes"]
    src = next(s for s in app.signals if s.panel == panels[-1] and not s.derive)
    dst_p = panels[0]
    xs, ys, _, _ = app.ia.host.series_data(src.uid)
    ax_src = axes[-1]
    px_, py_ = ax_src.transData.transform((xs[len(xs) // 2], ys[len(xs) // 2]))
    proc("button_press_event", x=px_, y=py_, button=1); proc("button_release_event", x=px_, y=py_, button=1); app.update()
    check(len(app.ia.model.tips) == 1 and not app.sig_tree.selection(), "點線條＝釘資料提示、清單沒選取（MATLAB 預設）")
    app.canvas.get_tk_widget().event_generate("<<Copy>>"); app.update()
    check(len(app._sig_clip) == 1 and app._sig_clip[0]["key"] == src.key and "已複製 1 條訊號" in app.status_var.get(),
          f"沒有選取時 ⌘C 複製資料提示所在的訊號（{app.status_var.get()[:30]}）")
    ax_dst = axes[0]
    proc("button_press_event", x=(ax_dst.bbox.x0 + ax_dst.bbox.x1) / 2, y=ax_dst.bbox.y1 - 4, button=1)
    proc("button_release_event", x=(ax_dst.bbox.x0 + ax_dst.bbox.x1) / 2, y=ax_dst.bbox.y1 - 4, button=1); app.update()
    n_before = len(app.signals)
    app.canvas.get_tk_widget().event_generate("<<Paste>>"); app.update()
    pasted = [s for s in app.signals if s.panel == dst_p and s.path == src.path and s.column == src.column and s is not src]
    check(len(app.signals) == n_before + 1 and len(pasted) == 1 and f"已貼上 1 條訊號到 P{dst_p}" in app.status_var.get(),
          f"點 P{dst_p} → ⌘V：貼到 P{dst_p}（{app.status_var.get()[:30]}）")
    app.undo_action(); app.update()
    check(len(app.signals) == n_before, "復原貼上")
    app.ia.clear_tips()
    with open(path, "w") as f:
        f.write("# clock\n" + "\n".join(map(str, np.tile([0, 0, 1, 1], 200))) + "\n")
    app.rescan(quiet=True); app.update()
    # 顯示／隱藏面板不會把欄重排成 reqwidth／reqheight（A 檢查：顯示訊號屬性後左欄跳到 532、已繪訊號被壓到 49 px）
    d = app.dock
    d.reset(); app.update()
    for _ in range(5):
        app.update_idletasks(); app.update()
    _m = d.winfo_ismapped
    d.winfo_ismapped = lambda: False
    check(d._geometry_snapshot() is None, "視窗沒顯示（最小化／無桌面）時不量版面、不做還原")
    d.winfo_ismapped = _m
    if HL:
        check(True, "（無桌面：面板沒有實際大小，顯示／隱藏面板的版面像素檢查略過）")
        return
    if app.winfo_height() < app.theme.px(930):
        # 螢幕可用區放不下設計的 940 px 高（macOS 1080p 邏輯解析度＋Dock 時 Tk 會拒絕，啟動後縮到 893）：欄高比設計矮、
        # 面板的 reqheight 又固定，45%／回到原本的像素門檻不成立（HEAD 在同一台也一樣），只在設計高度檢查
        check(True, f"（視窗只有 {app.winfo_height()} px 高，不到設計的 940：顯示／隱藏面板的版面像素檢查略過）")
        return
    w0 = d._col_width("left"); h_folder0, h_sigs0 = app.folder_panel.winfo_height(), app.sig_panel.winfo_height()
    d.hide("props", False)
    for _ in range(5):
        app.update_idletasks(); app.update()
    w1 = d._col_width("left"); hs = {k: d.panels[k].winfo_height() for k in ("folder", "sigs", "props")}
    H = d.cols["left"].winfo_height()
    check(app.prop_panel.winfo_ismapped() and hs["sigs"] >= d.MIN_PANE_H and hs["folder"] >= d.MIN_PANE_H
          and hs["props"] <= H * d.NEW_PANE_SHARE + 4 and w1 <= max(w0, app.prop_panel.winfo_reqwidth()) + 4,
          f"顯示訊號屬性：新面板最多 45% 欄高、其餘面板留著、欄寬只加到放得下（{w0}→{w1}，高 {hs}）")
    d.hide("props", True)
    for _ in range(5):
        app.update_idletasks(); app.update()
    check(abs(d._col_width("left") - w0) <= 4 and abs(app.folder_panel.winfo_height() - h_folder0) <= 6
          and abs(app.sig_panel.winfo_height() - h_sigs0) <= 6,
          f"再隱藏：欄寬與面板高度回到原本（{w0} vs {d._col_width('left')}；{h_folder0}/{h_sigs0} vs "
          f"{app.folder_panel.winfo_height()}/{app.sig_panel.winfo_height()}）")


@step
def s23_tabs_color_wav_dnd():
    """三個分頁重新分類；右鍵「顏色」色塊直接換色；WAV／.npy 當表格、拖放加入（add_dropped_paths）。"""
    ttk = sv.ttk
    names = {k: [str(sec.title) for sec in app.strip.tabs[k].sections] for k in app.strip.tabs}
    check(list(app.strip.tabs) == ["home", "signal", "preprocess", "style", "analyze", "measure", "view", "export"],
          f"8 個分頁（第四批在「訊號」後面加「前處理」）（{list(app.strip.tabs)}）")
    check(names["signal"] == ["編輯", "順序", "Panel", "參數", "突波抑制", "比對", "轉態"], f"訊號分頁分區（{names['signal']}）")
    check(names["style"] == ["線條", "數位顯示"], f"樣式分頁分區（{names['style']}）")
    check(names["analyze"] == ["分析視窗"], f"分析分頁分區（{names['analyze']}）")
    check(names["measure"] == ["量測", "統計", "峰值", "雙位準", "資料游標", "資料提示"],
          f"量測分頁分區（Time Scope 的 STATISTICS／PEAKS／BILEVEL 在資料游標前面）（{names['measure']}）")
    check(names["view"] == ["顯示", "互動", "縮放", "感興趣區域", "座標", "版面", "外觀"],
          f"檢視分頁分區（感興趣區域＝Signal Analyzer 的 REGION OF INTEREST）（{names['view']}）")
    check(names["export"] == ["圖片視窗", "圖檔"], f"匯出分頁分區（{names['export']}）")
    lay = app.dock.layout()
    check(lay["columns"]["left"][:2] == ["folder", "sigs"] and "props" in lay["hidden"] and lay["columns"]["center"] == ["plot", "meas"],
          f"預設版面：左欄 資料夾、已繪訊號（訊號屬性隱藏）｜右邊整個是圖（量測面板在圖的下方）（{lay['columns']} hidden={lay['hidden']}）")
    # 舊存檔的版面（沒有 layout_version、訊號屬性在右欄）→ 不套用，改用新預設；新存檔（layout_version 2 以上）照存的套
    cfg_old = app.dump_settings(); cfg_old.pop("layout_version", None)
    cfg_old["layout"] = {"columns": {"left": ["folder"], "center": ["plot"], "right": ["sigs", "props", "meas", "cursors"]}, "hidden": ["meas", "cursors"]}
    app.apply_settings(cfg_old, quiet=True); app.update()
    lay = app.dock.layout()
    check(lay["columns"]["left"][:2] == ["folder", "sigs"] and "props" in lay["hidden"], f"舊版面存檔 → 改用新預設、訊號屬性隱藏（{lay['columns']}）")
    cfg_new = app.dump_settings(); cfg_new["layout"]["hidden"] = [h for h in cfg_new["layout"]["hidden"] if h not in ("props", "meas", "cursors")]
    check(cfg_new.get("layout_version") == sv.LAYOUT_VERSION, "新存檔寫 layout_version")
    app.apply_settings(cfg_new, quiet=True); app.update()
    hid = app.dock.layout()["hidden"]
    check("props" in hid and "meas" in hid and "cursors" not in hid,
          "新存檔照存的套用（游標量測面板顯示），但「訊號屬性」「量測」只在這次工作階段顯示、還原時一律隱藏（2026-10-24 使用者指定）")
    app.dock.reset(); app.update()
    check(len(app.strip.tabs["signal"].sections[3].winfo_children()) >= 1 and app._ts_cols.get("params1") is not None
          and str(app._ts_cols["params1"][1].winfo_children()[0].winfo_children()[1].cget("textvariable")) == str(app.p_sps),
          "訊號 → 參數：SPS 等設定列在工具列上（和訊號屬性面板共用同一組變數）")
    # 右鍵 → 顏色 → 色塊
    sig = app.signals[0]
    app.sig_tree.selection_set([f"s{sig.uid}"]); app._on_list_select()
    m = sv.tk.Menu(app, tearoff=0)
    app._add_style_menu_items(m)
    labels = [m.entrycget(i, "label") for i in range(m.index("end") + 1) if m.type(i) != "separator"]
    sub = app.nametowidget(m.entrycget(labels.index("顏色"), "menu"))
    sub_labels = [sub.entrycget(i, "label") for i in range(sub.index("end") + 1) if sub.type(i) != "separator"]
    pal = app.render_info.get("palette") or sv.PALETTE
    check(labels[0] == "顏色" and sub_labels[-2:] == ["自動", "自訂…"] and len(sub_labels) == min(10, len(pal)) + 2
          and sub.entrycget(0, "image"), f"右鍵 → 顏色：色塊 ×{len(pal)}＋自動＋自訂…（{sub_labels[:2]}）")
    n_undo = len(app.undo)
    sub.invoke(2); app.update()
    check(sig.color == pal[2] and len(app.undo) == n_undo + 1 and app.render_info["artists"][sig.uid]["line"].get_color() == pal[2]
          and "線色改成" in app.status_var.get(), f"點第 3 個色塊 → 線色 {pal[2]}、進 undo")
    app.undo_action(); app.update()
    check(sig.color is None, "復原 → 自動色")
    m.destroy()
    # WAV／npy：表格介面、資料夾樹認得、拖放加入
    import wave
    wdir = os.path.join(ROOT, "audio"); os.makedirs(wdir, exist_ok=True)
    pw = os.path.join(wdir, "tone.wav")
    with wave.open(pw, "wb") as wf:
        wf.setnchannels(2); wf.setsampwidth(2); wf.setframerate(64000)
        fr = np.column_stack([(1000 * np.sin(np.arange(640) / 10)).astype("<i2"), np.arange(640, dtype="<i2")]).astype("<i2")
        wf.writeframes(fr.tobytes())
    pn = os.path.join(wdir, "vec.npy"); np.save(pn, np.arange(300.0))
    tbl = sv.get_csv_table(pw)
    check(sv.is_csv_file(pw) and sv.is_csv_file(pn) and tbl.names == ["ch1", "ch2"] and tbl.estimate_rate() == 64000.0, "WAV 走表格路徑：ch1／ch2、取樣率 64000")
    app.rescan(quiet=True); app.update()
    kinds = {n["path"]: n["kind"] for n in app.tree_map.values() if n.get("kind") in ("csv", "text")}
    check(kinds.get(pw) == "csv" and kinds.get(pn) == "csv", "資料夾樹列出 .wav／.npy（表格型）")
    n0 = len(app.signals)
    added = app.add_dropped_paths([pw, pn, os.path.join(ROOT, "digital", "clk.txt"), os.path.join(wdir, "nope.xyz")]); app.update()
    sw = [s for s in app.signals if s.path == pw]
    check(added >= 3 and len(sw) == 2 and any(s.path == pn for s in app.signals) and abs(sw[0].sps - 64000.0 / app.symbol_rate()) < 1e-6
          and "拖放加入" in app.status_var.get() and "不認得" in app.status_var.get(),
          f"拖放：WAV 2 聲道＋npy＋txt 直接加入並畫圖、SPS 由取樣率算、不認得的檔案在狀態列（{app.status_var.get()[:60]}）")
    app.undo_action(); app.update()
    check(len(app.signals) == n0, "復原拖放加入")
    pbad = os.path.join(wdir, "broken.wav")
    with open(pbad, "wb") as f:
        f.write(b"\xff\xfe\x00\x00garbage" * 50)
    n1 = len(app.signals)
    app.add_dropped_paths([pbad]); app.update()
    check(len(app.signals) == n1 and "不認得或讀不了" in app.status_var.get() and "broken.wav" in app.status_var.get(),
          f"拖放：讀不了的 WAV（表格型）列進狀態列的壞檔案清單，不會悄悄略過（{app.status_var.get()[:60]}）")
    sub_root = os.path.join(ROOT, "audio")
    app.add_dropped_paths([sub_root]); app.update()
    check(os.path.abspath(app.root_dir) == os.path.abspath(sub_root) and "根資料夾改成" in app.status_var.get(), "拖資料夾 → 變成根資料夾")
    app.root_var.set(ROOT); app.rescan(quiet=True); app.update()
    if sys.platform == "darwin":
        try:
            import tkinterdnd2  # noqa: F401
            check(app.dnd_available, "tkinterdnd2 有裝：主視窗是放置目標")
        except ImportError:
            pass


@step
def s24_shortcuts():
    """鍵盤快速鍵系統（仿 MATLAB Preferences ▸ Keyboard ▸ Shortcuts）：預設鍵分派、輸入框放行、清單裡的方向鍵不平移、
    畫布的鍵交給 Interactor、偏好設定 → 鍵盤 改鍵（衝突詢問、移除、還原）、存進設定檔並還原、匯出／匯入 JSON。"""
    import dsv_keys
    from types import SimpleNamespace as NS
    km = app.keymap
    mod = "Command" if sys.platform == "darwin" else "Control"
    check(len(app.actions) >= 70 and all(a in app.actions for a in sv.SignalViewer.ACTION_DEFAULTS) and not km.conflicts()
          and km.lookup(dsv_keys.canonical("Mod+Z")) == ["edit.undo"] and km.lookup(dsv_keys.canonical("Mod+Y")) == ["edit.redo"]
          and km.lookup(dsv_keys.canonical("Shift+Mod+Z")) == ["edit.redo"],
          f"登記 {len(app.actions)} 個動作、預設鍵無衝突、⌘Z／⌘Y／⌘⇧Z＝復原／重做")
    if not app.signals:
        app.add_all_visible(); app.plot(); app.update()
    n = len(app.signals)
    app.sig_tree.selection_set(app.sig_tree.get_children()[:1]); app.update()
    tk_key(app.sig_tree, "Delete"); app.update()
    check(len(app.signals) == n - 1, "清單上按 Delete → 移除選取的訊號（edit.remove，只移一次）")
    tk_key(app.sig_tree, "z", mods=mod); app.update()
    check(len(app.signals) == n, f"{mod}+Z → 復原")
    tk_key(app.sig_tree, "y", mods=mod); app.update()
    check(len(app.signals) == n - 1, f"{mod}+Y → 重做")
    tk_key(app.sig_tree, "z", mods=mod); app.update()
    tk_key(app.sig_tree, "Z", mods=f"{mod}-Shift"); app.update()
    check(len(app.signals) == n - 1, f"{mod}+Z 復原後 {mod}+Shift+Z → 重做（MATLAB／macOS 慣例）")
    app.undo_action(); app.update()
    # 輸入框有焦點：⌘Z 交給輸入框（不復原）、F5 這種還是動作
    app.remove_selected() if app.selected_signals() else None
    app.update(); n2 = len(app.signals)
    tk_key(app.root_entry, "z", mods=mod); app.update()
    check(len(app.signals) == n2, "位址列有焦點時 ⌘Z／Ctrl+Z 交給輸入框，不復原")
    hits = []
    orig = app.actions["file.rescan"].run
    app.actions["file.rescan"].run = lambda: hits.append(1)      # 動作登記的是方法本身：換掉動作的 run 才攔得到
    tk_key(app.root_entry, "F5"); app.update()
    app.actions["file.rescan"].run = orig
    check(hits == [1], "位址列有焦點時 F5 仍是「重新掃描」（F 鍵不是打字）")
    app.undo_action(); app.update()
    # 清單裡的方向鍵不平移圖；畫布有焦點時 Home／方向鍵由 Interactor 處理（分派器放行）
    axes = [ax for ax in app.fig.get_axes() if ax.get_visible()]
    xl0 = axes[0].get_xlim()
    tk_key(app.sig_tree, "Left"); app.update()
    check(axes[0].get_xlim() == xl0, "已繪訊號清單有焦點時 ← 不平移圖（清單自己的鍵）")
    check(app.dispatch_shortcut("Left", app.canvas.get_tk_widget()) is None and app.dispatch_shortcut("Home", app.canvas.get_tk_widget()) is None
          and app.dispatch_shortcut(dsv_keys.canonical("Mod+Z"), app.canvas.get_tk_widget()) == "break",
          "畫布有焦點：←／Home 放行給 Interactor；⌘Z 仍由分派器復原")
    app.redo_action(); app.update()
    # 從別的元件按 Home → plot.restore_view 走 Interactor.run_key_action
    app.show_all_x(); app.update()
    full = app.current_xlim()
    ax_h = app.render_info["axes"][0]
    app.ia.zoom_step([ax_h], *pk.interact.axes_center_px(ax_h), 2.0); app.update()
    zoomed = app.current_xlim()
    r = app.dispatch_shortcut("Home", app.folder_panel)
    app.update()
    back = app.current_xlim()
    check(r == "break" and zoomed != full and abs(back[0] - full[0]) < 1e-6 * max(1.0, abs(full[1] - full[0])) and abs(back[1] - full[1]) < 1e-6 * max(1.0, abs(full[1] - full[0])),
          f"面板上按 Home → 還原視圖（plot.restore_view）：{zoomed} → {back}（原始 {full}）")
    # 工具提示帶快速鍵；復原按鈕提示跟著 keymap
    tip = app.home_btns["rescan"]._pk_tip
    check(tip.endswith(" (F5)") and ("⌘Z" in app.btn_undo._pk_tip if sys.platform == "darwin" else "Ctrl+Z" in app.btn_undo._pk_tip),
          f"按鈕提示附上快速鍵（{tip[-8:]}；{app.btn_undo._pk_tip}）")
    # 偏好設定 → 鍵盤：選「格線」、按 F6 新增；F5 給格線（問要不要搶）；移除；套用
    d = sv.PreferencesDialog(app); d.grab_release(); app.update()
    d._show("keyboard"); app.update()
    rows = d.kb_tree.get_children()
    check(len(rows) == len(app.actions) and d.kb_tree.exists("view.grid") and d.kb_tree.item("edit.undo")["values"][1] in ("⌘Z", "Ctrl+Z"),
          f"鍵盤頁列出 {len(rows)} 個動作，復原顯示 {d.kb_tree.item('edit.undo')['values'][1]}")
    d.kb_filter.set("格線"); app.update()
    check(list(d.kb_tree.get_children()) == ["view.grid"], "搜尋「格線」只剩那一列")
    d.kb_tree.selection_set("view.grid"); d._kb_select()
    d._kb_capture_key(NS(keysym="F6", state=0))
    check(d.kb_capture.get() == "F6" and d._kb_spec == "F6", "在框裡按 F6 → 顯示 F6")
    d._kb_add(); app.update()
    check(d.km.bindings("view.grid") == (dsv_keys.canonical("Mod+G"), "F6") and app.keymap.bindings("view.grid") == (dsv_keys.canonical("Mod+G"),),
          "新增 F6 給格線（套用前主程式不變）")
    asked = []
    orig_ask = sv.messagebox.askyesno
    sv.messagebox.askyesno = lambda *a, **k: asked.append(a[:1]) or True       # 「快速鍵已被使用」→ 回答「是」（搶過來）
    try:
        d._kb_capture_key(NS(keysym="F5", state=0)); d._kb_add(); app.update()
    finally:
        sv.messagebox.askyesno = orig_ask
    check(len(asked) == 1 and d.km.bindings("file.rescan") == () and "F5" in d.km.bindings("view.grid"),
          "F5 已是「重新掃描」的鍵 → 詢問後改給格線、重新掃描失去 F5")
    d.kb_list.selection_clear(0, "end"); d.kb_list.selection_set(0); d._kb_remove(); app.update()
    check(d.km.bindings("view.grid") == ("F6", "F5"), "移除選取的快速鍵（⌘G）")
    d._apply(); app.update()
    g0 = app.v["grid"].get()
    tk_key(app.sig_tree, "F6"); app.update()
    check(app.keymap.bindings("view.grid") == ("F6", "F5") and app.v["grid"].get() != g0 and app.keymap.lookup("F5") == ["view.grid"]
          and app.home_btns["rescan"]._pk_tip == app.home_btns["rescan"]._pk_tip_base,
          "套用後 F6 切換格線、F5 不再是重新掃描（提示也拿掉快速鍵）")
    tk_key(app.sig_tree, "F6"); app.update()
    cfg = app.dump_settings()
    check(cfg["shortcuts"]["shortcuts"] == {"file.rescan": [], "view.grid": ["F6", "F5"]}, "設定檔只存改過的動作")
    d.kb_filter.set(""); app.update()                 # 搜尋框還是「格線」：清掉才看得到其他動作
    d.kb_tree.selection_set("file.rescan"); d._kb_reset(); d._apply(); app.update()
    check(app.keymap.bindings("file.rescan") == ("F5",) and app.keymap.conflicts() == {"F5": ["file.rescan", "view.grid"]}
          and d.kb_tree.item("view.grid")["values"][1].startswith("⚠") and "1" in d.kb_conflict_var.get(),
          "還原重新掃描的預設 → F5 衝突：列上 ⚠、上方計數")
    path = os.path.join(OUT, "shortcuts.json")
    d.km.save_json(path)
    d.km.reset_all(); d._kb_fill(); app.update()
    check(d.km.to_dict()["shortcuts"] == {} and d.kb_tree.item("view.grid")["values"][1] in ("⌘G", "Ctrl+G"), "全部還原預設")
    nload = d.km.load_json(path)
    check(nload == 1 and d.km.bindings("view.grid") == ("F6", "F5"), "匯入剛匯出的 JSON")
    d.km.reset_all(); d._apply(); d.destroy(); app.update()
    check(not app.keymap.overrides and app.keymap.lookup("F5") == ["file.rescan"] and app.home_btns["rescan"]._pk_tip.endswith(" (F5)"),
          "套用全部預設 → 主程式回到預設、提示回來")
    app.apply_settings(cfg, quiet=True); app.update()
    check(app.keymap.bindings("view.grid") == ("F6", "F5") and app.ia.key_map.get("home") == "restore_view", "apply_settings 還原快速鍵")
    app.keymap.set("plot.restore_view", ["End"]); app._apply_keymap()
    check(app.ia.key_map.get("end") == "restore_view" and "home" not in app.ia.key_map and app.ia.key_map.get("delete") == "delete",
          "圖上的鍵改成 End → Interactor key_map 跟著變（Delete／Esc 固定）")
    app.keymap.reset_all(); app._apply_keymap(); app.update()


@step
def s25_panel_close_select_wheel():
    """panel 左上角 ×（刪除、不進匯出圖）、點握把區選取 panel → Delete 刪除、滾輪捲動不靠 <Enter>、高 DPI 時畫布高度用邏輯像素。"""
    from matplotlib.backend_bases import MouseEvent
    if not app.signals:
        app.add_all_visible()
    for i, s_ in enumerate(app.signals[:6]):
        s_.panel = i + 1
    app.refresh_list(); app.plot(); app.update()
    for _ in range(3):
        app.update_idletasks(); app.update()
    w = app.canvas.get_tk_widget()
    panels = list(app.render_info["panels"])
    check(len(panels) >= 3 and sorted(app._close_items) == sorted(panels) and not any("×" in t.get_text() for t in app.fig.texts),
          f"每個 panel 都有 ×（{len(app._close_items)}／{len(panels)}），而且不是 matplotlib 圖的一部分（匯出不會印到）")
    H = app.fig.bbox.height
    def center(p):                                    # Tk 畫布座標 → matplotlib 像素：TkAgg 同一套像素，只上下翻（W10）
        b = w.bbox(app._close_items[p])
        return (b[0] + b[2]) / 2, H - (b[1] + b[3]) / 2
    def proc(name, x, y, **kw):
        app.canvas.callbacks.process(name, MouseEvent(name, app.canvas, x, y, **kw))
    p0 = panels[0]
    cx, cy = center(p0)
    proc("motion_notify_event", cx, cy)
    muted, red, _a = app._panel_ui_colors()
    check(app._close_hover == p0 and w.itemcget(app._close_items[p0], "fill") == red and f"P{p0}" in app.status_var.get(),
          f"滑到 × 上：變紅、狀態列提示（{app.status_var.get()}）")
    proc("motion_notify_event", cx + 200, cy)
    check(app._close_hover is None and w.itemcget(app._close_items[p0], "fill") == muted, "滑開：× 變回灰色")
    n = len(app.signals)
    n_p0 = len([s_ for s_ in app.signals if s_.panel == p0])
    proc("button_press_event", cx, cy, button=1); proc("button_release_event", cx, cy, button=1); app.update()
    check(p0 not in app.render_info["panels"] and len(app.signals) == n - n_p0 and app._strip_drag is None,
          f"點 × → 刪除 P{p0}（{n} → {len(app.signals)} 條），沒有開始拖曳")
    app.undo_action(); app.update()
    check(len(app.signals) == n and p0 in app.render_info["panels"], "復原刪除")
    for _ in range(3):
        app.update_idletasks(); app.update()
    ax1, p1 = app.render_info["axes"][1], app.render_info["panels"][1]
    mx, my = ax1.bbox.x0 - 20, (ax1.bbox.y0 + ax1.bbox.y1) / 2
    proc("button_press_event", mx, my, button=1); proc("button_release_event", mx, my, button=1); app.update()
    check(app._sel_panel == p1 and len(w.find_withtag("dsv_panel_sel")) == 1 and f"P{p1}" in app.status_var.get(),
          f"點握把區（沒拖）→ 選取 P{p1}、出現選取框（{app.status_var.get()[:30]}）")
    tk_key(w, "Escape"); app.update()
    check(app._sel_panel is None and not w.find_withtag("dsv_panel_sel"), "Esc 取消 panel 選取")
    proc("button_press_event", mx, my, button=1); proc("button_release_event", mx, my, button=1); app.update()
    n_p1 = len([s_ for s_ in app.signals if s_.panel == p1])
    tk_key(w, "Delete"); app.update()
    check(p1 not in app.render_info["panels"] and len(app.signals) == n - n_p1 and app._sel_panel is None,
          f"選取 P{p1} 後在圖上按 Delete → 刪除整個 panel（{n} → {len(app.signals)}）")
    n2 = len(app.signals)
    tk_key(w, "Delete"); app.update()
    check(len(app.signals) == n2, "沒有選取任何東西時再按 Delete → 不會刪訊號")
    app.undo_action(); app.update()
    proc("button_press_event", mx, my, button=1); proc("button_release_event", mx, my, button=1); app.update()
    app.sig_tree.selection_set([app.sig_tree.get_children()[0]]); app._on_list_select(); app.update()
    check(app._sel_panel is None, "在清單選訊號 → 取消 panel 選取（選取互斥）")
    r_ = app.dispatch_shortcut("Delete", app.sig_tree); app.update()
    check(r_ == "break" and len(app.signals) == n - 1, "清單有焦點時 Delete 照舊移除選取的訊號")
    app.undo_action(); app.update()
    # 滾輪：不需要 <Enter> 就能捲動（游標本來就停在圖上）
    app.plot_scroll.event_generate("<Leave>", when="now"); app.update()
    check(bool(app.plot_scroll.bind_all("<MouseWheel>")), "滾輪捲動一開始就掛著，<Leave> 不會拆掉")
    if not HL:
        app.plot_scroll.yview_moveto(0); app.update()
        if app._plot_scrollable():
            ax_ = app.render_info["axes"][0]
            tx, ty = 8, int(app.fig.bbox.height - ax_.bbox.y1) + 30          # TkAgg：Tk 畫布 y＝圖高 − matplotlib y（W10）
            rx, ry = w.winfo_rootx() + tx, w.winfo_rooty() + ty
            _w14_wheel_hit(True)                   # W-A：Windows 安靜模式的命中測試換成 Tk 幾何（Mac 不換）
            try:
                w.event_generate("<MouseWheel>", delta=_w14_wheel_delta(-1), x=tx, y=ty, rootx=rx, rooty=ry, when="now"); app.update()
            finally:
                _w14_wheel_hit(False)
            check(app.plot_scroll.yview()[0] > 0, f"沒有 <Enter> 時滾輪也會捲動（yview {app.plot_scroll.yview()[0]:.3f}）")
            app.plot_scroll.yview_moveto(0)
    # 捲軸：滑塊要照位置擺（元素名結尾 thumb）、照 MATLAB 的捲軸 12 px 寬；捲動時滑塊跟著移動
    sb = app.plot_vbar
    def thumb_span():
        hh = sb.winfo_height(); xx = sb.winfo_width() // 2
        ys = [y for y in range(0, hh, 2) if "thumb" in str(sb.identify(xx, y))]
        return (ys[0], ys[-1]) if ys else (None, None)
    if not HL and app._plot_scrollable():
        app.plot_scroll.yview_moveto(0); app.update()
        t0 = thumb_span()
        app.plot_scroll.yview_moveto(1.0); app.update()
        t1 = thumb_span()
        check(sb.winfo_width() == app.theme.px(12) and t0[0] is not None and t0[0] < 4 and t1[1] >= sb.winfo_height() - 4
              and t1[0] > t0[0] + 10 and (t0[1] - t0[0]) < sb.winfo_height() - 20,
              f"捲軸：12 px 寬、滑塊不是填滿整條、捲到底時滑塊移到底（{t0} → {t1}，高 {sb.winfo_height()}）")
        app.plot_scroll.yview_moveto(0); app.update()
    # 高 DPI（W10；0.9.14 在使用者的 175% PC 上量到才改）：TkAgg 的 Tk 畫布像素就是 matplotlib 的像素，device_pixel_ratio 放大的是
    # fig.dpi——圖要剛好填滿 Tk 畫布（不被切掉），每張圖的英吋高度不變（Tk 像素跟著放大，螢幕上和 0.9.12 沒宣告 DPI、Windows 點陣放大時一樣大）。
    # 以前這裡驗「dpr 2 時畫布高度不變（邏輯像素）」：那樣圖比畫布大 dpr 倍，右下被切掉、× 與框畫在別張圖上。做完還原成原本的 dpr
    # （Windows 175% 是 1.75；以前固定設回 1.0，後面的步驟在 Windows 上就不是螢幕真的 DPI 了）
    def _dpi_state():
        wd_ = app.canvas.get_tk_widget()
        return {"item_h": int(float(app.plot_scroll.itemcget(app._plot_win, "height"))), "tk": (wd_.winfo_width(), wd_.winfo_height()),
                "fig": (round(app.fig.bbox.width), round(app.fig.bbox.height)), "scroll": bool(app._plot_scrollable()),
                "in": [round(a.bbox.height / float(app.fig.dpi), 3) for a in app.render_info["axes"]]}
    ph0_, fit0_ = app.v["panel_height"].get(), app.v["fit_panels"].get()
    app.v["fit_panels"].set(False); app.v["panel_height"].set("8")      # 每張 8 in：dpr 1 與 2 時畫布都比可見範圍高（每張都是自己的高度）
    app.plot(); app.update()
    r0_ = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)
    d1_ = _dpi_state()
    app.canvas._set_device_pixel_ratio(2.0); app.plot(); app.update()
    d2_ = _dpi_state()
    app.canvas._set_device_pixel_ratio(r0_); app.plot(); app.update()
    d3_ = _dpi_state()
    app.v["panel_height"].set(ph0_); app.v["fit_panels"].set(fit0_); app.plot(); app.update()
    fill_ = all(abs(d_["fig"][0] - d_["tk"][0]) <= 1 and abs(d_["fig"][1] - d_["tk"][1]) <= 1 for d_ in (d1_, d2_, d3_))
    same_in_ = len(d1_["in"]) == len(d2_["in"]) > 0 and all(abs(a_ - b_) <= 0.02 for a_, b_ in zip(d1_["in"], d2_["in"]))
    grow_ = abs(d2_["item_h"] - d1_["item_h"] * 2.0 / r0_) <= 0.02 * d2_["item_h"] + 4
    check(d1_["scroll"] and d2_["scroll"] and fill_ and same_in_ and grow_ and d3_["item_h"] == d1_["item_h"] and d3_["fig"] == d1_["fig"],
          f"device_pixel_ratio 2：圖剛好填滿 Tk 畫布（{d2_['fig']} vs {d2_['tk']}）、每張圖的英吋高度不變（{d1_['in']} → {d2_['in']}）、"
          f"畫布的 Tk 像素跟著放大（{d1_['item_h']} → {d2_['item_h']}；捲動 {d1_['scroll']}／{d2_['scroll']}）；還原 dpr {r0_} 一模一樣")
    # T14-8 (a)（0.9.14 第一輪測試強度，突變 S02～S04）：device_pixel_ratio 1.75（Windows 175%）時拖放的落點、目前 panel 的藍框、× 的位置與命中
    # 都照 TkAgg 的座標（Tk 畫布像素＝matplotlib 像素，不乘除 dpr；只有固定的 3 個邏輯像素的邊乘 dpr）——Mac 的 dpr 永遠是 1、PC 平常是 100%，
    # 只有在這裡模擬才分得出 0.9.13 的乘除寫法（W10 在使用者的 175% PC 上量到才改）
    fit1_ = app.v["fit_panels"].get()
    cur0_ = app.current_panel()
    app.v["fit_panels"].set(True)
    app.canvas._set_device_pixel_ratio(1.75); app.plot(); app.update()
    try:
        w5_ = app.canvas.get_tk_widget()
        H5_ = float(app.fig.bbox.height)
        pan5_, axs5_ = list(app.render_info.get("panels") or []), list(app.render_info.get("axes") or [])
        drops5_, hits5_ = [], []
        for p_, ax_ in zip(pan5_, axs5_):
            bb_ = ax_.bbox
            cx_, cy_ = (bb_.x0 + bb_.x1) / 2.0, (bb_.y0 + bb_.y1) / 2.0
            app.scroll_to_panel(p_); app.update()                # 放不下時捲到看得到那張（落點只算看得到的圖區）
            drops5_.append(app.drop_target(w5_.winfo_rootx() + int(cx_), w5_.winfo_rooty() + int(H5_ - cy_)) == ("panel", p_))
            bx_ = w5_.bbox(app._close_items.get(p_)) if app._close_items.get(p_) else None
            if bx_:
                ev_ = SimpleNamespace(x=(bx_[0] + bx_[2]) / 2.0, y=H5_ - (bx_[1] + bx_[3]) / 2.0)
                hits5_.append(app._close_hit(ev_) == p_ and abs(bx_[1] - (H5_ - bb_.y1)) <= 1.75 * 4 + 2)
            else:
                hits5_.append(False)
        frame5_ = None
        if len(pan5_) >= 2:
            app._set_current_panel(pan5_[1], announce=False); app._draw_panel_ui(); app.update()
            c_ = [float(v_) for v_ in w5_.coords("dsv_panel_cur")]
            bb_ = axs5_[1].bbox
            want_ = [bb_.x0 - 3 * 1.75, H5_ - bb_.y1 - 3 * 1.75, bb_.x1 + 3 * 1.75, H5_ - bb_.y0 + 3 * 1.75]
            frame5_ = len(c_) == 4 and all(abs(a_ - b_) <= 1.5 for a_, b_ in zip(c_, want_))
        check(len(pan5_) >= 2 and all(drops5_) and all(hits5_) and frame5_ is True,
              f"device_pixel_ratio 1.75（Windows 175%）：每張圖中心的拖放落點就是那張（{drops5_}）、每張的 × 畫在圖的左上角、點 × 命中那張（{hits5_}）、"
              f"目前 panel 的藍框貼著圖（外 3 個邏輯像素；{frame5_}）——不乘除 device_pixel_ratio（突變 S02～S04）")
    finally:
        app.plot_scroll.yview_moveto(0)
        app.canvas._set_device_pixel_ratio(r0_)
        app.v["fit_panels"].set(fit1_)
        if cur0_ is not None:
            app._set_current_panel(cur0_, announce=False)
        app.plot(); app.update()


@step
def s26_current_folder():
    """資料夾面板照 MATLAB Current Folder：欄位、資料夾在前、排序、雙擊進入／返回／前進／上一層、最近資料夾、
    右鍵選單、F2 改名（含檢查）、Delete 不刪檔、詳細資料、自動重新整理、隱藏檔、不能畫的檔案灰字。"""
    t = app.file_tree
    root0 = app.root_dir
    work = os.path.join(OUT, "cf_root")
    shutil.rmtree(work, ignore_errors=True)
    os.makedirs(os.path.join(work, "b_sub", "deep"))
    os.makedirs(os.path.join(work, "a_sub"))
    with open(os.path.join(work, "z_small.txt"), "w") as f:
        f.write("1\n0\n")
    with open(os.path.join(work, "m_big.txt"), "w") as f:
        f.write("\n".join(str(i % 2) for i in range(5000)) + "\n")
    with open(os.path.join(work, "notes.pdf"), "wb") as f:
        f.write(b"%PDF-1.4\n")
    with open(os.path.join(work, "b_sub", "inner.txt"), "w") as f:
        f.write("1\n1\n0\n")
    with open(os.path.join(work, ".hidden.txt"), "w") as f:
        f.write("1\n")
    app.navigate_to(work); app.update()
    top = [t.item(i, "text") for i in t.get_children()]
    check(top == ["a_sub", "b_sub", "m_big.txt", "notes.pdf", "z_small.txt"],
          f"最上層＝目前資料夾的內容（沒有「.」節點）、資料夾在前、依名稱排序、隱藏檔不列（{top}）")
    heads = [t.heading(c, "text") for c in ("#0",) + sv.CF_COLS]
    check(heads == ["名稱 ▲", "大小", "修改日期", "類型"] and tuple(t.cget("displaycolumns")) == sv.CF_COLS,
          f"欄位 名稱／大小／修改日期／類型（MATLAB Name／Size／Date Modified／Type），名稱遞增（{heads}）")
    pdf = next(i for i in t.get_children() if t.item(i, "text") == "notes.pdf")
    sub = next(i for i in t.get_children() if t.item(i, "text") == "b_sub")
    check(app.tree_map[pdf]["kind"] == "other" and "cf_other" in t.item(pdf, "tags") and t.item(pdf, "values")[2] == "PDF 檔案"
          and t.item(sub, "values")[2] == "資料夾" and t.item(pdf, "image"),
          f"不能畫的檔案也列出、灰字、類型「PDF 檔案」、有圖示（{t.item(pdf, 'values')}）")
    t.heading("size", "text")
    app.cf_sort_by("size"); app.update()
    order = [t.item(i, "text") for i in t.get_children()]
    check(order[:2] == ["a_sub", "b_sub"] and order[2:] == ["z_small.txt", "notes.pdf", "m_big.txt"] and t.heading("size", "text").endswith("▲"),
          f"依大小排序：資料夾仍在前、檔案由小到大（{order}）")
    app.cf_sort_by("size"); app.update()
    order = [t.item(i, "text") for i in t.get_children()]
    check(order[2] == "m_big.txt" and t.heading("size", "text").endswith("▼"), f"再點一次反向（{order}）")
    app.cf_sort_by("name"); app.update()
    app.cf_toggle_column("modified"); app.update()
    check(tuple(t.cget("displaycolumns")) == ("size", "type"), "標題右鍵 顯示 → 關掉修改日期欄")
    app.cf_toggle_column("modified"); app.update()
    # 雙擊資料夾＝進入；返回／前進／上一層；最近資料夾
    sub = next(i for i in t.get_children() if t.item(i, "text") == "b_sub")
    t.see(sub); app.update()
    bb = t.bbox(sub)
    if bb:
        ev = SimpleNamespace(x=bb[0] + bb[2] - 4, y=bb[1] + bb[3] // 2)
        app._on_tree_double(ev); app.update()
    else:
        app._cf_open_items([sub]); app.update()
    check(os.path.abspath(app.root_dir) == os.path.abspath(os.path.join(work, "b_sub"))
          and [t.item(i, "text") for i in t.get_children()] == ["deep", "inner.txt"] and app.btn_nav_back.instate(["!disabled"]),
          f"雙擊資料夾 → 進入成為目前資料夾、返回鈕可按（{os.path.basename(app.root_dir)}）")
    app.nav_back(); app.update()
    check(os.path.abspath(app.root_dir) == os.path.abspath(work) and app.btn_nav_fwd.instate(["!disabled"]), "返回 → 回上一個資料夾、前進鈕可按")
    app.nav_forward(); app.update()
    check(os.path.basename(app.root_dir) == "b_sub", "前進 → 再進去")
    app.go_up_folder(); app.update()
    vals = list(app.root_entry.cget("values"))
    check(os.path.abspath(app.root_dir) == os.path.abspath(work) and os.path.abspath(vals[0]) == os.path.abspath(work)
          and any(v.endswith("b_sub") for v in vals) and app.dump_settings()["folder_history"][0] == app.root_dir,
          f"上一層；位址列下拉＝最近資料夾，存進設定檔（{[os.path.basename(v) for v in vals[:3]]}）")
    # 雙擊檔案＝開啟（加入繪圖）
    n0 = len(app.signals)
    small = next(i for i in t.get_children() if t.item(i, "text") == "z_small.txt")
    app._cf_open_items([small]); app.update()
    check(len(app.signals) == n0 + 1 and app.signals[-1].path == os.path.join(work, "z_small.txt"), "雙擊文字檔 → 加入繪圖")
    app.undo_action(); app.update()
    opened = []
    orig_open = app._sys_open
    app._sys_open = lambda path, reveal=False: opened.append((os.path.basename(path), reveal))
    pdf = next(i for i in t.get_children() if t.item(i, "text") == "notes.pdf")
    app._cf_open_items([pdf]); app.update()
    check(opened == [("notes.pdf", False)] and len(app.signals) == n0, "雙擊不能畫的檔案 → 用系統預設程式開啟（不加入繪圖）")
    # 右鍵選單
    t.selection_set([small]); app.update()
    bb = t.bbox(small)
    menus.clear()
    app._cf_context(SimpleNamespace(x=(bb[0] + 5) if bb else 5, y=(bb[1] + 3) if bb else 3, x_root=50, y_root=50))
    labels = list(menus[-1]) if menus else []
    want = ["開啟", "以系統預設程式開啟", "在 Finder 中顯示" if sys.platform == "darwin" else "在檔案總管中顯示",
            "在 Finder 開啟目前資料夾" if sys.platform == "darwin" else "在檔案總管開啟目前資料夾", "複製路徑", "重新命名…"]
    check(labels[:len(want)] == want and "顯示" in labels and "排序方式" in labels, f"右鍵選單照 MATLAB（{labels}）")
    app.cf_reveal(os.path.join(work, "z_small.txt"))
    app.cf_copy_path([os.path.join(work, "z_small.txt")]); app.update()
    check(opened[-1] == ("z_small.txt", True) and app.clipboard_get() == os.path.join(work, "z_small.txt"), "在 Finder 中顯示、複製路徑")
    app._sys_open = orig_open
    # F2 改名（含 MATLAB 的檢查）、Delete 不刪檔
    answers = iter(["", "a_sub", "renamed.txt"])
    orig_ask = sv.ask_string
    errs = []
    orig_err = sv.messagebox.showerror
    sv.ask_string = lambda *a, **k: next(answers)
    sv.messagebox.showerror = lambda *a, **k: errs.append(a[1] if len(a) > 1 else "")
    try:
        app.cf_rename(small); app.update()
        app.cf_rename(small); app.update()
        app.cf_rename(small); app.update()
    finally:
        sv.ask_string = orig_ask
        sv.messagebox.showerror = orig_err
    names = [t.item(i, "text") for i in t.get_children()]
    check(len(errs) == 2 and "空白" in errs[0] and "同名" in errs[1] and "renamed.txt" in names and "z_small.txt" not in names
          and os.path.exists(os.path.join(work, "renamed.txt")),
          f"F2 改名：空白、同名被擋（{errs}），改成 renamed.txt 後列表更新")
    ren = next(i for i in t.get_children() if t.item(i, "text") == "renamed.txt")
    t.selection_set([ren]); t.focus_set()
    tk_key(t, "Delete"); app.update()
    check(os.path.exists(os.path.join(work, "renamed.txt")) and "不會刪除" in app.status_var.get(), "資料夾面板按 Delete 不刪磁碟上的檔案")
    # 詳細資料（預設收合）
    check(not app.v["cf_details"].get() and not app.cf_details_body.winfo_ismapped(), "詳細資料預設收合（跟使用者的 MATLAB 一樣）")
    app.cf_toggle_details(True); app.update()
    ren = next(i for i in t.get_children() if t.item(i, "text") == "renamed.txt")
    t.selection_set([ren]); app.update()
    d = app.cf_details_var.get()
    check(d.startswith("renamed.txt") and "TXT 檔案" in d and "KB" in d and "修改日期" in d, f"詳細資料：名稱、類型、大小、修改日期（{d!r}）")
    sub = next(i for i in t.get_children() if t.item(i, "text") == "b_sub")
    t.selection_set([sub]); app.update()
    check("2 個項目" in app.cf_details_var.get(), f"詳細資料：資料夾的項目數（{app.cf_details_var.get()!r}）")
    app.cf_toggle_details(False); app.update()
    # 自動重新整理：保留展開與選取
    t.item(sub, open=True)
    t.selection_set([sub]); app.update()
    check(not app.cf_autorefresh_check(), "沒變動 → 不重列")
    with open(os.path.join(work, "added.txt"), "w") as f:
        f.write("0\n1\n")
    os.utime(work, (time.time() + 5, time.time() + 5))
    changed = app.cf_autorefresh_check(); app.update()
    sub = next(i for i in t.get_children() if t.item(i, "text") == "b_sub")
    check(changed and any(t.item(i, "text") == "added.txt" for i in t.get_children()) and t.item(sub, "open")
          and [t.item(i, "text") for i in t.selection()] == ["b_sub"],
          "新增檔案 → 自動重列，展開與選取不變")
    # 隱藏檔
    app.v["cf_hidden"].set(True); app.rescan(quiet=True); app.update()
    check(any(t.item(i, "text") == ".hidden.txt" for i in t.get_children()), "偏好「顯示隱藏的檔案與資料夾」→ 列出 . 開頭的檔案")
    app.v["cf_hidden"].set(False)
    app.navigate_to(root0); app.update()


@step
def s27_iq_window():
    """AM/PM/FM 分析視窗（分析 → AM/PM 分析…／FM 分析…）：I/Q 配對算 AM／PM／FM 各一張子圖、x 軸秒；FM＝相位差 × fs/2π（Hz）；
    相位展開；複製訊號 → 貼到主圖 panel 變衍生訊號（跟著來源與 symbol rate 更新、存進設定檔）；右鍵／⌘C；沒有配對不開窗。"""
    from types import SimpleNamespace as NS
    fs = 4e6; f0 = 12.5e3; n = 4000
    t = np.arange(n) / fs
    amp = 100 + 50 * np.sin(2 * np.pi * 2000 * t)
    path = os.path.join(ROOT, "tone_iq.csv")
    with open(path, "w") as f:
        f.write("Time,adc i,adc q\n")
        f.writelines(f"{tt:.9f},{a:.4f},{b:.4f}\n" for tt, a, b in zip(t, amp * np.cos(2 * np.pi * f0 * t), amp * np.sin(2 * np.pi * f0 * t)))
    cfg0 = app.dump_settings()                       # 結束時整個還原（s9 要用這時候的訊號與設定）
    app.v["symbol_rate"].set("1M")
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()   # 分析範圍＝主圖 x 範圍：先全部顯示
    si = app.find_signal("tone_iq.csv;;adc i"); sq = app.find_signal("tone_iq.csv;;adc q")
    check(si is not None and sq is not None and si.sps == 4.0 and app.symbol_rate() == 1e6, f"合成 I/Q 單音：SPS 4、symbol rate 1M → fs 4 MHz（sps={si.sps if si else None}）")
    tops0 = [w for w in app.winfo_children() if isinstance(w, sv.tk.Toplevel)]
    app.sig_tree.selection_set([]); app._on_list_select()
    app.clear_all(); app.update()
    app.open_iq_window("fm"); app.update()
    check(len([w for w in app.winfo_children() if isinstance(w, sv.tk.Toplevel)]) == len(tops0) and "沒有訊號" in app.status_var.get(),
          f"沒有訊號時 FM 分析… 不開視窗、狀態列說明（{app.status_var.get()[:30]}）")
    app.undo_action(); app.show_all_x(); app.update()
    si = app.find_signal("tone_iq.csv;;adc i"); sq = app.find_signal("tone_iq.csv;;adc q")
    w = app.open_iq_window("fm"); app.update()
    check(w is not None and w.title().startswith("AM/PM/FM 分析") and w.kinds() == ["fm"] and len(w.lines) == 1 and w.tip_xunit == "s",
          f"open_iq_window('fm')：合併後的 AM/PM/FM 視窗、一開始只勾 FM、一條線、x 軸秒（{w.title() if w else None}）")
    y = w._series[0]["y"]; x = w._series[0]["x"]
    check(np.isnan(y[0]) and abs(float(np.nanmedian(y)) - f0) < 1.0 and float(np.nanmax(np.abs(y[1:] - f0))) < 5.0 and abs(x[-1] - (n - 1) / fs) < 1e-12,
          f"FM＝相位差 × fs/2π：12.5 kHz 單音讀 {float(np.nanmedian(y)):.1f} Hz（第 0 點空）、x 最後一點 {x[-1]:.6f} s")
    w.v_kind["am"].set(True); w.v_kind["pm"].set(True); w.compute(); app.update()
    kinds = [s_["kind"] for s_ in w._series]
    am = next(s_["y"] for s_ in w._series if s_["kind"] == "iq_mag"); pm = next(s_["y"] for s_ in w._series if s_["kind"] == "iq_phase")
    check(kinds == ["iq_mag", "iq_phase", "iq_fm"] and len(w.fig.axes) == 3 and abs(float(am.max()) - 150) < 0.01 and abs(float(am.min()) - 50) < 0.01
          and float(pm.min()) >= -180 and float(pm.max()) <= 180 and [a.get_ylabel() for a in w.fig.axes] == ["|I+jQ|", "∠ [deg]", "f [Hz]"],
          f"勾 AM、PM → 三張子圖：AM 50..150、PM −180..180、FM（{kinds}）")
    w.v_unwrap.set(True); w.compute(); app.update()
    pm = next(s_ for s_ in w._series if s_["kind"].startswith("iq_phase"))
    check(pm["kind"] == "iq_phase_unwrap" and float(np.max(np.abs(np.diff(pm["y"])))) < 180 and app.iq_defaults["unwrap"] is True and app.v["iq_unwrap"].get(),
          "相位展開 → PM 連續、設定記住")
    w.v_order.set("QI"); w.compute(); app.update()
    yq = next(s_["y"] for s_ in w._series if s_["kind"] == "iq_fm")
    check(abs(float(np.nanmedian(yq)) + f0) < 1.0 and app.iq_defaults["iq_order"] == "QI", f"I/Q 順序 QI → FM 符號相反（{float(np.nanmedian(yq)):.1f} Hz）")
    w.v_order.set("IQ"); w.compute(); app.update()
    # 複製 → 貼到主圖 panel：衍生訊號、跟著來源與 symbol rate
    n0 = len(app.signals)
    d = w.copy_signals(); app.update()
    check(len(d) == 3 and [x_["derive"] for x_ in d] == ["iq_mag", "iq_phase_unwrap", "iq_fm"] and len(app._sig_clip) == 3 and len(sv.CLIPBOARD) == 3
          and sv.CLIPBOARD[0].xunit == "s" and "⌘V" in app.status_var.get() or "Ctrl+V" in app.status_var.get(),
          f"複製訊號：3 條衍生訊號進剪貼簿、圖片視窗用的 Series 也有（{app.status_var.get()[:40]}）")
    app.paste_to_panel(si.panel); app.update()
    new = app.signals[n0:]
    fmsig = next((s_ for s_ in new if s_.derive == "iq_fm"), None)
    check(len(new) == 3 and fmsig is not None and all(s_.panel == si.panel for s_ in new) and fmsig.src == f"{si.uid},{sq.uid}"
          and abs(float(np.nanmedian(fmsig.get_data())) - f0) < 1.0 and app.sig_tree.set(f"s{fmsig.uid}", "fmt") == "FM Hz"
          and fmsig.uid in app.render_info["artists"],
          f"貼到 P{si.panel}：3 條衍生訊號、FM 的值一樣、清單 Fmt「FM Hz」、有畫出來")
    app.v["symbol_rate"].set("2M"); app.plot(); app.update()
    check(abs(float(np.nanmedian(fmsig.get_data())) - 2 * f0) < 1.0, f"改 symbol rate 2M → 貼上的 FM 自動重算成 {float(np.nanmedian(fmsig.get_data())):.0f} Hz")
    app.v["symbol_rate"].set("1M"); app.plot(); app.update()
    n_1 = len(app.signals)
    app.paste_into(si.panel); app.update()
    again = app.signals[n_1:]
    check(n_1 == n0 + 3 and len(again) == 3 and all(s_.panel == si.panel and s_.key.endswith("#2") for s_ in again)
          and app.status_var.get() == f"已貼上 3 條訊號到 P{si.panel}",
          f"同一組再貼一次 → 照 MATLAB 再貼一份（{[s_.key for s_ in again]}；第 13 項，以前略過）")
    app.undo_action(); app.update()
    check(len(app.signals) == n0 + 3, "⌘Z → 第二份拿掉")
    cfg = app.dump_settings()
    check(cfg["iq"] == {"unwrap": True, "iq_order": "IQ", "kinds": ["am", "pm", "fm"]}
          and sorted(s_["derive"] for s_ in cfg["signals"] if s_["derive"]) == ["iq_fm", "iq_mag", "iq_phase_unwrap"],
          f"設定檔：iq 視窗設定（含勾選的 kinds）與 iq_fm 衍生訊號（{cfg['iq']}）")
    app.apply_settings(cfg, quiet=True); app.update()
    fm2 = next((s_ for s_ in app.signals if s_.derive == "iq_fm"), None)
    check(fm2 is not None and fm2.sources() is not None and abs(float(np.nanmedian(fm2.get_data())) - f0) < 1.0, "讀回設定檔：FM 衍生訊號找得到來源、值一樣")
    menus.clear()
    w.context_menu(NS(kind="line", id=1, ax=None), NS(guiEvent=None))
    lab = menus[-1] if menus else []
    check(lab[:2] == ["複製", "複製全部訊號（3 條）"], f"視窗線上右鍵：最上面是「複製」「複製全部訊號」（MATLAB 線條右鍵的 Copy）（{lab[:3]}）")
    menus.clear()
    ax0 = app.render_info["axes"][0]
    app._context_for_hit(NS(kind="empty", id=None, ax=ax0), NS(guiEvent=None, x=0, y=0))
    lab = menus[-1] if menus else []
    check(len(lab) > 2 and lab[2].startswith("貼上到 P"), f"主圖右鍵：「貼上到 Pn」在復原／重做下面（{lab[:3]}）")
    # 視窗裡按 ⌘V ＝ 貼到主圖目前的 panel
    n_b = len(app.signals); app.undo_action(); app.update()          # 先把剛才貼的拿掉
    n_b = len(app.signals)
    app._current_panel = si.panel
    tk_key(w.canvas.get_tk_widget(), "v", mods="Command" if sys.platform == "darwin" else "Control"); app.update()
    w.canvas.get_tk_widget().event_generate("<<Paste>>", when="now"); app.update()      # 同一次按鍵的虛擬事件：只貼一次（第 13 項）
    check(len(app.signals) == n_b + 3 and all(s_.panel == si.panel for s_ in app.signals[n_b:]),
          f"在 AM/PM/FM 視窗按 ⌘V（按鍵＋同一次按鍵的 <<Paste>>）→ 只貼一次、直接貼到主圖目前的 panel（{n_b} → {len(app.signals)}）")
    app.undo_action(); app.update()
    # 把線拖到主圖的 panel 上
    wd = w.canvas.get_tk_widget(); w.update()
    ln = w.lines[1]; axl = ln.axes; xd, yd = ln.get_xdata(), ln.get_ydata(); ii = len(xd) // 2
    pxx, pyy = axl.transData.transform((xd[ii], yd[ii])); hh = w.canvas.get_width_height(physical=True)[1]
    xx, yy = int(round(pxx)), int(round(hh - pyy))
    w._drag_out_press(NS(x=xx, y=yy, x_root=wd.winfo_rootx() + xx, y_root=wd.winfo_rooty() + yy))
    check(w._drag_src is not None and w._drag_src["uid"] == 1, "在視窗的線上按住 → 記下要拖的線")
    mw = app.canvas.get_tk_widget(); tax = app.render_info["axes"][-1]; HH = app.fig.bbox.height; p_t = app.render_info["panels"][-1]
    txr = mw.winfo_rootx() + int((tax.bbox.x0 + tax.bbox.x1) / 2); tyr = mw.winfo_rooty() + int(HH - (tax.bbox.y0 + tax.bbox.y1) / 2)
    w._drag_out_motion(NS(x=-40, y=yy, x_root=wd.winfo_rootx() - 40, y_root=wd.winfo_rooty() + yy))
    check(w._drag_src["out"] and str(wd.cget("cursor")) != "", f"拖出視窗 → 帶著線走（游標 {wd.cget('cursor')}）")
    w._drag_out_motion(NS(x=0, y=0, x_root=txr, y_root=tyr))
    check(w._drag_src["target"] == p_t and f"P{p_t}" in app.status_var.get(), f"移到主圖 P{p_t} 上 → 狀態列「放開以貼到 P{p_t}」")
    n_c = len(app.signals)
    w._drag_out_release(NS(x=0, y=0, x_root=txr, y_root=tyr)); app.update()
    check(len(app.signals) == n_c + 1 and app.signals[-1].panel == p_t and app.signals[-1].derive == w._series[0]["kind"] and str(wd.cget("cursor")) == "",
          f"放開 → 那條線貼到 P{p_t}（衍生訊號 {app.signals[-1].derive}）、游標還原")
    app.undo_action(); app.update()
    w._drag_out_press(NS(x=xx, y=yy, x_root=wd.winfo_rootx() + xx, y_root=wd.winfo_rooty() + yy))
    w._drag_out_motion(NS(x=-40, y=yy, x_root=wd.winfo_rootx() - 40, y_root=wd.winfo_rooty() + yy))
    n_c = len(app.signals)
    w._drag_out_release(NS(x=0, y=0, x_root=5, y_root=5)); app.update()
    check(len(app.signals) == n_c and "取消" in app.status_var.get(), "放在主圖以外 → 取消、不貼")
    app._sig_clip = []; sv.CLIPBOARD[:] = []
    tk_key(w.canvas.get_tk_widget(), "c", mods="Command" if sys.platform == "darwin" else "Control"); app.update()
    check(len(app._sig_clip) == 3, "視窗裡 ⌘C／Ctrl+C ＝ 複製全部訊號")
    if sys.platform == "darwin":
        app._sig_clip = []; sv.CLIPBOARD[:] = []
        tk_key(w.canvas.get_tk_widget(), "??", mods="Command", keycode=0x08000063); app.update()   # 注音輸入法量到的 ⌘C（keysym ??）
        check(len(app._sig_clip) == 3, "注音輸入法的 ⌘C（keysym ??、只有 keycode 認得出是 C）在視窗裡也是複製全部訊號（第 13 項）")
    w.destroy(); app.update()
    sel_now = [s_.derive for s_ in app.selected_signals()]
    w2 = app.open_iq_window("ampm"); app.update()
    check(all(sel_now) and w2 is not None and w2.title().startswith("AM/PM/FM 分析") and w2.kinds() == ["am", "pm"] and len(w2.lines) == 2,
          f"清單選的是剛貼上的衍生訊號時 open_iq_window('ampm') 仍用來源 I/Q 開視窗：勾 AM、PM 兩張（選取 {sel_now}）")
    if w2 is not None:
        w2.destroy(); app.update()
    app.clear_all(); app.update()
    os.remove(path); app.rescan(quiet=True); app.update()
    app.apply_settings(cfg0, quiet=True); app.update()   # 回到 s27 開始前的訊號、symbol rate 等設定


@step
def s28_batch1_tools():
    """第一批 MATLAB 工具（2026-10-24）：峰值搜尋、雙位準（轉態／過衝下衝／脈波）的工具列與表格、平移器（Panner）、
    擷取訊號（Extract Signals：在時間範圍內／在時間游標之間、保留開始時間）、從外部拖檔案放進 panel
    （macOS 用 tests/fakednd.m 走 tkdnd 原生的拖放路徑；其他平台直接呼叫拖放處理函式）。"""
    from types import SimpleNamespace as NS
    from matplotlib.backend_bases import MouseEvent
    import tests_common
    cfg0 = app.dump_settings()                       # 結束時整個還原（s9 要用這時候的訊號與設定）
    app.dock.reset(); app.update()
    app.clear_all(); app.update()
    for rel in ("digital/clk.txt", "digital/data.txt", "hex/samples.txt", "sub dir [1]/weird name #2.txt"):
        app.add_text_signal(os.path.join(ROOT, rel))
    app.refresh_list(); app.plot(keep=False); app.update()
    clk = app.find_signal("digital/clk.txt")
    check(clk is not None and sorted({s_.panel for s_ in app.signals}) == [1, 2, 3, 4], "s28：四條訊號各一個 panel")
    # ---------------------------------------------------------------- 量測：峰值、轉態、過衝／下衝
    mb = app._meas_btns
    groups = ("stats", "peaks", "trans", "aberr", "pulse")
    check(set(mb) == set(groups) | {"bilevel"} and all(f"meas.{g}" in app.actions for g in groups + ("bilevel",)),
          "量測分頁：訊號統計／峰值搜尋／轉態／過衝下衝／脈波／雙位準設定都有按鈕、也都是可設快速鍵的動作")
    app.actions["meas.peaks"].run(); app.update()
    check(app.v_meas_group["peaks"].get() and "peaks" in app.meas_groups() and app.meas_visible(),
          "峰值搜尋（快速鍵動作）：打開這一組、量測面板跟著顯示")
    app.set_meas_group("trans", True); app.set_meas_group("aberr", True); app.update()
    app.sig_tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
    head, rows = app.update_measurements()
    labels = [r[0] for r in rows]
    check(labels[:10] == [lb for _k, lb in sv.MEAS_STAT_ROWS] and "P1" in labels and "+邊緣數" in labels and "+過衝" in labels
          and "−穩定時間" in labels and "+工作週期" in labels, f"表格：統計、P1…、轉態、過衝／下衝、脈波都列出（{len(labels)} 列）")
    mcfg, _mkey = app._meas_cfg()
    lo, hi, _src = app.meas_range()
    exp = sv.measure_signal(clk, lo, hi, mcfg)
    opts = app.current_opts()
    fac, unit, sr = sv.x_display_factor(opts), opts["xunit"], app.symbol_rate()
    got = {r[0]: r[1] for r in rows}
    check(all(got[lb] == sv.format_meas(k, exp, fac, unit, sr) for k, lb in sv.MEAS_TRANS_ROWS + sv.MEAS_ABERR_ROWS + sv.MEAS_PULSE_ROWS),
          "轉態、過衝／下衝、脈波的值＝measure_signal（dsv_measure，已對過 MATLAB）＋format_meas")
    npk = len(exp.get("peaks") or [])
    check(npk == 3 and len(app._peak_artists) == 1 and "@" in got["P1"], f"峰值：預設 Num Peaks 3 → P1..P3、圖上一組 ▼（{npk}、{len(app._peak_artists)}）")
    app.v["pk_label"].set(True); app.request_measure_update(0); app.update_measurements(); app.update()
    check(len(app._peak_artists) == 1 + npk, f"標示峰值：▼ 旁邊加 P1…P{npk}（{len(app._peak_artists)} 個 artist）")
    app.v["pk_label"].set(False)
    app.v["pk_num"].set("0"); app._on_peak_params()
    check("Num Peaks" in app.status_var.get(), f"Num Peaks 0 → 狀態列說明範圍（{app.status_var.get()[:40]}）")
    app.v["pk_num"].set("3"); app._on_peak_params()
    dlg = app.bilevel_settings_dialog(); app.update()
    ents = [w for w in _walk(dlg) if isinstance(w, sv.ttk.Entry)]
    btns = {str(w.cget("text")): w for w in _walk(dlg) if isinstance(w, sv.ttk.Button)}
    check(len(ents) == 7 and {"確定", "取消", "套用"} <= set(btns), "雙位準設定：High／Low／Tol／Upper／Mid／Lower／Settle Seek 七格＋確定／取消／套用")
    ents[3].delete(0, "end"); ents[3].insert(0, "40")          # Upper 40 < Mid 50：不合法
    btns["套用"].invoke(); app.update()
    msgs = [str(app.getvar(str(w.cget("textvariable")))) for w in _walk(dlg)
            if isinstance(w, sv.ttk.Label) and str(w.cget("textvariable"))]
    check(app.v["bl_upper"].get() == "90" and any("Lower < Mid < Upper" in m_ for m_ in msgs),
          f"參考位準 Upper 40 < Mid 50 → 對話框裡說明、設定不變（{msgs}）")
    ents[3].delete(0, "end"); ents[3].insert(0, "80")
    btns["確定"].invoke(); app.update()
    check(app.v["bl_upper"].get() == "80" and not dlg.winfo_exists(), "Upper 80 → 確定：套用並關閉")
    app.v["bl_upper"].set("90")
    for g in ("peaks", "trans", "aberr"):
        app.set_meas_group(g, False)
    # ---------------------------------------------------------------- 平移器（Panner）
    app.actions["view.panner"].run(); app.update(); time.sleep(0.2); app.update()
    pn = app.panner
    cp_ = app.current_panel()
    vis = [s_ for s_ in app.signals if s_.visible and s_.uid in app.render_info["artists"] and s_.panel == cp_]
    check(app.v["panner"].get() and pn.frame.winfo_manager() == "pack" and len(pn.lines) == len(vis) == 1 and pn.full is not None,
          f"平移器（快速鍵動作）：主圖下方顯示，畫目前 panel（P{cp_}）顯示中的訊號、一條一條線（{len(pn.lines)}；第 12 項：只畫目前 panel）")
    ax = app.render_info["axes"][-1]
    r_ = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)
    rp_ = float(getattr(pn.canvas, "device_pixel_ratio", 1.0) or 1.0)
    check(HL or abs(pn.ax.bbox.x0 / rp_ - ax.bbox.x0 / r_) < 1.5 and abs(pn.ax.bbox.x1 / rp_ - ax.bbox.x1 / r_) < 1.5,
          "平移器的座標區和主圖左右對齊")
    fa, fb = pn.full
    a, b = fa + (fb - fa) * 0.2, fa + (fb - fa) * 0.4
    app.ia.set_xlim(ax, a, b, draw=True); app.update()
    check(pn.view is not None and abs(pn.view[0] - a) < 1e-9 and abs(pn.view[1] - b) < 1e-9, "主圖縮放 → 平移器的縮放窗跟著")

    def pev(name, xd):
        px_, py_ = pn.ax.transData.transform((xd, 0.5))
        return MouseEvent(name, pn.canvas, px_, py_, button=1)

    def pdrag(x0_, x1_):
        pn.canvas.callbacks.process("button_press_event", pev("button_press_event", x0_))
        pn.canvas.callbacks.process("motion_notify_event", pev("motion_notify_event", (x0_ + x1_) / 2))
        pn.canvas.callbacks.process("motion_notify_event", pev("motion_notify_event", x1_))
        pn.canvas.callbacks.process("button_release_event", pev("button_release_event", x1_))
        app.update()

    tolx = (fb - fa) * 0.01
    sh = (fb - fa) * 0.1
    pdrag((a + b) / 2, (a + b) / 2 + sh)
    xl = app.current_xlim()
    check(abs(xl[0] - (a + sh)) < tolx and abs(xl[1] - (b + sh)) < tolx, f"拖縮放窗中間 → 主圖跟著滑動（{xl}）")
    app.toolbar.back(); app.update()
    xb = app.current_xlim()
    check(abs(xb[0] - a) < tolx and abs(xb[1] - b) < tolx, f"放開時推進「上一個視圖」：Back 回到拖之前（{xb}）")
    app.toolbar.forward(); app.update()
    pdrag(b + sh, fb)                                          # 拖右邊到底：截在訊號範圍內
    xl = app.current_xlim()
    check(abs(xl[0] - (a + sh)) < tolx and abs(xl[1] - fb) < tolx, f"拖縮放窗右邊 → 調寬度、截在範圍內（{xl}）")
    pdrag(fa + (fb - fa) * 0.25, fa + (fb - fa) * 0.05)        # 縮放窗（0.3..1.0）外面按下往左拉：建立新的縮放窗
    xl = app.current_xlim()
    check(abs(xl[0] - (fa + (fb - fa) * 0.05)) < tolx and abs(xl[1] - (fa + (fb - fa) * 0.25)) < tolx, f"窗外拖曳 → 新的縮放窗（{xl}）")
    pn.canvas.callbacks.process("button_press_event", pev("button_press_event", fa + (fb - fa) * 0.6))
    pn.canvas.callbacks.process("button_release_event", pev("button_release_event", fa + (fb - fa) * 0.6))
    check(app.current_xlim() == xl, "在平移器上點一下沒拖：不動")
    pn.canvas.callbacks.process("button_press_event", pev("button_press_event", (xl[0] + xl[1]) / 2))
    pn.canvas.callbacks.process("motion_notify_event", pev("motion_notify_event", (xl[0] + xl[1]) / 2 - sh))
    check(app.current_xlim() != xl and pn.cancel_drag() and app.current_xlim() == xl, "拖到一半按 Esc：主圖回到按下前的範圍")
    pn.canvas.callbacks.process("button_release_event", pev("button_release_event", (xl[0] + xl[1]) / 2 - sh))
    app.actions["view.panner"].run(); app.update()
    check(not app.v["panner"].get() and not pn.frame.winfo_manager(), "再按一次：平移器隱藏")
    # ---------------------------------------------------------------- 擷取訊號（感興趣區域）
    app.show_all_x(); app.update()
    ax = app.render_info["axes"][-1]
    app.sig_tree.selection_set([f"s{clk.uid}"]); app._on_list_select()
    app.ia.set_xlim(ax, 100.0, 119.99, draw=True); app.update()
    n0, pmax = len(app.signals), max(s_.panel for s_ in app.signals)
    new = app.extract_roi("limits"); app.update()
    nr = new[0] if new else None
    check(len(new) == 1 and nr.label == clk.name + "_ROI" and nr.roi == "100:120" and nr.panel == pmax + 1 and nr.offset == 0.0,
          f"在時間範圍內（選取 1 條）：名稱 +_ROI、樣本 100..119、新 panel、從 0 開始（{[(x.label, x.roi, x.panel, x.offset) for x in new]}）")
    check(nr is not None and np.array_equal(nr.get_data(), clk.get_data()[100:120]), "擷取的資料＝來源同一段")
    xl = app.current_xlim()
    check(xl[0] <= 0.5 and xl[1] >= 19.5 and "從 0 開始" in app.status_var.get() and "x 範圍換到新訊號" in app.status_var.get(),
          f"不保留開始時間：新訊號（0..20）在目前範圍（100..120）外 → x 範圍換到新訊號、狀態列說明（{xl}）")
    check(app.sig_tree.selection() == (f"s{nr.uid}",) if nr else False, "擷取完選取新訊號")
    app.undo_action(); app.update()
    check(len(app.signals) == n0 and not any(s_.roi for s_ in app.signals), "復原擷取")
    app.v["roi_preserve"].set(True); app._on_roi_preserve()
    app.ia.set_xlim(app.render_info["axes"][-1], 100.0, 140.0, draw=True); app.update()
    app.sig_tree.selection_set([]); app._on_list_select()
    new = app.extract_roi("limits"); app.update()
    labels_new = sorted(x.label for x in new)
    check(len(new) == 4 and len({x.panel for x in new}) == 4 and all(abs(x.x0 - 100.0) < 1e-9 for x in new if x.sps == 1.0)
          and clk.name + "_ROI" in labels_new, f"沒有選取＝全部顯示中的訊號；保留開始時間：從 x=100 開始；各自的新 panel（{labels_new}）")
    app.undo_action(); app.update()
    app.ia.set_xlim(app.render_info["axes"][-1], 100.2, 100.9, draw=True); app.update()
    n1 = len(app.signals)
    check(app.extract_roi("limits", [clk]) == [] and len(app.signals) == n1, "範圍內少於兩個資料點：不擷取（MATLAB 的規則與警告）")
    check(app.extract_roi("cursors", [clk]) == [], "兩條資料游標沒開：「在時間游標之間」不做、提示怎麼開")
    app.set_dcursor_mode("two"); app.update()
    app.dcur.xs = [20.0, 12.0]
    new = app.extract_roi("cursors", [clk]); app.update()
    check(len(new) == 1 and new[0].roi == "12:21" and abs(new[0].x0 - 12.0) < 1e-9, f"在時間游標之間（順序不拘，兩端都含）：12..20（{[x.roi for x in new]}）")
    m = sv.tk.Menu(app, tearoff=0)
    app._add_roi_menu(m, NS(kind="empty", id=None), 1)
    lab1 = [m.entrycget(i, "label") for i in range(m.index("end") + 1)]
    m2 = sv.tk.Menu(app, tearoff=0)
    app._add_roi_menu(m2, NS(kind="line", id=clk.uid), 1)
    lab2 = [m2.entrycget(i, "label") for i in range(m2.index("end") + 1)]
    app.set_dcursor_mode("none"); app.update()
    m3 = sv.tk.Menu(app, tearoff=0)
    app._add_roi_menu(m3, NS(kind="empty", id=None), 1)
    lab3 = [m3.entrycget(i, "label") for i in range(m3.index("end") + 1)]
    check(lab1 == ["擷取訊號（P1）"] and lab2 == [f"擷取訊號（{clk.name}）"] and lab3 == ["在時間範圍內擷取訊號（P1）"],
          f"圖上右鍵：panel／線各自的擷取；沒開兩條游標時只有「在時間範圍內」（{lab1} {lab2} {lab3}）")
    d_ = new[0].to_dict() if new else {}
    check(d_.get("roi") == "12:21" and sv.Signal.from_dict(d_).roi == "12:21", "擷取的訊號存進設定檔再讀回")
    app.v["roi_preserve"].set(False)
    app.undo_action(); app.update()
    # ---------------------------------------------------------------- 從外部拖檔案進 panel
    ext = os.path.join(OUT, "dnd outside")
    ext2 = os.path.join(OUT, "dnd other")
    os.makedirs(ext, exist_ok=True); os.makedirs(ext2, exist_ok=True)
    for d_, mod in ((ext, 7), (ext2, 3)):
        with open(os.path.join(d_, "same.txt"), "w") as f:
            f.write("\n".join(str(v) for v in (np.arange(300) % mod)) + "\n")
    with open(os.path.join(ext, "two.csv"), "w") as f:
        f.write("a,b\n" + "\n".join(f"{i},{i % 5}" for i in range(100)) + "\n")
    with open(os.path.join(ext, "new.txt"), "w") as f:
        f.write("\n".join(str(v) for v in range(50)) + "\n")
    app.show_all_x(); app.plot_scroll.yview_moveto(0); app.update()
    L = tests_common.fake_dnd_lib(OUT)
    native = L is not None and app.dnd_available and not HL

    def drop(rx, ry, paths, leave=False, settle=0.15):
        if native:
            return tests_common.native_drop(app, rx, ry, paths, leave=leave, settle=settle)
        ev = NS(data=app.tk.call("list", *paths), x_root=int(rx), y_root=int(ry), action="copy")
        app._on_drop_over(ev)
        if leave == "hover":
            pass
        elif leave:
            app._on_drop_leave(ev)
        else:
            app._on_drop(ev)
        t0 = time.time()
        while time.time() - t0 < settle:
            app.update(); time.sleep(0.01)
        return [1, 1, 1, 1], ""

    def center_of(p):
        info = app.render_info
        axp = info["axes"][info["panels"].index(p)]
        cw = app.canvas.get_tk_widget()
        H = app.fig.bbox.height
        return cw.winfo_rootx() + (axp.bbox.x0 + axp.bbox.x1) / 2, cw.winfo_rooty() + (H - (axp.bbox.y0 + axp.bbox.y1) / 2)   # TkAgg（W10）

    def at(p):
        """捲到 panel p 再取它的中心：量測面板開在圖的下方時圖區較矮、畫布會捲，放下後 scroll_to_panel 也會捲（座標要重新取，像使用者重新瞄準）。"""
        app.scroll_to_panel(p); app.update()
        return center_of(p)

    print(f"（s28 拖放：{'原生 tkdnd（tests/fakednd.m）' if native else '直接呼叫處理函式'}；量測面板{'開著（圖的下方）' if app.meas_visible() else '關著'}）")
    rx, ry = at(2)
    check(app.drop_target_at(int(rx), int(ry)) == 2, "落點在 P2 的圖上 → P2")
    n0 = len(app.signals)
    ops, err = drop(rx, ry, [os.path.join(ext, "same.txt")])
    added = app.signals[n0:]
    check(not err and ops == [1, 1, 1, 1] and len(added) == 1 and added[0].panel == 2 and "到 P2" in app.status_var.get(),
          f"放在 P2 → 加進 P2（ops {ops} {err}；{[(x.key, x.panel) for x in added]}）")
    check(app.sig_tree.selection() == (f"s{added[0].uid}",) if added else False, "放下的訊號被選取")
    n0 = len(app.signals)
    rx, ry = at(2)
    drop(rx, ry, [os.path.join(ext2, "same.txt")])
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == 2 and added[0].key == "same.txt#2" and added[0].name == "same.txt",
          f"另一個資料夾的同名檔：不會被當成同一條（key #2、名稱不變）（{[(x.key, x.name) for x in added]}）")
    n0 = len(app.signals)
    rx, ry = at(2)
    drop(rx, ry, [os.path.join(ext, "same.txt")])
    check(len(app.signals) == n0 and "P2 已經有" in app.status_var.get(), f"同一個檔案再放進 P2：略過（{app.status_var.get()[:30]}）")
    rx3, ry3 = at(3)
    drop(rx3, ry3, [os.path.join(ext, "same.txt")])
    check(len(app.signals) == n0 + 1 and app.signals[-1].panel == 3, "同一個檔案放進 P3：再一份（不同 panel 可以各一份）")
    rx4, ry4 = at(4)
    n0 = len(app.signals)
    drop(rx4, ry4, [os.path.join(ext, "two.csv")])
    added = app.signals[n0:]
    check(len(added) == 2 and all(x.panel == 4 for x in added), f"CSV 放進 P4：兩欄都進 P4（{[(x.key, x.panel) for x in added]}）")
    app.undo_action(); app.update()
    check(len(app.signals) == n0, "復原拖放加入")
    lw = app.sig_tree
    n0, pmax = len(app.signals), max(s_.panel for s_ in app.signals)
    drop(lw.winfo_rootx() + 20, lw.winfo_rooty() + 30, [os.path.join(ext, "new.txt")])
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == pmax + 1 and app.sig_tree.selection() == (f"s{added[0].uid}",),
          f"放在清單上（圖以外）→ 開新 panel P{pmax + 1}、選取（{[(x.key, x.panel) for x in added]}）")
    if app._plot_scrollable():
        check(app.plot_scroll.yview()[1] > 0.99, f"新 panel 在最下面：畫布捲過去（{app.plot_scroll.yview()}）")
    app.plot_scroll.yview_moveto(0); app.update()
    rx1, ry1 = center_of(1)
    st0 = app.status_var.get()
    drop(rx1, ry1, [os.path.join(ext, "new.txt")], leave="hover", settle=0.0)      # 拖到 P1 上面停著
    w_ = app.canvas.get_tk_widget()
    hint = w_.find_withtag("dsv_drop_hint")
    hint_ok = bool(hint) and w_.coords(hint[0])[1] < (center_of(1)[1] - w_.winfo_rooty()) < w_.coords(hint[0])[3]
    st_hover = app.status_var.get()
    drop(rx1, ry1, [os.path.join(ext, "new.txt")], leave=True, settle=0.3)        # 離開（不放）
    check(HL or (hint_ok and st_hover.startswith("放開以加到 P1") and not w_.find_withtag("dsv_drop_hint") and app.status_var.get() == st0),
          f"拖到 P1 上：P1 框起來、狀態列說明；離開後框消失、狀態列恢復（{st_hover[:30]}）")
    app.clear_all(); app.update()
    app.apply_settings(cfg0, quiet=True); app.update()   # 回到 s28 開始前的訊號與設定


def _child_env(home, **extra):
    """子行程 DSV（真的第二個行程：s29、U9、s49、s51、s54…）的環境：個人資料夾全部指到測試的 home——HOME（macOS／Linux）、
    USERPROFILE（Windows 的 expanduser 從 Python 3.8 起只看它、不看 HOME）、APPDATA／LOCALAPPDATA（Windows 的設定與凍結資料夾）、
    XDG_DATA_HOME（Linux）；字型快取共用（MPLCONFIGDIR，新 HOME 不用重建好幾秒）。
    0.9.13 W5（verify_win_0912.md）：以前只設 HOME／LOCALAPPDATA，Windows 上子行程讀寫的是**真的** %USERPROFILE%\\.signal_viewer_last.json。"""
    import matplotlib
    env = dict(os.environ, HOME=home, USERPROFILE=home, APPDATA=home, LOCALAPPDATA=home, XDG_DATA_HOME=home, MPLCONFIGDIR=matplotlib.get_configdir())
    env.update(extra)
    return env


_S29_CHILD = r'''
import os, sys, json
repo, home, mode = sys.argv[1], sys.argv[2], sys.argv[3]
sys.path.insert(0, repo)
import tests_common; tests_common.install_quiet()
import signal_viewer as sv
sv.frozen_data_dir = (lambda d=os.path.join(home, "frozen"): d)
marks = os.path.join(home, "marks.txt")
def note(s):
    with open(marks, "a", encoding="utf-8") as f:
        f.write(s + "\n")
note("home " + sv.HOME + " | " + sv.AUTOSAVE_PATH + " | " + sv.frozen_data_dir())
for _n in ("showerror", "showinfo", "showwarning", "askyesno", "askokcancel", "askyesnocancel", "askquestion", "askretrycancel"):
    setattr(sv.messagebox, _n, (lambda *a, _n=_n, **k: note("native " + _n + " " + json.dumps([str(x) for x in a[:2]], ensure_ascii=False))))
app = sv.SignalViewer(root_dir=None, autorestore=True)
sv._install_quit_signals(app)
def limit_writes():
    import resource
    n = len(json.dumps(app.dump_settings(), ensure_ascii=False, indent=2).encode("utf-8"))
    soft, hard = resource.getrlimit(resource.RLIMIT_FSIZE)
    resource.setrlimit(resource.RLIMIT_FSIZE, (max(1, n // 2), hard))    # 從這裡開始「磁碟滿」：寫到一半核心回 EFBIG
step = {"k": 0}
def poll():
    ds = list(getattr(sv, "_TK_DIALOGS", []))
    if not ds:
        app.after(50, poll)
        return
    d = ds[0]
    note("dialog " + d.title() + " | " + " / ".join(str(b.cget("text")) for b in d.buttons.values()))
    if mode == "ro_close":
        d.buttons[True].invoke()                                              # 照樣關閉
    if mode == "stay_close":
        if step["k"] == 0:
            step["k"] = 1
            d.buttons[False].invoke()
            app.after(150, lambda: note("stayed " + app.status_var.get()))
            app.after(400, app.on_close)
            app.after(450, poll)
        else:
            d.buttons[True].invoke()
def start():
    nt = getattr(app, "_autosave_notice", None)
    alive = nt is not None and nt.winfo_exists()
    note("start " + json.dumps({"n": len(app.signals), "notice": nt.title() if alive else None,
                                "msg": getattr(nt, "message", None) if alive else None}, ensure_ascii=False))
    if mode in ("dialog_term", "stay_close", "ro_close"):
        if mode == "ro_close":
            sv.log("s29：自動存檔的資料夾改成不能寫入")                          # 先有 log 檔（資料夾不能寫入之後只能接著寫、建不了）
            os.chmod(home, 0o555)                                             # 自動存檔的資料夾不能寫入（檔案本身可以寫）
        limit_writes()
        app.after(10, app.on_close)
        app.after(60, poll)
    else:
        if mode == "idle_full":
            limit_writes()
        note("ready")
app.after(1500, start)
app.mainloop()
note("exit")
'''


def _s29_u12_u13():
    """第九輪（2026-10-26 使用者決定 U12、U13），真的獨立行程（安靜模式、暫存 HOME：DSV 預設的自動存檔路徑、log、frozen 都在測試目錄）：
    (1) 關閉時自動存檔寫不下去（RLIMIT_FSIZE，核心回 EFBIG）→ 跳真的「照樣關閉／先不關」對話框（Tk 畫的）；開著的時候收到 SIGTERM
        （更新後自動重啟）→ 2 秒內結束、rc 0，上一份自動存檔一個位元組都不動、log 寫照樣關閉——對話框擋不住結束訊號。
    (2) 閒置時磁碟滿、收到 SIGTERM：不跳對話框，2 秒內結束，上一份自動存檔不動，log 寫原因。
    (3) 對話框按「先不關」→ 程式還開著、狀態列說明；再關一次、按「照樣關閉」→ 結束，上一份自動存檔不動。
    (4) 自動存檔被截斷：開啟時另存 .bad.json、從空的開始、跳提示（不擋操作）；提示開著時收到 SIGTERM 照樣 2 秒內結束，
        新的自動存檔寫好之後清理：備份還在，凍結檔一個都不清（第十輪 U15：沒提到的也留著）。
    第十輪：(5) 自動存檔的資料夾不能寫入（檔案本身可以寫）、磁碟又滿 → 關閉照 U12 問，照樣關閉時上一份一個位元組都不動（以前直接覆寫、截斷）；
    (6) U15：截斷在 "signals" 之前、整份 NUL → 備份還在時開關幾次都一個凍結檔都不清，備份刪掉之後再開才照常清；
    (7) 沒有讀取權限 → 提示寫「沒有讀取權限」、整個改名成備份、先修好權限再匯入，提示開著時 SIGTERM 照樣 2 秒內結束。
    第十一輪：(8) 自動存檔是捷徑、它指的檔不在 → 提示、捷徑改名成備份、凍結檔不清、SIGTERM 照樣 2 秒內結束、那個檔不會被建出來；
    (9) 自動存檔結構不對（"view" 不是物件）→ 提示寫原因、另存備份，關閉、再開都一個凍結檔都不清。
    第十二輪：(10) 自動存檔讀得了、一條獨立訊號的 "panel" 是文字 → 其他的照常還原、提示寫出那一條、另存備份，提示開著時 SIGTERM 照樣 2 秒內結束，
    關閉、再開都一個凍結檔都不清。"""
    import json
    import signal as _signal
    import subprocess
    import matplotlib
    child = os.path.join(OUT, "s29_child.py")
    with open(child, "w", encoding="utf-8") as f:
        f.write(_S29_CHILD)

    def _home(tag):
        h = os.path.join(OUT, "s29", tag)
        shutil.rmtree(h, ignore_errors=True)
        os.makedirs(h)
        return h

    def _session_autosave(h):
        """一份正常的自動存檔：一個 CSV 的兩條訊號（開啟時還原）。"""
        csvp = os.path.join(h, "a.csv")
        with open(csvp, "w", encoding="utf-8") as f:
            f.write("s29 i,s29 q\n" + "\n".join(f"{math.cos(k / 9.0):.6f},{math.sin(k / 9.0):.6f}" for k in range(400)) + "\n")
        cfg = {"version": 6, "root": "", "view": {"autosave": True, "lang": "zh"}, "signals": [
            {"key": "a.csv;;s29 i", "path": csvp, "column": "s29 i", "sps": 1.0, "panel": 1, "uid": 1},
            {"key": "a.csv;;s29 q", "path": csvp, "column": "s29 q", "sps": 1.0, "panel": 2, "uid": 2}]}
        p = os.path.join(h, ".signal_viewer_last.json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        return p

    def _run(h, mode):
        env = _child_env(h)
        env.pop("DSV_TEST_ONLY", None)
        env.pop("DSV_LANG", None)
        return subprocess.Popen([sys.executable, child, PROJECT, h, mode], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)

    def _marks(h):
        p = os.path.join(h, "marks.txt")
        return open(p, encoding="utf-8").read() if os.path.exists(p) else ""

    def _wait(p, h, word, timeout=60):
        t0 = time.time()
        while time.time() - t0 < timeout and p.poll() is None and word not in _marks(h):
            time.sleep(0.05)
        return word in _marks(h)

    def _term(p):
        t1 = time.time()
        p.send_signal(_signal.SIGTERM)
        try:
            rc = p.wait(timeout=10)
        except subprocess.TimeoutExpired:
            p.kill()
            rc = None
        return rc, time.time() - t1

    def _log(h):
        p = os.path.join(h, "signal_viewer.log")
        return open(p, encoding="utf-8").read() if os.path.exists(p) else ""

    def _err(p):
        """子行程的 stderr 有 Traceback 才附上（字型警告之類不算）。"""
        try:
            e_ = (p.stderr.read() or b"").decode("utf-8", "replace") if p.stderr else ""
        except Exception:
            return ""
        return e_[-300:] if "Traceback" in e_ else ""
    # (1) 對話框開著時收到 SIGTERM
    h = _home("dialog_term")
    auto = _session_autosave(h)
    before = open(auto, "rb").read()
    p = _run(h, "dialog_term")
    shown = _wait(p, h, "dialog ")
    time.sleep(0.3)
    alive = p.poll() is None
    rc, dt = _term(p) if alive else (p.returncode, None)
    log = _log(h)
    ok = (shown and alive and rc == 0 and dt is not None and dt < 2.0 and open(auto, "rb").read() == before
          and "照樣關閉" in log and "上一份自動存檔沒動" in log and "Traceback" not in log)
    check(ok, f"U12（獨立行程）：關閉時自動存檔寫不下去 → 跳「照樣關閉／先不關」（{shown}：{_marks(h).split('dialog ')[-1][:40]!r}）；"
              f"開著時收到 SIGTERM → {dt if dt is None else round(dt, 2)} s 內結束（rc {rc}），上一份自動存檔不動、log 寫照樣關閉 {_err(p)}")
    # (2) 閒置時磁碟滿、收到 SIGTERM
    h = _home("idle_full")
    auto = _session_autosave(h)
    before = open(auto, "rb").read()
    p = _run(h, "idle_full")
    ready = _wait(p, h, "ready")
    time.sleep(0.5)
    rc, dt = _term(p) if p.poll() is None else (p.returncode, None)
    log = _log(h)
    ok = (ready and rc == 0 and dt is not None and dt < 2.0 and open(auto, "rb").read() == before and "dialog " not in _marks(h)
          and "自動存檔失敗（結束訊號）" in log and "收到結束訊號，照樣關閉" in log and "File too large" in log)
    check(ok, f"U12（獨立行程）：閒置時磁碟滿、收到 SIGTERM → 不跳對話框、{dt if dt is None else round(dt, 2)} s 內結束（rc {rc}），"
              f"上一份自動存檔不動、log 寫原因 {_err(p)}")
    # (3) 先不關 → 還開著；再關、照樣關閉 → 結束
    h = _home("stay_close")
    auto = _session_autosave(h)
    before = open(auto, "rb").read()
    p = _run(h, "stay_close")
    done = _wait(p, h, "exit", timeout=90)
    try:
        rc = p.wait(timeout=10)
    except subprocess.TimeoutExpired:
        p.kill()
        rc = None
    m = _marks(h)
    stayed = next((ln[7:] for ln in m.splitlines() if ln.startswith("stayed ")), "")
    hm = next((ln[5:] for ln in m.splitlines() if ln.startswith("home ")), "")
    parts = hm.split(" | ")
    check(len(parts) == 3 and all(x == h or x.startswith(h + os.sep) for x in parts),
          f"W5：子行程的個人資料夾、自動存檔、凍結資料夾都在測試的 home 裡（{hm[:150]}）——Windows 的 expanduser 只看 USERPROFILE（_child_env）")
    ok = (done and rc == 0 and m.count("dialog ") == 2 and stayed.startswith("沒有關閉") and open(auto, "rb").read() == before
          and "使用者選「先不關」" in _log(h) and "使用者選「照樣關閉」" in _log(h))
    check(ok, f"U12（獨立行程）：按「先不關」→ 程式還開著、狀態列「{stayed[:30]}」；再關一次按「照樣關閉」→ 結束（rc {rc}），"
              f"上一份自動存檔不動 {_err(p)}")
    # (4) 自動存檔被截斷
    h = _home("corrupt")
    fz = os.path.join(h, "frozen")
    os.makedirs(fz)
    named, cut, orphan = "s29_named_" + "4d" * 10 + ".npy", "s29_cut_" + "5e" * 10 + ".npy", "s29_orphan_" + "6f" * 10 + ".npy"
    for n_ in (named, cut, orphan):
        np.save(os.path.join(fz, n_), np.arange(3.0))
    full = json.dumps({"version": 6, "signals": [{"key": "x", "path": os.path.join(fz, named), "column": None},
                                                 {"key": "y", "path": os.path.join(fz, cut), "column": None}]}, indent=2)
    bad = full[:full.index(cut) + 10]
    auto = os.path.join(h, ".signal_viewer_last.json")
    with open(auto, "w", encoding="utf-8") as f:
        f.write(bad)
    p = _run(h, "corrupt")
    ready = _wait(p, h, "ready")
    st_line = next((ln[6:] for ln in _marks(h).splitlines() if ln.startswith("start ")), "{}")
    st = json.loads(st_line) if st_line.startswith("{") else {}
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    bak_ok = os.path.isfile(bak) and open(bak, encoding="utf-8").read() == bad
    time.sleep(0.3)
    rc, dt = _term(p) if p.poll() is None else (p.returncode, None)
    try:
        new_ok = bool(json.load(open(auto, encoding="utf-8")).get("version"))
    except Exception:
        new_ok = False
    left = sorted(n for n in os.listdir(fz) if n.endswith(".npy"))
    ok = (ready and st.get("n") == 0 and st.get("notice") == "上次的工作階段讀不回來" and bak_ok and rc == 0 and dt is not None
          and dt < 2.0 and new_ok and left == sorted([named, cut, orphan]) and open(bak, encoding="utf-8").read() == bad)
    check(ok, f"U13（獨立行程）：自動存檔被截斷 → 從空的開始（{st.get('n')} 條）、提示「{st.get('notice')}」、另存 .bad.json（{bak_ok}）；"
              f"提示開著時 SIGTERM → {dt if dt is None else round(dt, 2)} s 內結束（rc {rc}），新的自動存檔寫好（{new_ok}），"
              f"備份還在就一個凍結檔都不清（U15：剩 {left}）{_err(p)}")
    # ---- 第十輪（2026-10-26 使用者決定 U15、第九輪驗證回報的兩項）----
    # (5) 自動存檔的資料夾不能寫入（檔案本身可以寫）、磁碟又滿（RLIMIT_FSIZE）：關閉跳「照樣關閉／先不關」，按照樣關閉 → 上一份一個位元組都不動
    h = _home("ro_close")
    auto = _session_autosave(h)
    before = open(auto, "rb").read()
    p = _run(h, "ro_close")
    done = _wait(p, h, "exit", timeout=90)
    try:
        rc = p.wait(timeout=10)
    except subprocess.TimeoutExpired:
        p.kill()
        rc = None
    os.chmod(h, 0o755)
    m = _marks(h)
    tmp_left = [n_ for n_ in os.listdir(h) if ".tmp" in n_]
    ok = (done and rc == 0 and m.count("dialog ") == 1 and open(auto, "rb").read() == before and not tmp_left
          and "native " not in m and "使用者選「照樣關閉」" in _log(h))
    check(ok, f"(b)（獨立行程）：自動存檔的資料夾不能寫入（檔案本身可以寫）、磁碟又滿 → 關閉跳「照樣關閉／先不關」（{m.count('dialog ')} 次），"
              f"按照樣關閉 → 結束（rc {rc}），上一份自動存檔一個位元組都不動（{open(auto, 'rb').read() == before}）、不直接覆寫、"
              f"不留暫存檔（{tmp_left}）{_err(p)}")

    # (6) U15：自動存檔截斷在 "signals" 之前、整份 NUL（文字裡看不到任何凍結檔名）→ 備份還在的期間開關幾次都一個凍結檔都不清；
    #     備份刪掉之後再開才照常清
    def _u15_home(tag, kind):
        h_ = _home(tag)
        fz_ = os.path.join(h_, "frozen")
        os.makedirs(fz_)
        nm = ["s29_u15a_" + "1d" * 10 + ".npy", "s29_u15b_" + "2e" * 10 + ".npy", "s29_u15c_" + "3f" * 10 + ".npy"]
        for n_ in nm:
            np.save(os.path.join(fz_, n_), np.arange(4.0))
        full_ = json.dumps({"version": 6, "root": "", "view": {"autosave": True, "lang": "zh"},
                            "signals": [{"key": "x", "path": os.path.join(fz_, nm[0]), "column": None},
                                        {"key": "y", "path": os.path.join(fz_, nm[1]), "column": None}]}, indent=2)
        bad_ = full_[:full_.index('"signals"') - 3] if kind == "early" else "\0" * len(full_)
        with open(os.path.join(h_, ".signal_viewer_last.json"), "w", encoding="utf-8") as f_:
            f_.write(bad_)
        return h_, fz_, sorted(nm), bad_

    def _start_line(h_):
        ln = next((x_[6:] for x_ in _marks(h_).splitlines() if x_.startswith("start ")), "{}")
        try:
            return json.loads(ln)
        except ValueError:
            return {}

    def _cycle(h_):
        """開一次 DSV（安靜模式）、等開好、送 SIGTERM（關閉時寫好新的自動存檔、接著清凍結檔）。回傳 (開好了嗎, rc, 開啟時的狀態)。"""
        mp = os.path.join(h_, "marks.txt")
        if os.path.exists(mp):
            os.remove(mp)
        p_ = _run(h_, "idle")
        ready_ = _wait(p_, h_, "ready")
        st_ = _start_line(h_)
        time.sleep(0.3)
        rc_, _dt = _term(p_) if p_.poll() is None else (p_.returncode, None)
        return ready_, rc_, st_, p_

    u15 = "只要自動存檔旁邊還有任何一份備份（.signal_viewer_last.bad*.json），frozen 資料夾裡的獨立訊號資料檔就一個都不會被自動清掉"
    h, fz, nm, bad = _u15_home("u15_early", "early")
    r1, rc1, st1, p = _cycle(h)
    left1 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    bak_ok = os.path.isfile(bak) and open(bak, encoding="utf-8").read() == bad
    r2, rc2, st2, p = _cycle(h)                                       # 再開一次：自動存檔讀得了、備份還在
    left2 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    ok = (r1 and r2 and rc1 == 0 and rc2 == 0 and st1.get("n") == 0 and st1.get("notice") == "上次的工作階段讀不回來"
          and u15 in (st1.get("msg") or "") and "不需要了就把這些備份都刪掉" in (st1.get("msg") or "") and bak_ok
          and left1 == nm and left2 == nm and st2.get("notice") is None)
    check(ok, f"U15（獨立行程）：自動存檔截斷在 \"signals\" 之前（文字裡沒有任何凍結檔名）→ 提示寫「只要還有任何一份備份就一個都不清」"
              f"（{u15 in (st1.get('msg') or '')}）；關閉（SIGTERM，rc {rc1}）、再開再關（rc {rc2}）凍結檔一個都沒刪（{len(left1)}／{len(left2)} 個）{_err(p)}")
    for n_ in os.listdir(h):
        if n_.startswith(".signal_viewer_last.bad"):
            os.remove(os.path.join(h, n_))
    r3, rc3, st3, p = _cycle(h)                                       # 備份刪掉：照常清
    left3 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    check(r3 and rc3 == 0 and left3 == [], f"U15（獨立行程）：備份刪掉之後再開，沒人用到的凍結檔照常清掉（剩 {left3}）{_err(p)}")
    h, fz, nm, bad = _u15_home("u15_nul", "nul")
    r4, rc4, st4, p = _cycle(h)
    left4 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    check(r4 and rc4 == 0 and st4.get("n") == 0 and u15 in (st4.get("msg") or "") and left4 == nm,
          f"U15（獨立行程）：自動存檔整份變成 NUL → 提示同上、關閉後凍結檔一個都沒刪（{len(left4)} 個）{_err(p)}")

    # (7) 自動存檔沒有讀取權限：提示寫「沒有讀取權限」、整個改名成備份（權限照舊 000）、先修好權限再匯入；提示開著時 SIGTERM 照樣 2 秒內結束
    h = _home("noread")
    fz = os.path.join(h, "frozen")
    os.makedirs(fz)
    orphan10 = "s29_noread_" + "4a" * 10 + ".npy"
    np.save(os.path.join(fz, orphan10), np.arange(3.0))
    auto = _session_autosave(h)
    os.chmod(auto, 0)
    p = _run(h, "idle")
    ready = _wait(p, h, "ready")
    st = _start_line(h)
    time.sleep(0.3)
    rc, dt = _term(p) if p.poll() is None else (p.returncode, None)
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    mode = (os.stat(bak).st_mode & 0o777) if os.path.exists(bak) else None
    msg = st.get("msg") or ""
    try:
        new_ok = bool(json.load(open(auto, encoding="utf-8")).get("version"))
    except Exception:
        new_ok = False
    left = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    ok = (ready and st.get("n") == 0 and "原因：沒有讀取權限（[Errno 13]" in msg and "沒有寫入權限" not in msg
          and "整個改名成備份" in msg and bak in msg and "先修好它的權限" in msg and "另存了一份" not in msg
          and mode == 0 and rc == 0 and dt is not None and dt < 2.0 and new_ok and left == [orphan10])
    if os.path.exists(bak):
        os.chmod(bak, 0o644)
    check(ok, f"(c)（獨立行程）：自動存檔沒有讀取權限 → 提示寫「沒有讀取權限」、整個改名成備份（權限 {oct(mode) if mode is not None else None}）、"
              f"先修好權限再匯入；提示開著時 SIGTERM → {dt if dt is None else round(dt, 2)} s 內結束（rc {rc}），新的自動存檔寫好（{new_ok}），"
              f"凍結檔沒刪（{left}）：{msg[:160]!r}{_err(p)}")

    # ---- 第十一輪（2026-10-26 第十輪驗證回報）----
    # (8) 自動存檔是捷徑、它指的檔不在（外接磁碟沒接上）：開啟時提示寫出捷徑指到哪裡、捷徑本身改名成備份（還是指著那個檔）、凍結檔一個都不清；
    #     提示開著時 SIGTERM 照樣 2 秒內結束，關閉時在原處寫一份新的自動存檔，那個檔不會被建出來（以前開啟時就把凍結檔全部刪掉）
    h = _home("dangling_link")
    fz = os.path.join(h, "frozen")
    os.makedirs(fz)
    nm11 = sorted(["s29_link_" + "7a" * 10 + ".npy", "s29_link_" + "8b" * 10 + ".npy"])
    for n_ in nm11:
        np.save(os.path.join(fz, n_), np.arange(3.0))
    target = os.path.join(h, "ext", "real.json")
    auto = os.path.join(h, ".signal_viewer_last.json")
    os.symlink(target, auto)
    p = _run(h, "idle")
    ready = _wait(p, h, "ready")
    st = _start_line(h)
    time.sleep(0.3)
    rc, dt = _term(p) if p.poll() is None else (p.returncode, None)
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    msg = st.get("msg") or ""
    left = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    try:
        new_ok = (not os.path.islink(auto)) and bool(json.load(open(auto, encoding="utf-8")).get("version"))
    except Exception:
        new_ok = False
    ok = (ready and st.get("n") == 0 and st.get("notice") == "上次的工作階段讀不回來" and "捷徑指的檔不在" in msg and target in msg
          and os.path.islink(bak) and sv.readlink_plain(bak) == target and rc == 0 and dt is not None and dt < 2.0 and new_ok
          and not os.path.exists(target) and left == nm11)
    check(ok, f"第十一輪（獨立行程）：自動存檔是捷徑、它指的檔不在 → 提示「{st.get('notice')}」寫出捷徑指到哪裡、捷徑改名成備份"
              f"（{sv.readlink_plain(bak) if os.path.islink(bak) else None}）、凍結檔一個都沒刪（{left}）；SIGTERM → "
              f"{dt if dt is None else round(dt, 2)} s 內結束（rc {rc}），原處寫了新的自動存檔（{new_ok}）、那個檔沒被建出來"
              f"（{not os.path.exists(target)}）{_err(p)}")
    # (9) 自動存檔 JSON 讀得出來、結構不對（"view" 不是物件）：提示寫出原因、另存備份、從空的開始；關閉、再開，凍結檔一個都不清
    #     （以前只記 log、不提示，關閉時整個蓋掉，接著清掉它用到的凍結檔）
    h = _home("bad_view")
    fz = os.path.join(h, "frozen")
    os.makedirs(fz)
    nmv = "s29_view_" + "9c" * 10 + ".npy"
    np.save(os.path.join(fz, nmv), np.arange(3.0))
    text = json.dumps({"version": 6, "root": "", "view": 5, "signals": [{"key": "x", "path": os.path.join(fz, nmv), "column": None, "uid": 1}]})
    with open(os.path.join(h, ".signal_viewer_last.json"), "w", encoding="utf-8") as f:
        f.write(text)
    r9, rc9, st9, p = _cycle(h)
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    bak_ok = os.path.isfile(bak) and open(bak, encoding="utf-8").read() == text
    left9 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    r10, rc10, st10, p = _cycle(h)                                    # 再開一次：自動存檔讀得了、備份還在
    left10 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    ok = (r9 and r10 and rc9 == 0 and rc10 == 0 and st9.get("n") == 0 and st9.get("notice") == "上次的工作階段讀不回來"
          and '設定檔的 "view" 不是 JSON 物件' in (st9.get("msg") or "") and bak_ok and left9 == [nmv] and left10 == [nmv]
          and st10.get("notice") is None)
    check(ok, f"第十一輪（獨立行程）：自動存檔的 \"view\" 不是物件 → 提示寫出原因（{(st9.get('msg') or '')[60:110]!r}）、另存備份（{bak_ok}）；"
              f"關閉（rc {rc9}）、再開再關（rc {rc10}），凍結檔一個都沒刪（{left9}／{left10}）{_err(p)}")

    # ---- 第十二輪（2026-10-26 最後驗證回報）----
    # (10) 自動存檔是合法的 JSON，一條獨立訊號的 "panel" 是文字：其他的照常還原、提示「上次的工作階段有訊號沒還原」、另存備份；提示開著時 SIGTERM
    #      照樣 2 秒內結束；關閉、再開再關，凍結檔一個都不清（以前開啟時默默略過，第一次關閉就清掉那一條的檔，資料永久不見）
    h = _home("partial")
    fz = os.path.join(h, "frozen")
    os.makedirs(fz)
    nm12 = {"victim": "s29_victim_" + "1a" * 10 + ".npy", "good": "s29_good_" + "2b" * 10 + ".npy", "orphan": "s29_orph_" + "3c" * 10 + ".npy"}
    for n_ in nm12.values():
        np.save(os.path.join(fz, n_), np.arange(5.0))
    auto = _session_autosave(h)
    cfg12 = json.load(open(auto, encoding="utf-8"))
    cfg12["signals"] = [{"key": "s29 victim", "path": os.path.join(fz, nm12["victim"]), "column": None, "panel": "x", "uid": 7},
                        {"key": "s29 good", "path": os.path.join(fz, nm12["good"]), "column": None, "panel": 3, "uid": 8}] + cfg12["signals"]
    text12 = json.dumps(cfg12, ensure_ascii=False, indent=2)
    with open(auto, "w", encoding="utf-8") as f:
        f.write(text12)
    p = _run(h, "idle")
    ready = _wait(p, h, "ready")
    st = _start_line(h)
    time.sleep(0.3)
    rc, dt = _term(p) if p.poll() is None else (p.returncode, None)
    bak = os.path.join(h, ".signal_viewer_last.bad.json")
    bak_ok = os.path.isfile(bak) and open(bak, encoding="utf-8").read() == text12
    msg = st.get("msg") or ""
    left = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    try:
        new_refs = [os.path.basename(str(s_.get("path"))) for s_ in json.load(open(auto, encoding="utf-8")).get("signals") or []]
    except Exception:
        new_refs = None
    ok = (ready and st.get("n") == 3 and st.get("notice") == "上次的工作階段有訊號沒還原" and "s29 victim" in msg
          and '設定檔的 "signals[].panel" 不是整數' in msg and bak in msg and bak_ok and rc == 0 and dt is not None and dt < 2.0
          and new_refs is not None and nm12["victim"] not in new_refs and left == sorted(nm12.values()))
    check(ok, f"第十二輪（獨立行程）：自動存檔裡一條獨立訊號的 \"panel\" 是文字 → 其他 {st.get('n')} 條照常還原、提示「{st.get('notice')}」寫出那一條和原因、"
              f"另存備份（{bak_ok}）；提示開著時 SIGTERM → {dt if dt is None else round(dt, 2)} s 內結束（rc {rc}）；新的自動存檔不再記著它，"
              f"凍結檔一個都沒刪（{left}）{_err(p)}")
    r12, rc12, st12, p = _cycle(h)                                    # 再開一次：剩下的照常還原、不再提示；備份還在，照樣不清
    left12 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    check(r12 and rc12 == 0 and st12.get("n") == 3 and st12.get("notice") is None and left12 == sorted(nm12.values()),
          f"第十二輪（獨立行程）：再開再關 → {st12.get('n')} 條照常還原、不再提示；備份還在，凍結檔一個都沒刪（{left12}）{_err(p)}")


@step
def s29_sigterm_autosave():
    """SIGTERM（更新後自動重啟用）：獨立行程開 DSV（安靜模式），開好後閒置再送 SIGTERM → 2 秒內存好自動存檔並結束
    （2026-10-24 0.9.3 曾經 15 秒沒反應被強制結束、沒存到檔）。"""
    if sys.platform.startswith("win"):
        check(True, "（Windows 沒有 SIGTERM 重啟流程，略過）")
        return
    import signal as _signal
    import subprocess
    import matplotlib
    home = os.path.join(OUT, "sigterm_home")
    os.makedirs(home, exist_ok=True)
    auto = os.path.join(home, ".signal_viewer_last.json")
    ready = os.path.join(home, "ready")
    code = ("import sys; sys.path.insert(0, %r); import tests_common; tests_common.install_quiet(); import signal_viewer as sv; "
            "sv.frozen_data_dir = (lambda: %r); "      # 啟動時、寫完自動存檔會清凍結檔（U9）：只看測試目錄
            "app = sv.SignalViewer(root_dir=%r); sv._install_quit_signals(app); open(%r, 'w').write('1'); app.mainloop()") % (
        PROJECT, os.path.join(home, "frozen"), ROOT, ready)
    env = _child_env(home)   # 共用字型快取：不然新 HOME 要重建好幾秒
    p = subprocess.Popen([sys.executable, "-c", code], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    t0 = time.time()
    while time.time() - t0 < 60 and not os.path.exists(ready) and p.poll() is None:
        time.sleep(0.1)
    time.sleep(3.0)                                  # 開好後閒置（mainloop 卡在 Tcl_DoOneEvent）
    alive = p.poll() is None and os.path.exists(ready)
    m0 = os.path.getmtime(auto) if os.path.exists(auto) else 0.0
    t1 = time.time()
    p.send_signal(_signal.SIGTERM)
    try:
        rc = p.wait(timeout=10)
    except subprocess.TimeoutExpired:
        p.kill()
        rc = None
    dt = time.time() - t1
    err = (p.stderr.read() or b"").decode("utf-8", "replace") if p.stderr else ""
    saved = os.path.exists(auto) and os.path.getmtime(auto) > m0
    check(alive and rc == 0 and dt < 2.0 and saved, f"SIGTERM：{dt:.2f}s 內存好自動存檔並正常結束（rc {rc}）{err[-200:]}")
    _s29_u12_u13()                                   # 第九、十輪：自動存檔寫不進去時的關閉對話框擋不住 SIGTERM、讀不了的自動存檔、U15、資料夾不能寫入


@step
def s30_batch2_spectrum():
    """第二批 MATLAB 工具（2026-10-24）：頻譜視窗改成 MATLAB Spectrum Analyzer 的工具列——示波器／估計／量測＋情境分頁頻譜／頻譜圖；
    RBW／視窗長度／FFT 長度／視窗與衰減／重疊、雙邊、一般／最大值保持／最小值保持軌跡、頻譜圖（時間解析度、時間跨度、色彩範圍、
    色彩圖、重新指派、版面配置）、頻譜峰值搜尋（Peaks 面板、▼ 標記、縮放後重找）、設定檔往返與舊設定相容。"""
    import time as _time
    from contextlib import contextmanager
    DS = sv.dsv_spectrum

    class _TooBig(Exception):
        """測試的保險：要求超大的視窗、FFT 或頻譜圖時直接丟這個，舊版（沒有上限）才不會真的去配置幾 GB。"""

    @contextmanager
    def no_huge():
        dw0, welch0, sg0 = DS.design_window, DS.welch, DS.spectrogram

        def dw_(name, L, atten=DS.DEFAULT_ATTEN):
            if int(L) > 5_000_000:
                raise _TooBig(f"視窗 {int(L)} 點")
            return dw0(name, L, atten)

        def welch_(x, fs_, w_, nov, nfft=None, *a, **k):
            if int(nfft or len(w_)) > (1 << 24):
                raise _TooBig(f"FFT {int(nfft)} 點")
            return welch0(x, fs_, w_, nov, nfft, *a, **k)

        def sg_(x, fs_, w_, nov, nfft=None, *a, **k):
            cells = DS.num_segments(len(x), len(w_), nov) * int(nfft or len(w_))
            if cells > (1 << 26):
                raise _TooBig(f"頻譜圖 {cells} 格")
            return sg0(x, fs_, w_, nov, nfft, *a, **k)
        DS.design_window, DS.welch, DS.spectrogram = dw_, welch_, sg_
        try:
            yield
        finally:
            DS.design_window, DS.welch, DS.spectrogram = dw0, welch0, sg0

    def spin_of(w_, var_):
        """工具列上綁 var_ 的 Spinbox（找元件，不靠屬性名稱：舊版沒有 sp_overlap）。"""
        return next((c_ for c_ in strip_controls(w_.strip) if c_.winfo_class() == "TSpinbox" and str(c_.cget("textvariable")) == str(var_)), None)

    def fws(w_, var_):
        """工具列上綁 var_ 的欄位（Entry／下拉／Spinbox；刻度的參考負載、滿刻度在頻譜與頻譜圖分頁各一個）。找元件、不靠屬性名稱（舊版也能跑）。"""
        return [c_ for c_ in strip_controls(w_.strip) if c_.winfo_class() in ("TEntry", "TCombobox", "TSpinbox")
                and str(c_.cget("textvariable")) == str(var_)]

    def err_on(w_, var_, msg_):
        """欄位是共用的錯誤狀態、訊息是 msg_：每個顯示它的元件都紅框（invalid）、提示換成 msg_、說明列有 msg_。"""
        ws_ = fws(w_, var_)
        return bool(ws_) and all(c_.instate(["invalid"]) and getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ in w_.v_msg.get()

    def err_off(w_, var_, msg_):
        """欄位不是錯誤狀態：沒有紅框、提示不是訊息、說明列沒有 msg_。"""
        ws_ = fws(w_, var_)
        return bool(ws_) and not any(c_.instate(["invalid"]) or getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ not in w_.v_msg.get()
    FM = getattr(sv, "SPEC_FIELD_MESSAGES", {})                 # 第六輪的訊息表（舊版沒有：拿不到時用一句佔位的字，檢查照樣失敗、不丟例外）
    fm = lambda k_: FM.get(k_, "（第六輪的訊息）")                # noqa: E731
    fs = 8e6; n = 20000
    t = np.arange(n) / fs
    rng = np.random.default_rng(3)
    y1 = np.sin(2 * np.pi * 1e6 * t) + 0.01 * np.sin(2 * np.pi * 2.5e6 * t) + 1e-3 * rng.standard_normal(n)
    y2 = 0.5 * np.sin(2 * np.pi * 1.5e6 * t) + 1e-3 * rng.standard_normal(n)
    path = os.path.join(ROOT, "spec2_tones.csv")
    with open(path, "w") as f:
        f.write("Time,tone a,tone b\n")
        f.writelines(f"{tt:.12f},{a:.9f},{b:.9f}\n" for tt, a, b in zip(t, y1, y2))
    cfg0 = app.dump_settings()                       # 結束時整個還原（s9 要用這時候的訊號與設定）
    spec0 = dict(app.spec_defaults)
    app.v["symbol_rate"].set("1M")
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    sa = app.find_signal("spec2_tones.csv;;tone a"); sb = app.find_signal("spec2_tones.csv;;tone b")
    check(sa is not None and sb is not None and sa.sps == 8.0, f"合成兩個單音：SPS 8、symbol rate 1M → fs 8 MHz（sps={sa.sps if sa else None}）")
    app.spec_defaults.clear(); app.spec_defaults.update(sv.DEFAULT_SPEC)
    w = sv.SpectrumWindow(app, [sa]); app.update()
    # ---------------------------------------------------------------- 工具列（MATLAB R2025a spectrumAnalyzer 的分頁與區段）
    st = w.strip
    vis = [k for k in st._order if st.tab_visible(k)]
    secs = {k: [s_.title for s_ in st.tabs[k].sections] for k in st._order}
    check(vis == ["scope", "estimation", "measure", "spectrum", "mask", "chmeas"] and not st.tab_visible("spectrogram"),
          f"分頁：示波器／估計／量測＋情境分頁「頻譜」「頻譜遮罩」「通道量測」（照 MATLAB 的順序：頻譜檢視開著就有遮罩（類型不是 RMS、"
          f"單位不是線性時）與通道量測）；頻譜圖分頁要打開頻譜圖檢視才出現（{vis}）")
    check(secs["scope"] == ["檢視", "頻寬", "設定", "資料"] and secs["estimation"] == ["頻率解析度", "視窗選項"]
          and secs["measure"] == ["通道", "峰值", "失真"]
          and secs["spectrum"] == ["軌跡選項", "刻度"] and secs["spectrogram"] == ["通道", "時間選項", "軌跡選項", "刻度"],
          f"區段照 MATLAB：SCOPE（VIEWS／BANDWIDTH／CONFIGURATION）、ESTIMATION（FREQUENCY RESOLUTION／WINDOW OPTIONS）、"
          f"MEASUREMENTS（CHANNEL／PEAKS／DISTORTION；MATLAB 另有 CURSORS）、"
          f"SPECTRUM（TRACE OPTIONS／SCALE）、SPECTROGRAM（CHANNEL／TIME OPTIONS／TRACE OPTIONS／SCALE）（{secs}）")
    combos = [c for c in strip_controls(st) if c.winfo_class() == "TCombobox"]
    wins = next((list(c.cget("values")) for c in combos if str(c.cget("textvariable")) == str(w.v_window_label)), [])
    check(wins == ["Blackman-Harris", "Chebyshev", "Flat Top", "Hamming", "Hann", "Kaiser", "Rectangular"],
          f"視窗清單＝MATLAB 的 7 種、同樣順序（{wins}）")
    st_ = lambda wdg: str(wdg.cget("state"))       # noqa: E731
    check(st_(w.e_atten) == "disabled" and st_(w.e_wlen) == "disabled" and st_(w.cb_rbw) == "normal",
          "Hann 時「衰減」灰；解析度方法 RBW 時「視窗長度」灰、RBW 可填")
    # ---------------------------------------------------------------- 預設＝MATLAB：RBW Auto（fs/1024）、Hann、不重疊、雙邊、只有一般軌跡、圖例關
    info = w.v_info.get()
    ax = w.fig.axes[0]
    xs = ax.get_lines()[0].get_xdata()
    check("RBW = 7.8125kHz" in info and "視窗長度 = 1536" in info and "NFFT = 1536" in info and "重疊 = 0%" in info and "Navg = 13" in info,
          f"預設：RBW Auto＝8 MHz/1024＝7.8125 kHz → Hann 1536 點、NFFT 1536、不重疊、13 段平均（{info[:120]}）")
    check(len(w.lines) == 1 and ax.get_legend() is None and float(np.min(xs)) < -3.99e6 and float(np.max(xs)) == 4e6 and w.v_fs_text.get() == "8M",
          f"預設雙邊（−fs/2..fs/2，Nyquist 在正端）、只畫一般軌跡、沒有圖例；頻寬區顯示取樣率 8M（{w.v_fs_text.get()}）")
    r = DS.welch(sa.slice_range(*app.current_xlim())[0], 8e6, DS.design_window("hann", 1536), 0, 1536, "centered", detrend=True)
    check(np.allclose(np.asarray(ax.get_lines()[0].get_ydata()), sv.to_db(sv.spectrum_type_values("mag", r))),
          "畫出來的值＝dsv_spectrum.welch（和 MATLAB pwelch 逐筆比對過的那個）")
    # ---------------------------------------------------------------- 估計：RBW、視窗長度、FFT 長度、重疊、視窗與衰減
    w.v_rbw.set("10k"); w.compute()
    check("RBW = 10kHz" in w.v_info.get() and "視窗長度 = 1200" in w.v_info.get(), f"RBW 10k → Hann 1200 點（{w.v_info.get()[:90]}）")
    w.v_rbw.set("5M"); w.compute()
    check("RBW 太大" in w.v_msg.get() and len(w.lines) == 0, f"RBW 5M：頻寬／RBW ≤ 2 → 說明、不畫（{w.v_msg.get()[:60]}）")
    w.v_rbw.set("abc"); w.compute()
    check(w.v_rbw.get() == "abc" and err_on(w, w.v_rbw, fm("rbw")) and w.v_status.get() == "頻率解析度：" + fm("rbw")
          and "RBW 太大" in w.v_msg.get() and app.spec_defaults["rbw"] == "5M",
          "RBW 看不懂 → 照第三批的錯誤狀態（使用者 2026-10-26 決定）：打的字留著、紅框、提示／說明列／狀態列寫 MATLAB 的 RBW 錯誤訊息（狀態列前面寫區段"
          "「頻率解析度」），計算與設定檔用上一次合格的 5M（以前改回 Auto 並寫 DSV 的句子）")
    w.v_res_label.set("視窗長度"); w._on_res()
    w.v_wlen.set("4096"); w.v_overlap.set("50"); w.v_nfft.set("2048"); w.compute()
    info = w.v_info.get()
    check("視窗長度 = 4096" in info and "NFFT = 2048" in info and "重疊 = 50%" in info and "Navg = 8" in info
          and len(w.fig.axes[0].get_lines()[0].get_xdata()) == 2048 and st_(w.e_wlen) == "normal" and st_(w.cb_rbw) == "disabled",
          f"視窗長度 4096、重疊 50%（2048 點）→ 8 段；NFFT 2048＜視窗：折疊相加、2048 個頻率點（{info[:110]}）")
    w.v_overlap.set("100"); w.v_nfft.set("x"); w.compute()
    info = w.v_info.get()
    check(w.v_overlap.get() == "100" and w.v_nfft.get() == "x" and err_on(w, w.v_overlap, fm("overlap")) and err_on(w, w.v_nfft, fm("nfft").format(2))
          and "重疊 = 50%" in info and "NFFT = 2048" in info and app.spec_defaults["overlap"] == "50" and app.spec_defaults["nfft"] == "2048"
          and w.v_status.get() == "頻率解析度：" + fm("nfft").format(2),
          f"重疊 100、FFT 長度看不懂 → 打的字留著、兩個都紅框、說明列寫 MATLAB 的重疊與 FFT 長度錯誤訊息（{{0}}＝2），計算與設定檔"
          f"用上一次合格的 50%、2048，狀態列寫最後變成錯誤的那個（以前改回 0／Auto）（{info[:100]}）")
    w.v_overlap.set("0"); w.v_nfft.set("Auto"); w.v_rbw.set("Auto")
    w.v_res_label.set("RBW"); w._on_res()
    check(err_off(w, w.v_overlap, fm("overlap")) and err_off(w, w.v_nfft, fm("nfft").format(2)) and err_off(w, w.v_rbw, fm("rbw"))
          and w.v_status.get().startswith("已計算") and app.spec_defaults["overlap"] == "0" and app.spec_defaults["rbw"] == "",
          "改成合格的值（重疊 0、FFT 長度 Auto、RBW Auto）再算一次 → 三個欄位的紅框、提示、說明列都清掉，狀態列換回重新計算的那句，設定存新的值")
    w.v_rbw.set("Auto")
    nen = {}
    for k_ in DS.WINDOWS:
        w.v_window_label.set(DS.WINDOW_TEXT[k_]); w._on_window()
        m_ = re.search(r"NENBW = ([0-9.]+)", w.v_info.get())
        nen[k_] = float(m_.group(1)) if m_ else None
    check(abs(nen["hann"] - 1.5) < 1e-3 and abs(nen["rectangular"] - 1.0) < 1e-3 and abs(nen["flat-top"] - 3.77) < 0.01
          and abs(nen["blackman-harris"] - 2.004) < 0.01 and nen["kaiser"] and nen["chebyshev"], f"7 種視窗都算得出來，NENBW 對（{nen}）")
    w.v_window_label.set("Kaiser"); w._on_window()
    check(st_(w.e_atten) == "normal", "Kaiser／Chebyshev 時「衰減」可填")
    w.v_atten.set("30"); w.compute()
    check(w.v_atten.get() == "30" and err_on(w, w.v_atten, fm("atten")) and "Window = Kaiser (60 dB)" in w.v_info.get()
          and w.v_status.get() == "視窗選項：" + fm("atten") and app.spec_defaults["atten"] == "60",
          "衰減 < 45 dB（MATLAB 的下限）→ 打的字留著、紅框、MATLAB 的旁波瓣衰減錯誤訊息（狀態列「視窗選項：…」），用並存上一次合格的 60"
          "（以前改回 60 並寫 DSV 的句子）")
    w.v_atten.set("60"); w.compute()
    # ---------------------------------------------------------------- 數字欄位的單一規則（使用者 2026-10-25 決定；第四輪）：第二批的欄位也收 SI 字首
    # （以前視窗長度、FFT 長度、衰減、重疊、參考負載、滿刻度、色彩範圍只收一般數字，時間欄位只收 200us 這種時間單位），整串都要是數字；不收 Inf 的欄位
    # 打 Inf 不再被當成值、也不會讓重新計算整個失敗（視窗長度 Inf 以前 int() 丟 OverflowError）。錯的時候（第六輪起）照第三批的共用錯誤狀態：
    # 打的字留著、紅框、MATLAB 的錯誤訊息、用並存上一次合格的值（以前改回預設值並說明，參考負載與滿刻度不提示）
    def try_(fn):
        try:
            return fn()
        except Exception as ex_:                                 # noqa: BLE001 —— 42b4834：衰減 Inf 時 RBW 換算丟 ValueError、視窗長度 Inf 時 int() 丟 OverflowError
            return f"例外 {type(ex_).__name__}"
    w.v_atten.set("0.1k"); w.compute()
    att_si = (w.v_atten.get(), "Window = Kaiser (100 dB)" in w.v_info.get())
    att_inf = try_(lambda: (w.v_atten.set("Inf"), w.compute(), (w.v_atten.get(), err_on(w, w.v_atten, fm("atten")),
                                                                 "Window = Kaiser (100 dB)" in w.v_info.get()))[-1])
    w.v_atten.set("60"); w.v_window_label.set("Hann"); w._on_window()
    w.v_res_label.set("視窗長度"); w._on_res()
    w.v_wlen.set("2k"); w.v_nfft.set("4k"); w.v_overlap.set("0.05k"); w.compute()
    info = w.v_info.get()
    est_si = ("視窗長度 = 2000" in info, "NFFT = 4000" in info, "重疊 = 50%" in info, w.v_wlen.get(), w.v_nfft.get(), w.v_overlap.get())
    wl_inf = try_(lambda: (w.v_wlen.set("Inf"), w.compute(), (w.v_wlen.get(), err_on(w, w.v_wlen, fm("wlen")),
                                                               "視窗長度 = 2000" in w.v_info.get()))[-1])
    w.v_wlen.set("0x10"); w.compute()                          # 以前 parse_number 當成 16（重新計算前先換掉 Inf：42b4834 上才不會再丟一次例外）
    wl_hex = (w.v_wlen.get(), err_on(w, w.v_wlen, fm("wlen")), "視窗長度 = 2000" in w.v_info.get())
    w.v_res_label.set("RBW"); w._on_res(); w.v_wlen.set("1024"); w.v_nfft.set("Auto"); w.v_overlap.set("0")
    w.v_tres.set("200u"); w.compute()                          # 時間欄位：SI 字首（RBW Auto＋時間解析度 200 µs → RBW 5 kHz）
    tres_si = ("RBW = 5kHz" in w.v_info.get(), w.v_tres.get())
    w.v_tres.set("Auto")
    w.v_foffset.set("1e999"); w.compute()                      # 以前收成 Inf（頻率軸整個變 Inf）
    foff_inf = (w.v_foffset.get(), err_on(w, w.v_foffset, fm("foffset")), w._last_p["foffset"])
    w.v_foffset.set("0")                                       # 42b4834 上留著 1e999 的話後面的步驟全部跟著壞
    w.v_rload.set("0.05k"); w.compute()
    rl_si = (w._last_p["rload"], w.v_rload.get())
    w.v_rload.set("Inf"); w.compute()                          # 以前收成 Inf（功率全部變 0）；第五輪悄悄改回 1、第六輪是錯誤狀態、用上一次合格的 50
    rl_inf = (w._last_p["rload"], w.v_rload.get(), err_on(w, w.v_rload, fm("rload")))
    w.v_rload.set("1")
    w.v_fullscale.set("2k"); w.compute()                       # 以前 parse_number 看不懂、悄悄用 Auto
    fs_si = w._fullscale_for(w.signals)
    w.v_fullscale.set("Auto")
    w.v_clim.set("[-0.08k 0.02k]"); w.compute()
    clim_si = (w._last_p["clim"], w.v_clim.get())
    w.v_clim.set("-80, 20"); w.compute()
    check(att_si == ("0.1k", True) and att_inf == ("Inf", True, True) and est_si == (True, True, True, "2k", "4k", "0.05k")
          and wl_inf == ("Inf", True, True) and wl_hex == ("0x10", True, True) and tres_si == (True, "200u") and foff_inf == ("1e999", True, 0.0)
          and rl_si == (50.0, "0.05k") and rl_inf == (50.0, "Inf", True) and fs_si == (2000.0, "手動") and clim_si == ((-80.0, 20.0), "[-0.08k 0.02k]"),
          f"第二批的欄位照頻譜視窗數字欄位的單一規則：衰減 0.1k＝100 dB、視窗長度 2k、FFT 長度 4k、重疊 0.05k＝50%、時間解析度 200u、參考負載 0.05k＝50 Ω、"
          f"滿刻度 2k（手動）、色彩範圍 [-0.08k 0.02k]，打的字留著（以前除了頻率偏移與 RBW 都不收 SI 字首）；頻率偏移 1e999、參考負載 Inf 不再收成無限大，"
          f"衰減 Inf、視窗長度 Inf 不再讓重新計算丟例外、視窗長度 0x10 不再當 16——第六輪起是共用的錯誤狀態：打的字留著、紅框、MATLAB 的錯誤訊息，"
          f"用上一次合格的 100 dB、2000 點、偏移 0、參考負載 50（以前改回預設值，參考負載悄悄改回 1）"
          f"（{att_si}、{att_inf}、{est_si}、{wl_inf}、{wl_hex}、{tres_si}、{foff_inf}、{rl_si}、{rl_inf}、{fs_si}、{clim_si}）")
    # ---------------------------------------------------------------- 第五輪：單一規則的其他輸入；第六輪（使用者 2026-10-26 決定）起第二批的欄位打錯時照第三批的
    # 共用錯誤狀態——打的字留著、每個顯示它的元件都紅框、說明列寫 MATLAB 的錯誤訊息、狀態列寫「區段：訊息」、用上一次合格的值（以前改回預設值並寫 DSV 的句子）
    def after(var_, txt_, back_=None):
        """欄位打字後重新計算（Entry／下拉的 Enter 就是 compute）：(欄位的字, 說明列, 狀態列, 每個顯示它的元件是不是紅框)；back_＝記下結果後把欄位
        換回這個合格的字（下一次重新計算就清掉，錯誤不會一直累積）。重新計算丟例外時回傳例外名稱。"""
        w.v_msg.set("")
        var_.set(txt_)
        try:
            w.compute()
        except Exception as ex_:                                 # noqa: BLE001
            return f"例外 {type(ex_).__name__}"
        r_ = (var_.get(), w.v_msg.get(), w.v_status.get(), tuple(bool(c_.instate(["invalid"])) for c_ in fws(w, var_)))
        if back_ is not None:
            var_.set(back_)
        return r_

    def plus(r_, *extra):
        """after() 的結果再接幾個值（重新計算丟例外時 r_ 是字串，原樣傳回）。"""
        return r_ + tuple(extra) if isinstance(r_, tuple) else r_
    SEC = {"atten": "視窗選項", "overlap": "視窗選項", "rbw": "頻率解析度", "nfft": "頻率解析度", "wlen": "頻率解析度", "tres": "時間選項",
           "tspan": "時間選項", "foffset": "頻寬", "rload": "刻度", "fullscale": "刻度", "clim": "設定"}

    def is_err(r_, key_, txt_, nw_=1):
        """after() 的結果是 key_ 欄位的錯誤狀態：打的字 txt_ 留著、說明列有訊息、狀態列＝「區段：訊息」、nw_ 個元件都紅框。"""
        msg_ = fm("nfft").format(2) if key_ == "nfft" else fm(key_)
        return isinstance(r_, tuple) and r_[0] == txt_ and msg_ in r_[1] and r_[2] == SEC[key_] + "：" + msg_ and r_[3] == (True,) * nw_
    with no_huge():
        # 每個第二批欄位一筆「數字後面多打字」：取開頭數字（parseFloat）的寫法會收成合格的值，這條規則是錯
        w.v_window_label.set("Kaiser"); w._on_window()
        g5 = {"衰減 70abc": is_err(after(w.v_atten, "70abc", "60"), "atten", "70abc")}
        w.v_window_label.set("Hann"); w._on_window()
        g5["重疊 25abc"] = is_err(after(w.v_overlap, "25abc", "0"), "overlap", "25abc")
        g5["RBW 10kabc"] = is_err(after(w.v_rbw, "10kabc", "Auto"), "rbw", "10kabc")
        g5["FFT 長度 2048abc"] = is_err(after(w.v_nfft, "2048abc", "Auto"), "nfft", "2048abc")
        g5["時間解析度 1..2"] = is_err(after(w.v_tres, "1..2", "Auto"), "tres", "1..2")
        g5["時間跨度 1msx"] = is_err(after(w.v_tspan, "1msx", "Auto"), "tspan", "1msx")
        g5["頻寬的偏移 12abc"] = is_err(after(w.v_foffset, "12abc", "0"), "foffset", "12abc")
        r_ = after(w.v_rload, "50abc")
        g5["參考負載 50abc"] = is_err(r_, "rload", "50abc", 2) and w._last_p["rload"] == 1.0      # 兩個欄位（頻譜、頻譜圖的刻度）都紅
        w.v_rload.set("1")
        r_ = after(w.v_clim, "[-80 20abc]", "-80, 20")
        g5["色彩範圍 [-80 20abc]"] = is_err(r_, "clim", "[-80 20abc]", 0) and w._last_p["clim"] == (-80.0, 20.0)
        r_ = after(w.v_fullscale, "2kabc")
        g5["滿刻度 2kabc"] = is_err(r_, "fullscale", "2kabc", 2) and w._fullscale_for(w.signals)[1] != "手動"   # 上一次合格的 Auto：照資料猜
        w.v_fullscale.set("Auto")
        w.v_res_label.set("視窗長度"); w._on_res()
        g5["視窗長度 2048abc"] = is_err(after(w.v_wlen, "2048abc", "1024"), "wlen", "2048abc")
        # NaN：視窗長度以前讓 int() 丟 ValueError；參考負載、頻寬的偏移以前收成 NaN（整條頻譜 NaN、頻率軸 NaN）
        g5["視窗長度 NaN"] = is_err(after(w.v_wlen, "NaN", "1024"), "wlen", "NaN")
        r_ = after(w.v_wlen, "1.023k")                         # 字首十進位換算：整數 1023（以前 1022.9999…）
        g5["視窗長度 1.023k"] = isinstance(r_, tuple) and r_[0] == "1.023k" and r_[3] == (False,) and "視窗長度 = 1023" in w.v_info.get()
        w.v_wlen.set("1024")
        w.v_res_label.set("RBW"); w._on_res()
        r_ = after(w.v_rload, "NaN")
        g5["參考負載 NaN"] = is_err(r_, "rload", "NaN", 2) and w._last_p["rload"] == 1.0
        w.v_rload.set("1")
        r_ = after(w.v_foffset, "NaN")
        g5["頻寬的偏移 NaN"] = is_err(r_, "foffset", "NaN") and w._last_p["foffset"] == 0.0
        w.v_foffset.set("0")
        w.compute()
    bad5 = [k_ for k_, v_ in g5.items() if not v_]
    check(not bad5,
          f"第二批每個欄位的「數字後面多打字」都是錯，照共用的錯誤狀態（打的字留著、紅框——參考負載與滿刻度在頻譜、頻譜圖分頁的兩個欄位都紅——"
          f"說明列寫 MATLAB 的錯誤訊息、狀態列「區段：訊息」，用上一次合格的值）：衰減 70abc、重疊 25abc、RBW 10kabc、FFT 長度 2048abc、時間解析度 1..2、"
          f"時間跨度 1msx、頻寬的偏移 12abc、參考負載 50abc（以前悄悄改回 1）、色彩範圍 [-80 20abc]、滿刻度 2kabc（以前悄悄用 Auto）、視窗長度 2048abc；"
          f"NaN 不讓重新計算丟例外也不被收下（視窗長度、參考負載、頻寬的偏移）；視窗長度 1.023k＝1023（十進位換算，以前差 1 ulp 被當成非整數）"
          f"（{bad5 or '15 種都對'}）")
    # 收 SI 字首之後打得出來的超大值：衰減 10k／1.5M（以前重新計算丟 OverflowError／ValueError、壞值存進設定，開新視窗時建構子再丟一次）、
    # FFT 長度 1G（以前一段要 16 GB）、時間解析度 1.5M 秒與 RBW 5u（以前換算視窗長度時設計幾十億點的視窗）——都不丟例外、不配置幾 GB
    with no_huge():
        w.v_window_label.set("Chebyshev"); w._on_window()
        # （每一筆之後先把欄位換回合格的值：舊版不會改回，後面的操作才不會跟著丟例外）
        big5 = {"Chebyshev RBW 10k": plus(after(w.v_atten, "10k"), app.spec_defaults.get("atten"))}
        w.v_atten.set("60")
        big5["Chebyshev 6139 dB RBW"] = after(w.v_atten, "6139")              # RBW 換算視窗長度時 NENBW 是 NaN（以前 ValueError）→ 說明列
        w.v_atten.set("60")
        w.v_res_label.set("視窗長度"); w._on_res()
        big5["Chebyshev 視窗長度 1.5M"] = after(w.v_atten, "1.5M")
        w.v_atten.set("60"); w.v_wlen.set("4096")
        big5["Chebyshev 6139 dB 4096 點"] = after(w.v_atten, "6139")         # L＝1000 算得出來（欄位放行），4096 點的 Chebyshev 是 NaN
        w.v_atten.set("60"); w.v_wlen.set("1024")
        w.v_res_label.set("RBW"); w._on_res()
        w.v_window_label.set("Kaiser"); w._on_window()
        big5["Kaiser RBW 10k"] = after(w.v_atten, "10k")
        w.v_atten.set("60")
        w.v_window_label.set("Hann"); w._on_window()
        big5["FFT 長度 1G"] = after(w.v_nfft, "1G")
        w.v_nfft.set("Auto")
        big5["FFT 長度 16777217"] = after(w.v_nfft, "16777217")
        w.v_nfft.set("Auto")
        big5["時間解析度 1.5M"] = after(w.v_tres, "1.5M")
        w.v_tres.set("Auto")
        big5["RBW 5u"] = after(w.v_rbw, "5u")
        w.v_rbw.set("Auto")
        w.compute()
        spec_b = dict(app.spec_defaults)
        app.spec_defaults.update(window="chebyshev", atten="10k")              # 設定檔裡已經有壞值（舊版存的）：開新視窗不丟例外
        try:
            w2 = sv.SpectrumWindow(app, [sa]); app.update()
            big5["重開 Chebyshev 10k"] = (w2.v_atten.get(), w2.v_msg.get())
            w2.destroy()
        except Exception as ex_:                                 # noqa: BLE001
            big5["重開 Chebyshev 10k"] = f"例外 {type(ex_).__name__}"
            for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow) and c_ is not w]:
                try:                                             # 舊版建構子丟例外時留下沒建完的視窗：關掉，換主題時才不會再算一次、把壞值存回設定
                    t_.destroy()
                except Exception:                                # noqa: BLE001
                    pass
        app.spec_defaults.clear(); app.spec_defaults.update(spec_b)
        w.compute()
    m_big = "衰減 {v} dB 太大，算不出視窗"                       # DSV 的上限（MATLAB 沒有）：第六輪起是衰減欄位的錯誤狀態（以前改回 60 並說明）
    m_cap = "FFT 長度最多 2^24（16777216）點"
    m_short = "不夠一段視窗（{L} 點）"

    def big_err(r_, key_, msg_):
        """欄位的錯誤狀態（DSV 的上限訊息）：打的字留著、紅框、說明列與狀態列寫 msg_。"""
        return r_[1].count(msg_) >= 1 and r_[2] == SEC[key_] + "：" + msg_ and r_[3] == (True,)
    ok_big = {
        "Chebyshev RBW 10k": lambda r_: r_[0] == "10k" and big_err(r_, "atten", m_big.format(v="10000")) and r_[4] == "60",
        "Chebyshev 視窗長度 1.5M": lambda r_: r_[0] == "1.5M" and big_err(r_, "atten", m_big.format(v="1500000")),
        "Chebyshev 6139 dB 4096 點": lambda r_: r_[0] == "6139" and f"{sa.name}：衰減 6139 dB 太大，算不出視窗" in r_[1] and r_[3] == (False,),
        "Chebyshev 6139 dB RBW": lambda r_: r_[0] == "6139" and f"{sa.name}：衰減 6139 dB 太大，算不出視窗" in r_[1] and r_[3] == (False,),
        "Kaiser RBW 10k": lambda r_: r_[0] == "10k" and big_err(r_, "atten", m_big.format(v="10000")),
        "FFT 長度 1G": lambda r_: r_[0] == "1G" and big_err(r_, "nfft", m_cap),
        "FFT 長度 16777217": lambda r_: r_[0] == "16777217" and big_err(r_, "nfft", m_cap),
        "時間解析度 1.5M": lambda r_: r_[0] == "1.5M" and m_short.format(L=18_000_000_000_000) in r_[1] and r_[3] == (False,),
        "RBW 5u": lambda r_: r_[0] == "5u" and m_short.format(L=2_400_000_000_000) in r_[1] and r_[3] == (False,),
        "重開 Chebyshev 10k": lambda r_: r_[0] == "60" and "衰減" not in r_[1]}
    def ok5(k_, v_):
        try:
            return isinstance(v_, tuple) and bool(ok_big[k_](v_))
        except Exception:                                        # noqa: BLE001 —— 長度不對之類：當成不對
            return False
    bad_big = {k_: v_ for k_, v_ in big5.items() if not ok5(k_, v_)}
    check(not bad_big,
          f"收 SI 字首之後打得出來的超大值不丟例外、不配置幾 GB：衰減 10k／1.5M（Chebyshev、Kaiser，RBW 與視窗長度模式）是衰減欄位的錯誤狀態——打的字留著、"
          f"紅框、說明列與狀態列寫 DSV 的「衰減 … dB 太大，算不出視窗」、用並存上一次合格的 60（第五輪改回 60）；設定檔裡已經有 10k 時開新視窗：換回預設 60、"
          f"不提示（和第三批的欄位一樣；以前 OverflowError／ValueError，建構子再丟一次）；Chebyshev 6139 dB 在 4096 點算不出來 → 說明列寫那條訊號"
          f"（欄位本身合格，不紅）；FFT 長度 1G、16777217 → 錯誤狀態「FFT 長度最多 2^24（16777216）點」；時間解析度 1.5M 秒、RBW 5u → 說明列寫「不夠一段"
          f"視窗（1.8e13／2.4e12 點）」，不真的設計那麼長的視窗；Chebyshev 6139 dB 在 RBW 模式換算視窗長度時算不出來也一樣寫在說明列（以前 ValueError）"
          f"（{bad_big or '10 種都對'}）")
    # 重疊的箭頭（▲▼ 鈕、上下鍵、滾輪都產生 <<Increment>>／<<Decrement>>）照單一規則：0.025k＝25 → 26（Tk 內建的 scan %f 讀成 0.025 → 1）；
    # 欄位打錯還沒重算時從上一次合格的值加減
    sp_ov = spin_of(w, w.v_overlap)
    w.v_overlap.set("0.025k"); w.compute()
    sp_ov.event_generate("<<Increment>>"); app.update()
    ov_up = (w.v_overlap.get(), w._last_p["overlap"])
    w.v_overlap.set("12abc")
    sp_ov.event_generate("<<Increment>>"); app.update()
    ov_bad = (w.v_overlap.get(), w._last_p["overlap"])
    w.v_overlap.set("0.5k")                                    # 超出範圍：也從上一次的值加減（Tk 會夾到 99）
    sp_ov.event_generate("<<Decrement>>"); app.update()
    ov_hi = (w.v_overlap.get(), w._last_p["overlap"])
    w.v_overlap.set("0"); w.compute()
    check(ov_up == ("26", 26.0) and ov_bad == ("27", 27.0) and ov_hi == ("26", 26.0),
          f"重疊的箭頭照單一規則：0.025k（25%）按 ▲ → 26 並重算（以前 Tk 的 scan %f 讀成 0.025 → 1%）；12abc、0.5k（不合格）按箭頭從上一次合格的值"
          f"加減（{ov_up}、{ov_bad}、{ov_hi}）")
    # ---------------------------------------------------------------- 第六輪（使用者 2026-10-26 決定）：第二批每個欄位都是共用的錯誤狀態——打的字留著、每個顯示它的
    # 元件都紅框、提示換成 MATLAB 的錯誤訊息、說明列與狀態列（「區段：訊息」）也寫、計算與設定檔用上一次合格的值；改成合格的值就清掉（紅框、提示、說明列、
    # 狀態列都換回去）。視窗長度 2 照 MATLAB 是錯（MATLAB 要大於 2；以前收）
    st6 = {}
    # 第七輪：每個欄位錯的時候計算用的值＝上一次合格的值（good_ 都和預設值不同；以前頻寬的偏移、滿刻度、時間跨度改用預設值也照過）
    USED6 = {"foffset": 1000.0, "rbw": 10e3, "wlen": 2048, "nfft": 4096, "atten": 70.0, "overlap": 25.0, "tres": 1e-3, "tspan": 2e-3,
             "rload": 50.0, "fullscale": 512.0}
    for key_, var_, good_, bad_ in (("foffset", w.v_foffset, "1k", "abc"), ("rbw", w.v_rbw, "10k", "-1"), ("wlen", w.v_wlen, "2048", "2"),
                                    ("nfft", w.v_nfft, "4096", "1.5"), ("atten", w.v_atten, "70", "30"), ("overlap", w.v_overlap, "25", "-1"),
                                    ("tres", w.v_tres, "1ms", "0"), ("tspan", w.v_tspan, "2ms", "-1"), ("rload", w.v_rload, "50", "0"),
                                    ("fullscale", w.v_fullscale, "512", "-1")):
        var_.set(good_); w.compute()
        tip0 = [getattr(c_, "_pk_tip", "") for c_ in fws(w, var_)]
        var_.set(bad_); w.compute()
        msg_ = fm("nfft").format(2) if key_ == "nfft" else fm(key_)
        on_ = (var_.get() == bad_, err_on(w, var_, msg_), w.v_status.get() == SEC[key_] + "：" + msg_, app.spec_defaults[key_] == good_,
               w._last_p.get(key_) == USED6[key_])           # 計算用的也是上一次合格的值（不是預設值）
        var_.set(good_); w.compute()
        off_ = (err_off(w, var_, msg_), [getattr(c_, "_pk_tip", "") for c_ in fws(w, var_)] == tip0, w.v_status.get().startswith("已計算"),
                app.spec_defaults[key_] == good_)
        st6[key_] = on_ + off_
    for var_, v_ in ((w.v_foffset, "0"), (w.v_rbw, "Auto"), (w.v_wlen, "1024"), (w.v_nfft, "Auto"), (w.v_atten, "60"), (w.v_overlap, "0"),
                     (w.v_tres, "Auto"), (w.v_tspan, "Auto"), (w.v_rload, "1"), (w.v_fullscale, "Auto")):
        var_.set(v_)
    w.compute()
    bad6 = {k_: v_ for k_, v_ in st6.items() if not all(v_)}
    check(not bad6 and not any(c_.instate(["invalid"]) for c_ in strip_controls(w.strip)),
          f"第二批每個欄位（頻寬的偏移、RBW、視窗長度、FFT 長度、衰減、重疊、時間解析度、時間跨度、參考負載、滿刻度）：不合格 → 打的字留著、紅框、提示與說明列"
          f"寫 MATLAB 的錯誤訊息、狀態列「區段：訊息」、計算用並存上一次合格的值（不是預設值）；改成合格的值 → 紅框清掉、提示換回原本的說明、說明列沒有、狀態列換回重新計算"
          f"的那句、存新的值；視窗長度 2 照 MATLAB 是錯（以前收）（{bad6 or '10 個欄位都對'}）")
    # 衰減的單位字（使用者 2026-10-26 決定：dB 類欄位收自己的單位字）：70 dB、70dB 照收、存打的字；70 dBm、70 Hz 是錯（用上一次合格的值）
    w.v_window_label.set("Kaiser"); w._on_window()
    w.v_atten.set("70 dB"); w.compute()
    a1 = (err_off(w, w.v_atten, fm("atten")), "Window = Kaiser (70 dB)" in w.v_info.get(), app.spec_defaults["atten"])
    w.v_atten.set("70dB"); w.compute()
    a1 += (err_off(w, w.v_atten, fm("atten")),)
    w.v_atten.set("80 dBm"); w.compute()
    a2 = (err_on(w, w.v_atten, fm("atten")), "Window = Kaiser (70 dB)" in w.v_info.get(), app.spec_defaults["atten"])
    w.v_atten.set("80 Hz"); w.compute()
    a2 += (err_on(w, w.v_atten, fm("atten")),)
    w.v_atten.set("60"); w.compute()
    check(a1 == (True, True, "70 dB", True) and a2 == (True, True, "70dB", True),
          f"衰減的單位字：70 dB、70dB 照收（存打的字，Window = Kaiser (70 dB)）；80 dBm、80 Hz（別的單位字）是錯，用上一次合格的 70 dB（以前 70 dB 是錯、"
          f"80 Hz 照收成 80）（{a1}、{a2}）")
    w.v_window_label.set("Hann"); w._on_window()
    # ---------------------------------------------------------------- 軌跡：一般／最大值保持／最小值保持（同顏色、透明度 0.7／0.5）、單邊、對數
    w.v_maxhold.set(True); w.v_minhold.set(True); w.compute()
    lns = w.fig.axes[0].get_lines()
    yN, yX, yM = (np.asarray(l_.get_ydata()) for l_ in lns[:3])
    check(len(lns) == 3 and [l_.get_alpha() for l_ in lns] == [1.0, 0.7, 0.5] and len({l_.get_color() for l_ in lns}) == 1
          and lns[1].get_label().endswith("(Max-Hold)") and np.all(yX >= yN - 1e-9) and np.all(yN >= yM - 1e-9),
          "Max-Hold／Min-Hold：同顏色、透明度 0.7／0.5（MATLAB 的畫法）；最大 ≥ 平均 ≥ 最小")
    w.v_two.set(False); w.compute()
    l0 = w.fig.axes[0].get_lines()[0]
    fx, fy = np.asarray(l0.get_xdata()), np.asarray(l0.get_ydata())
    k1 = int(np.argmax(fy))
    check(fx[0] == 0.0 and fx[-1] == 4e6 and abs(fx[k1] - 1e6) < 1.0 and abs(fy[k1]) < 0.01,
          f"單邊 0..fs/2：1 MHz 單音（剛好在 bin 上）振幅 1 → 0 dB（{fy[k1]:.4f} dB @ {fx[k1]:g} Hz）")
    w.v_fscale_label.set("對數"); w._on_fscale()
    check(w.fig.axes[0].get_xscale() == "log", "單邊可以用對數頻率刻度")
    w.v_two.set(True); w.compute()
    check(w.fig.axes[0].get_xscale() == "linear" and "對數頻率刻度只能用在單邊" in w.v_msg.get(), "雙邊時對數刻度不能用 → 線性並說明（MATLAB 的限制）")
    w.v_fscale_label.set("線性"); w._on_fscale()
    w.v_maxhold.set(False); w.v_minhold.set(False); w.compute()          # 勾選的 command 就是重算（設定在重算時存）
    # ---------------------------------------------------------------- 頻譜圖（情境分頁、色彩列、版面配置、時間解析度／跨度、重新指派、通道）
    w.destroy()
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()
    st = w.strip
    w.btn_view_sg.invoke(); app.update()
    check(w.v_show_spec.get() and w.v_show_sg.get() and st.tab_visible("spectrogram") and st.tab_visible("spectrum"),
          "按「頻譜圖」→ 頻譜＋頻譜圖一起看，「頻譜圖」情境分頁出現")
    im = w.sg_image
    arr = np.asarray(im.get_array())
    check(im is not None and arr.shape == (13, 1536) and tuple(im.get_clim()) == (-80.0, 20.0) and im.get_cmap().name == "jet"
          and w.sg_cbar is not None and w.sg_ax.get_title() == sa.name,
          f"頻譜圖：13 條線 × 1536 個頻率、色彩範圍 [-80 20]、jet、有色彩列、預設畫第 1 條訊號（{arr.shape}）")
    sg = DS.spectrogram(sa.slice_range(*app.current_xlim())[0], 8e6, DS.design_window("hann", 1536), 0, 1536, "centered", "power", detrend=True)
    exp_ = sv.to_db(sv.spectrum_type_values("mag", {"power": sg["P"].T, "mode": "centered", "nfft": 1536}))
    check(np.allclose(arr, exp_), "頻譜圖的每一格＝dsv_spectrum.spectrogram（和 MATLAB spectrogram 逐筆比對過的那個）")
    sp_ax = w.fig.axes[0]
    check(w.sg_ax.get_shared_x_axes().joined(w.sg_ax, sp_ax) and w.sg_ax.get_position().y1 < sp_ax.get_position().y0,
          "版面垂直：頻譜在上、頻譜圖在下，頻率軸一起縮放")
    w.v_layout_label.set("水平"); w._on_layout()
    check(w.sg_ax.get_position().x0 > w.fig.axes[0].get_position().x1, "版面水平：頻譜圖在頻譜右邊")
    w.v_colorbar.set(False); w.compute()
    check(w.sg_cbar is None, "關掉色彩列")
    w.v_colorbar.set(True); w.v_layout_label.set("垂直"); w._on_layout()
    w.v_channel_label.set(sb.name); w._on_channel()
    check(w.sg_ax.get_title() == sb.name and app.spec_defaults["channel"] == 1, "通道選第 2 條 → 頻譜圖換畫它")
    w.v_channel_label.set(sa.name); w._on_channel()
    w.v_tres.set("200us"); w.compute()
    check("RBW = 5kHz" in w.v_info.get() and "視窗長度 = 2400" in w.v_info.get(),
          f"RBW Auto＋時間解析度 200 µs → RBW＝1/200 µs＝5 kHz（MATLAB TimeResolutionSource）（{w.v_info.get()[:80]}）")
    w.v_rbw.set("10k"); w.v_tres.set("1ms"); w.compute()
    check("每條 10 段" in w.v_info.get(), f"RBW 10k＋時間解析度 1 ms（≥ 1/RBW）→ 每條線 10 段合成（{w.v_info.get()[90:200]}）")
    w.v_tres.set("10us"); w.compute()
    m_tmin = fm("tres_min").format("0.0001") if FM else "（第六輪的訊息）"
    tres_x = (w.v_tres.get(), err_on(w, w.v_tres, m_tmin), w.v_status.get() == "時間選項：" + m_tmin, "每條 10 段" in w.v_info.get(),
              app.spec_defaults["tres"])
    check(tres_x == ("10us", True, True, True, "1ms"),
          f"時間解析度 < 1/RBW → 時間解析度欄位的錯誤狀態：MATLAB「時間解析度應為大於或等於 {{0}} 秒」的訊息（{{0}}＝1/RBW＝0.0001 秒）、打的字留著，"
          f"用並存上一次合格的 1 ms（每條照樣 10 段；以前改回 Auto 並寫 DSV 的句子）（{tres_x}）")
    w.v_rbw.set("Auto"); w.v_tres.set("Auto")
    w.v_tspan.set("1ms"); w.compute()
    yl = w.sg_ax.get_ylim()
    check(abs((yl[1] - yl[0]) - 1e-3) < 1e-9, f"時間跨度 1 ms → 頻譜圖顯示最後 1 ms（{yl}）")
    w.v_tspan.set("1us"); w.compute()
    m_smin = fm("tspan_min").format(sv.ml_num(2 * 1536 / 8e6)) if FM else "（第六輪的訊息）"
    yl1 = w.sg_ax.get_ylim() if w.sg_ax is not None else (0.0, 0.0)
    ts_x = (w.v_tspan.get(), err_on(w, w.v_tspan, m_smin), w.v_status.get() == "時間選項：" + m_smin, abs((yl1[1] - yl1[0]) - 1e-3) < 1e-9,
            app.spec_defaults["tspan"])
    check(ts_x == ("1us", True, True, True, "1ms"),
          f"時間跨度比 2 倍更新時間短 → 時間跨度欄位的錯誤狀態：MATLAB「時間跨度應為大於 {{0}} 秒」的訊息（{{0}}＝2 × 1536 點 ÷ 8 MHz＝0.000384 秒）、"
          f"打的字留著，用並存上一次合格的 1 ms（頻譜圖照樣顯示最後 1 ms；以前改看整段並寫 DSV 的句子）（{ts_x}）")
    # 第五輪：時間跨度也收 SI 字首（500u＝500 µs；以前 parse_time_s 不認 u 單獨當字首）；用 symbol 當單位時時間解析度、時間跨度也收 SI 字首
    # （0.2k、1k；以前 parse_number 不收）；時間跨度多打字（1..2）是錯 → 改回 Auto 並說明
    w.v_tspan.set("500u"); w.compute()
    yl5 = w.sg_ax.get_ylim() if w.sg_ax is not None else (0.0, 0.0)
    ts_si = (abs((yl5[1] - yl5[0]) - 5e-4) < 1e-9, w.v_tspan.get())
    w.v_tspan.set("1..2"); w.compute()
    ts_bad = (w.v_tspan.get(), err_on(w, w.v_tspan, fm("tspan")))
    w.v_tspan.set("Auto"); w.v_hz.set(False); w.v_tres.set("0.2k"); w.compute()
    sym_tres = ("視窗長度 = 2400" in w.v_info.get(), w.v_tres.get(), fm("tres") not in w.v_msg.get() and err_off(w, w.v_tres, fm("tres")))
    w.v_tres.set("Auto"); w.v_tspan.set("1k"); w.compute()
    yls = w.sg_ax.get_ylim() if w.sg_ax is not None else (0.0, 0.0)
    sym_tspan = (abs((yls[1] - yls[0]) - 1000.0) < 1e-6, w.v_tspan.get())
    w.v_tspan.set("Auto"); w.v_hz.set(True); w.compute()
    check(ts_si == (True, "500u") and ts_bad == ("1..2", True) and sym_tres == (True, "0.2k", True) and sym_tspan == (True, "1k"),
          f"時間跨度 500u＝最後 500 µs（以前改回 Auto）、1..2 是錯（錯誤狀態、打的字留著）；用 symbol 當單位時時間解析度 0.2k＝200 symbol（RBW 1/200 → Hann 2400 點）、"
          f"時間跨度 1k＝最後 1000 symbol（以前都改回 Auto）（{ts_si}、{ts_bad}、{sym_tres}、{sym_tspan}）")
    # 打的 FFT 長度比 Auto 長、頻譜圖的段數 × FFT 長度超過 2^26 格（重疊 99%：1231 段 × 60000）→ 不算頻譜圖、說明列寫原因，頻譜照畫
    # （以前一次配置 1231 × 60000 個複數，16M 這種 FFT 長度更是幾十 GB）
    with no_huge():
        w.v_overlap.set("99"); w.v_nfft.set("60k")
        try:
            w.compute()
            sg_big = (w.sg_image is None, "× FFT 長度 60000 格，太大，沒有畫" in w.v_msg.get(), len(w.lines) > 0)
        except Exception as ex_:                                 # noqa: BLE001
            sg_big = f"例外 {type(ex_).__name__}"
        w.v_nfft.set("1024")                                   # 不比 Auto（1536）長：照舊算（和以前一樣不檢查）
        w.compute()
        sg_ok = (w.sg_image is not None, "太大，沒有畫" not in w.v_msg.get())
        w.v_overlap.set("0"); w.v_nfft.set("Auto"); w.compute()
    check(sg_big == (True, True, True) and sg_ok == (True, True),
          f"打的 FFT 長度比 Auto 長、頻譜圖要超過 2^26 格（重疊 99%、FFT 長度 60k）→ 不算頻譜圖、說明列寫原因、頻譜照畫；FFT 長度不比 Auto 長時照舊畫"
          f"（{sg_big}、{sg_ok}）")
    # 第六輪（使用者 2026-10-26 決定）：FFT 長度 Auto 也有 2^26 格的上限——重疊 99.99%（hop 1 點）＋重新指派：18465 段 × 1536 × 3 份 > 2^26 → 不算頻譜圖、
    # 說明列寫原因（建議改小重疊、縮小範圍或關掉重新指派），頻譜照畫（以前 FFT 長度 Auto 時不檢查，這裡會一次配置約 2.5 GB）。保險：要求超過上限的頻譜圖時
    # 直接丟 _TooBig（重新指派算 3 份），舊版跑這個測試也不會真的配置
    @contextmanager
    def no_huge_sg():
        sg0 = DS.spectrogram

        def sg_(x, fs_, w_, nov, nfft=None, *a, **k):
            cells = DS.num_segments(len(x), len(w_), nov) * int(nfft or len(w_)) * (3 if k.get("reassign") else 1)
            if cells > (1 << 26):
                raise _TooBig(f"頻譜圖 {cells} 格")
            return sg0(x, fs_, w_, nov, nfft, *a, **k)
        DS.spectrogram = sg_
        try:
            yield
        finally:
            DS.spectrogram = sg0
    with no_huge_sg():
        w.v_overlap.set("99.99"); w.v_reassign.set(True); w.v_nfft.set("Auto")
        try:
            w.compute()
            sg_auto = (w.sg_image is None, bool(re.search(re.escape(f"{sa.name}：頻譜圖要 ") + r"\d+ 段 × FFT 長度 1536 格，太大，沒有畫："
                                                          + re.escape("把重疊改小、縮小主圖的範圍或關掉重新指派"), w.v_msg.get())), len(w.lines) > 0,
                       "Navg = 18465" in w.v_info.get())
        except Exception as ex_:                                 # noqa: BLE001
            sg_auto = f"例外 {type(ex_).__name__}"
        w.v_reassign.set(False); w.v_overlap.set("0"); w.compute()
    check(sg_auto == (True, True, True, True),
          f"FFT 長度 Auto 也有頻譜圖 2^26 格的上限：重疊 99.99%＋重新指派（18465 段 × 1536 點 × 3 份）→ 不算頻譜圖、說明列寫原因與改法，頻譜照畫"
          f"（18465 段平均）；以前 Auto 不檢查、一次配置好幾 GB（{sg_auto}）")
    w.v_reassign.set(True); w.compute()
    arr_r = np.asarray(w.sg_image.get_array())
    check("重新指派" in w.v_info.get() and arr_r.shape == arr.shape and not np.allclose(arr_r, arr), "重新指派：頻譜圖重算（能量搬到時間／頻率重心）")
    w.v_reassign.set(False)
    w.set_view("spectrogram"); app.update()
    check(not st.tab_visible("spectrum") and st.tab_visible("spectrogram") and len(w.lines) == 0 and w.sg_image is not None,
          "只看頻譜圖：「頻譜」情境分頁消失、沒有頻譜線")
    w.v_show_sg.set(False); w._on_view("spectrogram")
    check(w.v_show_sg.get() and not w.v_show_spec.get(), "兩個檢視不能都關（剛關掉的那個留著）")
    w.set_view("spectrum")
    check(not st.tab_visible("spectrogram") and st.current != "spectrogram", "回到只看頻譜：頻譜圖分頁收起來")
    # ---------------------------------------------------------------- 設定（色彩範圍、色彩圖）
    w.set_view("both")
    w.settings_dialog(); app.update()
    dlg = w._settings_dlg
    ents = [c for c in dlg.winfo_children()[0].winfo_children() if c.winfo_class() == "TEntry"]
    cbs = [c for c in dlg.winfo_children()[0].winfo_children() if c.winfo_class() == "TCombobox"]
    ents[0].delete(0, "end"); ents[0].insert(0, "abc")
    btns = {str(b.cget("text")): b for b in dlg.winfo_children()[0].winfo_children()[-1].winfo_children()}
    btns["套用"].invoke(); app.update()
    errs = [dlg.getvar(str(l_.cget("textvariable"))) for l_ in dlg.winfo_children()[0].winfo_children()
            if l_.winfo_class() == "TLabel" and str(l_.cget("textvariable"))]
    m_cl = fm("clim")
    e0 = ents[0]
    dlg_x = (m_cl in errs, e0.get() == "abc", bool(e0.instate(["invalid"])), getattr(e0, "_pk_tip", "") == m_cl, m_cl in w.v_msg.get(),
             w.v_status.get() == "設定：" + m_cl, w.v_clim.get() == "-80, 20", app.spec_defaults["clim"] == "-80, 20")
    check(all(dlg_x),
          f"設定：色彩範圍看不懂 → 對話框的欄位照共用的錯誤狀態：打的字留著、紅框、提示與對話框下方寫 MATLAB 設定對話框的色彩範圍錯誤訊息，"
          f"頻譜視窗的說明列與狀態列（「設定：…」）也寫；不套用、色彩範圍與設定檔維持 -80, 20（以前只在對話框下方寫 DSV 的句子）（{dlg_x}）")
    # 單位字：色彩範圍收色彩列的單位（這時是 dB）——-80 dB, 20 dB 照收、[-80 dBm 20 dBm] 是錯（使用者 2026-10-26 決定）
    e0.delete(0, "end"); e0.insert(0, "[-80 dBm 20 dBm]")
    btns["套用"].invoke(); app.update()
    u_bad = (bool(e0.instate(["invalid"])), w.v_clim.get(), m_cl in w.v_msg.get())
    e0.delete(0, "end"); e0.insert(0, "-80 dB, 20 dB")
    btns["套用"].invoke(); app.update()
    u_ok = (bool(e0.instate(["invalid"])), w.v_clim.get(), m_cl in w.v_msg.get(), tuple(w.sg_image.get_clim()) if w.sg_image is not None else None,
            app.spec_defaults["clim"])
    # 打錯後按「取消」：打的字不要了，錯誤狀態跟著清掉（說明列、狀態列換回去）；再打開時欄位是目前套用的值、沒有紅框（MATLAB 的設定對話框也是）
    e0.delete(0, "end"); e0.insert(0, "xyz")
    btns["套用"].invoke(); app.update()
    st_err = w.v_status.get()
    btns["取消"].invoke(); app.update()
    cancel_x = (st_err == "設定：" + m_cl, m_cl not in w.v_msg.get(), w.v_status.get() != st_err, not dlg.winfo_exists())
    w.settings_dialog(); app.update()
    dlg = w._settings_dlg
    ents = [c for c in dlg.winfo_children()[0].winfo_children() if c.winfo_class() == "TEntry"]
    cbs = [c for c in dlg.winfo_children()[0].winfo_children() if c.winfo_class() == "TCombobox"]
    btns = {str(b.cget("text")): b for b in dlg.winfo_children()[0].winfo_children()[-1].winfo_children()}
    reopen_x = (ents[0].get(), bool(ents[0].instate(["invalid"])))
    check(u_bad == (True, "-80, 20", True) and u_ok == (False, "-80 dB, 20 dB", False, (-80.0, 20.0), "-80 dB, 20 dB") and all(cancel_x)
          and reopen_x == ("-80 dB, 20 dB", False),
          f"色彩範圍的單位字＝色彩列的單位（dB）：[-80 dBm 20 dBm] 是錯（紅框、不套用）、-80 dB, 20 dB 照收並存進設定；打錯後按取消 → 錯誤狀態清掉"
          f"（說明列沒有、狀態列換回去），再打開時欄位是目前套用的值、沒有紅框（{u_bad}、{u_ok}、{cancel_x}、{reopen_x}）")
    ents[0].delete(0, "end"); ents[0].insert(0, "[-60 0]"); cbs[0].set("hot")
    btns["確定"].invoke(); app.update()
    check(tuple(w.sg_image.get_clim()) == (-60.0, 0.0) and w.sg_image.get_cmap().name == "hot" and not dlg.winfo_exists(),
          "設定：色彩範圍 [-60 0]、色彩圖 hot → 頻譜圖跟著換")
    lim = w.auto_color_limits()
    a_ = np.asarray(w.sg_image.get_array())
    check(lim is not None and abs(lim[1] - float(np.max(a_))) < 1e-9 and abs(lim[1] - lim[0] - 100.0) < 1e-6, f"依資料自動：最大值往下 100 dB（{lim}）")
    # ---------------------------------------------------------------- 峰值搜尋（Peaks 面板、▼、標示、縮放後重找、參數檢查）
    w.set_view("spectrum")
    w.v_peaks.set(True); w._on_peaks_toggle(); app.update()
    tree = w.peaks_tree
    groups = tree.get_children()
    p_a = [tree.item(c_, "values") for c_ in tree.get_children(groups[0])] if groups else []
    check(w.peaks_frame.winfo_manager() == "pack" and len(groups) == 2 and len(p_a) == 3 and p_a[0][1] in ("-1MHz", "1MHz"),
          f"打開峰值搜尋 → 下方 Peaks 面板：每條訊號 3 個峰（MATLAB 預設 Num Peaks 3），最高的在 ±1 MHz（{p_a}）")
    mk = [a_ for a_ in w._peak_artists if getattr(a_, "_dsv_peak", False)]
    check(len(mk) == 2 and all(m_.get_marker() == "v" for m_ in mk), "圖上每條訊號一組 ▼ 標記")
    w.v_pk_label.set(True); w._update_peaks(draw=True)
    txt = sorted(a_.get_text() for a_ in w._peak_artists if hasattr(a_, "get_text"))
    check(txt == ["P1", "P1", "P2", "P2", "P3", "P3"], f"標示峰值：▼ 上面寫 P1、P2、P3（{txt}）")
    draws = []
    cid = w.canvas.mpl_connect("draw_event", lambda e: draws.append(1))
    t_end = _time.time() + 0.6
    while _time.time() < t_end:
        app.update(); _time.sleep(0.02)
    w.canvas.mpl_disconnect(cid)
    check(len(draws) <= 1, f"峰值標記不會自己一直觸發重畫（0.6 秒內畫了 {len(draws)} 次）")
    ax = w.fig.axes[0]
    ax.set_xlim(1.2e6, 3e6)
    t_end = _time.time() + 0.4
    while _time.time() < t_end:
        app.update(); _time.sleep(0.02)
    pr = w.peak_results()
    check(pr and pr[0][1] and abs(pr[0][1][0][1] - 1.5e6) > 1 and all(1.2e6 <= f_ <= 3e6 for _v, f_ in pr[0][1])
          and abs(pr[1][1][0][1] - 1.5e6) < 1e3,
          f"縮放到 1.2～3 MHz → 只在看得到的範圍找（MATLAB）：訊號 b 的 1.5 MHz 是 P1（{[(n_, [round(f_) for _v, f_ in p_]) for n_, p_ in pr]}）")
    w.v_pk_num.set("1"); w._on_peak_params()
    check(all(len(tree.get_children(g_)) == 1 for g_ in tree.get_children()), "Num Peaks 1 → 每條只列 1 個")
    w.v_pk_num.set("0"); w._on_peak_params()
    check(w.v_pk_num.get() == "0" and err_on(w, w.v_pk_num, fm("pk_num")) and w.v_status.get() == "峰值：" + fm("pk_num")
          and app.spec_defaults["pk_num"] == "1" and all(len(tree.get_children(g_)) == 1 for g_ in tree.get_children()),
          "Num Peaks 0 → 共用的錯誤狀態（使用者 2026-10-26 決定）：打的字留著、紅框、提示／說明列／狀態列（「峰值：…」）寫 MATLAB 的峰值數目錯誤訊息，"
          "峰值搜尋用、設定檔存上一次合格的 1（以前用預設 3、說明列寫 DSV 的句子）")
    w.v_pk_num.set("3")

    def peaks_after(var_, txt_):
        """在峰值的一個欄位打字按 Enter：(說明列, 每條訊號列出幾個峰)；42b4834 打 Inf 時 int() 丟例外。"""
        w.v_msg.set("")
        var_.set(txt_)
        try:
            w._on_peak_params()
        except Exception as ex_:                                 # noqa: BLE001
            return f"例外 {type(ex_).__name__}"
        return w.v_msg.get(), [len(tree.get_children(g_)) for g_ in tree.get_children()]
    pk_r = {"Num Peaks 0.002k": peaks_after(w.v_pk_num, "0.002k"), "Num Peaks Inf": peaks_after(w.v_pk_num, "Inf"),
            "Num Peaks 0x10": peaks_after(w.v_pk_num, "0x10")}
    w.v_pk_num.set("3")
    pk_r["Min Distance Inf"] = peaks_after(w.v_pk_mindist, "Inf")
    w.v_pk_mindist.set("1")
    pk_r["Threshold NaN"] = peaks_after(w.v_pk_thr, "NaN")
    w.v_pk_thr.set("0")
    pk_r["Min Height -Inf"] = peaks_after(w.v_pk_minh, "-Inf")
    w.v_pk_minh.set("")
    w._on_peak_params()
    e_num, e_md, e_thr = fm("pk_num"), fm("pk_mindist"), fm("pk_thr")
    check(pk_r == {"Num Peaks 0.002k": ("", [2, 2]), "Num Peaks Inf": (e_num, [2, 2]), "Num Peaks 0x10": (e_num, [2, 2]),
                   "Min Distance Inf": ("", [1, 1]), "Threshold NaN": (e_thr, [3, 3]), "Min Height -Inf": ("", [3, 3])},
          f"峰值欄位照頻譜視窗數字欄位的單一規則：Num Peaks 0.002k＝2（以前不收 SI 字首）；Num Peaks 打 Inf、0x10（以前當 16）是錯：MATLAB 的 "
          f"峰值數目的錯誤訊息、用上一次合格的 2（以前用預設 3）；Min Distance 照 MATLAB 收 Inf（使用者 2026-10-26 決定）＝每條只留最高的峰（以前是錯）；"
          f"Threshold NaN 是錯（MATLAB 的門檻值錯誤訊息）；Min Height -Inf 照收（MATLAB 的預設）（{pk_r}）")
    # 第五輪：四個峰值欄位都有「數字後面多打字」與 NaN（Num Peaks、Min Distance 的 NaN 以前讓 int() 丟例外，Min Height 的 NaN 以前被收下），
    # Threshold 收 Inf 與 SI 字首、Min Height 收 SI 字首、0x10 是錯；用的值看 peak_params()（說明列的「用預設值」看列出幾個峰）
    def pk_val(key_):
        try:
            return w.peak_params()[0][key_]
        except Exception as ex_:                                 # noqa: BLE001
            return f"例外 {type(ex_).__name__}"
    e_minh = fm("pk_minh")
    pk5 = {"Num Peaks 2abc": peaks_after(w.v_pk_num, "2abc"), "Num Peaks NaN": peaks_after(w.v_pk_num, "NaN")}
    w.v_pk_num.set("3")
    pk5["Threshold 1abc"] = peaks_after(w.v_pk_thr, "1abc")
    pk5["Threshold Inf"] = (peaks_after(w.v_pk_thr, "Inf")[0], pk_val("threshold"))
    pk5["Threshold 0.01k"] = (peaks_after(w.v_pk_thr, "0.01k")[0], pk_val("threshold"))
    w.v_pk_thr.set("0")
    pk5["Min Height -50abc"] = peaks_after(w.v_pk_minh, "-50abc")
    pk5["Min Height NaN"] = peaks_after(w.v_pk_minh, "NaN")
    pk5["Min Height 0x10"] = peaks_after(w.v_pk_minh, "0x10")
    pk5["Min Height -0.05k"] = (peaks_after(w.v_pk_minh, "-0.05k")[0], pk_val("min_height"))
    w.v_pk_minh.set("")
    pk5["Min Distance 2abc"] = peaks_after(w.v_pk_mindist, "2abc")
    pk5["Min Distance NaN"] = peaks_after(w.v_pk_mindist, "NaN")
    w.v_pk_mindist.set("1")
    w._on_peak_params()
    want_pk5 = {"Num Peaks 2abc": (e_num, [3, 3]), "Num Peaks NaN": (e_num, [3, 3]), "Threshold 1abc": (e_thr, [3, 3]),
                "Threshold Inf": ("", math.inf), "Threshold 0.01k": ("", 10.0), "Min Height -50abc": (e_minh, [3, 3]),
                "Min Height NaN": (e_minh, [3, 3]), "Min Height 0x10": (e_minh, [3, 3]), "Min Height -0.05k": ("", -50.0),
                "Min Distance 2abc": (e_md, [3, 3]), "Min Distance NaN": (e_md, [3, 3])}
    check(pk5 == want_pk5,
          f"峰值四個欄位的「數字後面多打字」（Num Peaks 2abc、Threshold 1abc、Min Height -50abc、Min Distance 2abc）與 NaN 都是錯：MATLAB 的錯誤訊息、"
          f"用上一次合格的值（以前 Num Peaks、Min Distance 的 NaN 讓重新找峰丟 ValueError、Min Height 的 NaN 被收下）；Threshold 收 Inf（README）與 0.01k＝10、"
          f"Min Height 收 -0.05k＝-50，Min Height 0x10 是錯（以前當 16）（{ {k_: v_ for k_, v_ in pk5.items() if want_pk5[k_] != v_} or '11 種都對'}）")
    # 第六輪：峰值欄位的錯誤狀態不把打錯的字存進設定（以前按 Enter 不存、下一次重新計算存打錯的字），合格的字按 Enter 就存；改好就清掉
    w.v_pk_num.set("5"); w._on_peak_params()
    saved_ok = app.spec_defaults["pk_num"]
    w.v_pk_num.set("0"); w._on_peak_params()
    pk_state = (w.v_pk_num.get(), err_on(w, w.v_pk_num, fm("pk_num")), w.v_status.get() == "峰值：" + fm("pk_num"), app.spec_defaults["pk_num"],
                [len(tree.get_children(g_)) for g_ in tree.get_children()])
    w.compute()                                               # 重新計算存設定時也是上一次合格的字（以前存打錯的 0）
    pk_saved = (app.spec_defaults["pk_num"], err_on(w, w.v_pk_num, fm("pk_num")))
    w.v_pk_num.set("3"); w._on_peak_params()
    pk_clear = (err_off(w, w.v_pk_num, fm("pk_num")), w.v_status.get(), app.spec_defaults["pk_num"])
    check(saved_ok == "5" and pk_state == ("0", True, True, "5", [5, 5]) and pk_saved == ("5", True) and pk_clear == (True, "峰值搜尋：已套用", "3"),
          f"峰值欄位：合格的字按 Enter 就存進設定；打錯（Num Peaks 0）→ 打的字留著、紅框、狀態列「峰值：…」，峰值搜尋用、設定檔存上一次合格的 5"
          f"（重新計算以後也是；以前存打錯的字），改成 3 → 錯誤清掉、狀態列「峰值搜尋：已套用」、存 3（{saved_ok}、{pk_state}、{pk_saved}、{pk_clear}）")
    # 單位字（使用者 2026-10-26 決定）：Threshold、Min Height 收 y 軸的單位——dB 時 3 dB、-60 dB 照收，3 dBm 是錯；單位改 dBm 後寫 dB 的 Min Height
    # 變成錯誤狀態（上一次合格的 -60 dB 這時也不合格 → 不限），-60 dBm 照收
    u1 = (peaks_after(w.v_pk_thr, "3 dB")[0], pk_val("threshold"))
    u2 = (peaks_after(w.v_pk_thr, "3 dBm")[0], pk_val("threshold"))
    w.v_pk_thr.set("0")
    u3 = (peaks_after(w.v_pk_minh, "-60 dB")[0], pk_val("min_height"))
    w.v_unit_label.set("dBm"); w._on_unit(); app.update()
    u4 = (err_on(w, w.v_pk_minh, fm("pk_minh")), pk_val("min_height"), w.v_status.get() == "峰值：" + fm("pk_minh"))
    u5 = (peaks_after(w.v_pk_minh, "-60 dBm")[0], pk_val("min_height"))
    w.v_pk_minh.set(""); w._on_peak_params()
    w.v_unit_label.set("dB"); w._on_unit(); app.update()
    check(u1 == ("", 3.0) and u2 == (fm("pk_thr"), 3.0) and u3 == ("", -60.0) and u4 == (True, -math.inf, True) and u5 == ("", -60.0)
          and err_off(w, w.v_pk_minh, fm("pk_minh")),
          f"峰值的單位字＝y 軸的單位：dB 時 Threshold 3 dB、Min Height -60 dB 照收，Threshold 3 dBm 是錯（用上一次合格的 3）；單位改 dBm → 寫 -60 dB 的 "
          f"Min Height 變成錯誤狀態（上一次合格的字也不合格 → 不限）、-60 dBm 照收（{u1}、{u2}、{u3}、{u4}、{u5}）")
    w.v_peaks.set(False); w._on_peaks_toggle(); app.update()
    check(not w.peaks_frame.winfo_manager() and not w._peak_artists, "關掉峰值搜尋 → 面板與 ▼ 都收起來")
    # ---------------------------------------------------------------- 資料提示仍可用；I/Q 複數強制雙邊
    w.ia.add_tip(1, 100)
    check(len(w.ia.model.tips) == 1, "頻譜線上照樣可以釘資料提示")
    w.v_iq.set(True); w.v_two.set(False); w.compute()
    check(all(str(c_.cget("state")) == "disabled" for c_ in w.ck_two) and float(np.min(w.fig.axes[0].get_lines()[0].get_xdata())) < 0,
          "I/Q 複數：一定是雙邊（勾選灰掉），頻率有負的")
    w.v_iq.set(False); w.v_two.set(True); w.compute()
    # ---------------------------------------------------------------- 設定檔往返；舊設定（Welch 段數、rect／blackman）相容
    w.v_window_label.set("Flat Top"); w._on_window()
    w.v_overlap.set("25"); w.v_maxhold.set(True); w.v_peaks.set(True); w._on_peaks_toggle(); w.compute()
    cfg = app.dump_settings()["spectrum"]
    check(cfg["window"] == "flat-top" and cfg["overlap"] == "25" and cfg["maxhold"] is True and cfg["peaks"] is True and cfg["view"] == "spectrum"
          and cfg["rbw"] == "" and cfg["clim"] == "[-60 0]" and cfg["cmap"] == "hot" and "nseg" not in cfg,
          f"頻譜設定存進設定檔（視窗、重疊、軌跡、峰值、檢視、色彩）（{ {k: cfg[k] for k in ('window', 'overlap', 'clim', 'cmap')} }）")
    w.destroy()
    w = sv.SpectrumWindow(app, [sa]); app.update()
    check(w.v_window.get() == "flat-top" and w.v_overlap.get() == "25" and w.v_maxhold.get() and w.v_peaks.get()
          and w.peaks_frame.winfo_manager() == "pack" and len(w.lines) == 2,
          f"重開頻譜視窗：上次的視窗、重疊、Max-Hold、峰值搜尋都還在（{w.v_window.get()}、{w.v_overlap.get()}、{w.v_maxhold.get()}、"
          f"{w.v_peaks.get()}、{w.peaks_frame.winfo_manager()!r}、{len(w.lines)} 條）")
    w.destroy()
    app.spec_defaults.clear(); app.spec_defaults.update(dict(sv.DEFAULT_SPEC, window="rect", nseg=4))
    w = sv.SpectrumWindow(app, [sa]); app.update()
    check(w.v_window.get() == "rectangular" and "nseg" not in app.spec_defaults and "Window = Rectangular" in w.v_info.get(),
          "舊設定：window＝rect → Rectangular；「Welch 段數」不再使用（改用 RBW／視窗長度）")
    w.destroy()
    # ---------------------------------------------------------------- 頻譜圖的通道：選擇不會被自動改掉（第三批審查；和頻譜遮罩的通道同一個規則）
    yn = y1.copy()
    yn[5000:5010] = np.nan                               # 範圍內有 NaN：算頻譜時略過這條
    path_n = os.path.join(ROOT, "spec2_nan.csv")
    with open(path_n, "w") as f:
        f.write("Time,tone n\n")
        f.writelines(f"{tt:.12f},{v_:.9f}\n" for tt, v_ in zip(t, yn))
    path_s = os.path.join(ROOT, "spec2_short.csv")              # 只有 1000 點：視窗長度 4096 時算不出頻譜（不是被略過，是估計時才失敗）
    with open(path_s, "w") as f:
        f.write("Time,tone s\n")
        f.writelines(f"{tt:.12f},{v_:.9f}\n" for tt, v_ in zip(t[:1000], y1[:1000]))
    app.add_csv_columns_direct(path_n, None); app.add_csv_columns_direct(path_s, None)
    app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    sn, ss = app.find_signal("spec2_nan.csv;;tone n"), app.find_signal("spec2_short.csv;;tone s")
    app.spec_defaults.clear(); app.spec_defaults.update(dict(sv.DEFAULT_SPEC, view="both"))
    sg_title = lambda w_: w_.sg_ax.get_title() if w_.sg_ax is not None else None          # noqa: E731
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()
    w.cb_channel.current(1); w._on_channel(1); app.update()      # 在兩條的視窗選第 2 條
    a_ = (w._channel, app.spec_defaults["channel"], sg_title(w))
    w.destroy()
    w = sv.SpectrumWindow(app, [sa]); app.update()               # 只有 1 條的視窗：暫時畫第 1 條，選擇與設定不變
    b_ = (w._channel, app.spec_defaults["channel"], sg_title(w), w.v_channel_label.get(), tuple(w.cb_channel.cget("values")), "頻譜圖：" in w.v_msg.get())
    w.compute(); app.update()
    b2 = app.spec_defaults["channel"]
    w.destroy()
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()           # 回到兩條的視窗：又畫第 2 條
    c_ = (w._channel, sg_title(w), w.v_channel_label.get(), app.spec_defaults["channel"])
    w.destroy()
    w = sv.SpectrumWindow(app, [sn, sa, sb]); app.update()       # 第 1 條這次算不出頻譜（NaN）：清單照樣列出它，號碼不位移
    vals = tuple(w.cb_channel.cget("values"))
    if len(vals) > 2:
        w.cb_channel.current(2)
    w._on_channel(2); app.update()
    d_ = (vals, w._channel, sg_title(w), w.v_channel_label.get(), app.spec_defaults["channel"])
    if len(vals) > 2:
        w.cb_channel.current(0)
    w._on_channel(0); app.update()                               # 選被略過的那條：暫時畫第一條有頻譜的，說明列寫明，選擇照存
    note_ = f"頻譜圖：選的「{sn.name}」這次沒有頻譜，暫時畫「{sa.name}」（選擇不變）"
    e_ = (w._channel, sg_title(w), w.v_channel_label.get(), app.spec_defaults["channel"], note_ in w.v_msg.get())
    if len(vals) > 2:
        w.cb_channel.current(2)
    w._on_channel(2); app.update()
    w.v_channel_label.set("沒有這條"); w._on_channel(); app.update()   # 程式用文字選、找不到：不改
    f_ = (w._channel, app.spec_defaults["channel"])
    w.destroy()
    w = sv.SpectrumWindow(app, [ss, sa]); app.update()           # 選的那條估計時才失敗（1000 點 < 視窗 4096）：暫時畫下一條有頻譜的
    w.v_res.set("window-length"); w.v_wlen.set("4096"); w.compute(); app.update()
    w.cb_channel.current(0); w._on_channel(0); app.update()
    note_s = f"頻譜圖：選的「{ss.name}」這次沒有頻譜，暫時畫「{sa.name}」（選擇不變）"
    g_ = (w._channel, sg_title(w), w.v_channel_label.get(), w.sg_image is not None, note_s in w.v_msg.get(), "範圍內只有 1000 點" in w.v_msg.get())
    w.destroy()
    check(a_ == (1, 1, sb.name) and b_ == (1, 1, sa.name, sa.name, (sa.name,), False) and b2 == 1 and c_ == (1, sb.name, sb.name, 1)
          and d_ == ((sn.name, sa.name, sb.name), 2, sb.name, sb.name, 2) and e_ == (0, sa.name, sn.name, 0, True) and f_ == (2, 2)
          and g_ == (0, sa.name, ss.name, True, True, True),
          f"頻譜圖的通道不會被自動改掉（和頻譜遮罩的通道同一個規則）：選第 2 條後開只有 1 條的視窗 → 暫時畫第 1 條、下拉顯示它，選擇與設定的 channel "
          f"都還是 1（以前改成 0 並存進設定）；回到兩條的視窗又畫第 2 條。清單是視窗的每一條訊號：第 1 條這次算不出頻譜（NaN）時下拉仍列出 3 條，"
          f"選第 3 條就畫它（不會位移到別條）；選被略過的那條、或選的那條估計時才算不出來（1000 點 < 視窗 4096）→ 暫時畫第一條有頻譜的、說明列寫明、"
          f"選擇照存；程式用文字選、找不到時不改（{a_}、{b_}、{b2}、{c_}、{d_}、{e_}、{f_}、{g_}）")
    # 第五輪：選的那條頻譜圖太大（打的 FFT 長度比 Auto 長、段數 × FFT 長度超過 2^26 格）→ 不算它的頻譜圖、說明列寫原因，也不改畫別條
    # （5000 點那條 231 段 × 60000 算得下，但選的是 20000 點的 1231 段；「沒有頻譜時暫時畫第一條」只用在真的算不出頻譜）
    path_5 = os.path.join(ROOT, "spec2_5k.csv")
    with open(path_5, "w") as f:
        f.write("Time,tone f\n")
        f.writelines(f"{tt:.12f},{v_:.9f}\n" for tt, v_ in zip(t[:5000], y1[:5000]))
    app.add_csv_columns_direct(path_5, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    s5 = app.find_signal("spec2_5k.csv;;tone f")
    app.spec_defaults.clear(); app.spec_defaults.update(dict(sv.DEFAULT_SPEC, view="both", channel=1, overlap="99", nfft="60k"))
    with no_huge():
        try:
            w = sv.SpectrumWindow(app, [s5, sa]); app.update()
            big_sel = (w.sg_image is None, bool(re.search(re.escape(f"{sa.name}：頻譜圖要 ") + r"\d+ 段 × FFT 長度 60000 格，太大，沒有畫", w.v_msg.get())),
                       "暫時畫" not in w.v_msg.get(), w._channel, len(w.lines))
            w.destroy()
        except Exception as ex_:                                 # noqa: BLE001
            big_sel = f"例外 {type(ex_).__name__}"
            for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow)]:
                try:
                    t_.destroy()
                except Exception:                                # noqa: BLE001
                    pass
    check(big_sel == (True, True, True, 1, 2),
          f"選的那條頻譜圖太大（20000 點、重疊 99%、FFT 長度 60k：1231 段 × 60000 格）→ 不算它的頻譜圖、說明列寫原因，也不改畫別條（5000 點那條算得下"
          f"也不換）；兩條的頻譜照畫、選擇不變（{big_sel}）")
    app.spec_defaults.clear(); app.spec_defaults.update(spec0)
    app.apply_settings(cfg0, quiet=True); app.update()


@step
def s30_round7_fields():
    """第三批審查第七輪（第六輪的審查）：會讓重新計算丟例外、壞值存進設定（之後開頻譜視窗建構子就失敗）的有限值——Min Distance 很大的整數、
    滿刻度很大／很小、頻率偏移很大；狀態列和第三批同一個規則（還有欄位是錯誤狀態時不寫「已計算…」「峰值搜尋：已套用」、在錯的欄位再按一次
    Enter 就再寫一次）；時間跨度被拒的字不會因為關掉頻譜圖就變成合格；衰減的上限只看目前的視窗；峰值四個欄位逐一（紅框、提示、狀態列的區段、
    用並存上一次合格的值、改好清掉）；RMS／線性單位的單位字；色彩範圍換單位與設定對話框；symbol 的句子；只看頻譜時沒有頻譜圖上限的說明；
    設定檔裡不合格的峰值欄位；重新計算以外才發現的峰值錯誤。欄位一律用真的 Enter（tests_common.tk_key 走欄位的綁定），回呼丟的例外照實記下。"""
    cfg0 = app.dump_settings()
    spec0 = dict(app.spec_defaults)
    CB = []                                                      # 這一步裡 Tk 回呼丟的例外（以前 OverflowError／ZeroDivisionError／ValueError）

    def rec(exc, val, tb):
        CB.append(f"{exc.__name__}: {val}")
    had = "report_callback_exception" in app.__dict__
    app.report_callback_exception = rec
    try:
        _s30_round7_body(CB)
    finally:
        if not had:
            del app.report_callback_exception
        for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow)]:
            try:
                t_.destroy()
            except Exception:                                    # noqa: BLE001
                pass
        app.spec_defaults.clear(); app.spec_defaults.update(spec0)
        app.apply_settings(cfg0, quiet=True); app.update()


def _s30_round7_body(CB):
    fs = 8e6; n = 20000
    t = np.arange(n) / fs
    rng = np.random.default_rng(3)
    y1 = np.sin(2 * np.pi * 1e6 * t) + 0.01 * np.sin(2 * np.pi * 2.5e6 * t) + 1e-3 * rng.standard_normal(n)
    y2 = 0.5 * np.sin(2 * np.pi * 1.5e6 * t) + 1e-3 * rng.standard_normal(n)
    path = os.path.join(ROOT, "spec7_tones.csv")
    with open(path, "w") as f:
        f.write("Time,tone a,tone b\n")
        f.writelines(f"{tt:.12f},{a:.9f},{b:.9f}\n" for tt, a, b in zip(t, y1, y2))
    app.v["symbol_rate"].set("1M")
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    sa = app.find_signal("spec7_tones.csv;;tone a"); sb = app.find_signal("spec7_tones.csv;;tone b")
    FM = getattr(sv, "SPEC_FIELD_MESSAGES", {})
    fm = lambda k_: FM.get(k_, "（第六輪的訊息）")                # noqa: E731

    def fws(w_, var_):
        return [c_ for c_ in strip_controls(w_.strip) if c_.winfo_class() in ("TEntry", "TCombobox", "TSpinbox")
                and str(c_.cget("textvariable")) == str(var_)]

    def err_on(w_, var_, msg_):
        ws_ = fws(w_, var_)
        return bool(ws_) and all(c_.instate(["invalid"]) and getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ in w_.v_msg.get()

    def err_off(w_, var_, msg_):
        ws_ = fws(w_, var_)
        return bool(ws_) and not any(c_.instate(["invalid"]) or getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ not in w_.v_msg.get()

    def enter(w_, var_, txt_, idx_=0):
        """在綁 var_ 的欄位打 txt_、按 Enter（真的綁定）；回傳這次回呼丟的例外。"""
        c_ = fws(w_, var_)[idx_]
        c_.delete(0, "end"); c_.insert(0, txt_)
        n0 = len(CB)
        tk_key(c_, "Return"); app.update()
        return CB[n0:]

    def again(w_, var_):
        """不改字、在欄位上再按一次 Enter。"""
        n0 = len(CB)
        tk_key(fws(w_, var_)[0], "Return"); app.update()
        return CB[n0:]

    def drop_others(keep):
        """舊版建構子丟例外時留下沒建完的視窗：關掉（換主題時才不會再算一次、把壞值存回設定）。"""
        for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow) and c_ not in keep]:
            try:
                t_.destroy()
            except Exception:                                    # noqa: BLE001
                pass

    def reopen(sigs, fn):
        """用目前的 app.spec_defaults 開新的頻譜視窗、fn(視窗) 取結果再關掉；建構子丟例外時回傳例外名稱。"""
        n0 = len(CB)
        try:
            w2 = sv.SpectrumWindow(app, sigs); app.update()
        except Exception as ex_:                                 # noqa: BLE001
            drop_others(keep=[w])
            return f"例外 {type(ex_).__name__}"
        r_ = fn(w2)
        w2.destroy(); app.update()
        return r_ if len(CB) == n0 else f"回呼例外 {CB[n0:]}"

    def groups(w_):
        return [len(w_.peaks_tree.get_children(g_)) for g_ in w_.peaks_tree.get_children()]
    app.spec_defaults.clear(); app.spec_defaults.update(sv.DEFAULT_SPEC)
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()
    w.btn_peaks.invoke(); app.update()
    # ---------------------------------------------------------------- Min Distance 很大的整數（1e19、1e300）：以前 find_peaks 把 Python 的大整數換成 C long 時
    # 丟 OverflowError，按 Enter 就存進設定，之後只要 Peak Finder 開著，開頻譜視窗建構子就丟同一個例外。第七輪照 MATLAB 收（＝Inf）；第八輪（使用者
    # 2026-10-26 決定）起有限的值超過 2^53 − 1 是欄位的錯誤狀態、用並存上一次合格的 1（上限本身在 s30_round8_fields）——這裡看不丟例外、壞值不存進設定、
    # 重開視窗照常
    capm = getattr(sv, "SPEC_MSG_MINDIST_CAP", "（第八輪的訊息 {v}）")
    enter(w, w.v_pk_mindist, "1")
    g1 = groups(w)
    md = {}
    for t_, v_ in (("1e19", "10000000000000000000"), ("1e300", "1e+300")):
        cb_ = enter(w, w.v_pk_mindist, t_)
        md[t_] = (cb_, w.v_pk_mindist.get(), err_on(w, w.v_pk_mindist, capm.format(v=v_)), app.spec_defaults.get("pk_mindist"), groups(w) == g1)
    md["重開"] = reopen([sa, sb], lambda w2: (w2.v_pk_mindist.get(), groups(w2) == g1))
    enter(w, w.v_pk_mindist, "1")
    check(md == {"1e19": ([], "1e19", True, "1", True), "1e300": ([], "1e300", True, "1", True), "重開": ("1", True)},
          f"Min Distance 打 1e19、1e300 按 Enter：不丟例外；第八輪起超過上限 2^53 − 1 是錯誤狀態（打的字留著、紅框、DSV 的上限訊息），峰值搜尋用、設定檔存"
          f"上一次合格的 1，重開視窗照常（以前 OverflowError：按 Enter 就存進去，之後開頻譜視窗建構子都失敗；第七輪照收＝只留最高的峰）（{md}）")
    # ---------------------------------------------------------------- 滿刻度很大（1e155：FS² 溢位）／很小（1e-200：FS² 是 0），單位 dBFS、通道量測開著：
    # 以前 spectrum_units 的 FS ** 2 丟 OverflowError、通道量測的 dBFS 功率除以 0 丟 ZeroDivisionError，每次重新計算都丟、壞值存進設定。MATLAB 收這些值
    # （MATLAB 的滿刻度欄位只擋 NaN 與 ≤ 0），DSV 照算（頻譜墊到下限、通道功率 ±Infinity）
    w.set_chmeas(on=True); app.update()
    w.v_unit_label.set("dBFS"); w._on_unit(); app.update()
    capfs = getattr(sv, "SPEC_MSG_FULLSCALE_CAP", "（第八輪的訊息 {v}）")
    fsx = {}
    for t_, v_ in (("1e155", "1e+155"), ("1e-200", "1e-200")):
        cb_ = enter(w, w.v_fullscale, t_)
        fsx[t_] = (cb_, err_on(w, w.v_fullscale, capfs.format(v=v_)), app.spec_defaults.get("fullscale"), (w._last_p or {}).get("fullscale"),
                   len(w.lines) > 0, w.cm_result is not None)
    fsx["重開"] = reopen([sa], lambda w2: (w2.v_fullscale.get(), len(w2.lines) > 0, w2.cm_result is not None))
    enter(w, w.v_fullscale, "Auto")
    w.set_chmeas(on=False); app.update()
    w.v_unit_label.set("dB"); w._on_unit(); app.update()
    check(fsx == {"1e155": ([], True, "", None, True, True), "1e-200": ([], True, "", None, True, True), "重開": ("Auto", True, True)},
          f"滿刻度 1e155（FS² 溢位）、1e-200（FS² 是 0）在 dBFS、通道量測開著時按 Enter：不丟例外；第八輪起超出 1e-150～1e150 是錯誤狀態（打的字留著、"
          f"紅框、DSV 的訊息），頻譜與通道量測用並存上一次合格的 Auto，重開視窗照常（以前 OverflowError／ZeroDivisionError，壞值存進設定後開頻譜視窗"
          f"建構子就失敗；第七輪照收）（{fsx}）")
    # ---------------------------------------------------------------- 頻率偏移的上限 ±1e300（DSV 才有）：再大 matplotlib 算不出頻率軸的刻度（線性約 9e307、
    # 對數刻度約 4e307 就丟例外）→ 欄位的錯誤狀態、DSV 的上限訊息、用並存上一次合格的值；設定檔裡的 1e308 開視窗時換回 0
    capf = getattr(sv, "SPEC_MSG_FOFFSET_CAP", "（第七輪的訊息 {v}）")
    enter(w, w.v_foffset, "1k")
    cb_ = enter(w, w.v_foffset, "1e308")
    fo1 = (cb_, w.v_foffset.get(), err_on(w, w.v_foffset, capf.format(v="1e+308")), w.v_status.get() == "頻寬：" + capf.format(v="1e+308"),
           (w._last_p or {}).get("foffset"), app.spec_defaults.get("foffset"))
    cb_ = enter(w, w.v_foffset, "-1e300")
    fo2 = (cb_, err_off(w, w.v_foffset, capf.format(v="1e+308")), (w._last_p or {}).get("foffset"), app.spec_defaults.get("foffset"))
    enter(w, w.v_foffset, "0")
    w.v_two.set(False); w.compute(); w.v_fscale_label.set("對數"); w._on_fscale(); app.update()
    cb_ = enter(w, w.v_foffset, "4e307")
    fo3 = (cb_, err_on(w, w.v_foffset, capf.format(v="4e+307")), w.fig.axes[0].get_xscale() if w.fig.axes else None, (w._last_p or {}).get("foffset"))
    enter(w, w.v_foffset, "0")
    w.v_fscale_label.set("線性"); w._on_fscale(); w.v_two.set(True); w.compute(); app.update()
    app.spec_defaults["foffset"] = "1e308"
    fo4 = reopen([sa], lambda w2: (w2.v_foffset.get(), err_off(w2, w2.v_foffset, capf.format(v="1e+308")), (w2._last_p or {}).get("foffset")))
    app.spec_defaults["foffset"] = "0"
    check(fo1 == ([], "1e308", True, True, 1000.0, "1k") and fo2 == ([], True, -1e300, "-1e300") and fo3 == ([], True, "log", 0.0)
          and fo4 == ("0", True, 0.0),
          f"頻率偏移 1e308 → 錯誤狀態：打的字留著、紅框、說明列與狀態列寫「頻率偏移 1e+308 太大，畫不出頻率軸（最多 ±1e+300）」，用並存上一次合格的 1k；"
          f"-1e300 照收；單邊對數刻度打 4e307 也是錯誤狀態（以前 9e307 以上、對數刻度 4e307 以上畫圖時丟例外，壞值存進設定）；設定檔裡的 1e308 開視窗時"
          f"換回 0、不提示（{fo1}、{fo2}、{fo3}、{fo4}）")
    # ---------------------------------------------------------------- 狀態列（第三批的規則）：還有欄位是錯誤狀態時，重新計算的「已計算…」與峰值的
    # 「峰值搜尋：已套用」不蓋掉——換成還錯著的欄位裡最後寫的那個錯誤，都改好才換回；在錯的欄位再按一次 Enter（字沒變）也再寫一次那個錯誤
    E_ov, E_fo, E_pk = "視窗選項：" + fm("overlap"), "頻寬：" + fm("foffset"), "峰值：" + fm("pk_num")
    S = lambda: w.v_status.get()                                 # noqa: E731
    st = {}
    cb_st = len(CB)                                              # 這一段的回呼例外（前面幾段的不算在這裡）
    enter(w, w.v_overlap, "100"); enter(w, w.v_foffset, "abc"); enter(w, w.v_foffset, "0")
    st["A 改好後打錯的偏移 → 重疊的錯誤"] = S() == E_ov
    enter(w, w.v_overlap, "0")
    st["A 都改好 → 已計算"] = S().startswith("已計算")
    enter(w, w.v_overlap, "100"); enter(w, w.v_foffset, "abc"); enter(w, w.v_overlap, "0")
    st["B 改好先打錯的重疊 → 偏移的錯誤"] = S() == E_fo
    enter(w, w.v_foffset, "0")
    st["B 都改好 → 已計算"] = S().startswith("已計算")
    enter(w, w.v_overlap, "100"); w.compute(); app.update()
    st["C 按「重新計算」→ 還是重疊的錯誤"] = S() == E_ov
    enter(w, w.v_foffset, "abc"); again(w, w.v_overlap)
    st["R 在重疊再按一次 Enter（字沒變）→ 重疊的錯誤"] = S() == E_ov
    again(w, w.v_foffset)
    st["R 在偏移再按一次 Enter → 偏移的錯誤"] = S() == E_fo
    enter(w, w.v_foffset, "0"); enter(w, w.v_overlap, "0")
    enter(w, w.v_overlap, "100"); enter(w, w.v_pk_num, "0")
    st["D 峰值錯 → 峰值的錯誤"] = S() == E_pk
    enter(w, w.v_pk_num, "3")
    st["D 改好峰值 → 重疊的錯誤（不是「峰值搜尋：已套用」）"] = S() == E_ov
    enter(w, w.v_overlap, "0")
    enter(w, w.v_pk_num, "0"); enter(w, w.v_overlap, "100"); enter(w, w.v_overlap, "0")
    st["E 改好重疊 → 峰值的錯誤（不是「已計算…」）"] = S() == E_pk
    enter(w, w.v_overlap, "100"); again(w, w.v_pk_num)
    st["E 在 Num Peaks 再按一次 Enter → 峰值的錯誤"] = S() == E_pk
    enter(w, w.v_overlap, "0"); enter(w, w.v_pk_num, "3")
    st["E 都改好 → 峰值搜尋：已套用"] = S() == "峰值搜尋：已套用"
    w.set_chmeas(on=False, mode="span"); app.update()
    span0 = w.v_cm_span.get()
    E_cm = "通道量測：" + sv.CM_MESSAGES["span"]
    w.v_cm_span.set("-5"); w._on_cm_field("span"); app.update()
    enter(w, w.v_overlap, "100"); enter(w, w.v_overlap, "0")
    st["F 通道量測跨度錯、改好重疊 → 跨度的錯誤"] = S() == E_cm
    w.v_cm_span.set(span0); w._on_cm_field("span"); app.update()
    st["F 都改好 → 已計算"] = S().startswith("已計算")
    E_mo = "頻譜遮罩：" + sv.MASK_MESSAGES["offset"]
    w.v_mask_offset.set("x"); w._on_mask_field("offset"); app.update()
    w.set_chmeas(on=True); app.update()
    st["G 打開通道量測（新的一句）→ 量測的結果"] = S().startswith("通道量測（")
    w.set_chmeas(on=False); app.update()
    st["G 關掉通道量測（換回「已計算…」）→ 遮罩偏移的錯誤"] = S() == E_mo
    w.v_mask_offset.set("0"); w._on_mask_field("offset"); app.update()
    st["G 都改好 → 已計算"] = S().startswith("已計算")
    w.settings_dialog(); app.update()
    dlg = w._settings_dlg
    kids = dlg.winfo_children()[0].winfo_children()
    ent = next(c_ for c_ in kids if c_.winfo_class() == "TEntry")
    btns = {str(b_.cget("text")): b_ for b_ in kids[-1].winfo_children()}
    ent.delete(0, "end"); ent.insert(0, "xyz"); btns["套用"].invoke(); app.update()
    enter(w, w.v_overlap, "100")
    btns["套用"].invoke(); app.update()
    st["H 設定對話框同一個錯字再按套用 → 設定的錯誤"] = S() == "設定：" + fm("clim")
    btns["取消"].invoke(); app.update()
    st["H 取消對話框 → 換成還錯著的重疊"] = S() == E_ov
    enter(w, w.v_overlap, "0")
    st["H 都改好 → 已計算"] = S().startswith("已計算")
    bad_st = [k_ for k_, v_ in st.items() if not v_]
    check(not bad_st and not CB[cb_st:],
          f"狀態列和第三批的欄位同一個規則：兩個欄位都錯時改好其中一個（第二批或峰值的），狀態列換成還錯著的那個（以前寫「已計算…」「峰值搜尋：已套用」，"
          f"另一個還是紅框）；按「重新計算」、關掉通道量測換回「已計算…」也一樣；在錯的欄位或設定對話框再按一次 Enter／套用（字沒變）就再寫一次那個錯誤；"
          f"打開通道量測寫的新的一句照留；都改好才換回（{bad_st or f'{len(st)} 項都對'}；回呼例外 {CB[cb_st:]}）")
    # ---------------------------------------------------------------- 峰值四個欄位逐一：打錯 → 打的字留著、紅框、提示與說明列是 MATLAB 的訊息、狀態列「峰值：…」，
    # 峰值搜尋用、設定檔存上一次合格的值（按 Enter 時與之後重新計算時都是）；改好 → 清掉、狀態列「峰值搜尋：已套用」、存新的字
    pk7 = {}
    for key_, var_, good_, bad_, used_, val_, back_ in (("pk_num", w.v_pk_num, "5", "0", "num", 5, "3"),
                                                        ("pk_thr", w.v_pk_thr, "3", "-1", "threshold", 3.0, "0"),
                                                        ("pk_minh", w.v_pk_minh, "-20", "NaN", "min_height", -20.0, ""),
                                                        ("pk_mindist", w.v_pk_mindist, "5", "0.5", "min_dist", 5, "1")):
        enter(w, var_, good_)
        tip0 = [getattr(c_, "_pk_tip", "") for c_ in fws(w, var_)]
        saved0 = app.spec_defaults.get(key_)
        enter(w, var_, bad_)
        on_ = (var_.get() == bad_, err_on(w, var_, fm(key_)), w.v_status.get() == "峰值：" + fm(key_), app.spec_defaults.get(key_) == good_,
               w.peak_params()[0][used_] == val_)
        w.compute(); app.update()
        on2 = (app.spec_defaults.get(key_) == good_, err_on(w, var_, fm(key_)), w.peak_params()[0][used_] == val_)
        enter(w, var_, back_)
        off_ = (err_off(w, var_, fm(key_)), [getattr(c_, "_pk_tip", "") for c_ in fws(w, var_)] == tip0, w.v_status.get() == "峰值搜尋：已套用",
                app.spec_defaults.get(key_) == back_)
        pk7[key_] = (saved0 == good_,) + on_ + on2 + off_
    bad_pk = {k_: v_ for k_, v_ in pk7.items() if not all(v_)}
    check(not bad_pk,
          f"峰值四個欄位逐一（Num Peaks 5 → 0、Threshold 3 → -1、Min Height -20 → NaN、Min Distance 5 → 0.5）：合格的字按 Enter 就存；打錯 → 打的字留著、"
          f"紅框、提示與說明列是 MATLAB 的錯誤訊息、狀態列「峰值：…」，峰值搜尋用、設定檔存上一次合格的值（重新計算以後也是）；改好 → 紅框與提示換回、"
          f"狀態列「峰值搜尋：已套用」、存新的字（{bad_pk or '4 個欄位都對'}）")
    # RMS 與線性單位的單位字：RMS 的 dB 是 dBV——Threshold（高度差）第八輪起收自己的單位字 dB（3 dB 收、3 dBV 錯；第七輪相反）；線性功率的 W（500 mW＝0.5）
    w.set_spectrum_type("rms"); app.update()
    u1 = (enter(w, w.v_pk_thr, "3 dB"), err_off(w, w.v_pk_thr, fm("pk_thr")), w.peak_params()[0]["threshold"])
    enter(w, w.v_pk_thr, "3 dBV")
    u2 = (err_on(w, w.v_pk_thr, fm("pk_thr")), w.peak_params()[0]["threshold"])
    enter(w, w.v_pk_thr, "0")
    w.set_spectrum_type("power"); w.v_unit_label.set("線性"); w._on_unit(); app.update()
    u3 = (enter(w, w.v_pk_minh, "500 mW"), err_off(w, w.v_pk_minh, fm("pk_minh")), w.peak_params()[0]["min_height"])
    enter(w, w.v_pk_minh, "")
    w.v_unit_label.set("dB"); w._on_unit(); w.set_spectrum_type("mag"); app.update()
    check(u1 == ([], True, 3.0) and u2 == (True, 3.0) and u3 == ([], True, 0.5),
          f"單位字：RMS 的 y 軸是 dBV，Threshold（高度差）收 dB（3 dB 照收、3 dBV 是錯、用上一次合格的 3）；線性功率是 W（Min Height 500 mW＝0.5）"
          f"（{u1}、{u2}、{u3}）")
    # 重新計算以外才發現的峰值錯誤（打了字沒按 Enter，再勾「標示峰值」重找）：說明列、狀態列也寫
    w.v_pk_num.set("0"); w.v_pk_label.set(True); w._update_peaks(draw=True); app.update()
    l7 = (fm("pk_num") in w.v_msg.get(), w.v_status.get() == "峰值：" + fm("pk_num"), err_on(w, w.v_pk_num, fm("pk_num")))
    enter(w, w.v_pk_num, "3"); w.v_pk_label.set(False); w._update_peaks(draw=True); app.update()
    check(l7 == (True, True, True), f"Num Peaks 打 0 沒按 Enter、勾「標示峰值」重找峰值：錯誤狀態、說明列與狀態列也寫（{l7}）")
    w.destroy(); app.update()
    # ---------------------------------------------------------------- 設定檔裡不合格的峰值欄位：開視窗時換回預設值、不紅、不提示
    app.spec_defaults.clear(); app.spec_defaults.update(dict(sv.DEFAULT_SPEC, peaks=True, pk_num="0", pk_thr="-1", pk_minh="NaN", pk_mindist="0.5"))
    w = sv.SpectrumWindow(app, [sa]); app.update()
    sf = (w.v_pk_num.get(), w.v_pk_thr.get(), w.v_pk_minh.get(), w.v_pk_mindist.get(),
          not any(c_.instate(["invalid"]) for v_ in (w.v_pk_num, w.v_pk_thr, w.v_pk_minh, w.v_pk_mindist) for c_ in fws(w, v_)),
          not any(fm(k_) in w.v_msg.get() for k_ in ("pk_num", "pk_thr", "pk_minh", "pk_mindist")), not w.v_status.get().startswith("峰值："))
    check(sf == ("3", "0", "", "1", True, True, True),
          f"設定檔裡不合格的峰值欄位（Num Peaks 0、Threshold -1、Min Height NaN、Min Distance 0.5）：開視窗時換回預設值 3／0／空白／1，不紅框、說明列與狀態列"
          f"不寫（和第二批、第三批的欄位一樣）（{sf}）")
    w.destroy(); app.update()
    # ---------------------------------------------------------------- 時間跨度：比 2 倍更新時間短而被拒的字，關掉頻譜圖再重新計算（沒辦法檢查）不會變成合格、
    # 不會存進設定；原本合格的 1 ms 照用照存（以前關掉頻譜圖它就變成「上一次合格」並存進設定，1 ms 不見了）
    app.spec_defaults.clear(); app.spec_defaults.update(dict(sv.DEFAULT_SPEC, view="both"))
    w = sv.SpectrumWindow(app, [sa]); app.update()
    m_smin = fm("tspan_min").format(sv.ml_num(2 * 1536 / 8e6)) if FM else "（第六輪的訊息）"
    enter(w, w.v_tspan, "1ms"); enter(w, w.v_tspan, "1us")
    t1 = (err_on(w, w.v_tspan, m_smin), app.spec_defaults.get("tspan"))
    w.btn_view_sg.invoke(); app.update()
    t2 = (w.v_show_sg.get(), err_on(w, w.v_tspan, m_smin), (w._last_p or {}).get("tspan"), app.spec_defaults.get("tspan"))
    w.btn_view_sg.invoke(); app.update()
    yl = w.sg_ax.get_ylim() if w.sg_ax is not None else (0.0, 0.0)
    t3 = (err_on(w, w.v_tspan, m_smin), abs((yl[1] - yl[0]) - 1e-3) < 1e-9, app.spec_defaults.get("tspan"))
    w.destroy(); app.update()
    w = sv.SpectrumWindow(app, [sa]); app.update()
    t4 = (w.v_tspan.get(), err_off(w, w.v_tspan, m_smin))
    check(t1 == (True, "1ms") and t2 == (False, True, 0.001, "1ms") and t3 == (True, True, "1ms") and t4 == ("1ms", True),
          f"時間跨度 1us 比 2 倍更新時間短被拒（用並存 1 ms）→ 關掉頻譜圖：還是錯誤狀態、用並存 1 ms；再打開：頻譜圖照樣顯示最後 1 ms；重開視窗是 1ms"
          f"（以前關掉頻譜圖 1us 就變成合格並存進設定）（{t1}、{t2}、{t3}、{t4}）")
    # 時間用 symbol（關掉「頻率用 Hz」）：時間跨度太短的訊息寫 symbol（DSV 自己的句子；hop＝1536 點 ÷ 8 點／symbol＝192 symbol，{0}＝384）
    w.v_hz.set(False); w.compute(); app.update()
    enter(w, w.v_tspan, "100")
    m_sym = getattr(sv, "SPEC_FIELD_MESSAGES_SYMBOL", {}).get("tspan_min", "（symbol）").format("384")
    sy = (err_on(w, w.v_tspan, m_sym), w.v_status.get() == "時間選項：" + m_sym, "symbol" in m_sym)
    enter(w, w.v_tspan, "Auto"); w.v_hz.set(True); w.compute(); app.update()
    check(sy == (True, True, True), f"時間用 symbol 時時間跨度太短：訊息寫「…大於 384 symbol…」（{sy}）")
    # 衰減的上限只看目前的視窗：Kaiser 6200 dB 算得出來 → 照收；換 Chebyshev（算不出來）→ 錯誤狀態、用預設 60；換回 Kaiser → 清掉、又是 6200
    w.set_view("spectrum"); app.update()
    w.v_res_label.set("視窗長度"); w._on_res()
    w.v_window_label.set("Kaiser"); w._on_window(); app.update()
    big = sv.SPEC_MSG_ATTEN_BIG.format(v="6200")
    enter(w, w.v_atten, "6200")
    k1 = (err_off(w, w.v_atten, big), "Window = Kaiser (6200 dB)" in w.v_info.get(), app.spec_defaults.get("atten"))
    w.v_window_label.set("Chebyshev"); w._on_window(); app.update()
    k2 = (w.v_atten.get(), err_on(w, w.v_atten, big), w.v_status.get() == "視窗選項：" + big, "Window = Chebyshev (60 dB)" in w.v_info.get())
    w.v_window_label.set("Kaiser"); w._on_window(); app.update()
    k3 = (err_off(w, w.v_atten, big), "Window = Kaiser (6200 dB)" in w.v_info.get())
    enter(w, w.v_atten, "60")
    w.v_window_label.set("Hann"); w._on_window(); w.v_res_label.set("RBW"); w._on_res(); app.update()
    check(k1 == (True, True, "6200") and k2 == ("6200", True, True, True) and k3 == (True, True),
          f"衰減的上限只看目前的視窗（使用者決定留第五輪的「算不出視窗＝錯」）：Kaiser 6200 dB 照收（第六輪兩種視窗都看，說 Kaiser 算不出視窗）；換 Chebyshev"
          f"（真的算不出來）→ 錯誤狀態「衰減 6200 dB 太大，算不出視窗」、用預設 60；換回 Kaiser 又是 6200（{k1}、{k2}、{k3}）")
    # 只看頻譜時沒有頻譜圖上限的說明（重疊 99.99%＋重新指派：要畫頻譜圖的話會超過 2^26 格，但頻譜圖沒開）
    w.v_reassign.set(True)
    enter(w, w.v_overlap, "99.99")
    cap_x = ("頻譜圖要" not in w.v_msg.get(), len(w.lines) > 0, w.sg_image is None)
    w.v_reassign.set(False); enter(w, w.v_overlap, "0")
    check(cap_x == (True, True, True), f"只看頻譜（重疊 99.99%、重新指派）：頻譜照畫，說明列沒有「頻譜圖要…太大」——頻譜圖沒開就不檢查它的上限（{cap_x}）")
    # 色彩範圍：套用 -70 dB, 10 dB → 單位改 dBm（色彩列的單位變了）→ 錯誤狀態、用預設 [-80 20]；打開設定對話框：欄位一打開就紅框、下方寫訊息；
    # 再按「設定…」還是同一個對話框；單位改回 dB → 清掉、又是 [-70 10]
    m_cl = fm("clim")
    w.set_view("both"); app.update()
    w.settings_dialog(); app.update()
    dlg = w._settings_dlg
    kids = dlg.winfo_children()[0].winfo_children()
    ent = next(c_ for c_ in kids if c_.winfo_class() == "TEntry")
    btns = {str(b_.cget("text")): b_ for b_ in kids[-1].winfo_children()}
    ent.delete(0, "end"); ent.insert(0, "-70 dB, 10 dB"); btns["確定"].invoke(); app.update()
    cl1 = (w.v_clim.get(), (w._last_p or {}).get("clim"))
    w.v_unit_label.set("dBm"); w._on_unit(); app.update()
    cl2 = (m_cl in w.v_msg.get(), w.v_status.get() == "設定：" + m_cl, (w._last_p or {}).get("clim"))
    w.settings_dialog(); app.update()
    dlg = w._settings_dlg
    kids = dlg.winfo_children()[0].winfo_children()
    ent = next(c_ for c_ in kids if c_.winfo_class() == "TEntry")
    lbl = [dlg.getvar(str(c_.cget("textvariable"))) for c_ in kids if c_.winfo_class() == "TLabel" and str(c_.cget("textvariable"))]
    cl3 = (ent.get(), bool(ent.instate(["invalid"])), m_cl in lbl)
    w.settings_dialog(); app.update()
    n_dlg = len([c_ for c_ in w.winfo_children() if isinstance(c_, sv.tk.Toplevel) and c_.winfo_exists()])
    {str(b_.cget("text")): b_ for b_ in kids[-1].winfo_children()}["取消"].invoke(); app.update()
    w.v_unit_label.set("dB"); w._on_unit(); app.update()
    cl4 = (m_cl not in w.v_msg.get(), (w._last_p or {}).get("clim"), w.v_status.get().startswith("已計算"))
    check(cl1 == ("-70 dB, 10 dB", (-70.0, 10.0)) and cl2 == (True, True, (-80.0, 20.0)) and cl3 == ("-70 dB, 10 dB", True, True) and n_dlg == 1
          and cl4 == (True, (-70.0, 10.0), True),
          f"色彩範圍 -70 dB, 10 dB 之後單位改 dBm → 錯誤狀態（說明列、狀態列「設定：…」）、用預設 [-80 20]；打開設定對話框時欄位就是紅框、下方寫訊息；"
          f"再按「設定…」還是同一個對話框（{n_dlg} 個）；單位改回 dB → 清掉、又是 [-70 10]（{cl1}、{cl2}、{cl3}、{cl4}）")
    # 程式直接把色彩範圍改成不合格的字（工具列沒有這個欄位）：一樣是錯誤狀態，計算與設定檔用並存上一次合格的 -70, 10（不是預設值、不存打錯的字）
    w.v_clim.set("-70, 10"); w.compute(); app.update()
    w.v_clim.set("abc"); w.compute(); app.update()
    clp = ((w._last_p or {}).get("clim"), app.spec_defaults.get("clim"), m_cl in w.v_msg.get())
    w.v_clim.set("-80, 20"); w.compute(); app.update()
    check(clp == ((-70.0, 10.0), "-70, 10", True) and m_cl not in w.v_msg.get(),
          f"程式把色彩範圍改成 abc：錯誤狀態、說明列寫色彩範圍的錯誤訊息，計算與設定檔用並存上一次合格的 -70, 10；改回合格的值就清掉（{clp}）")
    w.destroy(); app.update()



@step
def s30_round8_fields():
    """第三批審查第八輪（使用者 2026-10-26 05:20 的選單）：滿刻度與 Min Distance 的上限（極端值是欄位的錯誤狀態：紅框、說明列與狀態列寫原因、用並存上一次
    合格的值）；dBFS 改用對數換算（滿刻度很小、資料很大時不再是 Inf）；Threshold 在 dB 類時收自己的單位字 dB；說明列的大整數用科學記號；灰掉或藏起來
    的欄位（RBW 模式的視窗長度、視窗長度模式的 RBW、Hann 的衰減、關掉頻譜圖的時間選項、設定對話框沒開時的色彩範圍）維持灰框，說明列寫「欄位名稱：訊息
    （怎麼做才改得到）」，換回能用的模式就是紅框、說明列只寫訊息。欄位一律用真的 Enter（tests_common.tk_key），回呼丟的例外照實記下。"""
    cfg0 = app.dump_settings()
    spec0 = dict(app.spec_defaults)
    CB = []

    def rec(exc, val, tb):
        CB.append(f"{exc.__name__}: {val}")
    had = "report_callback_exception" in app.__dict__
    app.report_callback_exception = rec
    try:
        _s30_round8_body(CB)
    finally:
        if not had:
            del app.report_callback_exception
        for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow)]:
            try:
                t_.destroy()
            except Exception:                                    # noqa: BLE001
                pass
        app.spec_defaults.clear(); app.spec_defaults.update(spec0)
        app.apply_settings(cfg0, quiet=True); app.update()


def _s30_round8_body(CB):
    fs = 8e6; n = 20000
    t = np.arange(n) / fs
    rng = np.random.default_rng(8)
    y1 = np.sin(2 * np.pi * 1e6 * t) + 0.01 * np.sin(2 * np.pi * 2.5e6 * t) + 1e-3 * rng.standard_normal(n)
    y2 = 0.5 * np.sin(2 * np.pi * 1.5e6 * t) + 1e-3 * rng.standard_normal(n)
    y3 = 1e5 * np.sin(2 * np.pi * 0.5e6 * t) + rng.standard_normal(n)     # 很大的資料：滿刻度 1e-150 時以前 P/(FS²/2) 溢位成 Inf
    path = os.path.join(ROOT, "spec8_tones.csv")
    with open(path, "w") as f:
        f.write("Time,tone a,tone b,tone big\n")
        f.writelines(f"{tt:.12f},{a:.9f},{b:.9f},{c:.6f}\n" for tt, a, b, c in zip(t, y1, y2, y3))
    app.v["symbol_rate"].set("1M")
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    sa = app.find_signal("spec8_tones.csv;;tone a"); sb = app.find_signal("spec8_tones.csv;;tone b")
    sbig = app.find_signal("spec8_tones.csv;;tone big")
    FM = getattr(sv, "SPEC_FIELD_MESSAGES", {})
    fm = lambda k_: FM.get(k_, "（第六輪的訊息）")                # noqa: E731

    def fws(w_, var_):
        return [c_ for c_ in strip_controls(w_.strip) if c_.winfo_class() in ("TEntry", "TCombobox", "TSpinbox")
                and str(c_.cget("textvariable")) == str(var_)]

    def err_on(w_, var_, msg_):
        ws_ = fws(w_, var_)
        return bool(ws_) and all(c_.instate(["invalid"]) and getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ in w_.v_msg.get()

    def err_off(w_, var_, msg_):
        ws_ = fws(w_, var_)
        return bool(ws_) and not any(c_.instate(["invalid"]) or getattr(c_, "_pk_tip", "") == msg_ for c_ in ws_) and msg_ not in w_.v_msg.get()

    def enter(w_, var_, txt_, idx_=0):
        c_ = fws(w_, var_)[idx_]
        was = str(c_.cget("state"))
        if was == "disabled":                                    # 灰掉的欄位：打字要先讓它能用（使用者是先換模式），這裡只用在能用的欄位
            return [f"欄位灰掉：{var_}"]
        c_.delete(0, "end"); c_.insert(0, txt_)
        n0 = len(CB)
        tk_key(c_, "Return"); app.update()
        return CB[n0:]

    def reopen(sigs, fn):
        n0 = len(CB)
        try:
            w2 = sv.SpectrumWindow(app, sigs); app.update()
        except Exception as ex_:                                 # noqa: BLE001
            return f"例外 {type(ex_).__name__}"
        r_ = fn(w2)
        w2.destroy(); app.update()
        return r_ if len(CB) == n0 else f"回呼例外 {CB[n0:]}"

    def groups(w_):
        return [len(w_.peaks_tree.get_children(g_)) for g_ in w_.peaks_tree.get_children()]

    def notes(w_):
        return w_.v_msg.get().split("；")
    app.spec_defaults.clear(); app.spec_defaults.update(sv.DEFAULT_SPEC)
    # ---------------------------------------------------------------- 滿刻度的範圍 1e-150～1e150（DSV 的上限）：範圍外是錯誤狀態——打的字留著、頻譜與頻譜圖分頁的
    # 兩個欄位都紅、說明列與狀態列（「刻度：…」）寫原因，dBFS 與通道量測用並存上一次合格的 512；邊界照收；設定檔裡的 1e155 開視窗時換回 Auto、不提示
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()
    w.set_chmeas(on=True); app.update()
    w.v_unit_label.set("dBFS"); w._on_unit(); app.update()
    capfs = getattr(sv, "SPEC_MSG_FULLSCALE_CAP", "（第八輪的訊息 {v}）")
    enter(w, w.v_fullscale, "512")
    y512 = [np.asarray(ln.get_ydata(), dtype=float).copy() for ln in w.lines.values()]
    fsr = {}
    for t_, v_ in (("1e155", "1e+155"), ("1e-200", "1e-200"), ("1.5e150", "1.5e+150"), ("9e-151", "9e-151")):
        cb_ = enter(w, w.v_fullscale, t_)
        fsr[t_] = (cb_, w.v_fullscale.get() == t_, err_on(w, w.v_fullscale, capfs.format(v=v_)), len(fws(w, w.v_fullscale)) == 2,
                   w.v_status.get() == "刻度：" + capfs.format(v=v_), app.spec_defaults.get("fullscale"), (w._last_p or {}).get("fullscale"),
                   all(np.array_equal(np.asarray(ln.get_ydata(), dtype=float), y_) for ln, y_ in zip(w.lines.values(), y512)) and len(w.lines) == len(y512))
    for t_ in ("1e150", "1e-150"):
        cb_ = enter(w, w.v_fullscale, t_)
        ys_ = np.concatenate([np.asarray(ln.get_ydata(), dtype=float) for ln in w.lines.values()]) if w.lines else np.zeros(0)
        fsr[t_] = (cb_, err_off(w, w.v_fullscale, capfs.format(v=sv.ml_num(float(t_)))), app.spec_defaults.get("fullscale"),
                   bool(ys_.size) and bool(np.all(np.isfinite(ys_))), w.cm_result is not None and math.isfinite(w.cm_result["power_disp"]))
    enter(w, w.v_fullscale, "Auto")
    w.destroy(); app.update()
    app.spec_defaults["fullscale"] = "1e155"
    fsr["設定檔 1e155"] = reopen([sa], lambda w2: (w2.v_fullscale.get(), err_off(w2, w2.v_fullscale, capfs.format(v="1e+155")),
                                                   not w2.v_status.get().startswith("刻度：")))
    app.spec_defaults["fullscale"] = ""
    want_fs = {k_: ([], True, True, True, True, "512", 512.0, True) for k_ in ("1e155", "1e-200", "1.5e150", "9e-151")}
    want_fs.update({"1e150": ([], True, "1e150", True, True), "1e-150": ([], True, "1e-150", True, True), "設定檔 1e155": ("Auto", True, True)})
    bad_fs = {k_: v_ for k_, v_ in fsr.items() if want_fs.get(k_) != v_}
    check(not bad_fs and not CB,
          f"滿刻度的範圍 1e-150～1e150（使用者 2026-10-26 決定加上限）：1e155、1e-200、1.5e150、9e-151 按 Enter → 打的字留著、兩個欄位（頻譜與頻譜圖分頁）都紅、"
          f"說明列與狀態列「刻度：滿刻度 … 超出範圍，要在 1e-150 到 1e+150 之間」，頻譜用並存上一次合格的 512（畫出來的值不變）；1e150、1e-150 照收、頻譜與"
          f"通道功率是有限的值；設定檔裡的 1e155 開視窗時換回 Auto、不提示（第七輪照收：頻譜墊到下限、通道功率 ±Infinity）（{bad_fs or '都對'}；回呼例外 {CB}）")
    # 很大的資料（振幅 1e5）在滿刻度 1e-150 的 dBFS：對數換算是有限的值（第七輪先除，P/(FS²/2) 溢位成 +Inf：線上的值是 Inf、通道功率 +Infinity）
    w = sv.SpectrumWindow(app, [sbig]); app.update()
    w.set_chmeas(on=True); w.v_unit_label.set("dBFS"); w._on_unit(); app.update()
    for st_ in ("power", "mag"):
        w.set_spectrum_type(st_); app.update()
        enter(w, w.v_fullscale, "1e-150")
    ys_ = np.concatenate([np.asarray(ln.get_ydata(), dtype=float) for ln in w.lines.values()]) if w.lines else np.zeros(0)
    w.set_spectrum_type("power"); app.update()
    yp_ = np.concatenate([np.asarray(ln.get_ydata(), dtype=float) for ln in w.lines.values()]) if w.lines else np.zeros(0)
    cmp_ = w.cm_result["power_disp"] if w.cm_result is not None else None
    big_ok = (bool(ys_.size) and bool(np.all(np.isfinite(ys_))), bool(yp_.size) and bool(np.all(np.isfinite(yp_))) and float(np.max(yp_)) > 3000.0,
              cmp_ is not None and math.isfinite(cmp_) and cmp_ > 3000.0)
    enter(w, w.v_fullscale, "Auto")
    w.destroy(); app.update()
    check(big_ok == (True, True, True),
          f"振幅 1e5 的資料、滿刻度 1e-150 的 dBFS（振幅與功率類型）：頻譜的值與通道功率都是有限的（對數換算；第七輪先除，P/(FS²/2) 溢位成 +Inf）（{big_ok}、"
          f"通道功率 {cmp_}）")
    # ---------------------------------------------------------------- Min Distance 有限值最多 2^53 − 1（DSV 的上限；Inf 照 MATLAB 收）：1e19、1e300、2^53 是錯誤狀態——
    # 打的字留著、紅框、說明列與狀態列（「峰值：…」）寫原因，峰值搜尋用、設定檔存上一次合格的 5；2^53 − 1、Inf 照收（只留最高的峰）；設定檔裡的 1e300 開視窗時換回 1
    w = sv.SpectrumWindow(app, [sa, sb]); app.update()
    w.btn_peaks.invoke(); app.update()
    capm = getattr(sv, "SPEC_MSG_MINDIST_CAP", "（第八輪的訊息 {v}）")
    enter(w, w.v_pk_mindist, "5")
    g5 = groups(w)
    mdr = {}
    for t_, v_ in (("1e19", "10000000000000000000"), ("1e300", "1e+300"), ("9007199254740992", "9007199254740992")):
        cb_ = enter(w, w.v_pk_mindist, t_)
        mdr[t_] = (cb_, w.v_pk_mindist.get() == t_, err_on(w, w.v_pk_mindist, capm.format(v=v_)), w.v_status.get() == "峰值：" + capm.format(v=v_),
                   app.spec_defaults.get("pk_mindist"), w.peak_params()[0]["min_dist"], groups(w) == g5)
    for t_ in ("9007199254740991", "Inf"):
        cb_ = enter(w, w.v_pk_mindist, t_)
        mdr[t_] = (cb_, err_off(w, w.v_pk_mindist, capm.format(v="1e+300")), app.spec_defaults.get("pk_mindist"), groups(w))
    enter(w, w.v_pk_mindist, "1")
    w.destroy(); app.update()
    app.spec_defaults["pk_mindist"] = "1e300"; app.spec_defaults["peaks"] = True
    mdr["設定檔 1e300"] = reopen([sa, sb], lambda w2: (w2.v_pk_mindist.get(), err_off(w2, w2.v_pk_mindist, capm.format(v="1e+300")),
                                                       not w2.v_status.get().startswith("峰值：")))
    app.spec_defaults["pk_mindist"] = "1"; app.spec_defaults["peaks"] = False
    want_md = {k_: ([], True, True, True, "5", 5, True) for k_ in ("1e19", "1e300", "9007199254740992")}
    want_md.update({"9007199254740991": ([], True, "9007199254740991", [1, 1]), "Inf": ([], True, "Inf", [1, 1]), "設定檔 1e300": ("1", True, True)})
    bad_md = {k_: v_ for k_, v_ in mdr.items() if want_md.get(k_) != v_}
    check(not bad_md and g5 != [1, 1],
          f"Min Distance 的上限 2^53 − 1（使用者 2026-10-26 決定）：1e19、1e300、2^53 按 Enter → 錯誤狀態（打的字留著、紅框、說明列與狀態列「峰值：最小峰值距離 … "
          f"太大…」），峰值搜尋用、設定檔存上一次合格的 5；2^53 − 1 與 Inf 照收（只留最高的峰）；設定檔裡的 1e300 開視窗時換回 1、不提示（第七輪照收＝只留"
          f"最高的峰）（{bad_md or '都對'}、{g5}）")
    # ---------------------------------------------------------------- Threshold 在 dB 類時收自己的單位字 dB（高度差）：y 軸 dBm、dBV（RMS）、dBFS/Hz 時 3 dB 照收、
    # 3 dBm／3 dBV／3 dBFS/Hz 是錯；線性時和 y 軸同單位（3 W 收、3 dB 錯）；Min Height 照舊收 y 軸的單位
    w = sv.SpectrumWindow(app, [sa]); app.update()
    w.btn_peaks.invoke(); app.update()
    thr = {}
    for st_, un_, lin_, bad_ in (("mag", "dBm", False, "3 dBm"), ("rms", "dB", False, "3 dBV"), ("psd", "dBFS", False, "3 dBFS/Hz"),
                                 ("power", "dB", True, "3 dB")):
        w.set_spectrum_type(st_); w.v_unit_label.set("線性" if lin_ else un_); w._on_unit(); app.update()
        ok_ = "3 W" if lin_ else "3 dB"
        cb1 = enter(w, w.v_pk_thr, ok_)
        r1 = (cb1, err_off(w, w.v_pk_thr, fm("pk_thr")), w.peak_params()[0]["threshold"])
        cb2 = enter(w, w.v_pk_thr, bad_)
        r2 = (cb2, err_on(w, w.v_pk_thr, fm("pk_thr")), w.peak_params()[0]["threshold"], app.spec_defaults.get("pk_thr"))
        thr[f"{st_} {'線性' if lin_ else un_}"] = (r1, r2)
        enter(w, w.v_pk_thr, "0")
    w.set_spectrum_type("mag"); w.v_unit_label.set("dBm"); w._on_unit(); app.update()
    mh = (enter(w, w.v_pk_minh, "-50 dBm"), err_off(w, w.v_pk_minh, fm("pk_minh")), w.peak_params()[0]["min_height"])
    enter(w, w.v_pk_minh, "-50 dB")
    mh2 = err_on(w, w.v_pk_minh, fm("pk_minh"))
    enter(w, w.v_pk_minh, "")
    w.v_unit_label.set("dB"); w._on_unit(); app.update()
    w.destroy(); app.update()
    want_thr = {k_: (([], True, 3.0), ([], True, 3.0, ok_s)) for k_, ok_s in (("mag dBm", "3 dB"), ("rms dB", "3 dB"), ("psd dBFS", "3 dB"),
                                                                                ("power 線性", "3 W"))}
    check(thr == want_thr and mh == ([], True, -50.0) and mh2,
          f"Threshold（峰和鄰點的高度差）在 dB 類時收自己的單位字 dB：y 軸 dBm、dBV（RMS）、dBFS/Hz 時 3 dB 照收、3 dBm／3 dBV／3 dBFS/Hz 是錯（用並存上一次"
          f"合格的 3；第七輪收 y 軸的位準單位，3 dB 是錯）；線性時同 y 軸（3 W 收、3 dB 錯）；Min Height 照舊收 y 軸的單位（-50 dBm 收、-50 dB 錯）"
          f"（{ {k_: v_ for k_, v_ in thr.items() if want_thr.get(k_) != v_} or '4 種都對'}、{mh}、{mh2}）")
    # ---------------------------------------------------------------- 灰掉或藏起來的欄位：維持灰框（disabled 與 invalid 都在，主題畫灰框），說明列寫「欄位名稱：訊息
    # （怎麼做才改得到）」，狀態列照舊寫「區段：訊息」；換回能用的模式 → 紅框、說明列只寫訊息（不帶「才改得到」）
    w = sv.SpectrumWindow(app, [sa]); app.update()
    hid = {}

    def grey(c_):
        return bool(c_.instate(["disabled", "invalid"]))

    def red(c_):
        return bool(c_.instate(["invalid"])) and not c_.instate(["disabled"])
    # 視窗長度：視窗長度模式打 2 → 切到 RBW 模式（欄位灰掉）
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    enter(w, w.v_wlen, "2")
    on_ = (red(w.e_wlen), notes(w).count(fm("wlen")) == 1)
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    hid["視窗長度（RBW 模式）"] = (on_, grey(w.e_wlen), "視窗長度：" + fm("wlen") + "（切到「視窗長度」模式才改得到）" in notes(w),
                              w.v_status.get() == "頻率解析度：" + fm("wlen"))
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    hid["視窗長度（換回視窗長度模式）"] = (red(w.e_wlen), fm("wlen") in notes(w), "才改得到" not in w.v_msg.get())
    enter(w, w.v_wlen, "1024")
    # RBW：RBW 模式打 -1 → 切到視窗長度模式
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    enter(w, w.v_rbw, "-1")
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    hid["RBW（視窗長度模式）"] = (grey(w.cb_rbw), "RBW：" + fm("rbw") + "（切到「RBW」模式才改得到）" in notes(w))
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    hid["RBW（換回 RBW 模式）"] = (red(w.cb_rbw), fm("rbw") in notes(w), "才改得到" not in w.v_msg.get())
    enter(w, w.v_rbw, "Auto")
    # 衰減：Kaiser 打 30 → 換 Hann（灰掉）
    w.v_window_label.set("Kaiser"); w._on_window(); app.update()
    enter(w, w.v_atten, "30")
    w.v_window_label.set("Hann"); w._on_window(); app.update()
    hid["衰減（Hann）"] = (grey(w.e_atten), "衰減：" + fm("atten") + "（視窗選「Chebyshev」或「Kaiser」才改得到）" in notes(w),
                         w.v_status.get() == "視窗選項：" + fm("atten"))
    w.v_window_label.set("Chebyshev"); w._on_window(); app.update()
    hid["衰減（換 Chebyshev）"] = (red(w.e_atten), fm("atten") in notes(w), "才改得到" not in w.v_msg.get())
    enter(w, w.v_atten, "60")
    w.v_window_label.set("Hann"); w._on_window(); app.update()
    # 時間解析度、時間跨度：兩個檢視都開時打錯 → 關掉頻譜圖（分頁藏起來）
    w.set_view("both"); app.update()
    enter(w, w.v_tres, "0"); enter(w, w.v_tspan, "-1")
    w.btn_view_sg.invoke(); app.update()
    hid["時間選項（頻譜圖關）"] = (not w.v_show_sg.get() and not w.strip.tab_visible("spectrogram"),
                             "時間解析度：" + fm("tres") + "（打開「頻譜圖」檢視才改得到）" in notes(w),
                             "時間跨度：" + fm("tspan") + "（打開「頻譜圖」檢視才改得到）" in notes(w), w.v_status.get() == "時間選項：" + fm("tspan"))
    w.btn_view_sg.invoke(); app.update()
    hid["時間選項（頻譜圖開）"] = (red(w.cb_tres) and red(w.cb_tspan), fm("tres") in notes(w) and fm("tspan") in notes(w), "才改得到" not in w.v_msg.get())
    enter(w, w.v_tres, "Auto"); enter(w, w.v_tspan, "Auto")
    w.set_view("spectrum"); app.update()
    # 色彩範圍：程式改成 abc（工具列沒有這個欄位）→ 說明列「色彩範圍：…（按「設定…」才改得到）」；打開設定對話框 → 只寫訊息；取消 → 又寫怎麼改得到
    w.v_clim.set("abc"); w.compute(); app.update()
    c1 = "色彩範圍：" + fm("clim") + "（按「設定…」才改得到）" in notes(w)
    w.settings_dialog(); app.update()
    c2 = (fm("clim") in notes(w), "才改得到" not in w.v_msg.get())
    dlg = w._settings_dlg
    kids = dlg.winfo_children()[0].winfo_children()
    {str(b_.cget("text")): b_ for b_ in kids[-1].winfo_children()}["取消"].invoke(); app.update()
    c3 = "色彩範圍：" + fm("clim") + "（按「設定…」才改得到）" in notes(w)
    hid["色彩範圍（設定對話框）"] = (c1, c2, c3)
    w.v_clim.set("-80, 20"); w.compute(); app.update()
    hid["都改好"] = (w.v_msg.get() == "" or "才改得到" not in w.v_msg.get(), not any(c_.instate(["invalid"]) for c_ in strip_controls(w.strip)))
    # 說明列的大整數用科學記號：視窗長度 1e300（合格的整數，> 2）→「不夠一段視窗（1e+300 點）」，不寫 301 位數
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    enter(w, w.v_wlen, "1e300")
    m_l = w.v_msg.get()
    hid["視窗長度 1e300 的說明"] = ("不夠一段視窗（1e+300 點）" in m_l, "0" * 30 not in m_l)
    enter(w, w.v_wlen, "1024")
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    w.destroy(); app.update()
    want_hid = {"視窗長度（RBW 模式）": ((True, True), True, True, True), "視窗長度（換回視窗長度模式）": (True, True, True),
                "RBW（視窗長度模式）": (True, True), "RBW（換回 RBW 模式）": (True, True, True), "衰減（Hann）": (True, True, True),
                "衰減（換 Chebyshev）": (True, True, True), "時間選項（頻譜圖關）": (True, True, True, True), "時間選項（頻譜圖開）": (True, True, True),
                "色彩範圍（設定對話框）": (True, (True, True), True), "都改好": (True, True), "視窗長度 1e300 的說明": (True, True)}
    bad_hid = {k_: v_ for k_, v_ in hid.items() if want_hid.get(k_) != v_}
    check(not bad_hid and not CB,
          f"灰掉或藏起來的欄位（使用者 2026-10-26 決定：維持主題的灰框，說明列寫清楚怎麼改得到）：視窗長度（RBW 模式）「視窗長度：…（切到「視窗長度」模式才改得到）」、"
          f"RBW（視窗長度模式）「RBW：…（切到「RBW」模式才改得到）」、衰減（Hann）「衰減：…（視窗選「Chebyshev」或「Kaiser」才改得到）」、時間解析度與時間跨度"
          f"（關掉頻譜圖）「…（打開「頻譜圖」檢視才改得到）」、色彩範圍（設定對話框沒開）「色彩範圍：…（按「設定…」才改得到）」——欄位灰框（disabled＋invalid）、"
          f"狀態列照舊「區段：訊息」；換回能用的模式 → 紅框、說明列只寫訊息；視窗長度 1e300 的說明寫「1e+300 點」（以前 301 位數）"
          f"（{bad_hid or '都對'}；回呼例外 {CB}）")


@step
def s30_round9_fields():
    """第三批審查第九輪：設定檔裡不認得的檢視換回頻譜（以前兩個檢視都關、什麼都沒畫）；RBW 是次正規數時說明「不夠一段視窗（Inf 點）」（以前怪衰減）；
    峰值欄位在重新計算以外改好（打了合格的字沒按 Enter、縮放後重找峰值）時說明列與狀態列跟著換回；以及第八輪的變異測試找到的缺口——灰掉的欄位不在每次
    重新計算時重新宣告錯誤、重疊的箭頭從欄位現在的字起算、設定檔裡不合格的第二批欄位開視窗時換回預設值、狀態列記下最新的「已計算…」、同一欄換了另一個
    錯字由別的動作重新計算時狀態列再寫一次、頻譜圖剛好 2^26 格（上限，含）照畫。欄位一律用真的 Enter（tests_common.tk_key），回呼丟的例外照實記下。"""
    cfg0 = app.dump_settings()
    spec0 = dict(app.spec_defaults)
    cells0 = sv.SPEC_MAX_SG_CELLS
    CB = []

    def rec(exc, val, tb):
        CB.append(f"{exc.__name__}: {val}")
    had = "report_callback_exception" in app.__dict__
    app.report_callback_exception = rec
    try:
        _s30_round9_body(CB)
    finally:
        sv.SPEC_MAX_SG_CELLS = cells0
        if not had:
            del app.report_callback_exception
        for t_ in [c_ for c_ in app.winfo_children() if isinstance(c_, sv.SpectrumWindow)]:
            try:
                t_.destroy()
            except Exception:                                    # noqa: BLE001
                pass
        app.spec_defaults.clear(); app.spec_defaults.update(spec0)
        app.apply_settings(cfg0, quiet=True); app.update()


def _s30_round9_body(CB):
    fs = 8e6; n = 20000
    t = np.arange(n) / fs
    rng = np.random.default_rng(9)
    y1 = np.sin(2 * np.pi * 1e6 * t) + 0.01 * np.sin(2 * np.pi * 2.5e6 * t) + 1e-3 * rng.standard_normal(n)
    y2 = 0.5 * np.sin(2 * np.pi * 1.5e6 * t) + 1e-3 * rng.standard_normal(n)
    path = os.path.join(ROOT, "spec9_tones.csv")
    with open(path, "w") as f:
        f.write("Time,tone a,tone b\n")
        f.writelines(f"{tt:.12f},{a:.9f},{b:.9f}\n" for tt, a, b in zip(t, y1, y2))
    app.v["symbol_rate"].set("1M")
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(); app.show_all_x(); app.update()
    sa = app.find_signal("spec9_tones.csv;;tone a")
    FM = sv.SPEC_FIELD_MESSAGES
    fm = lambda k_: FM[k_]                                       # noqa: E731

    def fws(w_, var_):
        return [c_ for c_ in strip_controls(w_.strip) if c_.winfo_class() in ("TEntry", "TCombobox", "TSpinbox")
                and str(c_.cget("textvariable")) == str(var_)]

    def enter(w_, var_, txt_, idx_=0):
        c_ = fws(w_, var_)[idx_]
        if str(c_.cget("state")) == "disabled":
            return [f"欄位灰掉：{var_}"]
        c_.delete(0, "end"); c_.insert(0, txt_)
        n0 = len(CB)
        tk_key(c_, "Return"); app.update()
        return CB[n0:]

    def type_only(w_, var_, txt_):
        """打字、不按 Enter。"""
        c_ = fws(w_, var_)[0]
        c_.delete(0, "end"); c_.insert(0, txt_); app.update()
        return c_

    def notes(w_):
        return w_.v_msg.get().split("；") if w_.v_msg.get() else []

    def fresh(**kw):
        app.spec_defaults.clear(); app.spec_defaults.update(sv.DEFAULT_SPEC); app.spec_defaults.update(kw)
    # ---------------------------------------------------------------- 設定檔裡不認得的檢視（"garbage"、空字串、"none"、數字、list）換回頻譜、不提示；
    # 認得的照用（以前不認得的兩個檢視都關：什麼都沒畫、情境分頁全藏起來，狀態列卻寫「已計算 1 條頻譜」）
    vw = {}
    for v_ in ("garbage", "", "none", 5, ["spectrum"], "spectrogram", "both"):
        fresh(view=v_)
        n0 = len(CB)
        w = sv.SpectrumWindow(app, [sa]); app.update()
        vw[repr(v_)] = (bool(w.v_show_spec.get()), bool(w.v_show_sg.get()), w.strip.tab_visible("spectrum"), w.strip.tab_visible("chmeas"),
                        len(w.lines) > 0, w.sg_image is not None, app.spec_defaults.get("view"), CB[n0:])
        w.destroy(); app.update()
    good = (True, False, True, True, True, False, "spectrum", [])
    want_vw = {repr(v_): good for v_ in ("garbage", "", "none", 5, ["spectrum"])}
    want_vw.update({"'spectrogram'": (False, True, False, False, False, True, "spectrogram", []),
                    "'both'": (True, True, True, True, True, True, "both", [])})
    bad_vw = {k_: v_ for k_, v_ in vw.items() if want_vw.get(k_) != v_}
    check(not bad_vw,
          f"設定檔裡不認得的檢視（garbage、空字串、none、5、list）開視窗時換回頻譜、不提示：頻譜檢視開著、頻譜與通道量測分頁看得到、有畫線，設定存回 spectrum"
          f"（以前兩個檢視都關：什麼都沒畫、情境分頁全藏起來，狀態列卻寫「已計算 1 條頻譜」）；spectrogram、both 照用（{bad_vw or '7 種都對'}）")
    # ---------------------------------------------------------------- RBW 是次正規數（5e-324、1e-320）：fs/RBW 溢位成 Inf → 說明列「不夠一段視窗（Inf 點）」，
    # 不怪衰減（Hann 不用衰減；以前 math.ceil(inf) 的 OverflowError 被當成「衰減 60 dB 太大，算不出視窗」）；時間解析度 5e-324（RBW Auto）的 RBW 寫 Inf
    fresh()
    w = sv.SpectrumWindow(app, [sa]); app.update()
    sub = {}
    for t_ in ("5e-324", "1e-320"):
        cb_ = enter(w, w.v_rbw, t_)
        nt_ = notes(w)
        sub[t_] = (cb_, any("不夠一段視窗（Inf 點）" in x_ for x_ in nt_), not any("衰減" in x_ for x_ in nt_),
                   not fws(w, w.v_rbw)[0].instate(["invalid"]))
    enter(w, w.v_rbw, "Auto")
    w.set_view("both"); app.update()
    cb_ = enter(w, w.v_tres, "5e-324")
    sub["時間解析度 5e-324"] = (cb_, "RBW Inf）" in w.v_msg.get(), "RBW inf" not in w.v_msg.get())
    enter(w, w.v_tres, "Auto")
    sub["改回 Auto"] = (bool(w.lines), "不夠一段視窗" not in w.v_msg.get(), "RBW 太大" not in w.v_msg.get())
    w.destroy(); app.update()
    want_sub = {"5e-324": ([], True, True, True), "1e-320": ([], True, True, True), "時間解析度 5e-324": ([], True, True), "改回 Auto": (True, True, True)}
    bad_sub = {k_: v_ for k_, v_ in sub.items() if want_sub.get(k_) != v_}
    check(not bad_sub and not CB,
          f"RBW 打 5e-324、1e-320（次正規數，欄位合格）：說明列「…不夠一段視窗（Inf 點）…」、不寫衰減（Hann 不用衰減；以前「衰減 60 dB 太大，算不出視窗」）；"
          f"時間解析度 5e-324（RBW Auto）的說明寫「RBW Inf」（以前 Python 的 inf）；改回 Auto 照畫（{bad_sub or '都對'}；回呼例外 {CB}）")
    # ---------------------------------------------------------------- 峰值欄位在重新計算以外改好：Num Peaks 0 按 Enter（錯誤狀態）→ 改打 3、不按 Enter → 縮放頻譜
    # （排一次重找峰值，用到欄位現在的字）→ 紅框清掉、說明列不再寫、狀態列換回錯誤之前的「已計算…」（以前說明列與狀態列還寫著舊的錯誤，要等下一個動作；
    # 換回的那句也不是「峰值搜尋：已套用」——峰值欄位還錯著時按 Enter 不把它記成改好後換回的那句）
    fresh(peaks=True)
    w = sv.SpectrumWindow(app, [sa]); app.update()
    s_pre = w.v_status.get()
    cb1 = enter(w, w.v_pk_num, "0")
    e1 = (cb1, w.v_status.get() == "峰值：" + fm("pk_num"), fm("pk_num") in notes(w), fws(w, w.v_pk_num)[0].instate(["invalid"]))
    c_ = type_only(w, w.v_pk_num, "3")
    ax = w._spec_axes[0]
    lo_, hi_ = ax.get_xlim()
    ax.set_xlim(lo_ * 0.5, hi_ * 0.5)                         # xlim_changed → 60 ms 後重找峰值（_update_peaks）
    t0_ = time.time()
    while w._peak_job is not None and time.time() - t0_ < 5:
        app.update(); time.sleep(0.02)
    app.update()
    ng = [len(w.peaks_tree.get_children(g_)) for g_ in w.peaks_tree.get_children()]
    e2 = (not c_.instate(["invalid"]), fm("pk_num") not in w.v_msg.get(), w.v_status.get() == s_pre, "pk_num" not in w._fld_errs, ng == [3])
    w.destroy(); app.update()
    check(e1 == ([], True, True, True) and e2 == (True, True, True, True, True) and s_pre.startswith("已計算") and not CB,
          f"峰值欄位在重新計算以外改好：Num Peaks 0 按 Enter → 錯誤狀態（狀態列「峰值：…」）；改打 3 不按 Enter、縮放頻譜重找峰值 → 紅框清掉、說明列不再寫、"
          f"狀態列換回錯誤之前的「已計算…」（不是「峰值搜尋：已套用」）、找到 3 個峰（以前說明列與狀態列還寫著舊的錯誤，要等下一個動作）"
          f"（{e1}、{e2}、{s_pre[:12]!r}；回呼例外 {CB}）")
    # ---------------------------------------------------------------- 灰掉的欄位不在每次重新計算時重新宣告：視窗長度 2（視窗長度模式）→ 切 RBW 模式（灰掉、
    # 還是錯誤狀態）→ 重疊打 100 → 狀態列是重疊的錯誤（最後打錯的）；按「重新計算」也一樣（不會每次都換回「頻率解析度：…」）
    fresh()
    w = sv.SpectrumWindow(app, [sa]); app.update()
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    enter(w, w.v_wlen, "2")
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    dc = [w.v_status.get() == "頻率解析度：" + fm("wlen")]
    enter(w, w.v_overlap, "100")
    dc.append(w.v_status.get() == "視窗選項：" + fm("overlap"))
    w.compute(); app.update()
    dc.append(w.v_status.get() == "視窗選項：" + fm("overlap"))
    w.btn_view_sg.invoke(); app.update()                        # 別的重新計算（開關）也一樣
    dc.append(w.v_status.get() == "視窗選項：" + fm("overlap"))
    w.btn_view_sg.invoke(); app.update()
    dc.append("wlen" in w._fld_errs and "overlap" in w._fld_errs)
    enter(w, w.v_overlap, "0")
    dc.append(w.v_status.get() == "頻率解析度：" + fm("wlen"))   # 改好重疊：換成還錯著的視窗長度
    w.v_res_label.set("視窗長度"); w._on_res(); app.update()
    enter(w, w.v_wlen, "1024")
    w.v_res_label.set("RBW"); w._on_res(); app.update()
    dc.append(w.v_status.get().startswith("已計算"))
    check(dc == [True] * 7 and not CB,
          f"灰掉的欄位（RBW 模式的視窗長度 2）還是錯誤狀態、不在每次重新計算時重新宣告：之後打錯重疊 → 狀態列「視窗選項：…」，按「重新計算」、開關頻譜圖也還是"
          f"（不會每次換回「頻率解析度：…」）；改好重疊 → 換成還錯著的視窗長度；都改好 → 已計算（{dc}；回呼例外 {CB}）")
    # ---------------------------------------------------------------- 重疊的箭頭從欄位現在的字起算：打 0.03k 不重新計算 → ▲ → 31 並重算（不是從上一次合格的 0 起算）
    sp_ov = next(c_ for c_ in fws(w, w.v_overlap) if c_.winfo_class() == "TSpinbox")
    type_only(w, w.v_overlap, "0.03k")
    sp_ov.event_generate("<<Increment>>"); app.update()
    ov = (w.v_overlap.get(), w._last_p["overlap"], app.spec_defaults.get("overlap"))
    type_only(w, w.v_overlap, "250m")                          # 0.25 → 1.25
    sp_ov.event_generate("<<Increment>>"); app.update()
    ov2 = (w.v_overlap.get(), w._last_p["overlap"])
    enter(w, w.v_overlap, "0")
    check(ov == ("31", 31.0, "31") and ov2 == ("1.25", 1.25),
          f"重疊的箭頭從欄位現在的字起算：打 0.03k（30%）不重新計算、按 ▲ → 31 並重算、存進設定；250m ▲ 1.25（不是從上一次合格的值起算）（{ov}、{ov2}）")
    # ---------------------------------------------------------------- 狀態列記下最新的「已計算…」：失真的諧波數量打 0（錯誤狀態，狀態列「失真：…」）→ 主圖縮小範圍後
    # 重新計算（「已計算…」的分析範圍變了，狀態列照舊寫錯誤）→ 諧波數量改好（不重新計算頻譜）→ 狀態列換回最新的那句（不是錯誤之前那次的範圍）
    s_old = w.v_status.get()
    cbn = enter(w, w.v_dist_nharm, "0")
    k1 = w.v_status.get().startswith("失真：")
    ax_m = app.render_info["axes"][app.render_info["panels"].index(sa.panel)]
    xl0 = ax_m.get_xlim()
    ax_m.set_xlim(xl0[0], xl0[0] + (xl0[1] - xl0[0]) / 2); app.update()
    w.compute(); app.update()
    k2 = w.v_status.get().startswith("失真：")
    cbn += enter(w, w.v_dist_nharm, "6")
    s_new = w.v_status.get()
    ax_m.set_xlim(*xl0); app.update()
    w.compute(); app.update()
    check(k1 and k2 and s_new.startswith("已計算") and s_new != s_old and not cbn,
          f"還有欄位錯著時重新計算，狀態列寫錯誤、把這次的「已計算…」記成改好後換回的那句：諧波數量 0 → 主圖縮小範圍後重新計算 → 改回 6 → 狀態列是新範圍的"
          f"「已計算…」（不是錯誤之前那次的範圍）（{k1}、{k2}、{s_old[-60:]!r} → {s_new[-60:]!r}；{cbn}）")
    # ---------------------------------------------------------------- 同一欄換了另一個錯字、由別的動作重新計算：重疊 100 按 Enter、頻率偏移 x 按 Enter（狀態列「頻寬：…」）
    # → 重疊改打 200（不按 Enter）→ 按「重新計算」→ 狀態列換成重疊的錯誤（又打錯一次＝新的一次錯誤）
    enter(w, w.v_overlap, "100"); enter(w, w.v_foffset, "x")
    se1 = w.v_status.get() == "頻寬：" + fm("foffset")
    type_only(w, w.v_overlap, "200")
    w.compute(); app.update()
    se2 = w.v_status.get() == "視窗選項：" + fm("overlap")
    w.compute(); app.update()                                   # 同一個字再重新計算一次：不再重寫（狀態列照舊）
    se3 = w.v_status.get() == "視窗選項：" + fm("overlap")
    enter(w, w.v_foffset, "0"); enter(w, w.v_overlap, "0")
    check(se1 and se2 and se3 and w.v_status.get().startswith("已計算"),
          f"同一欄又打錯另一個字（重疊 100 → 200）、由「重新計算」觸發：狀態列換成重疊的錯誤（不停在頻率偏移的錯誤）（{se1}、{se2}、{se3}）")
    w.destroy(); app.update()
    # ---------------------------------------------------------------- 設定檔裡不合格的第二批欄位（abc）開視窗時換回預設值、不提示（使用者決定；和第三批的欄位一樣）：
    # 欄位是預設值、沒有紅框、說明列與狀態列不寫錯誤
    dflt = {"foffset": "0", "rbw": "Auto", "wlen": "1024", "nfft": "Auto", "atten": "60", "overlap": "0", "tres": "Auto", "tspan": "Auto",
            "rload": "1", "fullscale": "Auto", "clim": "-80, 20"}
    ld = {}
    for key_, d_ in dflt.items():
        fresh(view="both", **{key_: "abc"})
        n0 = len(CB)
        w2 = sv.SpectrumWindow(app, [sa]); app.update()
        var_ = getattr(w2, "v_" + key_)
        red_ = any(c_.instate(["invalid"]) for c_ in fws(w2, var_))
        ld[key_] = (var_.get(), red_, key_ in w2._fld_errs, w2.v_status.get().startswith("已計算"), w2.v_msg.get() == "", CB[n0:])
        w2.destroy(); app.update()
    bad_ld = {k_: v_ for k_, v_ in ld.items() if v_ != (dflt[k_], False, False, True, True, [])}
    check(not bad_ld,
          f"設定檔裡不合格的第二批欄位（頻寬的偏移、RBW、視窗長度、FFT 長度、衰減、重疊、時間解析度、時間跨度、參考負載、滿刻度、色彩範圍各打 abc）開視窗時"
          f"換回預設值：欄位是預設值、沒有紅框、說明列與狀態列不寫錯誤（{bad_ld or '11 個都對'}）")
    # ---------------------------------------------------------------- 頻譜圖剛好在上限（段數 × FFT 長度＝上限，含）照畫、多 1 格不畫：把上限暫時改成這次的格數
    # （真的 2^26 格要多吃 8 GB 以上；比的是 > 還是 ≥），視窗長度 1024、FFT 長度 Auto（1024）、重疊 0
    fresh(view="both", res_method="window-length", wlen="1024")
    w = sv.SpectrumWindow(app, [sa]); app.update()
    xl_ = app.panel_xlim(sa.panel)
    npts = len(sa.slice_range(*xl_)[0]) if xl_ else n
    nseg, nfft_ = npts // 1024, 1024
    cells = nseg * nfft_
    sg = {}
    for cap_, nm_ in ((cells, "剛好"), (cells - 1, "少 1 格"), (cells + 1, "多 1 格")):
        sv.SPEC_MAX_SG_CELLS = cap_
        w.compute(); app.update()
        sg[nm_] = (w.sg_image is not None, any("太大，沒有畫" in x_ for x_ in notes(w)))
    sv.SPEC_MAX_SG_CELLS = 1 << 26
    w.compute(); app.update()
    w.destroy(); app.update()
    check(sg == {"剛好": (True, False), "少 1 格": (False, True), "多 1 格": (True, False)} and nseg >= 2,
          f"頻譜圖的上限含等號：段數 × FFT 長度剛好等於上限（{nseg} 段 × {nfft_}＝{cells} 格）照畫、上限少 1 格就不畫並寫原因（使用者決定上限 2^26 格，"
          f"剛好 2^26 格照畫）（{sg}）")
    check(not CB, f"第九輪的情境沒有回呼例外（{CB}）")

# ---------------------------------------------------------------------------------------------------------------------------
# s35a～s35f：2026-10-24 使用者回報的六個問題（每次更新後又出現，所以每一個都有自己的步驤，修正前會失敗）：
# 1 啟動預設平移模式（資料提示關；開了才存進 view.tips）；2 「訊號屬性」面板啟動一律隱藏（新開、還原存檔兩條路）；
# 3 AM/PM 與 FM 合成一個「AM/PM/FM 分析…」視窗（一顆按鈕、一個清單項目、一個動作；舊 id analysis.fm 的快速鍵照樣有效）；
# 4 星座圖「顯示符號」全部／最後 N／前 N：N 在「全部」時變灰，「重新計算」用主圖目前的 x 範圍、標題的符號數跟著變；
# 5 三種拖放來源（檔案、資料夾面板、I/Q 視窗的線）：放在某張圖＝加進那張、最後一張圖下面的空白＝新增 panel，狀態列「放開以加到 P1」／「放開以新增 P3」；
# 6 圖上線條右鍵「刪除這條訊號（名稱）」（可復原；平移模式裡線上右鍵也拿得到）。
_S35: dict = {}          # 各步驟共用：開始前的設定（cfg0）、獨立行程探測的結果、模擬的舊存檔


def _s35_cfg0():
    return _S35.setdefault("cfg0", app.dump_settings())


def _s35_mode_off():
    tb = app.plot_toolbar
    (tb.set_mode("") if hasattr(tb, "set_mode") else tb.clear_mode())     # 修正前的程式沒有 set_mode：步驟仍要跑到自己的檢查


def _s35_setup():
    """I/Q（iq.csv）在 P1、CLK 在 P2，全部顯示、畫布捲到最上面；回傳 (si, sq, clk)。"""
    _s35_cfg0()
    _s35_mode_off()
    app.clear_all(); app.rescan(quiet=True); app.update()
    app.add_csv_columns_direct(os.path.join(ROOT, "iq.csv"), None)
    app.add_text_signal(os.path.join(ROOT, "digital", "clk.txt"))
    app.refresh_list(); app.plot(); app.show_all_x(); app.plot_scroll.yview_moveto(0); app.update()
    si = app.find_signal("iq.csv;;adc i"); sq = app.find_signal("iq.csv;;adc q"); clk = app.find_signal("digital/clk.txt")
    check(si is not None and sq is not None and clk is not None and si.panel == sq.panel == 1 and clk.panel == 2,
          f"準備：I/Q 在 P1、CLK 在 P2（{[(s_.key, s_.panel) for s_ in app.signals]}）")
    return si, sq, clk


def _s35_restore():
    _s35_mode_off()
    app.clear_all(); app.update()
    app.apply_settings(_s35_cfg0(), quiet=True); app.update()   # 回到 s35 開始前的訊號與設定


def _s35_probes():
    """新開程式（沒有設定檔）與還原存檔，各在獨立行程裡開一次 DSV（安靜模式），記下工具列模式、資料提示、訊號屬性／量測是否隱藏、
    量測面板在哪一欄、看得到的欄與左欄寬；再按「量測」記下面板與圖的位置。只跑一次。"""
    if "fresh" in _S35:
        return
    import json
    import subprocess
    import matplotlib
    cfg0 = _s35_cfg0()
    probe = os.path.join(OUT, "probe35.py")
    with open(probe, "w", encoding="utf-8") as f:
        f.write("import sys, json, os\nsys.path.insert(0, sys.argv[1])\nimport tests_common; tests_common.install_quiet()\n"
                "import signal_viewer as sv\nsv.AUTOSAVE_PATH = sys.argv[2]\nsv.LOG_PATH = os.path.join(os.path.dirname(sys.argv[2]), 'log.txt')\n"
                "sv.frozen_data_dir = (lambda: os.path.join(os.path.dirname(sys.argv[2]), 'frozen'))\n"   # 啟動時清凍結檔（U9）：只看測試目錄
                "app = sv.SignalViewer(root_dir=None, autorestore=True)\n"
                "import time\nd = app.dock\n"
                "for i in range(40):\n    app.update()\n    if i >= 12 and d._pending_sash is None:\n        break\n    time.sleep(0.05)\n"
                "out = {'mode': app.plot_toolbar.mode, 'tips': bool(app.v_tips.get()), 'props_hidden': 'props' in d.hidden,\n"
                "    'meas_hidden': 'meas' in d.hidden, 'v_props': bool(app.v_panel['props'].get()), 'v_meas': bool(app.v_panel['meas'].get()),\n"
                "    'nsig': len(app.signals), 'meas_col': d.column_of('meas'), 'vis': d.visible_columns(),\n"
                "    'h0': (int(d.h.sashpos(0)) if len(d.h.panes()) > 1 else None)}\n"
                "app.v_panel['meas'].set(True); app._toggle_panel('meas')\n"
                "for _ in range(4):\n    app.update()\n"
                "mp, pp = app.meas_panel, app.plot_panel\n"
                "out['press'] = {'shown': 'meas' not in d.hidden, 'col': d.column_of('meas'), 'mapped': bool(mp.winfo_ismapped()),\n"
                "    'meas_y': mp.winfo_rooty(), 'meas_x': mp.winfo_rootx(), 'meas_w': mp.winfo_width(), 'meas_h': mp.winfo_height(),\n"
                "    'plot_y': pp.winfo_rooty(), 'plot_x': pp.winfo_rootx(), 'plot_w': pp.winfo_width(), 'plot_h': pp.winfo_height(),\n"
                "    'col_h': d.cols['center'].winfo_height()}\n"
                "print('PROBE', json.dumps(out))\n"
                "app.destroy()\n")

    def run_probe(name, autosave_cfg):
        home = os.path.join(OUT, name)
        os.makedirs(home, exist_ok=True)
        auto = os.path.join(home, ".signal_viewer_last.json")
        if autosave_cfg is None:
            if os.path.exists(auto):
                os.remove(auto)
        else:
            with open(auto, "w", encoding="utf-8") as f:
                json.dump(autosave_cfg, f, ensure_ascii=False)
        env = _child_env(home)
        env.pop("DSV_TEST_ONLY", None)
        r = subprocess.run([sys.executable, probe, PROJECT, auto], env=env, capture_output=True, text=True, timeout=120)
        line = next((ln for ln in r.stdout.splitlines() if ln.startswith("PROBE ")), "")
        return (json.loads(line[6:]) if line else {}), (r.stderr or "")[-300:]

    legacy = dict(cfg0, root=ROOT, signals=[], annotations=[], datatips=[], layout_version=sv.LAYOUT_VERSION)
    legacy["layout"] = dict(cfg0["layout"], hidden=["cursors"])          # 使用者的實際存檔：訊號屬性、量測都存成「顯示」
    legacy["view"] = {k: v for k, v in cfg0["view"].items() if k != "tips"}   # 這次改動以前的存檔沒有 view.tips
    _S35["legacy"] = legacy
    _S35["fresh"] = run_probe("fresh35", None)
    _S35["rest"] = run_probe("restore35", legacy)
    _S35["rest2"] = run_probe("restore35b", dict(legacy, view=dict(legacy["view"], tips=True)))
    # 0.9.6 的存檔（使用者 2026-10-24 23:36 截圖的版面）：layout_version 2、量測在右欄而且開著、三欄都看得到、左欄寬 333
    lay96 = {"columns": {"left": ["folder", "sigs", "props"], "center": ["plot"], "right": ["meas", "cursors"]},
             "hidden": ["cursors"], "collapsed": [], "max": None,
             "sash": {"h_cols": ["left", "center", "right"], "h": [333, 1000], "left": [250, 500], "center": [], "right": []}}
    _S35["lay96"] = lay96
    _S35["rest96"] = run_probe("restore35c", dict(legacy, layout_version=2, layout=lay96))


@step
def s35a_default_pan_mode():
    """問題 1：啟動時圖工具列的預設模式是平移（不是資料提示）——新開程式、還原沒有 view.tips 的舊存檔都是；
    使用者自己開了資料提示才存進 view.tips、下次照開。"""
    _s35_probes()
    fresh, err = _S35["fresh"]
    rest, err2 = _S35["rest"]
    rest2, err3 = _S35["rest2"]
    legacy = _S35["legacy"]
    check(fresh.get("mode") == "pan/zoom" and fresh.get("tips") is False,
          f"新開程式（沒有設定檔）：工具列預設平移、資料提示關（{fresh} {err}）")
    check(rest.get("mode") == "pan/zoom" and rest.get("tips") is False,
          f"還原舊存檔（沒有 view.tips）：平移模式、資料提示關（{rest} {err2}）")
    check(rest2.get("mode") == "" and rest2.get("tips") is True,
          f"存檔 view.tips=True（使用者開過資料提示）→ 還原成資料提示模式（{rest2} {err3}）")
    if app.v_tips.get():                                       # 前面的步驟可能開著資料提示：沒有 view.tips 的存檔不會動它（只有啟動時才是預設關）
        app.v_tips.set(False); app._on_tips_toggle()
    app.plot_toolbar.set_mode("zoom")
    app.apply_settings(legacy, quiet=True); app.update()      # 同一個行程裡再走一次 apply_settings（啟動還原走的就是它）
    check(app.plot_toolbar.mode == "pan/zoom" and app.plot_toolbar.v_pan.get() and not app.plot_toolbar.v_zoom.get() and not app.ia.tips_enabled,
          "apply_settings（舊存檔，沒有 view.tips；本來是放大模式）→ 平移模式、工具列的平移鈕亮著、資料提示關")
    app.v_tips.set(True); app._on_tips_toggle()
    check(app.dump_settings()["view"]["tips"] is True and app.plot_toolbar.mode == "" and app.ia.tips_enabled,
          "按開資料提示 → view.tips=True 存進設定檔、平移模式關")
    app.apply_settings(dict(legacy, view=dict(legacy["view"], tips=True)), quiet=True); app.update()
    check(app.v_tips.get() and app.ia.tips_enabled and app.plot_toolbar.mode == "", "apply_settings view.tips=True → 資料提示模式")
    app.v_tips.set(False); app._on_tips_toggle()
    check(not app.ia.tips_enabled and app.plot_toolbar.mode == "", "按掉資料提示 → 點線＝選取（不自動切回平移；平移只是啟動時的預設）")
    app._apply_tips_mode()
    check(app.plot_toolbar.mode == "pan/zoom", "_apply_tips_mode（啟動／還原走的）→ 平移")
    app.plot_toolbar.set_mode("")


@step
def s35b_props_hidden_on_start():
    """問題 2：「訊號屬性」面板啟動一律隱藏——新開程式、還原把它存成「顯示」的存檔（使用者的實際存檔）、舊版面（layout_version 1）三條路；
    其他面板照存檔（量測面板 2026-10-25 起也一律隱藏，見 s35g）。根本原因：按「參數…」之後版面存檔記成顯示，每次啟動都跟著回來。"""
    _s35_probes()
    fresh, err = _S35["fresh"]
    rest, err2 = _S35["rest"]
    legacy = _S35["legacy"]
    check(fresh.get("props_hidden") is True and fresh.get("v_props") is False, f"新開程式（沒有設定檔）：「訊號屬性」隱藏（{fresh} {err}）")
    check(rest.get("props_hidden") is True and rest.get("v_props") is False,
          f"還原存成「訊號屬性顯示」的存檔：仍隱藏、檢視分頁的勾選同步（{rest} {err2}）")
    app.apply_settings(dict(legacy, layout=dict(legacy["layout"], hidden=[])), quiet=True); app.update()
    check("props" in app.dock.hidden and not app.v_panel["props"].get() and "cursors" not in app.dock.hidden,
          "apply_settings（同樣的存檔、游標量測也存成顯示）：訊號屬性隱藏、游標量測照存檔顯示")
    app.apply_settings(dict(legacy, layout_version=1), quiet=True); app.update()
    check(app.dock.hidden == {"props", "meas", "cursors"}, "layout_version 1 的存檔 → 預設版面（訊號屬性隱藏）")
    d_ = sv.SignalViewer._layout_for_restore({"hidden": [], "before_max": {"hidden": ["cursors"]}})
    check(d_["hidden"] == ["meas", "props"] and d_["before_max"]["hidden"] == ["cursors", "meas", "props"],
          f"_layout_for_restore：hidden 與 before_max.hidden 都補上 props（和 meas）（{d_}）")
    app.v_panel["props"].set(True); app._toggle_panel("props"); app.update()
    check("props" not in app.dock.hidden and "props" not in app.dump_settings()["layout"]["hidden"]
          and "props" in sv.SignalViewer._layout_for_restore(app.dump_settings()["layout"])["hidden"],
          "這次工作階段裡叫出訊號屬性 → 顯示（存檔也記成顯示）；但還原存檔時一律隱藏")
    app.v_panel["props"].set(False); app._toggle_panel("props"); app.update()


@step
def s35c_iq_window_merged():
    """問題 3：「AM/PM 分析…」「FM 分析…」合成一個「AM/PM/FM 分析…」視窗——一顆按鈕、一個清單項目、一個動作（analysis.ampm；
    舊 id analysis.fm 的快速鍵經別名照樣有效）；視窗裡勾 AM／PM／FM，勾選記進設定、下次沿用。"""
    from types import SimpleNamespace as NS
    si, sq, _clk = _s35_setup()
    ab = app._analyze_btns
    check("fm" not in ab and "analysis.fm" not in app.actions and app.actions["analysis.ampm"].label == "AM/PM/FM 分析…",
          "只剩一個動作 analysis.ampm「AM/PM/FM 分析…」（analysis.fm 併掉）")
    km_bak = app.keymap.to_dict()
    app.keymap.from_dict({"version": 1, "platform": sv.dsv_keys.PLATFORM, "shortcuts": {"analysis.fm": ["F9"]}}); app._apply_keymap()
    check(app.keymap.bindings("analysis.ampm") == ("F9",) and app.keymap.lookup("F9") == ["analysis.ampm"],
          "舊設定檔綁在 analysis.fm 的快速鍵 → 經別名套到 analysis.ampm")
    app.keymap.from_dict(km_bak); app._apply_keymap()
    menus.clear()
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    app._on_list_context(NS(x=2, y=2, x_root=10, y_root=10))
    lab = menus[-1] if menus else []
    check(sum(1 for x in lab if x.startswith("AM/PM/FM 分析")) == 1 and not any(x.startswith(("FM 分析", "AM/PM 分析")) for x in lab)
          and "AM/PM/FM 分析（選取的兩條）…" in lab,
          f"清單右鍵只有一個「AM/PM/FM 分析（對象）…」，清單自己選了兩條一般訊號時字樣正好是「AM/PM/FM 分析（選取的兩條）…」（0.9.13 D11）（{lab[-8:]}）")
    app.iq_defaults.pop("kinds", None)
    w = app.open_iq_window(); app.update()
    check(w is not None and w.title().startswith("AM/PM/FM 分析") and w.kinds() == ["am", "pm", "fm"] and len(w.fig.axes) == 3
          and "AM/PM/FM 分析" in app.status_var.get(),
          f"按「AM/PM/FM 分析…」→ 一個視窗、預設三項全勾（{w.title() if w else None}；{app.status_var.get()[:30]}）")
    w.v_kind["fm"].set(False); w.compute(); app.update()
    check(w.kinds() == ["am", "pm"] and app.iq_defaults["kinds"] == ["am", "pm"] and len(w.fig.axes) == 2, "取消 FM → 兩張子圖、勾選記進設定（iq.kinds）")
    w.v_kind["am"].set(False); w.v_kind["pm"].set(False); w.v_kind["fm"].set(True); w.compute(); app.update()
    check(w.kinds() == ["fm"] and len(w._series) == 1 and w._series[0]["kind"] == "iq_fm" and np.isnan(w._series[0]["y"][0]),
          "只勾 FM → 一張 FM 子圖（舊「FM 分析…」視窗的功能都在）")
    w.destroy(); app.update()
    w = app.open_iq_window(); app.update()
    check(w is not None and w.kinds() == ["fm"], "再開 → 沿用上次勾的（FM）")
    w.destroy(); app.update()
    app.iq_defaults["kinds"] = ["am", "pm", "fm"]


@step
def s35d_constellation_symbols():
    """問題 4：星座圖「顯示符號」旁的數字 N 與「重新計算」看不出效果——N 只在「最後 N 個」「前 N 個」有用（「全部」時變灰）；
    新增「前 N 個」；「重新計算」用主圖目前的 x 範圍重畫、標題的符號數跟著變。"""
    si, sq, _clk = _s35_setup()
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.show_all_x(); app.update()
    app.const_defaults.update({"symbols": "all", "nsym": 256, "offset": 0, "sps": "", "ref": "none", "sync": False, "xrange": True})
    cw = app.open_constellation(); app.update()
    di, dq = si.get_data(), sq.get_data()
    n = min(len(di), len(dq))
    idx_all = sv.constellation_indices(n, 64, 0)
    check(isinstance(cw, sv.ConstellationWindow) and cw._symbols_mode() == "all" and cw.sp_nsym.instate(["disabled"]) and cw.result["points"] == len(idx_all),
          f"星座圖預設「全部」：N 的數字格是灰的（用不到）、{cw.result['points']} 點")
    cw.v_nsym.set("16"); cw.compute(); app.update()
    check(cw.result["points"] == len(idx_all) and cw.sp_nsym.instate(["disabled"]), "「全部」時改 N 再按「重新計算」→ 點數不變（N 用不到，所以要變灰）")
    cw.v_symbols_label.set("最後 N 個"); cw.compute(); app.update()
    t_ = cw.fig.axes[0].get_title()
    check(cw.result["points"] == 16 and not cw.sp_nsym.instate(["disabled"]) and np.isclose(cw.lines[1].get_xdata()[-1], di[idx_all[-1]])
          and "16 個符號" in t_ and app.const_defaults["symbols"] == "last",
          f"最後 N 個（N=16）→ 16 點、N 可改、標題寫 16 個符號（{t_}）")
    cw.v_symbols_label.set("前 N 個"); cw.v_nsym.set("10"); cw.compute(); app.update()
    xd = cw.lines[1].get_xdata()
    check(cw.result["points"] == 10 and np.isclose(xd[0], di[idx_all[0]]) and np.isclose(xd[-1], di[idx_all[9]])
          and app.const_defaults["symbols"] == "first" and "10 個符號" in cw.fig.axes[0].get_title(),
          "前 N 個（N=10）→ 前 10 個符號、設定 symbols=first、標題 10 個符號")
    cw.v_symbols_label.set("全部"); cw.compute(); app.update()
    for ax_ in app.render_info["axes"]:
        ax_.set_xlim(10.0, 40.0)                      # 主圖縮到 x 10..40 symbol（像滾輪／平移後）
    app.canvas.draw(); app.update()
    i0, i1 = si.index_range(10.0, 40.0)
    idx_rng = sv.constellation_indices(n, 64, 0, i0, i1)
    cw.compute(); app.update()
    check(cw.result["points"] == len(idx_rng) and 0 < len(idx_rng) < len(idx_all) and f"{len(idx_rng):,} 個符號" in cw.fig.axes[0].get_title()
          and "x 10..40" in cw.v_status.get(),
          f"主圖縮到 x 10..40 → 「重新計算」只用這段、標題的符號數跟著變（{cw.result['points']} 點；{cw.v_status.get()[:40]}）")
    cw.destroy(); app.show_all_x(); app.update()


@step
def s35e_drop_targets():
    """問題 5：拖訊號進圖永遠落在同一個 panel——三種來源（Finder 拖檔案、資料夾面板拖檔案、I/Q 視窗拖線）同一套落點判定：
    放在某張圖＝加進那張（框起來、「放開以加到 Pn」）、最後一張圖下面的空白＝新增 panel（虛線框、「放開以新增 Pn」）、圖以外＝新 panel（檔案）／取消（其他）。"""
    from types import SimpleNamespace as NS
    import tests_common
    si, sq, _clk = _s35_setup()
    cw_ = app.canvas.get_tk_widget()
    H_ = float(app.fig.bbox.height)

    def center_of(p):                                 # TkAgg：Tk 畫布像素＝matplotlib 像素（W10；Mac 的 dpr 是 1，和以前一樣）
        info = app.render_info
        axp = info["axes"][info["panels"].index(p)]
        return cw_.winfo_rootx() + (axp.bbox.x0 + axp.bbox.x1) / 2, cw_.winfo_rooty() + (H_ - (axp.bbox.y0 + axp.bbox.y1) / 2)

    rx1, ry1 = center_of(1)
    rx2, ry2 = center_of(2)
    # 最下面那張的 x 刻度數字與 x 軸標籤算那張（第三輪審查 F14）；再下面＝畫布最下面多留的「新增 panel」拖放區（DROP_STRIP_IN）
    def _ry_new():
        """「新增 panel」區（畫布最下面的拖放區）裡的一點（螢幕 y）：每次用的時候照當時的位置算（開別的視窗、狀態列換字時主視窗的元件會挪幾個像素）。"""
        return cw_.winfo_rooty() + (float(app.fig.bbox.height) - app._drop_new_y(app.render_info["axes"])) + 6

    ry_new = _ry_new()
    sc_bottom = app.plot_scroll.winfo_rooty() + app.plot_scroll.winfo_height()
    check(ry_new < sc_bottom - 5, f"最後一張圖（P2）下面有空白可以放（{ry_new:.0f} < {sc_bottom}）")
    check(app.drop_target(int(rx1), int(ry1)) == ("panel", 1) and app.drop_target(int(rx2), int(ry2)) == ("panel", 2)
          and app.drop_target(int(rx2), int(ry_new)) == ("new", 3) and app.drop_target(5, 5) == ("out", None)
          and app.drop_target_at(int(rx2), int(ry_new)) is None and app.drop_target_at(int(rx2), int(ry2)) == 2,
          "落點判定：P1 上＝P1、P2 上＝P2、最後一張圖下面的空白＝新增 P3、圖以外＝out")
    # 5a 外部檔案拖放（有 tkdnd 用原生 tests/fakednd.m，否則直接呼叫處理函式）
    ext = os.path.join(OUT, "dnd35")
    os.makedirs(ext, exist_ok=True)
    pa = os.path.join(ext, "a.txt")
    with open(pa, "w") as f:
        f.write("\n".join(str(v) for v in (np.arange(300) % 7)) + "\n")
    L = tests_common.fake_dnd_lib(OUT)
    native = L is not None and app.dnd_available and not HL

    def drop(rx, ry, paths, leave=False, settle=0.15):
        if native:
            return tests_common.native_drop(app, rx, ry, paths, leave=leave, settle=settle)
        ev = NS(data=app.tk.call("list", *paths), x_root=int(rx), y_root=int(ry), action="copy")
        app._on_drop_over(ev)
        if leave == "hover":
            pass
        elif leave:
            app._on_drop_leave(ev)
        else:
            app._on_drop(ev)
        t0 = time.time()
        while time.time() - t0 < settle:
            app.update(); time.sleep(0.01)
        return [1, 1, 1, 1], ""

    print(f"（s35 拖放：{'原生 tkdnd（tests/fakednd.m）' if native else '直接呼叫處理函式'}）")
    st0 = app.status_var.get()
    drop(rx2, _ry_new(), [pa], leave="hover", settle=0.0)
    hint = cw_.find_withtag("dsv_drop_hint")
    st_hover = app.status_var.get()
    hint_new_ok = bool(hint) and cw_.coords(hint[0])[1] < (_ry_new() - cw_.winfo_rooty()) < cw_.coords(hint[0])[3]
    drop(rx2, _ry_new(), [pa], leave=True, settle=0.3)
    check(HL or (st_hover.startswith("放開以新增 P3") and hint_new_ok and not cw_.find_withtag("dsv_drop_hint") and app.status_var.get() == st0),
          f"檔案拖到最後一張圖下面的空白：狀態列「放開以新增 P3」、空白框起來；離開後恢復（{st_hover[:30]}；hint {hint_new_ok}）")
    drop(rx1, ry1, [pa], leave="hover", settle=0.0)
    st_hover = app.status_var.get()
    drop(rx1, ry1, [pa], leave=True, settle=0.3)
    check(HL or st_hover.startswith("放開以加到 P1"), f"檔案拖到 P1 上：狀態列「放開以加到 P1」（{st_hover[:30]}）")
    n0 = len(app.signals)
    drop(rx2, _ry_new(), [pa])
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == 3 and "到 P3" in app.status_var.get(),
          f"檔案放在空白 → 新增 P3（{[(x.key, x.panel) for x in added]}；{app.status_var.get()[:40]}）")
    app.undo_action(); app.update()
    n0 = len(app.signals)
    drop(rx2, ry2, [pa])
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == 2, f"檔案放在 P2 上 → 加進 P2（{[(x.key, x.panel) for x in added]}）")
    app.undo_action(); app.update()
    # 5b 從資料夾面板拖到圖上
    app.expand_tree(True); app.update()
    iid = next((i for i, nd in app.tree_map.items() if nd.get("kind") == "text" and str(nd.get("path", "")).endswith("data.txt")), None)
    check(iid is not None, "資料夾面板裡有 digital/data.txt")
    app.file_tree.see(iid); app.update()
    bb = app.file_tree.bbox(iid)
    tx, ty = app.file_tree.winfo_rootx(), app.file_tree.winfo_rooty()
    ex, ey = (bb[0] + 5, bb[1] + bb[3] // 2) if bb else (20, 40)
    app.file_tree.selection_set([])

    def tree_press_and_move(rx, ry):
        app._cf_drag_press(NS(x=ex, y=ey, x_root=tx + ex, y_root=ty + ey))
        app._cf_drag_motion(NS(x=ex, y=ey, x_root=int(rx), y_root=int(ry)))
        app.update()

    tree_press_and_move(rx2, ry2)
    d_ = app._cf_drag
    check(d_ is not None and d_["out"] and d_["target"] == ("panel", 2) and app.status_var.get().startswith("放開以加到 P2") and bool(cw_.find_withtag("dsv_drop_hint")),
          f"從資料夾面板拖 data.txt 到 P2 上：帶著走、P2 框起來、狀態列「放開以加到 P2」（{app.status_var.get()[:30]}）")
    n0 = len(app.signals)
    app._cf_drag_release(NS(x_root=int(rx2), y_root=int(ry2))); app.update()
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == 2 and added[0].key == "digital/data.txt" and app.sig_tree.selection() == (f"s{added[0].uid}",)
          and "到 P2" in app.status_var.get() and not cw_.find_withtag("dsv_drop_hint"),
          f"放開 → data.txt 加進 P2、選取、框消失（{app.status_var.get()[:40]}）")
    app.undo_action(); app.update()
    check(app.find_signal("digital/data.txt") is None, "Ctrl+Z 復原資料夾面板的拖曳加入")
    n0 = len(app.signals)
    tree_press_and_move(rx2, _ry_new())
    check(app._cf_drag is not None and app._cf_drag["target"] == ("new", 3) and app.status_var.get().startswith("放開以新增 P3"),
          f"拖到最後一張圖下面的空白：「放開以新增 P3」（{app.status_var.get()[:30]}）")
    app._cf_drag_release(NS(x_root=int(rx2), y_root=int(_ry_new()))); app.update()
    added = app.signals[n0:]
    check(len(added) == 1 and added[0].panel == 3 and "到 P3" in app.status_var.get(), f"放開 → 新增 P3（{[(x.key, x.panel) for x in added]}）")
    app.undo_action(); app.update()
    n0 = len(app.signals)
    tree_press_and_move(rx2, ry2)
    app._cf_drag_motion(NS(x=ex, y=ey, x_root=tx + 10, y_root=ty + 10)); app.update()
    app._cf_drag_release(NS(x_root=tx + 10, y_root=ty + 10)); app.update()
    check(len(app.signals) == n0 and "取消" in app.status_var.get() and not cw_.find_withtag("dsv_drop_hint"),
          f"拖出去又放回面板上（圖以外）→ 取消、不加（{app.status_var.get()[:30]}）")
    # 5c I/Q 視窗的線拖到最後一張圖下面的空白 → 新增 panel（拖到某張圖上＝貼進那張，s27 測過）
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    w = app.open_iq_window("ampm"); app.update()
    wd = w.canvas.get_tk_widget(); w.update()
    ln = w.lines[1]; axl = ln.axes
    xd_, yd_ = ln.get_xdata(), ln.get_ydata(); ii = len(xd_) // 2
    pxx, pyy = axl.transData.transform((xd_[ii], yd_[ii])); hh = w.canvas.get_width_height(physical=True)[1]
    xx, yy = int(round(pxx)), int(round(hh - pyy))
    w._drag_out_press(NS(x=xx, y=yy, x_root=wd.winfo_rootx() + xx, y_root=wd.winfo_rooty() + yy))
    w._drag_out_motion(NS(x=-40, y=yy, x_root=wd.winfo_rootx() - 40, y_root=wd.winfo_rooty() + yy))
    w._drag_out_motion(NS(x=0, y=0, x_root=int(rx2), y_root=int(_ry_new())))
    check(w._drag_src is not None and w._drag_src["out"] and w._drag_src.get("target_kind") == "new"
          and app.status_var.get().startswith("放開以新增 P3") and bool(cw_.find_withtag("dsv_drop_hint")),
          f"I/Q 視窗的線拖到最後一張圖下面的空白：「放開以新增 P3」、空白框起來（{app.status_var.get()[:30]}）")
    w._drag_out_motion(NS(x=0, y=0, x_root=int(rx1), y_root=int(ry1)))
    check(w._drag_src["target"] == 1 and app.status_var.get().startswith("放開以加到 P1"), f"移到 P1 上 → 「放開以加到 P1」（{app.status_var.get()[:30]}）")
    w._drag_out_motion(NS(x=0, y=0, x_root=int(rx2), y_root=int(_ry_new())))
    n0 = len(app.signals)
    w._drag_out_release(NS(x=0, y=0, x_root=int(rx2), y_root=int(_ry_new()))); app.update()
    check(len(app.signals) == n0 + 1 and app.signals[-1].panel == 3 and app.signals[-1].derive == w._series[0]["kind"] and not cw_.find_withtag("dsv_drop_hint"),
          f"放開 → 新增 P3、貼成衍生訊號（{app.signals[-1].derive}, P{app.signals[-1].panel}）")
    app.undo_action(); app.update()
    w.destroy(); app.update()


@step
def s35f_line_context_delete():
    """問題 6：圖上線條右鍵有「刪除這條訊號（名稱）」——只移除那一條（沒被選到的衍生訊號不管在哪一張都留著，見 s37 的 U8）、Ctrl+Z 可復原；
    平移模式（啟動預設）裡線上右鍵也是訊號選單，空白處右鍵才是 MATLAB 的平移模式選單。"""
    from types import SimpleNamespace as NS
    from matplotlib.backend_bases import MouseEvent
    si, sq, _clk = _s35_setup()
    menus.clear(); menu_objs.clear()
    ax0 = app.render_info["axes"][0]
    app._context_for_hit(NS(kind="line", id=sq.uid, ax=ax0), NS(guiEvent=None, x=0, y=0))
    lab = menus[-1] if menus else []
    label = f"刪除這條訊號（{sq.name}）"
    check(label in lab and "刪除這個 panel" in lab and lab.index(label) < lab.index("刪除這個 panel"),
          f"線上右鍵有「{label}」（在「刪除這個 panel」前面）（{lab[-9:]}）")
    n0 = len(app.signals)
    ok_ = invoke_menu(menu_objs[-1], label) if menu_objs else False
    app.update()
    check(ok_ and len(app.signals) == n0 - 1 and app.find_signal("iq.csv;;adc q") is None and app.find_signal("iq.csv;;adc i") is not None
          and app.status_var.get().startswith("已移除 1 條訊號"),
          f"按下去 → 只有 adc q 被移除、adc i 留著、狀態列說可復原（{app.status_var.get()[:30]}）")
    app.undo_action(); app.update()
    check(len(app.signals) == n0 and app.find_signal("iq.csv;;adc q") is not None, "Ctrl+Z → 這條訊號回來")
    menus.clear()
    app._context_for_hit(NS(kind="empty", id=None, ax=ax0), NS(guiEvent=None, x=0, y=0))
    check(not any(x.startswith("刪除這條訊號") for x in (menus[-1] if menus else [])), "空白處右鍵沒有「刪除這條訊號」")
    # 平移模式（啟動預設）裡：線上右鍵＝訊號選單（有刪除這條訊號）、空白處右鍵＝平移模式選單（MATLAB）
    app.plot_toolbar.set_mode("pan"); app.canvas.draw(); app.update()
    sq2 = app.find_signal("iq.csv;;adc q")
    a_ = app.render_info["artists"][sq2.uid]
    axq, lnq = a_["ax"], a_["line"]
    xq, yq = lnq.get_xdata(), lnq.get_ydata()
    pxq, pyq = axq.transData.transform((xq[1500], yq[1500]))
    menus.clear()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, pxq, pyq, button=3))
    lab_line = menus[-1] if menus else []
    menus.clear()
    app.ia.on_press(MouseEvent("button_press_event", app.canvas, (axq.bbox.x0 + axq.bbox.x1) / 2, axq.bbox.y1 - 3, button=3))
    lab_empty = menus[-1] if menus else []
    check(any(x.startswith("刪除這條訊號（") for x in lab_line) and lab_empty[:1] == ["還原視圖"] and not any(x.startswith("刪除這條訊號") for x in lab_empty),
          f"平移模式：線上右鍵＝訊號選單（{lab_line[:2]}…）、空白處右鍵＝平移模式選單（{lab_empty[:2]}）")
    _s35_restore()

@step
def s35g_meas_panel_bottom():
    """問題 7（2026-10-24 23:36）：「量測」面板預設在圖的下方（中欄），預設不出現、按「量測」（或打開任何一組量測）才出現；
    每次啟動都隱藏——新開程式、還原把它存成「顯示」的存檔、0.9.6 的存檔（量測在右欄、開著）都一樣。
    0.9.6 的存檔：量測搬到圖的下方，其他照存的（右欄沒東西就不顯示、左欄寬不變）；使用者自己搬到別欄的位置照記。"""
    _s35_probes()
    d = app.dock
    fresh, err = _S35["fresh"]
    rest, err2 = _S35["rest"]
    r96, err3 = _S35["rest96"]

    def below(p_):
        return bool(p_ and p_.get("shown") and p_.get("col") == "center" and (HL or (
            p_.get("mapped") and p_["meas_y"] >= p_["plot_y"] + p_["plot_h"] - 2 and abs(p_["meas_x"] - p_["plot_x"]) <= 2
            and abs(p_["meas_w"] - p_["plot_w"]) <= 2 and p_["meas_h"] >= 60 and p_["plot_h"] >= 0.5 * p_["col_h"])))

    def geom():
        mp, pp = app.meas_panel, app.plot_panel
        return {"shown": "meas" not in d.hidden, "col": d.column_of("meas"), "mapped": bool(mp.winfo_ismapped()),
                "meas_y": mp.winfo_rooty(), "meas_x": mp.winfo_rootx(), "meas_w": mp.winfo_width(), "meas_h": mp.winfo_height(),
                "plot_y": pp.winfo_rooty(), "plot_x": pp.winfo_rootx(), "plot_w": pp.winfo_width(), "plot_h": pp.winfo_height(),
                "col_h": d.cols["center"].winfo_height()}

    # --- 三種啟動（獨立行程）---
    check(fresh.get("meas_hidden") is True and fresh.get("v_meas") is False and fresh.get("meas_col") == "center",
          f"新開程式：量測面板在中欄（圖的下方）、隱藏、量測鈕沒亮（{ {k: fresh.get(k) for k in ('meas_hidden', 'v_meas', 'meas_col')} } {err}）")
    check(below(fresh.get("press")), f"新開程式按「量測」→ 面板出現在圖的正下方、和圖同寬，圖仍佔一半以上（{fresh.get('press')}）")
    check(rest.get("meas_hidden") is True and rest.get("v_meas") is False,
          f"還原把量測存成「顯示」的存檔：仍隱藏（{ {k: rest.get(k) for k in ('meas_hidden', 'v_meas', 'meas_col')} } {err2}）")
    check(r96.get("meas_hidden") is True and r96.get("meas_col") == "center" and r96.get("vis") == ["left", "center"]
          and (HL or (r96.get("h0") is not None and abs(r96["h0"] - 333) <= 3)),
          f"還原 0.9.6 的存檔（量測在右欄、開著）：搬到圖的下方、隱藏；右欄沒東西不顯示、左欄寬照存的 333"
          f"（{ {k: r96.get(k) for k in ('meas_hidden', 'meas_col', 'vis', 'h0')} } {err3}）")
    check(below(r96.get("press")), f"0.9.6 的存檔還原後按「量測」→ 出現在圖的正下方（{r96.get('press')}）")
    # --- 同一個行程：量測鈕、量測組、存檔還原 ---
    app.set_dcursor_mode("none"); d.reset(); app.update()
    check(d.order["center"] == ["plot", "meas"] and "meas" in d.hidden and not app.v_panel["meas"].get() and d.visible_columns() == ["left", "center"],
          f"預設版面：量測在圖的下方、隱藏，右欄（游標量測）也隱藏（{d.order} {sorted(d.hidden)}）")
    btn = next((w for w in _walk(app.strip.tabs["measure"]) if isinstance(w, (sv.ttk.Button, sv.ttk.Checkbutton)) and str(w.cget("text")) == "量測"), None)
    check(btn is not None, "量測分頁有「量測」鈕")
    if btn is None:
        return
    btn.invoke(); app.update()
    g = geom()
    check(app.v_panel["meas"].get() and below(g) and d.visible_columns() == ["left", "center"],
          f"按「量測」→ 面板出現在圖的正下方（中欄），右欄不出現（{g}）")
    btn.invoke(); app.update()
    check("meas" in d.hidden and not app.v_panel["meas"].get()
          and (HL or abs(app.plot_panel.winfo_height() - d.cols["center"].winfo_height()) <= 4),
          f"再按一次 → 隱藏，圖回到整欄高（{app.plot_panel.winfo_height()} / {d.cols['center'].winfo_height()}）")
    g0 = app.v["meas_groups"].get()
    app.set_meas_group("stats", False); app.update()
    check("meas" in d.hidden, "關掉一組量測不會叫出面板")
    app._meas_btns["stats"].invoke(); app.update()
    check(app.v_meas_group["stats"].get() and below(geom()), f"面板隱藏時打開「訊號統計」→ 面板出現在圖的下方（{geom()}）")
    app.v["meas_groups"].set(g0); app._sync_meas_group_vars()
    # 存檔還原：這次工作階段開著 → 存檔記成顯示，但還原一律隱藏；量測組照存的
    cfg = app.dump_settings()
    check("meas" not in cfg["layout"]["hidden"] and cfg["layout_version"] == 3, "開著時存檔：版面記成顯示、layout_version 3")
    app.apply_settings(cfg, quiet=True); app.update()
    check("meas" in d.hidden and d.column_of("meas") == "center" and not app.v_panel["meas"].get() and app.v["meas_groups"].get() == cfg["view"]["meas_groups"],
          "還原同一份存檔 → 量測隱藏、還在圖的下方、量測組照存的")
    # 使用者自己搬到右欄：位置照記（只有顯示與否不記）
    d.move("meas", "right"); d.hide("meas", False); app.update()
    cfg_r = app.dump_settings()
    app.apply_settings(cfg_r, quiet=True); app.update()
    check(d.column_of("meas") == "right" and "meas" in d.hidden, "自己搬到右欄的存檔（layout_version 3）→ 還原後還在右欄、隱藏")
    # 「只看圖」式最大化的是量測面板 → 還原最大化前的版面
    d.reset(); app.update()
    d.hide("meas", False); d.maximize("meas"); app.update()
    cfg_m = app.dump_settings()
    app.apply_settings(cfg_m, quiet=True); app.update()
    check(d.max_key is None and "meas" in d.hidden and "plot" not in d.hidden and (HL or app.plot_panel.winfo_ismapped()),
          f"存檔時量測面板最大化 → 還原成最大化前的版面、量測隱藏、圖看得到（max={d.max_key} hidden={sorted(d.hidden)}）")
    # 0.9.6 的存檔在同一個行程裡套用：左欄寬照存的、量測搬到圖的下方
    W = d.h.winfo_width()
    lay96 = dict(_S35["lay96"], sash=dict(_S35["lay96"]["sash"], h=[333, max(700, W - 300)]))
    app.apply_settings(dict(app.dump_settings(), layout_version=2, layout=lay96), quiet=True)
    for _ in range(30):
        app.update()
        if d._pending_sash is None:
            break
        time.sleep(0.1)
    check(d.column_of("meas") == "center" and d.order["center"] == ["plot", "meas"] and "meas" in d.hidden and d.visible_columns() == ["left", "center"]
          and (HL or abs(d.h.sashpos(0) - 333) <= 3) and app._layout_applied,
          f"apply_settings（0.9.6 的存檔）：量測搬到圖的下方、隱藏，左欄寬照存的（{d.h.sashpos(0)}）")
    # 純函式：搬欄、分隔線、不改傳入的 dict
    L = sv.SignalViewer._layout_for_restore
    o2 = L(_S35["lay96"], 2)
    check(o2["columns"]["center"] == ["plot", "meas"] and o2["columns"]["right"] == ["cursors"] and "meas" in o2["hidden"]
          and o2["sash"]["h_cols"] == ["left", "center"] and o2["sash"]["h"] == [333] and o2["sash"]["left"] == [250, 500]
          and _S35["lay96"]["columns"]["right"] == ["meas", "cursors"] and _S35["lay96"]["sash"]["h"] == [333, 1000],
          f"_layout_for_restore(0.9.6 版面, 2)：量測搬到圖後面、右欄空了 → 只留左欄的分隔線；傳入的 dict 沒被改（{o2['columns']} {o2['sash']}）")
    o3 = L(_S35["lay96"], 3)
    check(o3["columns"]["right"] == ["meas", "cursors"] and o3["sash"]["h"] == [333], "layout_version 3：量測的欄照存的（只隱藏）")
    oc = L({"columns": {"left": ["props"], "center": ["plot"], "right": ["cursors"]}, "hidden": [],
            "sash": {"h_cols": ["left", "center", "right"], "h": [300, 900]}}, 3)
    check("h" not in oc["sash"] and "h_cols" not in oc["sash"], f"左欄整欄藏起來（對不上）→ 拿掉橫向分隔線、改用預設欄寬（{oc['sash']}）")
    om = L({"columns": {"left": ["folder"], "center": ["plot", "meas"], "right": []}, "hidden": ["folder", "plot"], "max": "meas",
            "before_max": {"columns": {"left": ["folder"], "center": ["plot", "meas"], "right": []}, "hidden": [], "max": None}}, 3)
    check(om.get("max") is None and "before_max" not in om and om["hidden"] == ["meas", "props"], f"最大化的是量測 → 改用最大化前的版面（{om}）")
    _s35_restore()
    d.reset(); app.update()


# ---------------------------------------------------------------------------------------------------------------------------
# s36a／s36b：2026-10-25 使用者回報的第 8、9 項（修正前會失敗）：
# 8 每個 panel 自己的 x／y 軸數值與單位、可以各自縮放——MATLAB Signal Analyzer 每個顯示畫面有「連結時間」（Link Time，MATLAB 預設勾、
#   可對單一畫面取消）：勾著的一起縮放平移（Symbol rate 不同的換算成同一段時間），取消的自己縮放；
# 9 AM/PM/FM（星座圖、GFSK 一樣）分析「目前 panel」：點 panel（任何模式）就選定、框起來；panel 右鍵直接分析那個 panel；
#   清單明確選兩條時用那兩條；視窗標題與狀態列寫是哪個 panel、哪兩條。
def _s36_setup():
    """P1＝iq.csv 的 adc i／adc q、P2＝第二組 I/Q（pair36.csv 的 b i／b q，值不同）、P3＝CLK；全部顯示、捲到最上面。"""
    _s35_cfg0()
    _s35_mode_off()
    app.clear_all(); app.rescan(quiet=True); app.update()
    path2 = os.path.join(OUT, "pair36.csv")
    with open(path2, "w", encoding="utf-8") as f:
        f.write("b i,b q\n" + "\n".join(f"{math.cos(k / 9.0):.6f},{math.sin(k / 9.0):.6f}" for k in range(3000)) + "\n")
    app.add_csv_columns_direct(os.path.join(ROOT, "iq.csv"), None)
    app.add_csv_columns_direct(path2, None)
    app.add_text_signal(os.path.join(ROOT, "digital", "clk.txt"))
    app.refresh_list(); app.v["normalize"].set(False); app.plot(); app.show_all_x(); app.plot_scroll.yview_moveto(0); app.update()
    s1 = app.find_signal("iq.csv;;adc i"); q1 = app.find_signal("iq.csv;;adc q")
    s2 = next((x for x in app.signals if x.name.endswith("b i")), None); q2 = next((x for x in app.signals if x.name.endswith("b q")), None)
    clk = app.find_signal("digital/clk.txt")
    ok = all(x is not None for x in (s1, q1, s2, q2, clk)) and len({s1.panel, s2.panel, clk.panel}) == 3 and s1.panel == q1.panel and s2.panel == q2.panel
    check(ok, f"準備：P1 adc i／q、P2 b i／q、P3 CLK（{[(x.name, x.panel) for x in app.signals]}）")
    return s1, q1, s2, q2, clk


def _ax(p):
    info = app.render_info
    return info["axes"][info["panels"].index(p)]


def _wheel(ax, n=1):
    from matplotlib.backend_bases import MouseEvent
    x, y = ax.bbox.x0 + 0.5 * ax.bbox.width, ax.bbox.y0 + 0.5 * ax.bbox.height
    app.ia.on_scroll(MouseEvent("scroll_event", app.canvas, x, y, step=n))
    app.update()


def _click(ax, button=1):
    from matplotlib.backend_bases import MouseEvent
    x, y = ax.bbox.x0 + 0.37 * ax.bbox.width, ax.bbox.y0 + 0.93 * ax.bbox.height   # 上緣附近的空白（不壓到線）
    MouseEvent("button_press_event", app.canvas, x, y, button=button)._process()
    MouseEvent("button_release_event", app.canvas, x, y, button=button)._process()
    app.update()


def _xlabels_on(ax):
    ticks = ax.xaxis.get_major_ticks()
    return bool(ticks) and ticks[0].label1.get_visible()


@step
def s36a_panel_axes():
    """第 8 項：每個 panel 自己的 x 軸、x 單位、Symbol rate、y 單位；「連結時間」預設勾（MATLAB），取消的自己縮放；
    工具列「座標」編輯目前 panel；設定檔、舊設定檔、全部顯示、x 從／到、⌘U、刪 panel 再復原、十字游標。"""
    s1, q1, s2, q2, clk = _s36_setup()
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    a1, a2, a3 = _ax(p1), _ax(p2), _ax(p3)
    check(all(app.panel_is_linked(p) for p in (p1, p2, p3)) and a1.get_shared_x_axes().joined(a1, a3),
          "預設：每個 panel 都勾「連結時間」（MATLAB Signal Analyzer 預設），x 一起動")
    check(all(_xlabels_on(a) and a.get_xlabel() == "x [symbol]" for a in (a1, a2, a3)),
          "全部連結、單位一樣：每一張都有 x 刻度文字與 x 軸標籤（第 11 項；0.9.8 只有最下面一張有）")
    x1_0 = a1.get_xlim()
    _wheel(a2)
    check(a1.get_xlim() != x1_0 and a1.get_xlim() == a2.get_xlim() == a3.get_xlim(), "連結時：在 P2 滾輪，三張一起縮放")
    app.show_all_x(); app.update()
    # --- 取消 P2 的連結時間（先點 P2 成為目前 panel，再按工具列的「連結時間」）
    _click(_ax(p2))
    check(app.current_panel() == p2 and app.cur_panel_var.get() == f"目前 P{p2}", f"點 P2 → 目前 panel＝P2，工具列「座標」寫 P2（{app.cur_panel_var.get()}）")
    app.v_link.set(False); app._on_link_field(); app.update()
    a1, a2, a3 = _ax(p1), _ax(p2), _ax(p3)
    check(not app.panel_is_linked(p2) and not a2.get_shared_x_axes().joined(a2, a1) and a1.get_shared_x_axes().joined(a1, a3),
          "取消 P2 的連結時間：P2 自己一條 x；P1、P3 還是一起")
    check(_xlabels_on(a1) and _xlabels_on(a2) and _xlabels_on(a3) and a2.get_xlabel() == "x [symbol]",
          "x 不同步的 panel 各自有刻度文字與 x 軸標籤")
    x1_0, x2_0 = a1.get_xlim(), a2.get_xlim()
    _wheel(a2)
    check(a2.get_xlim() != x2_0 and a1.get_xlim() == x1_0, f"沒連結的 P2 自己縮放，P1 不動（P2 {x2_0}→{a2.get_xlim()}）")
    x2_1 = a2.get_xlim()
    _wheel(a1)
    check(a1.get_xlim() != x1_0 and a3.get_xlim() == a1.get_xlim() and a2.get_xlim() == x2_1, "在 P1 滾輪：P3（連結）跟著、P2 不動")
    app.plot(keep=True); app.update()
    check(_ax(p2).get_xlim() == x2_1, "重畫（保留範圍）：每個 panel 留著自己的 x 範圍")
    # --- 每個 panel 的單位：P2 用 us、Symbol rate 2M、y 單位 V（工具列「座標」，目前 panel＝P2）
    app.v["xunit"].set("us"); app._on_xunit_field(); app.update()
    app.v["symbol_rate"].set("2M"); app._on_rate_field(); app.update()
    app.v_yunit.set("V"); app._on_yunit_field(); app.update()
    a1, a2 = _ax(p1), _ax(p2)
    fmt2 = a2.xaxis.get_major_formatter()
    check(a2.get_xlabel() == "x [us]" and a1.get_xlabel() == "x [symbol]" and fmt2(10, 0) == "5" and a1.xaxis.get_major_formatter()(10, 0) == "10",
          f"P2：x 單位 us、Symbol rate 2M（10 symbol＝5 us）；P1 仍是 symbol（{a2.get_xlabel()} {fmt2(10, 0)}）")
    check(a2.get_ylabel().endswith(f"P{p2} [V]") and a1.get_ylabel().endswith(f"P{p1}"), f"y 軸單位只標在 P2（{a2.get_ylabel()}）")
    tip = app.ia.host.tip_text(s2.uid, 20, 20 / s2.sps + s2.x0, 0.0)
    check(" us" in tip, f"P2 的資料提示 x 用 us（{tip!r}）")
    _click(_ax(p1))
    check(app.v["xunit"].get() == "symbol" and app.v_yunit.get() == "" and app.v_link.get() and app.cur_panel_var.get() == f"目前 P{p1}",
          "點 P1：工具列「座標」換成 P1 的設定（symbol、無 y 單位、連結）")
    app.v["xunit"].set("ns"); app.plot(keep=True); app.update()       # 和以前一樣：改了欄位再按任何會重畫的鈕就生效（只改目前 panel）
    check(_ax(p1).get_xlabel() == "x [ns]" and _ax(p2).get_xlabel() == "x [us]", "改欄位後重畫：只有目前 panel（P1）換成 ns")
    app.v["xunit"].set("symbol"); app.plot(keep=True); app.update()
    # --- 設定檔往返、舊設定檔
    cfg = app.dump_settings()
    pp2 = cfg["panels"][str(p2)]
    check(pp2["link"] is False and pp2["xunit"] == "us" and pp2["symbol_rate"] == "2M" and pp2["yunit"] == "V" and pp2["xlim"]
          and cfg["panels"][str(p1)]["link"] is True, f"設定檔記每個 panel：連結、x 單位、Symbol rate、y 單位、x 範圍（{pp2}）")
    xl2 = tuple(_ax(p2).get_xlim())
    app.apply_settings(cfg, quiet=True); app.update()
    check(not app.panel_is_linked(p2) and app.panel_xunit(p2) == "us" and app.panel_symbol_rate(p2) == 2e6
          and all(abs(a - b) < 1e-6 * max(1.0, abs(b)) for a, b in zip(_ax(p2).get_xlim(), xl2)) and _ax(p2).get_ylabel().endswith("[V]"),
          f"還原設定檔：P2 的設定與自己的 x 範圍都回來（{_ax(p2).get_xlim()} vs {xl2}）")
    old = dict(cfg)
    old.pop("panels")
    old["view"] = dict(cfg["view"], xunit="symbol", symbol_rate="1M")
    app.apply_settings(old, quiet=True); app.update()
    check(all(app.panel_is_linked(p) and app.panel_xunit(p) == "symbol" and app.panel_symbol_rate(p) == 1e6 for p in app.panel_order())
          and _ax(p1).get_shared_x_axes().joined(_ax(p1), _ax(p2)), "舊設定檔（沒有 panels）：全部連結、單位照 view（和以前一樣）")
    # --- Symbol rate 不同也能連結：同一段時間（P2 2M → P2 的 symbol 是 P1 的 2 倍）
    app.set_panel_prop("symbol_rate", "2M", p2); app.update()
    a1, a2 = _ax(p1), _ax(p2)
    r = [b / a for a, b in zip(a1.get_xlim(), a2.get_xlim()) if abs(a) > 1e-9]
    check(r and all(abs(v - 2.0) < 1e-6 for v in r) and getattr(a1, "_pk_xlink", None) == getattr(a2, "_pk_xlink", None) is not None,
          f"Symbol rate 不同的 panel 連結：同一段時間（P2 的 x＝P1 × 2：{a1.get_xlim()} {a2.get_xlim()}）")
    _wheel(a1)
    r = [b / a for a, b in zip(_ax(p1).get_xlim(), _ax(p2).get_xlim()) if abs(a) > 1e-9]
    check(r and all(abs(v - 2.0) < 1e-6 for v in r), "在 P1 滾輪：P2 換算後一起縮放")
    app.ia.zoom_out(); app.update()
    r2 = [b / a for a, b in zip(_ax(p1).get_xlim(), _ax(p2).get_xlim()) if abs(a) > 1e-9]
    check(r2 and all(abs(v - 2.0) < 1e-6 for v in r2), "工具列「縮小」：換算連結的 panel 不會被縮兩次（比例仍是 2）")
    app.set_panel_prop("symbol_rate", "1M", p2); app.update()
    # --- ⌘U（連結時間）、全部顯示、x 從／到
    _click(_ax(p2))
    app.actions["view.link_time"].run(); app.update()
    check(not app.panel_is_linked(p2) and not app.v_link.get(), "Ctrl+U／⌘U（連結時間）：目前 panel（P2）取消連結")
    _wheel(_ax(p2)); _wheel(_ax(p2))
    app.show_all_x(); app.update()
    a, b = _ax(p2).get_xlim()
    lo2, hi2 = s2.x_span
    check(a <= lo2 + 1e-9 and b >= hi2 - 1e-9, f"全部顯示：沒連結的 P2 也回到自己的全部範圍（{(a, b)} ⊇ {(lo2, hi2)}）")
    x1_0 = _ax(p1).get_xlim()
    app.xfrom_var.set("10"); app.xto_var.set("20"); app.apply_xrange(); app.update()
    check(_ax(p2).get_xlim() == (10.0, 20.0) and _ax(p1).get_xlim() == x1_0, "x 從／到：只套到目前 panel（P2，沒連結），P1 不動")
    # --- 十字游標：沒連結的 panel 不畫
    app.v["cursor"].set(True); app._toggle_cursor(); app.canvas.draw(); app.update()
    app._draw_cursor(5.0, p1)
    vis = {p: vl.get_visible() for (ax_, vl, _tx), p in zip(app._cursor_items, app.render_info["panels"])}
    check(vis.get(p1) and vis.get(p3) and not vis.get(p2), f"十字游標：P1、P3（連結）畫、P2（沒連結）不畫（{vis}）")
    app.v["cursor"].set(False); app._toggle_cursor()
    # --- 刪掉 panel 再復原：它的座標設定跟著回來
    app.set_panel_prop("yunit", "LSB", p2); app.update()
    app.delete_panel(p2); app.update()
    check(p2 not in app.panel_props, "刪掉 P2：它的設定也拿掉（之後同號的新 panel 從預設開始）")
    app.undo_action(); app.update()
    check(app.panel_props.get(p2, {}).get("yunit") == "LSB" and not app.panel_is_linked(p2), "復原：P2 回來，y 單位、連結時間也回來")
    _s35_restore()


@step
def s36b_panel_iq_target():
    """第 9 項：AM/PM/FM、星座圖、GFSK 分析「目前 panel」——點 panel（平移模式也一樣）就選定、框起來；panel 右鍵直接分析那個 panel；
    清單明確選兩條時用那兩條；視窗標題與狀態列寫是哪個 panel、哪兩條；沒有 I/Q 的 panel 說清楚、不開空視窗。"""
    from types import SimpleNamespace as NS
    s1, q1, s2, q2, clk = _s36_setup()
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    app.sig_tree.selection_set([]); app._on_list_select()
    app.plot_toolbar.set_mode("pan"); app.update()              # 啟動預設的平移模式
    _click(_ax(p2))
    check(app.current_panel() == p2, f"平移模式下點 P2 → 目前 panel＝P2（{app.current_panel()}）")
    app._draw_panel_ui(); app.update()
    w = app.canvas.get_tk_widget()
    items = w.find_withtag("dsv_panel_cur")
    r_ = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)       # 只放大框外 3 個邏輯像素的邊
    bb = _ax(p2).bbox
    ok_box = False
    if len(items) == 1:
        x0, y0, x1, y1 = w.coords(items[0])
        H = float(app.fig.bbox.height)                # TkAgg：Tk 畫布座標＝matplotlib 像素上下翻（W10）
        ok_box = abs(x0 - (bb.x0 - 3 * r_)) <= 2 and abs(y0 - ((H - bb.y1) - 3 * r_)) <= 2 and abs(y1 - ((H - bb.y0) + 3 * r_)) <= 2
    check(ok_box, f"P2 框起來（Tk 畫布上，不會進匯出的圖）（{len(items)} 個框）")
    win = app.open_iq_window(); app.update()
    check(win is not None and len(win.pairs) == 1 and win.pairs[0][0].uid == s2.uid and win.pairs[0][1].uid == q2.uid
          and f"P{p2}" in win.title() and app.status_var.get().startswith(f"已開啟 AM/PM/FM 分析：P{p2}，I＝{s2.name}、Q＝{q2.name}"),
          f"按 AM/PM/FM：分析 P2 的 I/Q，標題與狀態列寫 P2 與兩條名稱（{win.title() if win else None}／{app.status_var.get()[:50]}）")
    if win is not None:
        win.destroy(); app.update()
    _click(_ax(p1))
    w2 = app.open_constellation(); app.update()
    check(w2 is not None and w2.pairs[0][0].uid == s1.uid and f"P{p1}" in w2.title(), "點 P1 → 星座圖分析 P1 的 I/Q")
    if w2 is not None:
        w2.destroy(); app.update()
    app.sig_tree.selection_set([f"s{s2.uid}", f"s{q2.uid}"]); app._on_list_select(); app.update()
    w3 = app.open_gfsk(); app.update()
    check(w3 is not None and w3.pairs[0][0].uid == s2.uid and "清單選取" in w3.title() and app.current_panel() == p1,
          "清單明確選了 P2 的兩條（目前 panel 是 P1）→ GFSK 用那兩條，標題寫「清單選取」")
    if w3 is not None:
        w3.destroy(); app.update()
    app.sig_tree.selection_set([]); app._on_list_select()
    # --- panel 右鍵：直接分析那個 panel（也會把它設成目前 panel）
    menus.clear(); menu_objs.clear()
    app._context_for_hit(NS(kind="empty", id=None, ax=_ax(p2)), NS(guiEvent=None, x=0, y=0))
    lab = menus[-1] if menus else []
    check(all(x in lab for x in (f"AM/PM/FM 分析（P{p2}）…", f"星座圖（P{p2}）…", f"GFSK（P{p2}）…", f"座標（P{p2}）")) and app.current_panel() == p2,
          f"P2 右鍵：AM/PM/FM、星座圖、GFSK（P2）與座標子選單；右鍵也選定 P2（{lab[:8]}）")
    n_iq = len([x for x in app.winfo_children() if isinstance(x, sv.IqWindow)])
    ok_ = invoke_menu(menu_objs[-1], f"AM/PM/FM 分析（P{p2}）…") if menu_objs else False
    app.update()
    iqs = [x for x in app.winfo_children() if isinstance(x, sv.IqWindow)]
    check(ok_ and len(iqs) == n_iq + 1 and iqs[-1].pairs[0][0].uid == s2.uid, "按「AM/PM/FM 分析（P2）…」→ 分析 P2")
    for x in iqs[n_iq:]:
        x.destroy()
    app.update()
    # --- 沒有 I/Q 的 panel：不開空視窗，說清楚是哪個 panel、裡面有哪些
    _click(_ax(p3))
    n_iq = len([x for x in app.winfo_children() if isinstance(x, sv.IqWindow)])
    res = app.open_iq_window(); app.update()
    st = app.status_var.get()
    check(res is None and len([x for x in app.winfo_children() if isinstance(x, sv.IqWindow)]) == n_iq
          and f"P{p3} 找不到 I/Q 配對" in st and clk.name in st, f"目前 panel（P3）沒有 I/Q：不開視窗，狀態列說 P3 有什麼（{st[:60]}）")
    # --- 清單右鍵：標籤寫出分析對象
    app.sig_tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
    bbox = app.sig_tree.bbox(f"s{s1.uid}")
    menus.clear()
    app._on_list_context(NS(x=(bbox[0] + 5) if bbox else 5, y=(bbox[1] + 3) if bbox else 5, x_root=0, y_root=0))
    lab = menus[-1] if menus else []
    check(f"AM/PM/FM 分析（P{p1}）…" in lab and f"GFSK（P{p1}）…" in lab, f"清單右鍵：選了 P1 的訊號 → 「AM/PM/FM 分析（P1）…」（{[x for x in lab if 'P' in x][:4]}）")
    app.sig_tree.selection_set([]); app._on_list_select()
    # --- 只有一張 panel 時不畫目前 panel 的框
    app.delete_panel(p3); app.delete_panel(p2); app.update()
    app._draw_panel_ui(); app.update()
    check(not app.canvas.get_tk_widget().find_withtag("dsv_panel_cur"), "只剩一張 panel：不畫目前 panel 的框")
    app.plot_toolbar.set_mode("")
    _s35_restore()


# ---------------------------------------------------------------------------------------------------------------------------
# s37：2026-10-25 使用者回報的第 10、11、12 項（修正前會失敗）：
# 10 點右邊哪個 panel，左邊「已繪訊號」清單就選它的全部訊號（含隱藏的、取代原本的選取、捲到看得到第一列）——平移／放大／資料提示／
#    沒有模式點空白都算，滑鼠右鍵也算；點在線上照舊（選那一條／釘提示）；點握把區（任何模式）選取 panel 後 Delete 照樣刪整個 panel；
#    左鍵要「點」（放開時沒拖動）才換清單：平移、拉框放大、拖圖例不改使用者自己在清單選的；跟著選的只有清單反白、線不加粗；
#    跟著選的按 Delete＝刪除 panel（照「清空前確認」先問）；平移／放大模式握把選取後 Delete／⌫ 也刪；Esc 取消跟著選的。
#    第二輪審查（_s37_round2）：跟著選的不算使用者的選取（Shift＋點線只選點到的那條、單一訊號的 panel 點線＝自己選的）；Delete 不看模式與焦點、
#    工具列／面板／清單右鍵「移除」、⌘X 都先問；拆開／編輯 Panel 後不再算跟著選；點別張的資料提示取消跟著選、復原時目前 panel 跟著；
#    握把區右鍵也換 panel、點擊門檻 10 px；狀態列不留錯的條數；拖放到 x 標籤＝上面那張。
# 11 每個 panel 都畫 x 刻度字與 x 軸標籤（連結、單位一樣也畫；收合的矮列不畫、最下面那張照畫），不壓到下一張的座標區與圖例；
#    收合的矮列下面不留標籤空隙；存成別的大小重排；最右邊的刻度字不被切掉；「全部放進視窗」每張至少 0.5 in、放得下圖例；十字游標讀數框不超出座標區。
#    第二輪審查（_s37_round2_layout）：圖例放不下只加高那一張（「全部放進視窗」照樣不捲）；存成放不下每張標籤的大小退回 0.9.8 的標法；刻度字只用一個字型。
# 12 下面的平移器只畫目前 panel 的訊號，點別張馬上換；x 單位用那張的；拖縮放窗動的是目前 panel，連結時間的照連結跟著。
# 第四輪審查（_s37_round4／_s37_round4_layout）：剪下／刪掉目前 panel 後點最上面那張再 ⌘V 貼到那張；平移過之後握把上照樣是手；座標區外的
#    提示框、圖例算自己那張；雙擊 × 只刪一張；平移／放大模式清單自己選的不從圖上刪；衍生訊號一起剪貼有資料；刪提示的 ⌘Z 不重設 y；
#    凍結檔不越積越多；檔案樹 ⌘X；右鍵 x 刻度字；退回而且太矮時狀態列兩件事都說。
# 第五輪（_s37_round5，2026-10-25 使用者決定 U7b、U9）：右鍵點 x 刻度字／標籤＝右鍵點那張的空白（四種模式、同一個選單）；
#    凍結檔沒人用到就自動清（啟動時、寫完自動存檔之後），「匯出設定」帶著資料、清掉之後照樣匯入得回來。
# 第七輪（_s37_round7，2026-10-25 使用者決定 U10）：刪除／剪下要把沒被選到的衍生訊號（不管在哪一張）改成獨立訊號、frozen 資料夾卻寫不進去（唯讀、同名的檔案擋住、
#    磁碟滿…）時整個取消：什麼都沒移除、復原記錄與剪貼簿不變、錯誤視窗寫出哪幾條、資料夾、原因（每個入口都測）。
# 第十輪（_s37_round10，2026-10-26 使用者決定 U15、U16）：自動存檔壞掉（截斷在 "signals" 之前、截斷在檔名中間、整份 NUL）時只要還有任何一份
#    備份就一個凍結檔都不清；AM/PM/FM 視窗複製、拖線帶著整段資料，來源刪掉之後照 U11 貼成獨立訊號或整個不貼；沒有資料就整個不貼；
#    自動存檔／匯出的資料夾不能寫入時不直接覆寫；沒有讀取權限的提示；paste_signals 回傳條數（AM/PM/FM 視窗 ⌘V 把主視窗帶到前面）。
def _sel_uids():
    return {s_.uid for s_ in app.selected_signals()}


def _panel_uids(p):
    return {s_.uid for s_ in app.signals if s_.panel == p}


def _mouse(ax, fx, fy, button=1):
    """在座標區 ax 的 (fx, fy)（0..1）按一下（matplotlib 事件，走主圖全部的 callback）。"""
    from matplotlib.backend_bases import MouseEvent
    x, y = ax.bbox.x0 + fx * ax.bbox.width, ax.bbox.y0 + fy * ax.bbox.height
    MouseEvent("button_press_event", app.canvas, x, y, button=button)._process()
    MouseEvent("button_release_event", app.canvas, x, y, button=button)._process()
    app.update()


def _drag_px(x, y, dx, dy=0.0, button=1, steps=8):
    """從 matplotlib 像素 (x, y) 按住拖 (dx, dy) 再放開（中間送 motion，工具列平移／拉框、Interactor 拖曳都走真的路徑）。"""
    from matplotlib.backend_bases import MouseEvent
    MouseEvent("button_press_event", app.canvas, x, y, button=button)._process()
    for k in range(1, steps + 1):
        MouseEvent("motion_notify_event", app.canvas, x + dx * k / steps, y + dy * k / steps, buttons={1})._process()
    MouseEvent("button_release_event", app.canvas, x + dx, y + dy, button=button)._process()
    app.update()


def _empty_at(ax):
    """座標區 ax 裡一個真的空白的位置 (fx, fy)：不在線、圖例、提示上（_click 的上緣附近在 cos 的波峰旁邊可能壓到線）。"""
    from matplotlib.backend_bases import MouseEvent
    app.canvas.draw()
    for fy in (0.985, 0.95, 0.5, 0.03):
        for fx in (0.37, 0.12, 0.62, 0.25):
            x, y = ax.bbox.x0 + fx * ax.bbox.width, ax.bbox.y0 + fy * ax.bbox.height
            if app.ia.hit_test(MouseEvent("button_press_event", app.canvas, x, y, button=1)).kind == "empty":
                return fx, fy
    return 0.37, 0.985


def _mid_empty_px(ax):
    """座標區 ax 中間附近一個真的空白的位置（matplotlib 像素）：拖曳平移用——從中間拖 40 px 還在座標區裡（_empty_at 先挑上緣附近，
    拖出去就不平移）。只跑 s20（DSV_TEST_ONLY）時座標區中心剛好在 clk 線上，按下會變成點線、右鍵開的是線的選單。"""
    from matplotlib.backend_bases import MouseEvent
    app.canvas.draw()
    cands = [(fx / 100.0, fy / 100.0) for fy in (50, 58, 42, 66, 34, 74, 26, 80, 20) for fx in range(50, 5, -3)]   # 中間附近先；方波的邊很密時往旁邊找
    for fx, fy in cands:
        x, y = ax.bbox.x0 + fx * ax.bbox.width, ax.bbox.y0 + fy * ax.bbox.height
        if all(app.ia.hit_test(MouseEvent("button_press_event", app.canvas, x, y, button=b)).kind == "empty" for b in (1, 3)):
            return x, y
    return pk.interact.axes_center_px(ax)


def _click_empty(ax, button=1):
    """點座標區 ax 的空白處。"""
    _mouse(ax, *_empty_at(ax), button=button)


def _line_click(sig, frac=0.33, shift=False, button=1):
    """點在訊號 sig 的線上（第 frac 位置的樣本；button＝3 右鍵）。"""
    from matplotlib.backend_bases import MouseEvent
    app.canvas.draw()
    x, y = _w14_line_point(sig, frac)
    kw = {"modifiers": {"shift"}} if shift else {}
    MouseEvent("button_press_event", app.canvas, x, y, button=button, **kw)._process()
    MouseEvent("button_release_event", app.canvas, x, y, button=button, **kw)._process()
    app.update()


def _handle_press(p, drag_to=None):
    """在 panel p 左邊的握把區（P 標籤那一帶，座標區外）按一下；drag_to＝拖到這個 matplotlib y 再放開。"""
    from matplotlib.backend_bases import MouseEvent
    ax = _ax(p)
    x, y = ax.bbox.x0 - 20, (ax.bbox.y0 + ax.bbox.y1) / 2
    MouseEvent("button_press_event", app.canvas, x, y, button=1)._process()
    if drag_to is not None:
        for k in range(1, 8):
            MouseEvent("motion_notify_event", app.canvas, x, y + (drag_to - y) * k / 7)._process()
        y = drag_to
    MouseEvent("button_release_event", app.canvas, x, y, button=1)._process()
    app.update()


def _xlabel_gaps():
    """每張圖的 x 刻度字＋x 軸標籤的下緣，到下一張圖上緣（座標區、圖例取高的）的距離（像素，負的＝壓到）；和最下面那張標籤的下緣。"""
    app.canvas.draw()
    r = app.canvas.get_renderer()
    info = app.render_info
    axes = info["axes"]
    gaps = []
    for i in range(len(axes) - 1):
        bb = axes[i].xaxis.get_tightbbox(r)
        lo = bb.y0 if bb is not None else axes[i].bbox.y0
        nxt = [axes[i + 1], info["axes_right"].get(info["panels"][i + 1])]
        tops = [axes[i + 1].bbox.y1] + [a.get_legend().get_window_extent(r).y1 for a in nxt if a is not None and a.get_legend() is not None]
        gaps.append(lo - max(tops))
    bb = axes[-1].xaxis.get_tightbbox(r)
    return gaps, (bb.y0 if bb is not None else 0.0)


def _panner_drag(pn, x0, x1):
    """在平移器上從資料座標 x0 拖到 x1。"""
    from matplotlib.backend_bases import MouseEvent

    def ev(name, xd):
        px_, py_ = pn.ax.transData.transform((xd, 0.5))
        return MouseEvent(name, pn.canvas, px_, py_, button=1)
    pn.canvas.callbacks.process("button_press_event", ev("button_press_event", x0))
    pn.canvas.callbacks.process("motion_notify_event", ev("motion_notify_event", (x0 + x1) / 2))
    pn.canvas.callbacks.process("motion_notify_event", ev("motion_notify_event", x1))
    pn.canvas.callbacks.process("button_release_event", ev("button_release_event", x1))
    app.update()


class _AskSpy:
    """暫時換掉 messagebox：記下問了什麼（「清空前確認」），回答 answer。"""

    def __init__(self, answer=True):
        self.calls, self.answer = [], answer

    def __getattr__(self, name):
        def f(*a, **k):
            self.calls.append((name, a[:2]))
            return self.answer if name.startswith("ask") else None
        return f


def _with_ask(answer, fn):
    spy, old = _AskSpy(answer), sv.messagebox
    sv.messagebox = spy
    try:
        fn()
        app.update()
    finally:
        sv.messagebox = old
    return spy.calls


def _lws(p):
    """panel p 每條線現在的線寬與沒選取時的線寬。"""
    arts = app.render_info["artists"]
    return [(arts[u]["line"].get_linewidth(), float(arts[u]["lw"])) for u in sorted(_panel_uids(p)) if u in arts]


def _set_mode(mode):
    app.v_tips.set(mode == "tips"); app._on_tips_toggle()
    app.plot_toolbar.set_mode("" if mode in ("tips", "") else mode); app.update()


def _thick(sig):
    """sig 的線現在是不是「選取」的粗線（沒選取時線寬的 2.5 倍）。"""
    a = app.render_info["artists"].get(sig.uid)
    return a is not None and abs(a["line"].get_linewidth() - 2.5 * float(a["lw"])) < 1e-9


def _press_at(x, y, button=1, moves=()):
    """在主圖的 matplotlib 像素 (x, y) 按下、經過 moves（[(x, y), …]）、在最後一點放開（走主圖全部的 callback）。"""
    from matplotlib.backend_bases import MouseEvent
    MouseEvent("button_press_event", app.canvas, x, y, button=button)._process()
    for mx, my in moves:
        MouseEvent("motion_notify_event", app.canvas, mx, my, buttons={button})._process()
    ex, ey = moves[-1] if moves else (x, y)
    MouseEvent("button_release_event", app.canvas, ex, ey, button=button)._process()
    app.update()


def _tip_box_xy(tip_id):
    app.canvas.draw()
    ann, _mk = app.ia.tip_artists[tip_id]
    r_ = app.canvas.get_renderer()
    bb = ann.get_bbox_patch().get_window_extent(r_) if ann.get_bbox_patch() is not None else ann.get_window_extent(r_)
    return (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2


def _s37_round2(s1, q1, s2, q2, clk):
    """第二輪審查（2026-10-25）：點過 panel（清單跟著選）之後 Shift＋點線、只有一條訊號的 panel、拆開／編輯 Panel 之後、資料提示、復原、
    握把區右鍵與點擊門檻、狀態列、拖放到 x 標籤。"""
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    dpr = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)
    app.v["confirm_clear"].set(True)
    # 點過 panel 後 Shift＋點線：跟著選的不算使用者的選取 → 只選點到的那一條（以前會把點到的那條拿掉、留下另一條，接著 Delete 刪錯訊號）
    for mode, name in (("", "沒有工具列模式"), ("tips", "資料提示模式")):
        _set_mode(mode)
        for pre in (p1, p2):
            _follow(pre)                                    # 清單跟著選 P1／P2（沒有工具列模式：右鍵點空白，U2）
            _line_click(q2, 0.55, shift=True)
            check(_sel_uids() == {q2.uid} and app._follow_panel() is None and _thick(q2) and not _thick(s2),
                  f"{name}：點 P{pre} 空白（清單跟著選）再 Shift＋點 P2 的「b q」線 → 只選 b q、它加粗（{sorted(_sel_uids())}）")
        n0 = len(app.signals)
        calls = _with_ask(True, lambda: tk_key(w, "Delete"))
        check(len(app.signals) == n0 - 1 and app.find_signal_by_uid(q2.uid) is None and app.find_signal_by_uid(s2.uid) is not None
              and not calls, f"{name}：接著按 Delete → 移除的是點到的 b q、不問（{n0} → {len(app.signals)}，{calls}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
    _set_mode("")
    _click_empty(_ax(p2))
    _line_click(clk, 0.5, shift=True)
    _line_click(q2, 0.55, shift=True)
    check(_sel_uids() == {clk.uid, q2.uid}, f"點 P2 空白、Shift＋點 CLK、再 Shift＋點 b q → 選 CLK 和 b q（和 0.9.8 一樣；{sorted(_sel_uids())}）")
    # 只有一條訊號的 panel：清單跟著選過再點線／在線上按右鍵＝自己選的那一條（加粗；Delete 只刪它、不問「刪除 P3」）
    _follow(p3)
    _line_click(clk, 0.5)
    check(_sel_uids() == {clk.uid} and app._follow_panel() is None and _thick(clk),
          "只有一條訊號的 P3：點過空白再點在線上 → 自己選的那一條（加粗，不再算跟著選）")
    n0 = len(app.signals)
    calls = _with_ask(True, lambda: tk_key(w, "Delete"))
    check(len(app.signals) == n0 - 1 and not calls, f"接著 Delete：直接移除那一條、不問「刪除 P3」（{calls}）")
    if len(app.signals) < n0:
        app.undo_action(); app.update()
    _follow(p3)
    menus.clear()
    _line_click(clk, 0.5, button=3)
    check(_sel_uids() == {clk.uid} and app._follow_panel() is None and _thick(clk) and bool(menus),
          "只有一條訊號的 P3：點過空白再在線上按右鍵 → 那條線的選單、那一條加粗")
    # 清單跟著選 P2 之後「拆成各自一張」（清單右鍵也是這個）：成員變了就不再算跟著 P2，當成自己選的兩條（AM/PM/FM 寫「清單選取」）
    _set_mode("pan")
    _click_empty(_ax(p2))
    app.split_panels(); app.update()
    win = app.open_iq_window(); app.update()
    title = win.title() if win is not None else app.status_var.get()
    check(app._follow_panel() is None and win is not None and "清單選取" in title and _thick(q2) and s2.panel != q2.panel,
          f"點 P2（清單跟著選）再「拆成各自一張」：不再算跟著 P2，AM/PM/FM 分析選的兩條（{title[:36]}）")
    if win is not None:
        win.destroy(); app.update()
    app.undo_action(); app.update()
    check(s2.panel == q2.panel == p2, "復原拆開")
    # 清單跟著 P1 時，在 P2 的資料提示上按右鍵／點它：目前 panel 換成 P2，跟著 P1 選的取消（框、平移器、清單不會分在兩張；Delete 不會問刪 P1）
    _set_mode("tips")
    _line_click(s2, 0.45)
    tip = app.datatips[-1] if app.datatips else None
    if tip is not None:
        _click_empty(_ax(p1))
        menus.clear()
        _press_at(*_tip_box_xy(tip.id), button=3)
        check(app.current_panel() == p2 and app._follow_panel() is None and not tree.selection() and bool(menus),
              f"清單跟著 P1 時在 P2 的資料提示上按右鍵：目前 panel＝P2、跟著 P1 選的取消（{sorted(_sel_uids())}、目前 P{app.current_panel()}）")
        n0 = len(app.signals)
        calls = _with_ask(False, lambda: tk_key(w, "Delete"))
        check(len(app.signals) == n0 and not calls, f"接著 Delete：不會問刪 P1、什麼 panel 都不刪（{calls}）")
        _click_empty(_ax(p1))
        _press_at(*_tip_box_xy(tip.id))
        st_ = app.status_var.get()
        check(app.ia.selected_tip == tip.id and not tree.selection() and "清單選取它的" not in st_ and f"P{p2}" in st_,
              f"清單跟著 P1 時點 P2 的資料提示：選取提示、清單清空，狀態列不寫「清單選取它的 2 條訊號」（{st_[:32]}）")
    else:
        check(False, "資料提示模式點線沒有釘到提示")
    app.ia.clear_tips(); app.update()
    _click_empty(_ax(p2))
    _with_ask(True, lambda: tk_key(w, "Delete"))
    _click_empty(_ax(p1))
    app.undo_action(); app.update()
    check(p2 in app.panel_order() and app._follow_panel() == p2 and app.current_panel() == p2,
          f"刪除 P2、點 P1、⌘Z：P2 回來、清單跟著 P2，目前 panel（框、平移器、AM/PM/FM）也是 P2（目前 P{app.current_panel()}）")
    # 握把區：右鍵也是點這張（目前 panel、清單跟著）；點一下和拖曳的分界和座標區一樣是 10 個邏輯像素
    _set_mode("pan")
    _click_empty(_ax(p2))
    ax3 = _ax(p3)
    menus.clear()
    _press_at(ax3.bbox.x0 - 20, (ax3.bbox.y0 + ax3.bbox.y1) / 2, button=3)
    check(app.current_panel() == p3 and _sel_uids() == _panel_uids(p3) and bool(menus) and sv.tr("隱藏這張圖的訊號") in menus[-1],
          f"清單跟著 P2 時在 P3 的握把區按右鍵：P3 的選單，目前 panel、清單也換成 P3（目前 P{app.current_panel()}）")
    for mode, name in (("pan", "平移模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        tk_key(w, "Escape"); app.update()
        ax2 = _ax(p2)
        x0, y0 = ax2.bbox.x0 - 20, (ax2.bbox.y0 + ax2.bbox.y1) / 2
        order0 = app.panel_order()
        _press_at(x0, y0, moves=[(x0 + 4 * dpr, y0 + 4 * dpr), (x0 + 6 * dpr, y0 + 5 * dpr)])
        check(app._sel_panel == p2 and _sel_uids() == _panel_uids(p2) and app.panel_order() == order0,
              f"{name}：握把區按下、手抖約 8 個邏輯像素再放開＝點一下（選取 P2；和座標區一樣 10 px 才算拖曳）")
        tk_key(w, "Escape"); app.update()
    # 狀態列：清單改了、按 Esc 之後，不留「清單選取它的 N 條訊號」
    app._sig_clip = []
    _set_mode("pan")
    _click_empty(_ax(p1)); _click_empty(_ax(p2))
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    st1 = app.status_var.get()
    _click_empty(_ax(p1))
    tk_key(w, "Escape"); app.update()
    st2 = app.status_var.get()
    check("清單選取它的" not in st1 and "清單選取它的" not in st2 and f"P{p2}" in st1 and f"P{p1}" in st2,
          f"清單改成只選一條、按 Esc 之後，狀態列不留和清單不符的條數（{st1[:22]}／{st2[:22]}）")
    # 拖放：放在某張圖下面的「x [單位]」標籤上＝加到那張（標籤屬於上面那張；以前算下一張）
    app.canvas.draw()
    r_ = app.canvas.get_renderer()
    wdg = app.canvas.get_tk_widget()
    H = app.fig.bbox.height
    got = []
    for p in (p1, p2):
        lb = _ax(p).xaxis.label.get_window_extent(r_)
        xr = wdg.winfo_rootx() + (lb.x0 + lb.x1) / 2                   # TkAgg：Tk 畫布像素＝matplotlib 像素（W10）
        yr = wdg.winfo_rooty() + (H - (lb.y0 + lb.y1) / 2)
        got.append(app.drop_target(int(xr), int(yr)))
    check(got == [("panel", p1), ("panel", p2)], f"拖放到 P1、P2 的「x [symbol]」標籤上：加到那張（{got}）")
    _set_mode("")
    tk_key(w, "Escape"); app.update()


def _s37_round2_layout(s1, q1, s2, q2, clk):
    """第二輪審查（版面）：一張訊號多只有那張加高（「全部放進視窗」照樣放進可見高度）；存成比較小的圖檔放不下每張的標籤時
    退回 0.9.8 的標法（圖例不蓋刻度字、標籤不畫進下一張），存完畫面照舊；x 刻度字只用一個字型（重畫快一點，畫出來一樣）。"""
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    dpr = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)
    path = os.path.join(OUT, "multi37.csv")
    with open(path, "w", encoding="utf-8") as f:
        f.write(",".join(f"m{k}" for k in range(10)) + "\n"
                + "\n".join(",".join(f"{math.sin(j / (5.0 + k)):.5f}" for k in range(10)) for j in range(400)) + "\n")
    app.add_csv_columns_direct(path, None, panel=p1)
    app.refresh_list(); app.plot(keep=True); app.update()
    extra = [s_ for s_ in app.signals if os.path.basename(s_.path or "") == "multi37.csv"]
    fit0 = app.v["fit_panels"].get()
    for fit in (False, True):
        app.v["fit_panels"].set(fit); app.plot(keep=True); app.update()
        app.canvas.draw()
        r_ = app.canvas.get_renderer()
        a1, a2, a3 = _ax(p1), _ax(p2), _ax(p3)
        top1 = app.render_info["axes_right"].get(p1) or a1
        lg = top1.get_legend().get_window_extent(r_)
        h1, h2, h3 = (a.bbox.height / dpr for a in (a1, a2, a3))
        Hc, vis = app.fig.bbox.height, app.plot_scroll.winfo_height()            # TkAgg：圖的像素＝Tk 畫布像素（W10）
        check(len(extra) == 10 and h1 > h2 + 20 and abs(h2 - h3) < 1.5 and lg.y0 >= a1.bbox.y0 - 0.5 and (not fit or Hc <= vis + 1),
              f"「全部放進視窗」{'開' if fit else '關'}、P1 有 12 條訊號：只有 P1 加高到放得下圖例（{h1:.0f} px），P2、P3 照舊（{h2:.0f}／{h3:.0f} px）"
              + (f"，畫布＝可見高度（{Hc:.0f} ≤ {vis} px，不用捲）" if fit else ""))
    app._remove_signals(extra); app.update()
    app.v["fit_panels"].set(fit0); app.plot(keep=True); app.update()
    # 存成 8×2.4 in（放不下每張的標籤與圖例）：這次只標最下面那張（3 張連結、單位一樣＝0.9.8 的標法），不重疊；存完畫面每張又都標
    axes = app.render_info["axes"]
    pos0 = [tuple(a.get_position().bounds) for a in axes]
    size0 = tuple(app.fig.get_size_inches())
    app.fig.set_size_inches(8, 2.4, forward=False)
    app.fig._pk_exporting = True                            # 和 plotkit.export.export_figure 一樣：這次畫圖是匯出（畫面上一定每張都標）
    try:
        gaps_e, bot_e = _xlabel_gaps()
        fb = bool(app.render_info["layout"].last["fallback"])
        shown = [_xlabels_on(a) and a.xaxis.label.get_visible() for a in axes]
        r_ = app.canvas.get_renderer()
        legs_in = all(((app.render_info["axes_right"].get(p) or a).get_legend() is None
                       or (app.render_info["axes_right"].get(p) or a).get_legend().get_window_extent(r_).y0 >= a.bbox.y0 - 0.5)
                      for p, a in zip(app.render_info["panels"], axes))
    finally:
        del app.fig._pk_exporting
    app.fig.set_size_inches(*size0, forward=False)
    out_png = os.path.join(OUT, "s37_export_8x2.4.png")
    pk.export.export_figure(app.fig, out_png, dpi=100, size_in=(8, 2.4))
    app.canvas.draw()
    pos1 = [tuple(a.get_position().bounds) for a in axes]
    back = [_xlabels_on(a) and a.xaxis.label.get_visible() for a in axes]
    check(fb and shown == [False, False, True] and all(g >= 1 for g in gaps_e) and bot_e >= 0 and legs_in,
          f"存成 8×2.4 in（放不下每張的標籤與圖例）：這次退回 0.9.8 的標法、只標最下面那張（{shown}），不重疊（{[round(float(g), 1) for g in gaps_e]} px）、圖例在座標區裡")
    check(os.path.isfile(out_png) and back == [True, True, True]
          and all(all(abs(u - v) < 1e-9 for u, v in zip(a, b)) for a, b in zip(pos0, pos1)),
          "存完 8×2.4 in 的圖檔：畫面上每張又都標 x 軸、版面照舊")
    fam1 = pk.styles.resolved_fonts(app.render_info["style"])[:1]
    check(all(list(a.xaxis.get_major_ticks()[0].label1.get_fontfamily()) == fam1 for a in axes),
          f"x 刻度字（數字）只用第一個字型 {fam1}（不帶中文字型的備援清單：重畫快一點，畫出來一樣）")


def _follow(p):
    """讓清單跟著選 panel p：沒有工具列模式（U2：左鍵點空白是取消選取）用右鍵點空白（D2；清單自己選了這張的某幾條時右鍵會留著，
    所以先清掉），其他模式左鍵點空白。"""
    plain = not str(getattr(app.toolbar, "mode", "") or "") and not app.ia.tips_enabled
    if plain:
        app.sig_tree.selection_set([]); app._on_list_select(); app.update()
    _click_empty(_ax(p), button=3 if plain else 1)


def _line_xy(sig, frac=0.33):
    """訊號 sig 的線上一點（第 frac 位置的樣本；matplotlib 像素）。"""
    app.canvas.draw()
    return tuple(float(v) for v in _w14_line_point(sig, frac))


def _handle_dbl(p):
    """在 panel p 的握把區雙擊（matplotlib 事件，dblclick）。"""
    from matplotlib.backend_bases import MouseEvent
    ax = _ax(p)
    x, y = ax.bbox.x0 - 20, (ax.bbox.y0 + ax.bbox.y1) / 2
    MouseEvent("button_press_event", app.canvas, x, y, button=1)._process()
    MouseEvent("button_release_event", app.canvas, x, y, button=1)._process()
    MouseEvent("button_press_event", app.canvas, x, y, button=1, dblclick=True)._process()
    MouseEvent("button_release_event", app.canvas, x, y, button=1)._process()
    app.update()


def _xlabel_xy(p, what="label"):
    """panel p 的 x 軸標籤（what="label"）或中間那個 x 刻度字（"tick"）的中心（matplotlib 像素）。"""
    app.canvas.draw()
    r_ = app.canvas.get_renderer()
    ax = _ax(p)
    if what == "label":
        bb = ax.xaxis.label.get_window_extent(r_)
    else:
        ts = [t.label1 for t in ax.xaxis.get_major_ticks() if t.label1.get_visible() and t.label1.get_text()]
        bb = ts[len(ts) // 2].get_window_extent(r_)
    return (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2


def _derived_state(sigs):
    return [(s_.uid, s_.panel, s_.derive, s_.src, np.asarray(s_.get_data(), float).copy()) for s_ in sigs]


def _s37_round3(s1, q1, s2, q2, clk):
    """第三輪（2026-10-25 使用者的決定 U1–U8 與第三輪審查 F3–F9）：平移／放大模式點線＝只選那一條；沒有工具列模式點空白＝取消選取；
    四種模式都能拖握把換順序、雙擊收合；點 x 刻度字／標籤＝點那張；刪除不帶走沒被選到的衍生訊號（不管在哪一張）；狀態列；⌘X；y 範圍；焦點在輸入框／資料夾。"""
    from matplotlib.backend_bases import MouseEvent
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    app.v["confirm_clear"].set(True)
    # ---- U1：平移／放大模式點線＝只選那一條（自己選的：加粗、⌘C 只複製它、Delete 只刪它、不問 panel），目前 panel 換成那張
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式")):
        _set_mode(mode)
        tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
        _line_click(q2, 0.5)
        check(_sel_uids() == {q2.uid} and _thick(q2) and app._follow_panel() is None and app.current_panel() == p2,
              f"U1 {name}：點 P2 的「b q」線 → 只選那一條、加粗（自己選的），目前 panel＝P2（{sorted(_sel_uids())}，P{app.current_panel()}）")
        app._sig_clip = []
        app.actions["edit.copy"].run(); app.update()
        check([d.get("uid") for d in app._sig_clip] == [q2.uid], f"U1 {name}：⌘C 只複製點到的那一條（{[d.get('label') or d.get('key') for d in app._sig_clip]}）")
        app._sig_clip = []
        n0 = len(app.signals)
        calls = _with_ask(True, lambda: tk_key(w, "Delete"))
        check(len(app.signals) == n0 - 1 and app.find_signal_by_uid(q2.uid) is None and not calls,
              f"U1 {name}：接著按 Delete（焦點在圖上）→ 只移除那一條、不問「刪除 P2」（{n0} → {len(app.signals)}，{calls}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
        app.show_all_x(); app.update()
        _line_click(s2, 0.3)
        app.show_all_x(); app.update()
        _line_click(q2, 0.6, shift=True)
        check(_sel_uids() == {s2.uid, q2.uid} and _thick(s2) and _thick(q2), f"U1 {name}：Shift＋點另一條線＝加選（{sorted(_sel_uids())}）")
        app.show_all_x(); app.update()
        _click_empty(_ax(p1))
        fol1 = app._follow_panel()
        app.show_all_x(); app.update()
        _line_click(q2, 0.55, shift=True)
        check(fol1 == p1 and _sel_uids() == {q2.uid} and _thick(q2) and app._follow_panel() is None,
              f"U1 {name}：點 P1 空白（清單跟著選 P1）再 Shift＋點 P2 的線＝只選點到的那條（D13；{sorted(_sel_uids())}）")
        app.show_all_x(); app.update()
        tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
        xl0 = tuple(_ax(p2).get_xlim())
        x_, y_ = _line_xy(q2, 0.45)
        _drag_px(x_, y_, 70, 25)
        check(_sel_uids() == {s1.uid} and tuple(_ax(p2).get_xlim()) != xl0,
              f"U1／D6 {name}：從線上開始拖曳＝{'平移' if mode == 'pan' else '拉框放大'}，清單不換（{sorted(_sel_uids())}）")
        app.show_all_x(); app.update()
    # 第 9 項：平移模式點 P1 的一條線之後 AM/PM/FM 分析 P1（單一條不是 I/Q 配對 → 目前 panel，0.9.8 的規則）
    _set_mode("pan")
    _line_click(q1, 0.4)
    win = app.open_iq_window(); app.update()
    check(win is not None and f"— P{p1}：" in win.title() and win.pairs[0][0].uid == s1.uid and win.pairs[0][1].uid == q1.uid,
          f"U1＋第 9 項：平移模式點 P1 的「adc q」線 → AM/PM/FM 分析目前 panel P1（{win.title() if win else app.status_var.get()[:40]}）")
    if win is not None:
        win.destroy(); app.update()
    for opener, what in ((app.open_constellation, "星座圖"), (app.open_gfsk, "GFSK")):
        _line_click(q1, 0.4)
        win = opener(); app.update()
        check(win is not None and f"— P{p1}：" in win.title(),
              f"U1＋第 9 項：平移模式點 P1 的線 → {what}分析目前 panel P1（{win.title() if win else app.status_var.get()[:40]}）")
        if win is not None:
            win.destroy(); app.update()
    # 線上右鍵＝那條線的選單（刪除這條訊號）：平移、資料提示、沒有工具列模式；放大模式照 MATLAB 的模式選單（U5，不改）
    for mode, name in (("pan", "平移模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        menus.clear()
        _line_click(q2, 0.4, button=3)
        check(menus and any("刪除這條訊號" in x for x in menus[-1]) and _sel_uids() == {q2.uid},
              f"{name}：線上按右鍵＝那條線的選單（有「刪除這條訊號」），清單只選那一條")
    _set_mode("zoom")
    menus.clear()
    _line_click(q2, 0.4, button=3)
    check(menus and sv.tr("還原視圖") in menus[-1] and not any("刪除這條訊號" in x for x in menus[-1]),
          f"U5 放大模式：線上按右鍵照 MATLAB 的放大模式選單（{(menus[-1] if menus else [])[:3]}）")
    app.show_all_x(); app.update()
    # ---- U2：沒有工具列模式點空白＝取消清單選取（跟著選的、自己選的都取消），目前 panel 換成那張；只有握把、右鍵點空白會跟著選
    _set_mode("")
    tk_key(w, "Escape"); app.update()
    _handle_press(p2)
    fol_h = app._follow_panel()
    _click_empty(_ax(p1))
    check(fol_h == p2 and not tree.selection() and app._follow_panel() is None and app.current_panel() == p1 and app._sel_panel is None,
          f"U2：握把選 P2（清單跟著）後在 P1 點空白 → 清單選取取消、目前 panel＝P1（{sorted(_sel_uids())}）")
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    _click_empty(_ax(p3))
    check(not tree.selection() and app.current_panel() == p3, "U2：自己在清單選的，點別張空白也取消（0.9.8／MATLAB plot edit）")
    menus.clear()
    _click_empty(_ax(p2), button=3)
    check(app._follow_panel() == p2 and bool(menus), "U2：沒有工具列模式右鍵點空白照樣＝清單跟著選那張（D2）")
    tree.selection_set([f"s{q1.uid}"]); app._on_list_select(); app.update()
    app.canvas.draw()
    lb2 = (app.render_info["axes_right"].get(p2) or _ax(p2)).get_legend().get_window_extent(app.canvas.get_renderer())
    _press_at((lb2.x0 + lb2.x1) / 2, (lb2.y0 + lb2.y1) / 2)
    check(_sel_uids() == {q1.uid} and app.current_panel() == p2, f"U2：沒有工具列模式點圖例不換清單（{sorted(_sel_uids())}）")
    for mode, name in (("pan", "平移模式"), ("tips", "資料提示模式")):
        _set_mode(mode)
        tree.selection_set([f"s{q1.uid}"]); app._on_list_select(); app.update()
        _press_at((lb2.x0 + lb2.x1) / 2, (lb2.y0 + lb2.y1) / 2)
        check(app._follow_panel() == p2, f"D3 {name}：點 P2 的圖例＝清單跟著選 P2")
    app.legend_loc.clear(); app.plot(keep=True); app.update()
    # ---- U3：四種模式都能拖握把換順序、雙擊收合；握把上是手形游標、狀態列寫「拖曳換順序」
    grab = "openhand" if sys.platform == "darwin" else "hand2"
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        tk_key(w, "Escape"); app.update()
        order0 = app.panel_order()
        _handle_press(p3, drag_to=_ax(p1).bbox.y1 - 5)
        moved = app.panel_order()
        if moved != order0:
            app.undo_action(); app.update()
        _handle_dbl(p2)
        coll = p2 in app.panel_collapsed
        if coll:
            app.toggle_panel_collapsed(p2); app.update()
        ax2 = _ax(p2)
        MouseEvent("motion_notify_event", app.canvas, ax2.bbox.x0 - 20, (ax2.bbox.y0 + ax2.bbox.y1) / 2)._process()
        cur_h = str(w.cget("cursor"))
        MouseEvent("motion_notify_event", app.canvas, ax2.bbox.x0 + 0.5 * ax2.bbox.width, ax2.bbox.y0 + 0.5 * ax2.bbox.height)._process()
        cur_in = str(w.cget("cursor"))
        tk_key(w, "Escape"); app.update()
        _handle_press(p2)
        st_ = app.status_var.get()
        check(moved[0] == p3 and app.panel_order() == order0 and coll and cur_h == grab and (cur_in != grab or mode == "pan"),
              f"U3 {name}：拖握把換順序（{order0} → {moved}）、雙擊收合（{coll}）、握把上是手形游標（{cur_h}；座標區裡 {cur_in or '預設'}）")
        check("拖曳換順序" in st_ and app._sel_panel == p2, f"U3 {name}：點握把選取 P2，狀態列照實寫「拖曳換順序」（{st_[:30]}）")
        tk_key(w, "Escape"); app.update()
    _set_mode("zoom")                                       # 放大模式雙擊握把＝收合，不會順便「還原視圖」（MATLAB 的雙擊還原只在座標區裡）
    xa, xb = _ax(p1).get_xlim()
    app.ia.set_xlim(_ax(p1), xa + 0.2 * (xb - xa), xa + 0.4 * (xb - xa), draw=True); app.update()
    xl_z = tuple(_ax(p1).get_xlim())
    _handle_dbl(p3)
    coll3 = p3 in app.panel_collapsed
    xl_z2 = tuple(_ax(p1).get_xlim())
    if coll3:
        app.toggle_panel_collapsed(p3); app.update()
    check(coll3 and all(abs(a - b) < 1e-9 for a, b in zip(xl_z, xl_z2)),
          f"U3 放大模式：雙擊 P3 的握把＝收合，P1 的縮放不被「還原視圖」（{tuple(round(v, 2) for v in xl_z)} → {tuple(round(v, 2) for v in xl_z2)}）")
    tk_key(w, "Escape"); app.show_all_x(); app.update()
    # ---- U7：點某張自己的 x 刻度字或 x 軸標籤＝點那張的空白（平移／放大／資料提示＝跟著選；沒有工具列模式＝取消選取）；拖曳照舊平移 x
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        for what in ("label", "tick"):
            tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
            app._set_current_panel(p3, announce=False); app.update()
            _press_at(*_xlabel_xy(p1, what))
            if mode:
                ok7 = app.current_panel() == p1 and app._follow_panel() == p1
            else:
                ok7 = app.current_panel() == p1 and not tree.selection()
            check(ok7, f"U7 {name}：點 P1 的 x {'軸標籤' if what == 'label' else '刻度字'} → 目前 panel＝P1、清單"
                       f"{'跟著選 P1' if mode else '取消選取'}（P{app.current_panel()}，{sorted(_sel_uids())}）")
    _set_mode("")
    tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
    app._set_current_panel(p3, announce=False)
    xl0 = tuple(_ax(p1).get_xlim())
    tx, ty = _xlabel_xy(p1, "tick")
    _drag_px(tx, ty, 80)
    check(tuple(_ax(p1).get_xlim()) != xl0 and _sel_uids() == {clk.uid},
          "U7：在 P1 的 x 刻度字上拖曳照舊平移 P1 的 x（x 尺規），清單不換")
    app.show_all_x(); app.update()
    # ---- F3：平移／放大模式，清單跟著 P1 時點或右鍵 P2 的資料提示、標註、參考線＝取消跟著選（框、平移器換到 P2）
    _set_mode("tips")
    _line_click(s2, 0.45)
    tip = app.datatips[-1] if app.datatips else None
    xl2 = _ax(p2).get_xlim()
    ann_t = app.add_annotation("text", p2, xl2[0] + 0.7 * (xl2[1] - xl2[0]), 0.0, text="F3 note")
    ann_x = app.add_annotation("xline", p2, xl2[0] + 0.15 * (xl2[1] - xl2[0]))
    app.ia.deselect_tip(); app.ia.select_annotation(None); app.update()
    app.canvas.draw()
    r_ = app.canvas.get_renderer()

    def _obj_xy(kind):
        if kind == "tip":
            return _tip_box_xy(tip.id)
        art = app.ia.ann_artists[(ann_t if kind == "text" else ann_x).id]
        if kind == "text":
            bb = art.get_window_extent(r_)
            return (bb.x0 + bb.x1) / 2, (bb.y0 + bb.y1) / 2
        ax2_ = _ax(p2)
        return float(ax2_.transData.transform((ann_x.value, 0.0))[0]), ax2_.bbox.y0 + 0.2 * ax2_.bbox.height
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式")):
        for kind in ("tip", "text", "refline"):
            for btn in (1, 3):
                _set_mode(mode)
                _click_empty(_ax(p1))
                app.show_all_x(); app.update()
                if tip is None:
                    continue
                menus.clear()
                ox, oy = _obj_xy(kind)
                _press_at(ox, oy, button=btn)
                check(not tree.selection() and app._follow_panel() is None and app.current_panel() == p2,
                      f"F3 {name}：清單跟著 P1 時{'右鍵' if btn == 3 else '點'} P2 的{dict(tip='資料提示', text='文字標註', refline='參考線')[kind]}"
                      f" → 取消跟著選、目前 panel＝P2（{sorted(_sel_uids())}，P{app.current_panel()}）")
                app.show_all_x(); app.update()
    app.ia.clear_tips()
    for a_ in (ann_t, ann_x):
        if a_ is not None:
            app.ia.remove_annotation(a_.id)
    app.update()
    # ---- F4：複製過之後點 panel，狀態列照樣寫「目前 panel：Pn，清單選取它的 N 條訊號」，後面加上 ⌘V 的提示
    _set_mode("pan")
    tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
    app.actions["edit.copy"].run(); app.update()
    _click_empty(_ax(p2)); st2 = app.status_var.get()
    _click_empty(_ax(p2)); st2b = app.status_var.get()
    _click_empty(_ax(p1)); st1 = app.status_var.get()
    check(all("清單選取它的" in x and "⌘V" in x for x in (st2, st2b, st1)) and f"P{p2}" in st2 and f"P{p1}" in st1,
          f"F4：複製過之後點 P2、再點 P2、點 P1，狀態列都寫「目前 panel：Pn，清單選取它的 N 條訊號…；⌘V…」（{st1[:44]}）")
    app._sig_clip = []
    # ---- F5：握把選取後按 Esc、或在清單改選，狀態列不留「已選取 P2：Delete 刪除這個 panel…」
    for mode in ("pan", ""):
        _set_mode(mode)
        _handle_press(p2)
        tk_key(w, "Escape"); app.update()
        st_e = app.status_var.get()
        _handle_press(p2)
        tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
        st_l = app.status_var.get()
        check("已選取 P" not in st_e and "已選取 P" not in st_l and app._sel_panel is None,
              f"F5 {mode or '沒有工具列模式'}：握把選取後 Esc／在清單改選，狀態列不留「已選取 P2：Delete…」（{st_e[:20]}／{st_l[:20]}）")
        tk_key(w, "Escape"); app.update()
    # ---- F6：沒有工具列模式，從線上開始拖曳＝平移、清單不換；點一下（放開時沒拖動）才選那一條
    _set_mode("")
    tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
    xl0 = tuple(_ax(p2).get_xlim())
    x_, y_ = _line_xy(q2, 0.5)
    _drag_px(x_, y_, 60)
    check(_sel_uids() == {s1.uid} and not _thick(q2) and tuple(_ax(p2).get_xlim()) != xl0,
          f"F6：沒有工具列模式從 P2 的線上開始拖曳平移 → 清單不換、線不加粗（{sorted(_sel_uids())}）")
    app.show_all_x(); app.update()
    _follow(p1)
    x_, y_ = _line_xy(q2, 0.5)
    _drag_px(x_, y_, 60)
    check(app._follow_panel() == p2, "F6／D7：清單跟著 P1 時從 P2 的線上拖曳 → 清單跟著換到 P2（框、平移器、清單一致）")
    app.show_all_x(); app.update()
    x_, y_ = _line_xy(q2, 0.5)
    _press_at(x_, y_, moves=[(x_ + 3, y_ + 2), (x_ + 5, y_ + 3)])
    check(_sel_uids() == {q2.uid} and _thick(q2), "F6：在線上按下、手抖 5 px 放開＝點一下，選那一條")
    # ---- F7：焦點在「資料夾」檔案樹或輸入框時，Delete／⌫ 給那個元件（檔案樹照舊只提示、不刪 panel）；在圖／清單／平移器上才刪
    _set_mode("pan")
    _click_empty(_ax(p2))
    n0 = len(app.signals)
    calls_t = _with_ask(True, lambda: tk_key(app.file_tree, "Delete"))
    st_t = app.status_var.get()
    ent = next((x for x in _walk(app) if x.winfo_class() == "TEntry"), None)
    txt0 = ent.get() if ent is not None else ""
    calls_e = _with_ask(True, lambda: tk_key(ent, "BackSpace")) if ent is not None else ["no entry"]
    if ent is not None:                                     # ⌫ 真的刪了輸入框的一個字：放回去
        ent.delete(0, "end"); ent.insert(0, txt0)
    check(len(app.signals) == n0 and not calls_t and not calls_e and app._follow_panel() == p2 and "資料夾面板" in st_t,
          f"F7：焦點在資料夾檔案樹／輸入框按 Delete／⌫ → 給那個元件（不問、不刪 P2；{st_t[:24]}）")
    # ---- F8：清單什麼都沒反白時 ⌘X 不剪任何訊號（只認選取中的資料提示）；⌘C 照舊用最近釘的提示
    _set_mode("tips")
    _line_click(q2, 0.5)
    app.ia.deselect_tip(); app.update()
    _set_mode("pan")
    _click_empty(_ax(p1))
    tk_key(w, "Escape"); app.update()
    n0 = len(app.signals)
    _with_ask(True, lambda: app.actions["edit.cut"].run())
    cut_n = n0 - len(app.signals)
    if cut_n:
        app.undo_action(); app.update()
    app._sig_clip = []
    app.actions["edit.copy"].run(); app.update()
    check(cut_n == 0 and [d.get("uid") for d in app._sig_clip] == [q2.uid],
          f"F8：清單沒反白、提示沒選取時 ⌘X 不剪（剪了 {cut_n} 條）；⌘C 照舊複製最近釘的提示那條")
    app._sig_clip = []
    app.ia.clear_tips(); app.update()
    # ---- F9：刪除 panel 不會把別張手動調過的 y 範圍重設；⌘Z 回到刪除前一模一樣的視圖
    _set_mode("pan")
    app.v["confirm_clear"].set(False)
    ax2 = _ax(p2)
    fx, fy = _empty_at(ax2)
    _drag_px(ax2.bbox.x0 + fx * ax2.bbox.width, ax2.bbox.y0 + fy * ax2.bbox.height, 0, -40)
    y2 = tuple(_ax(p2).get_ylim())
    views0 = app._view_state()
    app.delete_panel(p3); app.update()
    y2d = tuple(_ax(p2).get_ylim())
    app.undo_action(); app.update()
    views1 = app._view_state()
    same = set(views0) == set(views1) and all(all(abs(a - b) < 1e-9 for a, b in zip(views0[k][0] + views0[k][1], views1[k][0] + views1[k][1]))
                                              for k in views0)
    check(y2d == y2 and same, f"F9：P2 手動調過 y（{tuple(round(v, 3) for v in y2)}），刪除 P3 後不變（{tuple(round(v, 3) for v in y2d)}）；⌘Z 回到刪除前的視圖（{same}）")
    app.show_all_x(); app.plot(keep=True); app.update()
    app.v["confirm_clear"].set(True)
    # ---- U8：刪除（任何入口）不帶走沒被選到的衍生訊號（不管在哪一張；這裡放在別張，同一張的在 s37m）：改成獨立訊號、保留現在的資料；⌘Z 連來源連結一起回來；詢問寫的條數＝真的刪掉的
    _set_mode("pan")
    tree.selection_set([f"s{s2.uid}", f"s{q2.uid}"]); app._on_list_select(); app.update()
    new_d = app.add_iq_magphase(); app.update()
    der = [x for x in app.signals if x.derive and set(x.src_uids) == {s2.uid, q2.uid}]
    st_d0 = _derived_state(der)

    def _u8(label, fn, removed, answer=True):
        n0_ = len(app.signals)
        calls_ = _with_ask(answer, fn)
        now = [app.find_signal_by_uid(u) for u, *_r in st_d0]
        kept = all(x is not None and not x.derive and x.src == "" and np.allclose(np.asarray(x.get_data(), float), d_, equal_nan=True)
                   for x, (_u, _p, _dv, _src, d_) in zip(now, st_d0))
        gone = n0_ - len(app.signals)
        app.undo_action(); app.update()
        back = [app.find_signal_by_uid(u) for u, *_r in st_d0]
        linked = all(x is not None and x.derive == dv and x.src == src and np.allclose(np.asarray(x.get_data(), float), d_, equal_nan=True)
                     for x, (_u, _p, dv, src, d_) in zip(back, st_d0))
        q_ = [str(c[1][1]) for c in calls_ if c[0].startswith("ask")]
        exact = all(f"（{removed} 條訊號）" in t for t in q_)
        check(len(der) == 2 and kept and gone == removed and linked and exact,
              f"U8 {label}：只刪 {removed} 條（實際 {gone}），P{der[0].panel if der else '?'}／P{der[-1].panel if der else '?'} 的衍生訊號留著、"
              f"改成獨立訊號、資料一樣（{kept}）；⌘Z 連結回來（{linked}）；詢問 {q_}")
    _u8("panel 左上角 ×（delete_panel）", lambda: app.delete_panel(p2), 2)
    _u8("握把選取＋Delete", lambda: (_handle_press(p2), tk_key(w, "Delete")), 2)
    _u8("點 panel 空白（跟著選）＋Delete", lambda: (_click_empty(_ax(p2)), tk_key(w, "Delete")), 2)
    _u8("點 panel 空白（跟著選）＋⌫（焦點在清單）", lambda: (_click_empty(_ax(p2)), tk_key(tree, "BackSpace")), 2)
    _u8("點 panel 空白（跟著選）＋工具列「移除」", lambda: (_click_empty(_ax(p2)), [b for b in app._sel_btns if str(b.cget("text")) == sv.tr("移除")][0].invoke()), 2)
    _u8("點 panel 空白（跟著選）＋⌘X", lambda: (_click_empty(_ax(p2)), app.actions["edit.cut"].run()), 2)
    _u8("清單自己選的「b q」＋Delete", lambda: (tree.selection_set([f"s{q2.uid}"]), app._on_list_select(), tk_key(tree, "Delete")), 1)
    _u8("線上右鍵「刪除這條訊號」", lambda: app.remove_signal_by_uid(s2.uid), 1)
    app._sig_clip = []
    if new_d:
        app._remove_signals(list(new_d)); app.update()
    # ---- U6：量測面板沒有選取時量全部（和匯出 TXT、頻譜同一個「全部」）；D15：點過 panel 只量那張，Esc／⌘A 回到全部
    app.v_panel["meas"].set(True); app._toggle_panel("meas"); app.update()
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    tree.selection_set([]); app._on_list_select(); app.update()
    h0 = list(app.update_measurements()[0])
    info0 = app.meas_info.get()
    _click_empty(_ax(p2))
    h2 = list(app.update_measurements()[0])
    exp_dir = os.path.join(OUT, "d15_txt")
    shutil.rmtree(exp_dir, ignore_errors=True); os.makedirs(exp_dir)
    app.export_txt(folder=exp_dir, open_folder=False)
    n_txt2 = len(os.listdir(exp_dir))
    tk_key(w, "Escape"); app.update()
    hE = list(app.update_measurements()[0])
    shutil.rmtree(exp_dir, ignore_errors=True); os.makedirs(exp_dir)
    app.export_txt(folder=exp_dir, open_folder=False)
    n_txtE = len(os.listdir(exp_dir))
    allv = [x.name for x in app.target_signals()][:sv.MEAS_MAX_SIGNALS]
    check(h0[1:] == allv and "量測全部" in info0 and h2[1:] == [x.name for x in app.signals if x.panel == p2] and hE[1:] == allv
          and n_txt2 == len(_panel_uids(p2)) and n_txtE == len(app.signals),
          f"U6／D15：沒有選取時量測面板量全部（{len(h0) - 1} 條，「{info0[-16:]}」）；點 P2 只量 P2（{len(h2) - 1}）、匯出 TXT 只出 P2（{n_txt2}）；"
          f"Esc 回到全部（{len(hE) - 1}／{n_txtE}）")
    app.v_panel["meas"].set(False); app._toggle_panel("meas"); app.update()
    # ---- D18：反方向不做：在清單選 P1 的訊號，目前 panel 不換
    app._set_current_panel(p2, announce=False)
    tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
    check(app.current_panel() == p2, "D18：在清單選 P1 的訊號不會把目前 panel 換成 P1（反方向不做）")
    # ---- F14：拖放到最下面那張的 x 刻度數字、「x [單位]」標籤上＝加到那張（字級 10／16／20 pt）；再下面的留白＝新增 panel
    font0 = app.v["plot_font_pt"].get()
    got14 = []
    for pt in ("10", "16", "20"):
        app.v["plot_font_pt"].set(pt); app.plot(keep=True); app.update()
        app.plot_scroll.yview_moveto(1.0); app.update()
        app.canvas.draw()
        r_ = app.canvas.get_renderer()
        H = app.fig.bbox.height
        axl = app.render_info["axes"][-1]
        pl = app.render_info["panels"][-1]
        ts = [t.label1.get_window_extent(r_) for t in axl.xaxis.get_major_ticks() if t.label1.get_visible() and t.label1.get_text()]
        lb = axl.xaxis.label.get_window_extent(r_)
        pts = {"tick_mid": ((ts[1].x0 + ts[1].x1) / 2, (ts[1].y0 + ts[1].y1) / 2), "tick_bot": ((ts[1].x0 + ts[1].x1) / 2, ts[1].y0 + 1),
               "label_bot": ((lb.x0 + lb.x1) / 2, lb.y0 + 1), "below": ((lb.x0 + lb.x1) / 2, 3.0)}
        for nm, (xx, yy) in pts.items():
            xr = w.winfo_rootx() + xx                       # TkAgg：Tk 畫布像素＝matplotlib 像素（W10）
            yr = w.winfo_rooty() + (H - yy)
            got14.append((pt, nm, app.drop_target(int(xr), int(yr))))
        ok14 = all(g == ("panel", pl) for p_, nm, g in got14 if p_ == pt and nm != "below") and \
            any(g[0] == "new" for p_, nm, g in got14 if p_ == pt and nm == "below")
        check(ok14, f"F14 {pt} pt：拖放到最下面那張的刻度數字、x 軸標籤上＝加到那張；標籤下面的留白＝新增 panel（{[(nm, g) for p_, nm, g in got14 if p_ == pt]}）")
    app.v["plot_font_pt"].set(font0); app.plot(keep=True); app.plot_scroll.yview_moveto(0); app.update()
    _set_mode("")
    tk_key(w, "Escape"); app.update()


def _s37_round3_layout(s1, q1, s2, q2, clk):
    """第三輪（版面）：存成圖檔退回 0.9.8 的標法時狀態列提示（D20／F1）、用目前大小存（低 DPI）不退回（F12）、只匯出這個 panel 照樣標（F2）、
    圖例用實際的高（F11）。"""
    extra = []
    for k in range(2):                                    # 5 張連結、單位一樣：存成 8×4 in 放不下每張的標籤
        pth = os.path.join(OUT, f"r3_more{k}.csv")
        with open(pth, "w", encoding="utf-8") as f:
            f.write(f"r{k} a,r{k} b\n" + "\n".join(f"{math.sin(j / (6.0 + k)):.5f},{math.cos(j / (7.0 + k)):.5f}" for j in range(500)) + "\n")
        app.add_csv_columns_direct(pth, None)
    app.refresh_list(); app.plot(keep=True); app.update()
    extra = [x for x in app.signals if os.path.basename(x.path or "").startswith("r3_more")]
    dlg = app.save_figure_dialog(); app.update()
    dlg.v_unit.set("in"); dlg.v_w.set("8"); dlg.v_h.set("4"); dlg._refresh()
    dlg.export(os.path.join(OUT, "r3_8x4.png")); app.update()
    st_ = app.status_var.get()
    hint = sv.tr("這個大小放不下每張 panel 的 x 軸標籤，這次匯出只在最下面標；要每張都標請加大高度")
    check(len(app.panel_order()) == 5 and hint in st_ and os.path.isfile(os.path.join(OUT, "r3_8x4.png")),
          f"D20／F1：5 張存成 8×4 in → 退回 0.9.8 的標法，狀態列提示「{hint[:16]}…」（{st_[-40:]}）")
    dlg = app.save_figure_dialog(); app.update()
    dlg.v_unit.set("in"); dlg.v_w.set("12"); dlg.v_h.set("12"); dlg._refresh()
    dlg.export(os.path.join(OUT, "r3_12x12.png")); app.update()
    st_b = app.status_var.get()
    dlg = app.save_figure_dialog(); app.update()
    dlg.v_dpi.set("41"); dlg._refresh()
    dlg.export(os.path.join(OUT, "r3_cur41.png")); app.update()
    st_c = app.status_var.get()
    le = app.render_info["layout"].last_export or {}
    check("放不下" not in st_b and "放不下" not in st_c and "太矮" not in st_c and not le.get("fallback") and all(le.get("labeled") or [True]),
          f"F12：存成 12×12 in、用目前大小存 41 dpi → 每張都標、狀態列沒有提示（{st_c[-30:]}）")
    ax1 = app.render_info["axes"][0]
    seen = {}
    orig = app.fig.savefig

    def spy(*a, **k):
        seen["p1"] = (ax1.xaxis.label.get_visible(), _xlabels_on(ax1))
        return orig(*a, **k)
    app.fig.savefig = spy
    try:
        dlg = app.ia.export_axes_dialog(ax1); app.update()
        dlg.v_unit.set("in"); dlg.v_w.set("8"); dlg.v_h.set("4"); dlg._refresh()
        dlg.export(os.path.join(OUT, "r3_P1_8x4.png")); app.update()
    finally:
        del app.fig.savefig
    check(seen.get("p1") == (True, True) and "放不下" not in app.status_var.get(),
          f"F2：「只匯出這個 panel」（P1，整張圖 8×4 in）→ P1 有自己的 x 刻度字與 x 軸標籤、不退回（{seen}）")
    app._remove_signals(extra); app.update()
    # F11：中文標籤的圖例（12 條）：那一張照實際量到的圖例高度加高，圖例不超出自己的座標區（不蓋到自己的 x 刻度字）
    pth = os.path.join(OUT, "r3_cjk.csv")
    with open(pth, "w", encoding="utf-8") as f:
        f.write(",".join(f"通道{k:02d}增益" for k in range(12)) + "\n"
                + "\n".join(",".join(f"{math.sin(j / (5.0 + k)):.4f}" for k in range(12)) for j in range(300)) + "\n")
    app.add_csv_columns_direct(pth, None)
    app.refresh_list(); app.plot(keep=True); app.update()
    cjk = [x for x in app.signals if os.path.basename(x.path or "") == "r3_cjk.csv"]
    pc = cjk[0].panel if cjk else None
    ph0 = app.v["panel_height"].get()
    app.v["panel_height"].set("0.5"); app.plot(keep=True); app.update()
    app.canvas.draw()
    r_ = app.canvas.get_renderer()
    axc = _ax(pc)
    lg = (app.render_info["axes_right"].get(pc) or axc).get_legend().get_window_extent(r_)
    mins_c = (app.render_info.get("legend_mins") or {}).get(pc)
    check(cjk and mins_c is not None and lg.y0 >= axc.bbox.y0 - 0.5,
          f"F11：12 條中文標籤的圖例照實際的高（{mins_c or 0:.2f} in）加高那一張，圖例不超出座標區（下緣差 {lg.y0 - axc.bbox.y0:.1f} px）")
    app.v["panel_height"].set(ph0)
    app._remove_signals(cjk); app.update()


def _close_xy(p):
    """panel p 左上角 × 的中心（matplotlib 像素，原點左下）。"""
    app._draw_panel_ui(); app.update()
    w = app.canvas.get_tk_widget()
    b = w.bbox(app._close_items[p])                   # Tk 畫布座標 → matplotlib 像素：TkAgg 同一套像素，只上下翻（W10）
    return (b[0] + b[2]) / 2, app.fig.bbox.height - (b[1] + b[3]) / 2


def _motion_to(x, y):
    """滑鼠移到主圖的 matplotlib 像素 (x, y)（走主圖全部的 motion 回呼，包括工具列的），回傳畫布現在的游標。"""
    from matplotlib.backend_bases import MouseEvent
    MouseEvent("motion_notify_event", app.canvas, x, y)._process()
    app.update_idletasks()
    return str(app.canvas.get_tk_widget().cget("cursor") or "")


_TREE_T = [int(time.monotonic() * 1000) & 0x3FFFFFFF]


def _tree_click(uid):
    """在「已繪訊號」清單點一下那一列的名稱（真的 Tk 按下／放開：Treeview 自己換選取 → <<TreeviewSelect>>）。
    事件時間每次往後 1.5 秒：不給時間（都是 0）的話，同一個位置的第二次按下會被 Tk 當成雙擊（<Double-1>），<Button-1> 不會跑。"""
    tree = app.sig_tree
    iid = f"s{uid}"
    tree.see(iid); app.update()
    bb = tree.bbox(iid, "#3") or tree.bbox(iid)
    x, y = bb[0] + 5, bb[1] + bb[3] // 2
    _TREE_T[0] += 1500
    tree.event_generate("<ButtonPress-1>", x=x, y=y, when="now", time=_TREE_T[0])
    tree.event_generate("<ButtonRelease-1>", x=x, y=y, state=0x100, when="now", time=_TREE_T[0] + 5)
    app.update()


def _views_reset():
    """x 回到全部、y 回到自動（放大模式點一下會放大 x、y）。"""
    app.show_all_x(); app.plot(keep=True); app.update()


def _peak_tip_outside(sig):
    """資料提示模式在 sig 的線上（座標區上緣附近的峰值）釘一個提示，提示框有一部分在座標區上緣之外（釘在峰值的提示框常這樣）；回傳提示。"""
    _set_mode("tips")
    app.sig_tree.selection_set([]); app._on_list_select(); app.update()
    app.canvas.draw()
    a = app.render_info["artists"][sig.uid]
    ln, ax = a["line"], a["ax"]
    xd, yd = np.asarray(ln.get_xdata(), float), np.asarray(ln.get_ydata(), float)
    lo, hi = sorted(ax.get_xlim())
    idx = np.nonzero((xd >= lo + 0.1 * (hi - lo)) & (xd <= lo + 0.6 * (hi - lo)) & np.isfinite(yd))[0]
    k = idx[int(np.argmax(yd[idx]))]
    if os.name == "nt":                          # Windows（W-E）：最高的那點常在圖例底下（字大、座標區窄）——照高度往下找第一個點得到這條線的
        from matplotlib.backend_bases import MouseEvent
        for k_ in idx[np.argsort(-yd[idx], kind="stable")][:400]:
            h_ = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, *ax.transData.transform((xd[k_], yd[k_]))))
            if h_.kind == "line" and h_.id == sig.uid:
                k = int(k_)
                break
    _press_at(*ax.transData.transform((xd[k], yd[k])))
    tip = app.datatips[-1]
    for _ in range(3):
        bb, top = _tip_bb(tip.id), _ax(sig.panel).bbox.y1
        if bb.y1 > top + 10:
            break
        tip.offset = (tip.offset[0], tip.offset[1] + (top + 16 - bb.y1) / app.fig.dpi * 72.0 + 4)
        app.plot(keep=True); app.update()
    app.ia.deselect_tip(); app.update()
    return tip


def _tip_bb(tid):
    app.canvas.draw()
    ann = app.ia.tip_artists[tid][0]
    return ann.get_bbox_patch().get_window_extent(app.canvas.get_renderer())


def _tip_out_xy(tip, p):
    """提示框在 panel p 的座標區上緣之外那一部分的中心。"""
    bb, top = _tip_bb(tip.id), _ax(p).bbox.y1
    return (bb.x0 + bb.x1) / 2, (max(bb.y0, top) + bb.y1) / 2


def _s37_round4(s1, q1, s2, q2, clk):
    """第四輪審查（2026-10-25）：剪下／刪掉目前 panel 之後點最上面那張再 ⌘V 貼到那張；握把上的手形游標（平移、拉框過之後）；
    座標區外的資料提示框、圖例算它自己那張（D22／F3／D3）；雙擊 × 只刪一張；平移／放大模式在清單自己選的照 0.9.8 不從圖上刪；
    衍生訊號和來源一起剪下貼上有資料；刪資料提示／標註的 ⌘Z 不重設別張的 y；凍結檔不越積越多；檔案樹裡 ⌘X 不剪訊號；右鍵點 x 刻度字。"""
    from matplotlib.backend_bases import MouseEvent
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    app.v["confirm_clear"].set(True)
    # ---- 剪下（或 ⌘C＋按 ×）目前 panel P2 之後點最上面那張 P1 再 ⌘V＝貼到 P1，不是開一張新的（四種模式；以前 _current_panel
    #      還指著不在的 P2，點最上面那張時 current_panel() 回的也是 P1，就不記下來）
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        for how in ("cut", "copy_close"):
            _set_mode(mode)
            tk_key(w, "Escape"); app.update()
            app._sig_clip = []
            _follow(p2)
            if mode == "zoom":
                app.show_all_x(); app.update()
            if how == "cut":
                _with_ask(True, lambda: app.actions["edit.cut"].run())
            else:
                app.actions["edit.copy"].run(); app.update()
                cx, cy = _close_xy(p2)
                _with_ask(True, lambda: _press_at(cx, cy))
            gone = p2 not in app.panel_order()
            _click_empty(_ax(p1))
            if mode == "zoom":
                app.show_all_x(); app.update()
            st1 = app.status_var.get()
            uids0 = {x.uid for x in app.signals}
            app.actions["edit.paste"].run(); app.update()
            into = sorted({x.panel for x in app.signals if x.uid not in uids0})
            app.undo_action(); app.undo_action(); app.update()
            check(gone and into == [p1] and p2 in app.panel_order() and f"P{p1}" in st1,
                  f"第四輪 {name}：點 P2 → {'⌘X' if how == 'cut' else '⌘C＋按 P2 的 ×'} → 點最上面的 P1 → ⌘V＝貼到 P1（貼到 {into}；{st1[:24]}）")
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    app._current_panel = None                               # 剛啟動、剛還原工作階段：還沒點過任何 panel
    tree.selection_set([f"s{s2.uid}", f"s{q2.uid}"]); app._on_list_select(); app.update()
    app.actions["edit.copy"].run(); app.update()
    _click_empty(_ax(p1))
    uids0 = {x.uid for x in app.signals}
    app.actions["edit.paste"].run(); app.update()
    into = sorted({x.panel for x in app.signals if x.uid not in uids0})
    if into:
        app.undo_action(); app.update()
    check(into == [p1], f"第四輪：還沒點過 panel 時在清單選 P2 的兩條 → ⌘C → 點最上面的 P1 → ⌘V＝貼到 P1（貼到 {into}）")
    app._sig_clip = []
    # ---- U3：平移模式在圖上按過一次（matplotlib 平移把工具列的 motion 回呼接到最後面）之後，握把上照樣是手形游標；放大模式也一樣
    grab = "openhand" if sys.platform == "darwin" else "hand2"
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式")):
        _set_mode("pan")
        _click_empty(_ax(p2))
        x2, y2 = _ax(p2).bbox.x0 + 0.5 * _ax(p2).bbox.width, _ax(p2).bbox.y0 + 0.97 * _ax(p2).bbox.height
        _drag_px(x2, y2, 60)                                 # 也拖曳平移一次
        app.show_all_x(); app.update()
        _set_mode(mode)
        a1 = _ax(p1)
        yc = a1.bbox.y0 + 0.5 * a1.bbox.height
        seq = [_motion_to(a1.bbox.x0 + dx, yc) for dx in (40, 8, -4, -12, -20, -28, -12)]
        inside = _motion_to(a1.bbox.x0 + 40, yc)
        check(all(c == grab for c in seq[2:]) and (mode == "pan" or inside != grab),
              f"U3 {name}：平移模式按過、拖過圖之後，從座標區移到 P1 的握把上照樣是手形游標（{seq[2:]}；回到座標區 {inside}）")
    tk_key(w, "Escape"); app.update()
    # ---- D22／F3：釘在峰值、提示框在座標區上緣之外的資料提示，點（右鍵）在框外面那一半也算 P2 的提示：清單跟著 P1 時取消跟著選、
    #      目前 panel＝P2，之後按 Delete 不會刪 P1（四種模式）
    tip = _peak_tip_outside(s2)
    bb0, top0 = _tip_bb(tip.id), _ax(p2).bbox.y1
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        for btn in (1, 3):
            _set_mode(mode)
            tk_key(w, "Escape"); app.update()
            _follow(p1)
            if mode == "zoom":
                _views_reset()
            fol = app._follow_panel()
            menus.clear()
            _press_at(*_tip_out_xy(tip, p2), button=btn)
            ok = fol == p1 and not tree.selection() and app._follow_panel() is None and app.current_panel() == p2
            n0 = len(app.signals)
            if btn == 3:
                app.v["confirm_clear"].set(False)
                tk_key(w, "Delete"); app.update()
                app.v["confirm_clear"].set(True)
            n1 = len(app.signals)
            if n1 < n0:
                app.undo_action(); app.update()
            app.ia.deselect_tip(); app.update()
            check(ok and n1 == n0 and bb0.y1 > top0,
                  f"D22／F3 {name}：清單跟著 P1 時{'右鍵' if btn == 3 else '點'} P2 的資料提示框伸出座標區上緣的那一半 → 取消跟著選、目前 panel＝P2"
                  f"{'，接著 Delete 不刪 P1' if btn == 3 else ''}（P{app.current_panel()}，{sorted(_sel_uids())}，{n0}→{n1}）")
    _set_mode("")
    _handle_press(p1)
    selp = app._sel_panel
    _press_at(*_tip_out_xy(tip, p2))
    check(selp == p1 and app._sel_panel is None and app._follow_panel() is None and app.current_panel() == p2,
          f"D22 沒有工具列模式：握把選取 P1 後點 P2 伸出座標區的資料提示框 → 握把選取、跟著選都取消，目前 panel＝P2（{app._sel_panel}）")
    app.ia.clear_tips(); app.update()
    # ---- D3：圖例拖到一半在座標區外（下緣之下）：點外面那一半也算點那張（目前 panel 換成它；平移／放大／資料提示模式清單跟著它）
    _set_mode("")
    tk_key(w, "Escape"); app.update()
    app.canvas.draw()
    lb = (app.render_info["axes_right"].get(p2) or _ax(p2)).get_legend().get_window_extent(app.canvas.get_renderer())
    _drag_px((lb.x0 + lb.x1) / 2, (lb.y0 + lb.y1) / 2, 0, (_ax(p2).bbox.y0 + 2) - (lb.y0 + lb.y1) / 2)
    app.canvas.draw()
    lb = (app.render_info["axes_right"].get(p2) or _ax(p2)).get_legend().get_window_extent(app.canvas.get_renderer())
    out_xy = ((lb.x0 + lb.x1) / 2, lb.y0 + 3)
    below = out_xy[1] < _ax(p2).bbox.y0
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        tk_key(w, "Escape"); app.update()
        _follow(p1)
        if mode == "zoom":
            app.show_all_x(); app.update()
        _press_at(*out_xy)
        ok3 = app.current_panel() == p2 and (app._follow_panel() == p2 if mode else True)
        check(below and ok3, f"D3 {name}：點 P2 的圖例在座標區外的那一半＝點 P2（目前 panel P{app.current_panel()}，清單跟著 {app._follow_panel()}）")
        if mode == "zoom":
            app.show_all_x(); app.update()
    app.legend_loc.clear(); app.plot(keep=True); app.update()
    # ---- U7b（2026-10-25 使用者決定，取代第四輪「右鍵點 x 刻度字沒有作用」）：右鍵點 P1 的 x 刻度字＝右鍵點 P1 的空白——
    #      平移模式出 MATLAB 平移模式的選單、目前 panel＝P1、清單跟著選 P1（四種模式的完整檢查在 _s37_round5）
    _set_mode("pan")
    tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
    app._set_current_panel(p3, announce=False)
    menus.clear()
    _press_at(*_xlabel_xy(p1, "tick"), button=3)
    check(menus and sv.tr("還原視圖") in menus[-1] and _sel_uids() == _panel_uids(p1) and app._follow_panel() == p1 and app.current_panel() == p1,
          f"U7b：平移模式右鍵點 P1 的 x 刻度字＝右鍵點 P1 的空白：MATLAB 平移模式的選單、目前 panel＝P1、清單跟著選 P1（{menus[-1] if menus else None}）")
    tk_key(w, "Escape"); app.update()
    # ---- 「清空前確認」關著時雙擊最上面那張的 ×：只刪那一張，第二下不會把換上來的那張收合（平移模式、沒有工具列模式）
    app.v["confirm_clear"].set(False)
    for mode, name in (("pan", "平移模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        x_, y_ = _close_xy(p1)
        MouseEvent("button_press_event", app.canvas, x_, y_, button=1)._process()
        MouseEvent("button_release_event", app.canvas, x_, y_, button=1)._process()
        app.update()
        MouseEvent("button_press_event", app.canvas, x_, y_, button=1, dblclick=True)._process()
        MouseEvent("button_release_event", app.canvas, x_, y_, button=1)._process()
        app.update()
        gone, coll = p1 not in app.panel_order(), sorted(app.panel_collapsed)
        if gone:
            app.undo_action(); app.update()
        for p_ in list(app.panel_collapsed):
            app.toggle_panel_collapsed(p_); app.update()
        check(gone and not coll and p1 in app.panel_order(),
              f"第四輪 {name}：「清空前確認」關著時雙擊 P1 的 × → 只刪 P1，換上來的那張不會被收合（收合的 {coll}）；⌘Z 回來")
    # ---- 平移／放大模式、焦點在圖上：在清單自己選的（點選、⌘A）照 0.9.8 不刪；在圖上點線選到的照樣刪（U1），⌘Z 之後再按也刪
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式")):
        _set_mode(mode)
        tk_key(w, "Escape"); app.update()
        _line_click(q2, 0.5)                                    # 先在圖上點過這條線，再到清單點它那一列（在清單自己選的）
        if mode == "zoom":
            app.show_all_x(); app.update()
        _tree_click(q2.uid)
        n0 = len(app.signals)
        tk_key(w, "Delete"); app.update()
        n1 = len(app.signals)
        if n1 < n0:
            app.undo_action(); app.update()
        app.actions["edit.select_all"].run(); app.update()
        n2 = len(app.signals)
        tk_key(w, "BackSpace"); app.update()
        n3 = len(app.signals)
        if n3 < n2:
            app.undo_action(); app.update()
        check(n1 == n0 and n3 == n2,
              f"第四輪 {name}：在清單自己選的（點選一條、⌘A 全選）焦點在圖上按 Delete／⌫ 照 0.9.8 不刪（{n0}→{n1}、{n2}→{n3}）")
        tk_key(w, "Escape"); app.update()
        _line_click(q2, 0.5)
        if mode == "zoom":
            app.show_all_x(); app.update()
        n0 = len(app.signals)
        tk_key(w, "Delete"); app.update()
        d1 = n0 - len(app.signals)
        if d1:
            app.undo_action(); app.update()
        back = _sel_uids()
        tk_key(w, "Delete"); app.update()
        d2 = n0 - len(app.signals)
        if d2:
            app.undo_action(); app.update()
        check(d1 == 1 and back == {q2.uid} and d2 == 1,
              f"U1 {name}：在圖上點線選到的，焦點在圖上按 Delete 只刪它；⌘Z 回來（照樣選著）再按 Delete 照樣刪（{d1}、{d2}）")
        app.show_all_x(); app.update()
    # ---- 衍生訊號和它的來源一起剪下再貼上：貼過去的衍生訊號改指貼上的來源、有資料（以前指著剪掉的舊訊號，貼過去是空的）
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    tree.selection_set([f"s{s2.uid}", f"s{q2.uid}"]); app._on_list_select(); app.update()
    new_d = app.add_iq_magphase(); app.update()
    mag = next((x for x in new_d if x.derive == "iq_mag"), None)
    ph = next((x for x in new_d if x.derive and x.derive != "iq_mag"), None)
    ok_j = []
    if mag is not None and ph is not None:
        ph.panel = p2                                          # 相位放進 P2（和來源同一張，像「編輯 Panel…」）
        app.refresh_list(); app.plot(keep=True); app.update()
        _follow(p2)
        uids0 = {x.uid for x in app.signals}
        _with_ask(True, lambda: app.actions["edit.cut"].run())
        _click_empty(_ax(p3))
        app.actions["edit.paste"].run(); app.update()
        pasted = [x for x in app.signals if x.uid not in uids0]
        pd = next((x for x in pasted if x.derive), None)
        plain = {x.uid for x in pasted if not x.derive}
        ok_j.append(len(pasted) == 3 and pd is not None and set(pd.src_uids) == plain and len(np.asarray(pd.get_data())) > 0
                    and all(x.panel == p3 for x in pasted))
        app.undo_action(); app.undo_action(); app.update()
        tree.selection_set([f"s{q2.uid}", f"s{mag.uid}"]); app._on_list_select(); app.update()    # 自己選的：一條來源＋它的衍生訊號
        uids0 = {x.uid for x in app.signals}
        app.actions["edit.cut"].run(); app.update()
        _click_empty(_ax(p3))
        app.actions["edit.paste"].run(); app.update()
        pasted = [x for x in app.signals if x.uid not in uids0]
        pd = next((x for x in pasted if x.derive), None)
        pq = next((x for x in pasted if not x.derive), None)
        ok_j.append(pd is not None and pq is not None and set(pd.src_uids) == {s2.uid, pq.uid} and len(np.asarray(pd.get_data())) > 0)
        app.undo_action(); app.undo_action(); app.update()
        tree.selection_set([f"s{mag.uid}"]); app._on_list_select(); app.update()                  # 只複製衍生訊號，之後來源被刪掉
        app.actions["edit.copy"].run(); app.update()
        app.delete_panel(p2); app.update()
        _click_empty(_ax(p3))
        uids0 = {x.uid for x in app.signals}
        app.actions["edit.paste"].run(); app.update()
        pasted = [x for x in app.signals if x.uid not in uids0]
        ok_j.append(len(pasted) == 1 and not pasted[0].derive and len(np.asarray(pasted[0].get_data())) == len(np.asarray(mag.get_data()))
                    and "改成獨立訊號" in app.status_var.get())
        app.undo_action(); app.undo_action(); app.update()
    check(len(ok_j) == 3 and all(ok_j),
          f"第四輪：衍生訊號和來源一起剪下（跟著選 P2、自己選的）貼到 P3，貼過去的衍生訊號改指貼上的來源、有資料；只複製衍生訊號、來源被刪掉之後貼上，"
          f"用複製那時的資料改成獨立訊號（{ok_j}）")
    # ---- 凍結檔：反覆「刪除 P2（別張有它的衍生訊號）→ ⌘Z」只存一份，不會越積越多；測試寫在測試目錄
    fdir = sv.frozen_data_dir()

    def _nfiles():
        return len([f for f in os.listdir(fdir) if f.endswith(".npy")]) if os.path.isdir(fdir) else 0
    counts = []
    for _ in range(3):
        app.delete_panel(p2); app.update()
        counts.append(_nfiles())
        app.undo_action(); app.update()
    check(os.path.abspath(fdir).startswith(os.path.abspath(OUT)) and counts[0] >= 1 and len(set(counts)) == 1,
          f"U8：反覆「刪除 P2 → ⌘Z」，改成獨立訊號的 .npy 不會越積越多（{counts} 個，在測試目錄）")
    live = [app.find_signal_by_uid(x.uid) for x in new_d]
    app._remove_signals([x for x in live if x is not None]); app.update()
    # ---- 刪掉資料提示、標註再 ⌘Z：別張手動調過的 y 範圍不變（第 8 項：每張各自縮放）
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    ax1 = _ax(p1)
    fx, fy = _empty_at(ax1)
    _drag_px(ax1.bbox.x0 + fx * ax1.bbox.width, ax1.bbox.y0 + fy * ax1.bbox.height, 0, -40)
    y1 = tuple(_ax(p1).get_ylim())
    _set_mode("tips")
    _line_click(q2, 0.5)
    n_t = len(app.datatips)
    tk_key(w, "Delete"); app.update()
    gone_t = len(app.datatips) == n_t - 1
    app.undo_action(); app.update()
    back_t = len(app.datatips) == n_t
    y1t = tuple(_ax(p1).get_ylim())
    xl2 = _ax(p2).get_xlim()
    ann = app.add_annotation("xline", p2, xl2[0] + 0.3 * (xl2[1] - xl2[0]))
    app.ia.deselect_tip(); app.ia.select_annotation(ann.id); app.update()
    tk_key(w, "Delete"); app.update()
    gone_a = not any(a_.id == ann.id for a_ in app.annotations)
    app.undo_action(); app.update()
    y1a = tuple(_ax(p1).get_ylim())
    same = all(abs(a_ - b_) < 1e-9 for a_, b_ in zip(y1 + y1, y1t + y1a))
    check(n_t >= 1 and gone_t and back_t and gone_a and same,
          f"第四輪：P1 手動調過 y（{tuple(round(v, 3) for v in y1)}），刪掉 P2 的資料提示、標註再 ⌘Z，P1 的 y 不被重設"
          f"（{tuple(round(v, 3) for v in y1t)}、{tuple(round(v, 3) for v in y1a)}）")
    app.ia.clear_tips()
    for a_ in list(app.annotations):
        app.ia.remove_annotation(a_.id)
    _views_reset()
    # ---- 焦點在「資料夾」檔案樹按 ⌘X：給那個元件（不剪清單跟著選的 P2，只提醒），和 Delete／⌫ 一樣（F7）
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    _follow(p2)
    n0 = len(app.signals)
    calls = _with_ask(True, lambda: app.file_tree.event_generate("<<Cut>>", when="now"))
    st_ = app.status_var.get()
    cut = n0 - len(app.signals)
    if cut:
        app.undo_action(); app.update()
    check(cut == 0 and not calls and "資料夾面板" in st_ and app._follow_panel() == p2,
          f"F7：焦點在資料夾檔案樹按 ⌘X → 不剪清單跟著選的 P2（剪了 {cut} 條、問了 {calls}；{st_[:24]}）")
    app._sig_clip = []
    tk_key(w, "Escape"); app.update()
    _set_mode("")
    tk_key(w, "Escape"); app.update()


def _s37_round4_layout(s1, q1, s2, q2, clk):
    """第四輪（版面）：存成圖檔退回 0.9.8 的標法、而且還是太矮時，狀態列兩件事都說（D20／F1）。"""
    for k in range(2):                                    # 5 張連結、單位一樣
        pth = os.path.join(OUT, f"r4_more{k}.csv")
        with open(pth, "w", encoding="utf-8") as f:
            f.write(f"t{k} a,t{k} b\n" + "\n".join(f"{math.sin(j / (6.0 + k)):.5f},{math.cos(j / (7.0 + k)):.5f}" for j in range(500)) + "\n")
        app.add_csv_columns_direct(pth, None)
    app.refresh_list(); app.plot(keep=True); app.update()
    extra = [x for x in app.signals if os.path.basename(x.path or "").startswith("r4_more")]
    got = []
    for w_in, h_in in (("10", "3"), ("8", "2.4")):
        dlg = app.save_figure_dialog(); app.update()
        dlg.v_unit.set("in"); dlg.v_w.set(w_in); dlg.v_h.set(h_in); dlg._refresh()
        dlg.export(os.path.join(OUT, f"r4_{w_in}x{h_in}.png")); app.update()
        le = app.render_info["layout"].last_export or {}
        got.append((w_in, h_in, bool(le.get("fallback")), bool(le.get("squeezed")), app.status_var.get()))
    hint_fb = sv.tr("這個大小放不下每張 panel 的 x 軸標籤，這次匯出只在最下面標；而且還是太矮，圖例、x 軸標籤、標題可能壓到下一張，請加大高度")
    check(len(app.panel_order()) == 5 and all(fb and sq and hint_fb in st_ for _w, _h, fb, sq, st_ in got),
          f"D20／F1：5 張存成 10×3、8×2.4 in → 退回 0.9.8 的標法而且還是太矮，狀態列兩件事都說"
          f"（{[(w_, h_, fb, sq, st_[-30:]) for w_, h_, fb, sq, st_ in got]}）")
    app._remove_signals(extra); app.update()


def _apply_geometry(geo, timeout=10.0):
    """改主視窗大小，等它真的生效再往下量：機器很忙時視窗管理員過一陣子才改，只等 0.3 秒的話圖照舊的高度排、之後才延後重畫
    （五套測試時「小視窗、P2／P3 收合」偶爾因此失敗，P1 量到 338 px）。要的高度和現在不同就等到高度變了（視窗有最小高度，
    不一定變成要的數字），再等平移區的高度連續 3 次不變、延後的重畫（_resize_job）跑完。"""
    m = re.match(r"\s*(\d+)x(\d+)", geo)
    h0 = app.winfo_height()
    need_change = bool(m) and int(m.group(2)) != h0
    app.geometry(geo)
    t0 = time.time()
    last, same = None, 0
    while time.time() - t0 < timeout:
        app.update()
        time.sleep(0.05)
        ps = app.plot_scroll.winfo_height()
        if (not need_change or app.winfo_height() != h0) and ps == last and not getattr(app, "_resize_job", None):
            same += 1
            if same >= 3:
                break
        else:
            same = 0
        last = ps
    app.update()


def _u9_probe(name, autosave_cfg, plant):
    """獨立行程開 DSV（安靜模式；自己的 HOME、自動存檔、凍結資料夾——都在測試目錄，不碰使用者的）：啟動前在凍結資料夾放 plant
    （檔名 → bytes／np.ndarray／"stale_lock"），啟動完印出凍結資料夾裡的檔案、自己的登記檔、還原了幾條訊號、獨立訊號的資料。"""
    import json
    import subprocess
    import matplotlib
    home = os.path.join(OUT, name)
    fz = os.path.join(home, "frozen")
    shutil.rmtree(home, ignore_errors=True)
    os.makedirs(fz, exist_ok=True)
    for fn, data in plant.items():
        p_ = os.path.join(fz, fn)
        if isinstance(data, np.ndarray):
            np.save(p_, data)
        else:
            with open(p_, "wb") as f:
                f.write(b"" if data == "stale_lock" else data)
            if data == "stale_lock":
                old = time.time() - 3600
                os.utime(p_, (old, old))
    auto = os.path.join(home, ".signal_viewer_last.json")
    with open(auto, "w", encoding="utf-8") as f:
        json.dump(autosave_cfg(fz), f, ensure_ascii=False)
    probe = os.path.join(OUT, "probe_u9.py")
    with open(probe, "w", encoding="utf-8") as f:
        f.write("import sys, json, os\nsys.path.insert(0, sys.argv[1])\nimport tests_common; tests_common.install_quiet()\n"
                "import signal_viewer as sv\nsv.AUTOSAVE_PATH = sys.argv[2]\nsv.LOG_PATH = os.path.join(os.path.dirname(sys.argv[2]), 'log.txt')\n"
                "sv.frozen_data_dir = (lambda d=sys.argv[3]: d)\n"
                "app = sv.SignalViewer(root_dir=None, autorestore=True)\n"
                "app.update()\n"
                "fzs = [x for x in app.signals if not x.derive and x.column is None]\n"
                "lk = getattr(app, '_frozen_lock', None)\n"
                "out = {'files': sorted(os.listdir(sys.argv[3])), 'own': os.path.basename(lk.path) if lk is not None else None,\n"
                "       'n': len(app.signals), 'data': [float(v) for v in fzs[0].get_data()] if fzs else None}\n"
                "print('PROBE', json.dumps(out))\n"
                "app.destroy()\n"
                "print('AFTER', json.dumps(sorted(os.listdir(sys.argv[3]))))\n")
    env = _child_env(home)
    env.pop("DSV_TEST_ONLY", None)
    r = subprocess.run([sys.executable, probe, PROJECT, auto, fz], env=env, capture_output=True, text=True, timeout=120)
    line = next((ln for ln in r.stdout.splitlines() if ln.startswith("PROBE ")), "")
    after = next((ln for ln in r.stdout.splitlines() if ln.startswith("AFTER ")), "")
    out = json.loads(line[6:]) if line else {}
    if out:
        out["after"] = json.loads(after[6:]) if after else None
    return out, (r.stderr or "")[-300:]


def _s37_round5(s1, q1, s2, q2, clk):
    """第五輪（2026-10-25 使用者決定 U7b、U9）：右鍵點某張自己的 x 刻度字／x 軸標籤＝右鍵點那張的空白（四種模式：目前 panel 換成那張、
    清單照 D2 跟著（自己選了這張的某幾條就留著）、出同一個選單，放大模式是 MATLAB 的放大選單）；凍結檔沒人用到就自動清（啟動時、寫完
    自動存檔之後；目前的訊號、復原／重做、剪貼簿、自動存檔用到的不清；別的 DSV 開著、自動存檔讀不了不清；只動 DSV 自己的檔名格式）；
    「匯出設定」帶著資料，凍結檔清掉之後照樣匯入得回來。放在 s37 最後：匯入設定會換掉訊號物件（之後只剩 _s35_restore）。"""
    import json
    from matplotlib.backend_bases import MouseEvent
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    app.show_all_x(); app.update()
    # ---- U7b：右鍵點 P1 的 x 刻度字／標籤＝右鍵點 P1 的空白（滑鼠正上方、座標區下緣那一點），四種模式
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        for what in ("tick", "label"):
            tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()     # 清單自己選了 P3 的 CLK、目前 panel＝P3
            app._set_current_panel(p3, announce=False); app.update()
            tx, ty = _xlabel_xy(p1, what)
            menus.clear()
            _press_at(tx, ty, button=3)
            got = list(menus[-1]) if menus else []
            cur, fol, sel = app.current_panel(), app._follow_panel(), _sel_uids()
            tk_key(w, "Escape"); app.update()
            tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
            app._set_current_panel(p3, announce=False); app.update()
            ax = _ax(p1)
            ex, ey = min(max(tx, ax.bbox.x0 + 1), ax.bbox.x1 - 1), ax.bbox.y0 + 1
            kind = app.ia.hit_test(MouseEvent("button_press_event", app.canvas, ex, ey, button=3)).kind
            menus.clear()
            _press_at(ex, ey, button=3)
            ref = list(menus[-1]) if menus else []
            tk_key(w, "Escape"); app.update()
            check(got and got == ref and kind == "empty" and cur == p1 and fol == p1 and sel == _panel_uids(p1),
                  f"U7b {name}：右鍵點 P1 的 x {'刻度字' if what == 'tick' else '軸標籤'}＝右鍵點 P1 的空白：目前 panel＝P1、清單跟著選 P1、"
                  f"同一個選單（{len(got)} 項，{got[:3]}…）（P{cur}，跟著 {fol}，{sorted(sel)}；對照點 {kind}）")
    zoom_menu = [sv.tr("縮小        Shift＋點"), sv.tr("還原視圖"), sv.tr("不限方向縮放"), sv.tr("只縮 x（水平）"), sv.tr("只縮 y（垂直）")]
    _set_mode("zoom")
    app.set_panel_prop("link", False, p1); app.update()                                  # P1 不連結：「縮小」只動 P1
    xa, xb = _ax(p1).get_xlim()
    app.ia.set_xlim(_ax(p1), xa + 0.3 * (xb - xa), xa + 0.7 * (xb - xa), draw=True); app.update()   # 先放大，才有地方縮小
    menus.clear(); menu_objs.clear()
    xl1, xl2 = tuple(_ax(p1).get_xlim()), tuple(_ax(p2).get_xlim())
    _press_at(*_xlabel_xy(p1, "label"), button=3)
    zm = list(menus[-1]) if menus else []
    ok_out = bool(menu_objs) and invoke_menu(menu_objs[-1], zoom_menu[0])
    app.update()
    xl1b, xl2b = tuple(_ax(p1).get_xlim()), tuple(_ax(p2).get_xlim())
    zoom_tail = [sv.tr("座標（P{p}）").format(p=p1), sv.tr("整張圖的大標題…")]    # 2026-10-27 使用者第二次選單：模式選單最下面加這兩項
    check(zm == zoom_menu + zoom_tail and ok_out and (xl1b[1] - xl1b[0]) > 1.4 * (xl1[1] - xl1[0]) and xl2b == xl2,
          f"U7b 放大模式：右鍵點 P1 的 x 軸標籤＝MATLAB 放大模式的選單（U5；最下面加了「座標（P1）」與大標題：{zm}），"
          f"「縮小」縮的是 P1（{xl1} → {xl1b}；P2 不動 {xl2b == xl2}）")
    app.set_panel_prop("link", True, p1); app.show_all_x(); app.update()
    # D2 的保留規則：清單自己選了 P1 的「adc q」→ 右鍵 P1 的 x 刻度字照樣留著（選單對它）；右鍵 P2 的 x 軸標籤 → 跟著選 P2
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        tree.selection_set([f"s{q1.uid}"]); app._on_list_select(); app.update()
        app._set_current_panel(p3, announce=False); app.update()
        menus.clear()
        _press_at(*_xlabel_xy(p1, "tick"), button=3)
        keep = bool(menus) and _sel_uids() == {q1.uid} and app._follow_panel() is None and app.current_panel() == p1
        menus.clear()
        _press_at(*_xlabel_xy(p2, "label"), button=3)
        moved = bool(menus) and _sel_uids() == _panel_uids(p2) and app._follow_panel() == p2 and app.current_panel() == p2
        check(keep and moved, f"U7b {name}：清單自己選了 P1 的「adc q」→ 右鍵 P1 的 x 刻度字照 D2 留著、目前 panel＝P1；"
                              f"右鍵 P2 的 x 軸標籤 → 清單跟著選 P2、目前 panel＝P2（{keep}、{moved}）")
        tk_key(w, "Escape"); app.update()
    # 選單對的是那一張：沒有工具列模式、資料提示模式按「插入垂直參考線」→ 參考線在 P1、x＝刻度字正上方
    for mode, name in (("", "沒有工具列模式"), ("tips", "資料提示模式")):
        _set_mode(mode)
        tx, ty = _xlabel_xy(p1, "tick")
        menus.clear(); menu_objs.clear()
        _press_at(tx, ty, button=3)
        lab = next((x for x in (menus[-1] if menus else []) if x.startswith(sv.tr("插入垂直參考線（x = {x:.6g}）").split("{")[0])), None)
        n_a = len(app.annotations)
        ok_i = lab is not None and invoke_menu(menu_objs[-1], lab)
        app.update()
        new_a = app.annotations[-1] if len(app.annotations) == n_a + 1 else None
        ax = _ax(p1)
        xd = float(ax.transData.inverted().transform((tx, ty))[0])
        tol = 2.0 * (ax.get_xlim()[1] - ax.get_xlim()[0]) / ax.bbox.width
        check(ok_i and new_a is not None and new_a.axes_key == f"P{p1}" and abs(new_a.value - xd) <= tol,
              f"U7b {name}：右鍵 P1 的 x 刻度字 →「插入垂直參考線」插在 P1、x＝刻度字正上方"
              f"（{getattr(new_a, 'axes_key', None)}，{getattr(new_a, 'value', None)} vs {xd:.4g}）")
        if new_a is not None:
            app.ia.remove_annotation(new_a.id); app.update()
        tk_key(w, "Escape"); app.update()
    _set_mode("pan")
    # 握把區上的右鍵照舊是握把的選單（不是座標區的）
    ax3 = _ax(p3)
    menus.clear()
    _press_at(ax3.bbox.x0 - 20, (ax3.bbox.y0 + ax3.bbox.y1) / 2, button=3)
    hm = list(menus[-1]) if menus else []
    check(len(menus) == 1 and sv.tr("還原視圖") not in hm and app.current_panel() == p3,
          f"U7b：握把區上右鍵照舊只有握把的選單（{hm[:4]}）")
    tk_key(w, "Escape"); app.update()

    # ================================ U9：凍結檔自動清理 ================================
    fdir = sv.frozen_data_dir()
    auto0, conf0 = app.v["autosave"].get(), app.v["confirm_clear"].get()
    app.v["autosave"].set(True)
    app.v["confirm_clear"].set(False)
    cleanup = getattr(app, "cleanup_frozen", lambda: [])
    Lock = getattr(sv, "FrozenInstanceLock", None)

    def _pair(fname, a, b):
        pth = os.path.join(OUT, fname)
        with open(pth, "w", encoding="utf-8") as f:
            f.write(f"{a},{b}\n" + "\n".join(f"{math.cos(k / 13.0):.6f},{math.sin(k / 17.0):.6f}" for k in range(1500)) + "\n")
        app.add_csv_columns_direct(pth, None); app.refresh_list(); app.plot(keep=True); app.update()
        si = next(x for x in app.signals if x.name.endswith(a))
        sq = next(x for x in app.signals if x.name.endswith(b))
        tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.update()
        der = app.add_iq_magphase(); app.update()
        app.delete_panel(si.panel); app.update()                 # 來源刪掉：別張的幅度／相位改成獨立訊號（U8）＝凍結檔
        return [x for x in (app.find_signal_by_uid(d.uid) for d in der) if x is not None]

    def _orphan(tag):
        p_ = os.path.join(fdir, f"{tag}_0123456789abcdef{abs(hash(tag)) % 10000:04d}.npy")
        np.save(p_, np.arange(4.0))
        return p_

    def _live(paths):
        return [os.path.isfile(p_) for p_ in paths]

    fz = _pair("u9.csv", "u i", "u q")
    fpaths = [x.path for x in fz]
    made = len(fz) == 2 and all(not x.derive and os.path.isfile(x.path)
                                and os.path.abspath(os.path.dirname(x.path)) == os.path.abspath(fdir) for x in fz)
    orphan = _orphan("u9orphan")
    tmpf = orphan + ".4242.tmp.npy"
    with open(tmpf, "wb") as f:
        f.write(b"x")
    others = [os.path.join(fdir, n) for n in ("notes.txt", "user_data.npy", "Keep_ABCDEF0123456789ABCD.npy")]
    for o in others:
        with open(o, "wb") as f:
            f.write(b"x")
    app.save_autosave(); app.update()
    check(made and not os.path.exists(orphan) and not os.path.exists(tmpf) and all(_live(fpaths)) and all(_live(others))
          and os.path.abspath(fdir).startswith(os.path.abspath(OUT)),
          f"U9：寫完自動存檔就清掉沒人用到的凍結檔（和寫到一半的暫存檔）；目前訊號用到的 2 個、資料夾裡別的檔案不碰；測試用測試目錄"
          f"（孤兒 {os.path.exists(orphan)}、暫存 {os.path.exists(tmpf)}、用到的 {_live(fpaths)}、別的 {_live(others)}）")
    app._remove_signals(fz); app.update()
    app.save_autosave(); app.update()                            # 自動存檔已經沒有它們，復原堆疊還有
    c_undo = all(_live(fpaths))
    app.undo_action(); app.undo_action(); app.update()           # 回到刪除來源之前：衍生訊號又有來源，只剩重做堆疊用到凍結檔
    derived_again = all(x.derive for x in (app.find_signal_by_uid(d.uid) for d in fz) if x is not None)
    app.save_autosave(); app.update()
    c_redo = derived_again and all(_live(fpaths))
    app.redo_action(); app.update()                              # 又是獨立訊號
    fz = [x for x in (app.find_signal_by_uid(d.uid) for d in fz) if x is not None]
    tree.selection_set([f"s{x.uid}" for x in fz]); app._on_list_select(); app.update()
    app.actions["edit.copy"].run(); app.update()
    app._remove_signals(fz); app.undo.clear(); app._update_undo_buttons(); app.update()
    app.save_autosave(); app.update()
    c_clip = all(_live(fpaths))                                  # 只剩剪貼簿用到（還能 ⌘V）
    check(c_undo and c_redo and c_clip,
          f"U9：沒有目前的訊號用到，但復原（{c_undo}）、重做（{c_redo}）、訊號剪貼簿（{c_clip}）還用到的凍結檔不清")
    pnew = app.next_panel()
    n_p = app.paste_to_panel(pnew); app.update()
    pasted = [x for x in app.signals if x.panel == pnew]
    pasted_ok = n_p == 2 and all(len(np.asarray(x.get_data())) > 0 for x in pasted)
    app._sig_clip = []
    app.save_autosave(); app.update()                            # 自動存檔記著貼上的這兩條
    app._remove_signals(pasted); app.undo.clear(); app._update_undo_buttons(); app.update()
    cleanup(); app.update()                                      # 沒有重寫自動存檔：磁碟上的自動存檔還用到
    c_auto = all(_live(fpaths))
    app.save_autosave(); app.update()                            # 自動存檔重寫、不再用到 → 沒人用到
    c_gone = not any(_live(fpaths))
    check(pasted_ok and c_auto and c_gone,
          f"U9：只有磁碟上的自動存檔（上次的工作階段）用到時不清；自動存檔重寫、沒人用到之後清掉（{pasted_ok}、{c_auto}、{c_gone}）")
    orphan = _orphan("u9broken")
    with open(sv.AUTOSAVE_PATH, "w", encoding="utf-8") as f:
        f.write('{"signals": [')
    cleanup(); app.update()
    c_b1 = os.path.isfile(orphan)                                # 自動存檔讀不了：不知道它用到哪些，不清
    app.save_autosave(); app.update()                            # 蓋掉之前先另存備份（U13）→ 備份還在：一個都不清（U15，第十輪）
    baks = sv.autosave_backup_paths(sv.AUTOSAVE_PATH) or []
    c_b2 = os.path.isfile(orphan) and len(baks) == 1
    for b_ in baks:
        os.remove(b_)                                            # 使用者把備份刪掉 → 照常清
    app.save_autosave(); app.update()
    c_b3 = not os.path.exists(orphan)
    check(c_b1 and c_b2 and c_b3, f"U9／U15：自動存檔讀不了（壞掉）時不清；寫好自動存檔（先另存備份）之後備份還在也不清；"
                                  f"備份刪掉、再寫自動存檔之後才清（{c_b1}、{c_b2}、{c_b3}）")
    orphan = _orphan("u9other")
    lk = Lock(fdir) if Lock is not None else None
    app.save_autosave(); app.update()
    c_o1 = lk is not None and os.path.isfile(orphan)            # 別的 DSV 開著（鎖著登記檔）：不清
    if lk is not None:
        lk.release()
    app.save_autosave(); app.update()
    c_o2 = not os.path.exists(orphan)
    app.v["autosave"].set(False)                                 # 「自動還原上次」關著：自動存檔只存偏好，寫完照樣清
    orphan = _orphan("u9off")
    app.save_autosave(); app.update()
    c_off = not os.path.exists(orphan)
    app.v["autosave"].set(True)
    check(c_o1 and c_o2 and c_off,
          f"U9：別的 DSV 開著時不清、它關掉之後清（{c_o1}、{c_o2}）；「自動還原上次」關著時寫完只存偏好的自動存檔也清（{c_off}）")
    # 啟動時清（獨立行程）：自動存檔用到的留著、還原得回來；沒人用到的、寫到一半的、當掉留下的舊登記檔清掉；別的檔案不碰
    ref = np.cos(np.arange(300) / 7.0)
    ref_name = "u9ref_00112233445566778899.npy"
    orphan_name = "u9orphan_99887766554433221100.npy"

    def _cfg(fzdir):
        return {"version": 6, "view": {"autosave": True},
                "signals": [{"key": "u9 ref", "path": os.path.join(fzdir, ref_name), "sps": 1.0, "panel": 1, "uid": 7,
                             "column": None, "fmt": "AUTO", "label": "u9 ref"}]}
    plant = {ref_name: ref, orphan_name: np.arange(3.0), orphan_name + ".777.tmp.npy": b"x", "notes.txt": b"x",
             "user_data.npy": b"x", ".dsv-instance-99999-dead.lock": "stale_lock"}
    res, err = _u9_probe("u9home", _cfg, plant)
    files = set(res.get("files") or [])
    want = {ref_name, "notes.txt", "user_data.npy"} | ({res["own"]} if res.get("own") else set())
    data_ok = res.get("data") is not None and np.allclose(res["data"], ref, rtol=0, atol=0)
    check(files == want and res.get("n") == 1 and data_ok and res.get("own") and res.get("after") == sorted(want - {res["own"]}),
          f"U9 啟動時（獨立行程）：自動存檔用到的凍結檔留著、還原得回來；沒人用到的、寫到一半的、當掉留下的舊登記檔清掉；別的檔案不碰；"
          f"關掉時登記檔刪掉（{sorted(files)}；關掉後 {res.get('after')}）{'' if res else err}")
    plant2 = {ref_name: ref, orphan_name: np.arange(3.0)}
    held = []

    def _cfg2(fzdir):
        if Lock is not None:                                   # 別的 DSV 開著：probe 啟動前在它的凍結資料夾裡鎖著一個登記檔
            held.append(Lock(fzdir))
        return _cfg(fzdir)
    res2, err2 = _u9_probe("u9home2", _cfg2, plant2)
    for h in held:
        h.release()
    files2 = set(res2.get("files") or [])
    check(bool(held) and {ref_name, orphan_name} <= files2,
          f"U9 啟動時（獨立行程）：還有別的 DSV 開著（鎖著登記檔）就不清（{sorted(files2)}）{'' if res2 else err2}")
    # 「匯出設定」帶著資料：凍結檔清掉之後「匯入設定」照樣讀回一模一樣的資料（真的走匯出、匯入對話框的路徑）
    fz2 = _pair("u9b.csv", "w i", "w q")
    data2 = {x.uid: np.asarray(x.get_data(), float).copy() for x in fz2}
    names2 = {os.path.basename(x.path) for x in fz2}
    exp = os.path.join(OUT, "u9_export.json")
    orig_s, orig_o = sv.filedialog.asksaveasfilename, sv.filedialog.askopenfilename
    sv.filedialog.asksaveasfilename = lambda **k: exp
    try:
        app.export_settings_dialog(); app.update()
    finally:
        sv.filedialog.asksaveasfilename = orig_s
    with open(exp, encoding="utf-8") as f:
        cfg_e = json.load(f)
    emb = cfg_e.get("frozen_data") or {}
    c_e1 = len(fz2) == 2 and set(emb) == names2
    app._remove_signals(fz2); app.undo.clear(); app._update_undo_buttons(); app._sig_clip = []; app.update()
    app.save_autosave(); app.update()
    c_e2 = not any(os.path.exists(os.path.join(fdir, n)) for n in names2)
    sv.filedialog.askopenfilename = lambda **k: exp
    try:
        app.import_settings_dialog(); app.update()
    finally:
        sv.filedialog.askopenfilename = orig_o
    back = {x.uid: x for x in app.signals if x.uid in data2}
    c_e3 = (len(back) == 2 and all(os.path.isfile(x.path) and os.path.abspath(os.path.dirname(x.path)) == os.path.abspath(fdir) for x in back.values())
            and all(np.array_equal(np.asarray(back[u].get_data(), float), data2[u], equal_nan=True) for u in data2))
    check(c_e1 and c_e2 and c_e3,
          f"U9：「匯出設定」把 2 條獨立訊號的資料放進 JSON（{sorted(emb)[:2]}）；凍結檔被清掉（{c_e2}）之後「匯入設定」照樣讀回一模一樣的資料、"
          f"寫回凍結資料夾（{c_e3}）")
    app.v["autosave"].set(auto0)
    app.v["confirm_clear"].set(conf0)
    _set_mode("")


def _s37_round6():
    """第六輪（U9 審查修正）：用到凍結檔的視窗一定在凍結資料夾登記，別的 DSV 清之前才看得到它開著、不會把它正在用的檔清掉——
    匯入只記路徑的設定檔（自動存檔的複本）、從資料夾面板加入凍結的 .npy 都會登記；登記失效（上鎖剛好撞到別的 DSV 的檢查、登記檔或
    整個凍結資料夾被刪掉）就在存凍結檔、清理之前重新登記。名稱只差大小寫、資料一樣的兩條獨立訊號共用一個檔（macOS、Windows 檔名
    不分大小寫），刪掉其中一條、寫完自動存檔不會把另一條用的檔清掉。「別的 DSV」用它清之前做的檢查（frozen_other_instances）模擬。"""
    import json
    fdir = sv.frozen_data_dir()
    tree = app.sig_tree
    auto0, conf0 = app.v["autosave"].get(), app.v["confirm_clear"].get()
    app.v["autosave"].set(True)
    app.v["confirm_clear"].set(False)
    _set_mode("pan")
    tk_key(app.canvas.get_tk_widget(), "Escape"); app.update()

    def _drop_frozen():
        """拿掉所有用到凍結檔的訊號、清空復原記錄與剪貼簿（檔案留著，沒有清理）。"""
        fz_ = [x for x in app.signals if sv.frozen_refs([x])]
        if fz_:
            app._remove_signals(fz_)
        app.undo.clear(); app._update_undo_buttons(); app._sig_clip = []; app.update()

    def _pair6(path, a, b):
        """CSV（a、b 兩欄）加進新的 panel → I/Q 幅度／相位 → 刪掉來源 panel：別張的兩條改成獨立訊號（凍結檔，U8）。"""
        if not os.path.exists(path):
            with open(path, "w", encoding="utf-8") as f:
                f.write(f"{a},{b}\n" + "\n".join(f"{math.cos(k / 11.0):.6f},{math.sin(k / 19.0):.6f}" for k in range(1200)) + "\n")
        n0 = len(app.signals)
        app.add_csv_columns_direct(path, None); app.refresh_list(); app.plot(keep=True); app.update()
        new = app.signals[n0:]
        si = next(x for x in new if x.name.endswith(a))
        sq = next(x for x in new if x.name.endswith(b))
        tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.update()
        der = app.add_iq_magphase(); app.update()
        app.delete_panel(si.panel); app.update()
        return [x for x in (app.find_signal_by_uid(d.uid) for d in der) if x is not None]

    def _unregister():
        """模擬沒登記的視窗（比凍結資料夾更早開、從沒存過凍結檔）。"""
        lk_ = getattr(app, "_frozen_lock", None)
        if lk_ is not None:
            lk_.release()
        app._frozen_lock = None

    def _seen():
        """別的 DSV 清之前看到「還有別的 DSV 開著」（這個測試行程裡只有 app）。"""
        return sv.frozen_other_instances(fdir, None)

    def _reg_ok():
        lk_ = getattr(app, "_frozen_lock", None)
        if lk_ is None or not lk_.locked:
            return False
        v = getattr(lk_, "valid", None)
        return bool(v()) if v is not None else os.path.exists(lk_.path)

    def _other_dsv_cleans():
        """別的 DSV（自己沒用到這些檔）寫完自動存檔後的清理：看到有別的 DSV 開著就不清（cleanup_frozen 的規則）。回傳刪掉的檔名。"""
        return [] if sv.frozen_other_instances(fdir, None) else sv.clean_frozen_dir(fdir, set())

    _drop_frozen()
    # ---- (A) 沒登記的視窗「匯入設定」只記路徑的設定檔（自動存檔的複本）：先登記，別的 DSV 關掉時不清它正在用的檔
    fz = _pair6(os.path.join(OUT, "r6a.csv"), "a6 i", "a6 q")
    names = sorted(os.path.basename(x.path) for x in fz)
    cfg_p = os.path.join(OUT, "r6_paths_only.json")
    app.save_settings(cfg_p, embed_frozen=False)
    with open(cfg_p, encoding="utf-8") as f:
        paths_only = sv.FROZEN_EMBED_KEY not in json.load(f)
    _drop_frozen()
    _unregister()
    alone0 = not _seen()
    orig_o = sv.filedialog.askopenfilename
    sv.filedialog.askopenfilename = lambda **k: cfg_p
    try:
        app.import_settings_dialog(); app.update()
    finally:
        sv.filedialog.askopenfilename = orig_o
    imp = [x for x in app.signals if os.path.basename(x.path or "") in names]
    seen_a, reg_a = _seen(), _reg_ok()
    gone_a = _other_dsv_cleans()
    check(len(fz) == 2 and paths_only and alone0 and len(imp) == 2 and seen_a and reg_a and not gone_a
          and all(os.path.isfile(x.path) for x in imp),
          f"U9 審查：沒登記的視窗（比凍結資料夾更早開）匯入只記路徑的設定檔（自動存檔的複本）→ 登記；別的 DSV 看得到它開著"
          f"（匯入前 {not alone0}、後 {seen_a}），關掉時不清它正在用的 2 個凍結檔（刪了 {gone_a}）")
    # ---- (B) 沒登記的視窗從資料夾面板加入凍結的 .npy：一樣登記
    _drop_frozen()
    _unregister()
    app.refresh_list(); app.update()
    none_reg = getattr(app, "_frozen_lock", None) is None and not _seen()      # 沒用到凍結檔：不登記
    n0 = len(app.signals)
    app.add_csv_columns_direct(os.path.join(fdir, names[0]), None); app.refresh_list(); app.plot(keep=True); app.update()
    added = app.signals[n0:]
    seen_b, reg_b = _seen(), _reg_ok()
    gone_b = _other_dsv_cleans()
    check(none_reg and len(added) == 1 and seen_b and reg_b and not gone_b and os.path.isfile(os.path.join(fdir, names[0])),
          f"U9 審查：沒登記的視窗從資料夾面板加入凍結的 .npy（{names[0]}）→ 登記，別的 DSV 不清它（沒用到時不登記 {none_reg}；"
          f"加入後 {seen_b}；刪了 {gone_b}）")
    # ---- (C) 上鎖剛好撞到別的 DSV 正在檢查（它把登記檔鎖住一下）：重試到鎖上，不留下 60 秒後會被當成當掉的登記
    _drop_frozen()
    _unregister()
    real_lock, n_try = sv._lock_fd, [0]

    def _busy_once(fd):
        n_try[0] += 1
        return False if n_try[0] == 1 else real_lock(fd)
    sv._lock_fd = _busy_once
    try:
        fz_c = _pair6(os.path.join(OUT, "r6c.csv"), "c6 i", "c6 q")        # 存凍結檔之前登記：第一次上鎖撞到別人
    finally:
        sv._lock_fd = real_lock
    lk_c = getattr(app, "_frozen_lock", None)
    check(len(fz_c) == 2 and n_try[0] >= 2 and lk_c is not None and lk_c.locked and _reg_ok(),
          f"U9 審查：存凍結檔時登記，第一次上鎖撞到別的 DSV 的檢查 → 重試到鎖上（試了 {n_try[0]} 次，鎖著 {getattr(lk_c, 'locked', None)}）")
    # 這次完全鎖不上（一直撞到）：清理之前確認登記，沒鎖上就重新登記
    _unregister()
    sv._lock_fd = lambda fd: False
    try:
        app.refresh_list(); app.update()                                       # 用到凍結檔 → 登記（鎖不上）
    finally:
        sv._lock_fd = real_lock
    lk_u = getattr(app, "_frozen_lock", None)
    unlocked = lk_u is not None and not lk_u.locked
    app.cleanup_frozen(); app.update()
    relock = _reg_ok() and getattr(app, "_frozen_lock", None) is not lk_u
    check(unlocked and relock, f"U9 審查：登記檔沒鎖上（{unlocked}）→ 清理之前重新登記、鎖上（{relock}）")
    # ---- (D) 登記檔被刪掉（別的 DSV 當成當掉留下的）、整個凍結資料夾被刪掉（使用者、清理工具）：再存凍結檔之前重新登記
    if os.name != "nt":
        _pair6(os.path.join(OUT, "r6d0.csv"), "f6 i", "f6 q")                 # 存過凍結檔：登記著
        lk_d = getattr(app, "_frozen_lock", None)
        if lk_d is not None:
            os.remove(lk_d.path)
        lost_d = lk_d is not None and not _seen()
        fz_d = _pair6(os.path.join(OUT, "r6d.csv"), "d6 i", "d6 q")
        back_d = _seen() and _reg_ok() and app._frozen_lock is not lk_d
        gone_d = _other_dsv_cleans()
        kept_d = not gone_d and all(os.path.isfile(x.path) for x in fz_d)
        shutil.rmtree(fdir)
        fz_e = _pair6(os.path.join(OUT, "r6e.csv"), "e6 i", "e6 q")
        back_e = _seen() and _reg_ok()
        gone_e = _other_dsv_cleans()
        kept_e = not gone_e and all(os.path.isfile(x.path) for x in fz_e)
        check(lost_d and back_d and kept_d and back_e and kept_e,
              f"U9 審查：登記檔被刪掉（別的 DSV 看不到 {lost_d}）→ 再存凍結檔之前重新登記（{back_d}），別的 DSV 不清（{kept_d}）；"
              f"整個凍結資料夾被刪掉 → 再存時資料夾重建、重新登記（{back_e}），別的 DSV 不清（{kept_e}）")
    else:
        check(True, "U9 審查：（Windows：開著的登記檔刪不掉，登記檔、凍結資料夾被刪掉的情況不會發生，略過）")
    # ---- (E) 名稱只差大小寫、資料一樣的兩條獨立訊號（x/Cap.csv、y/cap.csv 各做 I/Q 幅度／相位再刪來源）：刪掉 |Cap…|、
    #          寫完自動存檔，|cap…| 用的檔（磁碟上就是 Cap_… 那一個）不能被清掉
    _drop_frozen()
    dx, dy = os.path.join(OUT, "r6case", "x"), os.path.join(OUT, "r6case", "y")
    os.makedirs(dx, exist_ok=True)
    os.makedirs(dy, exist_ok=True)
    c1, c2 = os.path.join(dx, "Cap.csv"), os.path.join(dy, "cap.csv")
    with open(c1, "w", encoding="utf-8") as f:
        f.write("u i,u q\n" + "\n".join(f"{math.cos(k / 9.0):.6f},{math.sin(k / 23.0):.6f}" for k in range(1100)) + "\n")
    shutil.copyfile(c1, c2)
    fa = _pair6(c1, "u i", "u q")
    fb = _pair6(c2, "u i", "u q")
    ma = next(x for x in fa if x.name.startswith("|"))
    mb = next(x for x in fb if x.name.startswith("|"))
    na, nb = os.path.basename(ma.path), os.path.basename(mb.path)
    disk0 = sorted(n for n in os.listdir(fdir) if n.lower() == nb.lower())
    ref_b = np.load(mb.path)
    app._remove_signals([ma]); app.undo.clear(); app._update_undo_buttons(); app._sig_clip = []; app.update()
    app.save_autosave(); app.update()
    alive = os.path.isfile(mb.path)
    same_b = alive and np.load(mb.path).tobytes() == ref_b.tobytes()
    check(na != nb and na.lower() == nb.lower() and alive and same_b,
          f"U9 審查：「{ma.name}」「{mb.name}」資料一樣、檔名只差大小寫（磁碟上 {disk0}）；刪掉前者、寫完自動存檔，後者用的檔還在、"
          f"資料一樣（{alive}、{same_b}）")
    _drop_frozen()
    app.v["autosave"].set(auto0)
    app.v["confirm_clear"].set(conf0)
    _set_mode("")


def _s37_round7():
    """第七輪（2026-10-25 使用者決定 U10）：刪除／剪下會把沒被選到的衍生訊號（不管在哪一張）改成獨立訊號（U8），但 frozen 資料夾寫不進去——唯讀（chmod）、
    同名的檔案擋在資料夾的位置、磁碟滿（寫 .npy 的 _write_npy 寫到一半丟 ENOSPC；真的寫入失敗見第八輪）、同名的資料夾擋在 .npy 的位置、
    只有第二條存不了——就整個取消：
    什麼都沒移除、衍生訊號照舊連著來源（資料一樣）、復原／重做記錄不變、剪貼簿不變、資料夾裡不留暫存檔，跳一個錯誤視窗寫出哪幾條衍生訊號、
    資料夾路徑和原因，狀態列也說。每個入口都測：×、握把＋Delete、跟著選＋Delete／⌫／工具列「移除」／已繪訊號面板的移除鈕／清單右鍵「移除」／
    ⌘X、握把區與座標區空白右鍵「刪除這個 panel」、清單自己選的＋Delete／⌘X、線上右鍵「刪除這條訊號」（平移、資料提示、沒有工具列模式）。資料夾修好之後照常刪除、改成獨立訊號；
    同名但內容不對的凍結檔重寫成正確的資料。對話框全部攔下來（_with_ask），測試的 frozen 資料夾都在測試目錄。"""
    import errno as _errno
    import hashlib
    from matplotlib.backend_bases import MouseEvent
    from types import SimpleNamespace as NS
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    conf0 = app.v["confirm_clear"].get()
    fdir_fn = sv.frozen_data_dir                         # 測試目錄的 frozen（檔頭換掉的）
    real_write = getattr(sv, "_write_npy", None)         # 寫 .npy 的那一步（第八輪起不經過 np.save）
    real_save = np.save
    base = os.path.join(OUT, "r7")
    for dp, _dn, _fn in os.walk(base):
        os.chmod(dp, 0o755)
    shutil.rmtree(base, ignore_errors=True)
    os.makedirs(base)
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    app.v["confirm_clear"].set(True)
    # ---- 準備：r7.csv（資料只有這一輪用，凍結檔不會事先就有）的 I、Q 在 PA，它們的幅度、相位在別張
    csv7 = os.path.join(OUT, "r7.csv")
    with open(csv7, "w", encoding="utf-8") as f:
        f.write("r7 i,r7 q\n" + "\n".join(f"{math.cos(k / 7.3) * (1 + 0.2 * math.sin(k / 41.0)):.6f},{math.sin(k / 8.1):.6f}"
                                           for k in range(1300)) + "\n")
    n0 = len(app.signals)
    app.add_csv_columns_direct(csv7, None); app.refresh_list(); app.plot(keep=True); app.update()
    new = app.signals[n0:]
    si = next(x for x in new if x.name.endswith("r7 i"))
    sq = next(x for x in new if x.name.endswith("r7 q"))
    pa = si.panel
    tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.update()
    app.add_iq_magphase(); app.update()
    der = [x for x in app.signals if x.derive and set(x.src_uids) == {si.uid, sq.uid}]
    ref = {x.uid: np.asarray(x.get_data(), float).copy() for x in der}
    ok_setup = sq.panel == pa and len(der) == 2 and all(x.panel != pa for x in der) and all(len(v) == 1300 for v in ref.values())
    check(ok_setup, f"U10 準備：P{pa}＝r7 i／r7 q，幅度、相位在 {[f'P{x.panel}' for x in der]}（{[x.name for x in der]}）")
    if not ok_setup:
        return
    # 重做堆疊放一筆（取消的刪除不能把它清掉）、剪貼簿放別的東西（取消的剪下不能換掉它）
    app.hide_panel_signals(der[0].panel); app.update()
    app.undo_action(); app.update()
    tree.selection_set([f"s{der[1].uid}"]); app._on_list_select(); app.update()
    app.actions["edit.copy"].run(); app.update()
    tree.selection_set([]); app._on_list_select(); app.update()

    def _state():
        return [(x.uid, x.panel, x.derive, x.src, x.path, x.column, x.key, x.label, x.visible) for x in app.signals]

    def _undo_ids():
        return ([(e["desc"], id(e["state"])) for e in app.undo._undo], [(e["desc"], id(e["state"])) for e in app.undo._redo])

    def _linked():
        now = [app.find_signal_by_uid(x.uid) for x in der]
        return all(x is not None and x.derive and set(x.src_uids) == {si.uid, sq.uid}
                   and np.array_equal(np.asarray(x.get_data(), float), ref[x.uid], equal_nan=True) for x in now)

    def _undo_if_done(ud_before):
        """沒有取消、照樣刪掉了（修正前的版本）：這一項已經判失敗，復原回來，下一項才測得到。"""
        if len(app.undo._undo) > len(ud_before[0]):
            app.undo_action(); app.update()

    ro_dir = os.path.join(base, "probe_ro")
    os.makedirs(ro_dir)
    os.chmod(ro_dir, 0o500)
    try:
        with open(os.path.join(ro_dir, "probe"), "w"):
            pass
        ro_ok = False                                      # 唯讀資料夾照樣寫得進去（Windows、系統管理員）：唯讀這種略過
    except OSError:
        ro_ok = True
    os.chmod(ro_dir, 0o755)
    reasons = {"ro": sv.tr("沒有寫入權限"), "file": sv.tr("有同名的檔案或資料夾擋住"), "enospc": sv.tr("磁碟空間不足"),
               "npydir": sv.tr("有同名的檔案或資料夾擋住")}
    kinds_name = {"ro": "唯讀資料夾（chmod 500）", "file": "同名的檔案擋在資料夾的位置", "enospc": "磁碟滿（ENOSPC）",
                  "npydir": "同名的資料夾擋在 .npy 的位置"}

    def _target_name(sig):
        """sig 改成獨立訊號時的凍結檔名（save_frozen_array 的命名）。"""
        sig.get_data()
        full = sig.raw_full if (sig.roi and sig.raw_full is not None) else sig.raw
        a_ = np.ascontiguousarray(np.asarray(full, dtype=float)).ravel()
        stem = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(sig.name))[:40].strip("._") or "signal"
        return f"{stem}_{hashlib.blake2b(a_.tobytes(), digest_size=10).hexdigest()}.npy"

    class _Fail:
        """frozen 資料夾寫不進去的一種情況：進入時設好（sv.frozen_data_dir 指到測試目錄裡的那個位置），離開時還原。"""

        def __init__(self, kind):
            self.kind = kind
            self.dir = os.path.join(base, f"{kind}{len(os.listdir(base))}", "frozen")

        def __enter__(self):
            k = self.kind
            if k == "file":
                os.makedirs(os.path.dirname(self.dir))
                with open(self.dir, "w") as f_:
                    f_.write("not a folder")
            else:
                os.makedirs(self.dir)
                if k == "ro":
                    os.chmod(self.dir, 0o500)
                elif k == "npydir":
                    for x in der:
                        os.makedirs(os.path.join(self.dir, _target_name(x)))
                elif k == "enospc":
                    def _full(p_, arr, *a_, **k_):
                        with open(p_, "wb") as f_:
                            f_.write(b"\x93NUMPY partial")
                        raise OSError(_errno.ENOSPC, os.strerror(_errno.ENOSPC), p_)
                    sv._write_npy = _full                  # 第八輪起寫 .npy 的那一步
                    np.save = _full                        # 4bd2e53 以前（同一份測試放到舊版也測得到）
            sv.frozen_data_dir = lambda d=self.dir: d
            return self

        def __exit__(self, *exc):
            if real_write is not None:
                sv._write_npy = real_write
            np.save = real_save
            sv.frozen_data_dir = fdir_fn
            if os.path.isdir(self.dir):
                os.chmod(self.dir, 0o755)
            return False

        def leftovers(self):
            """資料夾裡留下的 .npy／暫存檔（登記檔不算）。"""
            if not os.path.isdir(self.dir):
                return []
            return sorted(n for n in os.listdir(self.dir) if n.endswith(".npy") and not os.path.isdir(os.path.join(self.dir, n)))

    rib = [b for b in app._sel_btns if str(b.cget("text")) == sv.tr("移除")]
    dock = [b for b, nm in app.sig_panel._tools if nm == "remove"]

    def _x_click():
        x_, y_ = _close_xy(pa)
        MouseEvent("button_press_event", app.canvas, x_, y_, button=1)._process()
        MouseEvent("button_release_event", app.canvas, x_, y_, button=1)._process()
        app.update()

    def _list_remove():
        bb_ = tree.bbox(f"s{si.uid}")
        menus.clear(); menu_objs.clear()
        app._on_list_context(NS(x=(bb_[0] + 5) if bb_ else 5, y=(bb_[1] + 3) if bb_ else 5, x_root=0, y_root=0))
        if menu_objs:
            invoke_menu(menu_objs[-1], sv.tr("移除"))

    def _own(fn):
        def f():
            tree.selection_set([f"s{si.uid}"]); app._on_list_select(); app.update()
            fn()
        return f

    def _menu_delete_panel(where):
        """右鍵選單「刪除這個 panel」：握把區（平移模式）或座標區空白（沒有工具列模式）。"""
        def f():
            menus.clear(); menu_objs.clear()
            if where == "handle":
                ax_ = _ax(pa)
                _press_at(ax_.bbox.x0 - 20, (ax_.bbox.y0 + ax_.bbox.y1) / 2, button=3)
            else:
                _set_mode("")
                _click_empty(_ax(pa), button=3)
            if menu_objs:
                invoke_menu(menu_objs[-1], sv.tr("刪除這個 panel"))
        return f

    def _line_delete(mode):
        def f():
            _set_mode(mode)
            menus.clear(); menu_objs.clear()
            _line_click(si, 0.4, button=3)
            pre = sv.tr("刪除這條訊號（{name}）").split("{")[0]
            lab = next((x for x in (menus[-1] if menus else []) if x.startswith(pre)), None)
            if lab is not None:
                invoke_menu(menu_objs[-1], lab)
        return f

    t_del, t_rm, t_cut = sv.tr("刪除已取消"), sv.tr("移除已取消"), sv.tr("剪下已取消")
    entries = [
        ("panel 左上角 ×", _x_click, t_del, True),
        ("握把選取＋Delete", lambda: (_handle_press(pa), tk_key(w, "Delete")), t_del, True),
        ("點 panel 空白（跟著選）＋Delete（焦點在圖上）", lambda: (_click_empty(_ax(pa)), tk_key(w, "Delete")), t_del, True),
        ("跟著選＋⌫（焦點在清單）", lambda: (_click_empty(_ax(pa)), tk_key(tree, "BackSpace")), t_del, True),
        ("跟著選＋工具列「移除」", lambda: (_click_empty(_ax(pa)), rib[0].invoke()), t_del, True),
        ("跟著選＋已繪訊號面板的移除鈕", lambda: (_click_empty(_ax(pa)), dock[0].invoke()), t_del, True),
        ("跟著選＋清單右鍵「移除」", lambda: (_click_empty(_ax(pa)), _list_remove()), t_del, True),
        ("跟著選＋⌘X", lambda: (_click_empty(_ax(pa)), app.actions["edit.cut"].run()), t_cut, True),
        ("握把區右鍵「刪除這個 panel」", _menu_delete_panel("handle"), t_del, True),
        ("座標區空白右鍵「刪除這個 panel」（沒有工具列模式）", _menu_delete_panel("axes"), t_del, True),
        ("清單自己選的「r7 i」＋Delete", _own(lambda: tk_key(tree, "Delete")), t_rm, False),
        ("清單自己選的「r7 i」＋⌘X", _own(lambda: app.actions["edit.cut"].run()), t_cut, False),
        ("線上右鍵「刪除這條訊號」（平移模式）", _line_delete("pan"), t_del, False),
        ("線上右鍵「刪除這條訊號」（資料提示模式）", _line_delete("tips"), t_del, False),
        ("線上右鍵「刪除這條訊號」（沒有工具列模式）", _line_delete(""), t_del, False),
    ]
    kinds = (["ro"] if ro_ok else []) + ["file", "enospc"]
    if not ro_ok:
        check(True, "U10：（這個環境的唯讀資料夾照樣寫得進去：唯讀這種情況略過，其他照測）")
    names = [x.name for x in der]
    for label, fn, title, asks in entries:
        for kind in kinds:
            _set_mode("pan")
            tk_key(w, "Escape"); app.update()
            tree.selection_set([]); app._on_list_select(); app.update()
            st0, ud0, order0 = _state(), _undo_ids(), app.panel_order()
            clip0, clipk0 = app._sig_clip, [id(x) for x in sv.CLIPBOARD]
            with _Fail(kind) as fl:
                calls = _with_ask(True, fn)
                left = fl.leftovers()
                fdir_shown = fl.dir
            st_ = app.status_var.get()                    # 換回平移模式之前（換模式會改狀態列）
            _set_mode("pan")
            app.ia.clear_tips(); app.update()
            errs = [c for c in calls if c[0] == "showerror"]
            ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
            asked = [c for c in calls if c[0].startswith("ask")]
            if not errs:
                order_ok = False
            elif asks:
                order_ok = len(asked) == 1 and calls.index(asked[0]) < calls.index(errs[0])   # 先照「清空前確認」問，答「是」才存、才報錯
            else:
                order_ok = not asked
            same = _state() == st0 and _undo_ids() == ud0 and app.panel_order() == order0
            clip_same = app._sig_clip is clip0 and [id(x) for x in sv.CLIPBOARD] == clipk0
            told = (all(n in msg for n in names) and fdir_shown in msg and msg.count(reasons[kind]) == 1   # 兩條同一個原因：只寫一次
                    and "什麼都沒有移除" in msg)
            ok = (len(errs) == 1 and ttl == title and order_ok and same and _linked() and clip_same and told and not left
                  and "已取消" in st_ and len(app.signals) == len(st0))
            check(ok, f"U10 {label}／{kinds_name[kind]}：整個取消——什麼都沒移除（{len(st0)} → {len(app.signals)} 條，欄位一樣 {_state() == st0}）、"
                      f"衍生訊號照舊連著來源（{_linked()}）、復原／重做記錄不變（{_undo_ids() == ud0}）、剪貼簿不變（{clip_same}）、"
                      f"資料夾沒留檔（{left}）；錯誤視窗 {len(errs)} 個「{ttl}」寫出兩條衍生訊號、資料夾、原因（{told}）；"
                      f"先問再報錯（{order_ok}）；狀態列「{st_[:30]}」")
            _undo_if_done(ud0)
    # ---- English 介面：錯誤視窗、狀態列都是英文（plotkit/i18n_en_fix3.py），沒有中文
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    lang0 = pk.i18n.get_language()
    pk.i18n.set_language("en")
    try:
        st0, ud0 = _state(), _undo_ids()
        with _Fail("enospc") as fl:
            calls = _with_ask(True, lambda: app.delete_panel(pa))
            fdir_shown = fl.dir
        st_en = app.status_var.get()
    finally:
        pk.i18n.set_language(lang0)
    errs = [c for c in calls if c[0] == "showerror"]
    ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
    cjk = re.findall(r"[　-〿一-鿿＀-￯]", ttl + msg + st_en)
    check(len(errs) == 1 and ttl == "Deletion cancelled" and not cjk and _state() == st0 and _undo_ids() == ud0
          and "Folder: " + fdir_shown in msg and "Reason: not enough disk space" in msg and all(n in msg for n in names)
          and "cancelled" in st_en,
          f"U10 English 介面：錯誤視窗「{ttl}」、內容與狀態列都是英文（中文字 {cjk[:6]}）：{msg[:90]!r}…；狀態列 {st_en[:60]!r}")
    _undo_if_done(ud0)
    # ---- 同名的資料夾擋在 .npy 的位置（資料夾本身寫得進去）：照樣取消、不留暫存檔
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    st0, ud0 = _state(), _undo_ids()
    with _Fail("npydir") as fl:
        calls = _with_ask(True, lambda: app.delete_panel(pa))
        left = fl.leftovers()
        tmps = [n for n in os.listdir(fl.dir) if ".tmp." in n]
    errs = [c for c in calls if c[0] == "showerror"]
    msg = str(errs[0][1][1]) if errs else ""
    check(len(errs) == 1 and _state() == st0 and _undo_ids() == ud0 and _linked() and not left and not tmps
          and reasons["npydir"] in msg and all(n in msg for n in names),
          f"U10 刪除 P{pa}／{kinds_name['npydir']}：整個取消、不留暫存檔（{tmps}）、錯誤視窗寫出原因（{msg.count(reasons['npydir'])} 次）")
    _undo_if_done(ud0)
    # ---- 只有第二條存不了（第一條已經存好）：照樣整個取消，第一條也不改成獨立訊號（沒有一半的狀態）；錯誤視窗只列存不了的那條
    d2 = os.path.join(base, "second", "frozen")
    os.makedirs(d2)
    cnt = [0]

    def _second(p_, arr, *a_, **k_):
        cnt[0] += 1
        if cnt[0] == 2:
            with open(p_, "wb") as f_:
                f_.write(b"\x93NUMPY partial")
            raise OSError(_errno.ENOSPC, os.strerror(_errno.ENOSPC), p_)
        return (real_write or real_save)(p_, arr, *a_, **k_)
    st0, ud0 = _state(), _undo_ids()
    sv.frozen_data_dir = lambda: d2
    sv._write_npy = _second                               # 第八輪起寫 .npy 的那一步
    np.save = _second                                     # 4bd2e53 以前
    try:
        calls = _with_ask(True, lambda: app.delete_panel(pa))
    finally:
        if real_write is not None:
            sv._write_npy = real_write
        np.save = real_save
        sv.frozen_data_dir = fdir_fn
    errs = [c for c in calls if c[0] == "showerror"]
    msg = str(errs[0][1][1]) if errs else ""
    first, second = der[0], der[1]
    tmps = [n for n in os.listdir(d2) if ".tmp." in n]
    check(cnt[0] == 2 and len(errs) == 1 and _state() == st0 and _undo_ids() == ud0 and _linked()
          and second.name in msg and first.name not in msg and not tmps,
          f"U10：只有第二條（{second.name}）存不了、第一條存好了 → 照樣整個取消，第一條也還是衍生訊號（{_linked()}）；"
          f"錯誤視窗只列存不了的那條（列了第一條 {first.name in msg}）；不留暫存檔（{tmps}）")
    _undo_if_done(ud0)
    # ---- 資料夾修好之後：同一個入口照常刪除，兩條改成獨立訊號、資料一樣；⌘Z 連結回來
    calls = _with_ask(True, lambda: (_click_empty(_ax(pa)), tk_key(w, "Delete")))
    now = [app.find_signal_by_uid(x.uid) for x in der]
    freed = all(x is not None and not x.derive and os.path.isfile(x.path)
                and np.array_equal(np.load(x.path), ref[x.uid], equal_nan=True) for x in now)
    gone = app.find_signal_by_uid(si.uid) is None and pa not in app.panel_order()
    st_ = app.status_var.get()
    errs = [c for c in calls if c[0] == "showerror"]
    app.undo_action(); app.update()
    check(gone and freed and not errs and "改成獨立訊號" in st_ and _linked(),
          f"U10：frozen 資料夾寫得進去時照常刪除 P{pa}，兩條改成獨立訊號、存的資料一樣（{freed}）；⌘Z 連結回來（{_linked()}）；「{st_[:40]}」")
    # ---- 同名但內容不對的凍結檔（以前當掉、被別的程式寫壞）：刪除前重寫成正確的資料（以前直接拿來用，重開後資料不對）
    fd = fdir_fn()
    os.makedirs(fd, exist_ok=True)
    bad = {x.uid: os.path.join(fd, _target_name(x)) for x in der}
    for p_ in bad.values():
        if os.path.exists(p_):
            os.remove(p_)
    np.save(bad[der[0].uid], np.zeros(5))                      # 格式對、資料不對
    with open(bad[der[1].uid], "wb") as f:                    # 不是 .npy
        f.write(b"garbage")
    calls = _with_ask(True, lambda: app.delete_panel(pa))
    now = [app.find_signal_by_uid(x.uid) for x in der]
    reread = []
    for x in now:
        if x is not None:
            x.invalidate(reload=True)                         # 像重開一樣從檔案讀
            try:
                reread.append(bool(np.array_equal(np.asarray(x.get_data(), float), ref[x.uid], equal_nan=True)))
            except Exception as e_:                           # 修正前：直接拿壞掉的檔來用，讀不回來
                reread.append(f"讀不回來 {type(e_).__name__}")
    fixed = (len(reread) == 2 and all(r_ is True for r_ in reread)
             and all(x is not None and not x.derive and os.path.abspath(x.path) == os.path.abspath(bad[x.uid]) for x in now))
    app.undo_action(); app.update()
    check(fixed and _linked() and not [c for c in calls if c[0] == "showerror"],
          f"U10：同名但內容不對的凍結檔（別的資料、不是 .npy）擋在路上 → 刪除前重寫成正確的資料，從檔案重讀一模一樣（{reread}）")
    # ---- 收尾：拿掉這一輪的訊號、復原記錄、剪貼簿
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    gone7 = [x for x in app.signals if x.uid in {si.uid, sq.uid} | {d.uid for d in der}]
    if gone7:
        app._remove_signals(gone7)
    app.undo.clear(); app._update_undo_buttons(); app._sig_clip = []; app.update()
    for dp, _dn, _fn in os.walk(base):
        os.chmod(dp, 0o755)
    app.v["confirm_clear"].set(conf0)
    _set_mode("")


def _s37_round8():
    """第八輪（2026-10-26 驗證回報，在 4bd2e53 上用真的獨立行程重現過）：
    (1) 真的寫入失敗（RLIMIT_FSIZE：核心在寫到一半回 EFBIG，和磁碟滿一樣是寫不下去）時刪除、剪下整個取消，錯誤視窗的原因看得懂
        「檔案超過大小上限（[Errno 27] File too large）」——以前是 numpy 的「1300 requested and … written」；中文、English 都測，不留暫存檔。
    (2) frozen 資料夾唯讀、但要存的資料已經在資料夾裡（刪除 → ⌘Z 留下的，讀回來一樣）：照使用者決定的「資料夾寫不進去就整個不刪」取消
        ——以前照樣刪除；這個視窗沒登記的話，資料夾恢復可寫之後別的 DSV 會把檔清掉，重開後兩條不見。已登記、沒登記兩種都測。
    (3) 自動存檔（「自動還原上次」開、關）、匯出設定寫到一半寫不下去：原本的檔一個位元組都不動、不留暫存檔、不清凍結檔——以前覆寫成
        半個 JSON，下次開啟什麼都沒有，凍結檔接著被清掉。
    (4) 匯入帶資料的設定檔（U9）、frozen 資料夾寫不進去：警告寫出哪幾條、資料夾、真正的原因，不寫成「找不到檔案」。
    對話框全部攔下來，frozen 資料夾、自動存檔、匯出的檔都在測試目錄；沒有 resource 模組（Windows）時真的寫入失敗那幾項略過。"""
    import errno as _errno_mod
    try:
        import resource
    except ImportError:
        resource = None
    from matplotlib.backend_bases import MouseEvent
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    conf0, auto0 = app.v["confirm_clear"].get(), app.v["autosave"].get()
    fdir_fn = sv.frozen_data_dir
    fd_orig = sv.filedialog.asksaveasfilename
    base = os.path.join(OUT, "r8")
    for dp, _dn, _fn in os.walk(base):
        os.chmod(dp, 0o755)
    shutil.rmtree(base, ignore_errors=True)
    os.makedirs(base)
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    app.v["confirm_clear"].set(True)
    csv8 = os.path.join(OUT, "r8.csv")                    # 只有這一輪用的資料：凍結檔不會事先就有
    with open(csv8, "w", encoding="utf-8") as f:
        f.write("r8 i,r8 q\n" + "\n".join(f"{math.cos(k / 5.9) * (1 + 0.3 * math.sin(k / 53.0)):.6f},{math.sin(k / 6.7):.6f}"
                                           for k in range(1300)) + "\n")
    n0 = len(app.signals)
    app.add_csv_columns_direct(csv8, None); app.refresh_list(); app.plot(keep=True); app.update()
    new = app.signals[n0:]
    si = next(x for x in new if x.name.endswith("r8 i"))
    sq = next(x for x in new if x.name.endswith("r8 q"))
    pa = si.panel
    tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.update()
    app.add_iq_magphase(); app.update()
    tree.selection_set([]); app._on_list_select(); app.update()
    der = [x for x in app.signals if x.derive and set(x.src_uids) == {si.uid, sq.uid}]
    ref = {x.uid: np.asarray(x.get_data(), float).copy() for x in der}
    names = [x.name for x in der]
    ok_setup = sq.panel == pa and len(der) == 2 and all(x.panel != pa for x in der)
    check(ok_setup, f"第八輪準備：P{pa}＝r8 i／r8 q，幅度、相位在 {[f'P{x.panel}' for x in der]}")
    if not ok_setup:
        return

    def _state():
        return [(x.uid, x.panel, x.derive, x.src, x.path, x.column, x.key, x.visible) for x in app.signals]

    def _undo_ids():
        return ([(e["desc"], id(e["state"])) for e in app.undo._undo], [(e["desc"], id(e["state"])) for e in app.undo._redo])

    def _linked():
        now = [app.find_signal_by_uid(x.uid) for x in der]
        return all(x is not None and x.derive and set(x.src_uids) == {si.uid, sq.uid}
                   and np.array_equal(np.asarray(x.get_data(), float), ref[x.uid], equal_nan=True) for x in now)

    def _undo_if_done(ud_before):
        if len(app.undo._undo) > len(ud_before[0]):          # 修正前的版本照樣刪掉了：這一項已經判失敗，復原回來，下一項才測得到
            app.undo_action(); app.update()

    def _limited(fn, limit=4096):
        """fn 只在這一下有檔案大小上限（真的寫入失敗：寫到 limit 位元組時核心回 EFBIG）。"""
        def g():
            soft, hard = resource.getrlimit(resource.RLIMIT_FSIZE)
            resource.setrlimit(resource.RLIMIT_FSIZE, (limit, hard))
            try:
                fn()
            finally:
                resource.setrlimit(resource.RLIMIT_FSIZE, (soft, hard))
        return g

    def _dir(tag):
        d = os.path.join(base, tag, "frozen")
        os.makedirs(d)
        return d

    def _left(d):
        """資料夾裡的 .npy／暫存檔（登記檔不算）。"""
        return sorted(n for n in os.listdir(d) if not n.startswith(sv.FROZEN_LOCK_PREFIX)) if os.path.isdir(d) else []

    def _x_click():
        x_, y_ = _close_xy(pa)
        MouseEvent("button_press_event", app.canvas, x_, y_, button=1)._process()
        MouseEvent("button_release_event", app.canvas, x_, y_, button=1)._process()
        app.update()

    def _line_delete():
        menus.clear(); menu_objs.clear()
        _line_click(si, 0.4, button=3)
        pre = sv.tr("刪除這條訊號（{name}）").split("{")[0]
        lab = next((x for x in (menus[-1] if menus else []) if x.startswith(pre)), None)
        if lab is not None:
            invoke_menu(menu_objs[-1], lab)

    def _own_cut():
        tree.selection_set([f"s{si.uid}"]); app._on_list_select(); app.update()
        app.actions["edit.cut"].run()

    efbig = sv.tr("{desc}（{raw}）").format(desc=sv.tr("檔案超過大小上限"), raw=f"[Errno {_errno_mod.EFBIG}] {os.strerror(_errno_mod.EFBIG)}")
    eacces = sv.tr("{desc}（{raw}）").format(desc=sv.tr("沒有寫入權限"), raw=f"[Errno {_errno_mod.EACCES}] {os.strerror(_errno_mod.EACCES)}")
    t_del, t_cut = sv.tr("刪除已取消"), sv.tr("剪下已取消")
    # ---- (1) 真的寫入失敗（EFBIG）：每種入口都取消、原因看得懂
    if resource is None:
        check(True, "第八輪：（沒有 resource 模組：真的寫入失敗那幾項略過）")
    else:
        entries = [("panel 左上角 ×", _x_click, t_del),
                   ("點 panel 空白（跟著選）＋Delete", lambda: (_click_empty(_ax(pa)), tk_key(w, "Delete")), t_del),
                   ("清單自己選的「r8 i」＋⌘X", _own_cut, t_cut),
                   ("線上右鍵「刪除這條訊號」（平移模式）", _line_delete, t_del)]
        for label, fn, title in entries:
            _set_mode("pan")
            tk_key(w, "Escape"); app.update()
            tree.selection_set([]); app._on_list_select(); app.update()
            st0, ud0, clip0 = _state(), _undo_ids(), app._sig_clip
            d = _dir(f"efbig{len(os.listdir(base))}")
            sv.frozen_data_dir = lambda d=d: d
            try:
                calls = _with_ask(True, _limited(fn))
            finally:
                sv.frozen_data_dir = fdir_fn
            st_ = app.status_var.get()
            errs = [c for c in calls if c[0] == "showerror"]
            ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
            ok = (len(errs) == 1 and ttl == title and msg.count(efbig) == 1 and all(n in msg for n in names) and d in msg
                  and _state() == st0 and _undo_ids() == ud0 and app._sig_clip is clip0 and _linked() and not _left(d)
                  and "已取消" in st_)
            check(ok, f"第八輪 {label}／真的寫不下去（EFBIG）：整個取消（什麼都沒移除 {_state() == st0}、復原記錄不變 {_undo_ids() == ud0}、"
                      f"衍生訊號照舊連著 {_linked()}、資料夾沒留檔 {_left(d)}）；錯誤視窗 {len(errs)} 個「{ttl}」，原因看得懂"
                      f"（{msg.count(efbig)} 次）：{msg[msg.find(sv.tr('原因：{reason}').split('{')[0]):][:70]!r}")
            _undo_if_done(ud0)
        # English 介面
        _set_mode("pan")
        tk_key(w, "Escape"); app.update()
        lang0 = pk.i18n.get_language()
        d = _dir("efbig_en")
        st0, ud0 = _state(), _undo_ids()
        pk.i18n.set_language("en")
        sv.frozen_data_dir = lambda: d
        try:
            calls = _with_ask(True, _limited(lambda: app.delete_panel(pa)))
        finally:
            sv.frozen_data_dir = fdir_fn
            pk.i18n.set_language(lang0)
        errs = [c for c in calls if c[0] == "showerror"]
        ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
        want_en = f"Reason: the file exceeds the size limit ([Errno {_errno_mod.EFBIG}] {os.strerror(_errno_mod.EFBIG)})"
        cjk = re.findall(r"[　-〿一-鿿＀-￯]", ttl + msg)
        check(len(errs) == 1 and ttl == "Deletion cancelled" and want_en in msg and not cjk and _state() == st0 and _undo_ids() == ud0,
              f"第八輪 English 介面、真的寫不下去：原因 {want_en in msg}（{msg[msg.find('Reason'):][:80]!r}），沒有中文（{cjk[:4]}）")
        _undo_if_done(ud0)
    # ---- (2) frozen 資料夾唯讀、要存的資料已經在資料夾裡（刪除 → ⌘Z 留下的）：照樣整個取消
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    probe_ro = os.path.join(base, "probe_ro")
    os.makedirs(probe_ro)
    os.chmod(probe_ro, 0o555)
    try:
        with open(os.path.join(probe_ro, "probe"), "w"):
            pass
        ro_ok = False                                      # 唯讀資料夾照樣寫得進去（Windows、系統管理員）：唯讀那幾項略過
    except OSError:
        ro_ok = True
    finally:
        os.chmod(probe_ro, 0o755)
    if not ro_ok:
        check(True, "第八輪：（這個環境的唯讀資料夾照樣寫得進去：唯讀那幾項略過）")
    dR = _dir("ro_existing")
    sv.frozen_data_dir = lambda: dR
    try:
        calls0 = _with_ask(True, lambda: app.delete_panel(pa))
        made = sorted(n for n in os.listdir(dR) if n.endswith(".npy"))
        freed = all(not x.derive for x in (app.find_signal_by_uid(d_.uid) for d_ in der) if x is not None)
        app.undo_action(); app.update()
        lk = app._frozen_lock
        reg_ok = lk is not None and lk.valid() and os.path.dirname(lk.path) == dR
        results_ro = []
        for registered in ((True, False) if ro_ok else ()):
            if not registered and app._frozen_lock is not None:
                app._frozen_lock.release(); app._frozen_lock = None      # 這個視窗沒登記（例如開的時候資料夾就唯讀）
            st0, ud0 = _state(), _undo_ids()
            os.chmod(dR, 0o555)
            try:
                calls = _with_ask(True, lambda: app.delete_panel(pa))
            finally:
                os.chmod(dR, 0o755)
            errs = [c for c in calls if c[0] == "showerror"]
            msg = str(errs[0][1][1]) if errs else ""
            ok = (len(errs) == 1 and msg.count(eacces) == 1 and sv.FROZEN_LOCK_PREFIX not in msg and all(n in msg for n in names)
                  and _state() == st0 and _undo_ids() == ud0 and _linked()
                  and sorted(n for n in os.listdir(dR) if n.endswith(".npy")) == made)
            results_ro.append(ok)
            check(ok, f"第八輪：frozen 資料夾唯讀、兩條的資料已經在資料夾裡、這個視窗{'已' if registered else '沒'}登記 → 照「寫不進去就整個不刪」取消"
                      f"（以前照樣刪除）：錯誤視窗 {len(errs)} 個、原因「沒有寫入權限」{msg.count(eacces)} 次、不寫登記檔名、什麼都沒移除"
                      f"（{_state() == st0}）、檔案還在（{sorted(n for n in os.listdir(dR) if n.endswith('.npy')) == made}）")
            _undo_if_done(ud0)
        calls1 = _with_ask(True, lambda: app.delete_panel(pa))           # 資料夾恢復可寫：照常刪除、用已經存好的檔
        again = [app.find_signal_by_uid(d_.uid) for d_ in der]
        ok_again = (all(x is not None and not x.derive and os.path.basename(x.path) in made for x in again)
                    and not [c for c in calls1 if c[0] == "showerror"] and app._frozen_lock is not None and app._frozen_lock.valid())
        app.undo_action(); app.update()
    finally:
        sv.frozen_data_dir = fdir_fn
    check(len(made) == 2 and freed and reg_ok and ok_again and _linked() and not [c for c in calls0 if c[0] == "showerror"],
          f"第八輪：資料夾可寫時照常刪除（存了 {made}）、⌘Z 連結回來；資料夾恢復可寫之後再刪照常、重新登記、用同一份檔（{ok_again}）")
    # ---- (3) 自動存檔、匯出設定寫到一半寫不下去：原本的檔不動、不留暫存檔、不清凍結檔
    if resource is None:
        check(True, "第八輪：（沒有 resource 模組：自動存檔、匯出設定寫不下去那幾項略過）")
    else:
        fdir = fdir_fn()
        os.makedirs(fdir, exist_ok=True)

        def _tmps(folder, stem):
            return sorted(n for n in os.listdir(folder) if n.startswith("." + stem + ".") and n.endswith(".tmp"))
        res_auto = []
        for on in (True, False):
            app.v["autosave"].set(on)
            app.save_autosave(); app.update()                         # 寫得進去：上一份
            before = open(sv.AUTOSAVE_PATH, "rb").read()
            orphan = os.path.join(fdir, f"r8orphan{int(on)}_{'0' * 19}{int(on)}.npy")
            np.save(orphan, np.arange(3.0))                            # 沒人用到的凍結檔：寫成功才會清
            err = []

            def _save():
                try:
                    app.save_autosave()
                except OSError as e_:
                    err.append(e_)
            _limited(_save, limit=max(1, len(before) // 2))()
            after = open(sv.AUTOSAVE_PATH, "rb").read()
            ok = (len(err) == 1 and getattr(err[0], "errno", None) == _errno_mod.EFBIG and after == before
                  and not _tmps(os.path.dirname(sv.AUTOSAVE_PATH), os.path.basename(sv.AUTOSAVE_PATH)) and os.path.isfile(orphan))
            res_auto.append(ok)
            check(ok, f"第八輪：自動存檔（「自動還原上次」{'開' if on else '關'}）寫到一半寫不下去 → 丟 OSError（{[getattr(e_, 'errno', None) for e_ in err]}）、"
                      f"上一份一個位元組都不動（{after == before}，{len(after)} bytes）、不留暫存檔、不清凍結檔（{os.path.isfile(orphan)}）")
            app.save_autosave(); app.update()                         # 寫得進去：照常清掉沒人用到的
            if os.path.exists(orphan):
                os.remove(orphan)
        app.v["autosave"].set(auto0)
        p_exp = os.path.join(base, "exp.json")
        app.save_settings(p_exp, embed_frozen=True)
        before = open(p_exp, "rb").read()
        sv.filedialog.asksaveasfilename = lambda **k: p_exp
        try:
            calls = _with_ask(True, _limited(app.export_settings_dialog, limit=max(1, len(before) // 2)))
        finally:
            sv.filedialog.asksaveasfilename = fd_orig
        after = open(p_exp, "rb").read()
        errs = [c for c in calls if c[0] == "showerror"]
        check(len(errs) == 1 and after == before and not _tmps(base, "exp.json"),
              f"第八輪：匯出設定蓋過舊檔時寫不下去 → 錯誤視窗（{len(errs)}）、舊檔一個位元組都不動（{after == before}）、不留暫存檔")
    # ---- (4) 匯入帶資料的設定檔、這台電腦的 frozen 資料夾寫不進去：警告寫真正的原因，不寫成「找不到檔案」
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    if ro_ok:
        _s37_round8_import(pa, der, names, base, fdir_fn, eacces, _dir, _linked)
    # ---- 收尾
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    gone8 = [x for x in app.signals if x.uid in {si.uid, sq.uid} | {d_.uid for d_ in der}]
    if gone8:
        app._remove_signals(gone8)
    app.undo.clear(); app._update_undo_buttons(); app._sig_clip = []; app.update()
    for dp, _dn, _fn in os.walk(base):
        os.chmod(dp, 0o755)
    app.v["confirm_clear"].set(conf0)
    app.v["autosave"].set(auto0)
    _set_mode("")


def _s37_round8_import(pa, der, names, base, fdir_fn, eacces, _dir, _linked):
    """第八輪 (4)：匯入帶資料的設定檔（U9）、這台電腦的 frozen 資料夾唯讀 → 錯誤視窗寫出哪幾條、資料夾、真正的原因，不寫成「找不到檔案」。
    第九輪（2026-10-26 使用者決定 U14）起整個不匯入：目前的工作階段一點都不動（第八輪是換掉工作階段、略過那幾條、⌘Z 回得去）。"""
    import json
    dE = _dir("export_src")
    sv.frozen_data_dir = lambda: dE
    try:
        _with_ask(True, lambda: app.delete_panel(pa))                 # 兩條改成獨立訊號（資料在 dE）
        frz = [app.find_signal_by_uid(d_.uid) for d_ in der]
        frz_ok = all(x is not None and not x.derive for x in frz)     # ⌘Z 會把同一個物件的欄位改回來：現在就記下
        frz_files = [os.path.basename(x.path) for x in frz if x is not None]
        p_imp = os.path.join(base, "with_data.json")
        app.save_settings(p_imp, embed_frozen=True)
        app.undo_action(); app.update()
    finally:
        sv.frozen_data_dir = fdir_fn
    with open(p_imp, encoding="utf-8") as f:
        emb = (json.load(f).get(sv.FROZEN_EMBED_KEY) or {})
    dI = _dir("import_ro")
    os.chmod(dI, 0o555)
    sv.frozen_data_dir = lambda: dI
    n_before, u_before = len(app.signals), len(app.undo._undo)
    try:
        calls = _with_ask(True, lambda: app.load_settings(p_imp))
    finally:
        sv.frozen_data_dir = fdir_fn
        os.chmod(dI, 0o755)
    errs = [str(c[1][1]) for c in calls if c[0] == "showerror"]
    warns = [c for c in calls if c[0] == "showwarning"]
    msg = errs[-1] if errs else ""
    nf = sv.tr("找不到檔案，已略過：\n")
    untouched = len(app.signals) == n_before and len(app.undo._undo) == u_before and _linked()
    if len(app.undo._undo) > u_before:
        app.undo_action(); app.update()                               # 修正前的版本照樣匯入了：回到匯入之前，後面才測得到
    check(len(frz_files) == 2 and all(n_ in emb for n_ in frz_files) and frz_ok and len(errs) == 1 and not warns and dI in msg
          and msg.count(eacces) == 1 and all(n in msg for n in names) and nf not in msg and untouched,
          f"第八輪／U14：匯入帶資料的設定檔、frozen 資料夾唯讀 → 整個不匯入（工作階段一點都不動 {untouched}）、錯誤視窗寫出兩條、資料夾、"
          f"原因「沒有寫入權限」（{msg.count(eacces)} 次），不寫成「找不到檔案」：{msg[:160]!r}")


def _s37_round9():
    """第九輪（2026-10-26 使用者決定 U11–U14，第八輪的待決問題）：
    U11 貼上（⌘V、座標區右鍵「貼上到 Pn」、握把區右鍵「貼上訊號到 Pn」）要把來源已經不在的衍生訊號改成獨立訊號，frozen 資料夾卻寫不進去
        （唯讀、同名的檔案擋住、真的寫不下去 EFBIG；資料已經在唯讀的資料夾裡也一樣，這個視窗登記不了也一樣）→ 整個不貼：什麼都沒貼、
        剪貼簿（_sig_clip、CLIPBOARD）和復原記錄不變、資料夾不留檔，錯誤視窗寫出哪幾條、資料夾、原因（中文、English）；修好之後照常貼上。
    U14 匯入帶資料的設定檔（「匯出設定」的 frozen_data）、frozen 資料夾寫不進去（唯讀、EFBIG、資料已經在唯讀的資料夾裡）→ 整個不匯入：
        訊號、復原記錄、檢視設定、panel 設定、目前 panel 都不變，錯誤視窗寫出哪幾條、資料夾、原因、設定檔；修好之後照常匯入、資料一樣。
    U12 關閉時自動存檔寫不進去 → 問「照樣關閉／先不關」：「先不關」不關、狀態列說明；「照樣關閉」關；兩種上一份自動存檔都一個位元組不動。
        結束訊號（interactive=False）、系統原生的對話框開著時不問、照樣關閉、記 log；偏好設定改語言後的重開（relaunch_standalone）也問，
        「先不關」不重開。真的對話框與 SIGTERM 見 s29（獨立行程）。
    U13 自動存檔讀不了 → 另存 <名稱>.bad.json（已經有就加時間，舊的不蓋掉；內容一樣不多存）、什麼都不套用（從空的開始）、提示；
        備份還在時凍結檔一個都不清（第十輪 U15 取代「只留備份提到的」），備份刪掉之後照常清；備份不了（資料夾唯讀）就不蓋掉壞檔
        （寫自動存檔丟 OSError），資料夾恢復可寫時先補備份再寫。
    對話框全部攔下來（_with_ask），frozen 資料夾、自動存檔都在測試目錄；修正前的版本 on_close 會把 app 關掉：先把 destroy 換掉才測得下去。"""
    import json
    import errno as _errno_mod
    try:
        import resource
    except ImportError:
        resource = None
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    conf0, auto0 = app.v["confirm_clear"].get(), app.v["autosave"].get()
    fdir_fn = sv.frozen_data_dir
    auto_path0 = sv.AUTOSAVE_PATH
    fd_open0 = sv.filedialog.askopenfilename
    base = os.path.join(OUT, "r9")
    for dp, _dn, _fn in os.walk(base):
        os.chmod(dp, 0o755)
    shutil.rmtree(base, ignore_errors=True)
    os.makedirs(base)
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    app.v["confirm_clear"].set(False)
    csv9 = os.path.join(OUT, "r9.csv")                    # 只有這一輪用的資料：凍結檔不會事先就有
    with open(csv9, "w", encoding="utf-8") as f:
        f.write("r9 i,r9 q\n" + "\n".join(f"{math.cos(k / 6.1) * (1 + 0.25 * math.sin(k / 47.0)):.6f},{math.sin(k / 7.7):.6f}"
                                           for k in range(1300)) + "\n")
    n0 = len(app.signals)
    app.add_csv_columns_direct(csv9, None); app.refresh_list(); app.plot(keep=True); app.update()
    new = app.signals[n0:]
    si = next(x for x in new if x.name.endswith("r9 i"))
    sq = next(x for x in new if x.name.endswith("r9 q"))
    pa = si.panel
    tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select(); app.update()
    app.add_iq_magphase(); app.update()
    tree.selection_set([]); app._on_list_select(); app.update()
    der = [x for x in app.signals if x.derive and set(x.src_uids) == {si.uid, sq.uid}]
    mag = next((x for x in der if x.derive == "iq_mag"), None)
    ph = next((x for x in der if x.derive != "iq_mag"), None)
    ok_setup = sq.panel == pa and len(der) == 2 and mag is not None and ph is not None and mag.panel != pa and ph.panel != pa
    check(ok_setup, f"第九輪準備：P{pa}＝r9 i／r9 q，幅度、相位在 {[f'P{x.panel}' for x in der]}")
    if not ok_setup:
        return
    ref_mag = np.asarray(mag.get_data(), float).copy()
    ref_ph = np.asarray(ph.get_data(), float).copy()
    mag_name = mag.name

    def _dir(tag):
        d = os.path.join(base, tag, "frozen")
        os.makedirs(d)
        return d

    def _left(d):
        """資料夾裡的 .npy／暫存檔（登記檔不算）。"""
        return sorted(n for n in os.listdir(d) if not n.startswith(sv.FROZEN_LOCK_PREFIX)) if os.path.isdir(d) else []

    def _state():
        return [(x.uid, x.panel, x.derive, x.src, x.path, x.column, x.key, x.label, x.visible) for x in app.signals]

    def _undo_ids():
        return ([(e["desc"], id(e["state"])) for e in app.undo._undo], [(e["desc"], id(e["state"])) for e in app.undo._redo])

    def _clip_ids():
        return (id(app._sig_clip), [id(x) for x in app._sig_clip], [id(x) for x in sv.CLIPBOARD])

    def _limited(fn, limit=4096):
        """fn 只在這一下有檔案大小上限（真的寫入失敗：寫到 limit 位元組時核心回 EFBIG）。"""
        def g():
            soft, hard = resource.getrlimit(resource.RLIMIT_FSIZE)
            resource.setrlimit(resource.RLIMIT_FSIZE, (limit, hard))
            try:
                fn()
            finally:
                resource.setrlimit(resource.RLIMIT_FSIZE, (soft, hard))
        return g

    def _why(desc, no):
        return sv.tr("{desc}（{raw}）").format(desc=sv.tr(desc), raw=f"[Errno {no}] {os.strerror(no)}")

    efbig, eacces = _why("檔案超過大小上限", _errno_mod.EFBIG), _why("沒有寫入權限", _errno_mod.EACCES)
    probe_ro = os.path.join(base, "probe_ro")
    os.makedirs(probe_ro)
    os.chmod(probe_ro, 0o555)
    try:
        with open(os.path.join(probe_ro, "probe"), "w"):
            pass
        ro_ok = False                                      # 唯讀資料夾照樣寫得進去（Windows、系統管理員）：唯讀那幾項略過
    except OSError:
        ro_ok = True
    finally:
        os.chmod(probe_ro, 0o755)
    if not ro_ok:
        check(True, "第九輪：（這個環境的唯讀資料夾照樣寫得進去：唯讀那幾項略過）")
    # ---- U11 準備：⌘X 幅度（來源還在，不用改）→ 刪掉來源的 panel（資料夾可寫：相位改成獨立訊號）→ 剪貼簿裡的幅度沒有來源了
    dW = _dir("src")
    sv.frozen_data_dir = lambda: dW
    try:
        tree.selection_set([f"s{mag.uid}"]); app._on_list_select(); app.update()
        _with_ask(True, lambda: app.actions["edit.cut"].run())
        _with_ask(True, lambda: app.delete_panel(pa))
    finally:
        sv.frozen_data_dir = fdir_fn
    clip_ok = (len(app._sig_clip) == 1 and app._sig_clip[0].get("derive") == "iq_mag" and sv.CLIP_RAW_KEY in app._sig_clip[0]
               and app.find_signal_by_uid(si.uid) is None and app.find_signal_by_uid(mag.uid) is None
               and not ph.derive and os.path.dirname(ph.path) == dW)
    check(clip_ok, f"第九輪準備：剪貼簿是剪下的幅度（帶著那時的資料），它的來源 P{pa} 已經刪掉、相位改成獨立訊號（{os.path.basename(ph.path or '')}）")
    if not clip_ok:
        return
    pt = ph.panel                                          # 貼到相位那張

    def _paste_key():
        app._set_current_panel(pt, announce=False)
        tk_key(w, "v", char="v", mods="Command" if sys.platform == "darwin" else "Control")

    def _paste_menu(where):
        def f():
            _set_mode("" if where == "axes" else "pan")
            menus.clear(); menu_objs.clear()
            if where == "handle":
                ax_ = _ax(pt)
                _press_at(ax_.bbox.x0 - 20, (ax_.bbox.y0 + ax_.bbox.y1) / 2, button=3)
                lab = sv.tr("貼上訊號到 P{p}").format(p=pt)
            else:
                _click_empty(_ax(pt), button=3)
                lab = sv.tr("貼上到 P{p}").format(p=pt)
            if not (menu_objs and invoke_menu(menu_objs[-1], lab)):
                print(f"（找不到選單項目 {lab!r}：{menus[-1] if menus else None}）")
        return f

    class _Fail:
        """frozen 資料夾寫不進去的一種情況：ro＝唯讀資料夾、file＝同名的檔案擋在資料夾的位置、efbig＝真的寫不下去（RLIMIT_FSIZE）。"""

        def __init__(self, kind):
            self.kind = kind
            self.dir = os.path.join(base, f"{kind}{len(os.listdir(base))}", "frozen")

        def __enter__(self):
            if self.kind == "file":
                os.makedirs(os.path.dirname(self.dir))
                with open(self.dir, "w") as f_:
                    f_.write("not a folder")
            else:
                os.makedirs(self.dir)
                if self.kind == "ro":
                    os.chmod(self.dir, 0o500)
            sv.frozen_data_dir = lambda d=self.dir: d
            return self

        def run(self, fn):
            return _with_ask(True, _limited(fn) if self.kind == "efbig" else fn)

        def __exit__(self, *exc):
            sv.frozen_data_dir = fdir_fn
            if os.path.isdir(self.dir):
                os.chmod(self.dir, 0o755)
            return False

    reason = {"ro": eacces, "file": sv.tr("有同名的檔案或資料夾擋住"), "efbig": efbig}
    kname = {"ro": "唯讀資料夾", "file": "同名的檔案擋在資料夾的位置", "efbig": "真的寫不下去（EFBIG）"}
    kinds = (["ro"] if ro_ok else []) + ["file"] + (["efbig"] if resource is not None else [])

    def _paste_cancelled(calls, d, why, st0, ud0, cl0, clip_items0):
        errs = [c for c in calls if c[0] == "showerror"]
        ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
        st_ = app.status_var.get()
        ok = (len(errs) == 1 and ttl == sv.tr("貼上已取消") and mag_name in msg and d in msg and msg.count(why) == 1
              and _state() == st0 and _undo_ids() == ud0 and _clip_ids() == cl0
              and all(a is b for a, b in zip(app._sig_clip, clip_items0)) and "已取消" in st_
              and not [c for c in calls if c[0] != "showerror"])
        if len(app.undo._undo) > len(ud0[0]):            # 修正前的版本照樣貼上了：這一項已經判失敗，復原回來，下一項才測得到
            app.undo_action(); app.update()
        return ok, errs, msg, st_

    entries = [("⌘V（焦點在圖上）", _paste_key), ("座標區右鍵「貼上到 Pn」（沒有工具列模式）", _paste_menu("axes")),
               ("握把區右鍵「貼上訊號到 Pn」", _paste_menu("handle"))]
    for label, fn in entries:
        for kind in kinds:
            _set_mode("pan")
            tk_key(w, "Escape"); app.update()
            st0, ud0, cl0, items0 = _state(), _undo_ids(), _clip_ids(), list(app._sig_clip)
            with _Fail(kind) as fl:
                calls = fl.run(fn)
                left = _left(fl.dir)
            ok, errs, msg, st_ = _paste_cancelled(calls, fl.dir, reason[kind], st0, ud0, cl0, items0)
            check(ok and not left,
                  f"U11 {label}／{kname[kind]}：整個不貼——清單不變（{_state() == st0}）、復原記錄不變（{_undo_ids() == ud0}）、剪貼簿不變"
                  f"（{_clip_ids() == cl0}）、資料夾沒留檔（{left}）；錯誤視窗 {len(errs)} 個寫出那一條、資料夾、原因"
                  f"（{msg.count(reason[kind])} 次）；狀態列「{st_[:34]}」")
    # 資料夾可寫：照常貼上，改成獨立訊號、資料和剪下那時一樣；⌘Z 拿掉，檔案留著（重做會用到）
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    dP = _dir("paste_ok")
    sv.frozen_data_dir = lambda: dP
    try:
        calls = _with_ask(True, _paste_key)
        pm = next((x for x in app.signals if x.name == mag_name and x.panel == pt), None)
        ok_paste = (pm is not None and not pm.derive and os.path.dirname(pm.path) == dP
                    and np.array_equal(np.asarray(pm.get_data(), float), ref_mag, equal_nan=True)
                    and not [c for c in calls if c[0] == "showerror"] and sv.tr("改成獨立訊號") in app.status_var.get())
        made = [n for n in os.listdir(dP) if n.endswith(".npy")]
        if pm is not None:
            app.undo_action(); app.update()
    finally:
        sv.frozen_data_dir = fdir_fn
    check(ok_paste and len(made) == 1 and app.find_signal_by_uid(pm.uid if pm else -1) is None,
          f"U11：資料夾可寫時照常貼上，幅度改成獨立訊號、資料和剪下那時一樣（{ok_paste}，{made}）；⌘Z 拿掉")
    # 資料已經在資料夾裡、資料夾唯讀：照樣整個不貼（已登記、沒登記兩種）
    for registered in ((True, False) if ro_ok else ()):
        _set_mode("pan")
        tk_key(w, "Escape"); app.update()
        sv.frozen_data_dir = lambda: dP
        try:
            app._frozen_register(create=True)
            if not registered and app._frozen_lock is not None:
                app._frozen_lock.release(); app._frozen_lock = None      # 這個視窗沒登記（例如開的時候資料夾就唯讀）
            st0, ud0, cl0, items0 = _state(), _undo_ids(), _clip_ids(), list(app._sig_clip)
            os.chmod(dP, 0o500)
            try:
                calls = _with_ask(True, _paste_key)
            finally:
                os.chmod(dP, 0o755)
            ok, errs, msg, st_ = _paste_cancelled(calls, dP, eacces, st0, ud0, cl0, items0)
        finally:
            sv.frozen_data_dir = fdir_fn
        check(ok and sorted(n for n in os.listdir(dP) if n.endswith(".npy")) == sorted(made) and sv.FROZEN_LOCK_PREFIX not in msg,
              f"U11：資料已經在 frozen 資料夾裡、資料夾唯讀、這個視窗{'已' if registered else '沒'}登記 → 照樣整個不貼"
              f"（錯誤視窗 {len(errs)} 個，原因「沒有寫入權限」{msg.count(eacces)} 次，不寫登記檔名）")
    # English 介面
    if ro_ok:
        _set_mode("pan")
        tk_key(w, "Escape"); app.update()
        lang0 = pk.i18n.get_language()
        st0, ud0, cl0, items0 = _state(), _undo_ids(), _clip_ids(), list(app._sig_clip)
        pk.i18n.set_language("en")
        try:
            with _Fail("ro") as fl:
                calls = fl.run(_paste_key)
            st_en = app.status_var.get()
        finally:
            pk.i18n.set_language(lang0)
        errs = [c for c in calls if c[0] == "showerror"]
        ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
        cjk = re.findall(r"[　-〿一-鿿＀-￯]", ttl + msg + st_en)
        check(len(errs) == 1 and ttl == "Paste cancelled" and not cjk and "Reason: no permission to write" in msg and mag_name in msg
              and _state() == st0 and _clip_ids() == cl0,
              f"U11 English 介面：「{ttl}」，內容與狀態列沒有中文（{cjk[:4]}）：{msg[:100]!r}")
        if len(app.undo._undo) > len(ud0[0]):
            app.undo_action(); app.update()
    # 剪貼簿裡還有一般訊號（不用改的）：照樣整個不貼——一般訊號也不貼
    other = next((x for x in app.signals if not x.derive and x.column is not None and x.panel != pt), None)
    if ro_ok and other is not None:
        _set_mode("pan")
        tk_key(w, "Escape"); app.update()
        clip_keep = app._sig_clip
        app._sig_clip = [other.to_dict()] + list(clip_keep)
        st0, ud0, cl0, items0 = _state(), _undo_ids(), _clip_ids(), list(app._sig_clip)
        with _Fail("ro") as fl:
            calls = fl.run(_paste_key)
        ok, errs, msg, st_ = _paste_cancelled(calls, fl.dir, eacces, st0, ud0, cl0, items0)
        app._sig_clip = clip_keep
        listed = msg.split("\n" + sv.tr("資料夾：{path}").split("{")[0])[0]    # 資料夾那一行之前：做了什麼＋哪幾條（說明那句也有「frozen 資料夾：」）
        check(ok and mag_name in listed and other.name not in listed and sv.tr("（共 {n} 條訊號）").format(n=2) in msg,
              f"U11：剪貼簿裡另有一條一般訊號（{other.name}）時照樣整個不貼，一般訊號也沒貼上（{_state() == st0}），錯誤視窗只列要改成獨立訊號的那條"
              f"（{ok}；對話框 {[c[0] for c in calls]}；{msg[:150]!r}；狀態列 {st_[:40]!r}）")
    # ---- U14：匯入帶資料的設定檔，frozen 資料夾寫不進去 → 整個不匯入
    _set_mode("pan")
    tk_key(w, "Escape"); app.update()
    sv.frozen_data_dir = lambda: dP
    try:
        _with_ask(True, _paste_key)                       # 幅度、相位兩條獨立訊號都在
    finally:
        sv.frozen_data_dir = fdir_fn
    two = [x for x in app.signals if x.name in (mag_name, ph.name) and not x.derive]
    p_exp = os.path.join(base, "with_data.json")
    app.save_settings(p_exp, embed_frozen=True)
    with open(p_exp, encoding="utf-8") as f:
        emb = json.load(f).get(sv.FROZEN_EMBED_KEY) or {}
    ok_exp = len(two) == 2 and {os.path.basename(x.path) for x in two} <= set(emb)
    check(ok_exp, f"U14 準備：匯出設定帶著幅度、相位兩條獨立訊號的資料（{sorted(emb)}）")
    app._remove_signals(two); app.update()               # 目前的工作階段裡沒有這兩條（匯入了才看得出來）
    grid0 = bool(app.v["grid"].get())
    app.v["grid"].set(not grid0)                          # 和設定檔不一樣的檢視設定：沒匯入就要照舊
    names2 = sorted(x.name for x in two)

    def _sess():
        return (_state(), _undo_ids(), {k: app.v[k].get() for k in app.VIEW_KEYS}, {p: dict(pp) for p, pp in app.panel_props.items()},
                sorted(app.panel_collapsed), app._current_panel)

    def _import():
        sv.filedialog.askopenfilename = lambda **k: p_exp
        try:
            app.import_settings_dialog()
        finally:
            sv.filedialog.askopenfilename = fd_open0

    def _import_cancelled(calls, d, why, s0):
        errs = [c for c in calls if c[0] == "showerror"]
        ttl, msg = (str(errs[0][1][0]), str(errs[0][1][1])) if errs else ("", "")
        st_ = app.status_var.get()
        same = _sess() == s0
        ok = (len(errs) == 1 and ttl == sv.tr("匯入已取消") and all(n in msg for n in names2) and d in msg and p_exp in msg
              and msg.count(why) == 1 and same and not [c for c in calls if c[0] != "showerror"] and "已取消" in st_)
        if len(app.undo._undo) > len(s0[1][0]):         # 修正前的版本照樣匯入了：回到匯入之前，下一項才測得到
            app.undo_action(); app.update()
        return ok, errs, msg, same
    for kind in [k for k in kinds if k != "file"] + ["file"]:
        _set_mode("pan")
        s0 = _sess()
        with _Fail(kind) as fl:
            calls = fl.run(_import)
            left = _left(fl.dir)
        ok, errs, msg, same = _import_cancelled(calls, fl.dir, reason[kind], s0)
        check(ok_exp and ok and not left,
              f"U14 匯入帶資料的設定檔／{kname[kind]}：整個不匯入——訊號、復原記錄、檢視設定、panel 設定、目前 panel 都不變（{same}），"
              f"資料夾沒留檔（{left}）；錯誤視窗 {len(errs)} 個寫出兩條、資料夾、原因（{msg.count(reason[kind])} 次）、設定檔：{msg[:120]!r}")
    # 資料夾可寫：照常匯入、資料一樣；⌘Z 回到匯入之前；資料已經在資料夾裡、資料夾唯讀：照樣整個不匯入
    dI = _dir("import_ok")
    sv.frozen_data_dir = lambda: dI
    try:
        calls = _with_ask(True, _import)
        got = {x.name: x for x in app.signals}
        ok_imp = (all(n in got and os.path.dirname(got[n].path) == dI for n in names2)
                  and np.array_equal(np.asarray(got[mag_name].get_data(), float), ref_mag, equal_nan=True)
                  and np.array_equal(np.asarray(got[ph.name].get_data(), float), ref_ph, equal_nan=True)
                  and not [c for c in calls if c[0] in ("showerror", "showwarning")])
        app.undo_action(); app.update()
    finally:
        sv.frozen_data_dir = fdir_fn
