@step
def s37_panel_selection_xaxis_panner():
    """第 10、11、12 項：點 panel → 清單選它的全部訊號（四種模式、右鍵、握把區；點線照舊；拖曳不改清單；只反白不加粗；
    跟著選的 Delete＝刪除 panel 並照「清空前確認」先問；握把選取後 Delete 刪整個 panel、平移／放大模式也一樣；Esc 取消）；
    每個 panel 都有 x 刻度字與 x 軸標籤（連結、單位一樣也有；收合規則與矮列下的空隙；不重疊、圖不被壓扁；存成別的大小重排；
    右緣的刻度字；全部放進視窗）；平移器只畫目前 panel、點別張馬上換、x 單位跟著、拖縮放窗動目前 panel、連結的跟著（Symbol rate
    不同的換算）、沒連結的不動。"""
    from matplotlib.colors import to_hex
    s1, q1, s2, q2, clk = _s36_setup()
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    tree = app.sig_tree
    w = app.canvas.get_tk_widget()
    conf0 = app.v["confirm_clear"].get()
    app.v["confirm_clear"].set(False)
    # ================================ 第 10 項：點 panel → 清單選它的全部訊號 ================================
    for mode, name in (("pan", "平移模式（啟動預設）"), ("zoom", "放大模式"), ("tips", "資料提示模式"), ("", "沒有工具列模式")):
        _set_mode(mode)
        tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()         # 原本選了 P1 的一條
        _click_empty(_ax(p2))
        got2, cur2, lw2, fol2 = _sel_uids(), app.current_panel(), _lws(p2), app._follow_panel()
        _click_empty(_ax(p1))
        got1, cur1 = _sel_uids(), app.current_panel()
        if mode:
            check(got2 == _panel_uids(p2) and cur2 == p2 and got1 == _panel_uids(p1) and cur1 == p1,
                  f"{name}：點 P2 空白 → 清單換成 P2 的全部訊號（取代原本的選取）；再點 P1 → 換成 P1 的（{sorted(got2)}／{sorted(got1)}）")
            check(lw2 and all(abs(a - b) < 1e-9 for a, b in lw2),
                  f"{name}：點 P2 時清單跟著選的只反白，P2 的線不加粗（存圖、複製圖也不變；線寬 {lw2}）")
        else:                                               # U2：沒有工具列模式＝0.9.8／MATLAB plot edit：點空白取消選取
            check(got2 == set() and fol2 is None and cur2 == p2 and got1 == set() and cur1 == p1,
                  f"{name}（U2）：點 P2 空白 → 取消清單選取（不選它的訊號）、目前 panel＝P2；點 P1 一樣（{sorted(got2)}／{sorted(got1)}）")
        if mode == "zoom":
            app.show_all_x(); app.update()                  # 放大模式單擊會放大：還原
    _set_mode("")
    if not HL:                                              # 走 Tk 事件的真實路徑
        for mode in ("pan", ""):
            _set_mode(mode)
            tree.selection_set([f"s{q1.uid}"]); app._on_list_select(); app.update()
            ax2 = _ax(p2)
            fx, fy = _empty_at(ax2)
            time.sleep(0.6)
            tk_click(app.canvas, ax2.bbox.x0 + fx * ax2.bbox.width, ax2.bbox.y0 + fy * ax2.bbox.height); app.update()
            if mode:
                check(_sel_uids() == _panel_uids(p2) and app.current_panel() == p2, f"Tk 事件、平移模式點 P2 空白：清單選 P2 的訊號（{sorted(_sel_uids())}）")
            else:
                check(not _sel_uids() and app.current_panel() == p2, f"Tk 事件、沒有工具列模式點 P2 空白（U2）：取消清單選取、目前 panel＝P2（{sorted(_sel_uids())}）")
        _set_mode("")
    # 點在線上：沒有工具列模式＝選那一條、加粗；資料提示模式＝釘提示；平移／放大模式也選那一條（U1）
    tree.selection_set([]); app._on_list_select(); app.update()
    _line_click(s2, 0.33)
    lw_s2 = app.render_info["artists"][s2.uid]
    check(_sel_uids() == {s2.uid} and app.current_panel() == p2 and abs(lw_s2["line"].get_linewidth() - 2.5 * float(lw_s2["lw"])) < 1e-9,
          f"沒有工具列模式點在 P2 的線上：照舊只選那一條、那條線照舊加粗（{sorted(_sel_uids())}）")
    _line_click(q2, 0.6, shift=True)
    check(_sel_uids() == {s2.uid, q2.uid}, f"Shift＋點另一條線：照舊加選（{sorted(_sel_uids())}）")
    app.v_tips.set(True); app._on_tips_toggle(); app.update()
    _click_empty(_ax(p1))
    n_tip = len(app.datatips)
    _line_click(s2, 0.45)
    check(len(app.datatips) == n_tip + 1 and not tree.selection() and app.current_panel() == p2,
          f"資料提示模式點在 P2 的線上：照舊釘資料提示（清單不換成整個 panel；提示和清單選取互斥）"
          f"（提示 {n_tip}→{len(app.datatips)}、選取 {sorted(_sel_uids())}、目前 P{app.current_panel()}）")
    app.ia.clear_tips(); app.v_tips.set(False); app._on_tips_toggle(); app.update()
    _set_mode("pan")
    _click_empty(_ax(p1))
    _line_click(q2, 0.5)
    check(_sel_uids() == {q2.uid} and _thick(q2) and app._follow_panel() is None and app.current_panel() == p2,
          f"平移模式（U1）點過 P1 再點 P2 的「b q」線：只選那一條（自己選的、加粗），目前 panel＝P2（{sorted(_sel_uids())}）")
    # 拖曳（平移、拉框放大、沒有模式拖曳平移、拖圖例）不改使用者自己在清單選的；點一下（沒拖）才換成整個 panel
    for mode, name in (("pan", "平移模式拖曳平移"), ("zoom", "放大模式拉框"), ("", "沒有工具列模式拖曳平移")):
        _set_mode(mode)
        tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
        ax2 = _ax(p2)
        fx, fy = _empty_at(ax2)
        xl0 = tuple(ax2.get_xlim())
        _drag_px(ax2.bbox.x0 + fx * ax2.bbox.width, ax2.bbox.y0 + fy * ax2.bbox.height, -0.2 * ax2.bbox.width, -0.3 * ax2.bbox.height)
        check(_sel_uids() == {q2.uid} and tuple(_ax(p2).get_xlim()) != xl0 and app.current_panel() == p2,
              f"{name}：清單自己選的 P2「b q」留著（不換成整個 panel）、x 範圍有變、目前 panel＝P2（{sorted(_sel_uids())}）")
        app.show_all_x(); app.update()
    _set_mode("")
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    app.canvas.draw()
    leg = (app.render_info["axes_right"].get(p2) or _ax(p2)).get_legend()
    lb = leg.get_window_extent(app.canvas.get_renderer())
    _drag_px((lb.x0 + lb.x1) / 2, (lb.y0 + lb.y1) / 2, -60, -10)
    check(_sel_uids() == {q2.uid}, f"沒有工具列模式拖 P2 的圖例：清單自己選的留著（{sorted(_sel_uids())}）")
    app.legend_loc.clear(); app.plot(keep=True); app.update()
    _set_mode("pan")
    _click_empty(_ax(p1))
    ax2 = _ax(p2)
    _drag_px(ax2.bbox.x0 + 0.5 * ax2.bbox.width, ax2.bbox.y0 + 0.5 * ax2.bbox.height, 80)
    check(_sel_uids() == _panel_uids(p2) and app.current_panel() == p2,
          "清單本來就是跟著選的（點過 P1）：在 P2 拖曳平移，清單跟著換成 P2（目前 panel 的框、平移器、清單一致）")
    app.show_all_x(); app.update()
    # 量測游標：點過 P1（清單跟著選）後在 P2 拖游標 → 目前 panel 換成 P2，清單也跟著（游標照樣拖得動）
    _click_empty(_ax(p1))
    app.set_dcursor_mode("two", show_panel=False); app.update(); app.canvas.draw()
    xs0 = list(app.dcur.positions())
    ax2 = _ax(p2)
    cx = float(ax2.transData.transform((xs0[0], 0.0))[0])
    _drag_px(cx, ax2.bbox.y0 + 0.5 * ax2.bbox.height, 40)
    xs1 = list(app.dcur.positions())
    check(app.current_panel() == p2 and _sel_uids() == _panel_uids(p2) and xs1[0] != xs0[0],
          f"平移模式在 P2 拖量測游標（清單本來跟著 P1）：目前 panel、清單都換成 P2，游標照樣移動（{xs0[0]:.4g} → {xs1[0]:.4g}）")
    app.set_dcursor_mode("none", show_panel=False); app.update()
    _set_mode("")
    # 滑鼠右鍵（MATLAB／README 的「左右鍵都算」）
    tree.selection_set([]); app._on_list_select(); menus.clear()
    _click_empty(_ax(p2), button=3)
    check(app.current_panel() == p2 and _sel_uids() == _panel_uids(p2) and bool(menus),
          "右鍵點 P2 空白：目前 panel＝P2、清單選 P2 的全部訊號，右鍵選單照樣出來")
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    _click_empty(_ax(p2), button=3)
    check(_sel_uids() == {q2.uid}, "右鍵點同一張圖、清單已經選了它的某一條：留著（右鍵選單對那一條）")
    _click_empty(_ax(p1), button=3)
    check(app.current_panel() == p1 and _sel_uids() == _panel_uids(p1), "右鍵換到 P1：清單換成 P1 的全部訊號")
    _set_mode("tips")                                       # 以下要「點空白＝清單跟著選」：資料提示模式（沒有工具列模式點空白是取消選取，U2）
    _click_empty(_ax(p2))
    menus.clear()
    _line_click(q2, 0.4, button=3)
    check(_sel_uids() == {q2.uid} and bool(menus) and any("刪除這條訊號" in x for x in menus[-1]),
          f"點過 P2（清單跟著選整張）再在「b q」線上按右鍵：那條線的選單、清單只選那一條（顏色、線寬只改它）（{sorted(_sel_uids())}）")
    # 點 P2 → 清單跟著選 P2 的 I、Q：AM/PM/FM 標題寫 P2（不是「清單選取」），清單右鍵的項目也寫 P2；自己在清單選的兩條照舊寫「清單選取」
    _click_empty(_ax(p2))
    win = app.open_iq_window(); app.update()
    check(win is not None and win.pairs[0][0].uid == s2.uid and f"— P{p2}：" in win.title() and "清單選取" not in win.title(),
          f"點 P2（清單跟著選了 P2 的兩條）按 AM/PM/FM：算目前 panel，標題寫 P2（{win.title() if win else None}）")
    if win is not None:
        win.destroy(); app.update()
    from types import SimpleNamespace as NS
    bbox = tree.bbox(f"s{s2.uid}")
    menus.clear()
    app._on_list_context(NS(x=(bbox[0] + 5) if bbox else 5, y=(bbox[1] + 3) if bbox else 5, x_root=0, y_root=0))
    lab = menus[-1] if menus else []
    check(f"AM/PM/FM 分析（P{p2}）…" in lab and f"GFSK（P{p2}）…" in lab and _sel_uids() == _panel_uids(p2),
          f"清單右鍵（點 P2 時跟著選的）：「AM/PM/FM 分析（P2）…」（{[x for x in lab if 'P' in x][:4]}）")
    tree.selection_set([f"s{s1.uid}"]); app._on_list_select()
    tree.selection_set([f"s{s2.uid}", f"s{q2.uid}"]); app._on_list_select(); app.update()
    win = app.open_iq_window(); app.update()
    check(win is not None and "清單選取" in win.title() and abs(app.render_info["artists"][s2.uid]["line"].get_linewidth()
                                                               - 2.5 * float(app.render_info["artists"][s2.uid]["lw"])) < 1e-9,
          f"自己在清單選 P2 的兩條（不是點 panel 跟著選的）：照舊寫「清單選取」（第 9 項）、線照舊加粗（{win.title() if win else None}）")
    if win is not None:
        win.destroy(); app.update()
    # 隱藏的訊號也選；清單捲到看得到第一列
    app.toggle_visible([q1]); app.update()
    _click_empty(_ax(p2)); _click_empty(_ax(p1))
    check(_sel_uids() == _panel_uids(p1) and q1.uid in _sel_uids() and not q1.visible, "隱藏的訊號也一起選（清單裡灰字那一列）")
    app.toggle_visible([q1]); app.update()
    seen = []
    tree.see = lambda iid: (seen.append(iid), sv.ttk.Treeview.see(tree, iid))
    try:
        tree.yview_moveto(1.0); app.update()
        _click_empty(_ax(p2)); _click_empty(_ax(p1))
    finally:
        del tree.see
    first = f"s{s1.uid}"
    check(seen and seen[-1] == first and bool(tree.bbox(first)), f"清單捲到看得到選取的第一列（see {seen[-2:]}，bbox {tree.bbox(first)}）")
    # Esc：取消跟著選的（任何模式）；自己在清單選的不動
    _set_mode("pan")
    _click_empty(_ax(p2))
    tk_key(w, "Escape"); app.update()
    check(not tree.selection() and app.current_panel() == p2, "點 P2 後按 Esc：取消跟著選的清單選取（目前 panel 不變；平移模式也一樣）")
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    tk_key(w, "Escape"); app.update()
    check(_sel_uids() == {q2.uid}, "自己在清單選的按 Esc 不動")
    # 握把區：選取 panel、清單跟著；Delete 刪整個 panel；Esc 一起取消；在清單選別的取消 panel 選取
    _set_mode("")
    tree.selection_set([]); app._on_list_select(); app.update()
    _handle_press(p2)
    app.update(); app.update()                                  # 清單選取的 <<TreeviewSelect>> 回呼也跑完
    check(app._sel_panel == p2 and _sel_uids() == _panel_uids(p2) and app.current_panel() == p2 and f"已選取 P{p2}" in app.status_var.get(),
          f"點 P2 的握把區：選取 P2、清單也選 P2 的全部訊號，清單的回呼沒有把 panel 選取取消（{app.status_var.get()[:24]}）")
    n0, n2 = len(app.signals), len(_panel_uids(p2))
    tk_key(w, "Delete"); app.update()
    check(p2 not in app.panel_order() and len(app.signals) == n0 - n2 and app._sel_panel is None,
          f"握把選取 P2 後按 Delete：照樣刪除整個 panel（{n0} → {len(app.signals)}）")
    app.undo_action(); app.update()
    check(p2 in app.panel_order() and len(app.signals) == n0, "復原刪除")
    _handle_press(p2)
    tk_key(w, "Escape"); app.update()
    check(app._sel_panel is None and not tree.selection() and not w.find_withtag("dsv_panel_sel"),
          "Esc：取消 panel 選取，跟著選的清單也一起取消")
    n0 = len(app.signals)
    tk_key(w, "Delete"); app.update()
    check(len(app.signals) == n0, "Esc 之後按 Delete：沒有選取的東西，不會刪訊號")
    _handle_press(p2)
    tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
    check(app._sel_panel is None and _sel_uids() == {s1.uid}, "握把選取後在清單選別的訊號：取消 panel 選取（照舊）")
    # 點 panel 空白（清單跟著選）後按 Delete：和握把＋Delete、× 一樣是刪除這個 panel，照「清空前確認」先問（以前不問就整張不見）
    app.v["confirm_clear"].set(True)
    for mode, name in (("tips", "資料提示模式"), ("", "沒有工具列模式（右鍵點空白跟著選）")):
        _set_mode(mode)
        _follow(p2)
        n0, n2 = len(app.signals), len(_panel_uids(p2))
        calls = _with_ask(False, lambda: tk_key(w, "Delete"))
        check(len(app.signals) == n0 and any(c[0] == "askyesno" and f"P{p2}" in str(c[1]) for c in calls),
              f"{name}：點 P2 空白後按 Delete → 先問「刪除 P2（{n2} 條訊號）？」，答「否」什麼都不刪（{calls}）")
        if len(app.signals) < n0:                      # 修正前：不問就整張刪掉了 → 復原，後面的檢查照樣跑
            app.undo_action(); app.update()
            _follow(p2)
        calls = _with_ask(True, lambda: tk_key(w, "Delete"))
        check(p2 not in app.panel_order() and len(app.signals) == n0 - n2 and len(calls) == 1,
              f"{name}：答「是」→ 刪除整個 P2（{n0} → {len(app.signals)}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
        calls = _with_ask(False, lambda: tk_key(w, "Delete"))
        check(p2 in app.panel_order() and len(app.signals) == n0 and len(calls) == 1,
              f"{name}：復原後清單仍跟著選 P2，再按 Delete 一樣先問（不會不問就刪）（{calls}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
    _set_mode("")
    _follow(p2)
    n0 = len(app.signals)
    calls = _with_ask(False, lambda: tk_key(tree, "Delete"))
    check(p2 in app.panel_order() and len(calls) == 1, f"焦點在清單時按 Delete（清單是點 P2 跟著選的）：一樣先問（{calls}）")
    if len(app.signals) < n0:
        app.undo_action(); app.update()
    # 平移／放大模式（啟動預設）點空白後按 Delete、焦點在圖上：和焦點在清單、平移器時一樣先問「刪除 P2」（第二輪審查：以前焦點在圖上不刪、
    # 在平移器或清單上卻會問並刪掉整張，結果看不見的焦點決定）
    for mode, name in (("pan", "平移模式"), ("zoom", "放大模式")):
        _set_mode(mode)
        _click_empty(_ax(p2))
        if mode == "zoom":
            app.show_all_x(); app.update()
        n0 = len(app.signals)
        calls = _with_ask(False, lambda: tk_key(w, "Delete"))
        check(p2 in app.panel_order() and len(app.signals) == n0 and len(calls) == 1 and f"P{p2}" in str(calls[0][1]),
              f"{name}點 P2 空白後按 Delete（焦點在圖上）：和焦點在清單、平移器一樣先問「刪除 P2」，答「否」不刪（{calls}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
    # 工具列「移除」、已繪訊號面板的移除鈕、清單右鍵「移除」、⌘X：清單是點 panel 跟著選的＝整張不見，一樣照「清空前確認」先問
    # （第二輪審查：以前只有 Delete 會問，這幾個入口不問就移除整張）
    from types import SimpleNamespace as NS
    rib = [b for b in app._sel_btns if str(b.cget("text")) == sv.tr("移除")]
    dock = [b for b, nm in app.sig_panel._tools if nm == "remove"]

    def _list_remove():
        bb_ = tree.bbox(f"s{q2.uid}")
        menus.clear(); menu_objs.clear()
        app._on_list_context(NS(x=(bb_[0] + 5) if bb_ else 5, y=(bb_[1] + 3) if bb_ else 5, x_root=0, y_root=0))
        if menu_objs:
            invoke_menu(menu_objs[-1], sv.tr("移除"))
    for how, fn in (("工具列「移除」", lambda: rib[0].invoke()), ("已繪訊號面板的移除鈕", lambda: dock[0].invoke()),
                    ("清單右鍵「移除」", _list_remove), ("⌘X／Ctrl+X 剪下", lambda: app.actions["edit.cut"].run())):
        _set_mode("pan")
        _click_empty(_ax(p2))
        n0 = len(app.signals)
        calls = _with_ask(False, fn)
        check(rib and dock and p2 in app.panel_order() and len(app.signals) == n0 and len(calls) == 1 and f"P{p2}" in str(calls[0][1]),
              f"點 P2 空白（清單跟著選）後按{how}：先問（{calls}），答「否」整張留著（{n0} → {len(app.signals)}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
    _click_empty(_ax(p2))
    calls = _with_ask(True, lambda: rib[0].invoke())
    check(p2 not in app.panel_order() and len(calls) == 1, f"答「是」→ 工具列「移除」刪除整個 P2（{calls}）")
    app.undo_action(); app.update()
    tree.selection_set([f"s{q2.uid}"]); app._on_list_select(); app.update()
    n0 = len(app.signals)
    calls = _with_ask(True, lambda: rib[0].invoke())
    check(len(app.signals) == n0 - 1 and app.find_signal_by_uid(q2.uid) is None and not calls,
          "清單自己選的一條按工具列「移除」：照舊直接移除那一條、不問（和 0.9.8 一樣）")
    app.undo_action(); app.update()
    # 平移／放大模式點握把區：選取 panel；Delete／⌫ 照狀態列說的刪除整個 panel（照「清空前確認」）；四種模式都能拖握把換順序，狀態列照實寫（U3）
    for mode, name, key in (("pan", "平移模式", "Delete"), ("zoom", "放大模式", "BackSpace")):
        _set_mode(mode)
        _handle_press(p3)
        st_ = app.status_var.get()
        check(app._sel_panel == p3 and _sel_uids() == _panel_uids(p3) and "Delete" in st_ and "拖曳換順序" in st_,
              f"{name}點握把區：選取 P3、清單跟著選，狀態列寫「拖曳換順序」（U3：四種模式都能拖；{st_}）")
        n0 = len(app.signals)
        calls = _with_ask(True, lambda: tk_key(w, key))
        check(p3 not in app.panel_order() and len(app.signals) == n0 - 1 and any(f"P{p3}" in str(c[1]) for c in calls),
              f"{name}握把選取 P3 後按 {key}（焦點在圖上）：先問再刪除整個 panel（{n0} → {len(app.signals)}，{calls}）")
        if len(app.signals) < n0:
            app.undo_action(); app.update()
        tk_key(w, "Escape"); app.update()
    _set_mode("pan")
    _handle_press(p3)
    order0 = app.panel_order()
    _handle_press(p3, drag_to=_ax(p1).bbox.y1 - 5)
    check(app.panel_order()[0] == p3 and app._strip_drag is None, f"平移模式在握把區拖曳（U3）：換順序（{order0} → {app.panel_order()}）")
    if app.panel_order() != order0:
        app.undo_action(); app.update()
    tk_key(w, "Escape"); _set_mode(""); app.update()
    _s37_round2(s1, q1, s2, q2, clk)
    _s37_round3(s1, q1, s2, q2, clk)
    _s37_round4(s1, q1, s2, q2, clk)
    app.v["confirm_clear"].set(False)
    # ================================ 第 11 項：每個 panel 都有 x 軸 ================================
    app.show_all_x(); app.update()
    a1, a2, a3 = _ax(p1), _ax(p2), _ax(p3)
    check(all(app.panel_is_linked(p) for p in (p1, p2, p3)) and a1.get_shared_x_axes().joined(a1, a2)
          and all(_xlabels_on(a) and a.get_xlabel() == "x [symbol]" for a in (a1, a2, a3)),
          "第 11 項：全部連結、單位一樣，每一張也都有 x 刻度字與 x 軸標籤")
    gaps, bot = _xlabel_gaps()
    check(gaps and all(g >= 2 for g in gaps) and bot >= 0,
          f"x 刻度字＋標籤不壓到下一張的座標區、圖例，最下面的沒被切掉（距離 {[round(float(g), 1) for g in gaps]} px、下緣 {float(bot):.1f}）")
    dpr = float(getattr(app.canvas, "device_pixel_ratio", 1.0) or 1.0)
    dpi = float(app.fig.get_dpi()) / dpr
    ph = max(0.5, min(10.0, sv.parse_number(app.v["panel_height"].get()) or 1.5))
    hs = [a.bbox.height / dpr for a in (a1, a2, a3)]
    h98 = (3 * ph + 0.2) / (3 + 2 * 0.3) * dpi            # 0.9.8：畫布 3×ph＋0.9 in、上 0.2、下 0.5、hspace 0.3 時一張圖的高度
    check(app.v["fit_panels"].get() or all(h >= 0.99 * h98 for h in hs),
          f"多了 x 標籤，圖本身沒有被壓扁（和 0.9.8 一樣高 {h98:.0f} px，畫布加高；每張 {[round(h) for h in hs]} px，每張圖高度 {ph} in）")
    # 最右邊的刻度剛好在右緣（x 從 0 到 3000）：刻度字不被圖的邊切掉（字級大也一樣）
    font0 = app.v["plot_font_pt"].get()
    app._set_current_panel(p2, announce=False)
    for pt in ("10", "16"):
        app.v["plot_font_pt"].set(pt)
        app.xfrom_var.set("0"); app.xto_var.set("3000"); app.apply_xrange(); app.update()
        app.canvas.draw()
        r_ = app.canvas.get_renderer()
        x1s = [t.label1.get_window_extent(r_).x1 for a in app.render_info["axes"] for t in a.xaxis._update_ticks() if t.label1.get_visible()]
        lim = max(tuple(a.get_xlim())[1] for a in app.render_info["axes"])
        check(x1s and max(x1s) <= app.fig.bbox.width + 0.5,
              f"圖字級 {pt} pt、x 到 {lim:g}（刻度在右緣）：最右邊的刻度字在圖裡（右緣 {max(x1s) if x1s else None:.1f} ≤ {app.fig.bbox.width:.0f} px）")
    app.v["plot_font_pt"].set(font0); app.show_all_x(); app.update()
    # 存成圖檔換了大小（8×4 in）：畫圖時照新的大小重排，每張的標籤一樣不壓到下一張、最下面不被切掉；存完畫面的版面不變
    pos0 = [tuple(a.get_position().bounds) for a in app.render_info["axes"]]
    size0 = tuple(app.fig.get_size_inches())
    app.fig.set_size_inches(8, 4, forward=False)
    gaps_e, bot_e = _xlabel_gaps()
    app.fig.set_size_inches(*size0, forward=False)
    app.canvas.draw()
    check(all(g >= 1 for g in gaps_e) and bot_e >= 0,
          f"畫成 8×4 in（存成圖檔的寬高）：標籤不壓到下一張、最下面不被切掉（{[round(float(g), 1) for g in gaps_e]} px、下緣 {float(bot_e):.1f}）")
    out_png = os.path.join(OUT, "s37_export_8x4.png")
    pk.export.export_figure(app.fig, out_png, dpi=100, size_in=(8, 4))
    app.canvas.draw()
    pos1 = [tuple(a.get_position().bounds) for a in app.render_info["axes"]]
    check(os.path.isfile(out_png) and all(all(abs(u - v) < 1e-9 for u, v in zip(a, b)) for a, b in zip(pos0, pos1)),
          "存成 8×4 in 的圖檔之後，畫面上的版面照舊（引擎照畫布大小排回來）")
    _s37_round2_layout(s1, q1, s2, q2, clk)
    _s37_round3_layout(s1, q1, s2, q2, clk)
    _s37_round4_layout(s1, q1, s2, q2, clk)
    fit0 = app.v["fit_panels"].get()
    app.v["fit_panels"].set(not fit0); app.plot(keep=True); app.update()
    gaps, bot = _xlabel_gaps()
    check(all(g >= 2 for g in gaps) and bot >= 0, f"「全部放進視窗」{'關' if fit0 else '開'}：一樣不重疊（{[round(float(g), 1) for g in gaps]} px）")
    app.v["fit_panels"].set(fit0)
    app.v["plot_font_pt"].set("16"); app.plot(keep=True); app.update()
    gaps, bot = _xlabel_gaps()
    check(all(g >= 2 for g in gaps) and bot >= 0, f"圖字級 16 pt：空隙跟著加大，不重疊、最下面不被切掉（{[round(float(g), 1) for g in gaps]} px、下緣 {float(bot):.1f}）")
    # 「全部放進視窗」、小視窗、16 pt：每張圖至少 0.5 in、放得下自己的圖例（圖例不蓋到自己的 x 刻度字），塞不下才捲動
    geo0 = app.geometry()
    _apply_geometry("1600x560")                            # 視窗有最小高度：實際是 640 px 高
    app.v["fit_panels"].set(True); app.plot(keep=True); app.update()

    def _legends_inside():
        app.canvas.draw()
        r_ = app.canvas.get_renderer()
        ok_leg, info_ = True, []
        for p_, a_ in zip(app.render_info["panels"], app.render_info["axes"]):
            top_ = app.render_info["axes_right"].get(p_) or a_
            lg = top_.get_legend()
            lb_ = lg.get_window_extent(r_) if lg is not None else None
            info_.append((round(a_.bbox.height / dpr), round(lb_.y0 - a_.bbox.y0, 1) if lb_ is not None else None))
            ok_leg = ok_leg and a_.bbox.height / dpr >= 0.5 * dpi - 1 and (lb_ is None or lb_.y0 >= a_.bbox.y0 - 0.5)
        return ok_leg, info_
    ok_leg, info_ = _legends_inside()
    check(ok_leg, f"「全部放進視窗」＋小視窗＋16 pt：每張圖至少 0.5 in、圖例在座標區裡（不蓋自己的 x 刻度字）（高, 圖例下緣離座標區下緣 {info_}）")
    ph0 = app.v["panel_height"].get()
    app.v["fit_panels"].set(False); app.v["panel_height"].set("0.5"); app.plot(keep=True); app.update()
    ok_leg, info_ = _legends_inside()
    check(ok_leg, f"每張圖高度 0.5 in＋16 pt（沒有全部放進視窗）：圖加高到放得下圖例，圖例不蓋自己的 x 刻度字（{info_}）")
    app.v["panel_height"].set(ph0); app.v["fit_panels"].set(True)
    app.v["plot_font_pt"].set(font0)
    app.panel_collapsed.update({p2, p3}); app.plot(keep=True); app.update()
    a1, a2, a3 = _ax(p1), _ax(p2), _ax(p3)
    gap12, gap23 = a1.bbox.y0 - a2.bbox.y1, a2.bbox.y0 - a3.bbox.y1
    base23 = 0.3 * (a1.bbox.height + a2.bbox.height + a3.bbox.height) / 3
