                ew.focus_set(); tw.update()
                app._sig_clip = list(sentinel)
                app.clipboard_clear(); app.clipboard_append("（舊的）")
                _zy_text_key(ew, "cmd_a", lay)
                sel = _zy_sel_text(ew)
                _zy_text_key(ew, "cmd_c", lay)
                c1 = app.clipboard_get()
