                after_cut = ew.get("1.0", "end-1c") if istext else ew.get()
                c2 = app.clipboard_get()
                _zy_text_key(ew, "cmd_v", lay)
                after_paste = ew.get("1.0", "end-1c") if istext else ew.get()
