            plain_ok = all(real_ok(v_, c_) for v_, c_ in ((0x1E, "]"), (0x21, "["), (0x1B, "-")))
            cmd_ok = all(real_ok(v_, c_) for v_, c_ in ((0x08, "c"), (0x00, "a"), (0x09, "v"), (0x06, "z")))
            app.sig_tree.selection_set([f"s{clk.uid}"]); app._on_list_select()
