                    check(abs(r - 1.1) < 0.02, f"真的 -（keysym {k3[0] if k3 else None}、字 {k3[3] if k3 else None!r}）：縮小一次（×{r:.3f}）")
                    app.v["diff"].set(True); app.sig_tree.selection_set([]); app._on_list_select(); app.plot(keep=True); app.show_all_x(); app.update()
                    k4 = rk.press_key(0x1E, rk.SHIFT)
