        w.v_cm_type_label.set("ACPR"); w._on_cm_type(); app.update()
        r["佔用頻寬 %（ACPR）"] = (_r8_grey(w.sp_cm_pct), "通道量測的佔用頻寬 (%)：" + M["percent"] + "（類型切到「佔用頻寬」才改得到）" in nt())
        _r8_type(w.sp_cm_npairs, "0")
        w.v_cm_type_label.set("佔用頻寬"); w._on_cm_type(); app.update()
        r["對組數（佔用頻寬）"] = (_r8_grey(w.sp_cm_npairs), "通道量測的對組數：" + M["npairs"] + "（類型切到「ACPR」才改得到）" in nt(),
                            _r8_red(w.sp_cm_pct), M["percent"] in nt())
        w.v_cm_type_label.set("ACPR"); w._on_cm_type(); app.update()
