# ============================================================================================================================
# 0.9.11 A 級修正（2026-10-28 使用者排的四項：audit/2026-10-26-branch-pause/decisions/todo_0911.md 的 2、8、6、7）：
# AM/PM/FM 視窗拖線不蓋掉既有 panel 的設定、焦點在「已繪訊號」清單時 ⇧=／−、圖例位置存進設定檔與自動存檔、
# 對前處理結果再套用／擷取之後狀態列留著成功訊息。每一部分都照使用者的操作路徑做（真的 Tk 事件：拖線、按鍵、按鈕、選單），再看結果。
# 四個步驟（s48_0911_a1…a4；DSV_TEST_ONLY=s48 一起跑）共用 _a0911_step：記住現在的訊號與設定，跑完整個還原。
# ============================================================================================================================
def _a0911_step(part):
    """跑一個 0.9.11 A 級的部分：先記住現在的訊號與設定（s9 要用這時候的），跑完關掉開過的視窗、整個還原。"""
    w = app.canvas.get_tk_widget()
    cfg0 = app.dump_settings()
    conf0, auto0 = app.v["confirm_clear"].get(), app.v["autosave"].get()
    app.v["confirm_clear"].set(False)
    try:
        if HL:
            check(True, f"（無桌面：{part.__name__} 的 Tk 事件檢查略過）")
            return
        try:
            part(w)
        except Exception:
            traceback.print_exc()
            check(False, f"{part.__name__} 例外")
    finally:
        app.v["confirm_clear"].set(conf0); app.v["autosave"].set(auto0)
        pw = getattr(app, "_pp_win", None)
        if pw is not None and pw.winfo_exists():
            pw.destroy()
        for x in list(app.winfo_children()):
            if isinstance(x, sv.IqWindow):
                x.destroy()
        app._sig_clip = []
        app.panel_collapsed.clear(); app.legend_loc.clear()
        _set_mode("pan")
        _s35_mode_off()
        app.clear_all(); app.update()
        app.apply_settings(cfg0, quiet=True); app.update()


def _a0911_props(p):
    """panel p 的連結時間／x 單位／Symbol rate／y 單位（第 8 項「每個 panel 各自設定」的四個值）。"""
    pp = app.panel_props.get(p) or {}
    return tuple(pp.get(k) for k in ("link", "xunit", "symbol_rate", "yunit"))


def _a0911_set_props(p, link, xunit, rate, yunit):
    app.set_panel_prop("link", link, panel=p); app.set_panel_prop("xunit", xunit, panel=p)
    app.set_panel_prop("symbol_rate", rate, panel=p); app.set_panel_prop("yunit", yunit, panel=p); app.update()


def _a0911_root_of(p):
    """主圖 panel p 座標區中央的螢幕座標（拖線的落點）。"""
    ax = _ax(p); mw = app.canvas.get_tk_widget()      # TkAgg：Tk 畫布像素＝matplotlib 像素（W10）
    return (mw.winfo_rootx() + int((ax.bbox.x0 + ax.bbox.x1) / 2),
            mw.winfo_rooty() + int(float(app.fig.bbox.height) - (ax.bbox.y0 + ax.bbox.y1) / 2))


def _a0911_root_new():
    """最後一張圖下面「新增 panel」區裡一點的螢幕座標。"""
    mw = app.canvas.get_tk_widget(); axes = app.render_info["axes"]      # TkAgg：Tk 畫布像素＝matplotlib 像素（W10）
    return (mw.winfo_rootx() + int((axes[0].bbox.x0 + axes[0].bbox.x1) / 2),
            mw.winfo_rooty() + int(float(app.fig.bbox.height) - app._drop_new_y(axes)) + 6)


def _a0911_iq_drag_keeps_settings(w):
    """A1：AM/PM/FM 視窗的線拖到不是目前 panel 的那張、拖到最下面新增 panel、拖到目前 panel——既有三張的連結時間／x 單位／Symbol rate／
    y 單位都不變（第 8 項）；新 panel 照「從清單／Finder 拖到最下面新增 panel」同一條規則（_panel_template：連結時間勾著、x 單位與
    Symbol rate 沿用拖之前的目前 panel、y 單位空白）。目前 panel 先用 P2（不是最上面那張；以前拖到別張蓋掉那張、拖到最下面蓋掉最上面
    那張——新編號還沒畫出來 current_panel() 退回 P1），再用 P1。"""
    for cur_is_top in (False, True):
        s1, q1, s2, q2, clk = _s36_setup()
        p1, p2, p3 = s1.panel, s2.panel, clk.panel
        _a0911_set_props(p1, True, "symbol", "1M", "V"); _a0911_set_props(p2, False, "us", "2M", "mV"); _a0911_set_props(p3, True, "ms", "3M", "dB")
        pc = p1 if cur_is_top else p2                    # 目前 panel：點它的空白（它的 I/Q 就是 AM/PM/FM 視窗分析的那組）
        other = p3
        _set_mode("pan")
        _i13_click(*_i13_empty(pc))
        w_iq = app.open_iq_window("ampm"); app.update()
        ok_win = w_iq is not None and {x.uid for x in w_iq.signals} == ({s1.uid, q1.uid} if cur_is_top else {s2.uid, q2.uid})
        check(ok_win and app.current_panel() == pc, f"A1 準備：點 P{pc} 的空白→目前 panel P{pc}，AM/PM/FM 視窗分析的是它的 I/Q（{app.current_panel()}）")
        for target in ("other", "new", "current"):
            _i13_click(*_i13_empty(pc)); app.update()
            n0 = len(app.signals)
            before = {p: _a0911_props(p) for p in (p1, p2, p3)}
            fields = (app.v["xunit"].get() or "symbol", str(app.v["symbol_rate"].get()).strip())
            tgt = _a0911_root_of(other) if target == "other" else _a0911_root_of(pc) if target == "current" else _a0911_root_new()
            want_dt = ("new", max(p1, p2, p3) + 1) if target == "new" else ("panel", other if target == "other" else pc)
            dt = app.drop_target(*tgt)
            grabbed = _pm_iq_drag(w_iq, 1, tgt)
            after = {p: _a0911_props(p) for p in (p1, p2, p3)}
            newp = app.signals[-1].panel if len(app.signals) == n0 + 1 else None
            where = (f"別張 P{other}" if target == "other" else f"最下面新增 P{want_dt[1]}" if target == "new" else f"目前 P{pc}")
            check(grabbed and dt == want_dt and newp == want_dt[1] and app.current_panel() == want_dt[1],
                  f"A1 目前 P{pc}：在視窗的線上按住、拖出視窗、放到{where}（落點 {dt}）→ 貼成衍生訊號到 P{newp}、目前 panel 換成它（抓到線 {grabbed}）")
            check(after == before,
                  f"A1 目前 P{pc}：拖線到{where}之後既有三張的連結時間／x 單位／Symbol rate／y 單位都不變（第 8 項；{after}）")
            if target == "new":
                tmpl = _a0911_props(want_dt[1])
                check(tmpl == (True, fields[0], fields[1], ""),
                      f"A1 新增的 P{want_dt[1]}：照拖到最下面新增 panel 的規則——連結時間勾著、x 單位與 Symbol rate 沿用拖之前的目前 P{pc}（{fields}）、y 單位空白（{tmpl}）")
            app.undo_action(); app.update()
            check(len(app.signals) == n0 and {p: _a0911_props(p) for p in (p1, p2, p3)} == before,
                  f"A1 目前 P{pc}：⌘Z 拿掉拖進來的那條，三張的設定照舊（{where}）")
        w_iq.destroy(); app.update()


@step
def s48_0911_a1_iq_drag():
    """0.9.11 A1：AM/PM/FM 視窗的線拖到別張、最下面新增 panel、目前 panel，既有 panel 的連結時間／x 單位／Symbol rate／y 單位都不變（第 8 項），
    新 panel 照拖到最下面新增 panel 的規則（todo_0911 第 2 項；0.9.8 起會蓋掉）。"""
    _a0911_step(_a0911_iq_drag_keeps_settings)


_A0911_ZOOM_KEYS = (   # 名稱 → (keysym, 字, 修飾鍵, keycode＝虛擬鍵碼 << 24 | Shift << 22 | 字)；注音的 keysym 是 ??、只有 keycode 認得出是哪顆鍵
    ("ABC ⇧=", "plus", "+", "Shift", 0x1840002B, "in"), ("ABC =", "equal", "=", "", 0x1800003D, "in"), ("ABC −", "minus", "-", "", 0x1B00002D, "out"),
    ("注音 ⇧=", "??", "+", "Shift", 0x1840002B, "in"), ("注音 =", "??", "=", "", 0x1800003D, "in"), ("注音 −", "??", "ㄦ", "", 0x1B003126, "out"),
)


def _a0911_click_row(sig):
    """在「已繪訊號」清單 sig 那一列的「Signal」欄點一下（真的 Tk 事件；第一欄是 ☑ 顯示，點了會切換顯示）。"""
    tree = app.sig_tree
    tree.see(f"s{sig.uid}"); app.update()
    bb = tree.bbox(f"s{sig.uid}", column="label")
    if not bb:
        return False
    time.sleep(0.55)                                       # 和上一次點擊隔開，Tk 才不會當成雙擊（雙擊格子＝改值）
    tree.event_generate("<Button-1>", x=bb[0] + 5, y=bb[1] + bb[3] // 2, when="now")
    tree.event_generate("<ButtonRelease-1>", x=bb[0] + 5, y=bb[1] + bb[3] // 2, when="now")
    app.update()
    return f"s{sig.uid}" in tree.selection()


def _a0911_list_focus_zoom(w):
    """A2：點過「已繪訊號」清單的一列（真的 Tk 點擊，焦點在清單）之後按 ⇧=（Tk 給 Shift+Plus）、=、−：圖放大／縮小，ABC 與注音
    （keysym ??、只有 keycode 認得出是哪顆鍵）一樣；清單自己的鍵照舊：↓ 換選取、←／Home 不動圖。以前「圖」範圍的鍵在清單上一律略過，
    ⇧=／− 什麼都不做（0.9.9 就這樣；第七次選單 2、10-28 使用者決定 0.9.11 修）。真的 NSEvent（照使用者目前的輸入法）也送一次。"""
    s1, q1, s2, q2, clk = _s36_setup()
    _set_mode("pan")
    tree = app.sig_tree
    xl0 = (1000.0, 2000.0)
    clicked = _a0911_click_row(clk)
    check(clicked and app.focus_lastfor() is tree, f"A2 準備：點清單 CLK 那一列→選到它、焦點在清單（{app.focus_lastfor()}）")
    for name, ks, ch, mods, code, how in _A0911_ZOOM_KEYS:
        if os.name == "nt" and name.startswith("注音"):      # 不算一項檢查（不灌通過數）：同一顆鍵的 Windows 按鍵事件就是上面 ABC 那幾項
            print(f"NOTE （Windows 不適用：「{name}」是 macOS 注音輸入法的按鍵事件（keysym ??＋macOS Tk 的鍵碼）；Windows 的注音輸入法"
                  f"之下 Tk 收到什麼要切輸入法才量得到（規則不允許），列在「沒測到」）")
            continue
        app.plot(keep=True, xlim=xl0); app.update()
        a = app.current_xlim()
        tk_key(tree, ks, char=ch, mods=mods, keycode=code); app.update()
        b = app.current_xlim()
        r = (b[1] - b[0]) / (a[1] - a[0])
        want = 1 / 1.1 if how == "in" else 1.1
        check(abs(r - want) < 0.02 and f"s{clk.uid}" in tree.selection(),
              f"A2 焦點在清單：{name}（keysym {ks}、keycode {code:#x}）→ {'放大' if how == 'in' else '縮小'}一次（x 範圍 ×{r:.3f}）、選取不變")
    # 清單自己的鍵照舊：↓ 換選取（在清單自己選的）、←／Home 是清單的（圖不平移、不還原視圖）
    app.plot(keep=True, xlim=xl0); app.update()
    _a0911_click_row(s1)
    a = app.current_xlim()
    tk_key(tree, "Down", mods="", keycode=0x7D000000); app.update()
    sel_down = tree.selection()
    tk_key(tree, "Left", mods="", keycode=0x7B000000); app.update()
    tk_key(tree, "Home", mods="", keycode=0x73000000); app.update()
    check(sel_down == (f"s{q1.uid}",) and app.current_xlim() == a,
          f"A2 焦點在清單：↓ 換選到下一列（{sel_down}）、←／Home 不平移、不還原視圖（x 範圍 {app.current_xlim()}）")
    # 真的按鍵：NSEvent 照使用者目前的輸入法走 Tk 自己的按鍵路徑（注音之下就是使用者遇到的情形）
    rk = _RealKeys()
    if rk.o is None:
        check(True, "（不是安靜模式／沒有 objc：A2 真的按鍵略過）")
        return
    lay_id = rk._layout()
    _a0911_click_row(clk)
    app.plot(keep=True, xlim=xl0); app.update()
    with rk:
        f = app.focus_get()
        if not (rk.ok and f is tree):
            check(True, f"（A2 真的按鍵：這個行程裡拿不到清單的鍵盤焦點（{f}），略過）")
            return
        a = app.current_xlim()
        k1 = rk.press_key(0x18, rk.SHIFT)
        b = app.current_xlim()
        k2 = rk.press_key(0x1B, 0)
        c = app.current_xlim()
    r1, r2 = (b[1] - b[0]) / (a[1] - a[0]), (c[1] - c[0]) / (b[1] - b[0])
    check(abs(r1 - 1 / 1.1) < 0.02 and abs(r2 - 1.1) < 0.02,
          f"A2 真的 ⇧= 與 −（輸入法 {lay_id}；Tk 的 keysym {k1[0] if k1 else None}、{k2[0] if k2 else None}）：焦點在清單也放大、縮小一次（×{r1:.3f}、×{r2:.3f}）")


