def _a0911_legend_loc_saved(w):
    """A3：圖例拖到的位置（主圖畫布上按住圖例拖）與右鍵選的位置（圖例選單「圖例位置 ▸ 左下」）每張各自存進「匯出設定」的檔與自動存檔，
    匯入／自動還原時回來、圖例畫在那裡；「自動還原上次」關著只存偏好時不帶（第五次選單 1 的規則）；不合的值略過；0.9.10 的檔沒有這個鍵＝右上。"""
    s1, q1, s2, q2, clk = _s36_setup()
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    _s35_mode_off()
    app.legend_loc.clear(); app.plot(keep=True); app.update(); app.canvas.draw()
    top = app.render_info["axes_right"].get(p1) or _ax(p1)
    leg = top.get_legend(); rd = app.canvas.get_renderer()
    lb = leg.get_window_extent(rd); tb = leg.get_texts()[0].get_window_extent(rd)
    hx, hy = (lb.x0 + tb.x0) / 2, (tb.y0 + tb.y1) / 2
    _press_at(hx, hy, moves=[(hx - 60, hy - 40), (hx - 90, hy - 60)])
    app.canvas.draw()
    lb1 = (app.render_info["axes_right"].get(p1) or _ax(p1)).get_legend().get_window_extent(app.canvas.get_renderer())
    loc1 = app.legend_loc.get(p1)
    check(isinstance(loc1, tuple) and abs((lb1.x0 - lb.x0) + 90) < 3 and abs((lb1.y0 - lb.y0) + 60) < 3,
          f"A3 準備：在畫布上按住 P{p1} 的圖例拖 (-90, -60) → 圖例移動、記下位置 {loc1}")
    # P3 的圖例右鍵 → 圖例位置 ▸ 左下
    top3 = app.render_info["axes_right"].get(p3) or _ax(p3)
    tb3 = top3.get_legend().get_texts()[0].get_window_extent(app.canvas.get_renderer())
    menus.clear(); menu_objs.clear()
    _press_at((tb3.x0 + tb3.x1) / 2, (tb3.y0 + tb3.y1) / 2, button=3)
    sub_ok = False
    m = menu_objs[-1] if menu_objs else None
    if m is not None:
        for i in range(m.index("end") + 1):
            if m.type(i) == "cascade" and m.entrycget(i, "label") == "圖例位置":
                sub = app.nametowidget(m.entrycget(i, "menu"))
                sub_ok = invoke_menu(sub, "左下")
    app.update()
    check(sub_ok and app.legend_loc.get(p3) == "lower left" and p2 not in app.legend_loc,
          f"A3 準備：P{p3} 的圖例右鍵「圖例位置 ▸ 左下」→ lower left；P{p2} 沒動過（{app.legend_loc}）")
    cfg = app.dump_settings()
    want = {str(p1): [loc1[0], loc1[1]], str(p3): "lower left"}
    check(cfg.get("legend_loc") == want, f"A3：dump_settings 的 legend_loc 每張各自記（{cfg.get('legend_loc')}）")
    path = os.path.join(OUT, "a0911_legend.json")
    app.save_settings(path)
    with open(path, encoding="utf-8") as fh:
        saved = sv.json.load(fh)
    check(saved.get("legend_loc") == want and set(saved["panels"][str(p1)]) == set(cfg["panels"][str(p1)]),
          f"A3：「匯出設定」的檔裡有 legend_loc（{saved.get('legend_loc')}），panels[p] 的鍵不變")
    auto0 = app.v["autosave"].get()
    app.v["autosave"].set(True); app.save_autosave()
    with open(sv.AUTOSAVE_PATH, encoding="utf-8") as fh:
        on = sv.json.load(fh).get("legend_loc")
    app.v["autosave"].set(False); app.save_autosave()
    with open(sv.AUTOSAVE_PATH, encoding="utf-8") as fh:
        off = sv.json.load(fh)
    app.v["autosave"].set(auto0)
    check(on == want and off.get("legend_loc") == {} and off.get("collapsed_panels") == [] and off.get("signals") == [],
          f"A3：自動存檔——「自動還原上次」開著存圖例位置（{on}）、關著只存偏好時不帶（{off.get('legend_loc')}；和收合狀態、訊號一樣）")
    # 匯入：回到記憶體、圖例畫在拖到的位置
    app.legend_loc.clear(); app.clear_all(); app.update()
    ok_load = app.load_settings(path, quiet=True); app.update(); app.canvas.draw()
    s1b = app.find_signal("iq.csv;;adc i"); clkb = app.find_signal("digital/clk.txt")
    got = dict(app.legend_loc)
    lb2 = None
    if s1b is not None and s1b.panel in app.render_info["panels"]:
        lb2 = (app.render_info["axes_right"].get(s1b.panel) or _ax(s1b.panel)).get_legend().get_window_extent(app.canvas.get_renderer())
    check(ok_load and s1b is not None and clkb is not None and got.get(s1b.panel) == (loc1[0], loc1[1]) and got.get(clkb.panel) == "lower left"
          and lb2 is not None and abs(lb2.x0 - lb1.x0) < 3 and abs(lb2.y0 - lb1.y0) < 3,
          f"A3：匯入那個檔 → 圖例位置回來（{got}）、P{s1b.panel if s1b else '?'} 的圖例畫在拖到的位置（Δ=({(lb2.x0 - lb1.x0) if lb2 else None}, {(lb2.y0 - lb1.y0) if lb2 else None})）")
    # 不合的值略過、0.9.10 的檔（沒有這個鍵）＝右上，重畫不出錯
    bad = dict(cfg, legend_loc={str(p1): "nowhere", str(p2): [0.1, "x"], "q": "best", str(p3): [0.1, 0.2, 0.3], "99": [float("nan"), 0.5]})
    app.apply_settings(bad, quiet=True); app.update()
    bad_ok = app.legend_loc == {} and len(app.render_info.get("panels") or []) == 3
    old = {k: v for k, v in cfg.items() if k != "legend_loc"}
    app.apply_settings(old, quiet=True); app.update()
    check(bad_ok and app.legend_loc == {} and len(app.render_info.get("panels") or []) == 3,
          f"A3：不合的 legend_loc 值整項略過、0.9.10 以前的檔沒有這個鍵＝全部右上，照樣畫出三張（{app.legend_loc}）")


