def _a0911_pp_status_kept(w):
    """A4：對一條前處理結果再按「套用」、用「擷取訊號 ▾ → 在時間範圍內」擷取一條前處理結果之後，狀態列留著「…已新增 … 條衍生訊號…」
    「已擷取 … 條訊號…」（等 Tk 把排在後面的 <<TreeviewSelect>> 處理完再看；以前被那條結果的參數說明蓋掉）；對一般訊號套用、
    擷取一般訊號照 0.9.9；之後自己點那一條照樣列參數。"""
    s1, q1, s2, q2, clk = _s36_setup()
    _fx3_tree_select([clk])
    pw = app.open_preprocess("smooth"); app.update()

    def settle():
        """和真的事件迴圈一樣：先處理排在佇列裡的事件（selection_set 排的 <<TreeviewSelect>>），閒置時才跑 after_idle。"""
        for _ in range(3):
            app.update()
        return app.status_var.get()
    pw.btn_apply.invoke(); st1 = settle()
    pp1 = [s for s in app.signals if s.derive in sv.PP_KINDS]
    check(len(pp1) == 1 and st1.startswith("平滑：已新增 1 條衍生訊號"), f"A4 對一般訊號 CLK 按「套用」：狀態列「{st1[:40]}」（0.9.9 的行為）")
    _fx3_tree_select([pp1[0]]); st_sel = settle()
    check("參數：" in st_sel and st_sel.startswith(pp1[0].name), f"A4 準備：自己選那條前處理結果→狀態列列它的參數（「{st_sel[:40]}」）")
    pw.btn_apply.invoke(); st2 = settle()
    pp2 = [s for s in app.signals if s.derive in sv.PP_KINDS and s not in pp1]
    check(len(pp2) == 1 and st2.startswith("平滑：已新增 1 條衍生訊號") and "參數：" not in st2,
          f"A4 對前處理結果再按「套用」：等 <<TreeviewSelect>> 處理完，狀態列還是「{st2[:40]}」（以前被參數說明蓋掉）")
    _fx3_tree_select([pp2[0]]); settle()
    app._roi_button_menu(); app.update()
    ok_m = invoke_menu(menu_objs[-1], "在時間範圍內") if menu_objs else False
    st3 = settle()
    n_roi = [s for s in app.signals if s.roi]
    check(ok_m and len(n_roi) == 1 and st3.startswith("已擷取 1 條訊號") and "參數：" not in st3,
          f"A4 「擷取訊號 ▾ → 在時間範圍內」擷取一條前處理結果：狀態列還是「{st3[:40]}」（以前被參數說明蓋掉）")
    _fx3_tree_select([clk]); settle()
    app._roi_button_menu(); app.update()
    ok_m = invoke_menu(menu_objs[-1], "在時間範圍內") if menu_objs else False
    st4 = settle()
    check(ok_m and len([s for s in app.signals if s.roi]) == 2 and st4.startswith("已擷取 1 條訊號"),
          f"A4 擷取一般訊號 CLK：狀態列「{st4[:40]}」（0.9.9 的行為）")
    _fx3_tree_select([pp2[0]]); st5 = settle()
    check("參數：" in st5 and st5.startswith(pp2[0].name), f"A4 之後自己點那條前處理結果：照樣列參數（「{st5[:40]}」）")
    pw.destroy(); app.update()


