@step
def s38_batch4_eye():
    """第四批 T4：眼圖視窗（MATLAB Communications Toolbox eyediagram(x, n, period, offset)）。預期值全部來自 MATLAB R2025a 的參考資料
    （tests/matlab_ref/eye_diagram：eye_ref.json 26 個案例的線資料／範圍／標題、線條屬性與錯誤、eye_sweep.json 斜坡掃描裡的 247 筆、eye_ylim.json
    44 筆舊參考的 YLim），不拿受測的 dsv_eye 算預期值；再加上入口（分析分頁、清單與 panel 右鍵、快速鍵動作）、畫哪幾條（第 9 項的規則、MATLAB 最多兩欄）、
    欄位錯誤（MATLAB 的訊息、沿用上一次合格的值）、設定、樣式選單（取代 plotstring）、主題、關窗。"""
    cfg38 = app.dump_settings()
    mode0 = {"pan/zoom": "pan", "zoom rect": "zoom"}.get(app.plot_toolbar.mode, "")
    style0 = app.v["style"].get()
    try:
        if style0 not in ("matlab", "matlab-dark"):
            # 自己建前提（DSV_TEST_PART=2 只靠 sq～s8 跑時，s3i 留下的是 matplotlib 預設風格：換主題時眼圖的圖底不變、MATLAB 風格線寬那項不跑）：
            # 風格照主題（MATLAB 風格；完整跑時 s10 之後本來就是），最後照原樣還原
            app.v["style"].set(sv.T.plot_style_name()); app.plot(keep=True); app.update()
        _s38_eye_checks()
    finally:                                              # 中途出錯也還原：後面的 s9 要用 s38 開始前的訊號、設定與工具列模式
        app.sig_tree.selection_set([]); app._on_list_select()
        for w_ in [x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]:
            w_.destroy()
        app.clear_all(); app.update()
        app.apply_settings(cfg38, quiet=True); app.update()
        if app.v["style"].get() != style0:
            app.v["style"].set(style0); app.plot(keep=True); app.update()
        app.plot_toolbar.set_mode(mode0); app.update()


def _s38_eye_checks():
    import json
    from types import SimpleNamespace as NS
    _s35_mode_off()
    for w_ in [x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]:
        w_.destroy()
    app.clear_all(); app.update()
    app.eye_defaults.clear(); app.eye_defaults.update(sv.DEFAULT_EYE)
    R = json.load(open(os.path.join(EYE_REF, "eye_ref.json"), encoding="utf-8"))
    ERR = {e["name"]: e for e in R["errors"]}
    # ---------------------------------------------------------------- 入口：分析分頁按鈕、快速鍵動作、沒有訊號時
    ab = app._analyze_btns
    btn = ab.get("eye")
    secs = {str(sec.title): sec for sec in app.strip.tabs["analyze"].sections}
    in_sec = btn is not None and any(w_ is btn for w_ in _walk(app.strip.tabs["analyze"]))
    act = app.actions.get("analysis.eye")
    check(btn is not None and str(btn.cget("text")) == "眼圖…" and in_sec and list(secs) == ["分析視窗"] and bool(btn.bind("<Enter>"))
          and btn.instate(["disabled"]) and act is not None and act.label == "眼圖…" and act.group == "分析"
          and btn in app._action_widgets.get("analysis.eye", []) and app.keymap.bindings("analysis.eye") == (),
          "分析分頁「分析視窗」區有「眼圖…」（和 AM/PM/FM、星座圖、GFSK 同一區）、有 tooltip、沒有訊號時變灰；快速鍵動作 analysis.eye「眼圖…」"
          "（分類「分析」，沒有預設鍵，偏好設定 → 鍵盤可以設）")
    n_top = len([x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)])
    res0 = app.open_eye(); app.update()
    check(res0 is None and app.status_var.get().startswith("眼圖：沒有訊號")
          and len([x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]) == n_top,
          f"沒有訊號按「眼圖…」→ 不開視窗，狀態列說明（{app.status_var.get()[:30]}）")
    app.status_var.set("")
    btn.invoke(); app.update()                                # 變灰的 ttk 按鈕：invoke 不會跑 command
    st_btn0 = app.status_var.get()
    res_act = act.run(); app.update()                         # 快速鍵動作（偏好設定 → 鍵盤設了鍵之後走這裡）
    check(st_btn0 == "" and res_act is None and app.status_var.get().startswith("眼圖：沒有訊號。先在「資料夾」面板")
          and len([x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]) == n_top,
          f"沒有訊號：工具列「眼圖…」變灰按不下去；快速鍵動作 analysis.eye 一樣不開視窗、狀態列說明（{app.status_var.get()[:40]}）")
    # ---------------------------------------------------------------- MATLAB eye_ref.json：26 個案例的線資料、範圍、座標區數與標題
    bad_ref, n_axes, n_cases, skipped = [], 0, 0, []
    for c in R["cases"]:
        name = c["name"]
        if c["input_class"] != "double":                 # int16：DSV 的訊號一律是 double（已知差異在 dsv_eye.selftest 釘住）
            skipped.append(name)
            continue
        a, _mark = _eye_load_input(os.path.join(EYE_REF, c["input_file"]))
        nums = [float(x.split("(")[1].rstrip(")")) for x in c["args"] if "(" in x]
        n_, period_, off_ = int(nums[0]), (nums[1] if len(nums) > 1 else 1.0), (int(nums[2]) if len(nums) > 2 else 0)
        if c["input_is_complex"]:                         # complex_zero_imag 的檔案只存實部（虛部全 0）
            cols = {"x i": a[:, 0], "x q": a[:, 1] if a.shape[1] > 1 else np.zeros(len(a))}
        elif a.shape[1] == 2:
            cols = {"c1": a[:, 0], "c2": a[:, 1]}
        else:
            cols = {"x": a[:, 0]}
        app.clear_all(); app.update()
        sigs = _eye_add(name, cols)
        w = _eye_open(sigs)
        if w is None:
            bad_ref.append(f"{name}: 沒開視窗（{app.status_var.get()[:40]}）")
            continue
        _eye_set(w, n=n_, period=repr(period_), offset=off_, xrange=False)
        axes_ml = c["axes"] if isinstance(c["axes"], list) else [c["axes"]]
        lines = _eye_lines(w)
        n_cases += 1
        if len(w.fig.axes) != len(axes_ml) or len(lines) != len(axes_ml) or w.field_errors:
            bad_ref.append(f"{name}: {len(w.fig.axes)} 個座標區 vs MATLAB {len(axes_ml)}（欄位錯誤 {list(w.field_errors)}）")
            w.destroy(); continue
        for i, (ax, axm) in enumerate(zip(w.fig.axes, axes_ml)):
            n_axes += 1
            lm = axm["lines"] if isinstance(axm["lines"], dict) else axm["lines"][0]
            ln = lines[i]
            probs = []
            if not _eye_same(ln.get_xdata(), _eye_arr(lm["XData"])):
                probs.append("XData")
            if not _eye_same(ln.get_ydata(), _eye_arr(lm["YData"])):
                probs.append("YData")
            if tuple(ax.get_xlim()) != tuple(float(v) for v in axm["xlim"]):
                probs.append(f"XLim {ax.get_xlim()} vs {axm['xlim']}")
            if tuple(ax.get_ylim()) != tuple(float(v) for v in axm["ylim"]):
                probs.append(f"YLim {ax.get_ylim()} vs {axm['ylim']}")
            if (ax.get_title(), ax.get_xlabel(), ax.get_ylabel()) != (EYE_TITLE_ZH[axm["title"]], EYE_LABEL_ZH[axm["xlabel"]], EYE_LABEL_ZH[axm["ylabel"]]):
                probs.append(f"文字 {ax.get_title()}／{ax.get_xlabel()}／{ax.get_ylabel()}")
            if probs:
                bad_ref.append(f"{name}[{i}]: {'、'.join(probs)}")
        w.destroy(); app.update()
    check(not bad_ref and n_cases == 25 and n_axes == 30 and skipped == ["int16_input"],
          f"MATLAB eyediagram（eye_ref.json {n_cases} 個案例、{n_axes} 個座標區：n＝2～8、奇數 n、offset、period、L＜n、L＝n、列向量、複數／兩欄實數／虛部全 0、"
          f"int8 參數、plotstring 三例）經過介面（清單選取 → 眼圖… → 欄位 → 整段資料）畫出來：每個座標區的線 XData／YData 逐點完全相等（含 NaN 斷點）、"
          f"XLim／YLim 完全相等、座標區數與標題（眼圖／同相訊號的眼圖／正交訊號的眼圖）、x／y 標籤（時間／振幅）照 MATLAB；int16 輸入 DSV 一律是 double 不比"
          + (f"（不符 {len(bad_ref)}：{bad_ref[:3]}）" if bad_ref else ""))
    # ---------------------------------------------------------------- MATLAB eye_sweep.json：1479 筆斜坡（x＝1..L）經過「只用目前 x 範圍」
    t_sw = time.time()
    S_all = [s_ for s_ in json.load(open(os.path.join(EYE_REF, "eye_sweep.json"), encoding="utf-8")) if not s_.get("err")]
    # 介面一筆要重畫一次（約 0.1 秒）：挑每個 n 的每個 offset（L＝5n+3）、n＝7（奇數 n）的全部 L、n＝2／8／16 在 L＝2、n、n+1 的每個 offset；
    # 全部 1479 筆的線資料由 dsv_eye.selftest 對（--selftest）
    S = [s_ for s_ in S_all if s_["n"] == 7 or s_["L"] == 5 * s_["n"] + 3 or (s_["n"] in (2, 8, 16) and s_["L"] in (2, s_["n"], s_["n"] + 1))]
    Lmax = max(s_["L"] for s_ in S)
    app.clear_all(); app.update()
    ramp = _eye_add("ramp", {"ramp": np.arange(1.0, Lmax + 1.0)})[0]
    w = _eye_open([ramp])
    bad_sw, n_sw = [], 0
    if w is not None:
        w.v_xrange.set(True)
        for L in sorted({s_["L"] for s_ in S}):
            app.plot(keep=True, xlim=(-0.5, L - 0.5)); app.update()      # SPS 1：x＝樣本索引，主圖範圍剛好包住前 L 個樣本（1..L）
            for s_ in (e for e in S if e["L"] == L):
                _eye_set(w, n=s_["n"], period="1", offset=s_["offset"])
                ln = _eye_lines(w)[0] if w.lines else None
                n_sw += 1
                if (ln is None or w.field_errors or w.result.get("samples") != L or not _eye_same(ln.get_xdata(), _eye_arr(s_["XData"]))
                        or not _eye_same(ln.get_ydata(), _eye_arr(s_["YData"])) or tuple(ln.axes.get_xlim()) != tuple(float(v) for v in s_["XLim"])):
                    bad_sw.append(f"n={s_['n']} off={s_['offset']} L={L}")
        w.destroy(); app.update()
    check(w is not None and not bad_sw and n_sw == len(S) == 247 and len(S_all) == 1479,
          f"MATLAB 斜坡掃描（eye_sweep.json 1479 筆裡的 {n_sw} 筆：n ∈ 2～8、10、12、16 每個 offset 在 L＝5n+3，n＝7 的 L＝2～15 與 38，"
          f"n＝2／8／16 的 L＝2、n、n+1）經過介面：主圖範圍剛好包住前 L 個樣本、"
          f"勾「只用目前 x 範圍」→ 線的 XData／YData 逐點完全相等、XLim 相等（{time.time() - t_sw:.0f} s）" + (f"（不符 {len(bad_sw)}：{bad_sw[:4]}）" if bad_sw else ""))
    # ---------------------------------------------------------------- MATLAB eye_ylim.json：44 筆舊參考的 YLim（資料從 eye_inputs.txt 重建）
    Yl = json.load(open(os.path.join(EYE_REF, "eye_ylim.json"), encoding="utf-8"))
    old = {}
    with open(os.path.join(EYE_REF, "eye_inputs.txt"), encoding="utf-8") as f:
        lines_ = [ln for ln in f.read().splitlines() if ln.strip()]
    for i in range(0, len(lines_), 3):
        parts = lines_[i].lstrip("#").split()
        kv = dict(p_.split("=") for p_ in parts[1:])
        rows, ncol = (int(v) for v in kv["size"].split("x"))
        re_v = np.array(lines_[i + 1].split()[1:], dtype=float).reshape((rows, ncol), order="F")
        im_v = np.array(lines_[i + 2].split()[1:], dtype=float).reshape((rows, ncol), order="F")
        old[parts[0]] = (re_v, im_v, kv["complex"] == "1")
    bad_yl, n_yl = [], 0
    for e in Yl:
        re_v, im_v, cplx = old[e["name"]]
        if cplx:
            cols = {"x i": re_v.ravel(order="F"), "x q": im_v.ravel(order="F")}
        elif re_v.shape[0] > 1 and re_v.shape[1] == 2:
            cols = {"c1": re_v[:, 0], "c2": re_v[:, 1]}
        else:
            cols = {"x": re_v.ravel(order="F")}
        app.clear_all(); app.update()
        w = _eye_open(_eye_add("old_" + e["name"], cols))
        if w is None:
            bad_yl.append(f"{e['name']}: 沒開視窗")
            continue
        _eye_set(w, n=8, period="1", offset=0, xrange=False)
        want = e["predicted"] if e["name"] == "int_types_n_offset" else e["eyediagram"]   # 那一筆 MATLAB 顯示的 YLim 是 single，predicted 是同一條規則的 double
        got = [tuple(ax.get_ylim()) for ax in w.fig.axes]
        n_yl += 1
        if not got or any(g_ != tuple(float(v) for v in want) for g_ in got):
            bad_yl.append(f"{e['name']}: {got} vs {want}")
        w.destroy(); app.update()
    check(not bad_yl and n_yl == 44, f"MATLAB 舊參考 eye_ylim.json（{n_yl} 筆：BPSK／QPSK／DC／斜坡、虛部全 0、列向量、兩欄、長度不到 n）經過介面："
                                       f"每個座標區的 YLim＝MATLAB eyediagram 的 YLim（完全相等）" + (f"（不符：{bad_yl[:3]}）" if bad_yl else ""))
    # ---------------------------------------------------------------- 欄位錯誤：MATLAB 的識別碼與訊息（eye_ref.json errors）、沿用上一次合格的值
    app.clear_all(); app.update()
    a, _c = _eye_load_input(os.path.join(EYE_REF, "inputs", "real_defaults.txt"))
    sig1 = _eye_add("err", {"x": a[:, 0]})[0]
    w = _eye_open([sig1])
    _eye_set(w, n=8, period="1", offset=0, xrange=False)
    good = dict(w.result)
    yd0 = np.array(_eye_lines(w)[0].get_ydata())
    bad_err = []
    for case, key, txt in (("n_equal_1", "n", "1"), ("n_noninteger", "n", "8.5"), ("n_vector", "n", "[8 8]"), ("period_zero", "period", "0"),
                           ("period_negative", "period", "-1"), ("offset_eq_n", "offset", "8"), ("offset_negative", "offset", "-1"),
                           ("offset_frac", "offset", "1.5")):
        ref = ERR[case]
        _eye_set(w, **{key: txt})
        e_ = w.field_errors.get(key)
        fw = w._fields[key]
        zh = e_.zh if e_ is not None else ""
        if not (e_ is not None and e_.identifier == ref["id"] and e_.en == ref["msg"] and fw.instate(["invalid"]) and fw._pk_tip == zh
                and w.v_status.get() == f"{w._field_label(key)}：{zh}" and zh in w.v_msg.get() and "圖用的是 n = 8、週期 = 1、取樣偏移 = 0" in w.v_msg.get()
                and w.result.get("n") == good["n"] and _eye_same(_eye_lines(w)[0].get_ydata(), yd0) and str(fw.get()) == txt
                and app.eye_defaults["n"] in ("", "8") and app.eye_defaults["period"] == "1" and app.eye_defaults["offset"] == 0):
            bad_err.append(f"{case}: {e_.identifier if e_ else None} {w.v_status.get()[:40]}")
        _eye_set(w, n=8, period="1", offset=0)
        if w.field_errors or any(f_.instate(["invalid"]) for f_ in w._fields.values()):
            bad_err.append(f"{case}: 改回合格的值後還是錯誤狀態")
    check(not bad_err, "欄位錯誤照 MATLAB（eye_ref.json errors：n＝1／8.5／[8 8] → comm:eyediagram:InvalidN、period＝0／−1 → NonPositivePeriod、"
                       "offset＝n／−1／1.5 → InvalidOffset，識別碼與英文訊息和 MATLAB 一樣）：打的字留著、紅框、提示換成繁中訊息，狀態列「欄位：訊息」，"
                       "說明列寫圖用的是哪一組值；圖與設定檔維持上一次合格的值；改回合格的值後錯誤狀態清掉" + (f"（不符：{bad_err}）" if bad_err else ""))
    # 上一次合格的取樣偏移對新的 n 也不合格：n 也先用上一次的（MATLAB 整個呼叫出錯、圖不變），n 欄位不算錯
    _eye_set(w, n=8, offset=7)
    _eye_set(w, n=4)
    e_ = w.field_errors.get("offset")
    check(e_ is not None and e_.identifier == ERR["offset_eq_n"]["id"] and "n" not in w.field_errors and w.result.get("n") == 8
          and w.result.get("offset") == 7 and "圖用的是 n = 8、週期 = 1、取樣偏移 = 7" in w.v_msg.get(),
          f"n 改成 4 而取樣偏移是 7（對 n＝4 不合格，MATLAB InvalidOffset）：取樣偏移紅框、圖維持 n＝8／offset＝7（{w.v_msg.get()[:60]}）")
    _eye_set(w, n=8, offset=0)
    # 範圍內沒有樣本 → MATLAB comm:eyediagram:EmptyX；只有一個樣本 → DSV 自己的訊息
    app.plot(keep=True, xlim=(5000.0, 5010.0)); app.update()
    _eye_set(w, xrange=True)
    zh_empty = sv.dsv_eye.EyeDiagramError(ERR["empty_x"]["id"]).zh
    check(sv.dsv_eye.EyeDiagramError(ERR["empty_x"]["id"]).en == ERR["empty_x"]["msg"] and zh_empty in w.v_msg.get()
          and "分析範圍＝主圖目前的 x 範圍（x 5000..5010 symbol）" in w.v_msg.get() and not w.lines and w.v_status.get().startswith("眼圖沒有畫：")
          and any(zh_empty in t.get_text() for t in w.fig.texts),
          f"主圖範圍裡沒有樣本：說明列寫 MATLAB 的「{zh_empty}」（comm:eyediagram:EmptyX）和怎麼調整範圍，圖上說沒有畫（{w.v_msg.get()[:60]}）")
    app.plot(keep=True, xlim=(9.6, 10.4)); app.update()          # SPS 1：範圍裡只有樣本 10
    w.compute(); app.update()
    st1 = w.v_status.get()
    app.show_all_x(); app.update()
    w.compute(); app.update()
    check("至少要有 2 個樣本" in st1 and len(w.lines) == 1 and w.v_status.get().startswith("已畫 13 條軌跡（96 個樣本）"),
          f"範圍裡只有 1 個樣本 → DSV 的 SingleSample 訊息；主圖全部顯示後「重新計算」→ 眼圖回來（{st1[:40]}／{w.v_status.get()[:30]}）")
    w.destroy(); app.update()
    # ---------------------------------------------------------------- 畫哪幾條（第 9 項的規則＋MATLAB 最多兩欄）、標題、右鍵
    s1, q1, s2, q2, clk = _s36_setup()
    p1, p2, p3 = s1.panel, s2.panel, clk.panel
    app.sig_tree.selection_set([]); app._on_list_select()
    app.plot_toolbar.set_mode("pan"); app.update()              # 啟動預設的平移模式：點 panel 選定它（和 s36b 一樣）
    _click_empty(_ax(p2))
    w = app.open_eye(); app.update()
    check(w is not None and [x.uid for x in w.signals] == [s2.uid, q2.uid] and w.title() == f"眼圖 — P{p2}：I＝{s2.name}、Q＝{q2.name}"
          and app.status_var.get() == f"已開啟眼圖視窗：P{p2}，I＝{s2.name}、Q＝{q2.name}" and len(w.fig.axes) == 2
          and [ax.get_title() for ax in w.fig.axes] == ["同相訊號的眼圖", "正交訊號的眼圖"],
          f"沒有選取、目前 panel＝P2（I/Q）→ 同相、正交兩張，標題與狀態列寫 P2 與兩條名稱（{w.title() if w else None}）")
    if w is not None:
        w.destroy(); app.update()
    # 真的按工具列「眼圖…」（ttk invoke → command）與快速鍵動作 analysis.eye（驗證者 10-28 問題 1：以前都直接叫 app.open_eye，command 接錯也抓不到）
    tops0 = [x for x in app.winfo_children() if isinstance(x, sv.tk.Toplevel)]
    btn.invoke(); app.update()
    new_b = [x for x in app.winfo_children() if isinstance(x, sv.tk.Toplevel) and x not in tops0]
    tops1 = tops0 + new_b
    act.run(); app.update()
    new_a = [x for x in app.winfo_children() if isinstance(x, sv.tk.Toplevel) and x not in tops1]
    t_eye = f"眼圖 — P{p2}：I＝{s2.name}、Q＝{q2.name}"
    check([type(x).__name__ for x in new_b] == ["EyeWindow"] and new_b[0].title() == t_eye
          and [type(x).__name__ for x in new_a] == ["EyeWindow"] and new_a[0].title() == t_eye,
          f"真的按工具列「眼圖…」與快速鍵動作 analysis.eye：各開一個眼圖視窗（不是別的分析視窗）、畫目前 panel P{p2}"
          f"（{[type(x).__name__ for x in new_b + new_a]}、{[x.title() for x in new_b + new_a][:1]}）")
    for x in new_b + new_a:
        x.destroy()
    app.update()
    _click_empty(_ax(p3))
    w = app.open_eye(); app.update()
    check(w is not None and [x.uid for x in w.signals] == [clk.uid] and w.title() == f"眼圖 — P{p3}：{clk.name}" and len(w.fig.axes) == 1
          and w.fig.axes[0].get_title() == "眼圖" and app.status_var.get() == f"已開啟眼圖視窗：P{p3}，{clk.name}",
          f"目前 panel＝P3（只有 CLK）→ 一張「眼圖」，標題寫 P3 與名稱（{w.title() if w else None}）")
    if w is not None:
        w.destroy(); app.update()
    _s35_mode_off()
    app.sig_tree.selection_set([f"s{q1.uid}"]); app._on_list_select(); app.update()
    w = app.open_eye(); app.update()
    check(w is not None and [x.uid for x in w.signals] == [q1.uid] and w.title() == f"眼圖 — 清單選取（P{p1}）：{q1.name}",
          f"清單選了 1 條（目前 panel 是 P3）→ 畫那一條，標題寫「清單選取（P1）」（{w.title() if w else None}）")
    if w is not None:
        w.destroy(); app.update()
    app.sig_tree.selection_set([f"s{q2.uid}", f"s{s1.uid}"]); app._on_list_select(); app.update()
    w = app.open_eye(); app.update()
    check(w is not None and [x.uid for x in w.signals] == [s1.uid, q2.uid] and w.title() == f"眼圖 — 清單選取（P{p1}／P{p2}）：I＝{s1.name}、Q＝{q2.name}",
          f"清單選了不同 panel 的 2 條 → 當成 I/Q（名稱認得出 I 的在上）、標題寫兩個 panel（{w.title() if w else None}）")
    if w is not None:
        w.destroy(); app.update()
    app.sig_tree.selection_set([f"s{s1.uid}", f"s{q1.uid}", f"s{clk.uid}"]); app._on_list_select(); app.update()
    n_top = len([x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)])
    res3 = app.open_eye(); app.update()
    st3 = app.status_var.get()
    zh_cols = sv.dsv_eye.EyeDiagramError(ERR["three_columns"]["id"]).zh
    check(res3 is None and len([x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]) == n_top
          and sv.dsv_eye.EyeDiagramError(ERR["three_columns"]["id"]).en == ERR["three_columns"]["msg"]
          and st3.startswith("眼圖：清單選了 3 條訊號——" + zh_cols) and "在清單只選 1 條或 2 條" in st3,
          f"清單選了 3 條：MATLAB 的 x 最多兩欄（three_columns → comm:eyediagram:invalidSizeX）→ 不開視窗，狀態列寫這個錯誤和要怎麼選（{st3[:50]}）")
    app.sig_tree.selection_set([]); app._on_list_select()
    # panel 右鍵「眼圖（P1）…」（目前 panel 是 P3 也畫 P1）、清單右鍵寫出對象
    menus.clear(); menu_objs.clear()
    app._context_for_hit(NS(kind="empty", id=None, ax=_ax(p1)), NS(guiEvent=None, x=0, y=0))
    lab = menus[-1] if menus else []
    ok_m = invoke_menu(menu_objs[-1], f"眼圖（P{p1}）…") if menu_objs else False
    app.update()
    eyes = [x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]
    check(f"眼圖（P{p1}）…" in lab and ok_m and eyes and [x.uid for x in eyes[-1].signals] == [s1.uid, q1.uid],
          f"panel 右鍵有「眼圖（P1）…」（和 AM/PM/FM、星座圖、GFSK 同一區），按了畫 P1 的 I/Q（{[x for x in lab if 'P' in x][:5]}）")
    for x in eyes:
        x.destroy()
    app.update()
    app.sig_tree.selection_set([f"s{clk.uid}"]); app._on_list_select(); app.update()
    bbox = app.sig_tree.bbox(f"s{clk.uid}")
    menus.clear(); menu_objs.clear()
    app._on_list_context(NS(x=(bbox[0] + 5) if bbox else 5, y=(bbox[1] + 3) if bbox else 5, x_root=0, y_root=0))
    lab = menus[-1] if menus else []
    ok_l = invoke_menu(menu_objs[-1], "眼圖（選取的 1 條）…") if menu_objs else False
    app.update()
    eyes = [x for x in app.winfo_children() if isinstance(x, sv.EyeWindow)]
    check("眼圖（選取的 1 條）…" in lab and ok_l and eyes and [x.uid for x in eyes[-1].signals] == [clk.uid],
          f"清單右鍵「眼圖（選取的 1 條）…」→ 畫選取的那條（{[x for x in lab if x.startswith('眼圖')]}）")
    for x in eyes:
        x.destroy()
    app.update()
    # panel 裡 3 條：有 I/Q 配對就畫那一對（和 AM/PM/FM 同一套）；沒有配對 → 不開視窗、狀態列寫 MATLAB 的錯誤
    clk.panel = p1
    app.refresh_list(); app.plot(); app.update()
    app.sig_tree.selection_set([]); app._on_list_select()
    w = app.open_eye(panel=p1); app.update()
    check(w is not None and [x.uid for x in w.signals] == [s1.uid, q1.uid],
          f"P1 有 adc i、adc q、CLK 三條 → 畫 I/Q 那一對（{[x.name for x in w.signals] if w else None}）")
    if w is not None:
        w.destroy(); app.update()
    s2.panel = q2.panel = p1
    s2.label, q2.label = "b one", "b two"
    s1.panel = q1.panel = p2
    app.refresh_list(); app.plot(); app.update()
    res4 = app.open_eye(panel=p1); app.update()
    st4 = app.status_var.get()
    check(res4 is None and st4.startswith(f"眼圖：P{p1} 有 3 條訊號、找不到 I/Q 配對") and zh_cols in st4,
          f"panel 有 3 條、沒有 I/Q 配對 → 不開視窗，狀態列寫 MATLAB 的欄數錯誤（{st4[:50]}）")
    # ---------------------------------------------------------------- 自動 n（2 × SPS）、設定檔、箭頭
    s1, q1, s2, q2, clk = _s36_setup()
    app.sig_tree.selection_set([f"s{s1.uid}"]); app._on_list_select(); app.update()
    app.eye_defaults.clear(); app.eye_defaults.update(sv.DEFAULT_EYE)
    w = app.open_eye(); app.update()
    sps0 = s1.sps
    # A10 用語（使用者 10-24 決定：眼圖、每符號樣本數、取樣偏移、週期）從元件讀、整組釘死（驗證者 10-28 問題 2：以前中文沒有任何 assert，突變 M15 改名抓不到）
    top_labels = [str(x.cget("text")) for x in w._fields["n"].master.winfo_children() if isinstance(x, sv.ttk.Label)] if w else []
    check(w is not None and top_labels == ["每條軌跡的樣本數", "週期", "取樣偏移"] and w.title().startswith("眼圖 — "),
          f"A10 用語：眼圖欄位列的標籤正好是 每條軌跡的樣本數／週期／取樣偏移、視窗標題「眼圖 — …」（{top_labels}）")
    check(w is not None and w.v_n.get() == str(int(round(2 * sps0))) and w.result.get("n") == int(round(2 * sps0)) and w.v_period.get() == "1"
          and w.v_offset.get() == "0" and w.v_xrange.get() and app.eye_defaults["n"] == "",
          f"預設：n＝2 × SPS（{sps0:g} → {w.v_n.get() if w else None}，MATLAB 文件的 2*sps）、週期 1、取樣偏移 0（MATLAB 的預設）、只用目前 x 範圍、設定存成自動")
    s1.sps = sps0 / 2
    w.compute(); app.update()
    n_half = w.v_n.get()
    s1.sps = sps0
    w.compute(); app.update()
    check(n_half == str(int(round(sps0))) and w.v_n.get() == str(int(round(2 * sps0))) and app.eye_defaults["n"] == "",
          f"n 沒改過＝自動：SPS 改成一半按「重新計算」→ n 跟著變（{n_half}），改回來又跟著回來")
    sp = w.sp_offset
    _eye_set(w, n=40, period="2", offset=5)
    w.sp_offset.event_generate("<<Increment>>"); app.update()
    up = w.v_offset.get()
    w.v_offset.set("39"); w.compute(); app.update()
    sp.event_generate("<<Increment>>"); app.update()
    top_ = w.v_offset.get()
    w.v_offset.set("0"); w.compute(); app.update()
    sp.event_generate("<<Decrement>>"); app.update()
    bot = w.v_offset.get()
    w.v_offset.set("abc"); w.compute(); app.update()
    sp.event_generate("<<Increment>>"); app.update()
    from_bad = w.v_offset.get()
    check(up == "6" and top_ == "39" and bot == "0" and from_bad == "1" and float(sp.cget("to")) == 39 and not w.field_errors,
          f"取樣偏移的箭頭：一次 ±1、夾在 0 … n−1（5 ↑ {up}、39 ↑ {top_}、0 ↓ {bot}）；打錯時從上一次合格的值（0）加（{from_bad}）")
    _eye_set(w, n=40, period="2", offset=5)
    d_ok = dict(app.eye_defaults)
