    if w is not None:
        w.destroy(); app.update()
    _s35_mode_off()
    app.sig_tree.selection_set([]); app._on_list_select()
    # 永不退步：主圖線上右鍵「刪除這條訊號」、訊號屬性面板預設隱藏
    s1 = app.signals[0]
    menus.clear(); menu_objs.clear()
    app._context_for_hit(NS(kind="line", id=s1.uid, ax=_ax(s1.panel)), NS(guiEvent=None, x=0, y=0))
    lab = menus[-1] if menus else []
    check(f"刪除這條訊號（{s1.name}）" in lab and "props" in app.dock.hidden and f"錯誤率比對（P{s1.panel}）…" in lab,
          "錯誤率比對做完後：主圖線上右鍵仍有「刪除這條訊號」（也有「錯誤率比對（P1）…」）、訊號屬性面板仍是隱藏的（使用者多次提醒的行為）")


