# ---- s50：B3（這版寫的自動存檔備份）----
@step
def s50_0913_b3_version_backup():
    """B3（2026-10-28 使用者決定，0.9.13）：每次寫自動存檔成功後多寫一份一模一樣的「這版寫的」備份 .signal_viewer_last.backup.json（含 app_version；
    不符合 U15 的 .bad*.json）；開啟時自動存檔的 app_version 比備份舊（中間被舊版開過又關掉）→ 問一次「用備份還原／用現在的檔」（真的對話框、真的按鈕）；
    凍結檔清理把備份引用的也算有人用到，備份讀不了就不清。28d5f87（0.9.12）：沒有備份、不問、只有備份引用的凍結檔被清掉。"""
    import json as _json
    tr = sv.tr
    # ---- (1) 在這個行程裡：寫自動存檔 → 備份一模一樣；清理把備份引用的算有人用；備份讀不了不清；U15 的樣式不受影響
    fdir_fn, auto0 = sv.frozen_data_dir, sv.AUTOSAVE_PATH
    base = tempfile.mkdtemp(prefix="s50_", dir=OUT)
    fdir = os.path.join(base, "frozen")
    os.makedirs(fdir)
    auto = os.path.join(base, ".signal_viewer_last.json")
    bak = sv.autosave_version_backup_path(auto)
    sv.frozen_data_dir, sv.AUTOSAVE_PATH = (lambda: fdir), auto
    try:
        app.save_settings(auto)
        a, b = _s49_read(auto), _s49_read(bak)
        legacy = os.path.join(base, ".signal_viewer_last.backup.json")
        check(os.path.basename(bak) == f".signal_viewer_last.backup-{sv.APP_VERSION}.json" and a == b and a.get("app_version") == sv.APP_VERSION and "_err" not in b
              and not os.path.lexists(legacy) and sv.autosave_backup_paths(auto) == [] and sv.frozen_cleanup_blocker(auto) is None,
              f"B3：寫自動存檔之後旁邊多一份一模一樣的這版的備份 {os.path.basename(bak)}（app_version {b.get('app_version')}；0.9.14 起每版各一份，"
              f"0.9.13 的 .backup.json 不寫），不算 U15 的 .bad*.json")
        only_bak = "s50_onlybak_" + "1a" * 10 + ".npy"
        orphan = "s50_orphan_" + "2b" * 10 + ".npy"
        for n_ in (only_bak, orphan):
            np.save(os.path.join(fdir, n_), np.arange(4.0))
        bcfg = dict(b, signals=list(b["signals"]) + [{"key": "only in backup", "path": os.path.join(fdir, only_bak), "column": None, "sps": 1.0, "panel": 9, "uid": 99}])
        with open(bak, "w", encoding="utf-8") as f:
            _json.dump(bcfg, f, ensure_ascii=False)
        removed = app.cleanup_frozen()
        left = sorted(n_ for n_ in os.listdir(fdir) if n_.endswith(".npy"))
        check(removed == [orphan] and left == [only_bak], f"B3 凍結檔清理：只有備份引用的留著、沒人用到的照清（清掉 {removed}，剩 {left}）")
        np.save(os.path.join(fdir, orphan), np.arange(4.0))
        with open(bak, "w", encoding="utf-8") as f:
            f.write("{broken")
        removed2 = app.cleanup_frozen()
        left2 = sorted(n_ for n_ in os.listdir(fdir) if n_.endswith(".npy"))
        check(removed2 == [] and left2 == [only_bak, orphan], f"B3 凍結檔清理：備份讀不了 → 這次一個都不清（剩 {left2}）")
        os.remove(bak)
        removed3 = app.cleanup_frozen()
        check(sorted(removed3) == [only_bak, orphan], f"B3 凍結檔清理：沒有備份就照常（清掉 {sorted(removed3)}）")
        app.v["autosave"].set(False)
        try:
            app.save_autosave()
            b2 = _s49_read(bak)
            check(b2.get("app_version") == sv.APP_VERSION and b2.get("signals") == [] and _s49_read(auto) == b2,
                  "B3：「自動還原上次」關著時備份也跟著只有偏好（和自動存檔一模一樣）")
        finally:
            app.v["autosave"].set(True)
    finally:
        sv.frozen_data_dir, sv.AUTOSAVE_PATH = fdir_fn, auto0
    # ---- (2) 真的獨立行程：自動存檔 0.9.11 寫的、備份這版寫的（多一條指著凍結檔的獨立訊號）。備份用這版的版本號：比這版新的備份照 C6
    #      （2026-10-29 使用者決定）不改寫也不問——以前這裡用一個比這版新的版本號代表「這版寫的」
    def _home(tag, auto_ver, bak_ver, bak_text=None, no_backup=False):
        h = os.path.join(OUT, "s50", tag)
        shutil.rmtree(h, ignore_errors=True)
        fz = os.path.join(h, "frozen")
        os.makedirs(fz)
        csvp = os.path.join(h, "a.csv")
        _s49_csv(csvp)
        only_bak = "s50_bak_" + "3c" * 10 + ".npy"
        np.save(os.path.join(fz, only_bak), np.arange(5.0))
        old = _s49_cfg(csvp, app_version=auto_ver)
        old["signals"] = old["signals"][:2]                    # 舊版寫的：只有 I、Q（舊版不認得的前處理結果已經被丟掉）
        if auto_ver is None:
            old.pop("app_version", None)
        old["saved"] = "2026-10-28 20:00:00"
        a_p = os.path.join(h, ".signal_viewer_last.json")
        with open(a_p, "w", encoding="utf-8") as f:
            _json.dump(old, f, ensure_ascii=False, indent=2)
        b_p = sv.autosave_version_backup_path(a_p, version=bak_ver) if bak_ver else sv.autosave_version_backup_path(a_p)   # 0.9.14：那一版自己的檔
        if not no_backup:
            newer = _s49_cfg(csvp, fz_gone=os.path.join(fz, only_bak), app_version=bak_ver)
            newer["saved"] = "2026-10-28 19:00:00"
            with open(b_p, "w", encoding="utf-8") as f:
                f.write(bak_text if bak_text is not None else _json.dumps(newer, ensure_ascii=False, indent=2))
        return h, a_p, b_p, fz, only_bak
    title = "上次的自動存檔被舊版改寫過"
    # (a) 用現在的檔（R2-D2，使用者 2026-10-29 13:0x 決定：舊備份自動另存一份 .signal_viewer_last.bad*.json——U15 認得，那份還在的期間凍結檔一個都不清；
    #     問句不再叫使用者自己複製。以前（131bf6a）關閉時只有舊備份用到的凍結檔就被清掉，照問句建議先複製的備份匯入時那條是「檔案不在」）
    h, a_p, b_p, fz, only_bak = _home("use_current", "0.9.11", sv.APP_VERSION)
    b0 = open(b_p, "rb").read()
    rc, st, marks, err = _s49_run_child(h, answer="no")
    dlg = next((ln for ln in marks.splitlines() if ln.startswith("dialog ")), "")
    a_after, b_after = _s49_read(a_p), _s49_read(b_p)
    bads = [n_ for n_ in os.listdir(h) if n_.startswith(".signal_viewer_last.bad")]
    check(rc == 0 and dlg.startswith("dialog " + title + " | 用現在的檔 / 用備份還原 | ") and "0.9.11 版寫的（2026-10-28 20:00:00）" in dlg
          and f"{sv.APP_VERSION} 版寫的（2026-10-28 19:00:00）" in dlg and st.get("n") == 2 and st.get("frozen") == [only_bak] and "native " not in marks,
          f"B3（獨立行程）：自動存檔 0.9.11 寫的、備份這版寫的 → 開啟先問「{title}」（兩個按鈕、寫出各是哪一版、何時寫的）；按「用現在的檔」→ 還原 2 條，"
          f"啟動時的清理留著備份引用的凍結檔（{st.get('frozen')}；rc {rc}）{err}")
    check("不用自己複製" in dlg and ".signal_viewer_last.bad*.json" in dlg and "請先把備份檔複製到別的地方" not in dlg
          and len(bads) == 1 and open(os.path.join(h, bads[0]), "rb").read() == b0
          and st.get("notice") == "舊備份已另存一份" and bads[0] in (st.get("msg") or "") and "匯入設定" in (st.get("msg") or "")
          and st.get("status", "").startswith("用現在的檔：舊備份已另存在") and bads[0] in st.get("status", ""),
          f"R2-D2：問句說選「用現在的檔」會自動另存舊備份、不用自己複製；按了之後舊備份一個位元組都一樣地另存成 {bads}、提示「{st.get('notice')}」"
          f"與狀態列寫出路徑（{st.get('status', '')[:50]}）")
    check(a_after.get("app_version") == sv.APP_VERSION and len(a_after.get("signals", [])) == 2 and b_after.get("app_version") == sv.APP_VERSION
          and b_after.get("signals") == a_after.get("signals") and sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy")) == [only_bak]
          and len(_s49_read(os.path.join(h, bads[0])).get("signals", []) if bads else []) == 5,
          f"B3＋R2-D2（獨立行程）：關閉後自動存檔與備份都被這版重寫（{a_after.get('app_version')}，2 條、一模一樣）；舊備份另存的那份還在（5 條），"
          f"只有它用到的凍結檔照 U15 留著（{sorted(n_ for n_ in os.listdir(fz) if n_.endswith('.npy'))}）")
    rc_a2, st_a2, marks_a2, err_a2 = _s49_run_child(h, answer="no")
    check(rc_a2 == 0 and not any(ln.startswith("dialog ") for ln in marks_a2.splitlines()) and st_a2.get("n") == 2
          and sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy")) == [only_bak]
          and [n_ for n_ in os.listdir(h) if n_.startswith(".signal_viewer_last.bad")] == bads,
          f"R2-D2：再開一次（同一版、不問）→ 另存的舊備份還在，它用到的凍結檔照樣留著（rc {rc_a2}）{err_a2}")
    # (b) 用備份還原
    h, a_p, b_p, fz, only_bak = _home("use_backup", "0.9.11", sv.APP_VERSION)
    rc, st, marks, err = _s49_run_child(h, answer="yes")
    rows = st.get("rows") or []
    a_after, b_after = _s49_read(a_p), _s49_read(b_p)
    check(rc == 0 and any(ln.startswith("dialog " + title) for ln in marks.splitlines()) and st.get("n") == 5 and [r["n"] for r in rows] == [400, 400, 400, 400, 5]
          and st.get("props", {}).get("3") == "pp title" and st.get("status", "").startswith("已用這版留的備份還原上次的工作階段")
          and len(a_after.get("signals", [])) == 5 and a_after.get("app_version") == sv.APP_VERSION and b_after.get("signals") == a_after.get("signals")
          and sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy")) == [only_bak],
          f"B3（獨立行程）：按「用備份還原」→ 還原備份的 5 條（含前處理結果與凍結檔那條、panel 標題）、狀態列說明；關閉後自動存檔＝備份＝5 條，凍結檔留著（rc {rc}）{err}")
    # (c) 同一版、自動存檔比較新、沒有備份、備份讀不了：都不問；備份讀不了時清理一個都不清
    for tag, av, bv, kw, want_frozen in (("same", sv.APP_VERSION, sv.APP_VERSION, {}, None), ("newer", "9.9.9", sv.APP_VERSION, {}, None),
                                          ("nobackup", "0.9.11", None, {"no_backup": True}, []),
                                          ("corrupt", "0.9.11", sv.APP_VERSION, {"bak_text": "{broken"}, "keep")):
        h, a_p, b_p, fz, only_bak = _home(tag, av, bv, **kw)
        orphan = "s50_orph_" + "4d" * 10 + ".npy"
        np.save(os.path.join(fz, orphan), np.arange(3.0))
        rc, st, marks, err = _s49_run_child(h, answer="yes")
        asked = any(ln.startswith("dialog ") for ln in marks.splitlines())
        fr = st.get("frozen")
        ok_fr = (fr == sorted([only_bak, orphan])) if want_frozen == "keep" else True
        check(rc == 0 and not asked and st.get("n") == 2 and ok_fr and "native " not in marks,
              f"B3（獨立行程，{tag}）：不問、照常還原自動存檔的 2 條（rc {rc}；啟動時凍結檔 {fr}）{err}")
    # (d) 自動存檔沒有 app_version（很舊的版本寫的）＝比備份舊：要問
    h, a_p, b_p, fz, only_bak = _home("noversion", None, sv.APP_VERSION)
    rc, st, marks, err = _s49_run_child(h, answer="no")
    dlg = next((ln for ln in marks.splitlines() if ln.startswith("dialog ")), "")
    check(rc == 0 and dlg.startswith("dialog " + title) and "沒有版本號" in dlg and st.get("n") == 2,
          f"B3（獨立行程）：自動存檔沒有 app_version → 當成最舊、照樣問（{dlg[:90]}）{err}")
    _s50_fix1(_home, title)
    _s50_fix2(_home)
    _s50_c6(_home, title)
    _s50_fix3(_home, title)


def _s50_fix3(_home, title):
    """0.9.13 深度審查第三輪（2026-10-29，最後一輪），都是真的獨立行程：
    (i) R2-D3（使用者 13:0x 決定）：B3／U13 的問句開著時從 Finder 開的檔（::tk::mac::OpenDocument：雙擊、打開方式、拖到 Dock 圖示）、拖進視窗的檔
        （tkinterdnd2 的 <<Drop>>）先排著，還原（含問句）做完再照拖放的規則加進來；問句時選了關閉（C1：什麼都不存）就不加。
        131bf6a：當下就加進清單，回答之後的還原整個蓋掉，那個檔默默沒開（關閉後的自動存檔也沒有它）。
    (j) C6 × U13（第三輪 R3-1／R3-D1／R3C-2）：自動存檔讀不了、備份是比這版新的版本寫的 → 問句不說「這版上次一起寫的」「關閉時備份會被重寫、請先複製」，
        改說這版不會改寫它；兩種回答關閉後備份都一個位元組都不動。"""
    import json as _json
    t13 = "上次的自動存檔讀不回來"
    # (i) B3「用備份還原」＋問句開著時 Finder 開檔＋拖進視窗
    h, a_p, b_p, fz, only_bak = _home("r2d3_b3_yes", "0.9.11", sv.APP_VERSION)
    d1, d2 = os.path.join(h, "doc1.csv"), os.path.join(h, "doc2.csv")
    with open(d1, "w", encoding="utf-8") as f:
        f.write("d1 x,d1 y\n" + "\n".join(f"{k},{-k}" for k in range(80)) + "\n")
    with open(d2, "w", encoding="utf-8") as f:
        f.write("d2 z\n" + "\n".join(f"{k * 0.5}" for k in range(70)) + "\n")
    mac = sys.platform == "darwin"
    rc, st, marks, err = _s49_run_child(h, answer="yes", opendoc=d1 if mac else None, drop=d2)
    rows = st.get("rows") or []
    names = [r["name"] for r in rows]
    a_after = _s49_read(a_p)
    want_doc = (["d1 x", "d1 y"] if mac else []) + ["d2 z"]
    got_doc = [n_ for n_ in names if any(n_.endswith(w) for w in want_doc)]
    saved_keys = [x.get("key", "") for x in a_after.get("signals", [])]
    check(rc == 0 and any(ln.startswith("dialog " + title) for ln in marks.splitlines()) and "opened during question" in marks
          and st.get("n") == 5 + len(want_doc) and [r["n"] for r in rows[:5]] == [400, 400, 400, 400, 5] and len(got_doc) == len(want_doc)
          and all(r["n"] in (80, 70) for r in rows[5:]) and st.get("status", "").startswith("已用這版留的備份還原上次的工作階段")
          and f"拖放加入 {len(want_doc)} 條訊號到" in st.get("status", "") and all(any(k.endswith(w) for k in saved_keys) for w in want_doc)
          and len(saved_keys) == 5 + len(want_doc),
          f"R2-D3：B3 的問句開著時從 Finder 開檔＋拖檔案進視窗 → 先排著；選「用備份還原」後備份的 5 條還原好，再照拖放的規則加進 {len(want_doc)} 條"
          f"（{got_doc}）、狀態列兩句都在（{st.get('status', '')[:70]}…）、關閉後自動存檔記著它們（rc {rc}）{err}")
    # (i2) 問句開著時開檔、接著關閉（C1）→ 什麼都不存、開的檔也不加
    h, a_p, b_p, fz, only_bak = _home("r2d3_close", "0.9.11", sv.APP_VERSION)
    d3 = os.path.join(h, "doc3.csv")
    with open(d3, "w", encoding="utf-8") as f:
        f.write("d3 x\n" + "\n".join(str(k) for k in range(30)) + "\n")
    f0 = _s50_files(h)
    rc, st, marks, err = _s49_run_child(h, answer="close", opendoc=d3 if mac else None, drop=None if mac else d3)
    f1 = _s50_files(h)
    check(rc == 0 and "opened during question" in marks and not st and "\nexit" in "\n" + marks and f1 == f0 and "doc3" not in str(_s49_read(a_p)),
          f"R2-D3 × C1：問句開著時開檔、接著按關閉 → 什麼都不存（自動存檔、備份、凍結檔一個位元組都不動）、開的檔不加（rc {rc}）{err}")
    # (i3) U13＋這版的備份：問句開著時開檔 → 選「用備份還原」→ 備份的 5 條＋開的檔
    h, a_p, b_p, fz, only_bak = _home("r2d3_u13_yes", "0.9.11", sv.APP_VERSION)
    with open(a_p, "wb") as f:
        f.write(b'{"version": 6, "signals": [{"key": "a.csv;;b1 i", "path": ')
    d4 = os.path.join(h, "doc4.csv")
    with open(d4, "w", encoding="utf-8") as f:
        f.write("d4 x\n" + "\n".join(str(k) for k in range(40)) + "\n")
    rc, st, marks, err = _s49_run_child(h, answer="yes", opendoc=d4 if mac else None, drop=None if mac else d4)
    rows = st.get("rows") or []
    check(rc == 0 and any(ln.startswith("dialog " + t13) for ln in marks.splitlines()) and "opened during question" in marks and st.get("n") == 6
          and [r["n"] for r in rows] == [400, 400, 400, 400, 5, 40] and rows[-1]["name"].endswith("d4 x")
          and st.get("status", "").startswith("上次的自動存檔讀不回來（另存在") and "拖放加入 1 條訊號到" in st.get("status", ""),
          f"R2-D3：U13＋這版備份的問句開著時開檔 → 選「用備份還原」→ 備份的 5 條＋開的檔 1 條、狀態列兩句都在（rc {rc}；{[r['name'] for r in rows]}）{err}")
    # (j) C6 × U13：備份是比這版新的版本寫的
    newer = "9.9.9"
    for ans in ("no", "yes"):
        h, a_p, b_p, fz, only_bak = _home("c6u13_" + ans, newer, newer)
        with open(a_p, "wb") as f:
            f.write(b'{"version": 6, "signals": [')
        b0 = open(b_p, "rb").read()
        rc, st, marks, err = _s49_run_child(h, answer=ans)
        dlg = next((ln for ln in marks.splitlines() if ln.startswith("dialog ")), "")
        b1 = open(b_p, "rb").read()
        st_j = st.get("status", "")
        st_ok = (st_j.startswith("上次的自動存檔讀不回來（另存在") and f"；已用比這版新的 {newer} 版寫的備份還原（" in st_j and "這版不會改寫它" in st_j
                 and "已用這版留的備份還原" not in st_j) if ans == "yes" else st_j.startswith("上次的自動存檔讀不回來，選了從空的開始")
        check(rc == 0 and dlg.startswith("dialog " + t13) and f"{newer} 版留的備份（" in dlg and f"這版留的備份是 {newer} 版寫的" not in dlg
              and f"它是比這版新的 {newer} 版寫的" in dlg
              and "這版不會改寫它" in dlg and "這版上次寫自動存檔時一起寫的" not in dlg and "自動存檔和備份都會被這次的工作階段重寫" not in dlg
              and "請先把備份檔複製到別的地方" not in dlg and b1 == b0 and st.get("n") == (5 if ans == "yes" else 0) and st_ok,
              f"C6 × U13（{'用備份還原' if ans == 'yes' else '從空的開始'}）：備份是比這版新的 {newer} 寫的 → 問句說這版不會改寫它（不說「這版上次一起寫的」"
              f"「關閉時會重寫、請先複製」）；關閉後備份一個位元組都沒動（rc {rc}）{err}")
    # (k) R2-D2 另存失敗（在這個行程裡，backup_bad_autosave 換成會失敗的替身）：提示「舊備份另存失敗」、這次不重寫那份備份；之後再試成功了才另存＋照常重寫
    fdir_fn, auto0 = sv.frozen_data_dir, sv.AUTOSAVE_PATH
    base = tempfile.mkdtemp(prefix="s50k_", dir=OUT)
    fdir = os.path.join(base, "frozen")
    os.makedirs(fdir)
    auto = os.path.join(base, ".signal_viewer_last.json")
    bak = sv.autosave_version_backup_path(auto)
    real = sv.backup_bad_autosave
    sv.frozen_data_dir, sv.AUTOSAVE_PATH = (lambda: fdir), auto
    notice0 = (getattr(app, "_vbak_notice", None), getattr(app, "_vbak_notice_title", None), getattr(app, "_vbak_notice_status", None))
    try:
        with open(bak, "w", encoding="utf-8") as f:
            _json.dump({"version": 6, "app_version": sv.APP_VERSION, "saved": "2026-10-28 19:00:00", "root": "", "view": {"autosave": True},
                        "signals": [{"key": "only old", "path": "/nowhere/old.csv", "column": "c", "sps": 1.0, "panel": 1, "uid": 1}]}, f, ensure_ascii=False)
        b0 = open(bak, "rb").read()

        def _boom(*a, **k):
            raise OSError(28, "No space left on device")
        sv.backup_bad_autosave = _boom
        app._keep_old_version_backup(bak, sv.APP_VERSION, "2026-10-28 19:00:00")
        t1, s1, n1 = app._vbak_notice_title, app._vbak_notice_status, app._vbak_notice or ""
        d = app.dump_settings()
        app._write_version_backup(d)
        b1 = open(bak, "rb").read()
        sv.backup_bad_autosave = real
        app._write_version_backup(d)
        b2 = open(bak, "rb").read()
        bads = sv.autosave_backup_paths(auto) or []
        check(t1 == "舊備份另存失敗" and s1 == "用現在的檔：舊備份另存失敗，這次不重寫它（詳見對話框）" and "另存失敗" in n1 and bak in n1
              and b1 == b0 and len(bads) == 1 and open(bads[0], "rb").read() == b0 and b2 != b0
              and _json.loads(b2.decode("utf-8")).get("app_version") == sv.APP_VERSION and not app._vbak_keep_pending,
              f"R2-D2 另存失敗：提示「{t1}」、這次不重寫那份備份（一個位元組都沒動）；再試成功了才另存（{[os.path.basename(p_) for p_ in bads]}）、照常重寫備份")
    finally:
        sv.backup_bad_autosave = real
        sv.frozen_data_dir, sv.AUTOSAVE_PATH = fdir_fn, auto0
        app._vbak_keep_pending = False
        app._vbak_notice, app._vbak_notice_title, app._vbak_notice_status = notice0


def _s50_c6(_home, title):
    """C6（2026-10-29 使用者決定）：較舊的版本不改寫較新版本寫的備份；之後回到新版本時照 B3 發現自動存檔被舊版改寫過、問要不要用備份。真的獨立行程：
    比這版新的版本（9.9.9）寫的自動存檔（2 條）與備份（5 條，多一條只有它用到的凍結檔）→ 這版開、關：不問、自動存檔改成這版寫的、備份一個位元組都不動、
    凍結檔留著；這版再開：還是不問（這版就是舊版）；「新版本」（子行程把 APP_VERSION 換成 9.9.9）開：問「上次的自動存檔被舊版改寫過」→ 用備份還原 → 5 條回來。
    以前（b8d5f5c）：這版關閉時把備份改寫成自己的、新版本再開兩份同一版不問，新版本的工作階段默默不見。"""
    newer = "9.9.9"
    h, a_p, b_p, fz, only_bak = _home("c6_newer", newer, newer)
    b0 = open(b_p, "rb").read()
    rc1, st1, marks1, err1 = _s49_run_child(h, answer="yes")
    a1 = _s49_read(a_p)
    asked1 = any(ln.startswith("dialog ") for ln in marks1.splitlines())
    rc2, st2, marks2, err2 = _s49_run_child(h, answer="yes")
    asked2 = any(ln.startswith("dialog ") for ln in marks2.splitlines())
    b2 = open(b_p, "rb").read()
    frozen2 = sorted(n_ for n_ in os.listdir(fz) if n_.endswith(".npy"))
    check(rc1 == 0 and rc2 == 0 and not asked1 and not asked2 and st1.get("n") == 2 and st2.get("n") == 2
          and a1.get("app_version") == sv.APP_VERSION and b2 == b0 and frozen2 == [only_bak] and "native " not in marks1 + marks2,
          f"C6：備份是比這版新的 {newer} 寫的 → 這版開、關兩次都不問、照常還原自動存檔的 2 條；自動存檔改成這版寫的、備份一個位元組都沒動、"
          f"只有備份用到的凍結檔留著（{frozen2}；rc {rc1}/{rc2}；問了 {asked1}/{asked2}）{err1}{err2}")
    rc3, st3, marks3, err3 = _s49_run_child(h, answer="yes", app_version=newer)
    dlg3 = next((ln for ln in marks3.splitlines() if ln.startswith("dialog ")), "")
    rows3 = st3.get("rows") or []
    a3, b3 = _s49_read(a_p), _s49_read(b_p)
    check(rc3 == 0 and dlg3.startswith("dialog " + title) and f"現在的自動存檔是 {sv.APP_VERSION} 版寫的" in dlg3 and f"這版留的備份是 {newer} 版寫的" in dlg3
          and st3.get("n") == 5 and [r["n"] for r in rows3] == [400, 400, 400, 400, 5] and st3.get("status", "").startswith("已用這版留的備份還原上次的工作階段")
          and a3.get("app_version") == newer and len(a3.get("signals", [])) == 5 and b3.get("signals") == a3.get("signals"),
          f"C6：回到比這版新的版本（{newer}）時照 B3 問「{title}」、用備份還原 → 那個版本的 5 條（含凍結檔那條）都回來；關閉後兩份都是它寫的"
          f"（rc {rc3}；{dlg3[:80]}）{err3}")

def _s50_files(h):
    """自動存檔、這版的備份、frozen 裡每個 .npy 的位元組；加上 .bad 備份的檔名（C1：問句開著時關閉＝這些一個位元組都不動）。"""
    out = {}
    p_ = os.path.join(h, ".signal_viewer_last.json")
    out[".signal_viewer_last.json"] = open(p_, "rb").read() if os.path.exists(p_) else None
    for n_ in sorted(os.listdir(h)):                      # 每一份版本備份（0.9.14 起 .backup-<版本>.json；0.9.13 的 .backup.json）
        if n_.startswith(".signal_viewer_last.backup") and n_.endswith(".json"):
            out[n_] = open(os.path.join(h, n_), "rb").read()
    fz_ = os.path.join(h, "frozen")
    for n_ in sorted(os.listdir(fz_)):
        if n_.endswith(".npy"):
            out["frozen/" + n_] = open(os.path.join(fz_, n_), "rb").read()
    out["bad"] = sorted(n_ for n_ in os.listdir(h) if n_.startswith(".signal_viewer_last.bad"))
    return out


def _s50_fix1(_home, title):
    """0.9.13 深度審查第一輪的修正（2026-10-29），都是真的獨立行程：
    (e) C1（P1）：B3 的問句開著時關閉——主視窗的關閉鈕（on_close＝WM_DELETE_WINDOW）、⌘Q（::tk::mac::Quit）、結束訊號（SIGTERM）→ 什麼都不存：
        自動存檔、這版的備份、凍結檔一個位元組都不動（f4e660e：空的工作階段蓋掉自動存檔和備份、凍結檔全清）。
    (f) 自動存檔讀不了（U13）而這版留的備份讀得了（使用者 2026-10-29 決定）：另存 .bad 之後直接問「用備份還原／從空的開始」；選了之前備份不被改寫、
        問句開著時關閉也什麼都不存。
    (g) B3 × 兩份都只有偏好（使用者 2026-10-29 決定）：不問、用現在的檔；只有一份只有偏好照樣問。
    (h) 這版留的備份讀不了（第一輪行為驗證 P-2）：照 U13 另存 .bad、提示一次；關閉時備份照常重寫，但只有那份讀不了的備份用到的凍結檔不被清掉（U15）。"""
    import json as _json
    # (e)
    for how in ("close", "macquit", "sigterm"):
        if how == "macquit" and sys.platform != "darwin":
            check(True, "（不是 macOS：⌘Q 的 ::tk::mac::Quit 略過；主視窗的關閉鈕那一條就是 Windows 的 WM_CLOSE）")
            continue
        if how == "sigterm" and sys.platform.startswith("win"):
            check(True, "（Windows 沒有 SIGTERM，略過）")
            continue
        h, a_p, b_p, fz, only_bak = _home("c1_" + how, "0.9.11", sv.APP_VERSION)
        np.save(os.path.join(fz, "s50_c1orph_" + "5e" * 10 + ".npy"), np.arange(3.0))
        f0 = _s50_files(h)
        rc, st, marks, err = _s49_run_child(h, answer=how)
        f1 = _s50_files(h)
        dlg = next((ln for ln in marks.splitlines() if ln.startswith("dialog ")), "")
        check(rc == 0 and dlg.startswith("dialog " + title) and not st and "\nexit" in "\n" + marks and f1 == f0 and len(f0) == 5
              and f0[".signal_viewer_last.json"] and f0.get(os.path.basename(b_p)) and not err,
              f"C1：B3 的問句開著時關閉（{how}）→ 什麼都不存：自動存檔、備份、凍結檔（{len(f0) - 3} 個）一個位元組都不動、沒有 .bad（rc {rc}；"
              f"{'一樣' if f1 == f0 else '變了：' + str([k for k in f0 if f0.get(k) != f1.get(k)])}）{err}")
    # (f)
    t13 = "上次的自動存檔讀不回來"
    for ans in ("yes", "no", "close"):
        h, a_p, b_p, fz, only_bak = _home("u13_" + ans, "0.9.11", sv.APP_VERSION)
        broken = b'{"version": 6, "signals": [{"key": "a.csv;;b1 i", "path": '
        with open(a_p, "wb") as f:
            f.write(broken)
        f0 = _s50_files(h)
        rc, st, marks, err = _s49_run_child(h, answer=ans)
