# 0.9.13 D14：第四批（眼圖、錯誤率比對）沒測到的小路徑。
@step
def s53_0913_b4tests():
    """0.9.13 D14：眼圖／錯誤率欄位按 Enter 就重算、錯誤率「重新計算」真的強制重算（force）、線寬／標記大小「自訂…」對話框（安靜模式用替身）、
    顏色對話框取消不改、I/Q 的 SPS 不同時說明列提示、「眼圖／錯誤率比對：P{p} 沒有顯示中的訊號」、每個 panel 的 x 單位＝µs／Symbol rate 之下
    眼圖「只用目前 x 範圍」取的樣本與錯誤率的取樣（每個 symbol 中點）和 symbol 單位時一樣、上一個／下一個錯誤寫 µs。"""
    cfg53 = app.dump_settings()
    mode0 = {"pan/zoom": "pan", "zoom rect": "zoom"}.get(app.plot_toolbar.mode, "")
    unit0 = sv.SETTINGS.get("offset_unit")
    ask0, cc0 = sv.simpledialog.askfloat, sv.colorchooser.askcolor
    try:
        _s53_checks()
    finally:
        sv.simpledialog.askfloat, sv.colorchooser.askcolor = ask0, cc0
        sv.SETTINGS["offset_unit"] = unit0
        for w_ in [x for x in app.winfo_children() if isinstance(x, (sv.EyeWindow, sv.ErrRateWindow))]:
            w_.destroy()
        app.sig_tree.selection_set([]); app._on_list_select()
        app.clear_all(); app.update()
        app.apply_settings(cfg53, quiet=True); app.update()
        app.plot_toolbar.set_mode(mode0); app.update()


def _s53_checks():
    _s35_mode_off()
    for w_ in [x for x in app.winfo_children() if isinstance(x, (sv.EyeWindow, sv.ErrRateWindow))]:
        w_.destroy()
    app.clear_all(); app.update()
    sv.SETTINGS["offset_unit"] = "symbol"
    app.eye_defaults.clear(); app.eye_defaults.update(sv.DEFAULT_EYE)
    app.errrate_defaults.clear(); app.errrate_defaults.update(sv.DEFAULT_ERRRATE)
    rng = np.random.default_rng(53)
    # ---- (a) 眼圖三個欄位：改了字只按 Enter（tk_key 走 <Return> 的綁定，不直接叫 compute）就重算
    sig = _eye_add("ret53", {"x": np.repeat(rng.integers(0, 2, 120) * 2.0 - 1.0, 4)})[0]
    sig.sps = 4.0
    app.plot(); app.update()
    w = _eye_open([sig])
    n_auto = w.v_n.get()
    w.v_n.set("12"); tk_key(w._fields["n"], "Return"); app.update()
    r_n = w.result.get("n")
    w.v_period.set("3"); tk_key(w._fields["period"], "Return"); app.update()
    r_p = w.result.get("period")
    w.v_offset.set("5"); tk_key(w.sp_offset, "Return"); app.update()
    r_o = w.result.get("offset")
    check(n_auto == "8" and r_n == 12 and r_p == 3.0 and r_o == 5 and not w.field_errors,
          f"眼圖欄位按 Enter 就重算：n 8（自動＝2 × SPS 4）→ 12、週期 → 3、取樣偏移 → 5（{n_auto} {r_n} {r_p} {r_o}）")
    w.destroy(); app.update()
    # ---- (b) I/Q 兩條的 SPS 不同：說明列提示「… 的 SPS 不同，用樣本索引對齊」；改成一樣就不提示
    si, sq = _eye_add("sps53", {"x i": np.cos(np.arange(400) / 9.0), "x q": np.sin(np.arange(400) / 9.0)})
    si.sps, sq.sps = 4.0, 2.0
    app.plot(); app.update()
    w2 = _eye_open([si, sq])
    s0, s1 = w2.signals
    note = f"{s0.name} 與 {s1.name} 的 SPS 不同，用樣本索引對齊"
    had = note in w2.v_msg.get()
    sq.sps = 4.0
    w2.compute(); app.update()
    check(w2 is not None and had and len(w2.fig.axes) == 2 and note not in w2.v_msg.get(),
          f"I/Q 的 SPS 不同（4 與 2）→ 說明列提示「{note[-20:]}」、兩張照畫；SPS 改成一樣 → 提示拿掉（{had}）")
    # ---- (c) 線寬／標記大小「自訂…」（simpledialog.askfloat 的替身）、顏色對話框取消（colorchooser 回 (None, None)）
    seen = []
    sty0 = w2._style_now()
    sv.simpledialog.askfloat = lambda *a, **k: (seen.append((a[:2], k.get("initialvalue"), k.get("minvalue"), k.get("maxvalue"))), 2.5)[1]
    _eye_menu(w2, "線寬", "自訂…")
    lw_after = (_eye_lines(w2)[0].get_linewidth(), app.eye_defaults.get("lw"), w2.v_status.get())
    sv.simpledialog.askfloat = lambda *a, **k: (seen.append((a[:2], k.get("initialvalue"), k.get("minvalue"), k.get("maxvalue"))), 9.0)[1]
    _eye_menu(w2, "標記大小", "自訂…")
    ms_after = (_eye_lines(w2)[0].get_markersize(), app.eye_defaults.get("ms"), w2.v_status.get())
    sv.simpledialog.askfloat = lambda *a, **k: (seen.append((a[:2], k.get("initialvalue"), k.get("minvalue"), k.get("maxvalue"))), None)[1]   # 對話框按取消
    _eye_menu(w2, "線寬", "自訂…")
    lw_cancel = (_eye_lines(w2)[0].get_linewidth(), app.eye_defaults.get("lw"))
    col0, dcol0, st0 = _eye_lines(w2)[0].get_color(), app.eye_defaults.get("color"), w2.v_status.get()
    sv.colorchooser.askcolor = lambda *a, **k: (None, None)           # 選色器按取消
    _eye_menu(w2, "顏色", "自訂…")
    col_cancel = (_eye_lines(w2)[0].get_color(), app.eye_defaults.get("color"), w2.v_status.get())
    check(seen == [(("線寬", "線寬（點）："), float(sty0["lw"]), 0.1, 20.0), (("標記大小", "標記大小（點）："), float(sty0["ms"]), 1.0, 60.0),
                   (("線寬", "線寬（點）："), 2.5, 0.1, 20.0)]
          and lw_after == (2.5, 2.5, "眼圖線條的線寬：2.5") and ms_after == (9.0, 9.0, "眼圖線條的標記大小：9") and lw_cancel == (2.5, 2.5)
          and col_cancel == (col0, dcol0, st0),
          f"眼圖右鍵 線寬／標記大小「自訂…」：對話框帶目前的值（{sty0['lw']}／{sty0['ms']}）與上下限，回 2.5／9 就套上、記進設定、狀態列說明；"
          f"按取消不改（{lw_cancel}）；顏色「自訂…」按取消不改（{col_cancel[0]}）（{seen}）")
    _eye_menu(w2, None, "重設樣式")
    w2.destroy(); app.update()
    # ---- (d) 那張 panel 的訊號全部隱藏 → 眼圖／錯誤率比對（panel 右鍵「眼圖（P2）…」走的 open_eye(panel=…)）不開視窗、狀態列說明
    p_h = si.panel
    app.sig_tree.selection_set([f"s{si.uid}", f"s{sq.uid}"]); app._on_list_select()
    app.toggle_visible([si, sq]); app.update()                       # 清單的「顯示」欄（可以 ⌘Z）
    n_e = len([x for x in app.winfo_children() if isinstance(x, (sv.EyeWindow, sv.ErrRateWindow))])
    r_e = app.open_eye(panel=p_h); app.update()
    st_e = app.status_var.get()
    r_r = app.open_errrate(panel=p_h); app.update()
    st_r = app.status_var.get()
    app.undo_action(); app.update()
    check(r_e is None and r_r is None and st_e == f"眼圖：P{p_h} 沒有顯示中的訊號" and st_r == f"錯誤率比對：P{p_h} 沒有顯示中的訊號"
          and len([x for x in app.winfo_children() if isinstance(x, (sv.EyeWindow, sv.ErrRateWindow))]) == n_e and si.visible and sq.visible,
          f"P{p_h} 的訊號全部隱藏 → 眼圖、錯誤率比對都不開視窗，狀態列「眼圖：P{p_h} 沒有顯示中的訊號」「錯誤率比對：P{p_h} 沒有顯示中的訊號」；⌘Z 顯示回來"
          f"（{st_e}／{st_r}）")
    # ---- (e) 錯誤率：欄位按 Enter 就重算；「重新計算」強制重算（force＝True：輸入看起來沒變也重算）
    app.clear_all(); app.update()
    bits = rng.integers(0, 4, 100)
    rxb = bits.copy()
    rxb[[10, 11, 40]] = (rxb[[10, 11, 40]] + 1) % 4
    tx = _er_sig("u53_tx", bits, 4)
    rx = _er_sig("u53_rx", rxb, 4, panel=tx.panel)
    w3 = _er_open([tx, rx])
    _er_set(w3, rd=0, cd=0, samples="整個訊框", custom="")
    base = (w3.result.get("n"), w3.result.get("sym_err"), dict(app._errmarks))
    w3.v_rd.set("1"); tk_key(w3._fields["rd"], "Return"); app.update()
    r_rd = w3.result.get("rd")
    w3.v_cd.set("2"); tk_key(w3._fields["cd"], "Return"); app.update()
    r_cd = w3.result.get("cd")
    w3.v_samples.set("自訂"); w3.v_custom.set("10 20 30"); tk_key(w3.e_custom, "Return"); app.update()
    r_cu = (w3.result.get("samples"), w3.result.get("n"))
    _er_set(w3, rd=0, cd=0, samples="整個訊框", custom="")
    check(base[:2] == (100, 3) and base[2].get(tx.panel) == [(10.0, 12.0), (40.0, 41.0)] and r_rd == 1 and r_cd == 2 and r_cu == ("Custom", 3),
          f"錯誤率欄位按 Enter 就重算：接收延遲 → 1、計算延遲 → 2、自訂樣本位置 10 20 30（接收延遲 1、計算延遲 2 之後都在可以比的範圍）→ 比 3 個"
          f"（{base[:2]} {r_rd} {r_cd} {r_cu}）")
    btn_rc = next(b_ for b_ in w3._fields["rd"].master.winfo_children() if isinstance(b_, sv.ttk.Button) and str(b_.cget("text")) == "重新計算")
    y = rx.get_data()
    y[200:204] = (y[200:204] + 1) % 4                                  # 記憶體裡的資料就地改了（同一個陣列物件：快取的鍵看不出來）
    w3.compute(); app.update()
    stale = w3.result.get("sym_err")
    btn_rc.invoke(); app.update()
    forced = (w3.result.get("sym_err"), app._errmarks.get(tx.panel))
    rx.invalidate()
    btn_rc.invoke(); app.update()
    back = w3.result.get("sym_err")
    check(stale == 3 and forced == (4, [(10.0, 12.0), (40.0, 41.0), (50.0, 51.0)]) and back == 3,
          f"「重新計算」強制重算：資料就地改了（快取看不出來）→ compute() 還是 3 個錯、按鈕（force）→ 4 個錯、區段多一段；資料還原再按 → 3（{stale} {forced} {back}）")
    # ---- (f) 每個 panel 的 x 單位＝µs、Symbol rate 2M：主圖刻度換算（20 symbol → 10 µs）；錯誤率的取樣（每個 symbol 中點）與紅色區段（symbol 格子）
    #          和 symbol 單位時完全一樣、上一個／下一個錯誤寫 µs；眼圖「只用目前 x 範圍」取的樣本和 symbol 單位時一樣
    p = tx.panel
    app.set_panel_prop("xunit", "us", panel=p); app.update()
    app.set_panel_prop("symbol_rate", "2M", panel=p); app.update()
    fmt = _ax(p).xaxis.get_major_formatter()
    tick = fmt(20.0, 0)
    xlabel = _ax(p).get_xlabel()
    _er_set(w3, rd=0, cd=0, samples="整個訊框", custom="")
    us_res = (w3.result.get("n"), w3.result.get("sym_err"), app._errmarks.get(p))
    app.show_all_x(); app.update()
    st_go = w3.goto(1) or w3.v_status.get()
    check(tick == "10" and "us" in xlabel and us_res == (100, 3, [(10.0, 12.0), (40.0, 41.0)]) and st_go.startswith(f"錯誤 1/2：P{p}，x 5..6 us"),
          f"x 單位 µs、Symbol rate 2M：主圖刻度 20 symbol → 10（{tick}，標籤 {xlabel!r}）；錯誤率照樣每個 symbol 取中點、紅色區段仍是 symbol 的格子"
          f"（{us_res[:2]} {us_res[2]}）；「下一個錯誤」寫 µs（{st_go[:36]}）")
    w3.destroy(); app.update()
    _ax(p).set_xlim(10.0, 30.0); app.canvas.draw(); app.update()
    app.sig_tree.selection_set([f"s{tx.uid}"]); app._on_list_select(); app.update()
    w4 = app.open_eye(); app.update()
    _eye_set(w4, xrange=True)
    s_us = (w4.result.get("samples"), w4.v_status.get()[:12])
    app.set_panel_prop("xunit", "symbol", panel=p); app.update()
    xl_sym = app.panel_xlim(p)
    w4.compute(); app.update()
    s_sym = w4.result.get("samples")
    check(s_us[0] == s_sym == 81 and xl_sym == (10.0, 30.0) and s_us[1].startswith("已畫"),
          f"眼圖「只用目前 x 範圍」在 µs 單位之下：主圖 symbol 10..30（顯示 5..15 µs）→ 取 81 個樣本（SPS 4），換回 symbol 單位一樣 81（{s_us} {s_sym} {xl_sym}）")
    w4.destroy(); app.update()


