    h, fz, csv2, arg, fzp, a_p, b_p = _prep("i", auto_cfg=_old, bak_cfg=_newer_en)
    rc, st, marks, tb, logt = _s54_run_child(h, ["--lang", "zh", arg], answer="yes")
    a_i = _s49_read(a_p)
