@step
def s55_0913_w1_popup_menus_released():
    """0.9.13 W1（Windows 相容性檢查 verify_win_0912.md）：每個右鍵／下拉選單站點彈出之後把選單（連子選單）銷毀——Windows 的 Tk 選單代號是
    16 位元，0.9.12 每次右鍵建約 12 個 tk.Menu 從不銷毀，約 430 次右鍵後「No more menus can be allocated」、之後任何選單都開不了只能重開。
    這裡把 POPUP_MENU_RELEASE_MS 設 1 ms、tk_popup 換成只記錄的假函式，走每一個站點：主圖空白／線上（平移、資料提示、無模式）、放大／平移模式選單、
    清單右鍵、資料夾面板右鍵（標題列、列）、panel 標題區、量測項目、資料游標／ROI／繪圖類型的下拉、Dock 面板 ▾、AM/PM/FM 視窗右鍵（開得起來時）——
    事件迴圈跑過之後彈過的選單都不在了、活著的 tk.Menu 數回到彈出前；POPUP_MENU_RELEASE_MS＝None（測試模式）時照 0.9.12 留著。"""
    from types import SimpleNamespace as NS
    from matplotlib.backend_bases import MouseEvent
    M = sv.pk.menus
    popped = []
    orig = sv.tk.Menu.tk_popup

    def rec(self, x, y, entry=None):
        popped.append(self)
    mode0 = {"pan/zoom": "pan", "zoom rect": "zoom"}.get(app.plot_toolbar.mode, "")
    sel0 = list(app.sig_tree.selection())
    rel_knob0 = M.POPUP_MENU_RELEASE_MS                          # 測試整體的設定（10 秒）：跑完放回去（以前放成 None，之後的步驟彈的選單都不銷毀）
    sites = []

    peaks = []

    def site(name, fn):
        n0 = len(popped)
        try:
            fn()
            peaks.append(M.live_menus(app))                      # 彈出後、事件迴圈跑之前：選單還在（1 ms 的計時器還沒到）
            app.update()
        except Exception as e:
            sites.append((name, f"例外 {type(e).__name__}: {e}"))
            return
        sites.append((name, len(popped) - n0))
    if not app.signals:                                          # 只跑 s55（DSV_TEST_ONLY）時自己建前提
        pth = os.path.join(OUT, "s55.txt")
        with open(pth, "w", encoding="utf-8") as f:
            f.write("\n".join(str(k % 2) for k in range(64)) + "\n")
        app.add_text_signal(pth)
        app.refresh_list(); app.plot(); app.update()
    wiq = None
    alive, kept, immediate, n_base, n_mid, n_after = ["?"], False, False, -1, -1, -1
    M.release_recent()                                           # 前面步驟彈過、還在等 10 秒計時器的選單先銷毀（只跑 s38,s55 時 s38 剛彈過），彈出前的基準才乾淨
    app.update()
    sv.tk.Menu.tk_popup = rec
    M.POPUP_MENU_RELEASE_MS = 1
    try:
        _s35_mode_off()
        sig = app.signals[0]
        p = sig.panel
        ax = _ax(p)
        n_base = M.live_menus(app)
        for mode in ("pan", "tips", ""):
            _set_mode(mode)
            site(f"主圖空白（{mode or '無'}）", lambda: app._context_for_hit(NS(kind="empty", id=None, ax=ax), NS(guiEvent=None, x=0, y=0)))
            site(f"主圖線上（{mode or '無'}）", lambda: app._context_for_hit(NS(kind="line", id=sig.uid, ax=ax), NS(guiEvent=None, x=0, y=0)))
        _s35_mode_off()
        cx, cy = pk.interact.axes_center_px(ax)
        site("放大模式選單", lambda: app.ia.zoom_mode_context(MouseEvent("button_press_event", app.canvas, cx, cy, button=3)))
        site("平移模式選單", lambda: app.ia.pan_mode_context(MouseEvent("button_press_event", app.canvas, cx, cy, button=3)))
        tree = app.sig_tree
        site("清單右鍵", lambda: app._on_list_context(NS(x=5, y=5, x_root=tree.winfo_rootx() + 5, y_root=tree.winfo_rooty() + 5)))
        ft = app.file_tree
        site("資料夾面板標題列右鍵", lambda: app._cf_context(NS(x=5, y=3, x_root=ft.winfo_rootx() + 5, y_root=ft.winfo_rooty() + 3)))
        site("資料夾面板列右鍵", lambda: app._cf_context(NS(x=5, y=40, x_root=ft.winfo_rootx() + 5, y_root=ft.winfo_rooty() + 40)))
        site("panel 標題區右鍵", lambda: app._panel_strip_menu(p, 10, 10))
        if getattr(app, "_meas_rows_btn", None) is not None:
            site("量測項目", lambda: app._meas_rows_menu())
        if getattr(app, "_dcursor_btn", None) is not None:
            site("資料游標下拉", lambda: app._dcursor_button_menu())
        if getattr(app, "_roi_btn", None) is not None:
            site("ROI 下拉", lambda: app._roi_button_menu())
        app.sig_tree.selection_set([f"s{sig.uid}"]); app._on_list_select()
        if getattr(app, "_ptype_btn", None) is not None:
            site("繪圖類型下拉", lambda: app._ptype_button_menu())
        key = next(iter(app.dock.panels))
        site("Dock 面板 ▾", lambda: app.dock.post_menu(key))
        try:
            wiq = app.open_iq_window("fm")
            app.update()
        except Exception:
            wiq = None
        if wiq is not None and wiq.winfo_exists():
            site("AM/PM/FM 視窗右鍵", lambda: wiq.context_menu(NS(kind="empty", id=None, ax=None), NS(guiEvent=None)))
            site("AM/PM/FM 視窗圖例右鍵", lambda: wiq.context_menu(NS(kind="legend", id=None, ax=None), NS(guiEvent=None)))
        n_mid = max(peaks) if peaks else -1
        t0 = time.time()
        while time.time() - t0 < 3.0 and any(m.winfo_exists() for m in popped):
            app.update()
            time.sleep(0.01)
        alive = [m for m in popped if m.winfo_exists()]
        n_after = M.live_menus(app)
        # 上一個彈過的選單在下一次彈出時就銷毀（不用等計時器；Windows 沒有桌面的工作階段桌面堆很小、連點會用完）
        M.POPUP_MENU_RELEASE_MS = 10000
        n_r = len(popped)
        app._context_for_hit(NS(kind="empty", id=None, ax=ax), NS(guiEvent=None, x=0, y=0))
        app._context_for_hit(NS(kind="line", id=sig.uid, ax=ax), NS(guiEvent=None, x=0, y=0))
        app._panel_strip_menu(p, 10, 10)
        trio = popped[n_r:]
        immediate = (len(trio) == 3 and not trio[0].winfo_exists() and not trio[1].winfo_exists() and trio[2].winfo_exists()
                     and M.live_menus(app) <= n_base + 12)
        M.release_recent()
        immediate = immediate and not trio[2].winfo_exists()
        # 對照：None（測試模式）＝不銷毀（0.9.12 的行為）
        M.POPUP_MENU_RELEASE_MS = None
        n1 = len(popped)
        app._context_for_hit(NS(kind="empty", id=None, ax=ax), NS(guiEvent=None, x=0, y=0))
        app.update(); time.sleep(0.03); app.update()
        kept = len(popped) == n1 + 1 and popped[-1].winfo_exists()
        for m in popped[n1:]:
            try:
                m.destroy()
            except Exception:
                pass
    finally:
        M.POPUP_MENU_RELEASE_MS = None
        sv.tk.Menu.tk_popup = orig
        if wiq is not None:
            try:
                wiq.destroy()
            except Exception:
                pass
        _s35_mode_off()
        app.plot_toolbar.set_mode(mode0)
        app.sig_tree.selection_set([i for i in sel0 if app.sig_tree.exists(i)]); app._on_list_select()
        app.update()
    bad = [(n, r) for n, r in sites if not (isinstance(r, int) and r >= 1)]
    check(len(sites) >= 14 and not bad and len(popped) >= 14, f"W1 每個站點都走到、都彈了選單（{len(popped)} 次）：{sites}")
    check(not alive and n_mid > n_base and n_after <= n_base,
          f"W1 事件迴圈跑過後彈過的 {len(popped)} 個選單都銷毀了（還活著 {len(alive)}）；活著的 tk.Menu：彈出前 {n_base} → 彈出後最多 {n_mid} → 銷毀後 {n_after}")
    check(immediate, "W1 連續右鍵：上一個彈過的選單在下一次彈出時就銷毀（不等計時器）、release_recent() 銷毀最後一個")
    check(kept, "W1 POPUP_MENU_RELEASE_MS＝None（測試模式）時照 0.9.12 留著不銷毀")
    M.POPUP_MENU_RELEASE_MS = rel_knob0
    _s55_bgerror_check()


def _s55_bgerror_check():
    """0.9.13 第一輪回歸驗證（verify_0913_r1_regression 3c）：產品預設的延遲（POPUP_MENU_RELEASE_MS＝1000）之下，分析視窗（眼圖、錯誤率比對、
    AM/PM/FM、頻譜）彈過右鍵選單、1 秒內就關掉——也不能留下 Tk 背景錯誤（銷毀計時器掛在主視窗上，選單先不在了就什麼都不做；提早銷毀時取消）。
    f4e660e：計時器掛在選單自己身上，視窗一關 Tkinter 就把回呼命令刪掉、Tcl 的 after 還在，到期時「invalid command name …<lambda>」
    （0.9.12 的 s38「關眼圖視窗沒有 Tk 背景錯誤」在 0.9.13 失敗；0.9.13 自己的測試把延遲改成 10 秒才看不到）。"""
    from types import SimpleNamespace as NS
    M = sv.pk.menus
    orig = sv.tk.Menu.tk_popup
    rel0 = M.POPUP_MENU_RELEASE_MS
    popped = []
    sv.tk.Menu.tk_popup = lambda self, x, y, entry=None: popped.append(self)
    app.tk.eval("set ::dsv_s55_bg {}; proc ::dsv_s55_bgrec {msg opts} {lappend ::dsv_s55_bg $msg}")
    old_h = app.tk.call("interp", "bgerror", "")
    app.tk.call("interp", "bgerror", "", "::dsv_s55_bgrec")
    wins, names = [], []
    sel0 = list(app.sig_tree.selection())
    try:
        M.POPUP_MENU_RELEASE_MS = _POPUP_DEFAULT_MS
        if len([s_ for s_ in app.signals if not s_.derive and not s_.waiting()]) < 2:      # 只跑 s55 時：錯誤率比對、AM/PM/FM 要兩條
            for k_ in range(2):
                pth = os.path.join(OUT, f"s55_bg{k_}.txt")
                with open(pth, "w", encoding="utf-8") as f:
                    f.write("\n".join(str((k * (k_ + 1)) % 2) for k in range(64)) + "\n")
                app.add_text_signal(pth)
            app.refresh_list(); app.plot(); app.update()
        sig = next(s_ for s_ in app.signals if not s_.derive and not s_.waiting())
        p = sig.panel
        two = [s_ for s_ in app.signals if not s_.derive and not s_.waiting()][:2]
        app.sig_tree.selection_set([f"s{s_.uid}" for s_ in two]); app._on_list_select(); app.update()
        openers = (("眼圖", lambda: app.open_eye(panel=p)), ("錯誤率比對", lambda: app.open_errrate()),
                   ("AM/PM/FM", lambda: app.open_iq_window("fm")),
                   ("頻譜", lambda: (app.open_spectrum(), ([x for x in app.winfo_children() if isinstance(x, sv.SpectrumWindow)] or [None])[-1])[1]))
        for name, fn in openers:
            try:
                w = fn(); app.update()
            except Exception:
                w = None
            if w is None or not w.winfo_exists():
                continue
            wins.append(w)
            if hasattr(w, "context_menu"):                # 錯誤率比對視窗沒有圖的右鍵選單：照樣開著、一起關（不彈）
                w.context_menu(NS(kind="empty", id=None, ax=None), NS(guiEvent=None))
                names.append(name)
        n_pop = len(popped)
        for w in wins:
            w.destroy()                                   # 選單的銷毀計時器（產品預設 1 秒）還沒到就關視窗
        app.update()
        t0 = time.time()
        while time.time() - t0 < _POPUP_DEFAULT_MS / 1000.0 + 0.6:
            app.update()
            time.sleep(0.02)
        bg = str(app.tk.eval("set ::dsv_s55_bg"))
    finally:
        app.tk.call("interp", "bgerror", "", old_h)
        M.POPUP_MENU_RELEASE_MS = rel0
        sv.tk.Menu.tk_popup = orig
        M.release_recent()
        app.sig_tree.selection_set([i for i in sel0 if app.sig_tree.exists(i)]); app._on_list_select()
        app.update()
    check(len(names) >= 3 and n_pop >= 3 and bg == "" and not any(m.winfo_exists() for m in popped),
          f"W1：產品預設的延遲（{_POPUP_DEFAULT_MS} ms）之下分析視窗（{'、'.join(names)}）彈過右鍵選單、馬上關掉 → 沒有 Tk 背景錯誤、選單都銷毀了"
          f"（背景錯誤：{bg[:120]!r}）")


