_W14_WHEEL_ORIG = []

# 驗名稱、標題全文、匯流排框裡的字的步驟：檢查假設圖的欄有 Mac 視窗那麼寬（字放得下、不縮短加「…」）。PC 175% 直立螢幕的主視窗只有
# 586 點寬，前面的步驟（s17 資料游標）留著的右欄讀數把圖的欄擠到 Dock 的 45%（W10 的規則），標題照規則縮短、匯流排的字放不下——
# 單獨跑這幾步（右欄沒開）都過（2026-10-29 PC：s1–s3＋s41 113/113、s18＋s19 91/91）。Windows 上這幾步先把右欄的面板收起來、
# 步驟結束照原樣打開（和單獨跑的版面一樣）；Mac 不包，照舊。
_W14_WIDE_STEPS = ("s19_bus_display", "s41_axis_names", "s42_paste_axis_names", "s43_panel_menus_split_cut", "s45_fix2_round2",
                   "s46_merge_u26_batch3")


def _w14_wide_plot(fn):
    import functools

    @functools.wraps(fn)
    def run_():
        d = app.dock
        opened = [k for k in d.order.get("right", []) if k not in d.hidden and k in app.v_panel and app.v_panel[k].get()]
        for k in opened:
            app.v_panel[k].set(False); app._toggle_panel(k)
        if opened:
            app.update()
        try:
            return fn()
        finally:
            for k in opened:
                try:
                    if not app.v_panel[k].get():
                        app.v_panel[k].set(True); app._toggle_panel(k)
                except Exception:
                    pass
            if opened:
                app.update()
    return run_


if os.name == "nt":
    steps[:] = [(_w14_wide_plot(fn) if fn.__name__ in _W14_WIDE_STEPS else fn) for fn in steps]


def _w14_geo_containing(self_w, rootX, rootY, displayof=0):
    """winfo_containing 的 Tk 幾何版：照 wm stackorder 由最上面的頂層視窗找起，看 (rootX, rootY) 落在哪一個，再一層一層往裡找
    最深、疊在最上面（winfo children 的順序＝由下到上）的元件。只給 Windows 的安靜模式用（見 _w14_wheel_hit）。"""
    root = self_w._root()
    x, y = int(rootX), int(rootY)

    def inside(w):
        try:
            return bool(w.winfo_ismapped()) and w.winfo_rootx() <= x < w.winfo_rootx() + w.winfo_width() \
                and w.winfo_rooty() <= y < w.winfo_rooty() + w.winfo_height()
        except Exception:
            return False
    try:
        order = list(root.tk.splitlist(root.tk.call("wm", "stackorder", ".")))
    except Exception:
        order = ["."]
    for path in reversed(order):
        try:
            cur = root.nametowidget(path)
        except Exception:
            continue
        if not inside(cur):
            continue
        while True:
            nxt = None
            for c in cur.winfo_children():
                try:
                    if c.winfo_class() in ("Toplevel", "Menu", "Tk"):
                        continue
                except Exception:
                    continue
                if inside(c):
                    nxt = c
            if nxt is None:
                return cur
            cur = nxt
    return None


def _w14_wheel_hit(on: bool) -> bool:
    """W-A：Windows 的安靜模式把每個視窗設成 alpha 0 的 layered window，作業系統的命中測試（WindowFromPoint）穿過它，
    winfo_containing 一律回 None——產品的滾輪處理（_bind_plot_wheel 先看游標在不在右側畫布）和 matplotlib 在 Windows 的滾輪
    （scroll_event_windows 也用 winfo_containing 找畫布）都直接 return，套件裡的滾輪檢查量不到產品的判斷。on＝True 時（只有 Windows
    的安靜模式）把 tkinter 的 winfo_containing 換成 Tk 幾何版，產品與 matplotlib 的判斷（座標區內外、放不下要捲、修飾鍵、縮放）照樣
    全部走過；作業系統那一段（真滑鼠在不透明視窗上滾）在 PC 桌面另外用真的滾輪驗（第 7 項）。Mac（安靜模式的 winfo_containing 照常，
    sq 步驟驗過）、無桌面都不換。回傳這次有沒有換。"""
    import tests_common as tc_
    if on:
        if os.name != "nt" or not tc_.QUIET or HL or _W14_WHEEL_ORIG:
            return False
        _W14_WHEEL_ORIG.append(sv.tk.Misc.winfo_containing)
        sv.tk.Misc.winfo_containing = _w14_geo_containing
        return True
    if _W14_WHEEL_ORIG:
        sv.tk.Misc.winfo_containing = _W14_WHEEL_ORIG.pop()
        return True
    return False


def _w14_recorded_keys_win(w, g_init):
    """Windows 版的「使用者錄的 ⌘3／⌘7／⌘` 按一次做一次」（_fx2_zhuyin_3_7_grave 的 macOS 注音鍵碼在 Windows 沒有對應的事件）：
    錄成 Ctrl+3／Ctrl+7／Ctrl+Grave，用 Windows 的按鍵事件（keysym＋VK 碼、Control）各按兩次——各翻一次格線、不重複；
    偏好設定 → 鍵盤 錄快速鍵：Windows 的 Ctrl+3／Ctrl+`（VK 0x33／0xC0）錄成 Ctrl+3／Ctrl+Grave。微軟注音本身沒測到（規則不允許切輸入法）。"""
    from types import SimpleNamespace
    try:
        for spec, ks, ch, vk in (("Ctrl+3", "3", "3", 0x33), ("Ctrl+7", "7", "7", 0x37), ("Ctrl+Grave", "grave", "`", 0xC0)):
            app.keymap.add("view.grid", spec); app._apply_keymap()
            w.focus_set(); app.update()
            g0 = app.v["grid"].get()
            tk_key(w, ks, char=ch, mods="Control", keycode=vk); app.update()
            g1 = app.v["grid"].get()
            tk_key(w, ks, char=ch, mods="Control", keycode=vk); app.update()
            g2 = app.v["grid"].get()
            check(g1 == (not g0) and g2 == g0,
                  f"Windows：使用者把 {spec} 錄給「格線」：Windows 的按鍵事件（keysym {ks}、VK {vk:#x}）按一次翻一次、不重複（{g0}→{g1}→{g2}）")
            app.keymap.reset("view.grid"); app._apply_keymap()
        d = sv.PreferencesDialog(app); d.grab_release(); app.update()
        rec = {}
        try:
            d._show("keyboard"); app.update()
            for name, ks, vk in (("Ctrl+3", "3", 0x33), ("Ctrl+7", "7", 0x37), ("Ctrl+`", "grave", 0xC0)):
                d._kb_capture_key(SimpleNamespace(keysym=ks, keycode=vk, state=4))
                rec[name] = d._kb_spec
        finally:
            d.destroy(); app.update()
        check(rec == {"Ctrl+3": "Ctrl+3", "Ctrl+7": "Ctrl+7", "Ctrl+`": "Ctrl+Grave"},
              f"Windows：偏好設定 → 鍵盤 錄快速鍵：Windows 的 Ctrl+3／Ctrl+7／Ctrl+` 錄成 Ctrl+3／Ctrl+7／Ctrl+Grave（{rec}）")
    finally:
        app.keymap.reset("view.grid"); app._apply_keymap()
        if app.v["grid"].get() != g_init:
            app.v["grid"].set(g_init); app._on_view_toggle("grid")
        app.update()


def _w14_line_point(sig, frac=0.33):
    """訊號 sig 的線上第 frac 位置的樣本（matplotlib 像素）——點線選取群（W-E）用的點。macOS 照舊就是那個樣本。
    Windows（175%、直立螢幕）：字是 1.75 倍、座標區窄，固定比例的那個樣本常常剛好在圖例／資料提示框底下，或和同一張圖的另一條線落在
    同一個像素（0.9.13 第一輪 PC 驗證的 W-E 24 項）——從那個樣本往兩邊找第一個「hit_test 確實是這條線」的樣本（照實際的線位置挑點，
    要驗的是點到之後的選取規則；找不到就用原本的樣本，檢查照樣會失敗）。"""
    from matplotlib.backend_bases import MouseEvent
    a = app.render_info["artists"][sig.uid]
    ln, ax = a["line"], a["ax"]
    xd, yd = ln.get_xdata(), ln.get_ydata()
    k0 = int(len(xd) * frac)
    x0, y0 = ax.transData.transform((xd[k0], yd[k0]))
    if os.name != "nt" or app.ia is None:
        return float(x0), float(y0)
    n = len(xd)
    for d in range(0, n):
        for k in ((k0 + d, k0 - d) if d else (k0,)):
            if not 0 <= k < n:
                continue
            x, y = ax.transData.transform((xd[k], yd[k]))
            if not (ax.bbox.x0 + 3 <= x <= ax.bbox.x1 - 3 and ax.bbox.y0 + 3 <= y <= ax.bbox.y1 - 3):
                continue
            h = app.ia.hit_test(MouseEvent("motion_notify_event", app.canvas, x, y))
            if h.kind == "line" and h.id == sig.uid:
                return float(x), float(y)
        if d > 400:
            break
    return float(x0), float(y0)


def _w14_wheel_delta(sign: int) -> int:
    """一格滾輪的 delta：Windows 的 WM_MOUSEWHEEL 是 ±120（matplotlib 的 step＝delta／120），Mac 照以前 ±1。"""
    return (120 if os.name == "nt" else 1) * (1 if sign > 0 else -1)


def _w14_geo_checks():
    """Windows 的安靜模式換了命中測試時：幾何版本身對不對（畫布中間＝畫布、捲軸上＝捲軸、主視窗外＝None）。"""
    w = app.canvas.get_tk_widget()
    sc, sb = app.plot_scroll, app.plot_vbar
    cx = sc.winfo_rootx() + sc.winfo_width() // 2
    cy = sc.winfo_rooty() + sc.winfo_height() // 2
    bx = sb.winfo_rootx() + sb.winfo_width() // 2
    by = sb.winfo_rooty() + sb.winfo_height() // 2
    far = (-5000, -5000)                          # 哪個視窗都不在的地方
    got = (app.winfo_containing(cx, cy), app.winfo_containing(bx, by) if sb.winfo_ismapped() else sb,
           app.winfo_containing(*far))
    check(got[0] is w and got[1] is sb and got[2] is None,
          f"W-A：Windows 安靜模式的命中測試（Tk 幾何）：右側畫布中間＝matplotlib 畫布、捲軸上＝捲軸、主視窗外＝None（{got}）")


def _w10_frame_in_work(w):
    """Windows：頂層視窗看得見的框（DWM，含標題列）整個在工作區裡 → (在不在, 框, 工作區)。"""
    outer, vis = sv.T._frame_rects(w)
    l_, t_, r_, b_ = sv.T.work_area(w)
    return (vis[0] >= l_ - 1 and vis[1] >= t_ - 1 and vis[2] <= r_ + 1 and vis[3] <= b_ + 1), vis, (l_, t_, r_, b_)


def _w10_strip_reachable(strip):
    """工具列每個看得到的分頁：分頁鈕在看得到的範圍（或分頁列可捲動、它被捲進來）；內容放不下時有 ◀ ▶（放得下時沒有）。→ 不合格的清單"""
    bad = []
    cur = strip.current
    px = strip.th.px
    for k in [k_ for k_ in strip._order if strip.tab_visible(k_)]:
        strip.select(k)
        strip.update()
        st = strip.narrow_state()
        W = strip.winfo_width()
        need = strip.tabs[k].winfo_reqwidth()
        arr = strip._nw["arrows"]
        if need > W and not (st["body_scroll"] and arr.get("body_l") is not None and arr["body_r"].winfo_manager() == "place"):
            bad.append(f"{k}：內容 {need} > {W} 卻不能捲動")
        if need <= W and st["body_scroll"]:
            bad.append(f"{k}：放得下卻在捲動")
        btn = strip._buttons[k]
        qab_w = strip.qab.winfo_reqwidth() + px(6)
        x0 = strip._tabrow.winfo_x() + btn.winfo_x()
        lim = (px(18), W - qab_w - px(18)) if st["tab_scroll"] else (0, W - qab_w)
        if not (lim[0] - 1 <= x0 and x0 + btn.winfo_width() <= lim[1] + 1):
            bad.append(f"{k}：分頁鈕 {x0}+{btn.winfo_width()} 不在看得到的 {lim}")
    if cur:
        strip.select(cur)
    return bad


