    h, a_p, b_p = _s58_home("f3_once", "corrupt", bak_ver=sv.APP_VERSION)
    rc, st, marks, dlgs, err = _s58_run(h, answer="yes", timeout=60, DSV_TEST_BREAK_APPLY=b_p)
