def _s59_txt(path, n=300):
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(str((k * 7) % 13) for k in range(n)) + "\n")


def _s59_bad_csv(path):
    """CSV 被別的程式改寫成欄位名稱不一樣的內容（檔案在、內容不對：讀 b1 i 丟 KeyError）。"""
    with open(path, "w", encoding="utf-8") as f:
        f.write("x1,x2\n" + "\n".join(f"{k},{k}" for k in range(50)) + "\n")


def _s59_cfg_txt(txtp, derived=True):
    """文字檔 T（P1，有標題）＋ lowpass(T)（P2，帶參數）。"""
    P = sv.dsv_preprocess
    params, _e = P.validate("lowpass", dict(P.default_form("lowpass"), units="Hz", fpass="0.05"))
    sigs = [{"key": "t.txt", "path": txtp, "sps": 1.0, "panel": 1, "uid": 1, "label": "T one"}]
    if derived:
        sigs.append({"key": "lowpass(T one)", "path": "", "derive": "pp_lowpass", "src": "1", "sps": 1.0, "panel": 2, "uid": 2,
                     "pp": P.normalize_params("pp_lowpass", params)})
    return {"version": 6, "app_version": sv.APP_VERSION, "root": "", "view": {"autosave": True, "lang": "zh"}, "signals": sigs,
            "panels": {"1": {"link": True, "xunit": "us", "symbol_rate": "2M", "yunit": "mV", "title": "T title"},
                       "2": {"link": True, "xunit": "symbol", "symbol_rate": "1M", "yunit": "", "title": "lp title"}}}


_S59_LOCKS = {}


def _s59_noread(path):
    """讓檔案「在卻讀不了」（s59／s60）：macOS／Linux 拿掉讀取權限（chmod 0，PermissionError）。Windows 的 chmod 只管唯讀屬性、拿不掉讀取權限
    （2026-10-30 合併後 PC 實測：chmod 0 之後照樣讀得到，s59／s60 那幾項因此失敗）——改成「別的程式獨占開著」：CreateFileW 不分享地開著它，
    DSV 開檔得到 PermissionError（WinError 32，檔案正被別的程式使用），和 macOS 沒有讀取權限一樣是 PermissionError、一樣是 README 說的
    「打不開的——沒有權限、被別的程式鎖住」。_s59_canread 放開。"""
    if os.name != "nt":
        os.chmod(path, 0)
        return
    import ctypes
    from ctypes import wintypes
    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    k32.CreateFileW.restype = wintypes.HANDLE
    k32.CreateFileW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    h = k32.CreateFileW(path, 0x80000000, 0, None, 3, 0x80, None)       # GENERIC_READ、不分享、OPEN_EXISTING、FILE_ATTRIBUTE_NORMAL
    if h is None or h == wintypes.HANDLE(-1).value:
        raise OSError(ctypes.get_last_error(), "CreateFileW（不分享）開不了", path)
    _S59_LOCKS[os.path.normcase(os.path.abspath(path))] = h


def _s59_canread(path):
    """_s59_noread 的反向：macOS／Linux 把權限改回 0o644；Windows 關掉獨占的那個 handle。"""
    if os.name != "nt":
        os.chmod(path, 0o644)
        return
    import ctypes
    h = _S59_LOCKS.pop(os.path.normcase(os.path.abspath(path)), None)
    if h is not None:
        ctypes.windll.kernel32.CloseHandle(h)


class _S59Env:
    """s59／s60 共用：暫存資料夾、凍結資料夾、錯誤視窗與 callback 例外的記錄、清單右鍵與工具列的操作。"""

    def __init__(self, tag):
        self.cfg0 = app.dump_settings()
        self.auto0 = app.v["cf_autorefresh"].get()
        self.root0 = app.root_var.get()
        self.fdir_fn = sv.frozen_data_dir
        self.base = tempfile.mkdtemp(prefix=tag + "_", dir=OUT)
        self.ext = os.path.join(self.base, "ext")
        os.makedirs(self.ext)
        fdir = os.path.join(self.base, "frozen")
        os.makedirs(fdir)
        sv.frozen_data_dir = lambda: fdir
        self.csvp = os.path.join(self.ext, "a.csv")
        self.txtp = os.path.join(self.ext, "t.txt")
        self.CB = []
        self.had = "report_callback_exception" in app.__dict__
        app.report_callback_exception = lambda exc, val, tb: self.CB.append(f"{exc.__name__}: {val}")
        self.spy, self.mb0 = _AskSpy(True), sv.messagebox      # 每一個對話框都記下來（「清空」問句照樣回答「是」）
        sv.messagebox = self.spy
        _s35_mode_off()
        app.v["cf_autorefresh"].set(False)

    def close(self):
        for p in (self.txtp, self.csvp, os.path.join(self.ext, "new.txt")):
            try:
                if os.path.exists(p):
                    _s59_canread(p)
            except OSError:
                pass
        sv.messagebox = self.mb0
        if not self.had:
            try:
                del app.report_callback_exception
            except AttributeError:
                pass
        sv.frozen_data_dir = self.fdir_fn
        app.v["cf_autorefresh"].set(self.auto0)
        _s35_mode_off()
        app.sig_tree.selection_set([]); app._on_list_select()
        app.clear_all(); app.update()
        app.root_var.set(self.root0)
        if self.root0:
            app.rescan(quiet=True)
        else:
            app.root_dir = ""
        app.apply_settings(self.cfg0, quiet=True); app.update()

    def dialogs(self):
        return [(n_, str(a_[0]) if a_ else "") for n_, a_ in self.spy.calls if n_.startswith("show")]

    def clear(self):
        self.CB.clear(); self.spy.calls.clear()

    def load(self, cfg):
        app.sig_tree.selection_set([]); app._on_list_select()
        app.clear_all(); app.update()
        app.apply_settings(cfg, quiet=True); app.update()
        self.clear()
        return all(len(s_.get_data()) > 0 for s_ in app.signals) and not any(s_.missing_file for s_ in app.signals)

    @staticmethod
    def g():
        return {s_.name: s_ for s_ in app.signals}

    @staticmethod
    def rows():
        tree = app.sig_tree
        out = []
        for s_ in app.signals:
            v_ = tree.item(f"s{s_.uid}")["values"] if tree.exists(f"s{s_.uid}") else []
            out.append((s_.name, bool(s_.missing_file), bool(s_.waiting()), str(v_[7]) if len(v_) > 7 else None))
        return out

    @staticmethod
    def lens():
        return [len(s_.get_data()) for s_ in app.signals]

    @staticmethod
    def select(*sigs):
        app.sig_tree.selection_set([f"s{s_.uid}" for s_ in sigs])
        app._on_list_select(); app.update()

    def list_menu(self, sig=None):
        """真的清單右鍵：先選那一列、在那一列上按右鍵；sig＝None 在第一列（選取不變）。"""
        tree = app.sig_tree
        if sig is not None:
            self.select(sig)
            bb = tree.bbox(f"s{sig.uid}")
        else:
            kids = tree.get_children()
            bb = tree.bbox(kids[0]) if kids else None
        y_ = (bb[1] + 2) if bb else 5
        menus.clear(); menu_objs.clear()
        app._on_list_context(SimpleNamespace(x=5, y=y_, x_root=tree.winfo_rootx() + 5, y_root=tree.winfo_rooty() + y_)); app.update()
        return menu_objs[-1] if menu_objs else None

    def fmt_menu(self, sig, f="DEC"):
        """清單右鍵「讀取格式」→ f（Tk 的 invoke：例外交給 report_callback_exception）。"""
        m = self.list_menu(sig)
        sub = None
        if m is not None:
            for i in range(m.index("end") + 1):
                if m.type(i) == "cascade" and m.entrycget(i, "label") == sv.tr("讀取格式"):
                    sub = app.nametowidget(m.entrycget(i, "menu"))
        ok_ = sub is not None and invoke_menu(sub, f)
        app.update()
        return ok_

    def menu_item(self, sig, label):
        m = self.list_menu(sig)
        ok_ = m is not None and invoke_menu(m, label)
        app.update()
        return ok_

    @staticmethod
    def via_tk(fn):
        app.after(0, fn); app.update()

    @staticmethod
    def tick():
        """資料夾自動重新整理的計時器跳一次（3 秒那一跳）。"""
        app.v["cf_autorefresh"].set(True)
        app._cf_autorefresh_tick(); app.update()
        app.after_cancel(app._cf_refresh_job)
        app.v["cf_autorefresh"].set(False)


@step
def s59_0914_a_running_placeholders():
    """0.9.14 A（2026-10-29 22:5x 使用者決定「App 開著時檔案出問題的其他情況都改成留佔位」，取代 0.9.13「執行中才壞掉的照舊」）：
    ① 沒有衍生訊號、檔案不見了又改讀取格式（清單右鍵、工具列「讀取格式」＋套用、⌘Z／⌘Y）；② 檔案在但讀不了（拿掉讀取權限、CSV 被改寫成
    欄位名稱不一樣）又改讀取格式（清單右鍵、工具列、訊號屬性面板的套用），有沒有衍生訊號都一樣；③ 重畫時才發現讀不了（檔案被改壞或拿掉權限之後
    按「重新掃描」、做別的會重畫的動作）——都和 B1 一樣留佔位：訊號、衍生訊號、前處理參數、panel 設定都留在清單（灰字、Fmt「檔案不在」或「讀不了」），
    自動存檔（和內容一樣的備份）照記；沒有錯誤視窗、沒有「讀取訊號失敗（已從清單移除）」、沒有「發生錯誤」；狀態列一句說明（呼叫端自己那句後面接著寫）；
    檔案回來或修好，原本的重新載入方式（清單右鍵、自動重新整理、再拖進來、重新掃描）就讀回來。貼上檔案讀不了的訊號也貼成佔位（C 的延伸）；
    剛加進來還沒讀過的檔讀不了照舊不加（移除＋錯誤視窗、狀態列「拖進來的檔案都讀不了」）。
    95bb038：①、②沒有衍生訊號＝「讀取訊號失敗（已從清單移除）」；②有衍生訊號＝「發生錯誤」（沒處理的例外）；③連衍生訊號、前處理參數一起移除；
    貼上讀不了的＝移除＋「發生錯誤」（TclError）。"""
    E = _S59Env("s59")
