    def press():
        if self.title() in ("還有檔案沒處理", "Some files still need your attention"):
            self.buttons[True].invoke()              # 關閉時的提醒（2026-10-30）：這一步不看它，像使用者一樣按「確定」（不按要等 15 秒它自己關）
            return
        if len(self.buttons) < 2:
            return
        note("dialog " + json.dumps({"title": self.title(), "buttons": [str(b.cget("text")) for b in self.buttons.values()],
                                     "msg": self.message or ""}, ensure_ascii=False))
        how = os.environ.get("DSV_TEST_B3_ANSWER", "no")
        if how == "close":
            self.master.on_close()
        else:
            self.buttons[how == "yes"].invoke()
