import threading as _s62_threading                          # noqa: E402
_S62_LANES = _s62_threading.Semaphore(3)


def _s62_child_script():
    """_S62_CHILD 寫到 OUT（同一份，只寫一次；s62 在開執行緒之前先叫）。"""
    child = os.path.join(OUT, "s62_child.py")
    if not os.path.exists(child):
        with open(child, "w", encoding="utf-8") as f:
            f.write(_S62_CHILD)
    return child


def _s62_run(home, version=None, answer="no", actions=None, timeout=90, lang=None):
    """_S62_CHILD 跑一次：回傳 dict（rc、dialogs、start、acted、exit、native、tb、log）。lang＝介面語言（"en"：英文）。"""
    import json as _json
    import subprocess
    child = _s62_child_script()
    mp = os.path.join(home, "marks.txt")
    if os.path.exists(mp):
        os.remove(mp)
    lp = os.path.join(home, "signal_viewer.log")
    log0 = os.path.getsize(lp) if os.path.exists(lp) else 0
    env = _child_env(home, DSV_TEST_B3_ANSWER=answer)
    for k in ("DSV_TEST_ONLY", "DSV_LANG", "DSV_TEST_APP_VERSION", "DSV_TEST_ACTIONS", "DSV_TEST_OPENDOC", "DSV_TEST_DROP", "DSV_TEST_LANG"):
        env.pop(k, None)
    if version:
        env["DSV_TEST_APP_VERSION"] = version
    if lang:
        env["DSV_TEST_LANG"] = lang
    if actions:
        env["DSV_TEST_ACTIONS"] = _json.dumps(actions, ensure_ascii=False)
    with _S62_LANES:                                       # 最多同時 3 個子行程（s62 的幾段同時跑；每段裡照順序）
        p = subprocess.Popen([sys.executable, child, PROJECT, home], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        try:
            _o, err = p.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            p.kill()
            _o, err = p.communicate()
    err = (err or b"").decode("utf-8", "replace")
    marks = open(mp, encoding="utf-8").read() if os.path.exists(mp) else ""
    out = {"rc": p.returncode, "dialogs": [], "start": {}, "acted": {}, "exit": False, "native": [], "tb": err[-500:] if "Traceback" in err else ""}
    for ln in marks.splitlines():
        head, _sp, rest = ln.partition(" ")
        try:
            if head == "dialog":
                out["dialogs"].append(_json.loads(rest))
            elif head in ("start", "acted"):
                out[head] = _json.loads(rest)
        except ValueError:
            pass
        if head == "exit":
            out["exit"] = True
        elif head == "native":
            out["native"].append(rest)
    try:
        with open(lp, "rb") as f:
            f.seek(log0)
            out["log"] = f.read().decode("utf-8", "replace")
    except OSError:
        out["log"] = ""
    return out


def _s62_bk(home, ver=None):
    """home 裡 ver 那一版的備份路徑（0.9.14 起 .signal_viewer_last.backup-<版本>.json）；ver＝None：0.9.13 的 .signal_viewer_last.backup.json。
    測試自己算檔名（不靠程式的函式：16446fd 沒有它們，那時這些檢查要照實失敗）。"""
    return os.path.join(home, ".signal_viewer_last.backup.json" if ver is None else f".signal_viewer_last.backup-{ver}.json")


def _s62_bytes(path):
    """檔案的位元組；不在、讀不了回 None（16446fd 沒有每版各自的檔：檢查照實失敗、不丟例外）。"""
    try:
        with open(path, "rb") as f:
            return f.read()
    except OSError:
        return None


def _s62_files(home):
    """home 裡的版本備份：檔名 → 位元組（.signal_viewer_last.backup*.json）。"""
    out = {}
    for n_ in sorted(os.listdir(home)):
        if n_.startswith(".signal_viewer_last.backup") and n_.endswith(".json"):
            with open(os.path.join(home, n_), "rb") as f:
                out[n_] = f.read()
    return out


def _s62_keys(path):
    d = _s49_read(path)
    return [x.get("key") for x in d.get("signals") or []] if "_err" not in d else None


@step
def s62_0914_version_backups():
    """0.9.14（2026-10-29 18:1x 使用者決定）：每個版本各留一份自己的備份、留最近 3 個版本。16446fd（0.9.13）只有一份 .backup.json，
    照 C6 較舊的版本不改寫較新版本寫的 → 三個版本交替時中間那版沒有備份（R3-D2：中間那版加的訊號被更舊的版本丟掉後找不回來）。"""
    import json as _json
    base = os.path.join(OUT, "s62")
    shutil.rmtree(base, ignore_errors=True)
    data = os.path.join(base, "data")
    os.makedirs(data)
    a_csv, m_csv = os.path.join(data, "a.csv"), os.path.join(data, "m.csv")
    _s49_csv(a_csv)
    with open(m_csv, "w", encoding="utf-8") as f:
        f.write("m sig\n" + "\n".join(str(k % 7) for k in range(250)) + "\n")
    I = {"key": "a.csv;;b1 i", "path": a_csv, "column": "b1 i", "sps": 1.0, "panel": 1, "uid": 1}
    Q = {"key": "a.csv;;b1 q", "path": a_csv, "column": "b1 q", "sps": 1.0, "panel": 1, "uid": 2}
    M = {"key": "m.csv;;m sig", "path": m_csv, "column": "m sig", "sps": 1.0, "panel": 2, "uid": 3}

    def home(tag):
        h = os.path.join(base, tag)
        os.makedirs(os.path.join(h, "frozen"))
        return h

    def cfg(ver, sigs, saved="2026-10-29 18:00:00", prefs=False):
        d = {"version": 6, "root": "", "view": {"autosave": not prefs, "lang": "zh"}, "signals": [] if prefs else [dict(s_) for s_ in sigs],
             "saved": saved}
        if ver is not None:
            d["app_version"] = ver
        return d

    def put(path, d):
        with open(path, "w", encoding="utf-8") as f:
            _json.dump(d, f, ensure_ascii=False, indent=1)

    def auto(h):
        return os.path.join(h, ".signal_viewer_last.json")

    IQ, IQM = [I["key"], Q["key"]], [I["key"], Q["key"], M["key"]]
    t_b3, t_u13 = "上次的自動存檔被舊版改寫過", "上次的自動存檔讀不回來"

    def rows(r, which="start"):
        return [(k_, n_) for k_, n_, _m in (r.get(which) or {}).get("rows") or []]

    def ok_run(r):
        return r["rc"] == 0 and r["exit"] and not r["tb"] and not r["native"]

    parts = ((_s62_three, (home, cfg, put, auto, rows, ok_run, IQ, IQM, I, Q, M, m_csv, t_b3)),
             (_s62_last_work, (home, cfg, put, auto, rows, ok_run, IQ, IQM, I, Q, M, m_csv, t_b3, t_u13)),
             (_s62_four, (home, cfg, put, auto, rows, ok_run, IQ, I, Q, t_b3)),
             (_s62_legacy, (home, cfg, put, auto, rows, ok_run, IQ, IQM, I, Q, M, t_b3, t_u13)),
             (_s62_misc, (home, cfg, put, auto, rows, ok_run, IQ, IQM, I, Q, M, t_b3)),
             (_s62_english, (home, cfg, put, auto, rows, ok_run, I, Q, M)))
    _s62_child_script()
    got = {}

    def run_part(i, part, args):
        out = []
        try:                                               # 一段出錯（例如 16446fd 沒有那個檔）不擋別段：每段的檢查都照實記
            part(lambda ok, msg: out.append((bool(ok), msg)), *args)
        except Exception:
            out.append((False, f"s62 {part.__name__} 例外：{traceback.format_exc().strip().splitlines()[-1]}\n{traceback.format_exc()}"))
        got[i] = out
    # 各段（不同的暫存 HOME，彼此獨立）同時跑、子行程最多同時 3 個（_S62_LANES）：這一步從約 2 分鐘縮到 1 分鐘以內，整套不容易超過 30 分鐘
    threads = [_s62_threading.Thread(target=run_part, args=(i, part, args), daemon=True) for i, (part, args) in enumerate(parts)]
    for t in threads:
        t.start()
    t_end = time.time() + 900
    for t in threads:
        t.join(max(1.0, t_end - time.time()))
    for i, (part, _a) in enumerate(parts):
        if i not in got:
            check(False, f"s62 {part.__name__} 沒有在 15 分鐘內跑完")
            continue
        for ok, msg in got[i]:
            check(ok, msg)
    try:
        _s62_inproc()                                      # 行程內的部分（用到這個行程的 app）：回到主執行緒照順序跑
    except Exception:
        traceback.print_exc()
        check(False, f"s62 _s62_inproc 例外：{traceback.format_exc().strip().splitlines()[-1]}")


def _s62_three(chk, home, cfg, put, auto, rows, ok_run, IQ, IQM, I, Q, M, m_csv, t_b3):
    """(A) 三個版本交替（R3-D2）：新版 0.9.16 → 中間版 0.9.15 加一條（m.csv）→ 更舊的版本（0.9.12：不寫備份）改寫自動存檔、丟掉那條 → 回中間版：
    問、用它自己的備份把那條找回來；再回新版：問的是新版自己的備份，選「用現在的檔」→ 舊備份另存（R2-D2）、中間版那條照樣在。
    (A') 同樣的前三步之後直接回新版：問的是新版自己的，問句列出中間版留的那份（路徑、版本）、要用就「匯入設定」，關閉後它一個位元組都不動。"""
